import axios from 'axios';
import React, { useEffect, useImperativeHandle, useState } from 'react'
import { forwardRef } from 'react';
import { Table } from 'react-bootstrap'
import Hoot from '../../../General/components/Hoot';
import { GetSchoolNotes, GetSubject } from '../../../General/components/InstituteData';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import CalculateNote from '../../../General/components/CalculateNote';
import { Badge, Form } from 'react-bootstrap';
import { Check, Close, Delete, Edit, Refresh } from '@mui/icons-material';

const TABLEURL = [
  Hoot() + "eduallsingleclassapi/get/",
  Hoot() + "eduallgetstudentsemesternotesbyclassandsemester/get/",
  Hoot() + "eduallsubjectsapi/get/"
];


const StatusType1 = [
  <Badge className="col" bg={'success'}>Dispensado</Badge>,
  <Badge className="col" bg={'warning'}>Exame</Badge>,
];


const StatusType2 = [
  <Badge className="col" bg={'success'}>Apto</Badge>,
  <Badge className="col" bg={'warning'}>Recurso</Badge>,
];



const StatusType3 = [
  <Badge className="col" bg={'success'}>Aprovado</Badge>,
  <Badge className="col" bg={'danger'}>Reprovado</Badge>,
];


const GetColor = (e, max) => {
  return (e < (max / 2)) ?
    <span className='text-danger'>{e}</span>
    : <span className='text-success'>{e}</span>
}

const FinalScore = (md, exam, special) => {
  if (md > 13) return md;
  if (Math.floor(exam + md / 2) >= 10) return Math.floor(exam + md / 2);
  return special;
}



const PdStudentMarksCollegeTable = forwardRef((props, ref) => {
  const Class = props.ClassId ? props.ClassId : 0;
  const Semester = props.Semester ? props.Semester : 0;
  const StudentCode = props.StudentCode ? props.StudentCode : null;
  const [load, setLoaded] = useState(false);
  const [Marks, setMarks] = useState([]);
  let MaxValue = 20

  async function loadData() {
    setMarks([]);
    try {
      const [response2, response4, response3] = await Promise.all([
        axios.get(TABLEURL[0] + `${Class}`),
        axios.get(TABLEURL[2]),
        axios.get(TABLEURL[1] + `${StudentCode},${Semester},${Class}`),
      ]);

      let sb = response2.data.length > 0 ? response2.data[0].ed_class_subjects.split(',') : [];
      let Subjects = [];
      for (let i = 0; i < sb.length; i++) {
        Subjects.push(Math.floor(sb[i] * 1));
      }

      let AllSubjectsMarks = [];

      function add(el, ind) {
        const found = AllSubjectsMarks.some(el => el.index === ind); 
        if(!found) AllSubjectsMarks.push(el);
      }


      const RealSubjects = [];
      let ids = [];
      response4.data.map((item, index) => {
        for (let i = 0; i < Subjects.length; i++) {
          const element = Subjects[i];
          if ((element * 1) === (item.ed_subject_id * 1)) {
            if (!ids.includes((element * 1))) {
              ids.push((element * 1))
              RealSubjects.push(item);
            }
          }
        }
      });


      
 

      RealSubjects.map((sub, index) => {
        if (response3.data.length > 0) {
          for (let i = 0; i < response3.data.length; i++) {
            let item = response3.data[i]
            if ((sub.ed_subject_id * 1) === (item.ed_semester_note_subject * 1)) {

              let mark = {
                a: "ok",
                index: index,
                id: item.ed_semester_note_id,
                subject: item.ed_subject_title,

                p1: item.ed_semester_note_p1,
                p2: item.ed_semester_note_p2,
                exam: item.ed_semester_note_exam,
                specialexam: item.ed_semester_note_specialexam,

                md: CalculateNote(item.ed_semester_note_p1, item.ed_semester_note_p2, item.ed_semester_note_exam, item.ed_semester_note_specialexam, 0),
                result: CalculateNote(item.ed_semester_note_p1, item.ed_semester_note_p2,
                  item.ed_semester_note_exam, item.ed_semester_note_specialexam, 1) * 1 < 10 ? 1 : 0,

                fn: CalculateNote(item.ed_semester_note_p1, item.ed_semester_note_p2, item.ed_semester_note_exam,
                  item.ed_semester_note_specialexam, 2),

                status: CalculateNote(item.ed_semester_note_p1, item.ed_semester_note_p2,
                  item.ed_semester_note_exam, item.ed_semester_note_specialexam, 0) * 1 <= 13 ? 1 : 0,

                MaxValue: MaxValue,
              };
              add(mark, index);

            }
          }
        } else {
          let mark = {
            index: index,
            id: 0,
            subject: sub.ed_subject_title,
            p1: 0, p2: 0, exam: 0, specialexam: 0,
            md: 0, result: 1, fn: 0, status: 1,
            MaxValue: MaxValue,
          }
          add(mark, index);
        }
      });



      RealSubjects.map((sub, index) => {
        let mark = {
          a: "humm",
          index: index,
          id: sub.ed_subject_id,
          subject: sub.ed_subject_title,
          p1: 0, p2: 0, exam: 0, specialexam: 0,
          md: 0, result: 1, fn: 0, status: 1,
          MaxValue: MaxValue,
        }
        add(mark, index);
      });

      function compare( a, b ) {
        if(a.subject < b.subject){
          return -1;
        }
        if(a.subject > b.subject){
          return 1;
        }
        return 0;
      }
      
      AllSubjectsMarks.sort( compare );


      console.log("##################### FINAL RESULT ##################");
      console.log(AllSubjectsMarks);
      console.log("*******************************************************")
      console.log(response3.data);
      console.log("#######################################################");

      setMarks(AllSubjectsMarks);
    } catch (error) {
      console.clear();
      console.log(error)
    }
  };

  useEffect(() => {
    loadData();
  }, [Semester, Class]);

  useImperativeHandle(ref, () => ({
    RunGetNotes() {
      console.log("printing the class code : " + Class);
      loadData();
    }
  }))


  return (
    <div className='col'> 
      <Table striped={props.nostriped ? false : true} responsive bordered>
        <thead>
          <tr>
            <th style={{ minWidth: '100px' }}>Cadeira</th>
            <th style={{ minWidth: '50px' }}>P1</th>
            <th style={{ minWidth: '50px' }}>P2</th>
            <th style={{ minWidth: '60px' }}>Media</th>
            <th>Situação</th>
            <th style={{ minWidth: '50px' }}>Exame</th>
            <th>Resultado</th>
            <th style={{ minWidth: '70px' }}>Recurso</th>
            <th style={{ minWidth: '80px' }}>Nota final</th>
            <th style={{ minWidth: '70px' }}>Estado</th>
          </tr>
        </thead>
        <tbody>
          {Marks.map((item, index) => (
            <tr key={index + 1}>
              <td>{item.subject}</td>
              <td>{GetColor(item.p1 * 1, item.MaxValue)}</td>
              <td>{GetColor(item.p2 * 1, item.MaxValue)}</td>
              <td>{GetColor(item.md * 1, item.MaxValue)}</td>
              <td><div className='ed-flex'> {StatusType1[item.status]} </div></td>
              <td>{GetColor(item.exam * 1, item.MaxValue, null)}</td>
              <td><div className='ed-flex'> {FinalScore(item.md, item.exam, item.specialexam) < 10 ? StatusType2[item.result] : StatusType2[0]}</div></td>
              <td>{item.result < 10 ? GetColor(item.specialexam * 1, item.MaxValue, null) : <></>}</td>
              <td>{GetColor(FinalScore(item.md, item.exam, item.specialexam), item.MaxValue, null)}</td>
              <td>
                {(FinalScore(item.md, item.exam, item.specialexam) >= 10 ?
                  <div className='ed-flex'>{StatusType3[0]}</div> :
                  <div className='ed-flex'>{StatusType3[1]}</div>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </Table>
      <br />
    </div>
  )
})


export default PdStudentMarksCollegeTable