const Hoot = (() => {

  const PRIMARY = "https://sv.eduall.pt/";
  const FALLBACK = "https://backofficeedsv.eduall.ao/";
  const LOCAL = "https://sv.eduall.pt/" ||  "http://localhost:5000/";

  let activeHost = null;

  // --- Inicialização imediata ---
  (function init() {
    if (typeof window === "undefined") {
      activeHost = PRIMARY;
      return;
    }

    const { hostname, protocol } = window.location;

    const isLocal =
      (hostname === "localhost" || hostname.endsWith(".localhost")) &&
      protocol === "http:";

    if (isLocal) {
      activeHost = LOCAL;
      return;
    }

    // Recupera host anterior se existir
    const saved = localStorage.getItem("activeHost");
    activeHost = saved || PRIMARY;

    // Teste ultra rápido em background
    const runTest = () => {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), 450);

      fetch(PRIMARY + "edualltxtdata/get", {
        method: "GET",
        signal: controller.signal,
      })
        .then(res => {
          clearTimeout(timer);
          if (res.ok) {
            activeHost = PRIMARY;
            localStorage.setItem("activeHost", PRIMARY);
          } else {
            activeHost = FALLBACK;
            localStorage.setItem("activeHost", FALLBACK);
          }
        })
        .catch(() => {
          clearTimeout(timer);
          activeHost = FALLBACK;
          localStorage.setItem("activeHost", FALLBACK);
        });
    };

    if ("requestIdleCallback" in window) {
      requestIdleCallback(runTest, { timeout: 500 });
    } else {
      setTimeout(runTest, 0);
    }
  })();

  // --- Função síncrona usada pela app ---
  return function () {
    return activeHost || PRIMARY;
  };

})();

export default Hoot;
