import React, {useEffect, useState} from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import {Modal, Form, Button} from 'react-bootstrap'
import { Save } from '@mui/icons-material';
import { Update } from '@material-ui/icons';
import { Link } from 'react-router-dom';
import DraggableModal from '../../../General/components/DraggableModal';
import {toast} from 'react-hot-toast';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import { GetInstituteCode, VehiclesDataOptions } from '../../../General/components/InstituteData';
import RefreshList from '../../../General/components/RefreshList';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import ReplaceWord from '../../../General/components/ReplaceWord';


 
function NewTransportRouteModal(props) {
    const [show, setShow] = useState(false);
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [Founded, SetFounded] = useState(null);

     
    const [showBox, SetshowBox]  = useState(false);
    const handleClose = () => {
      SetshowBox(false);
      setTimeout(() => {
        setShow(false);
      }, 1200);
    } 

    const handleShow = () => {
          SetshowBox(true);
          setShow(true);  
          setTimeout(() => {  
            GET_DATA(); 
         }, 1000);   
    };

    const [form, setForm] = useState({});
    const [errors, setErrors] = useState({});
     
    const INPUTS = {
         route_name:CRValue("#route_name"), 
         route_description:CRValue("#route_description"), 
         route_vehicle:CRValue("#route_vehicle"),  
    }; 
    
    
  const FORMURL = [
    Hoot()+"edualltransportrouteregister/post",
    props.get ? props.get : '',
    props.url ? props.url : ''
  ];
      
  const GET_DATA = async()=>{
   if(props.update){
      try {
        const response = await axios.get(FORMURL[1]); 
        if(response.data.length > 0){
          if(response.data[0] !==null){
            document.querySelector("#route_name").value = response.data[0].ed_transport_route_name; 
            document.querySelector("#route_description").value  = response.data[0].ed_transport_route_description; 
            document.querySelector("#route_vehicle").value  = response.data[0].ed_transport_route_vehicle; 
      
            INPUTS.route_name = response.data[0].ed_transport_route_name;
            INPUTS.route_description = response.data[0].ed_transport_route_description;
            INPUTS.route_vehicle = response.data[0].ed_transport_route_vehicle;
          }
        }else {
          toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
        }
      } catch (error) {
          toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
      }
   }
}

    const setField = (field, value)  =>{
       setForm({...form, [field]:value});
  
      if(!!errors[field]){
          setErrors({...errors, [field]:null});  
      }
  }


    const validateForm = ()=>{
      const {route_name,  route_vehicle} = form; 
      const NewErrors = {};
      setRegisterStatus(0);  
      if(INPUTS.route_name ===  "" || INPUTS.route_name ===  " "){
      if(!route_name || route_name === '') NewErrors.route_name =  'O nome da rota é invalido !';  
      }else{if(!route_name){setField("route_name", INPUTS.route_name );}} 
 
      if(INPUTS.route_vehicle ===  "" || INPUTS.route_vehicle ===  " "){
      if(!route_vehicle || route_vehicle === '') NewErrors.route_vehicle = 'Selecione um veiculo valido  invalida !'; 
      }else{if(!route_vehicle){setField("route_vehicle", INPUTS.route_vehicle);}} 
 
      return NewErrors;
  }
  
 
  
    const FormSubmit = (e)=>{  
       e.preventDefault();   
       const formErrors = validateForm();
      if(Object.keys(formErrors).length > 0){
            setErrors(formErrors);
            toast.error("Verifique todos os  campos !");   
            setRegisterStatus(1);   
        }else{  
            const SUBMIT_INPUTS = {route_name:INPUTS.route_name,  route_vehicle:INPUTS.route_vehicle, 
            route_description:INPUTS.route_description};
          if(!props.update){
            try {
              axios.post(FORMURL[0], SUBMIT_INPUTS).then(()=>{  
                toast.success("Rota registrada com sucesso !");
                setForm({});
                ClearInputs();
                setRegisterStatus(2);  
                RefreshList(`.el-refresh-list`)
              }).catch((error)=>{
                setRegisterStatus(1);
                console.clear()
                console.log(error.response);  
                toast.error("Lamentamos mas não foi  possivel executar esta ação !");
              }); 
            } catch (error) {
              setRegisterStatus(1);
                console.clear()
                console.log(error.response);  
                toast.error("Lamentamos mas não foi  possivel executar esta ação !");
            }
          } else {
            try {
              axios.put(FORMURL[2] , SUBMIT_INPUTS).then(()=>{  
                toast.success("Rota atualizada com sucesso !");
                setForm({});
                ClearInputs();
                RefreshList(`.el-refresh-list`)
                setRegisterStatus(2);  
                setTimeout(() => { 
                    handleClose();
                }, 500);
              }).catch((error)=>{
                setRegisterStatus(1);
                console.clear()
                console.log(error.response);  
                toast.error("Lamentamos mas não foi  possivel executar esta ação !");
              }); 
            } catch (error) {
              setRegisterStatus(1);
                console.clear()
                console.log(error.response);  
                toast.error("Lamentamos mas não foi  possivel executar esta ação !");
            }
            
          } 
        }  
    };
  
      
    const handleInput = (e)=>{  
       switch (e.target.id) { 
          case "route_name":
            setField("route_name", e.target.value) 
            INPUTS.route_name = e.target.value
           break; 
           case "route_description":
            setField("route_description", e.target.value) 
            INPUTS.route_description = e.target.value;
           break;  
           case "route_vehicle":
            setField("route_vehicle", e.target.value) 
            INPUTS.route_vehicle = e.target.value;
           break;  
           default:
       }
    }


  return (
    <div>
       <div onClick={handleShow}>
            {props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon/> Registrar nova rota </button>}
         </div>
      <Modal size='lg' className={showBox ? ModalAnimationShow() : ModalAnimationClose()}  centered  dialogAs={DraggableModal}  show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>{ props.title ? props.title : 'Registrar ' }  rota de transporte</h5>
          </div>  
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={FormSubmit}>
        <Modal.Body className='scrollLimit'>
            <Form.Group className="mb-3"  >
              <Form.Label>Nome da rota <span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Control  required onChange={handleInput} className={!!errors.route_name && 'is-invalid'} value={form.route_name} isInvalid={!!errors.route_name}
              type="text" id="route_name" autoFocus/>
              <Form.Control.Feedback type='invalid'>{errors.route_name}</Form.Control.Feedback>
            </Form.Group>  
            <Form.Group className="mb-3">
              <Form.Label>Veiculo  <span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Select required onChange={handleInput} id='route_vehicle' className={!!errors.route_vehicle && 'is-invalid'}
               value={form.route_vehicle} isInvalid={!!errors.route_vehicle}>
                  <VehiclesDataOptions />
              </Form.Select>
              <Form.Control.Feedback type='invalid'>{errors.route_vehicle}</Form.Control.Feedback>
            </Form.Group>   
            <Form.Group className="mb-3 mt-3"  >
              <Form.Label>Descrição</Form.Label>
              <Form.Control as={"textarea"} onChange={handleInput} className={!!errors.route_description && 'is-invalid'} value={form.route_description} 
              isInvalid={!!errors.route_description}  id="route_description"/> 
              <Form.Control.Feedback type='invalid'>{errors.route_description}</Form.Control.Feedback>
            </Form.Group>  
        </Modal.Body>
        <Modal.Footer>
          <div className="ed-space">
             <div className="ed-flex"></div>
             <div className="ed-flex">
             <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button> 
            {props.update ? (Founded === false ? <div></div>  : 
            <SaveButton icon={props.title ? <Update/> : <Save/>} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
            <SaveButton icon={props.title ? <Update/> : <Save/>} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />} 
             </div>
          </div>
        </Modal.Footer>
        </Form>
      </Modal>
    </div>
  )
}

export default NewTransportRouteModal;
