import React from 'react'
import { Table } from 'react-bootstrap';
import {
    GetAcademicYear_byclass, GetAcademiclevel_byclass, GetCicle_byclass, GetFaculty_byclass,
    GetClassroom_byclass, GetClasstitle_byclass, GetCourse_byclass, GetPeriod_byclass
} from '../../../../General/components/InstituteData';
import ReplaceWord from '../../../../General/components/ReplaceWord';

function STD_institute(props) {
    const StudentInfo = props.data.student;


    function fSafeValue(value, fallback = "---") {
        if (value === null || value === undefined || String(value).trim() === "") {
            return fallback;
        }
        return value;
    }

    return (
        <div>
            <Table bordered >
                <tbody>
                    <tr>
                        <td>
                            <div className="ed-space">
                                <div>Turma</div>
                                <div><span>{fSafeValue(StudentInfo.ed_class_title)}</span></div>
                            </div>
                        </td>
                        <td>
                            <div className="ed-space">
                                <div>Ano letivo</div>
                                <div><span>{fSafeValue(StudentInfo.ed_academic_year_title)}</span></div>
                            </div>
                        </td>
                    </tr>

                    <tr>
                        <td>
                            <div className="ed-space">
                                <div>Sala</div>
                                <div><span>{fSafeValue(StudentInfo.ed_classroom_title)}</span></div>
                            </div>
                        </td>
                        <td>
                            <div className="ed-space">
                                <div>Periodo</div>
                                <div><span>{<GetPeriod_byclass ID={StudentInfo.ed_student_class} />}</span></div>
                            </div>
                        </td>
                    </tr>

                    <tr>
                        <td>
                            <div className="ed-space">
                                <div>Curso</div>
                                <div><span>{fSafeValue(StudentInfo.ed_course_title)}</span></div>
                            </div>
                        </td>
                        <td>
                            <div className="ed-space">
                                <div>{ReplaceWord("Classe")}</div>
                                <div><span>{fSafeValue(StudentInfo.ed_academic_level_title)}</span></div>
                            </div>
                        </td>
                    </tr>

                    <tr>
                        <td>
                            <div className="ed-space">
                                <div>{StudentInfo.ed_student_type * 1 === 1 ? "Faculdade" : "Ciclo"}</div>
                                <div>
                                    {StudentInfo.ed_student_type * 1 === 1
                                        ? <span>{fSafeValue(StudentInfo.ed_faculty_title)}</span>
                                        : <span>{fSafeValue(StudentInfo.ed_cicle_title)}</span>}
                                </div>
                            </div>
                        </td>
                        <td>
                            <div className="ed-space">
                                <div>Status</div>
                                <div>
                                    <span>{Math.floor(StudentInfo.ed_student_status) === 1 ? "Activo" : "Inactivo"}</span>
                                </div>
                            </div>
                        </td>
                    </tr>
                </tbody>

            </Table>
        </div>
    )
}

export default STD_institute