import React, { useEffect, useState } from 'react'
import Table from './Table';
import axios from 'axios';
import { Delete, Edit, Refresh } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import NewCourseModal from '../modal/NewCourseModal';
import TableGrid from '../../../General/components/TableGrid';
import NewExamModal from '../modal/Pedagogy/NewExamModal';
import { GetTime } from '../../../General/components/InstituteData';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import ReplaceWord from '../../../General/components/ReplaceWord';
import moment from "moment";
import "moment/locale/pt";
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
moment.locale("pt")

const TABLEURL = Hoot() + "eduallstudentexamcalendarget/get/";
let Categories = ["", "Designer", "Arte", "Engenharia", "Saude", "Ciências"];

const columns = [
  {
    field: 'index', 
    headerName: 'Nº',
    resizable: true,
    width: 70,
  },
  {
    field: 'subject',
    headerName: ReplaceWord("Disciplina"),
    resizable: true,
    width: 200,
  },
  {
    field: 'class',
    headerName: 'Turma',
    resizable: true,
    width: 120,
  },
  {
    field: 'date',
    headerName: 'Data & Hora',
    resizable: true,
    width: 520,
  },
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true,
    cellRenderer: (props) => {
      return <div className="ed-flex">
        <NewExamModal title='Atualizar ' update='true' get={Hoot() + `eduallstudentexamcalendargetsingle/get/${props.data.id}`}
          url={Hoot() + `eduallstudentexamcalendarupdate/update/${props.data.id}`} toggle_btn={
            <button className="btn-circle bg-success text-light">
              <Edit />
            </button>} />
        <DeleteModal title='este evento' url={Hoot() + `eduallstudentexamcalendardelete/delete/${props.data.id}`} message='Evento deletado com sucesso' toggle_btn={
          <button className="btn-circle bg-danger ml-2 text-light">
            <Delete />
          </button>} />
      </div>;
    }
  }
];


function PdExams_table() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData() {
    setLoaded(false);
    setLoadStatus(0);
    try {
      const response = await axios.get(TABLEURL);
      const rows = [];
      response.data.map((item, index) => {

        let hs = item.ed_timing_hour_start;
        let he = item.ed_timing_hour_end;
        let ms = item.ed_timing_minute_start;
        let me = item.ed_timing_minute_end;
        let time = hs + 'H' + ' : ' + ms + ' MN' + ' | ' + he + ' H' + ' : ' + me + ' MN'

        rows.push({
          index: index + 1,
          id: item.ed_student_exam_id,
          subject: item.ed_subject_title,
          class: item.ed_class_title,
          date: moment(item.ed_student_exam_date).format("dddd, D [de] MMMM [de] YYYY [pelas] ") + " "+time,
          action: '',
        })
      });
      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 100);
      setLoadStatus(2);
    } catch (error) {
      setLoadStatus(1);
    }
  }

  useEffect(() => {
    loadData();
  }, []);




  if (load) {
    return (
      <div id="ed-custom-table-data" >
        <TableGrid
          TableHead={columns} 
          TableBody={data}
          TableTitle='Calendário de provas'
          TableBtn={
            <div className='ed-flex' > 
            <button id='ed-custom-table-data-btn'
              onClick={() =>
                ExportDataToTablesToPdf({
                  fileName: "Calendário de provas",
                  headerId: null,
                  contentId: "ed-custom-table-data",
                  footerId: null,
                  rotation: "portrait",
                  buttonId: "ed-custom-table-data-btn",
                  customHeader: "Calendário de provas",
                  excludedColumns: ["Ação"]
                })
              }
              className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
            </button> 
            <button className='btn-icon btn btn-export-data ml-2' 
               onClick={()=>ExportDataForTablesExcel("turmas ", ["Ação"], "ed-custom-table-data")}><PiMicrosoftExcelLogoDuotone />
            </button>
           <RefreshButton action={loadData} status={LoadStatus} />
       </div>
          }
        />
      </div>
    )
  } else {
    return (
      <div>
        <><div className="d-none">*</div>
          <TableGrid
            TableHead={columns}
            TableBody={[]}
            TableTitle='Calendário de provas'
            TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
          />
        </>
      </div>
    )
  }
}

export default PdExams_table;