 
import React, { useEffect, useRef, useState } from "react";
import axios from "axios";
import { PiFilePdf } from "react-icons/pi";
import toast, { Toaster } from "react-hot-toast";
import { PDFDocument } from "pdf-lib";
import Hoot from "./Hoot";
import CryptoJS from "crypto-js";

const API_KEY = "f7195fc6fb249aa163e95fcd97d2f7b1"; // default api nao institucional

/**
 * DownloadInvoicePDFButton
 *
 * Props:
 * - documentId: string | number (obrigatório)
 * - toggle_btn?: boolean
 *
 * Comportamento:
 * - !toggle_btn  → Dropdown roxo com: Baixar original | Baixar duplicado (2-up)
 * -  toggle_btn  → Um único botão (com loader) que baixa a fatura Duplicada (2-up)
 */
const DownloadInvoicePDFButton = ({ documentId, toggle_btn }) => {
  // Dropdown (modo sem toggle_btn)
  const [open, setOpen] = useState(false);
  const [busyOrg, setBusyOrg] = useState(false);
  const [busyDup, setBusyDup] = useState(false);
  const [pOrg, setPOrg] = useState(0);
  const [pDup, setPDup] = useState(0);
  const dropdownRef = useRef(null);

  // Botão único (modo com toggle_btn)
  const [loadingSingle, setLoadingSingle] = useState(false);

  useEffect(() => {
    const onDocClick = (e) => {
      if (!dropdownRef.current) return;
      if (!dropdownRef.current.contains(e.target)) setOpen(false);
    };
    document.addEventListener("click", onDocClick);
    return () => document.removeEventListener("click", onDocClick);
  }, []);

  // -------------------- Utils --------------------
  function barColor(pct, state) {
    if (state === "error") return "#dc3545";      // vermelho
    if (state === "success") return "#198754";    // verde
    if (pct >= 50 && pct < 100) return "#fd7e14"; // laranja
    return "#6c757d";                              // cinza
  }

  function downloadBlob(blob, filename) {
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
  }

  function buildFilename(kind) {
    const dias = [
      "domingo",
      "segunda feira",
      "terça feira",
      "quarta feira",
      "quinta feira",
      "sexta feira",
      "sábado",
    ];
    const now = new Date();
    const tz = "Europe/Lisbon";
    const dowIdx = new Date(now.toLocaleString("en-US", { timeZone: tz })).getDay();
    const fmt = new Intl.DateTimeFormat("pt-PT", {
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
      timeZone: tz,
    });
    const parts = Object.fromEntries(fmt.formatToParts(now).map((p) => [p.type, p.value]));
    const hhmm = `${parts.hour}:${parts.minute}mn`;
    const prefix = kind === "original" ? "Fatura_simples" : "Fatura_duplicada";
    return `${prefix} ${dias[dowIdx]} ${hhmm} .pdf`;
  }








 
 
  async function fetchInvoiceBlob(kind, onProgress) {
  if (!documentId) throw new Error("Sem fatura selecionada.");

  const url = `${Hoot()}eduallinvoicedoc/${documentId}/pdf`;
  onProgress?.(10);

  let apiKeyToUse = API_KEY; // chave padrão (fallback)
  let triedDefault = false;

  try {
    const instRes = await axios.get(Hoot() + "eduallgetcurentuserinstitute/get/");
    const institute = instRes.data?.[0];

    if (institute?.ed_institute_vendus_key) {
      try {
        const bytes = CryptoJS.AES.decrypt(
          institute.ed_institute_vendus_key,
          institute.ed_institute_code
        );
        const decrypted = bytes.toString(CryptoJS.enc.Utf8);

        if (decrypted && decrypted.length >= 6) {
          apiKeyToUse = decrypted;
        } else {
          console.warn("⚠️ Chave descriptografada inválida, usando API_KEY padrão");
          triedDefault = true;
        }
      } catch (err) {
        console.warn("⚠️ Erro ao descriptografar chave, usando API_KEY padrão", err);
        triedDefault = true;
      }
    }
  } catch (err) {
    console.warn("⚠️ Erro ao buscar dados da escola, usando API_KEY padrão", err);
    triedDefault = true;
  }

  try {
    // 🔹 Primeira tentativa com a chave da instituição
    const response = await axios.get(url, {
      responseType: "blob",
      headers: { Authorization: `Bearer ${apiKeyToUse}` },
      onDownloadProgress: (evt) => {
        if (!onProgress) return;
        if (evt.total) {
          const pct = Math.min(40, Math.floor((evt.loaded / evt.total) * 40));
          onProgress(pct);
        } else {
          onProgress((prev) =>
            typeof prev === "number" ? Math.min(30, prev + 2) : 20
          );
        }
      },
    });

    onProgress?.(45);
    return new Blob([response.data], { type: "application/pdf" });
  } catch (err) {
    // 🔹 Fallback automático: tenta novamente com API_KEY padrão
    if (!triedDefault) {
      console.warn("⚠️ Falha com chave institucional, tentando fallback com API default...");
      try {
        const fallbackResponse = await axios.get(url, {
          responseType: "blob",
          headers: { Authorization: `Bearer ${API_KEY}` },
          onDownloadProgress: (evt) => {
            if (!onProgress) return;
            if (evt.total) {
              const pct = Math.min(40, Math.floor((evt.loaded / evt.total) * 40));
              onProgress(pct);
            } else {
              onProgress((prev) =>
                typeof prev === "number" ? Math.min(30, prev + 2) : 20
              );
            }
          },
        });

        onProgress?.(45);
        return new Blob([fallbackResponse.data], { type: "application/pdf" });
      } catch (fallbackErr) {
        console.error("❌ Falha também com API default:", fallbackErr.message);
        throw fallbackErr;
      }
    } else {
      throw err;
    }
  }
}











  async function makeTwoUpA4Landscape(srcBlob, onProgress) {
    onProgress?.(50);
    const arrayBuffer = await srcBlob.arrayBuffer();
    const srcDoc = await PDFDocument.load(arrayBuffer);
    const outDoc = await PDFDocument.create();

    const A4 = { width: 841.89, height: 595.28 }; // landscape
    const total = srcDoc.getPageCount();

    for (let i = 0; i < total; i++) {
      const srcPage = srcDoc.getPage(i);
      const { width: sw, height: sh } = srcPage.getSize();
      const page = outDoc.addPage([A4.width, A4.height]);
      const embedded = await outDoc.embedPage(srcPage);

      const halfW = A4.width / 2;
      const scale = Math.min(halfW / sw, A4.height / sh);
      const dw = sw * scale;
      const dh = sh * scale;
      const y = (A4.height - dh) / 2;

      page.drawPage(embedded, { x: (halfW - dw) / 2, y, width: dw, height: dh });
      page.drawPage(embedded, { x: halfW + (halfW - dw) / 2, y, width: dw, height: dh });

      const pct = 50 + Math.round(((i + 1) / total) * 40); // 50→90
      onProgress?.(pct);
      // eslint-disable-next-line no-await-in-loop
      await new Promise((r) => setTimeout(r, 6));
    }

    onProgress?.(95);
    const bytes = await outDoc.save();
    onProgress?.(100);
    return new Blob([bytes], { type: "application/pdf" });
  }

  // -------------------- Handlers (modo dropdown) --------------------
  const handleDownloadOriginal = async () => {
    setBusyOrg(true);
    setPOrg(20);
    try {
      const blob = await fetchInvoiceBlob("original", setPOrg);
      const name = buildFilename("original");
      downloadBlob(blob, name);
      setPOrg(100);
      toast.success("O ficheiro está a ser descarregado !");
    } catch (e) {
      console.error(e);
      setPOrg(100);
      toast.error("Não foi possível obter a fatura !");
    } finally {
      setBusyOrg(false);
    }
  };

  const handleDownloadDuplicate = async () => {
    setBusyDup(true);
    setPDup(20);
    try {
      const original = await fetchInvoiceBlob("duplicado", setPDup);
      const duplicated = await makeTwoUpA4Landscape(original, setPDup);
      const name = buildFilename("duplicado");
      downloadBlob(duplicated, name);
      setPDup(100);
      toast.success("A versão duplicada está a ser descarregada !");
    } catch (e) {
      console.error(e);
      setPDup(100);
      toast.error("Não foi possível criar a versão duplicada !");
    } finally {
      setBusyDup(false);
    }
  };

  // -------------------- Handler (modo botão único) --------------------
  const handleSingleDuplicate = async () => {
    setLoadingSingle(true);
    try {
      const original = await fetchInvoiceBlob("duplicado");
      const duplicated = await makeTwoUpA4Landscape(original);
      const name = buildFilename("duplicado");
      downloadBlob(duplicated, name);
      toast.success("A versão duplicada está a ser descarregada !");
    } catch (e) {
      console.error(e);
      toast.error("Não foi possível criar a versão duplicada !");
    } finally {
      setLoadingSingle(false);
    }
  };

  // -------------------- Render --------------------
  if (!toggle_btn) {
    // Modo: um único botão (duplicado com loader)
    return (
      <div> 
        <button
          onClick={handleSingleDuplicate}
          disabled={loadingSingle}
          className="btn bg-main btn-bordered pt-0 pb-1 text-main ed-flex ed-center"
          title={`Baixar Fatura (duplicada) = ${documentId}`}
        >
          {loadingSingle ? (
            <div className="ed-flex ed-center">
              <div className="spinner-border text-main spinner-border-sm text-light" role="status" /> 
            </div>
          ) : (
            <div className="ed-flex text-main ed-center">
              <PiFilePdf color="" />  
            </div>
          )}
        </button>
      </div>
    );
  }

  // Modo: dropdown com as duas opções
  return (
    <div style={{ display: "inline-block", position: "relative" }} ref={dropdownRef}> 

      <button
        onClick={() => setOpen((v) => !v)}
        className="btn"
        style={{
          background: "var(--ed-purple)",
          color: "#fff",
          border: "none",
          borderRadius: 8,
          padding: "10px 14px",
          fontWeight: 600,
          display: "inline-flex",
          alignItems: "center",
          gap: 8,
        }}
        title={`Baixar fatura #${documentId}`}
      >
        <PiFilePdf size={18} /> Baixar fatura ▾
      </button>

      {open && (
        <div
          style={{
            position: "absolute",
            top: "110%",
            right: 0,
            background: "#111827",
            border: "1px solid #1f2937",
            borderRadius: 12,
            minWidth: 320,
            boxShadow: "0 12px 32px rgba(0,0,0,.45)",
            zIndex: 20,
            color: "#e5e7eb",
          }}
        >
          {/* Baixar original */}
          <div
            onClick={handleDownloadOriginal}
            style={{
              padding: "10px 14px",
              display: "flex",
              alignItems: "center",
              gap: 8,
              cursor: "pointer",
            }}
          >
            <span>Baixar original</span>
            {busyOrg && (
              <span
                style={{
                  marginLeft: "auto",
                  width: 16,
                  height: 16,
                  border: "2px solid #9ca3af",
                  borderTopColor: "transparent",
                  borderRadius: "50%",
                  display: "inline-block",
                  animation: "spin .8s linear infinite",
                }}
              />
            )}
          </div>
          {(busyOrg || pOrg > 0) && (
            <div style={{ padding: "6px 14px 10px" }}>
              <div
                style={{
                  width: "100%",
                  height: 8,
                  background: "#243041",
                  borderRadius: 999,
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    width: `${pOrg}%`,
                    height: "100%",
                    background: barColor(pOrg, pOrg === 100 && !busyOrg ? undefined : undefined),
                    transition: "width .15s linear",
                  }}
                />
              </div>
            </div>
          )}

          <div style={{ height: 1, background: "#1f2937", margin: "6px 0" }} />

          {/* Baixar duplicado */}
          <div
            onClick={handleDownloadDuplicate}
            style={{
              padding: "10px 14px",
              display: "flex",
              alignItems: "center",
              gap: 8,
              cursor: "pointer",
            }}
          >
            <span>Baixar duplicado (Horizontal)</span>
            {busyDup && (
              <span
                style={{
                  marginLeft: "auto",
                  width: 16,
                  height: 16,
                  border: "2px solid #9ca3af",
                  borderTopColor: "transparent",
                  borderRadius: "50%",
                  display: "inline-block",
                  animation: "spin .8s linear infinite",
                }}
              />
            )}
          </div>
          {(busyDup || pDup > 0) && (
            <div style={{ padding: "6px 14px 12px" }}>
              <div
                style={{
                  width: "100%",
                  height: 8,
                  background: "#243041",
                  borderRadius: 999,
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    width: `${pDup}%`,
                    height: "100%",
                    background: barColor(pDup, pDup === 100 && !busyDup ? undefined : undefined),
                    transition: "width .15s linear",
                  }}
                />
              </div>
            </div>
          )}
        </div>
      )}

      <style>{`
        @keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
      `}</style>
    </div>
  );
};

export default DownloadInvoicePDFButton;
