import React, {useState, useEffect} from 'react'
import  {  PrintOutlined } from '@mui/icons-material';
import { Link } from 'react-router-dom';
import { Avatar } from '@mui/material';
import axios from 'axios';
import {  Edit} from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot'; 
 import { GetAcademiclevel_byclass, GetClassroom_byclass, GetClasstitle_byclass, GetCourse_byclass, GetPeriod_byclass,   GetStudentParentsAvatars } from '../../../General/components/InstituteData';
import RandomColor from '../../../General/components/RandomColor';
import NewEnrollmentConfirmationModal from '../modal/NewEnrollmentConfirmationModal'; 
import { styled } from 'styled-components';
import ReactPaginate from 'react-paginate';
import moment from "moment" 
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import ReplaceWord from '../../../General/components/ReplaceWord'; 
import RefreshButton from '../../../General/components/RefreshButton';

const URL = Hoot()+"eduallenrollmentconfirmations/get";

 

function EnrollmentConfirmationGrid(props) { 
  const [data, setData] = useState([]); 
  const [StartDate, setStartDate] = useState(null);
  const [EndDate, setEndDate] = useState(null);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData(){
    try {
        const response = await axios.get(URL);
        setLoadStatus(0); 
         const Students = [];
          response.data.map((item, index)=>{  
              Students.push({
                student_id:item.ed_student_id,
                student_code:item.ed_student_code,
                student_name:item.ed_student_name,
                student_picture:item.ed_student_picture,
                student_enrollment_date:item.ed_enrollment_confirmation_registerdate,
                student_class:item.ed_enrollment_confirmation_class,
                student_linkedin:item.ed_student_linkedin,
                student_email:item.ed_student_email,
                student_phone:item.ed_student_phone, 
                enrollment_id:item.ed_enrollment_confirmation_id,
                student_facebook:item.ed_student_facebook,
                date:item.ed_enrollment_confirmation_date,
              }
          ) 
         });
        setData(Students); 
        setLoadStatus(2); 
    } catch (error) {
      setLoadStatus(1); 
    } 
  }

  useEffect(()=>{
      loadData(); 
  },[]);
  
 
  useEffect(()=>{
    setStartDate(props.startDate);
    setEndDate(props.endDate);
 },[props]);


  return (
      <div className="block"> 
        <div className="ed-space">
              <div></div>
              <div className='ed-flex' > 
                 <NewEnrollmentConfirmationModal multiple={true} confirmation  />
                 <div className="ml-2">
                    <RefreshButton action={loadData} status={LoadStatus} />
                 </div>
              </div> 
          </div>
        <div className="ed-edusers-cards">
           <PaginatedItems itemsPerPage={9} filterValue  data={data} /> 
      </div>
      <div className="ed-space">
            <div className="count"></div>
           <div className="pagination"></div>
      </div>
      <br />
      </div> 
  )
}

 
function Items({currentItems}){
  return( 
    <div className="ed-edusers-cards small-grids">  
     {currentItems &&
      currentItems.map((item)=>(
        <div className="pd-1">
        <article className="ed-eduser-box rm-cover">   
          <div className="ed-edusers-details">
              <div className="ed-flex">
                    <SwitchFromPages link={`studentinfo/${item.student_id}`}   menu='3'  menu_item='17'  toggle_btn={  
                        <Avatar  className='avatar-img df' sx={{ width:80, height:80 }}  src={item.student_picture !==""  ?  Hoot()+item.student_picture : ""}  />
                     } /> 
                      <div className="block">
                       <SwitchFromPages link={`studentinfo/${item.student_id}`}   menu='3'  menu_item='17'  toggle_btn={  
                        <Link to={`#`}><h5>{item.student_name}</h5></Link>
                        } /> 
                      <Link to={`#`}>
                        <span>
                          <div className="d-flex">Número de matrícula: <div className="ml-2 text-main"> 
                          <SwitchFromPages link={`studentinfo/${item.student_id}`}   menu='3'  menu_item='17'  toggle_btn={  
                                <>{item.student_code}</>
                            } /> 
                            </div>
                          </div>
                        </span>
                      </Link>
                  </div>
              </div>
              <ul>
                  <li>Sala : <GetClassroom_byclass ID={item.student_class} /></li>
                  <li>Turma : <GetClasstitle_byclass ID={item.student_class} /></li>
                  <li>{ReplaceWord("Classe")} : <GetAcademiclevel_byclass ID={item.student_class} /> </li>
                  <li>Periodo: <GetPeriod_byclass ID={item.student_class} /></li>
                  <li>Curso : <GetCourse_byclass ID={item.student_class} /> </li>
              </ul>
              <div className="action-buttons">
              <div className="ed-flex">
              <NewEnrollmentConfirmationModal  confirmation title='Atualizar ' update='true' get={Hoot()+`eduallgetsingleenrollmentconfirmation/get/${item.enrollment_id}`}  
                  url={Hoot()+`eduallstudentenrollmentconfirmationupdate/update/${item.enrollment_id}`} studentCode={item.student_id}  toggle_btn={
                    <button  className="btn-circle  bg-success text-light">
                      <Edit />
                    </button>} /> 
                    <Link to={`/print_student_enrollment_confirmation/${item.enrollment_id}`} >
                      <button  className="btn-circle bg-warning ml-2 text-light">
                          <PrintOutlined/>
                      </button>
                    </Link>
                </div>
              </div>
              <div className="ed-wrap"><span className="text-main">Data de confirmação :</span> {moment(item.student_enrollment_date).format("YYYY-MM-DD HH:mm:ss")} </div>
              </div> 
          </article>
        </div> 
      ))
      }
   </div> 
  )
}


function PaginatedItems({ itemsPerPage, data, filterValue}) {   
  const FilterData = (data)=>{  
        return data 
   }

  const [itemOffset, setItemOffset] = useState(0); 
  const endOffset = itemOffset + itemsPerPage;
  console.log(`Loading items from ${itemOffset} to ${endOffset}`);
  const currentItems = FilterData(data).slice(itemOffset, endOffset);
  const pageCount = Math.ceil( FilterData(data).length / itemsPerPage); 
  const handlePageClick = (event) => {
    const newOffset = (event.selected * itemsPerPage) % FilterData(data).length; 
    setItemOffset(newOffset);
  }; 
  return (
    <>
      <Items currentItems={currentItems} />
    <div className="ed-space mr-2">
      <div className='ml-2'> 
          <Title>{FilterData(data).length} items encontrados na lista </Title>
       </div> 
      <div>
      <div className="paginate box">
        <ReactPaginate
            breakLabel="..."
            nextLabel=" > "
            onPageChange={handlePageClick}
            pageRangeDisplayed={5}
            pageCount={pageCount}
            previousLabel=" < "
            renderOnZeroPageCount={null}
          />
       </div>
      </div>
    </div>
    </>
  );
}


const Title = styled.h3`
    font-size:18px;
    margin:0px;
`;

export default EnrollmentConfirmationGrid
