import axios from 'axios';
import React, { useEffect, useState } from 'react';
import Form from 'react-bootstrap/Form';
import ReactFlagsSelect from "react-flags-select";
import PhoneInput from 'react-phone-input-2'
import Hoot from '../../General/components/Hoot';
import { Avatar, AvatarGroup } from '@mui/material';


function UserGeneralSettings() {
 const [selectedCountry, setSelectedCountry] = useState("AO");
 const [selectedPhone, setSelectedPhone] = useState("");
 const [Data, setData] =  useState({});
 const [userFirstName, setUserFirstName] =  useState("");
 const [userLastName, setUserLastName] =  useState("");
 const [userEmail, setUserEmail] =  useState("");  
 const [userQuote, setUserQuote] =  useState("");  
 const [userGender, setUserGender] = useState(null);
 const [userCharge, setUserCharge] = useState("");
 const [userCountry, setUserCountry] = useState("");

 const LoadData = async()=>{
     try {
        const response = await axios.get(Hoot()+"eduallgetcurrentuserdata/get");
        console.clear()
        console.log(response.data);
        if(response.data.length >= 1){
            setData(response.data[0]);
            let Info  = response.data[0]
            let Name = Info.ed_user_account_name.split(" ");
            if(Name.length > 1){
                setUserFirstName(Name[0]);
                setUserLastName(Name[1]);
            }else{
                setUserFirstName(Name[0]);
            }
          setUserEmail(Info.ed_user_account_email);
          setUserQuote(Info.ed_user_account_detQuote);
          setUserGender(Info.ed_user_account_gender);
          setUserCharge(Info.ed_user_account_charge);
          setUserCountry(Info.ed_user_account_country);

        }
     } catch (error) {
        console.log(error);
     } 
 }

 useEffect(()=>{
    LoadData();
 },[]);

  return (
    <div className='container-box'>
       <Form>  
      <div className="ed-flex ed-space mb-3">
      <Form.Group className="mb-3 col" controlId="formBasicPassword">
        <Form.Label>Primeiro Nome</Form.Label>
        <Form.Control value={userFirstName} type="text" placeholder="-----" />
      </Form.Group> <div className="pd-1"></div>
      <Form.Group className="mb-3 col" controlId="formBasicCheckbox">
      <Form.Label>Ultimo nome</Form.Label>
          <Form.Control value={userLastName} type="text" placeholder="----" />
       </Form.Group> 
      </div>
      <div className="ed-flex ed-space mb-3">
      <Form.Group className="mb-3 col" controlId="formBasicPassword">
        <Form.Label>Email</Form.Label>
        <Form.Control value={userEmail} type="email" placeholder="----" />
      </Form.Group> <div className="pd-1"></div>
      <Form.Group className="mb-3 col" controlId="formBasicCheckbox">
      <Form.Label>Número de telefone</Form.Label>
      <PhoneInput country={'us'}  value={selectedPhone} onChange={(phone) => console.log(phone)}/>
       </Form.Group> 
      </div>
      <div className="ed-flex ed-space mb-3">
      <Form.Group className="mb-3 col" controlId="formBasicPassword">
        <Form.Label>País</Form.Label>
        <ReactFlagsSelect selected={userCountry !== null ? userCountry : selectedCountry} onSelect={(code) => setSelectedCountry(code)}/>
      </Form.Group> <div className="pd-1"></div>
      <Form.Group className="mb-3 col" controlId="formBasicCheckbox">
      <Form.Label>Profissão</Form.Label>
          <Form.Control type="text" placeholder="------" />
       </Form.Group> 
      </div>
      <div className="mb-3">
        <Form.Group>
             <Form.Label>Mensagem de entrada</Form.Label>  
            <Form.Control value={userQuote} as="textarea" rows={3} /> 
        </Form.Group>
      </div>
      <div className="ed-flex ed-space mb-3">
      <Form.Group className="mb-3 col" controlId="formBasicPassword">
        <Form.Label>Genero</Form.Label>
        <Form.Select value={userGender}>
            <option value="0">Masculino</option>
            <option value="1">Feminino</option>
            <option value="2">Transgênero</option>
            <option value="3">Gênero neutro</option>
            <option value="4">Não binário</option>
            <option value="5">Pangênero</option>
            <option value="6">Gênero queer</option>
            <option value="7">Outro</option>
            <option value="8">Prefiro não dizer</option> 
        </Form.Select>
      </Form.Group> <div className="pd-1"></div>
      <Form.Group className="mb-3 col" controlId="formBasicCheckbox">
      <Form.Label>Data de aniversário</Form.Label>
          <Form.Control value={userLastName} type="date" placeholder="----" />
       </Form.Group> 
      </div>
      <div className="mt-2"><button className="btn bg-main">Salvar alterações</button></div>
    </Form>
    </div>
  )
}

export default UserGeneralSettings
