import React from 'react'
import { CalendarOutline } from 'react-ionicons';
import { Link } from 'react-router-dom';
import CalendarEventsTable from '../components/Table/CalendarEventsTable';
import CalendarEventModal from '../components/modal/CalendarEventModal';

function CalendarEventsList() {
    document.title = 'Lista de eventos';  

    return (
      <div>
        <div className="ed-space">
          <div></div>
            <div className='ed-flex' >
              <Link className='btn mr-2 text-light btn-icon bg-green-light' to='/events_calendar'>
                  <CalendarOutline color={"white"} />
              </Link>
              <CalendarEventModal />
            </div> 
        </div>
        <div className="eduall-table">
            <CalendarEventsTable />
        </div>
      </div>
    )
}

export default CalendarEventsList
