import React from 'react'
import { Link } from 'react-router-dom';
import styled from 'styled-components'
import Logo from  '../../Assets/images/logo-small-white.png';

function LogoItem() {
  return (
    <Lg>
       <Link to='/WorkSpaces' >
          <div className='bg-main logo-menu'>
              <img loading="lazy" role="presentation" src={Logo} alt="eduall" />
          </div>
        </Link>
    </Lg>
  );
}

const Lg = styled.div`
.logo-menu{
    min-width:45px;
    width:45px;
    height:45px;
    border-radius:6px;
    display:flex;
    align-items:center;
    justify-content:center;

       img{
           width:26px;
           height:26px;
           margin:0px;
       }
  }
`;

export default LogoItem
