
import styled from 'styled-components';
import React, { useState, useEffect } from 'react';
import FullCalendar from '@fullcalendar/react';
import dayGridPlugin from '@fullcalendar/daygrid';
import timeGridPlugin from '@fullcalendar/timegrid'; 
import allLocales from '@fullcalendar/core/locales-all'
import interactionPlugin, { Draggable } from "@fullcalendar/interaction";
 


function CalendarBox({ Data ,  showModal }) { 

  function CalendarColors(){ 
    Data.forEach(e => {
        if(document.querySelectorAll(`.custom-calendar-area .el-event-${e.id}`).length > 0){
            document.querySelector(`.custom-calendar-area .el-event-${e.id}`).style.backgroundColor = e.color;
        }
    });   
  }

    useEffect(() => {  
       setTimeout(() => {
         CalendarColors()
       }, 1000);
    }, [Data]); 


  const eventRender = (info) => {
    const { event } = info;
    return (
      <div className={`el-event el-event-${event.id}`} style={{padding: '5px', borderRadius: '5px' }}>
         <span className='text-light'>{event.title}</span>  
      </div>
    );
  };
 

    return (
        <div className="mt-4 custom-calendar-area">
            <BoxContainer> 

                <FullCalendar 
                    plugins={[dayGridPlugin, timeGridPlugin, interactionPlugin]} 
                    initialView="dayGridMonth"
                    locales={allLocales} locale={'pt'}
                    nowIndicator={true} 
                    selectOverlap={() => {
                      return false;
                    }}
                    eventResizableFromStart
                    droppable
                    allDayMaintainDuration

                    editable={true}
                    selectable={true}
                    selectMirror={true}
                    dayMaxEvents={true}

                    headerToolbar={{
                        left: 'prev,next today',
                        center: 'title',
                        right: 'dayGridMonth,timeGridWeek,timeGridDay',
                    }}
                    events={Data}
                    //eventClick={(info) => alert(info.event.title)} 
                    eventContent={eventRender} // Use custom renderin 
                />
            </BoxContainer>
        </div>
    );
}

 
const BoxContainer = styled.div`
   width:100%; 
    border-radius:6px; 
    padding:20px;
    min-height:200px;
    background:var(--ed-white);  
    box-shadow:var(--ed-shadow-df);  
`;

export default CalendarBox 