import { forwardRef, useImperativeHandle, useRef, useState } from 'react';
import styled from 'styled-components';
import LinearProgress from '@mui/material/LinearProgress';
import Img_1 from '../../Assets/images/svg/docs.svg';
import Img_2 from '../../Assets/images/svg/images.svg';
import Img_3 from '../../Assets/images/svg/videos.svg';
import Img_4 from '../../Assets/images/svg/network.svg';
import Img_5 from '../../Assets/images/svg/media.svg';
import { TrashBinOutline } from 'react-ionicons';
import ReduceTextLength from './ReduceTextLength';
import { toast } from "react-toastify";
import { IoMdImages } from 'react-icons/io';  // Importando o ícone IoMdImages
import { DocumentTextOutline } from 'react-ionicons';  // Importando o ícone DocumentTextOutline

const MAX_FILE_SIZE_MB = 15;

const ALLOWED_FILE_TYPES = [
  "image/png", "image/jpg", "image/jpeg", "image/gif", "image/webp",
  "video/mp4", "audio/mp3", "audio/wav",
  "application/pdf", "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
];

const IMAGE_TYPES = ["image/png", "image/jpg", "image/jpeg", "image/gif", "image/webp"];
const VIDEO_TYPES = ["video/mp4"];
const AUDIO_TYPES = ["audio/mp3", "audio/wav"];

const FileIcons = [{ img: Img_1 }, { img: Img_2 }, { img: Img_3 }];

const FileUpload = forwardRef((props, ref) => {
  const DropRef = useRef(null);
  const [fileList, setFileList] = useState([]);

  useImperativeHandle(ref, () => ({
    ClearFiles() {
      setFileList([]);
      props.Files([]);
    }
  }));

  const validateFiles = (files) => {
    let validFiles = [];

    files.forEach(file => {
      if (!ALLOWED_FILE_TYPES.includes(file.type)) {
        toast.error(`Tipo de ficheiro não suportado: ${file.name}`);
      } else if (file.size / 1024 / 1024 > MAX_FILE_SIZE_MB) {
        toast.error(`O ficheiro ${file.name} excede o limite de 15MB!`);
      } else if (!fileList.some(existingFile => existingFile.name === file.name)) {
        validFiles.push(file);
      }
    });

    return validFiles;
  };

  const handleFileChange = (e) => {
    const selectedFiles = Array.from(e.target.files);
    const validFiles = validateFiles(selectedFiles);

    if (validFiles.length) {
      setFileList(prevFiles => [...prevFiles, ...validFiles]);
      props.Files([...fileList, ...validFiles]);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    DropRef.current.classList.remove("drag-over");

    const droppedFiles = Array.from(e.dataTransfer.files);
    const validFiles = validateFiles(droppedFiles);

    if (validFiles.length) {
      setFileList(prevFiles => [...prevFiles, ...validFiles]);
      props.Files([...fileList, ...validFiles]);
    }
  };

  const removeFile = (index) => {
    const updatedList = fileList.filter((_, i) => i !== index);
    setFileList(updatedList);
    props.Files(updatedList);
  };

  return (
    <Container>
      <div className={fileList.length ? "small-label col-lg-12" : ""}>
        <div className="col-lg-12 bxx">
          <label htmlFor={props.input_name} className={props.postupload ? "postuploadlabel col-lg-12" : "label-box col-lg-12"}>
            <div
              ref={DropRef}
              className={`upload-container ${props.size ? "small" : ""} ${props.postupload ? "postupload" : ""}`}
              onDragOver={(e) => { e.preventDefault(); DropRef.current.classList.add("drag-over"); }}
              onDragLeave={() => DropRef.current.classList.remove("drag-over")}
              onDrop={handleDrop}
            >
              {props.postupload ? (
                <>
                  <div className="icon"><IoMdImages /></div>
                  <h4>Arraste ou clique aqui para carregar seus arquivos</h4>
                </>
              ) : (
                <>
                  <div className="icon">
                    <img loading="lazy" src={FileIcons[props.Icon || 0].img} alt="Upload Icon" />
                  </div>
                  <h4>
                    Arrastar os seus ficheiros neste campo para serem carregados no sistema (
                    <span className='text-main'> carregar apenas ficheiros do tipo {props.extensions} </span>) 
                    <strong> {MAX_FILE_SIZE_MB} MB  maximo</strong>
                  </h4>
                </>
              )}
            </div>
            {fileList.length ? (
              <div className="clear" onClick={(e) => { e.preventDefault(); e.stopPropagation(); setFileList([]); }}>
                <TrashBinOutline /> Remover todos arquivos
              </div>
            ) : null}
          </label>
        </div>

        <input
          type="file"
          id={props.input_name}
          name={props.input_name}
          multiple={!props.single}
          hidden
          accept={ALLOWED_FILE_TYPES.join(", ")}
          onChange={handleFileChange}
        />

        <div className={fileList.length ? "file-loader col" : "d-none"}>
          {fileList.map((file, index) => (
            <div className="loaded-item" key={index}>
              <div className="box">
                <div className="prevfile">
                  {IMAGE_TYPES.includes(file.type) && (
                    <div className="icon image-icon"><img src={URL.createObjectURL(file)} alt="Preview" /></div>
                  )}
                  {VIDEO_TYPES.includes(file.type) && (
                    <div className="icon video-icon"><video src={URL.createObjectURL(file)} muted loop autoPlay /></div>
                  )}
                  {AUDIO_TYPES.includes(file.type) && (
                    <div className="icon audio-icon"><audio src={URL.createObjectURL(file)} controls /></div>
                  )}
                  {!IMAGE_TYPES.includes(file.type) && !VIDEO_TYPES.includes(file.type) && !AUDIO_TYPES.includes(file.type) && (
                    <div className="icon doc-icon"><DocumentTextOutline /></div>
                  )}
                </div>
              </div>
              <div className="ed-space">
                <div className="dets col">
                  <h3><ReduceTextLength length={60} text={file.name} /></h3>
                  <small className="size grey-text">{(file.size / 1024 / 1024).toFixed(2)} MB</small>
                </div>
                <div className="remove" onClick={(e) => { e.stopPropagation(); removeFile(index); }}>
                  <TrashBinOutline />
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </Container>
  );
});


 

const Container = styled.div`
   width:100%;
   position:relative; 
   padding:10px 0px;
   background:var(--ed-background-color);
   border:1px solid var(--ed-silver);
   border-radius:6px; 

   
   .bxx{ 
       width:100%;
    }

   .upload-container{
       min-height:300px;  
       width:100%;
       cursor:pointer;
       
          border:2px dashed var(--ed-purple);
          border-radius:10px;
          display:flex;
          align-items:center;
          justify-content:center;
          flex-direction:column;  
    }

    
    .clear{  
      border-radius:6px; 
      display:flex;
      align-items:center;
      justify-content:center;
      cursor:pointer; 
      background:transparent; 
      color:var(--ed-grey-text);
      font-size:13px;
      padding:8px 15px;
      margin-top:20px;
      border:1px solid var(--ed-grey-text);


      svg{
         color:var(--ed-gre-text);
         width:20px;
         height:20px;
         margin-right:5px;
      }
  }

  .clear:hover{
      background:var(--ed-red);
      color:#fff;
      border-color:var(--ed-red) !important;
            svg{
               color:var(--ed-white);
            }
   }


    .upload-container.small{
         min-height:100px !important; 

         h4{
            font-size:15px; 
         }

         img{
            max-width: 200px;
            margin-top:0px;  
         }

         .btn{ 
            font-size:14px; 
            position:relative;
         }
    }


   label{ 
       width:100%;
       height:100%;
       padding:20px 30px;
       display:flex;
       align-items:center;
       justify-content:center;
       text-align:center;
       flex-direction:column; 
   }

   img{
       max-width:250px;
       margin:20px 0;
       min-height:250px;
   }

   h4{
       font-size:17px;
       max-width:570px;
       line-height:30px;
       margin-bottom:20px;
       font-weight:500 !important;
       color:#a4b0be; 
   }


   .file-loader{
      display:flex;
      flex-direction:column;
      justify-content:flex-start; 
      width:100%;
      background:var(--ed-background-color);  
      padding:20px;
      padding-top:0px; 
     
     @media screen and (max-width:1280px){
      .loaded-item{
           width:100% !important;

            .box{
               height:230px;
            }
      }
}

     

 
      .loaded-item{ 
          width:100%; 
          margin:5px 0px; 
          position:relative; 
          padding:5px;
          box-shadow:var(--ed-shadow-df);
          height:80px;
          min-height:70px;
          border-radius:6px;
          background:var(--ed-white);
          display:flex; 
          align-items:center;


          .remove{
              margin:0px 10px !important;
              width:40px;
              height:40px;
              min-width:40px;
              border-radius:100%;
              border:1px solid var(--ed-grey-text);
              cursor:pointer;
              transition:all 1s ease-in-out;
              display:flex;
              align-items:center;
              justify-content:center;


               span{
                   display:flex;
                   align-items:center;
                   justify-content:center;
                 }

                 svg{
                    width:18px;
                    height:18px;
                    color:var(--ed-grey-text);
                    margin:0px !important;
                 }
          }


         .remove:hover{
            background:var(--ed-red);
            border:none !important;
                svg{
                    color:var(--ed-white);
                }
         }



         .dets{
            padding-left:10px;
            display:block;
            text-align:left; 
            font-size:14px;

            h3{
               font-size:14px;
               text-align:left;
               margin:0px;
            }  

            .btn{
               padding:3px 10px;
               border:2px solid var(--ed-red) !important;
               color:var(--ed-red) !important;
               background:transparent !important;
               box-shadow:none;
               font-size:13px;
            }
         } 

          .box{ 
            position:relative; 
            overflow:hidden;
            border-radius:6px;
            background:var(--ed-white);
            width:80px;
            min-width:90px; 
            height:100%;  
            border:1px solid var(--ed-silver-light);

            
            .prevfile{
               padding:0px;
               height:100%; 
               width:100%;

               img, video, .image-icon, .video-icon, .doc-icon{
                  width:100%;
                  height:100%; 
                  object-fit:cover !important;
               }

               video{
                  object-fit:cover;
               }

               .doc-icon{
                  background:var(--ed-purple);
                  display:flex;
                  align-items:center;
                  justify-content:center;

                  svg{
                       width:40px;
                       height:40px;
                       fill:var(--ed-white);
                       color:var(--ed-white);
                  }
               }
           }

            .box-over{ 

                .size{
                  padding:4px 10px;
                  background:var(--ed-white);
                  box-shadow:var(--ed-shadow-df);
                  border-radius:6px;
                  height:30px;
                  font-size:15px;
                }
            }
               
            img, video{
               width:100%;
               height:100%;
               margin:0px;
               min-height:auto !important;
            }

            .doc-icon{
               background:var(--ed-green);
               svg{
                    width:50px;
                    height:50px;
               }
            }
          }
      }
   }



  
   label.postuploadlabel{ 
      padding:5px 20px !important;
  }

    .postupload.upload-container{
        min-height:80px !important;

        h4{
           font-size:13px !important;
           margin:0px  !important;
           max-width:300px;
           line-height:20px;
        }

        .icon{
         font-size:50px;

           img{
              max-width:150px !important; 
              min-height:90px !important;
              margin:0px !important;
              margin-bottom:5px !important;
           }

           svg{
            color:var(--ed-dark); 
            margin-bottom:5px !important;
           }
        }
    }



   .small-label{
      display:flex;
      align-items:center;
      flex-direction:column; 

      .label{ 
         display:none !important;
      } 

    label{ 
     .icon img {
         max-width:160px !important;
         max-height:150px !important;
         min-height:90px !important;
         margin:0px !important;
      }

   

      .label-box{ 
          padding-right:20px;
      } 

      .upload-container{ 
         min-height:350px;
          width:100%;
          border:2px dashed var(--ed-purple);
          border-radius:10px;
          display:flex;
          align-items:center;
          justify-content:center;
          flex-direction:column;  
      }
   }
}


`;
export default FileUpload 