import React, { useEffect, useState, useMemo } from "react";
import axios from "axios";
import Hoot from "../../../General/components/Hoot";
import { Badge } from "react-bootstrap";
import TableGrid from "../../../General/components/TableGrid";
import { Avatar } from "@mui/material";
import SwitchFromPages from "../../../General/components/SwitchFromPages";
import { PiMicrosoftExcelLogoDuotone } from "react-icons/pi";
import ExportDataForTablesExcel from "../../../General/components/ExportDataForTablesExcel";

export default function ClassTransportPaymentsTable() {
  const [data, setData] = useState([]);
  const [status, setStatus] = useState("loading");

  useEffect(() => {
    const loadData = async () => {
      try {
        setStatus("loading");
        const { data: response } = await axios.get(
          `${Hoot()}eduallGetAllClassestransportaymentsStatus/get/`
        );
        setData(Array.isArray(response) ? response : []);
        setStatus("success");
      } catch (err) {
        console.error("❌ Erro ao carregar dados:", err);
        setStatus("error");
      }
    };
    loadData();
  }, []);

  // 📊 Resumo geral de pagamentos
  const summary = useMemo(() => {
    const stats = { paid: 0, notPaid: 0, canceled: 0, others: 0 };
    data.forEach(cls => {
      cls.students?.forEach(student => {
        student.months?.forEach(month => {
          switch (month?.status) {
            case "paid": stats.paid++; break;
            case "notpaid": stats.notPaid++; break;
            case "canceled":
            case "null": stats.canceled++; break;
            default: stats.others++; break;
          }
        });
      });
    });
    return stats;
  }, [data]);

  // 🌀 Estados visuais
  if (status === "loading") {
    return (
      <div className="ed-flex ed-center">
        <h4 className="title">Carregando informações de transporte...</h4>
      </div>
    );
  }

  if (status === "error") {
    return (
      <div className="ed-flex ed-center">
        <h4 className="text-danger">Erro ao carregar informações de transporte.</h4>
      </div>
    );
  }

  if (!data.length) {
    return (
      <div className="ed-flex ed-center">
        <h4 className="text-muted">Nenhuma turma encontrada.</h4>
      </div>
    );
  }

  // 🔹 Função auxiliar para montar badge de status
  const renderStatusBadge = (status) => {
    switch (status?.toLowerCase?.()) {
      case "paid":
        return <Badge bg="success" className="col-12">Propina paga</Badge>;
      case "notpaid":
        return <Badge bg="warning" className="col-12">Propina não paga</Badge>;
      case "null":
      case "canceled":
        return <Badge bg="danger" className="col-12">Pagamento anulado</Badge>;
      default:
        return <Badge bg="secondary" className="col-12">N/A</Badge>;
    }
  };

  return (
    <div>
      {/* 🔸 Estatísticas gerais */}
      <div className="status-total ed-flex flex-wrap gap-2 mb-3">
        <h5><div className="dot bg-green mr-1"></div>Pagas - {summary.paid}</h5>
        <h5><div className="dot bg-warning mr-1"></div>Não pagas - {summary.notPaid}</h5>
        <h5><div className="dot bg-danger mr-1"></div>Anuladas - {summary.canceled}</h5>
        <h5><div className="dot bg-secondary mr-1"></div>Outros - {summary.others}</h5>
      </div>

      {/* 🔸 Tabelas por turma */}
      {data.map((cls, index) => {
        const yearStart = cls.academic_year?.startDate?.split("-")?.[0] || "—";
        const yearEnd = cls.academic_year?.endDate?.split("-")?.[0] || "—";

        const baseColumns = [
          {
            field: "student",
            headerName: "Nome do estudante",
            resizable: true,
            width: 300,
            cellRenderer: (props) => (
              <SwitchFromPages
                link={`studentinfo/${props.data.id}`}
                menu="3"
                menu_item="17"
                toggle_btn={
                  <div className="ed-flex">
                    <Avatar
                      alt={props.data.student?.charAt(0) || ""}
                      src={props.data.picture ? Hoot() + props.data.picture : ""}
                      className="df"
                    />
                    <span className="ml-2">{props.data.student}</span>
                  </div>
                }
              />
            ),
          },
        ];

        // Adiciona colunas de meses dinamicamente
        const monthColumns = cls.students?.[0]?.months?.map((month, i) => ({
          field: `month_${i}`,
          headerName: month?.month || `Mês ${i + 1}`,
          resizable: true,
          width: 180,
          cellRenderer: (props) => renderStatusBadge(props.value),
        })) || [];

        const columns = [...baseColumns, ...monthColumns];

        // Gera linhas
        const rows = cls.students?.map(student => {
          const row = {
            id: student.id,
            student: `(#${student.id}) - ${student.name}`,
            picture: student.picture,
          };
          student.months?.forEach((m, i) => {
            row[`month_${i}`] = m.status;
          });
          return row;
        }) || [];

        return (
          <div key={cls.class_id || index} id={`ClassTransportPaymentsTable-${index + 1}`} className="mb-5">
            <TableGrid
              NoCustomItems
              TableHead={columns}
              TableBody={rows}
              TableHeight={rows.length < 5 ? 220 : 370}
              TableTitle={`Turma: ${cls.class_title} — Ano académico: ${yearStart} / ${yearEnd}`}
              TableBtn={
                <div className="ed-flex">
                  <button
                    className="btn-icon btn btn-export-data"
                    title="Exportar para Excel"
                    onClick={() =>
                      ExportDataForTablesExcel(
                        `Pagamentos de Transporte - ${cls.class_title} (${yearStart}/${yearEnd})`,
                        ["Ação"],
                        `ClassTransportPaymentsTable-${index + 1}`
                      )
                    }
                  >
                    <PiMicrosoftExcelLogoDuotone />
                  </button>
                </div>
              }
            />
          </div>
        );
      })}
    </div>
  );
}
