import React, {useState} from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import {Modal, Form, Button} from 'react-bootstrap'
import { Save, Update } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';


function NewAdmissionRegisterModal(props) {
    const [show, setShow] = useState(false); 
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [Founded, SetFounded] = useState(null);

       
    const [showBox, SetshowBox]  = useState(false);
    const handleClose = () => {
      SetshowBox(false);
      setTimeout(() => {
        setShow(false);
      }, 1200);
    } 

    const handleShow = () => {
          SetshowBox(true);
          setShow(true);  
          setTimeout(() => {  
 
          }, 1000);   
    };
    
  return (
    <div>
       <button className='btn btn-main bg-main ml-2' onClick={handleShow}>
           <AddCircleOutlineIcon/> Criar registro de admição
      </button> 
      <Modal className={showBox ? ModalAnimationShow() : ModalAnimationClose()}  centered  dialogAs={DraggableModal}  size='lg' show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title> 
            <div className="ed-wrap align-center">
                  <UserOptionDropDown />
                  <h5> Criar registro de admição</h5>
              </div>  
          </Modal.Title>
        </Modal.Header>
        <Modal.Body className='scrollLimit'>
          <Form> 
            <Form.Group className="mb-3"  >
              <Form.Label>Titulo<span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Control type="text" autoFocus/>
            </Form.Group>  
            <Form.Group className="mb-3"  >
              <Form.Label>Código<span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Control type="text"/>
            </Form.Group>  
            <Form.Group className="mb-3"  >
              <Form.Label>Curso<span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Select select>
                  <option value="1" selected>1</option>
                  <option value="2">2</option>
                  <option value="3">3</option>
              </Form.Select>
            </Form.Group>  
            <Form.Group className="mb-3"  >
              <Form.Label>Data inicial<span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Control type="date"/>
            </Form.Group> 
            <Form.Group className="mb-3"  >
              <Form.Label>Data de finalização<span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Control type="date"/>
            </Form.Group> 
            <Form.Group className="mb-3"  >
              <Form.Label>Número minimo de candidatos<span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Control type="number"/>
            </Form.Group> 
            <Form.Group className="mb-3"  >
              <Form.Label>Número maximo de candidatos<span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Control type="number"/>
            </Form.Group> 
            <Form.Group className="mb-3"  >
              <Form.Label>Estado<span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Select select>
                  <option value="1" selected>1</option>
                  <option value="2">2</option>
                  <option value="3">3</option>
              </Form.Select>
            </Form.Group> 
            <Form.Group className="mb-3"  >
              <Form.Label>Descrição<span className="text-danger ml-2">*</span> </Form.Label>
              <Form.Control as="textarea" rows={4}/>
            </Form.Group> 
          </Form>
        </Modal.Body>
        <Modal.Footer>
          <div className="ed-space">
            <div className="ed-flex"></div>
            <div className="ed-flex">
            <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button> 
              {props.update ? (Founded === false ? <div></div>  : 
              <SaveButton icon={props.title ? <Update/> : <Save/>} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
              <SaveButton icon={props.title ? <Update/> : <Save/>} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />} 
            </div>
          </div>
        </Modal.Footer>
      </Modal>
    </div>
  )
}

export default NewAdmissionRegisterModal