import axios from 'axios';
import React, { useEffect, useState } from 'react'
import Hoot from '../../../General/components/Hoot';
import styled from 'styled-components';
import { Avatar, Skeleton } from '@mui/material';
import ReduceTextLength from '../../../General/components/ReduceTextLength';
import { Link } from 'react-router-dom/cjs/react-router-dom';
import TitleBlock from '../../Components/TitleBlock';

function PP_classmates(props){
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);


  async function loadData(e){  
     try {
       setLoaded(false); 
      const response =  await axios.get(Hoot()+"eduallgetstudentsbyclass/"+e); 
       setData(response.data); 
      setTimeout(() => {
         setLoaded(true); 
      }, 200);
     } catch (error) {
       setTimeout(() => {
         setLoaded(true); 
      }, 200);
     }
  }

  useEffect(()=>{
      loadData(props.class); 
  },[props]);


  if(load  === true){ 
    return (
      <Container> 
        <div className="mt-2 mb-2">
           <TitleBlock title="Colegas de turma" />
        </div>
          <ul className='ed-wrap pp-students-collegues'>
              {data.map((item, index)=>{
                  return(<Box className='li-mt'  key={index+1}> 
                      <div className="circle"></div>
                      <div className="ed-flex box-content">
                           <Avatar className='df' src={Hoot()+item.ed_student_picture} sx={{width:70,height:70}} alt={item.ed_student_name}>{item.ed_student_name.split("")[0]}</Avatar>
                           <div className="ed-block ml-2">
                              <h5><ReduceTextLength text={item.ed_student_name} length={30}/></h5>
                              <div className="mt-2"><small><Link to="#" className="text-grey grey-text">Nº de matrícula : {item.ed_student_code} </Link></small></div>
                           </div>
                      </div>
                   </Box>)
              })}  
          </ul>
      </Container>
    ) 
  }else{ 
    return (
      <Container> 
        <div className="mt-2 mb-2">
           <TitleBlock title="Colegas de turma" />
        </div>
          <ul className='ed-wrap pp-students-collegues'>
              {[1,2,3,4,5,6,7,8,9] .map((item, index)=>{
                  return(<Box className='li-mt' key={index+1}> 
                      <div className="circle"></div>
                      <div className="ed-flex box-content">
                           <Avatar className='df'  sx={{width:70,height:70}}></Avatar>
                           <div className="ed-block ml-2 col">
                              <h5> <Skeleton variant='rectangle' animation='wave' width='90%' height={10} /></h5>
                              <div className="mt-2"><Skeleton variant='rectangle' animation='wave' width='100%' height={10} /></div>
                           </div>
                      </div>
                   </Box>)
              })}  
          </ul>
      </Container>
    )
  }


}

const Container = styled.div`
    width:100%;

    ul{
        padding:0px;
        margin:0px;
        gap:15px;
    }
`;

const Box = styled.div`
    background:var(--ed-white); 
    border-radius:6px; 
    box-shadow:var(--ed-shadow-df);
    width:calc(33.3% -  15px);
    min-height:90px; 

    .box-content{
        padding:10px;

         h5{
             font-size:16px;
             margin:0px;
         }

         small a{
            font-size:14px;
         }
    }
`;


export default PP_classmates 