import { Avatar } from '@mui/material';
import React, { useEffect, useState } from 'react';
import ArrowDropDownRoundedIcon from '@mui/icons-material/ArrowDropDownRounded';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';

function UserOptionDropDown(props){
    const [Loaded, setLoaded] = useState(false);
    const [Data, setData] = useState({});

   const LoadData = async()=>{
    try {
        const response = await axios.get(Hoot()+"eduallgetcurrentuserdata/get");
        if(response.data){
            setLoaded(true); 
            setData(response.data); 
        }else{
            setLoaded(false);
        }
    } catch (error) {
        setLoaded(false); 
    }
   }

   useEffect(()=>{
    LoadData();
   },[]);


 if(Loaded){
    return (
        <div>
          <li className="ed-flex mr-2" onclick={()=>LoadData()} >
              <Avatar className='df' src={Hoot()+Data?.ed_user_account_picture} sx={{width:50,height:50}}  />
              {!props.noarrow ? <ArrowDropDownRoundedIcon /> : <></>} 
            </li> 
        </div>
      )
 }else{
    return (
        <div>
          <li className="ed-flex mr-2">
              <Avatar className='df' sx={{width:50,height:50}}  />
              <ArrowDropDownRoundedIcon />
            </li> 
        </div>
      )
 }
}

export default UserOptionDropDown
