import React from 'react'
import { Link } from 'react-router-dom';
import styled from 'styled-components';
import ImageLazyLoading from '../../../General/components/ImageLazyLoading';

function Profile_gn_formations({data}){
    const Data = [
        {name:"Oregon College", image:"https://pbs.twimg.com/profile_images/1494452643510427648/wcMB4Tm0_400x400.jpg"},
    ]
    
      return (
        <Container>
        <h1 className="title">Formação academica (1)</h1>
        <section>
             {Data.map((item, index)=>{
                return(
                  <article>
                  <div className="content-header">
                      <div className="company-logo">
                           <Link to="#">
                              <div className="icon"><ImageLazyLoading height={80} source={item.image} /></div>
                          </Link>
                      </div>
                   <div className="ed-block">
                   <Link to="#"><h5>{item.name}</h5></Link>
                     <span className="charge">Engenheiro de software</span>
                     <div className="date">Desde 14 de Maio de 2019 até 23 de Junho de 2023</div>
                   </div>
                  </div>
               </article>)
             })}
        </section>
    </Container>
      )
    }
    
    
    
    const Container = styled.div`
        margin:20px 0px;
    
         section{
              margin:10px 0px;
    
               article{
                   display:block;
                   margin:30px 0px;
                   background:var(--ed-silver-light);
                   padding:10px;
                   border-radius:6px;
    
                   .content-header{
                      display:flex;
    
                      .company-logo{
                          height:80px;
                          width:80px;
                          border:3px solid var(--ed-silver-light); 
                          margin-right:20px;
                          border-radius:6px;
    
                          img{
                            border-radius:6px;
                            height:100%;
                            width:100%;
                          }
                      }
    
    
                     .ed-block{
                         h5{
                            font-size:18px;
                            color:var(--ed-dark);
                          }
    
                          .charge, .date{
                             font-size:15px;
                          }
    
                          .date{
                            color:var(--ed-grey-text);
                          }
                     } 
    
                   }
     
    
    
    
               }
         }
    
    `;
export default Profile_gn_formations
