import React, { useEffect, useState } from 'react'
import { FiDownloadCloud } from "react-icons/fi";
import TableGrid from '../../../General/components/TableGrid';
import RefreshButton from '../../../General/components/RefreshButton';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';

const TABLEURL = Hoot()+"";


let Categories = ["", "Designer", "Arte", "Engenharia", "Saude", "Ciências"];
const TAX = ["Sim", "Não"];


const columns = [
  {
    field: 'index',
    headerName: 'Nº',
    resizable: true,
    width: 90,
  },
  {
    field: 'title',
    headerName: 'Fatura',
    resizable: true,
    width: 300,
  },
  {
    field: 'price',
    headerName: 'Preço',
    resizable: true,
  },
  {
    field: 'date',
    headerName: 'Data',
    resizable: true,
  },
  {
    field: 'refer',
    headerName: 'Referencia',
    resizable: true,
  },
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true, cellRenderer: (props) => {
      return <div className="ed-flex">
        <a href="#" target="_blank" rel="noopener noreferrer">
          <button className="btn-circle  bg-success text-light">
            <FiDownloadCloud />
          </button>
        </a>
      </div>;
    }
  }
];


function SystemBillingsTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData() {
    try {
      setLoadStatus(0);
      setLoaded(false);
      const response = await axios.get(TABLEURL);
      const rows = [];
      response.data.map((item, index) => {
        rows.push({

        });
      });
      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoadStatus(1);
    }
  }

  useEffect(() => {
    loadData();
  }, []);




  if (load) {
    return (
      <div>
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Pagamentos do sistema (Licença  / Serviços)'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    )
  } else {
    return (
      <div>
        <><div className="d-none">*</div>
          <TableGrid
            TableHead={columns}
            TableBody={[]}
            TableTitle='Pagamentos do sistema (Licença  / Serviços)'
            TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
          />
        </>
      </div>
    )
  }
}

export default SystemBillingsTable