 import Menu from '@mui/material/Menu';
import MenuItem from '@mui/material/MenuItem';
import React, { useEffect, useState } from 'react'

function MenuDropDown(props) {
    const [anchorEl, setAnchorEl] = useState(null);
    const open = Boolean(anchorEl); 

    const handleClick = (event) => {
      setAnchorEl(event.currentTarget);
    };

    const handleClose = () => {
      setAnchorEl(null);
    };

    function closeButton(){
      if(props.closeItem && props.closeItem === true){
        handleClose();
      }
    }

    useEffect(() => {
      closeButton(); 
    }, [props])
    


  return (
    <div>
        <div id="internet-toggle-btn"  aria-controls={open ? 'basic-menu' : undefined} 
            aria-haspopup="true"  aria-expanded={open ? 'true' : undefined} onClick={handleClick} >
           {props.toggle_btn}
        </div>
        <Menu className={`${props.ChatBox ? "chat-widget-bx" : "" }`} id="basic-menu"  anchorEl={anchorEl}
        open={open}onClose={handleClose}MenuListProps={{ 'aria-labelledby': 'internet-toggle-btn', }}>
            <div>{props.header ?  <>{props.header}</> : <></>}</div>
            <div>
             {props.menus ? 
                <>
                 {props.menus.map((item, index)=>{
                    return(
                        <MenuItem key={index+1} onClick={handleClose}>    
                            {item}
                        </MenuItem> 
                    )
                })}
                </>
                : <></>}
            </div> 
            <div>
               {props.content ?  <> {props.content}</> : <></>}
            </div>
      </Menu>
    </div>
  )
}

export default MenuDropDown