import React, { useEffect, useState } from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap'
import { InfoOutlined, Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import ClearInputs from '../../../General/components/ClearInputs';
import { GetInstituteCode, GetTransportStopsDataOptions, ServiceDataOptions, StudentsArray, StudentsDataOptions } from '../../../General/components/InstituteData';
import CRValue from '../../../General/components/CRValue';
import { toast } from 'react-hot-toast';
import { Update } from '@material-ui/icons';
import SelectSearch from 'react-select-search';
import StudentDetailsMenu from '../elements/StudentDetailsMenu';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import RefreshList from '../../../General/components/RefreshList';

function NewTransportPassengerModal(props) {
  const [show, setShow] = useState(false);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});
  const [studentCode, setStudentCode] = useState(null);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [Founded, SetFounded] = useState(null);

  const [showBox, SetshowBox] = useState(false);
  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200);
  }

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };


  const INPUTS = {
    passenger_month_of_membership: CRValue("#passenger_month_of_membership"),
    passenger_stop: CRValue("#passenger_stop"),
  };

  const FORMURL = [
    Hoot() + "edualltransportpassengerregister/post/",
    props.get ? props.get : '',
    props.url ? props.url : ''
  ];

  const GET_DATA = async () => {
    if (props.update) {
      try {
        const response = await axios.get(FORMURL[1]);
        if (response.data.length > 0) {
          document.querySelector("#passenger_month_of_membership").value = response.data[0].ed_transport_passenger_startMonth;
          document.querySelector("#passenger_stop").value = response.data[0].ed_transport_passenger_stop;

          INPUTS.passenger_stop = response.data[0].ed_transport_passenger_stop;
          INPUTS.passenger_month_of_membership = response.data[0].ed_transport_passenger_startMonth;
          setStudentCode(response.data[0].ed_transport_passenger_code);
        } else {
          toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
          console.log("NOT FOUNDED ....")
        }
      } catch (error) {
        console.clear();
        console.log(error);
        toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
      }
    }
  }

  const GetStudentCode = (e) => {
    setStudentCode(e);
    setField("passenger_code", e);
  }

  const setField = (field, value) => {
    setForm({
      ...form,
      [field]: value
    })

    if (!!errors[field]) {
      setErrors({
        ...errors,
        [field]: null
      });
    }
  }


  const validateForm = () => {
    const { passenger_month_of_membership, passenger_stop } = form;
    const NewErrors = {};
    setRegisterStatus(0);
    if (INPUTS.passenger_month_of_membership === "" || INPUTS.passenger_month_of_membership === " ") {
      if (!passenger_month_of_membership || passenger_month_of_membership === '') NewErrors.passenger_month_of_membership = 'Selecione um mês de adesão valido !';
    } else { if (!passenger_month_of_membership) { setField("passenger_month_of_membership", INPUTS.passenger_month_of_membership); } }

    if (studentCode === null) NewErrors.passenger_code = 'Estudante selecionado é  invalido !';

    if (INPUTS.passenger_stop === "" || INPUTS.passenger_stop === " ") {
      if (!passenger_stop || passenger_stop === '') NewErrors.passenger_stop = 'Data invalida !';
    } else { if (!passenger_stop) { setField("passenger_stop", INPUTS.passenger_stop); } }
    return NewErrors;
  }



  const FormSubmit = (e) => {
    e.preventDefault();
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os  campos");
      setRegisterStatus(1);
    } else {

      const SUBMIT_INPUTS = {
        passenger_month_of_membership: INPUTS.passenger_month_of_membership,
        passenger_code: studentCode,
        passenger_stop: INPUTS.passenger_stop
      };

      if (!props.update) {
        console.log(SUBMIT_INPUTS);
        try {
          axios.post(FORMURL[0], SUBMIT_INPUTS).then(() => {
            toast.success("Passageiro registrada com sucesso !");
            setRegisterStatus(2);
            setForm({});
            ClearInputs();
            RefreshList(`.el-refresh-list`)
          }).catch((error) => {
            const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
            toast.error(msg);
            setRegisterStatus(1);
          });
        } catch (error) {
          const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
          toast.error(msg);
          setRegisterStatus(1);
        }

      } else {
        try {
          axios.put(FORMURL[2], SUBMIT_INPUTS).then(() => {
            toast.success("Passageiro atualizada com sucesso !");
            setRegisterStatus(2);
            setForm({});
            ClearInputs();
            RefreshList(`.el-refresh-list`)
            setTimeout(() => {
              handleClose();
            }, 1000);
          }).catch((error) => {
            const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
            toast.error(msg);
            setRegisterStatus(1);
          });
        } catch (error) {
          const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
          toast.error(msg);
          setRegisterStatus(1);
        }
      }
    }
  };


  const handleInput = (e) => {
    switch (e.target.id) {
      case "passenger_month_of_membership":
        INPUTS.passenger_month_of_membership = e.target.value
        setField("passenger_month_of_membership", e.target.value);
        break;
      case "passenger_stop":
        INPUTS.passenger_stop = e.target.value
        setField("passenger_stop", e.target.value);
        break;
      default:
    }
  }



  return (
    <div>
      <div onClick={handleShow}>
        {
          props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon /> Registrar  Passageiro</button>
        }
      </div>
      <Modal className={showBox ? ModalAnimationShow() : ModalAnimationClose()} centered size='lg' dialogAs={DraggableModal} show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>{props.title ? props.title : 'Registrar novo '} Passageiro</h5>
            </div>
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={FormSubmit}>
          <Modal.Body className='scrollLimit'>
            <Form.Group className="mb-3">
              <div className="ed-space">
                <div>
                  <Form.Label>Nome do estudante <span className='text-danger ml-2'>*</span></Form.Label>
                </div>
                <div className='ed-flex'>
                  {studentCode !== null ? <StudentDetailsMenu student_id={studentCode} toggle_btn={<div className='btn-pm-info'><InfoOutlined /></div>} /> : <></>}
                </div>
              </div>
              <div className={`select-search-item  ${errors.passenger_code ? 'error' : ''}`}>
                <SelectSearch onChange={(e) => GetStudentCode(e)} value={studentCode} options={StudentsArray()[0]} search={true}
                  placeholder="Selecione um aluno" />
              </div>
              <small className="text-danger">{errors.passenger_code}</small>
            </Form.Group>
            <Form.Group className="mb-3" >
              <Form.Label>Mês de adesão<span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Select onChange={handleInput} className={!!errors.passenger_month_of_membership && 'is-invalid'} value={form.passenger_month_of_membership} isInvalid={!!errors.passenger_month_of_membership}
                id="passenger_month_of_membership">
                <option value="0">Janeiro</option>
                <option value="1">Fevereiro</option>
                <option value="2">Março</option>
                <option value="3">Abril</option>
                <option value="4">Maio</option>
                <option value="5">Junho</option>
                <option value="6">Julho</option>
                <option value="7">Agosto</option>
                <option value="8">Setembro</option>
                <option value="9">Outubro</option>
                <option value="10">Novembro</option>
                <option value="11">Dezembro</option>
              </Form.Select>
              <Form.Control.Feedback type='invalid'>{errors.passenger_month_of_membership}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Paragem <span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Select onChange={handleInput} className={!!errors.passenger_stop && 'is-invalid'} value={form.passenger_stop} isInvalid={!!errors.passenger_stop}
                id="passenger_stop">
                <GetTransportStopsDataOptions />
              </Form.Select>
              <Form.Control.Feedback type='invalid'>{errors.passenger_stop}</Form.Control.Feedback>
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <div className="ed-space">
              <div className="ed-flex"></div>
              <div className="ed-flex">
                <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                {props.update ? (Founded === false ? <div></div> :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />}
              </div>
            </div>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  )
}

export default NewTransportPassengerModal