import { Search } from '@material-ui/icons'
import React, { useState, useEffect} from 'react'
import {Form } from 'react-bootstrap'
import styled from 'styled-components'
import { useHistory } from "react-router-dom";
import { useLocation } from 'react-router-dom';

function NavbarSearchForm() {
 const [TextSearch, SetTextSearch] =  useState("");
 const navigate = useHistory();
 const { search } = useLocation();
 const searchParams = new URLSearchParams(search);
 const param = searchParams.get("search");


 const SearchData = (e) =>{
  if(TextSearch.split("").length >= 1 ){
    e.preventDefault();
    navigate.push(`/search?search=`+TextSearch);
  }
}

    
 
useEffect(()=>{
    SetTextSearch(param);
 },[]); 


  return (
    <Container className='navbar-search-form'>
         <Form className='ml-2' onSubmit={SearchData} encType="multipart-form-data" >
            <Search/>
            <Form.Control value={TextSearch} onChange={(e)=>SetTextSearch(e.target.value)} placeholder='Encomtre maravilhas ...' />
        </Form>
    </Container>
  )
}

const Container = styled.div`
    form{
        display:flex;
        align-items:center;
        border-radius:6px;
        height:45px;
        min-width:200px;
        border:1px solid red;
        padding:4px 10px;
        background:var(--ed-background-color);  
        border:1px solid var(--ed-silver-light);

        input{
            background:var(--ed-background-color);  
            border:0px solid transparent !important;

            &:hover,
            &:focus{
                box-shadow: none !important;
                background: transparent !important;
                border: none !important;
            }
        }
    }
`;

export default NavbarSearchForm
