import React, {useState, useEffect} from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import {Modal, Form, Button} from 'react-bootstrap'
import { Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import {toast} from 'react-hot-toast';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import CourseDataOptions, { ClassDataOptions, GetInstituteCode } from '../../../General/components/InstituteData'; 
import { SettingsApplicationsRounded, Update } from '@material-ui/icons';
import RefreshList from '../../../General/components/RefreshList';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import { Link } from 'react-router-dom';
import StudentCard from '../../../General/components/StudentCard';
import ReplaceWord from '../../../General/components/ReplaceWord';

 
 

function PrintCardModal(props) {
    const [show, setShow] = useState(false);
    const [form, setForm] = useState({});
    const [errors, setErrors] = useState({});  
    const [ClassCode, setClassCode] = useState(null);
    const Data = [];
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [Founded, SetFounded] = useState(null);
  
   
    const [showBox, SetshowBox]  = useState(false);
    const handleClose = () => {
      SetshowBox(false);
      setTimeout(() => {
        setShow(false);
      }, 1200);
    } 
  
    const handleShow = () => {
          SetshowBox(true);
          setShow(true);  
    };
  
    
  
    return (
      <>
            <div className='bx-card' onClick={handleShow}>
              {
                props.toggle_btn ? props.toggle_btn :  <button className='btn btn-main bg-main'><AddCircleOutlineIcon/> Criar cartão de estudante </button> 
              }
            </div>
            <Modal size='md' centered  className={showBox ? ModalAnimationShow() : ModalAnimationClose()}  dialogAs={DraggableModal}  show={show} onHide={handleClose}>
              <Modal.Header closeButton>
                <Modal.Title>
                    <div className="ed-wrap align-center">
                      <UserOptionDropDown />
                      <h5> { props.title ? props.title+' Curso' : 'Criar cartão de estudante' }  </h5>
                  </div>   
                </Modal.Title>
              </Modal.Header>
              <Form>
              <Modal.Body className='scrollLimit'> 
              <Form.Group className="mb-3">
                <Form.Label>Selecionar {ReplaceWord("Classe", true)}<span className="text-danger ml-2">*</span> </Form.Label>
                <Form.Select  type="text"  onChange={(e)=>setClassCode(e.target.value)} className={!!errors.course_title && 'is-invalid'} 
                value={form.course_title}  isInvalid={!!errors.course_title} id="course_title">
                      <ClassDataOptions />
                </Form.Select>
                <Form.Control.Feedback type='invalid'>{errors.course_title}</Form.Control.Feedback>
            </Form.Group>   
            <div className="mt-4">
               <StudentCard index={props.card} data />
            </div>
              </Modal.Body>
              <Modal.Footer>
                <Link to={(ClassCode !== null) ? `/print_student_cardID/${props.card},${ClassCode} ` : "#"}>
                   <button  disabled={(ClassCode !== null) ? false : true}  className="col btn bg-main">Imprimir cartão escolar</button>
                </Link>
              </Modal.Footer>
              </Form>
            </Modal>
      </>
    )
}

export default PrintCardModal