import React, { useEffect, useState } from 'react';
import axios from 'axios';
import Hoot from './Hoot';

const extractUrls = (text) => {
  const urlRegex = /(https?:\/\/[^\s]+)/g;
  return text.match(urlRegex) || [];
};

const LinkPreviewComponent = ({ text }) => {
  const [previews, setPreviews] = useState([]);

  useEffect(() => {
    const urls = extractUrls(text);

    const fetchPreviews = async () => {
      const results = await Promise.all(urls.map(async (url) => {
        try {
          // 🔁 Agora usa a rota do seu backend:
          const response = await axios.get(Hoot()+`api/link-preview?url=${encodeURIComponent(url)}`);
          return { url, data: response.data };
        } catch (error) {
          console.warn('Erro ao buscar preview de link:', url);
          return null;
        }
      }));

      setPreviews(results.filter(Boolean));
    };

    if (urls.length > 0) {
      fetchPreviews();
    }
  }, [text]);

  const textWithLinks = text.split(/\s/).map((word, index) => {
    const isUrl = word.startsWith('http://') || word.startsWith('https://');
    return isUrl ? (
      <a key={index} href={word} target="_blank" rel="noopener noreferrer">{word}</a>
    ) : (
      <span key={index}> {word} </span>
    );
  });

  return (
    <div>
      <p>{textWithLinks}</p>
      {previews.map((preview, i) => (
        <div
          key={i}
          style={{
            border: '1px solid #ccc',
            borderRadius: 10,
            padding: 10,
            marginTop: 10,
            maxWidth: 400,
            boxShadow: '0 2px 6px rgba(0,0,0,0.1)'
          }}
        >
          <a href={preview.data.url} target="_blank" rel="noopener noreferrer" style={{ textDecoration: 'none', color: 'inherit' }}>
            {preview.data.image && (
              <img
                src={preview.data.image}
                alt="preview"
                style={{ width: '100%', borderRadius: 5, marginBottom: 10 }}
              />
            )}
            <h4 style={{ margin: '10px 0 5px 0' }}>{preview.data.title}</h4>
            <p style={{ fontSize: 14, color: '#444' }}>{preview.data.description}</p>
            <small style={{ color: '#888' }}>{preview.data.url}</small>
          </a>
        </div>
      ))}
    </div>
  );
};

export default LinkPreviewComponent;
