import React from 'react'
import { TrashBinOutline } from 'react-ionicons'
import { EyeOutline } from 'react-ionicons'
import { PrintOutline } from 'react-ionicons'
import { PencilOutline } from 'react-ionicons'


export function DeleteButton(props) {
  return (
    <button className="btn-circle bg-danger ml-2 text-light">
       <TrashBinOutline/>
    </button>
  )
}


export function PreviewButton(props) {
  return (
    <button className="btn-circle  bg-warning  ml-2 text-light">
       <EyeOutline />
    </button>
  )
}

 
export function EditButton(props) {
  return (
    <button className="btn-circle  bg-success  ml-2 text-light">
       <PencilOutline />
    </button>
  )
}
 

export function PrintButton(props) {
  return (
    <button className="btn-circle  bg-secondary  ml-2 text-light">
       <PrintOutline />
    </button>
  )
}


 