
 
export default  function  CalcAgeByBirthday(e){
     if (!e || typeof e !== "string") return "impossível de calcular";

 
    const birthDate = new Date(e);
    if (isNaN(birthDate.getTime())) return "impossível de calcular";

    const today = new Date();
    let age = today.getFullYear() - birthDate.getFullYear();

   
    const monthDiff = today.getMonth() - birthDate.getMonth();
    const dayDiff = today.getDate() - birthDate.getDate();
    if (monthDiff < 0 || (monthDiff === 0 && dayDiff < 0)) age--; 
    return age >= 0 ? age : "impossível de calcular";
}
  