import axios from "axios";
import Hoot from "./Hoot";
import RefreshList from "./RefreshList";
import { toast } from 'react-hot-toast';

async function SendSmsAndEmailFunc(contacts, message, title, files, emailAndSms) { 
    const emails = [];
    contacts.forEach(contact => { 
        emails.push(contact.email);
    });

    if (emailAndSms === 1) { // sms
        contacts.forEach(contact => { 
            sendSms(contact, message);
        });
    } else if (emailAndSms === 2) { // email
        sendEmail(contacts, message, title, files);
    } else if (emailAndSms === 3) { // both
        sendEmail(contacts, message, title,  files);
    }


    async function sendSms(contact, message) {
        setTimeout(() => { 
            try {
                axios.post(Hoot()+"eduallsendsmsmessage/post/", {
                    phone: contact.phone,
                    message: message,
                    usertype: contact.type,
                    contact: contact.id
                }).then(() => {
                    toast.success("Mensagem enviada com sucesso para " + contact.name + "( " + contact.phone + " )" + " !");
                    RefreshList(`.el-refresh-list`); 
                }).catch((error) => { 
                    const msg = error.response?.data?.msg;
                    toast.error(msg ? msg : "Lamentamos mas não foi  possivel enviar a mensagem para " + contact.name + "( " + contact.phone + " )" + " !");
                });
            } catch (error) { 
                const msg = error.response?.data?.msg;
                toast.error(msg ? msg : "Lamentamos mas não foi  possivel enviar a mensagem para " + contact.name + "( " + contact.phone + " )" + " !");
            }
    }, 200) 
}

async function sendEmail(mails, message, title, files) { 
    try {
       
        await axios.post(
            Hoot()+"eduallsendemailmessage/post/", 
            {Message:message.replace(/\n/g, '<br>'), Title:title, Emails:JSON.stringify(mails)}, 
            {headers:{"Content-Type": "application/json"}
          }).then(() => {
                toast.success("E-mails enviados com sucesso!");
                RefreshList(".el-refresh-list");  
            })
            .catch((error) => { 
                console.clear();
                console.log(error);

                const msg = error.response?.data?.msg;
                toast.error(msg ? msg : "Lamentamos, mas não foi possível enviar alguns dos e-mails!");
            });
    } catch (error) { 
         console.clear();
                console.log(error);
        toast.error("Ocorreu um erro inesperado ao enviar os e-mails!");
    }
}


}

export default SendSmsAndEmailFunc
