import React, { useEffect, useState } from 'react';
import styled from "styled-components";
import { Avatar } from '@mui/material'; 
import CommentReply from './CommentsComponents/CommentReply';
import CommentReactions from './CommentsComponents/CommentReactions';
import CommentAnswer from './CommentsComponents/CommentAnswer';
import ImageLazyLoading from './ImageLazyLoading';
import CommentsToggle from './CommentsToggle';
import axios from 'axios';
import Hoot from './Hoot';
import socketIO from 'socket.io-client';
import TimeAgo from "javascript-time-ago";
import pt from "javascript-time-ago/locale/pt.json";
import ReactTimeAgo from 'react-time-ago'  
const socket = socketIO(Hoot(), {withCredentials: true});

function CommentsArea({id, type, total}){ 
    const [load, setLoaded] = useState(false); 
    const [CommentsData , SetCommentsData] = useState([]);

 
   useEffect(() => {  
    socket.on('connect', () => { 
        console.log('Connected to server with id number',  socket.id);
   });
  }, []);

  
    async function loadData(){
        if(id !== null){
          try {
            setLoaded(false);  
            const response = await axios.get(Hoot()+"eduallgetCommentsDatabyidandtype/"+id+","+type); 
            SetCommentsData(response.data);
            //total(response.data.length);   
            setLoaded(true);  
          } catch (error) {
            setLoaded(false);  
          }
        } 
    }
  
  const GetRealTimeData =  (data)=>{ 
    console.clear();
    console.log(data, id);
    if(data !== null && data !== undefined){
      if((data.ed_comment_contentID*1 === id) && (data.ed_comment_contentType*1 === type)){ 
        if(data !== null & data !== undefined){
          SetCommentsData([...CommentsData, data]);
          setTimeout(() => { 
            CommentsToggle();
            //total(CommentsData.length);  
          }, 1000);
        };
      } 
    }
  } 
    
  
  useEffect(() => { 
    socket.on('eduall_response_content_comments', (data) => GetRealTimeData(data.data, data.user)); 
  }, [socket, CommentsData]);
  
  
  useEffect(()=>{
    loadData(); 
    setTimeout(() => {
        CommentsToggle();
    }, 1500);
  },[id, type]);



  return (
    <Container>
     <div className="comments-area">
        {CommentsData.map((item, index)=>{
            return(
                <li key={index+1} className="comment-box-area main-comment d-flex">
                     <div className="ed-flex  ed-ln">
                       <Avatar className='df' src={Hoot()+item.ed_user_account_picture} sx={{width:40,height:40}}  />
                      <div className="line"></div>
                    </div>
                    <div className="ed-block"> 
                    <div className="comment-box">
                        <div className="flex">
                  
                        <div className="ed-block">
                        <div className="ed-space">
                            <div className="name">{item.ed_user_account_name}</div>
                            <div className="time">
                              {(item.ed_comment_registerDate !== null && item.ed_comment_registerDate !== undefined ) ? 
                             <ReactTimeAgo date={item.ed_comment_registerDate} locale="pt-PT"/> : ""} 
                            </div>
                        </div>
                       <div className="content">
                       <div className="text-box">{item.ed_comment_text}</div>
                       {item.ed_comment_image !== "" ?
                          <div className="image">
                             <ImageLazyLoading source={Hoot()+item.ed_comment_image} />
                         </div>
                       : <></>}
                       </div>
                        <div className="ed-flex toggle-container">
                            <CommentReactions type={1} url="eduall_send_content_commentrepliesIo" total data id={item.ed_comment_id*1} socket={socket}  />  
                        </div>
                        </div>
                        <div className="toggle-reaction">
                            
                        </div>
                        </div>
                    
                    </div> 
                        <CommentReply socket={socket} id={item.ed_comment_id*1} />  
                   </div>
                </li>
            )
        })}
  </div>
</Container>
  )
}




const Container = styled.div` 
    .comment-box-area{ 
        margin:15px 0px; 
        padding:0px;
        list-style:none; 

        .time{
          margin-left:10px;
        }

        .show-answers{ 
            color:var(--ed-grey-text) !important; 
            font-size:15px !important;

              svg{
                  width:20px;
                  height:20px;
                  fill:var(--ed-grey-text) !important;
                  color:var(--ed-grey-text) !important; 
              }
        }

        .ed-ln{
            flex-direction:column;

             .line{
                  width:1px;
                  min-height:50px;
                  height:100%;
                  background:var(--ed-silver);
             }
        }

        .form-area {
            border-radius:30px;
            border:none;
            background:var(--ed-background-color);
            padding:0px 10px;
            max-width:500px !important;
            min-width:250px;

            .react-input-emoji{
                width:100% !important;
                min-width:150px;
                border-radius:30px;
                border:none !important;
                background:var(--ed-background-color) !important; 
            }

           .react-input-emoji--input{
               width:100% !important;
                min-width:150px;
                border-radius:30px;
                border:none !important;
                background:var(--ed-background-color) !important;
                padding:4px 10px !important; 
                font-size:15px !important;
           }

           .react-input-emoji--input,
           .react-input-emoji--placeholder{
               font-family:var(--ed-font-1) !important;
               color:var(--ed-dark);
               font-size:15px !important;
           }

           .react-input-emoji--container{
               border:none !important;
              background:var(--ed-background-color) !important;
           }

        svg{
            width:20px;
            height:20px;
            margin:0px 3px !important;
            fill:var(--ed-grey-text) !important;
            color:var(--ed-grey-text) !important; 
            cursor: pointer;
        }

        .gif-toggle{
            position: relative;
         }
 
        
        }
    

 


        .comment-box{ 
             width:max-content;
             margin:10px 0px; 


             .content{
                 .image{
                    margin:10px 0px;
                    max-width:350px;

                      img{
                           max-width:350px;
                           max-height:400px;
                           border-radius:10px;
                      }
                 }
             }


             .sp{
                  min-width:40px;
             }

             .comment-asnwer-input{
                display:flex;
                align-items:center;

                  span{
                     font-size:15px !important;
                     color:var(--ed-grey-text);
                  }
             }

             .flex{
                 display:flex;
                  .ed-block{
                    margin-left:10px;
                    position:relative;


                    .name{
                        font-size:16px;
                        font-weight:600;
                    }

                    .time{
                        font-size:15px !important;
                        color:var(--ed-grey-text);
                    }


                    .like-comment{ 
                        font-size:15px !important;
                        color:var(--ed-grey-text);
                        position:relative;
                     }

 


                    .reactions-area{   
                        background:var(--ed-white);
                        padding:8px 10px;
                        border-radius:30px; 
                        width:max-content;
                        box-shadow:var(--ed-shadow-1) !important;

 
                          .userrt{ 
                              position:relative;
                              margin-left:-2px;

                              .MuiAvatar-root{ 
                                  box-shadow:var(--ed-shadow-df) !important;
                              }

                                .reaction-icon{
                                    position:absolute;
                                    bottom:-8px;
                                    right:-4px;
                                    z-index:1000;
                                    font-size:14px;
                                    color:red !important;
                                }
                          }
                       }


                    
                   .text-box{
                        background:var(--ed-background-color);
                        max-width:700px;
                        width:max-content;
                        padding:10px;
                        border-radius:10px;
                        margin:8px 0px; 
                        font-size:15px !important;
                     }
                  }
             }
        }
        
        
         .comment-reply{
              padding-left:10px;
              padding-top:10px; 
              display:none;

               .ed-ln{
                 .line{
                    position:relative;
                    background:var(--ed-silver);
                    max-height:90% !important;
                    height:90% !important;
                    
                     &::after{
                        position:absolute;
                        bottom:0px;
                        left:-50px;
                        content:"";
                        width:50px;
                        height:1px;
                        background:var(--ed-silver);
                     }
                  }  
               }


               .comment-sub-reply{
                   padding-left:10px; 
                   padding-top:10px;
                   display:none;

                   .ed-ln{
                    .line{ 
                        max-height:38% !important;
                        height:38% !important;
                       
                        &::after{
                           background:var(--ed-silver);
                        }
                     }  
                  }
               }
          }

       


    } 

    .comment-sub-reply.show, 
    .comment-reply.show{
        display:block !important;
    }

`;

export default CommentsArea