import React, { useState } from "react";
import { Modal, Form, Table, Button } from "react-bootstrap";
import { Avatar, Checkbox } from "@mui/material";
import { Save, AddCircleOutline } from "@mui/icons-material";
import axios from "axios";
import { toast } from "react-hot-toast";
import DraggableModal from "../../../General/components/DraggableModal";
import Hoot from "../../../General/components/Hoot";
import { ClassDataOptions } from "../../../General/components/InstituteData";
import SaveButton from "../elements/SaveButton";
import UserOptionDropDown from "../elements/UserOptionDropDown";
import { ModalAnimationClose, ModalAnimationShow } from "../../../General/components/ModalAnimations";
import RefreshList from "../../../General/components/RefreshList";

function BulkStudentUserAccountModal() {
  const [show, setShow] = useState(false);
  const [classId, setClassId] = useState("");
  const [students, setStudents] = useState([]);
  const [selected, setSelected] = useState({});
  const [loading, setLoading] = useState(false);
  const [registerStatus, setRegisterStatus] = useState(null);
  const [showBox, SetShowBox] = useState(false);
  const [searchText, setSearchText] = useState("");

  // ---- Modal control ----
  const handleClose = () => {
    SetShowBox(false);
    setTimeout(() => setShow(false), 1200);
  };

  const handleShow = () => {
    SetShowBox(true);
    setShow(true);
  };

  // ---- API call: Get students by class ----
  const getStudents = async (classId) => {
    try {
      setLoading(true);
      const res = await axios.get(Hoot() + "eduallgetstudentsbyclass/" + classId);
      setStudents(res.data);

      const defaultSelected = {};
      res.data.forEach((st) => (defaultSelected[st.ed_student_id] = true));
      setSelected(defaultSelected);

      setLoading(false);
    } catch (err) {
      toast.error("Erro ao buscar alunos da turma!");
      setLoading(false);
    }
  };

  // ---- Select/deselect single student ----
  const handleSelect = (id) => {
    setSelected({ ...selected, [id]: !selected[id] });
  };

  // ---- Select/deselect all ----
  const handleSelectAll = (checked) => {
    const newSelection = {};
    students.forEach((st) => {
      newSelection[st.ed_student_id] = checked;
    });
    setSelected(newSelection);
  };

  // ---- Submit form ----
  const handleSubmit = async (e) => {
    e.preventDefault();
    const selectedStudents = students.filter((st) => selected[st.ed_student_id]);

    if (selectedStudents.length === 0) {
      toast.error("Selecione pelo menos um estudante!");
      return;
    }

    setRegisterStatus(0);
    try {
      const res = await axios.post(Hoot() + "eduallbulkstudentaccounts/post", {
        class_id: classId,
        students: selectedStudents,
        search_text: searchText,  
      });
      toast.success(res.data.msg);
      setRegisterStatus(2);
     RefreshList(`.el-refresh-list`); 
    } catch (err) {
      toast.error(err.response?.data?.msg || "Erro ao criar contas!");
      setRegisterStatus(1);
    }
  };

  // ---- Filtra estudantes pelo texto de pesquisa ----
  const filteredStudents = students.filter((st) =>
    st.ed_student_name.toLowerCase().includes(searchText.toLowerCase()) ||
    st.ed_student_code?.toString().includes(searchText)
  );

  return (
    <>
      <button className="btn btn-main bg-main" onClick={handleShow}>
        <AddCircleOutline /> Criar contas em massa
      </button>

      <Modal
        className={showBox ? ModalAnimationShow() : ModalAnimationClose()}
        centered
        size="lg"
        dialogAs={DraggableModal}
        show={show}
        onHide={handleClose}
      >
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>Criar contas de estudante em massa</h5>
            </div>
          </Modal.Title>
        </Modal.Header>

        <Form onSubmit={handleSubmit}>
          <Modal.Body>
            <div className="scrollLimit">
              {/* ---- Select Class ---- */}
              <Form.Group className="mb-3">
                <Form.Label>
                  Turma <span className="text-danger">*</span>
                </Form.Label>
                <Form.Select   value={classId}
                  onChange={(e) => {
                    setClassId(e.target.value);
                    getStudents(e.target.value);
                  }}
                > 
                  <ClassDataOptions />
                </Form.Select>
              </Form.Group>

              {loading && <p>Carregando estudantes...</p>}

              {!loading && students.length > 0 && (
                <>

                  {/* ---- Caixa de pesquisa abaixo da tabela ---- */}
                  <Form.Group className="mt-3 mb-2">
                    <Form.Label>Pesquisar </Form.Label>
                    <Form.Control
                      type="text"
                      placeholder="Digite ou cole texto aqui para pesquisa..."
                      value={searchText}
                      onChange={(e) => setSearchText(e.target.value)}
                    />
                  </Form.Group>
                  {/* ---- Tabela de alunos ---- */}
                  <Table bordered hover striped>
                    <thead>
                      <tr>
                        <th>
                          <Checkbox
                            checked={
                              filteredStudents.length > 0 &&
                              filteredStudents.every(
                                (st) => selected[st.ed_student_id]
                              )
                            }
                            indeterminate={
                              filteredStudents.some(
                                (st) => selected[st.ed_student_id]
                              ) &&
                              !filteredStudents.every(
                                (st) => selected[st.ed_student_id]
                              )
                            }
                            onChange={(e) => handleSelectAll(e.target.checked)}
                          />
                        </th>
                        <th>Foto</th>
                        <th>Nome</th>
                        <th>Gênero</th>
                        <th>Turma</th>
                      </tr>
                    </thead>
                    <tbody>
                      {filteredStudents.map((st, i) => (
                        <tr key={i}>
                          <td>
                            <Checkbox
                              checked={selected[st.ed_student_id] || false}
                              onChange={() => handleSelect(st.ed_student_id)}
                            />
                          </td>
                          <td>
                            <Avatar
                              className="df"
                              src={Hoot() + st.ed_student_picture}
                              alt={st.ed_student_name}
                              sx={{ width: 40, height: 40 }}
                            />
                          </td>
                          <td>
                            <div className="ed-block">
                              <div>{st.ed_student_name}</div>
                              <div>
                                <small className="grey-text">
                                  #{st.ed_student_code}
                                </small>
                              </div>
                            </div>
                          </td>
                          <td>
                            {st.ed_student_gender?.toLowerCase() === "male" ||
                            st.ed_student_gender?.toLowerCase() === "masculino" ? (
                              <span className="badge bg-success">Masculino</span>
                            ) : (
                              <span className="badge bg-warning text-dark">
                                Feminino
                              </span>
                            )}
                          </td>
                          <td>{st.ed_class_title}</td>
                        </tr>
                      ))}
                    </tbody>
                  </Table>
 
                </>
              )}
            </div>
          </Modal.Body>

          <Modal.Footer> 
            <SaveButton icon={<Save />} title={"Criar Contas"} status={registerStatus} />
          </Modal.Footer>
        </Form>
      </Modal>
    </>
  );
}

export default BulkStudentUserAccountModal;
