import React, { useState, useEffect } from 'react'
import { Avatar } from '@mui/material';
import { Link } from 'react-router-dom';
import Table from './Table';
import axios from 'axios';
import { BallotOutlined, Delete, Description, Edit, PreviewOutlined, Refresh, SummarizeOutlined } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import NewProductModal from '../modal/NewProductModal';
import DeleteModal from '../elements/DeleteModal';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import styled from 'styled-components';
import ImageLazyLoading from '../../../General/components/ImageLazyLoading';
import ReduceTextLength from '../../../General/components/ReduceTextLength';

const TABLEURL = Hoot() + "eduallproductsapi/get/";



const columns = [
  {
    field: 'index',
    headerName: 'Nº',
    resizable: true,
    width: 60
  },
  {
    field: 'name',
    headerName: 'Produto',
    resizable: true,
    width: 300,
    cellRenderer: (props) => {
      return <div className='ed-flex'>
        <Avatar variant="rounded" className='df mt-1' alt={props.data.name} sx={{ width: 40, height: 40 }} src={props.data.picture} />
        <span className='ml-2'>{props.data.name}</span>
      </div>
    }
  },
  {
    field: 'provider',
    headerName: 'Fornecedor',
    resizable: true,
  },
  {
    field: 'category',
    headerName: 'Categoria',
    resizable: true,
    width: 200
  },
  {
    field: 'aquriredvalue',
    headerName: 'Valor de compra',
    resizable: true,
  },
  {
    field: 'salesvalue',
    headerName: 'Valor de venda',
    resizable: true,
  },
  {
    field: 'stockamount',
    headerName: 'Quantidade no stock',
    resizable: true,
    cellRenderer: (props) => {
      return <div className="ed-flex">{getStockIndicator(props.data.stockamount)}  {props.data.stockamount}  items disponiveis </div>;
    }
  }, 
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true,
    cellRenderer: (props) => {
      return <div className="ed-flex">
        <NewProductModal title='Atualizar ' update='true' get={Hoot() + `eduallsingleproductapi/get/${props.data.id}`}
          url={Hoot() + `eduallproductupdate/update/${props.data.id}`} toggle_btn={
            <button class_code={props.data.id} className="btn-circle bg-success text-light">
              <Edit />
            </button>
          } />
        <DeleteModal title='produto' url={Hoot() + `eduallproductdelete/delete/${props.data.id}`}
          message='Produto deletado com sucesso' toggle_btn={
            <button class_code={props.data.id} className="btn-circle bg-danger ml-2 text-light">
              <Delete />
            </button>
          } />
      </div>;
    }
  }
];


const getStockIndicator = (stockAmount) => {
  if (stockAmount === 0) {
    return <div className="dot mr-1 dot-stock bg-danger outOfStock"></div>;
  } else if (stockAmount < 15) {
    return <div className="dot mr-1 dot-stock  bg-warning mediumStock"></div>;
  } else {
    return <div className="dot mr-1 dot-stock   bg-green highStock"></div>;
  }
};


function ProductsTable() {
  const [StockData, SetStockData] = useState({ highStock: 0, mediumStock: 0, outOfStock: 0 });
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [ToggleView, SetToggleView] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  const categorizeStock = (products) => {
    return products.reduce((acc, product) => {
      if (product.stockamount === 0) {
        acc.outOfStock++;
      } else if (product.stockamount < 15) {
        acc.mediumStock++;
      } else {
        acc.highStock++;
      }
      return acc;
    }, { highStock: 0, mediumStock: 0, outOfStock: 0 });
  };


  async function loadData() {
    try {
      setLoaded(false);
      setLoadStatus(0)
      const response = await axios.get(TABLEURL);
      const rows = [];

      response.data.map((item, index) => {
        rows.push({
          index: index + 1,
          id: item.ed_product_id,
          category: item.ed_product_category_name,
          provider: item.ed_provider_title,
          aquriredvalue: item.ed_product_purchase_price,
          salesvalue: item.ed_product_sale_price + " " + item.ed_coin_code,
          stockamount: item.ed_product_stock_amount,
          totalsales: item.ed_product_purchase_amount,
          picture: Hoot() + item.ed_product_picture,
          name: item.ed_product_name
        });
      });


      SetStockData(categorizeStock(rows))

      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2)
    } catch (error) {
      console.clear()
      console.log(error.response.data);
      setLoaded(true);
      setLoadStatus(1);
    }
  }

  useEffect(() => {
    loadData();
  }, []);





  if (load) {
    return (
      <div>
        <div className="d-none"><RefreshButton action={loadData} status={LoadStatus} /></div>
        <Container>
          <div className="box mt-4">
            <div className="ed-space">
              <div className="ed-flex">
                <div className="ed-flex mr-2"><div className="dot-stock dot bg-green mr-1"></div><strong>Stock Alto </strong>({StockData.highStock})</div>
                <div className="ed-flex mr-2"><div className="dot-stock dot bg-warning mr-1"></div><strong>Stock médio </strong>({StockData.mediumStock})</div>
                <div className="ed-flex mr-2"><div className="dot-stock dot bg-danger mr-1"></div><strong>Fora de stock </strong>({StockData.outOfStock})</div>
              </div> 
              <div className="ed-flex">
                <button onClick={()=>SetToggleView(ToggleView === false ? true : false)} className='btn btn-icon bg-green-light mr-2'>
                     {ToggleView === false ?  <BallotOutlined /> :  <SummarizeOutlined />} 
                </button>
                <NewProductModal />
              </div> 
            </div>
          </div>
          <section>
          {ToggleView === false ? 
            <aside>
            <TableGrid
              TableHead={columns}
              TableBody={data}
              TableTitle='Lista dos produtos'
              TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
            />
          </aside> 
          :  
          <div className="box">
          <aside className='ed-wrap products-grid col'>
            {data.map((item, index)=>(
              <article>
                <div className="mb-2">
                  <ImageLazyLoading height={200} source={item.picture} />
                </div>
                <strong className="grey-text mt-2 mb-2 ed-flex">preço de venda : <div className="ml-1">{item.salesvalue}</div></strong>
                <div className="pname">
                  <h5 className="product-name mb-2"><ReduceTextLength text={item.name} length={45} /></h5>
                </div>
                <div className="ed-flex mt-2">
                  <NewProductModal title='Atualizar ' update='true' get={Hoot() + `eduallsingleproductapi/get/${item.id}`}
                    url={Hoot() + `eduallproductupdate/update/${item.id}`} toggle_btn={
                      <button className="btn-circle bg-success text-light">
                          <Edit />
                      </button>
                    } />
                  <DeleteModal title='produto' url={Hoot() + `eduallproductdelete/delete/${item.id}`}
                    message='Produto deletado com sucesso' toggle_btn={
                      <button class_code={item.id} className="btn-circle bg-danger ml-2 text-light">
                        <Delete />
                      </button>
                    }/>
                </div>
              </article>
            ))}
          </aside>
          </div>

          }  
          </section>
        </Container>
      </div>
    )
  } else {
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista dos produtos'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    )
  }
}

export default ProductsTable

const Container = styled.div`
    .box-stock{ } 


    .products-grid{ 
       width:100%;
       gap:15px;
       
       article{ 
          width:24%;
          border:1px solid var(--ed-silver-light);
          height:480px;
          padding:10px;
          border-radius:6px;

          
          img{ 
            height:300px;
            width:100%;
            border-radius:6px;
          } 
       } 
     } 

    .pname{ 
      height:70px;
      margin-top:10px;
 

       h5{ 
          font-size:17px;
          line-height:30px;
       } 
    }


     .box{ 
        width:100%; 
        border-radius:6px;
        margin-bottom:20px;  
        padding:20px; 
        background:var(--ed-white);  
        box-shadow:var(--ed-shadow-df); 
     } 

      .dot-stock{ 
        width:17px;
        min-width:17px;
        height:17px;
        border-radius:100%;
         box-shadow:var(--ed-shadow-df); 
         border:2px solid var(--ed-white);
      } 
 
 `;