import React, {useState, useEffect} from 'react'
import axios from 'axios'
import { Delete, Description, Edit , PreviewOutlined, Refresh } from '@mui/icons-material';
import Table from './Table';
import Hoot from '../../../General/components/Hoot';
import NewClassRoomModal from '../modal/NewClassRoomModal';
import DeleteModal from '../elements/DeleteModal';
import BorrowBookModal from '../modal/BorrowBookModal';
import { Badge, Dropdown } from 'react-bootstrap';
import { GetsingleBookData, GetsingleBookPicture, GetsingleBookTitle, GetStudentName, GetStudentPicture } from '../../../General/components/InstituteData';
import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import { Avatar, AvatarGroup } from '@mui/material';
import { OverlayTrigger, Tooltip } from 'react-bootstrap';

const moment = require("moment");


const withTooltip = (button, tooltipText, placement = 'top') => {
  return (
    <OverlayTrigger
      placement={placement}
      overlay={<Tooltip>{tooltipText}</Tooltip>}
    >
      <span className="d-inline-block">{button}</span>
    </OverlayTrigger>
  );
}; 
 
 

require("moment/locale/pt");
moment.locale("pt");

const TABLEURL = Hoot()+"edualllibraryborrowedbooks/get";


 
const columns = [
  { 
    field: 'index',
    headerName: 'Nº',
    width: 90,  
    resizable: true,
  },
  
  { 
    field: 'book',
    headerName: 'Livros emprestados',  
    resizable: true,
    width: 350,   
    cellRenderer: (props) => {
      const books = (props.data.borrowed_books || []).map(book => ({
        ...book,
        picture: Hoot() + book.picture
      })); 
      return (
        <>
          <div className='ed-flex'>
             <AvatarGroup max={4} spacing="medium">
            {books.map((book, index) => (
              <>
              {withTooltip( 
                <Avatar
                  key={index} 
                  variant='rounded'
                  src={book.picture}
                  data-bs-toggle="tooltip"
                  title={book.title}
                  style={{ width: 40, height: 40 }}
              />, book.title)}
              </>
              
            ))}
          </AvatarGroup>
            <span className='ml-1'>{`Livros emprestados (${books.length})`}</span>
          </div> 
        </>
      );
    }
  },
  { 
    field: 'studentname',
    headerName: 'Nome do estudante',  
    resizable: true,
    width: 300,   
    cellRenderer: (props) => {
      return (
        <div className='ed-flex'>
          <Avatar  className='df'  alt={props.data.studentname}  
           src={props.data.studentpicture !== "" ? Hoot()+props.data.studentpicture : ""}  />
          <span className='ml-2'>{props.data.studentname}</span>
        </div>
      );
    }  
  },
  { 
    field: 'date',
    headerName: 'Data de solicitação & Devolução',  
    resizable: true,
    width: 400,    
    cellRenderer: (props) => {
      return (
        <div>{props.data.date}</div>
      );
    }
  },   
  { 
    field: 'status',
    headerName: 'Situação',  
    resizable: true,
    width: 170,   
    cellRenderer: (props) => {
      return (
        <>
          {props.data.status === 0 ? 
            <Badge bg='danger' className='col'>Não retornado</Badge> : 
            <Badge className='col' bg='info'>Retornado</Badge>
          }
        </>
      );
    }  
  },       
  {
    field: 'action',
    headerName: 'Ação',  
    resizable: true,
    cellRenderer: (props) => { 
      return (
        <div className="ed-flex"> 
          <BorrowBookModal 
            title='Atualizar ' 
            update='true' 
            get={Hoot() + `eduallsinglelibraryborrowedbook/get/${props.data.id}`}  
            url={Hoot() + `edualllibraryborrowedbookupdate/update/${props.data.id}`}  
            toggle_btn={  
              <button  className="btn-circle bg-success text-light">
                <Edit/>
              </button>  
            } 
          /> 
          <DeleteModal  
           title=' este registro de emprestimo de livro' 
            url={Hoot() + `edualllibraryborrowedbookdelete/delete/${props.data.id}`} 
            message='emprestimo deletado com sucesso' 
            toggle_btn={
              <button className="btn-circle bg-danger ml-2 text-light">
                <Delete/>
              </button>
            }
          />
        </div>  
      );
    }
  } 
];
 




function BorrowBooksTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData() {
    setLoaded(false); 
    try {
      setLoadStatus(0); 
      const response = await axios.get(TABLEURL);  
      const rows = response.data.map((item, index) => {
        return {
          index: index + 1,
          id: item.id,   
          studentname: item.studentname, 
          studentpicture: item.studentpicture,
          studentid: item.studentid,
          date: `${moment(item.date).format("D [de] MMMM [de] YYYY")} / ${moment(item.devolutionDate).format("D [de] MMMM [de] YYYY")}`,
          book: item.book,
          borrowed_books: item.borrowed_books,   
          status: item.status, 
          action: ''
        };  
      });

      console.clear()
      console.log(response.data);
      setData(rows);
      setTimeout(() => {
        setLoaded(true); 
      }, 200);
      setLoadStatus(2); 
    } catch (error) {
      setLoaded(true);
      setLoadStatus(1);  
    }
  }

  useEffect(() => {
    loadData(); 
  }, []);

  if (load) {
    return (
      <div>
        <TableGrid
          TableHead={columns}
          TableBody={data} 
          TableTitle='Livros emprestados' 
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    );
  } else {
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={[]} 
          TableTitle='Livros emprestados'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    );
  } 
}

export default BorrowBooksTable;
 
 