import React, {useState, useEffect} from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import {Modal, Form, Button} from 'react-bootstrap'
import { Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal'; 
import Hoot from '../../../General/components/Hoot'; 
import UserOptionDropDown from '../elements/UserOptionDropDown'; 
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import { Link } from 'react-router-dom'; 
import ReplaceWord from '../../../General/components/ReplaceWord';
import { Tooltip } from '@mui/material';
import { Avatar } from '@mui/material';

 
function PopEmailMessageDetails(props) {
    const [show, setShow] = useState(false); 
   
    const [showBox, SetshowBox]  = useState(false);
    const handleClose = () => {
      SetshowBox(false);
      setTimeout(() => {
        setShow(false);
      }, 1000);
    } 
  
    const handleShow = () => {
          SetshowBox(true);
          setShow(true);  
    };
  
    
  
    return (
      <>
            <div className='col-lg-12' onClick={handleShow}>
              {
                props.toggle_btn ? props.toggle_btn :  <button className='btn btn-main bg-main'><AddCircleOutlineIcon/> Criar cartão de estudante </button> 
              }
            </div>
            <Modal size='lg' centered  className={showBox ? ModalAnimationShow() : ModalAnimationClose()}  dialogAs={DraggableModal}  show={show} onHide={handleClose}>
              <Modal.Header closeButton>
                <Modal.Title>
                    <div className="ed-wrap align-center">
                      <UserOptionDropDown />
                      <h5>Detalhes da mensagem  </h5>
                  </div>   
                </Modal.Title>
              </Modal.Header>  
              <Modal.Body className='scrollLimit'> 

                <h4 className="title mb-2"> <strong>Assunto : </strong><span className="text-main">{props.data.subject}</span></h4>
                <Form.Group className="mb-3">
                   <textarea rows={6} readOnly value={props.data.message} className="form-control grey-text"></textarea>
                </Form.Group>    
                <div className="mt-2">
                    <p className='text-main'>mensagem enviada para ({props.data.contacts.length} pessoas)</p>
                </div>  
                <div className="mt-4">
                {props.data.contacts.map((contact, idx) => (
                   <li className="ed-flex mb-2">
                       <Tooltip key={idx} title={contact.contact_name || "Unknown"}>
                        <Avatar className='df' src={Hoot()+contact.contact_picture || "/default-avatar.png"}>
                            {!contact.contact_picture ? contact.contact_name?.charAt(0) : ""}
                        </Avatar>
                    </Tooltip>
                   <div className="ed-block ml-2">
                        <div> <strong>{contact.contact_name}</strong></div>
                        <div><small className='grey-text ed-wrap'>email de envio: <span className="text-green ml-1">{contact.contact_sent_email}</span> </small></div>
                   </div>
                   </li>
                ))}
                </div>
              </Modal.Body> 
            </Modal>
      </>
    )
}

export default PopEmailMessageDetails
