import React, { useEffect, useState, useRef } from 'react'
import { Form } from 'react-bootstrap'
import styled from 'styled-components'
import { Link } from 'react-router-dom';
import { Save, Delete, SummarizeOutlined, InfoOutlined, AddCircleOutline, RemoveCircleOutline } from '@mui/icons-material';
import BuildDataHistory from '../components/elements/BuildDataHistory';
import FileUpload from '../../General/components/FileUpload';
import { Avatar, Checkbox, FormControlLabel } from '@mui/material';
import { toast } from 'react-hot-toast';
import CRValue from '../../General/components/CRValue';
import ClearInputs from '../../General/components/ClearInputs';
import Hoot from '../../General/components/Hoot';
import axios from 'axios';
import { GetAcademiclevel_byclass, GetClassroom_byclass, GetClasstitle_byclass, GetCourse_byclass, GetInstituteCode, GetPeriod_byclass, StudentsArray } from '../../General/components/InstituteData';
import { MultiSelect } from 'react-multi-select-component';
import SelectSearch from 'react-select-search';
import ReplaceWord from '../../General/components/ReplaceWord';
import SaveButton from '../components/elements/SaveButton';
import StudentDetailsMenu from '../components/elements/StudentDetailsMenu';
import RandomCodeGenerator from '../../General/components/RandomCodeGenerator';
import NumberToPrice from '../../General/components/NumberToPrice';
import GenerateInvoiceCode from '../../General/components/GenerateInvoiceCode';

function Servicepayments() {
    document.title = 'Pagamento de serviços';
    const props = {};

    // 🔹 Inicializa o form com o método vazio
    const [form, setForm] = useState({
        service_payment_type: "",
    });
    const [errors, setErrors] = useState({});
    const [studentCode, setStudentCode] = useState(null);
    const [Docfile, setDocfile] = useState(false);
    const [Files, setFiles] = useState([]);
    const [PaymentType, setPaymentType] = useState(null);
    const [serviceCoin, setServiceCoin] = useState('Kz');
    const [StudentClass, setStudentClass] = useState('#');
    const [StudentName, setStudentName] = useState('#');
    const [StudentPicture, setStudentPicture] = useState('#');
    const [InvoiceValue, SetInvoiceValue] = useState(0);
    const [DeliveredValue, setDeliveredValue] = useState(0);
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [ServiceDiscount, SetServiceDiscount] = useState(0);

    const [Months, SetMonths] = useState(null);
    const ChildRef = useRef();

    const [allServices, setAllServices] = useState([]);
    const [selectedServices, setSelectedServices] = useState([]);
    const [amounts, setAmounts] = useState({});

    const FORMURL = [
        Hoot() + "eduallregisterservicepayment/post",
        Hoot() + "eduallsinglestudentapi/get/",
        Hoot() + "eduallservicesapi/get",
    ];

    const showBoxFile = () => setDocfile(!Docfile);
    const GetFiles = (e) => setFiles(e);

    const setField = (field, value) => {
        setForm({ ...form, [field]: value });
        if (!!errors[field]) setErrors({ ...errors, [field]: null });
    }

    const GetStudentCode = (e) => {
        setStudentCode(e);
        setField("service_payment_student_code", e);
    }

    const validateForm = () => {
        const { service_payment_type } = form;
        const NewErrors = {};

        if (!studentCode) NewErrors.service_payment_student_code = 'Selecione o estudante';
        if (!service_payment_type) NewErrors.service_payment_type = 'Selecione o método de pagamento';
        if (selectedServices.length === 0) NewErrors.service_payment_code = 'Selecione pelo menos um serviço';
        if (ServiceDiscount < 0 || ServiceDiscount >= 100) NewErrors.service_payment_discount = 'Desconto inválido (0-99)';
        if (PaymentType === 0 && (DeliveredValue - InvoiceValue < 0)) NewErrors.service_payment_value_delivered = 'Valor entregue insuficiente';
        return NewErrors;
    }

    // Carregar lista de serviços
    useEffect(() => {
        const loadServices = async () => {
            try {
                const res = await axios.get(FORMURL[2]);
                const options = (res.data || []).map((srv) => ({
                    label: srv.ed_service_title,
                    value: srv.ed_service_id,
                    price: Number(srv.ed_service_price) || 0,
                    coin: srv.ed_coin_code || 'Kz'
                }));
                setAllServices(options);
                if (options.length) setServiceCoin(options[0].coin || 'Kz');
            } catch {
                toast.error("Erro ao carregar serviços");
            }
        };
        loadServices();
    }, []);

    // Carregar dados do aluno
    useEffect(() => {
        (async () => {
            if (!studentCode) return;
            try {
                const response = await axios.get(FORMURL[1] + `${studentCode}`);
                if (response.data.length >= 1) {
                    setStudentName(response.data[0].ed_student_name);
                    setStudentClass(response.data[0].ed_student_class);
                    setStudentPicture(response.data[0].ed_student_picture);
                }
            } catch { }
        })();
    }, [studentCode]);

    // Recalcular total
    useEffect(() => {
        let total = 0;
        selectedServices.forEach(s => {
            const data = allServices.find(a => a.value === s.value);
            const qty = amounts[s.value] || 1;
            const price = data?.price || 0;
            total += price * qty;
        });
        const discounted = total - (total * (Number(ServiceDiscount) || 0) / 100);
        SetInvoiceValue(discounted);
    }, [selectedServices, amounts, ServiceDiscount, allServices]);


 
const FormSubmit = async (e) => {
  e.preventDefault();
  setRegisterStatus(0);

  const invoiceCode = await GenerateInvoiceCode();
  const formErrors = validateForm();

  if (Object.keys(formErrors).length > 0) {
    setErrors(formErrors);
    toast.error("Verifique os campos obrigatórios");
    setRegisterStatus(1);
    return;
  }

  if (!invoiceCode) {
    toast.error("Lamentamos, não foi possível gerar a fatura!");
    setRegisterStatus(1);
    return;
  }

  const CODE = RandomCodeGenerator(100);

  const services = selectedServices.map(s => {
    const info = allServices.find(a => a.value === s.value);
    return {
      code: s.value,
      amount: amounts[s.value] || 1,
      price: info?.price || 0,
      discount: Number(ServiceDiscount) || 0
    };
  });

  const payload = {
    service_payment_svcode: CODE,
    service_payment_student_code: studentCode,
    service_payment_type: form.service_payment_type,
    service_payment_bank: form.service_payment_bank,
    service_payment_place: form.service_payment_place,
    service_payment_bordeaux: form.service_payment_bordereux_number,
    service_payment_value_delivered: DeliveredValue,
    service_payment_exchange: 0,
    services,
  };

  const Update = () => {
    setForm({ service_payment_type: "" });
    ClearInputs();
    ChildRef.current?.ClearFiles();
    SetInvoiceValue(0);
    setRegisterStatus(2);
    setFiles([]);
    setErrors({});
    setSelectedServices([]);
    setAmounts({});
    setDeliveredValue(0);
    SetServiceDiscount(0);
    setPaymentType(null);
  };

  try {
    //  1. Submeter pagamento
    await axios.post(FORMURL[0], payload);

    //  2. Upload de ficheiros relacionados
    if (Files?.length && Files[0]?.length) {
      for (let i = 0; i < Files[0].length; i++) {
        const file = Files[0][i];
        const fileData = new FormData();

        fileData.append("file_name", file);
        fileData.append("file_code", CODE || "feepayment");
        fileData.append("file_size", file.size);
        fileData.append("file_type", file.type);
        fileData.append("file_use", "feepayment_register");
        fileData.append(
          "file_extension",
          (file.name?.split(".").pop() || "pdf").toLowerCase()
        );

        try {
          await axios.post(Hoot() + "eduallfilesregister/post/", fileData);
        } catch (err) {
          console.log("Erro ao enviar ficheiro:", err);
        }
      }
    }

    toast.success("Serviço(s) pago(s) com sucesso!");
    Update();
    
  } catch (error) {
    toast.error("Lamentamos, não foi possível concluir a operação!");
    console.clear();
    console.log(error?.response?.data || error);
    setRegisterStatus(1);
  }
};







    const handleInput = (e) => {
        switch (e.target.id) {
            case "service_payment_type":
                setPaymentType(e.target.value * 1);
                setField("service_payment_type", e.target.value);
                break;
            case "service_payment_discount":
                setField("service_payment_discount", e.target.value);
                SetServiceDiscount((e.target.value || 0) * 1);
                break;
            case "service_payment_value_delivered":
                setDeliveredValue(e.target.value * 1);
                setField("service_payment_value_delivered", e.target.value);
                break;
            default:
                setField(e.target.id, e.target.value);
        }
    }

    const changeAmount = (serviceId, delta) => {
        setAmounts(prev => {
            const current = prev[serviceId] || 1;
            const next = Math.max(1, current + delta);
            return { ...prev, [serviceId]: next };
        });
    };

    useEffect(() => {
        setAmounts(prev => {
            const next = { ...prev };
            selectedServices.forEach(s => {
                if (!next[s.value]) next[s.value] = 1;
            });
            Object.keys(next).forEach(id => {
                if (!selectedServices.find(s => String(s.value) === String(id))) {
                    delete next[id];
                }
            });
            return next;
        });
        if (selectedServices.length) {
            const first = allServices.find(a => a.value === selectedServices[0].value);
            if (first?.coin) setServiceCoin(first.coin);
        }
    }, [selectedServices, allServices]);

    return (
        <div>
          <div>
  <Form onSubmit={FormSubmit}>
    <div className="box-register">
      <div className="ed-space mb-4">
        <div>
          <Link className="btn bg-main" to="/paidservices">
            <SummarizeOutlined /> Serviços pagos
          </Link>
        </div>
        <div className="ed-flex">
          <button
            className="btn bg-danger"
            type="reset"
            id="clearForm"
            onClick={() => setForm({ service_payment_type: "" })}
          >
            <Delete /> Limpar
          </button>
          <SaveButton icon={<Save />} title={"Salvar"} status={RegisterStatus} />
        </div>
      </div>

      <div className="flex-wrapp">
        {studentCode !== null && (
          <Box className="boxItem" style={{ width: "400px" }}>
            <div className="ed-flex">
              <Link to="">
                <Avatar
                  alt={StudentName}
                  className="df"
                  src={StudentPicture !== "#" ? Hoot() + StudentPicture : ""}
                  sx={{ width: 106, height: 106 }}
                />
              </Link>
              <div className="d-block ml-2 description">
                <h3 className="name">
                  Nome :{" "}
                  <Link to="" className="text-main label-student-name">
                    {StudentName}
                  </Link>
                </h3>
                <h5>
                  Turma :{" "}
                  <Link to="" className="text-main label-student-class">
                    <GetClasstitle_byclass ID={StudentClass} />{" "}
                  </Link>
                </h5>
              </div>
            </div>
            <div className="ed-wrap mt-4   description">
              <h5 className='mr-2'>
                {ReplaceWord("Classe")} :{" "}
                <Link to="" className="text-main label-student-level">
                  <GetAcademiclevel_byclass ID={StudentClass} />
                </Link>{" "}
              </h5>
              <h5 className="mr-2">
                Sala :{" "}
                <Link to="" className="text-main label-student-classroom">
                  {<GetClassroom_byclass ID={StudentClass} />}
                </Link>
              </h5>
            </div>
            <div className="ed-wrap mt-2 description">
              <h5>
                Curso :{" "}
                <Link to="" className="text-main label-student-class">
                  <GetCourse_byclass ID={StudentClass} />
                </Link>
              </h5>
              <h5 className="mr-2">
                Periodo :{" "}
                <Link to="" className="text-main label-student-class">
                  <GetPeriod_byclass ID={StudentClass} />{" "}
                </Link>
              </h5>
            </div>
          </Box>
        )}

        <div className="pd-1 pd1"></div>
        <BoxContainer className="boxItem">
          <div className="ed-space mb-4">
            <div>
              <h2 className="title" style={{ marginBottom: "0px" }}>
                Dados do aluno
              </h2>
            </div>
            <BuildDataHistory />
          </div>

          {!props.student_code && (
            <Form.Group className="col-12 mt-4">
              <div className="ed-space">
                <div>
                  <Form.Label>
                    Nome do estudante <span className="text-danger ml-2">*</span>
                  </Form.Label>
                </div>
                <div className="ed-flex">
                  {studentCode !== null && (
                    <StudentDetailsMenu
                      student_id={studentCode}
                      toggle_btn={<div className="btn-pm-info"><InfoOutlined /></div>}
                    />
                  )}
                </div>
              </div>
              <div
                className={`select-search-item  ${
                  errors.feepayment_student_code ? "error" : ""
                }`}
              >
                <SelectSearch
                  onChange={(e) => GetStudentCode(e)}
                  value={studentCode}
                  options={StudentsArray()[0]}
                  search={true}
                  placeholder="Selecione um aluno"
                />
              </div>
              <small className="text-danger">
                {errors.feepayment_student_code}
              </small>
            </Form.Group>
          )}

          <Form.Group>
            <div className="ed-flex col-12 mt-4">
              <div className="block" style={{ width: "99%" }}>
                <Form.Label>Serviços</Form.Label>
                <MultiSelect
                  options={allServices}
                  value={selectedServices}
                  onChange={setSelectedServices}
                  labelledBy="Selecione serviços"
                />
                <small className="text-danger d-block mt-1">
                  {errors.service_payment_code}
                </small>

                {selectedServices.length > 0 && (
                  <div className="ed-flex ed-wrapp mt-3">
                    {selectedServices.map((s) => {
                      const qty = amounts[s.value] || 1;
                      const info = allServices.find((a) => a.value === s.value);
                      return (
                        <div key={s.value} className="badge-item-wrapper">
                          <span className="badge-item">
                            <span className="badge-title">{s.label}</span>
                            <span className="badge-qty">× {qty}</span>
                            <div className="badge-actions">
                              <RemoveCircleOutline
                                className="qty-btn"
                                onClick={() => changeAmount(s.value, -1)}
                              />
                              <AddCircleOutline
                                className="qty-btn"
                                onClick={() => changeAmount(s.value, +1)}
                              />
                            </div>
                          </span>
                          <div className="badge-subtext">
                            Preço unitário: {NumberToPrice(info?.price || 0)}{" "}
                            {info?.coin || serviceCoin}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                )}
              </div>
            </div>
          </Form.Group>
        </BoxContainer>
      </div>

      {/* 🔹 MÉTODO DE PAGAMENTO */}
      <div className="mt-4">
        <BoxContainer className="boxItem">
          <div className="ed-space mb-4">
            <div>
              <h2 className="title" style={{ marginBottom: "0px" }}>
                Método de pagamento
              </h2>
            </div>
          </div>
          <Form.Group>
            <div className="mt-4">
              <div className="block">
                <Form.Select
                  required
                  onChange={handleInput}
                  className={!!errors.service_payment_type && "is-invalid"}
                  value={form.service_payment_type ?? ""}
                  isInvalid={!!errors.service_payment_type}
                  id="service_payment_type"
                >
                  <option value="" disabled>
                    Selecionar método de pagamento
                  </option>
                  <option value="0">Dinheiro à mão</option>
                  <option value="1">Transferência</option>
                  <option value="2">Depósito</option>
                  <option value="3">TPA</option>
                </Form.Select>
                <Form.Control.Feedback type="invalid">
                  {errors.service_payment_type}
                </Form.Control.Feedback>
              </div>
            </div>
          </Form.Group>
        </BoxContainer>
      </div>

      {/* 🔹 DETALHES DE PAGAMENTO */}
      <div className="box-flex mt-4">
        <BoxContainer className="boxItem">
          <div className="ed-space mb-4">
            <div>
              <h2 className="title" style={{ marginBottom: "0px" }}>
                Detalhes de pagamento
              </h2>
            </div>
          </div>

          <div className="custom-box mt-2">
            <Form.Group>
              <div className="mt-2">
                <div className="block">
                  <Form.Label>Desconto (%)</Form.Label>
                  <Form.Control
                    onChange={handleInput}
                    type="number"
                    className={!!errors.service_payment_discount && "is-invalid"}
                    value={form.service_payment_discount || ""}
                    isInvalid={!!errors.service_payment_discount}
                    id="service_payment_discount"
                  />
                  <Form.Control.Feedback type="invalid">
                    {errors.service_payment_discount}
                  </Form.Control.Feedback>
                </div>

                <div
                  className={
                    PaymentType === 0 && PaymentType !== null
                      ? "block mt-4"
                      : "d-none"
                  }
                >
                  <Form.Label>Valor entregue</Form.Label>
                  <Form.Control
                    type="number"
                    className={!!errors.service_payment_value_delivered && "is-invalid"}
                    value={form.service_payment_value_delivered || ""}
                    onChange={handleInput}
                    isInvalid={!!errors.service_payment_value_delivered}
                    id="service_payment_value_delivered"
                  />
                  <Form.Control.Feedback type="invalid">
                    {errors.service_payment_value_delivered}
                  </Form.Control.Feedback>
                </div>

                <div className="block mt-4">
                  <Form.Label>Total Fatura</Form.Label>
                  <Form.Control
                    readOnly
                    type="text"
                    className="text-right text-danger"
                    value={NumberToPrice(InvoiceValue) + " " + serviceCoin}
                    id="service_payment_invoice"
                  />
                </div>
              </div>
            </Form.Group>
          </div>
        </BoxContainer>
      </div>

      {/* 🔹 ANEXAR COMPROVANTES */}
      <div className="ml-2">
        <FormControlLabel
          onChange={() => showBoxFile()}
          control={<Checkbox />}
          label="Anexar recibos de pagamento"
        />
      </div>

      <BoxContainer className={Docfile === true ? "boxItem" : "boxItem d-none"}>
        <h2 className="title">Carregar Recibo de pagamento</h2>
        <FileUpload
          input_name="feepayment_files"
          Icon="0"
          type_of_files="image/x-png,image/gif,image/jpeg,Docs/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document, application/pdf"
          extensions="pdf, docx, png, jpeg, jpg"
          Files={GetFiles}
          ref={ChildRef}
        />
      </BoxContainer>
      <br />
    </div>
  </Form>
</div>

        </div>
    )
}
const BoxContainer = styled.div`
  width: 100%;
  border-radius: 6px;
  margin: 10px 0;
  padding: 20px;
  min-height: 200px;
  background: var(--ed-white);
  box-shadow: var(--ed-shadow-df);

  .badge-item-wrapper {
    display: flex;
    flex-direction: column;
    align-items: center;
    margin: 8px;
  }

  .badge-subtext {
    font-size: 13px;
    color: #6c757d;
    margin-top: 4px;
    text-align: left;
  }

  .badge-item {
    display: flex;
    align-items: center;
    gap: 8px;
    background: #f4f6f8;
    color: #333;
    border-radius: 999px;
    padding: 6px 10px;
    margin: 2px;
    box-shadow: var(--ed-shadow-df);

    .badge-title {
      font-weight: 600;
      max-width: 240px;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .badge-qty {
      font-weight: 700;
    }

    .badge-actions {
      display: flex;
      align-items: center;
      gap: 4px;

      .qty-btn {
        cursor: pointer;
      }
    }
  }
`;

const Box = styled.div`
  width: auto;
  border-radius: 6px;
  padding: 20px;
  min-height: 200px;
  background: var(--ed-white);
  box-shadow: var(--ed-shadow-df);
  margin: 10px 0;
  min-width: 400px;

  .description {
    .name {
      font-size: 16px;
      margin-bottom: 12px;
      margin-top: 6px;
    }

    h5 {
      font-size: 16px;
    }
  }
`;

export default Servicepayments;
 