import React, {useState, useEffect} from 'react'
import Table from './Table'
import { AddCircleOutline, Delete, Description, Edit ,OpenInBrowser, Refresh } from '@mui/icons-material';
import { Link } from 'react-router-dom';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import styled from 'styled-components'
import NewTime from '../modal/NewTime';
import TableGrid from '../../../General/components/TableGrid';
import { AvatarGroup, Skeleton } from '@mui/material';
import { Alert, Avatar, Checkbox, FormControlLabel } from '@mui/material'; 
import ReactPaginate from 'react-paginate';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline'; 
import BallotOutlinedIcon from '@mui/icons-material/BallotOutlined';
import NewParentAccountModal from '../modal/NewParentAccountModal';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import NewStudentUserAccountModal from '../modal/NewStudentUserAccountModal';
import ReduceTextLength from '../../../General/components/ReduceTextLength';

const TABLEURL = Hoot()+'eduallgetuserparentsacccountsbyinstitute/get';
  
 


function UserParentsAccountsTable(props) {
    const [data, setData] = useState([]);
    const [load, setLoaded] = useState(false);
  
    const loadData = async()=>{
        setLoaded(false); 
        try {
            const response = await axios.get(TABLEURL);
            const rows = []; 
            console.clear() 

            
            const list =  [];
            for(let i = 0; i < response.data.length; i++){
                 let Item = response.data[i];
                 list.push({id:i, code:Item.ed_user_account_id,   data:Item});
            }
 

            let duplicates;
            let hashtable = {};

            for (var i = 0; i < list.length; i++) {  
                let key = ['code', 'data'].map(k => list[i][k]).join('|');
                hashtable[key] = hashtable[key] || [];
                hashtable[key].push(list[i]);
            }

            duplicates = Object.values(hashtable);


            for (let i = 0; i < duplicates.length; i++) {
                const element = duplicates[i];
                if(element.length >= 1){ 
                     let accounts  = [];
                     for(let e = 0; e < element.length; e++) {
                        accounts.push({
                            student_id:element[e].data.ed_student_id,
                            student_name:element[e].data.ed_student_name,
                            student_email:element[e].data.ed_student_email,
                            student_picture:Hoot()+element[e].data.ed_student_picture
                        });  
                     }
                     rows.push({
                       code:element[0].data.ed_user_account_id,
                       name:element[0].data.ed_user_account_name,
                       email: element[0].data.ed_user_account_email,
                       picture:Hoot()+element[0].data.ed_user_account_picture,
                       accounts:accounts
                    });
                }
                
            } 

            setData(rows);  
            setLoaded(true);  
        } catch (error) {
              console.clear()
              console.log(error)
            setLoaded(true);  
        }
    }
 



useEffect(()=>{
    loadData(); 
},[]);



let filterValue = props.FilterByName ? props.FilterByName : '';
  
const FilterData = (data)=>{ 
  return data.filter((item)=>
    item.name.toLowerCase().includes(filterValue) ||  
    item.email.toLowerCase().includes(filterValue)  
 ); 
}


  return (
  <div> 
    <div className="content"> 
    <button className="el-refresh-list d-none" onClick={()=>loadData()}>refresh</button>
           {load === true ?
             <div>
                <PaginatedItems itemsPerPage={12} filterValue  data={FilterData(data)} />
                <div className="ed-space">
                    <div className="count"></div>
                    <div className="pagination"></div>
                </div>
             </div>
           :
           <section className='ed-wrap mt-2'>
            {[1,2,3,4,5,6,7,8,9].map((item, index)=>{
                    return(
                        <Box key={index+1}>
                        <div className="ed-flex box-content mt-4">
                            <Avatar className='df'  sx={{width:90,height:90}} />
                            <div className="ed-block ml-2 col">
                                <h5> <Skeleton variant='rectangle' animation='wave' width='50%' height={10} /></h5>
                                <div className="mt-2"><Skeleton variant='rectangle' animation='wave' width='60%' height={10} /></div>
                            </div> 
                        </div>
                        <div className="mt-2 col">
                           <Skeleton variant='rectangle' animation='wave' width='50%' height={30} />
                        </div>
                    </Box>)
                })}
             </section>
           }
        
    </div>
</div>
)
}

 
function Items({currentItems}){
    return( 
      <Wrapper className='mt-4'>
       {currentItems &&
        currentItems.map((item)=>(
            <Box>
            <div className="ed-space">
            <div className="ed-flex   box-content"> 
                  <Avatar alt={item.name}  className='df'  src={item.picture}  sx={{ width: 90, height: 90 }}/> 
                  <div className="ed-block ml-2 col">
                      <h5>{item.name}</h5>
                      <small className="mt-2"><ReduceTextLength text={item.email} length={20}  /> </small>
                  </div> 
              </div>
              <div className="buttons">
              <div className="ed-flex">
                  <NewParentAccountModal get={Hoot()+"eduallgetuserchilds/get/"+item.code} update code={item.code}
                  toggle_btn={<EditButton />} /> 
              </div> 
              </div>
            </div>
              <ul className="mt-2"> 
                <AvatarGroup>
                    {item.accounts.map((pr, prIndex)=>{
                      return (<Avatar className='df' src={pr.student_picture} key={prIndex}  sx={{width:40,height:40}} />);
                   })} 
                  </AvatarGroup>
               </ul>
          </Box>
        ))
        }
      </Wrapper>
    )
  }
  
  
  function PaginatedItems({ itemsPerPage, data, filterValue}) {   
    const FilterData = (data)=>{  
          return data 
     }
  
    const [itemOffset, setItemOffset] = useState(0); 
    const endOffset = itemOffset + itemsPerPage;
    console.log(`Loading items from ${itemOffset} to ${endOffset}`);
    const currentItems = FilterData(data).slice(itemOffset, endOffset);
    const pageCount = Math.ceil( FilterData(data).length / itemsPerPage); 
    const handlePageClick = (event) => {
      const newOffset = (event.selected * itemsPerPage) % FilterData(data).length; 
      setItemOffset(newOffset);
    }; 
    return (
      <>
        <Items currentItems={currentItems} />
      <div className="ed-space mt-4">
        <div> 
            <Title>{FilterData(data).length} items encontrados na lista </Title>
         </div> 
        <div>
        <div className="paginate box">
          <ReactPaginate
              breakLabel="..."
              nextLabel=" > "
              onPageChange={handlePageClick}
              pageRangeDisplayed={5}
              pageCount={pageCount}
              previousLabel=" < "
              renderOnZeroPageCount={null}
            />
         </div>
        </div>
      </div>
      </>
    );
  }
  
  
  const Title = styled.h3`
      font-size:18px;
      margin:0px;
  `;


const Wrapper = styled.div`
     width:100%;
    display:flex;
    flex-wrap:wrap;
    gap:20px; 
`;

const Box = styled.div`
    flex: 0 0 calc((100% - 40px) / 3);
    min-width:300px;
    border-radius:6px;   
    padding:20px;
    min-height:120px;
    height:auto;
    background:var(--ed-white);  
    box-shadow:var(--ed-shadow-df); 
    position:relative; 
    display:block;
    margin-left:0px;


    h5{
      font-weight:600;
      font-size:18px;
    }

    small{
        font-size:16px;
       color:var(--ed-grey-text);
    }

    .buttons{
        position:absolute;
        top:10px;
        right:20px;
    }
`;

export default UserParentsAccountsTable