import React, { useState, useEffect } from 'react';
import { Spinner, Collapse } from 'react-bootstrap';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import { toast } from 'react-hot-toast';
import SendSmsAndEmailFunc from '../../../General/components/SendSmsAndEmailFunc';
import RefreshList from '../../../General/components/RefreshList';

function CreateTemporaryEduallAccountAlert({ email, userName, country, gender, expand }) {
    const [isValidEmail, setIsValidEmail] = useState(false);
    const [exists, setExists] = useState(null);
    const [loading, setLoading] = useState(false);
    const [openAccordion, setOpenAccordion] = useState(false);
    const [registerStatus, setRegisterStatus] = useState(null);

    const validateEmail = (email) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);

    useEffect(() => {
        const checkEmail = async () => {
            if (!email || !validateEmail(email)) {
                setIsValidEmail(false);
                setExists(null);
                return;
            }
            setIsValidEmail(true);
            setLoading(true);
            try {
                const response = await axios.get(`${Hoot()}eduallcheckexistentuseraccountemail/${email}`);
                setExists(response.data.length > 0);
            } catch (error) {
                 const msg = error?.response?.data?.msg || "Erro ao verificar o email !";
                toast.error(msg); 
                setExists(null);
            } finally {
                setLoading(false);
            }
        };
        checkEmail();
    }, [email]);

    const generateRandomPassword = () => {
        const length = 12;
        const upper = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
        const lower = 'abcdefghijklmnopqrstuvwxyz';
        const numbers = '0123456789';
        const special = '!@#$%^&*()_+[]{}|;:,.<>?';
        const all = upper + lower + numbers + special;

        let password = '';
        password += upper.charAt(Math.floor(Math.random() * upper.length));
        password += lower.charAt(Math.floor(Math.random() * lower.length));
        password += numbers.charAt(Math.floor(Math.random() * numbers.length));
        password += special.charAt(Math.floor(Math.random() * special.length));

        for (let i = password.length; i < length; i++) {
            password += all.charAt(Math.floor(Math.random() * all.length));
        }

        password = password.split('').sort(() => Math.random() - 0.5).join('');
        return password;
    };



    const handleRegister = async () => {
        if (!userName || userName.length < 5) {
            toast.error("O nome deve ter no mínimo 5 caracteres.");
            return;
        }
        if (!email || !country || !gender) {
            toast.error("Todos os campos são obrigatórios!");
            return;
        }
        if (!validateEmail(email)) {
            toast.error("Email inválido!");
            return;
        }




        setRegisterStatus(0);  
        const password = generateRandomPassword();
        const data = {
            ed_user_name: userName,
            ed_user_email: email,
            ed_user_password: password,
            ed_user_country: country,
            ed_user_gender: gender,
            create_by_inst: 1,
        };



        try {
            await axios.post(Hoot() + 'eduallusersaccountsignup/post', data);
            setRegisterStatus(2); 
             if (expand === true) {
                RefreshList(`.el-refresh-list`);
             }
            return;
        } catch (error) {
            console.clear()
            console.log(error);
             const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
            toast.error(msg);
            setRegisterStatus(1);
            return;
        }

    };

    if (loading) {
        return (
            <div className="mt-2 mb-2 text-red">
                <Spinner animation="border" size="sm" /> Verificando se a conta existe...
            </div>
        );
    }

    if (!isValidEmail || exists !== false || !userName || !gender) return null;

    return (
        <div>
            {registerStatus === 2 ? <>
                <div className="alert alert-success alert-dismissible fade show mt-2" role="alert">
                    <div className='col-lg-11' >
                        {expand === true ?
                            <small>
                                Conta criada com sucesso para <strong className="text-main">{userName}</strong> com o email
                                <strong className="text-main"> {email}</strong> 🎉.
                                Por favor, peça ao usuário que aceda à sua caixa de email e siga as instruções para
                                <span className="text-danger"> verificar e ativar a conta Eduall</span>. 
                            </small> 
                            :
                            <small>
                                Conta criada com sucesso e dados enviados para o usuário! 🎉
                                Agora você já pode prosseguir com a criação de username para funcionários ou atribuição de conta de aluno ou encarregado.
                                Basta clicar em <strong className='text-main underline'>Salvar</strong> no seu formulário para concluir a operação.
                            </small>}
                    </div>
                    <button type="button" className="btn-close" data-bs-dismiss="alert" aria-label="Close"></button>
                </div>


            </> :

                <section className='account-create-element'>
                    <div className="alert alert-info mt-3 text-left">
                        <div className="ed-flex ed-space">
                            <div className="ed-block">
                                <small className="grey-text">Nenhuma conta Eduall encontrada com o email {registerStatus} </small>
                                <div className="text-main mt-1"><strong>{email}</strong></div>
                            </div>

                            {!registerStatus || registerStatus === 1 ? (
                                <div className="mt-3" style={{ marginLeft: "-15px" }}>
                                    <div
                                        className={`btn bg-main ml-2 ${registerStatus === 0 ? "disabled" : ""
                                            }`}
                                        onClick={registerStatus === 0 ? undefined : handleRegister}
                                    >
                                        {registerStatus === 0 ? (
                                            <span className="d-flex align-items-center">
                                                <Spinner
                                                    animation="border"
                                                    role="status"
                                                    size="sm"
                                                    className="mr-2"
                                                />
                                                Criando conta...
                                            </span>
                                        ) : registerStatus === 1 ? (
                                            <>Tentar novamente</>
                                        ) : (
                                            <>Criar Conta</>
                                        )}
                                    </div>
                                </div>
                            ) : null}
                        </div>

                        <hr />

                        <div className="mt-2">
                            <a
                                href="#!"
                                className='cursor-pointer underline text-main'
                                onClick={(e) => {
                                    e.preventDefault();
                                    setOpenAccordion(!openAccordion);
                                }}
                            >
                                <small>{openAccordion ? "Fechar detalhes" : "Como funciona a criação da conta ?"}</small>
                            </a>

                            <Collapse in={openAccordion || expand === true}>
                                <div className="mt-3">
                                    {registerStatus === 0 && <div className="mb-2"><Spinner animation="border" /></div>}
                                    {registerStatus === 2 && <div className="alert alert-success mt-2">Conta criada com sucesso! Enviando dados...</div>}
                                    {registerStatus === 1 && <div className="alert alert-danger mt-2">Erro ao criar conta!</div>}
                                    {registerStatus === "done" && <div className="alert alert-success mt-2">Conta criada, dados enviados para o usuário.</div>}

                                    {!registerStatus && (
                                        <p className="grey-text text-left mt-2">
                                            <small>
                                                Você está prestes a criar uma conta EDUALL para <strong className="text-main mr-1">{userName}</strong>
                                                com o email <strong className="text-main">{email}</strong>.
                                            </small>
                                            <br />
                                            <small>
                                                Uma senha segura será criada automaticamente e enviada junto com os dados de acesso diretamente para o email do usuário.
                                            </small>
                                            <br />
                                            <small>
                                                Após a criação automática da conta, você poderá continuar com a atribuição de conta de professor, aluno ou encarregado,
                                                além de definir um username se for o caso.
                                            </small>
                                            <br />   <br />
                                            <small>
                                                Observação: caso a conta não seja ativada pelo usuário em até 42 horas, ela será deletada automaticamente pelo sistema.
                                            </small>
                                        </p>
                                    )}
                                </div>
                            </Collapse>
                        </div>
                    </div>
                </section>
            }
        </div>
    );
}

export default CreateTemporaryEduallAccountAlert;
