import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import ReactDOMServer from "react-dom/server";
import { AgGridReact } from "ag-grid-react";
import { Dropdown, Form } from "react-bootstrap";
import { SearchOutline } from "react-ionicons";
import { VscListFilter } from "react-icons/vsc";

/** -------------------- Utils -------------------- */
function normalizeText(str) {
  if (str == null) return "";
  return String(str)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim()
    .toLowerCase();
}

function isPlain(value) {
  return typeof value === "string" || typeof value === "number" || typeof value === "boolean";
}

// Extrai texto visível de elementos React renderizados
function elementToText(element) {
  try {
    const html = ReactDOMServer.renderToStaticMarkup(element);
    const temp = document.createElement("div");
    temp.innerHTML = html;
    const text = temp.textContent || temp.innerText || "";
    return normalizeText(text);
  } catch (_) {
    return "";
  }
}

function anyToText(value) {
  if (value == null) return "";
  if (isPlain(value)) return normalizeText(value);

  if (Array.isArray(value)) return normalizeText(value.map(anyToText).join(" "));

  if (React.isValidElement(value)) return elementToText(value);

  if (typeof value === "object") {
    try {
      return normalizeText(Object.values(value).map(anyToText).join(" "));
    } catch (_) {
      return "";
    }
  }

  return normalizeText(String(value));
}

function isSearchableColumn(col) {
  const header = (col?.headerName || "").toLowerCase();
  const field = (col?.field || "").toLowerCase();
  if (["ação", "acao", "action"].includes(header)) return false;
  if (field === "action") return false;
  return true;
}

/** -------------------- PreviewTable -------------------- */
function PreviewTable({ columns, rows, show = true }) {
  useEffect(() => {
    const tablePreview = document.getElementById("table-preview");
    if (!tablePreview) return;
    const avatars = tablePreview.querySelectorAll(".MuiAvatar-root");
    avatars.forEach((avatar) => avatar.remove());
  }, [rows]);

  if (!show) return null;

  return (
    <div className="table-preview" id="table-preview" style={{ marginBottom: 12, display: "none" }}>
      <div className="table-responsive">
        <table className="table table-sm table-bordered">
          <thead>
            <tr>{columns.map((c) => <th key={c.field}>{c.headerName}</th>)}</tr>
          </thead>
          <tbody>
            {rows.map((row, ridx) => (
              <tr key={ridx}>
                {columns.map((col) => {
                  const raw =
                    typeof col.valueGetter === "function"
                      ? col.valueGetter({ data: row, value: row[col.field] })
                      : row[col.field];

                  const rendered =
                    typeof col.cellRenderer === "function"
                      ? col.cellRenderer({ data: row, value: raw, colDef: col })
                      : raw;

                  return <td key={col.field}>{rendered}</td>;
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/** -------------------- TableGrid -------------------- */
function TableGrid(props) {
  const rowData = props.TableBody || [];
  const columnDefs = props.TableHead || [];

  const [displayedRows, setDisplayedRows] = useState(rowData);
  const [filterColumn, setFilterColumn] = useState("");
  const [columnSearchText, setColumnSearchText] = useState("");
  const [globalSearchText, setGlobalSearchText] = useState("");
  const [showDropdown, setShowDropdown] = useState(false);

  const gridRef = useRef();
  const CurrentHeight = props.TableHeight || (props.NoCustomItems ? 300 : 600);

  const onFilterTextBoxChanged = useCallback(() => {
    const id = props.TableInputCode
      ? `filter-text-box-${props.TableInputCode}`
      : "filter-text-box";
    const el = document.getElementById(id);
    setGlobalSearchText(el ? el.value : "");
  }, [props.TableInputCode]);

  const searchableColumns = useMemo(() => columnDefs.filter(isSearchableColumn), [columnDefs]);

  const searchIndex = useMemo(() => {
    return rowData.map((row) => {
      const perCol = {};
      searchableColumns.forEach((col) => {
        const baseValue =
          typeof col.valueGetter === "function"
            ? col.valueGetter({ data: row, value: row[col.field] })
            : row[col.field];

        const rendered =
          typeof col.cellRenderer === "function"
            ? col.cellRenderer({ data: row, value: baseValue, colDef: col })
            : baseValue;

        perCol[col.field] = anyToText(rendered);
      });

      const concat = normalizeText(Object.values(perCol).join(" "));
      return { row, perCol, concat };
    });
  }, [rowData, searchableColumns]);

  useEffect(() => {
    const global = normalizeText(globalSearchText);
    const colSearch = normalizeText(columnSearchText);
    const colKey = filterColumn;

    let matched = searchIndex;

    if (global) matched = matched.filter((it) => it.concat.includes(global));
    if (colKey && colSearch)
      matched = matched.filter((it) => {
        const cellTxt = it.perCol[colKey] || "";
        return cellTxt.includes(colSearch);
      });

    setDisplayedRows(matched.map((m) => m.row));
  }, [searchIndex, globalSearchText, filterColumn, columnSearchText]);

  return (
    <>
      <PreviewTable
        columns={columnDefs}
        rows={displayedRows}
        show={props.ShowPreview !== false}
      />

      <div className="custom-table nav-theme ag-custom-grid-table">
        <div className="ag-theme-alpine" style={{ height: CurrentHeight, width: "100%" }}>
          {props.NoCustomItems ? (
            <div>
              <div className="col bg-background py-4 text-center">
                <div className="ed-flex ed-center">
                  <h4 className="title m0">{props.TableTitle || ""}</h4>
                  <div className="ml-2">
                    <Dropdown
                      show={showDropdown}
                      onToggle={() => setShowDropdown(!showDropdown)}
                      className="ml-2"
                    >
                      <Dropdown.Toggle variant="light" className="btn btn-export-data-2">
                        <VscListFilter />
                      </Dropdown.Toggle>
                      <Dropdown.Menu style={{ padding: "10px", minWidth: "260px" }}>
                        <Form.Group className="mb-2 col-lg-12">
                          <Form.Label>Coluna</Form.Label>
                          <Form.Select
                            className="col-lg-12"
                            value={filterColumn}
                            onChange={(e) => setFilterColumn(e.target.value)}
                          >
                            <option value="">Selecione</option>
                            {searchableColumns.map((col) => (
                              <option key={col.field} value={col.field}>
                                {col.headerName}
                              </option>
                            ))}
                          </Form.Select>
                        </Form.Group>
                        <Form.Group>
                          <Form.Label>Pesquisar</Form.Label>
                          <Form.Control
                            type="text"
                            placeholder="Texto..."
                            value={columnSearchText}
                            onChange={(e) => setColumnSearchText(e.target.value)}
                          />
                        </Form.Group>
                      </Dropdown.Menu>
                    </Dropdown>
                  </div>
                  <div className="ml-1">{props.TableBtn && props.TableBtn}</div>
                </div>
              </div>
            </div>
          ) : (
            <div className="ed-space">
              <div className="title">
                <h1>{props.TableTitle || ""}</h1>
              </div>

              <div className="ed-flex">
                {!props.NoSearch && (
                  <div className="search-table-form ml-2">
                    <SearchOutline />
                    <input
                      type="text"
                      id={
                        props.TableInputCode
                          ? "filter-text-box-" + props.TableInputCode
                          : "filter-text-box"
                      }
                      className="form-control"
                      placeholder="Pesquisar ..."
                      onInput={onFilterTextBoxChanged}
                    />
                  </div>
                )}

                <Dropdown
                  show={showDropdown}
                  onToggle={() => setShowDropdown(!showDropdown)}
                  className="ml-2"
                >
                  <Dropdown.Toggle variant="light" className="btn btn-export-data-2">
                    <VscListFilter />
                  </Dropdown.Toggle>
                  <Dropdown.Menu style={{ padding: "10px", minWidth: "260px" }}>
                    <Form.Group className="mb-2">
                      <Form.Label>Coluna</Form.Label>
                      <Form.Select
                        value={filterColumn}
                        onChange={(e) => setFilterColumn(e.target.value)}
                      >
                        <option value="">Selecione</option>
                        {searchableColumns.map((col) => (
                          <option key={col.field} value={col.field}>
                            {col.headerName}
                          </option>
                        ))}
                      </Form.Select>
                    </Form.Group>
                    <Form.Group>
                      <Form.Label>Pesquisar</Form.Label>
                      <Form.Control
                        type="text"
                        placeholder="Texto..."
                        value={columnSearchText}
                        onChange={(e) => setColumnSearchText(e.target.value)}
                      />
                    </Form.Group>
                  </Dropdown.Menu>
                </Dropdown>

                {props.TableBtn && props.TableBtn}
              </div>
            </div>
          )}

          <AgGridReact
            rowData={displayedRows}
            columnDefs={columnDefs}
            suppressRowClickSelection={true}
            groupSelectsChildren={true}
            ref={gridRef}
            rowSelection={"multiple"}
            rowGroupPanelShow={"always"}
            pivotPanelShow={"always"}
            pagination={props.NoCustomItems ? false : true}
          />
        </div>
      </div>

      {window.innerWidth > 900 && (
        <>
          <br />
          <br />
        </>
      )}
    </>
  );
}

export default TableGrid;
