import React, { useEffect, useRef, useState } from 'react'
import styled from 'styled-components'
import { Button, Form, OverlayTrigger, Popover } from 'react-bootstrap'
import { Delete, InfoOutlined, Refresh, Search } from '@mui/icons-material';
import FileUpload from '../../../General/components/FileUpload';
import { Alert, Avatar, Checkbox, FormControlLabel } from '@mui/material'; 
import { Link } from 'react-router-dom';
import SmallStudentsGrid from '../../components/Grid/SmallStudentsGrid';
import FeespaymentsTable from '../../components/Table/FeespaymentsTable';
import NewfeeManualPaymentModal from '../../components/modal/NewfeeManualPaymentModal';
import {
    GetClassroom_byclass, GetClasstitle_byclass, GetCourse_byclass, GetPeriod_byclass, GetFaculty_byclass,
    ClassDataOptions, CourseDataOptions, GetAcademiclevel_byclass, GetInstituteCode, GetAcademicYear_byclass, GetAcademicYearcode_byclass, AcademicYearDataOptions
} from '../../../General/components/InstituteData';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import AnimationPage from '../../../General/AnimationPage';
import EmptyImage from '../../../Assets/images/svg/personal_info.svg';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import KeyShortcut from '../../../General/components/KeyShortcut';
import Loader from '../../../General/components/Loader';
import KeyDownEvent from '../../../General/components/KeyDownEvent';
import StudentDetailsMenu from '../../components/elements/StudentDetailsMenu';
import DeleteModal from '../../components/elements/DeleteModal';
import NotFounded from '../../../General/components/NotFounded';
import { FixedSizeList as List } from "react-window";
import KeyboardEventHandler from 'react-keyboard-event-handler';
import { useLocation, useHistory } from 'react-router-dom';
import ReplaceWord from '../../../General/components/ReplaceWord';


function FeesPayments() {
    document.title = "Pagar Propinas";
    const [StudentClass, setStudentClass] = useState('#');
    const [StudentName, setStudentName] = useState('#');
    const [StudentDataInfo, setStudentDataInfo] = useState({});
    const [StudentType, setStudentType] = useState(null);
    const [StudentPicture, setStudentPicture] = useState('#');
    const [StudentId, setStudentId] = useState('#');
    const [AcademicYear, setAcademicyear] = useState(null);
    const [ShowMonths, setShowMonths] = useState(false);
    const [StudentClassFilter, setStudentClassFilter] = useState(null);
    const [StudentNameFilter, setStudentNameFilter] = useState(null);
    const [PopStatus, setPopStatus] = useState(false);
    const [MP, SM] = useState([]);
    const [Founded, setFounded] = useState('');
    const ChildRef = useRef();

    /*get data with page params **/
    const navigate = useHistory();
    const { search } = useLocation();
    const searchParams = new URLSearchParams(search);
    const Year = searchParams.get("year");
    const Studentid = searchParams.get("student");

    const LoadByParams = (a, b) => {
        if (a * 1 >= 1 && b * 1 >= 1) {
            GetPaymentData(a, b);
            setAcademicyear(b);
        }
    }

    useEffect(() => {
        LoadByParams(Studentid, Year);
    }, [Year, Studentid]);



    const FilterPaymentByYear = (e) => {
        navigate.push(`/feespayments?student=` + 0 + `&year=` + 0);
        navigate.push(`/feespayments?student=` + StudentId + `&year=` + e.target.value);
    }

    const GetStudentPaymentData = (a, b) => {
        navigate.push(`/feespayments?student=` + 0 + `&year=` + 0);
        navigate.push(`/feespayments?student=` + a + `&year=` + b);
    }

    /***** end ***/






    const getAcademicYear = (e) => {
        setAcademicyear(e * 1);
    }


    let DfStudentCode = 0;
    let month = new Date().getMonth()
    let currentMonth = month + 1 <= 12 ? month + 1 : month;
    let Months = [];
    const CY = new Date().getFullYear();

    const FORMURL = [
        Hoot() + "eduallsinglestudentfeepayment/get/",
        Hoot() + "eduallsinglestudentapi/get/",
        Hoot() + "eduallsingleserviceapi/get/",
        Hoot() + "eduallsingleacademicyearapi/get/",
        Hoot() + "eduallfeepaymentcheckpaidmonth/",
    ];


const GetPaymentData = async (studentCode, academicYear) => {
  if (!studentCode || !academicYear) {
    console.warn("⚠️ Parâmetros inválidos para GetPaymentData");
    setFounded(false);
    return;
  }

  try {
    setFounded(null);

    const url = `${Hoot()}eduallfeepayments/get/student/${studentCode}?ano=${academicYear}`;
    const response = await axios.get(url);

    if (response?.data?.success && response.data.data) {
      const { student, months } = response.data.data;

      // guarda os dados do aluno
      if (student) {
        setStudentDataInfo(student);
        setStudentName(student.name);
        setStudentClass(student.class_id);
        setStudentPicture(student.picture);
        setStudentId(student.id);
      }

      // meses e status
      if (Array.isArray(months) && months.length > 0) {
        SM(months);             // atualiza o estado dos meses
        setShowMonths(true);
        setFounded(true);
      } else {
        setShowMonths(false);
        setFounded(false);
      }

    } else {
      setFounded(false);
      console.warn("Nenhum dado retornado da rota de pagamentos.");
    }

  } catch (error) {
    console.error("❌ Erro ao buscar dados de pagamento:", error);
    setFounded(false);
  }
};






    const FilterData = (a, e) => {
        a === 1 ? setStudentNameFilter(e.target.value) : setStudentClassFilter(e.target.value);
        ChildRef.current.ChangeFilter(a === 1 ? 1 : 0);
    }





    const handleKeys = (e) => {
        switch (e) {
            case "a":

                break;
            case "p":
                setPopStatus(true);
                break;
            default:
        }
    }

    return (
        <div className='feespayments'>
            <KeyboardEventHandler handleKeys={['p']} onKeyEvent={(key, e) => handleKeys(key)} />
            <div className="ed-space mb-3">
                <div className="ed-block">
                    <Form>
                        <div className="search-box boxItem">
                            <Form.Group>
                                <div className="ed-flex m0 fill">
                                    <Search />
                                    <div className="block col  ml-2">
                                        <Form.Control type="text" onChange={(e) => FilterData(1, e)} placeholder="Pesquisar ..." autoFocus />
                                    </div>
                                </div>
                            </Form.Group>
                        </div>
                    </Form>
                </div>
                <div className="ed-flex">
                    <NewfeeManualPaymentModal pop={PopStatus} />
                </div>
            </div>
            <div className="ed-flex" style={{ alignItems: 'flex-start' }}>
                <FilterBox className='filterBox'>
                    <Box className='boxItem'>
                        <div className="ed-space">
                            <div className="title">Selecione um aluno</div>
                            <div className="mr-2">
                                <Form.Select style={{ maxWidth: "150px" }} onChange={(e) => FilterPaymentByYear(e)}>
                                    <AcademicYearDataOptions />
                                </Form.Select>
                            </div>
                        </div>
                        <Container>
                            <SmallStudentsGrid ref={ChildRef} FilterByName={StudentNameFilter}
                                FilterByClass={StudentClassFilter} GetData={GetStudentPaymentData} />
                        </Container>
                    </Box>
                </FilterBox>
                <div className="pd-1"></div>
                <Box className='ml-2 boxItem'>
                    {
                        Founded === '' ?
                            <div className='empty-search'><img loading="lazy" role="presentation" src={EmptyImage} alt="selecione um estudante" /> </div>
                            :
                            <>
                                {
                                    Founded === null ?
                                        <LoaderContainer>
                                            <Loader absolute small />
                                        </LoaderContainer>
                                        :
                                        <>
                                            {
                                                Founded === false ?
                                                    <>
                                                        <NotFounded />
                                                    </>
                                                    :
                                                    <>
                                                        <div className="ed-space">
                                                            <div className="ed-flex mb-4">
                                                                <li className="ed-flex ex"><div className="dot success"></div> Pago</li>
                                                                <li className="ed-flex ex"><div className="dot warning"></div>Não pago</li>
                                                                <li className="ed-flex ex"><div className="dot other"></div> Outras</li>
                                                            </div>
                                                            <div className="ed-flex  " style={{ marginRight: '10px' }}>
                                                                {(StudentId !== "#" & StudentId !== null) ? <StudentDetailsMenu student_id={StudentId} toggle_btn={<div className='btn-pm-info'><InfoOutlined /></div>} /> : <></>}
                                                            </div>
                                                        </div>
                                                        <div className='d-none'>
                                                            {StudentDataInfo.ed_academic_year_id !== getAcademicYear ?
                                                                <GetAcademicYearcode_byclass ID={StudentClass} YearCode={getAcademicYear} /> :
                                                                <> {StudentDataInfo.ed_academic_year_title} </>}
                                                        </div>
                                                        <div className="ed-flex">
                                                            <SwitchFromPages link={`studentinfo/${StudentId}`}
                                                                menu='3' menu_item='17' toggle_btn={
                                                                    <Link to="#"><Avatar alt={StudentName} className='df'
                                                                        src={StudentPicture !== "#" ? Hoot() + StudentPicture : ""} sx={{ width: 106, height: 106 }} /></Link>
                                                                } />
                                                            <div className="d-block ml-2 description">
                                                                <SwitchFromPages link={`studentinfo/${StudentId}`}
                                                                    menu='3' menu_item='17' toggle_btn={<h5 className='name '>Nome : <Link to="#"
                                                                        className='text-main label-student-name'> {StudentName} </Link></h5>
                                                                    } />
                                                                <div className="ed-flex">
                                                                    <h5>Turma : </h5>
                                                                    <div className='text-main label-student-class ml-1 ed-flex'>
                                                                        {StudentDataInfo.class_title}
                                                                    </div>
                                                                </div> 
                                                            </div>
                                                        </div>
                                                        <div className="ed-wrap mt-4 description">
                                                            <h5>Ano académico : <Link to='#' className='text-main label-student-level'>
                                                                {StudentDataInfo.year_title}
                                                            </Link> </h5>
                                                            <h5 className='ml-2'>{ReplaceWord("Classe")} : <Link to='#' className='text-main label-student-level'>{StudentDataInfo.level_title}</Link> </h5>
                                                            <h5 className='ml-2'>Sala : <Link to='#' className='text-main label-student-classroom'> {StudentDataInfo.classroom_title} </Link></h5>
                                                        </div>
                                                        <div className="ed-wrap mt-2 description">
                                                            <h5>Curso : <Link to='#' className='text-main label-student-class'>{StudentDataInfo.course_title}</Link></h5> 
                                                            {StudentDataInfo.ed_institute_type * 1 === 1 ?
                                                                <h5 className='ml-2'>Faculdade :
                                                                    <Link to='#' className='text-main label-student-class'>
                                                                        {StudentDataInfo.faculty_title}
                                                                    </Link>
                                                                </h5>
                                                                :
                                                                <h5 className='ml-2'>Ciclos :
                                                                    <Link to='#' className='text-main label-student-class'>
                                                                        {StudentDataInfo.cicle_title}
                                                                    </Link>
                                                                </h5>
                                                            }
                                                        </div>
                                                        <h2>Propinas pagas </h2>
                                                        <div className="wrap wrap-scroll">
                                                            {
                                                                ShowMonths === true ?
                                                                    MP.map((item, index) => {
                                                                        return (<>
                                                                            <OverlayTrigger trigger="clickl" placement="top" overlay={
                                                                                <Popover id="popover-basic">
                                                                                    <Popover.Header className='bg-black text-light' as="h5">Propina de {item.month}</Popover.Header>
                                                                                    <Popover.Body>
                                                                                        {item.status === "notpaid" ?
                                                                                            <div className="ed-flex ed-center col">
                                                                                                <NewfeeManualPaymentModal toggle_btn={<Button className='btn-small bg-main fill-btn'>Pagar</Button>}
                                                                                                    title='Atualizar ' update='true' get={Hoot() + `eduallfeepaymentsingle/get/ `}
                                                                                                    url={Hoot() + `eduallfeepaymentupdate/update/ `}
                                                                                                />
                                                                                            </div>
                                                                                            : <></>
                                                                                        }
                                                                                        {item.status === "paid" ?
                                                                                            <div className="ed-flex">
                                                                                                <NewfeeManualPaymentModal toggle_btn={<Button className='btn-small bg-main ed-flex'><Refresh /><div className="ml-1">Atualizar</div></Button>}

                                                                                                />
                                                                                                <DeleteModal title='um pagamento de propina' url={Hoot() + `eduallfeepaymentsdelete/delete/`}
                                                                                                    message='Pagamento deletado com sucesso' toggle_btn={
                                                                                                        <Button className="bg-danger ed-flex btn-small ml-2 text-light">
                                                                                                            <Delete /><div className="ml-1">Anular</div>
                                                                                                        </Button>
                                                                                                    } />
                                                                                            </div>
                                                                                            : <></>
                                                                                        }
                                                                                        {item.status === "other" ?
                                                                                            <div className="ed-flex col">
                                                                                                <NewfeeManualPaymentModal toggle_btn={<Button className='btn-small bg-main fill-btn'>Pagar</Button>}
                                                                                                />
                                                                                            </div>
                                                                                            : <></>
                                                                                        }
                                                                                    </Popover.Body>
                                                                                </Popover>
                                                                            }>
                                                                                <div className={item.status === '' ? 'month' : `month ${item.status}`} key={index}>{item.month}</div>
                                                                            </OverlayTrigger>
                                                                        </>)
                                                                    })
                                                                    :
                                                                    ''}
                                                        </div>
                                                    </>
                                            }
                                        </>

                                }
                            </>
                    }
                </Box>
            </div>
            <div className="mt-4">
                <FeespaymentsTable />
            </div>
        </div>
    )
}

const FilterBox = styled.div`
  max-width:400px;
  min-width:400px;
  
  .title{
    font-weight: 600;
    font-size: 18px;
    margin-bottom:10px;
  }

`;

const Box = styled.div`
    width:100%; 
    border-radius:6px;   
    padding:20px;
    min-height:520px;
    height:auto;
    background:var(--ed-white);  
    box-shadow:var(--ed-shadow-df);
    margin:10px 0;
    position:relative;
    overflow:hidden;

    

    .ed-flex.col div,
    .ed-flex.col div div{
         width:100% !important; 
         border:2px solid gold !important;
    }

    .wrap-scroll{
         overflow-y:auto;
         max-height:180px;
         padding-right:20px;
         padding-left:10px; 
         margin-left:-10px;
    

         &::-webkit-scrollbar{
            width:6px !important;
            background-color:transparent !important;
        }
         
         &::-webkit-scrollbar-thumb{
            background:rgb(219, 219, 219) !important; 
        }
    }

    .empty-search{
         display:flex;
         align-items:center;
         justify-content:center;
         height:100%;
         min-height:440px; 

         img{
              max-width:600px;
              max-height:300px;
         }
    }

    @media screen and (max-width:1290px){ 
        width:auto;
        min-width:50%;
        min-height:550px; 
    }

    .ex{
        font-size:16px;
        margin-top:8px;
        margin-right:25px;

        .dot{
            width:20px;
            height:20px;
            border-radius:100%;
            margin-right:10px;
            border:3px solid var(--ed-white);
            box-shadow:var(--ed-shadow-df);
        }

        .dot.warning{
            background:#FFBD00;
        }

        .dot.success{
            background:#52B69A;
        }

        .dot.other{
            background:#CED4DA;
        }
    }



    .description{
        .name{
            font-size:18px;
            margin-bottom:15px;
            margin-top:10px;
        }

        h5{
            font-size:16px;
        }
    }

    h2{
        margin:10px 0;
        font-size:18px;
        font-weight:600;
    }
`;


const Container = styled.ul` 
    width:100%;
    max-height:430px;
    min-height:430px;
    overflow-y:auto;
    padding:0px; 

    ul{
         padding:0px;
         margin:0px; 
         max-height:419px;
         overflow-y:auto;
          
    &::-webkit-scrollbar{
        width:6px;
        background-color:transparent;
      }
    
     &:hover{      
      padding-right:10px;

      &::-webkit-scrollbar-thumb{
        background:#eaeaee;   
       }
     } 
    }

    
    .empty-search{
        display:flex;
        align-items:center;
        justify-content:center;
        height:100%;
        min-height:440px; 

        img{
             max-width:600px;
             max-height:300px;
        }
   }

 
    @media screen and (max-width:1280px){ 
       max-height:460px;
    }
 
    &::-webkit-scrollbar{
     width:6px;
     background-color:transparent;
   }
 
  &:hover{ 
   &::-webkit-scrollbar-thumb{
     background:#eaeaee;   
    }
  } 
`;


const LoaderContainer = styled.div`
  position:absolute;
  top:0px;
  left:0px;
  width:100%;
  height:100%;
  padding:30px;
  display:flex;
  align-items:center;
  justify-content:center; 
`;


export default FeesPayments