import React , {useEffect, useState} from 'react'
import Table from './Table'
import { Avatar } from '@mui/material'; 
import axios from 'axios'
import { Delete, Description, Edit , PreviewOutlined, Refresh } from '@mui/icons-material'; 
import Hoot from '../../../General/components/Hoot'; 
import DeleteModal from '../elements/DeleteModal'; 
import { Link } from 'react-router-dom';
import ParentsGrades from '../../../General/components/ParentsGrades';
import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import NumberToPrice from '../../../General/components/NumberToPrice';
import moment from 'moment';
import PAYx from './PAYx';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';

const TypeOfPayments = [
  <div className="badge bg-success col col-lg-12">Dinheiro a mão</div>,
  <div className="badge bg-danger col col-lg-12">Transferência</div>,
  <div className="badge bg-warning col col-lg-12">Depósito</div>,
  <div className="badge bg-info col col-lg-12">TPA</div> 
];

const PaymentsType = [
  <div className="badge bg-success col col-lg-12">Propinas</div>,
  <div className="badge bg-danger col col-lg-12">Transporte escolar</div>,
  <div className="badge bg-warning col col-lg-12">Serviços</div>,
  <div className="badge bg-info col col-lg-12">Pagamento de produtos</div> 
];

// NOVO: mapeamento para “Misto” quando houver vários métodos no agrupamento
const PaymentMethodLabel = {
  0: <div className="badge bg-success col col-lg-12">Dinheiro a mão</div>,
  1: <div className="badge bg-danger col col-lg-12">Transferência</div>,
  2: <div className="badge bg-warning col col-lg-12">Depósito</div>,
  3: <div className="badge bg-info col col-lg-12">TPA</div>,
  mixed: <div className="badge bg-secondary col col-lg-12">Misto</div>,
};

const columns = [   
  { 
    field: 'invoiceCode',
    headerName: 'Nº da Fatura',  
    resizable: true, 
  },
  { 
    field: 'name',
    headerName: 'Cliente',  
    resizable: true,
    cellRenderer:(props)=>{
      return props.data.code !== null ? (
        <div className="ed-flex">
          <Avatar alt="" className='df' src={props.data.code !== null  ?  Hoot()+props.data.picture : ""} />
          <span className='ml-2'> { props.data.name} </span>
        </div>
      ) : <div className="badge bg-main">{props.data.name}</div>
    }
  },
  { 
    field: 'paymenttype',
    headerName: 'Método de pagamento',  
    resizable: true,
    cellRenderer:(props)=>{
      // agora pode ser “mixed”
      return props.data.paymenttypeMixed ? PaymentMethodLabel['mixed'] : TypeOfPayments[props.data.paymenttype*1];
    }
  },
  { 
    field: 'paymentid',
    headerName: 'Tipo de pagamento',  
    resizable: true,
    width:250,
    cellRenderer:(props)=>{
      // se for grupo com pagamentos de tipos diferentes, vamos mostrar o primeiro + “(múltiplos)”
      return props.data.paymentidMixed
        ? <div className="badge bg-secondary col col-lg-12">Múltiplos</div>
        : PaymentsType[props.data.paymentid*1];
    }
  },
  { 
    field: 'total',
    headerName: 'Valor pago',  
    resizable: true, 
  },   
  { 
    field:'service',
    headerName:'Serviço / produto',  
    resizable: true, 
  },
  {
    field: 'situation',
    headerName: 'Situação',
    resizable: true,
    width: 180,
    cellRenderer: (props) => {
      return props.data.invoiceCount > 1
        ? <div className="badge col-lg-12 bg-warning">Fatura múltipla ({props.data.invoiceCount})</div>
        : <div className="badge col-lg-12 bg-success">PG. Simples</div>;
    }
  },
  { 
    field: 'paymentdate',
    headerName: 'Data de pagamento',  
    resizable: true, 
  },       
];

function PaymentsTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);
  const [TotalBalance, setTotalBalance] = useState("");
  const [CurrentCoin, SetCurrentCoin] = useState("");
  const [FilteredRows, setFilteredRows] = useState([]);

  // util comum (propinas e transporte calculam multa e iva de forma semelhante ao teu exemplo)
  function computeLineTotals({ price, discountPct = 0, ivaPct = 0, fineType = 0, fineValue = 0 }) {
    const afterDiscount = price - (price * discountPct) / 100;
    const base = ivaPct > 0 ? afterDiscount / (1 + ivaPct / 100) : afterDiscount;
    const ivaAmount = afterDiscount - base;
    const fineAmount = fineType === 1 ? fineValue : ((base * fineValue) / 100);
    const total = afterDiscount + fineAmount; // (sem “somar” IVA novamente, acompanha o modelo que já usas)
    return { base, ivaAmount, fineAmount, total, afterDiscount };
  }

  // normaliza uma linha qualquer para o mesmo shape
  function normalizeRow({
    invoiceCode,
    serviceTitle,
    name,
    code,
    picture,
    totalNotFormated,
    paymentdateISO,
    paymenttype,
    paymentid,
    coin
  }) {
    const paymentdate = moment(paymentdateISO).format("DD-MM-YYYY HH:mm");
    return {
      invoiceCode,
      serviceTitle,
      name,
      code: code ?? null,
      picture: picture ?? "",
      totalNotFormated,
      total: `${NumberToPrice(totalNotFormated)} ${coin || ""}`,
      paymentdate,
      paymentdateISO,
      paymenttype,
      paymentid,
      coin,
    };
  }

  async function loadData(){
    try {
      setLoaded(false);
      setLoadStatus(0);  
      const rawRows = []; 

      const [
        FeePaymentData,
        TransportPaymentData,
        ServicePaymentData,
        SallesPaymentDate
      ] = await Promise.all([
        axios.get(Hoot()+"eduallfeepaymentsapi/get/"),
        axios.get(Hoot()+"edualltransportpaymentsapi/get/"),
        axios.get(Hoot()+"eduallservicepaymentsapi/get"),
        axios.get(Hoot()+"eduallgetallproductsales/get/"),
      ]);

      // ====== PROPINAS
      FeePaymentData.data.forEach((item) => {
        const { total } = computeLineTotals({
          price: item.ed_fee_payment_price * 1,
          discountPct: item.ed_fee_payment_discount * 1,
          ivaPct: item.ed_fee_payment_iva * 1,
          fineType: item.ed_fee_payment_fineType * 1,
          fineValue: item.ed_fee_payment_fineValue * 1,
        });

        SetCurrentCoin(item.ed_coin_code);
        rawRows.push(
          normalizeRow({
            invoiceCode: item.ed_fee_payment_invoiceCode,
            serviceTitle: item.ed_service_title,
            name: item.ed_student_name,
            code: item.ed_student_code,
            picture: item.ed_student_picture,
            totalNotFormated: total,
            paymentdateISO: item.ed_fee_payment_registerDate,
            paymenttype: item.ed_fee_payment_type * 1,
            paymentid: 0, // Propinas
            coin: item.ed_coin_code
          })
        );
      });

      // ====== TRANSPORTE
      TransportPaymentData.data.forEach((item) => {
        const { total } = computeLineTotals({
          price: item.ed_transport_payment_price * 1,
          discountPct: item.ed_transport_payment_discount * 1,
          ivaPct: item.ed_transport_payment_iva * 1,
          fineType: item.ed_transport_payment_fineType * 1,
          fineValue: item.ed_transport_payment_fineValue * 1,
        });

        SetCurrentCoin(item.ed_coin_code);
        rawRows.push(
          normalizeRow({
            invoiceCode: item.ed_transport_payment_invoiceCode,
            serviceTitle: item.ed_service_title,
            name: item.ed_student_name,
            code: item.ed_student_code,
            picture: item.ed_student_picture,
            totalNotFormated: total,
            paymentdateISO: item.ed_transport_payment_registerDate,
            paymenttype: item.ed_transport_payment_type * 1,
            paymentid: 1, // Transporte
            coin: item.ed_coin_code
          })
        );
      });

      // ====== SERVIÇOS
      ServicePaymentData.data.forEach((item) => {
        const qty = item.ed_service_payment_amount * 1;
        const price = item.ed_service_payment_price * 1;
        const discount = item.ed_service_payment_discount * 1;
        const total = (qty * price) - ((price * qty * discount) / 100);

        SetCurrentCoin(item.ed_coin_code);
        rawRows.push(
          normalizeRow({
            invoiceCode: item.ed_service_payment_invoiceCode,
            serviceTitle: item.ed_service_title,
            name: item.ed_student_name,
            code: item.ed_student_code,
            picture: item.ed_student_picture,
            totalNotFormated: total,
            paymentdateISO: item.ed_service_payment_registerDate,
            paymenttype: item.ed_service_payment_type * 1,
            paymentid: 2, // Serviços
            coin: item.ed_coin_code
          })
        );
      });

      // ====== VENDAS (produtos)
      SallesPaymentDate.data.forEach((item) => { 
        let totalPaid = 0;
        let discountPercentage = item.ed_product_sale_discount * 1;
        const coinSymbol = item.coin_symbol || '';

        item.products.forEach((product) => {
          const q = product.ed_sale_product_quantity * 1;
          const p = product.ed_sale_product_price * 1;
          const productTotal = p * q;
          totalPaid += productTotal - (productTotal * discountPercentage / 100);
        });

        SetCurrentCoin(coinSymbol);  
        rawRows.push(
          normalizeRow({
            invoiceCode: item.ed_product_sale_invoiceCode,
            serviceTitle: item.products?.[0]?.ed_product_name || 'Produto(s)',
            name: item.ed_product_sale_nif || 'N/A',
            code: null,
            picture: "",
            totalNotFormated: totalPaid,
            paymentdateISO: item.ed_product_sale_date,
            paymenttype: item.ed_product_sale_payment_method * 1,
            paymentid: 3, // Produtos
            coin: coinSymbol
          })
        );
      });

      // ====== AGRUPAR POR invoiceCode (faturas múltiplas)
      const groupedMap = new Map();

      for (const r of rawRows) {
        if (!groupedMap.has(r.invoiceCode)) {
          groupedMap.set(r.invoiceCode, {
            invoiceCode: r.invoiceCode,
            // dados do cliente (mantemos os do 1º registo)
            name: r.name,
            code: r.code,
            picture: r.picture,
            coin: r.coin,

            // agregados
            totalNotFormated: r.totalNotFormated,
            services: [r.serviceTitle],
            paymentdateISO: r.paymentdateISO, // vamos ficar com a mais recente
            paymenttypeSet: new Set([r.paymenttype]),
            paymentidSet: new Set([r.paymentid]),
            count: 1,
          });
        } else {
          const g = groupedMap.get(r.invoiceCode);
          g.totalNotFormated += r.totalNotFormated;
          g.services.push(r.serviceTitle);
          // manter a data mais recente
          if (new Date(r.paymentdateISO) > new Date(g.paymentdateISO)) {
            g.paymentdateISO = r.paymentdateISO;
          }
          g.paymenttypeSet.add(r.paymenttype);
          g.paymentidSet.add(r.paymentid);
          g.count += 1;
          groupedMap.set(r.invoiceCode, g);
        }
      }

      // ====== converter para rows finais da tabela
      const rows = Array.from(groupedMap.values()).map(g => {
        const paymenttypeMixed = g.paymenttypeSet.size > 1;
        const paymentidMixed = g.paymentidSet.size > 1;

        // serviço: mostra o primeiro + “+N itens” se múltipla
        const firstTitle = g.services[0] || '';
        const extra = g.count > 1 ? ` + ${g.count - 1} itens` : '';
        const serviceLabel = `${firstTitle}${extra}`;

        return {
          invoiceCode: g.invoiceCode,
          name: g.name,
          code: g.code,
          picture: g.picture,
          paymenttypeMixed,
          paymentidMixed,
          paymenttype: paymenttypeMixed ? null : [...g.paymenttypeSet][0],
          paymentid: paymentidMixed ? null : [...g.paymentidSet][0],
          totalNotFormated: g.totalNotFormated,
          total: `${NumberToPrice(g.totalNotFormated)} ${g.coin || ''}`,
          service: serviceLabel,
          paymentdate: moment(g.paymentdateISO).format("DD-MM-YYYY HH:mm"),
          invoiceCount: g.count,
        };
      });

      // sort por data desc
      rows.sort((a, b) => {
        const parseDate = (dateStr) => {
          const [datePart, timePart] = dateStr.split(' ');
          const [day, month, year] = datePart.split('-').map(Number);
          return new Date(year, month - 1, day, ...timePart.split(':').map(Number));
        };
        return parseDate(b.paymentdate) - parseDate(a.paymentdate);
      });

      // total geral
      const total = rows.reduce((acc, obj) => acc + (Number(obj.totalNotFormated) || 0), 0);
      setTotalBalance(NumberToPrice(total));

      // define moeda (se quiseres, podes detectar “múltiplas”)
      SetCurrentCoin(rows[0]?.total?.split(' ').slice(-1)[0] ?? "");

      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2); 
    } catch (error) {
      console.error(error);
      setLoaded(true);
      setLoadStatus(1); 
    }
  }

  useEffect(()=>{
    loadData();  
  },[]);

  const handleFilterChange = (filtered) => {
    // Se quiseres recalcular total com base no filtro, descomenta:
    // setFilteredRows(filtered);
    // const total = filtered.reduce((acc, obj) => acc + (Number(obj.totalNotFormated) || 0), 0);
    // setTotalBalance(NumberToPrice(total));  
  };

  if(load){
    return (
      <div id="ed-custom-table-data" >
        <TableGrid
          TableHead={columns}
          TableBody={data} 
          onFilterChange={handleFilterChange}
          TableTitle={'Pagamentos gerais ( '+data.length+" )"} 
          TableBtn={
            <div className='ed-flex' >
              <div className="badge ml-2 bg-success mr-2">
                <h5 className='m0'>{TotalBalance} {CurrentCoin}</h5>
              </div>
              <button id='ed-custom-table-data-btn'
                onClick={() =>
                  ExportDataToTablesToPdf({
                    fileName: "Lista dos Pagamentos gerais",
                    headerId: null,
                    contentId: "ed-custom-table-data",
                    footerId: null,
                    rotation: "landscape",
                    buttonId: "ed-custom-table-data-btn",
                    customHeader: "Lista dos Pagamentos gerais",
                    excludedColumns: ["Ação"]
                  })
                }
                className='btn-icon ed-flex ed-center btn btn-export-data bg-white'><PiFilePdfDuotone />
              </button>
              <button className='btn-icon btn btn-export-data ml-2'
                onClick={() => ExportDataForTablesExcel("Lista dos Pagamentos gerais ", ["Ação"], "ed-custom-table-data")}><PiMicrosoftExcelLogoDuotone />
              </button>
              <RefreshButton action={loadData} status={LoadStatus} />
            </div>} 
        />
      </div>
    )  
  }else{
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={[]} 
          NoSearch
          TableTitle='Pagamentos gerais'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    )
  }
}

export default PaymentsTable
