import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Delete, Edit } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal'; 
import TableGrid from '../../../General/components/TableGrid';
import RefreshButton from '../../../General/components/RefreshButton';
import NewProductCategoryModal from '../modal/NewProductCategoryModal';

const TABLEURL = Hoot() + "eduallgetproduct_category/get/";

const columns = [
  {
    field: 'index',
    headerName: 'Nº',
    width: 90,
    resizable: true,
  },
  { 
    field: 'title',
    headerName: 'Categoria',
    resizable: true,
    width: 350,
  }, 
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true,
    cellRenderer: (props) => {
      return (
        <div className="ed-flex">
          <NewProductCategoryModal
            title="Atualizar"
            update={true}
            get={Hoot() + `eduallgetsingleproduct_category/get/${props.data.id}`}
            url={Hoot() + `eduallproduct_categoryupdate/update/${props.data.id}`}
            toggle_btn={
              <button className="btn-circle bg-success text-light">
                <Edit />
              </button>
            }
          />
          <DeleteModal
            title="esta categoria"
            url={Hoot() + `eduallproduct_categorydelete/delete/${props.data.id}`}
            message="Categoria deletada com sucesso !"
            toggle_btn={
              <button className="btn-circle bg-danger ml-2 text-light">
                <Delete />
              </button>
            }
          />
        </div>
      );
    },
  },
];

function ProductCategoryTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData() {
    setLoadStatus(0);
    try {
      setLoaded(false);
      const response = await axios.get(TABLEURL);
      const rows = [];
      response.data.map((item, index) => {
        rows.push({
          index: index + 1,
          id: item.ed_product_category_id,
          title: item.ed_product_category_name, 
          action: "",
        });
      });
      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoadStatus(1);
      setLoaded(false);
    }
  }

  useEffect(() => {
    loadData();
  }, []);

  if (load) {
    return (
      <div>
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle="Categorias dos produtos"
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    );
  } else {
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={[]}
          TableTitle="Categorias dos produtos"
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    );
  }
}

export default ProductCategoryTable;
