export function calculateRevenueDifference(data, dateParam, displayType, COIN) {
  let paymentsByPeriod = {};

  // Função segura para converter string/número
  const parseAmount = (val) => parseFloat(String(val).replace(/,/g, '')) || 0;

  data.forEach(entry => {
      const entryYear = parseInt(entry.paymentdate.split("-")[2], 10);
      const amount = parseAmount(entry.totalNotFormated); // ✅ converte seguro
      if (!paymentsByPeriod[entryYear]) paymentsByPeriod[entryYear] = 0;
      paymentsByPeriod[entryYear] += amount;
  });

  const targetYear = parseInt(dateParam, 10);
  const previousYear = targetYear - 1;

  const currentRevenue = paymentsByPeriod[targetYear] || 0;
  const previousRevenue = paymentsByPeriod[previousYear] || 0;

  const revenueDifference = currentRevenue - previousRevenue;

  const revenueChangePercentage = previousRevenue
      ? ((revenueDifference / previousRevenue) * 100).toFixed(2)
      : "N/A";

  const previousChangePercentage = currentRevenue
      ? ((-revenueDifference / currentRevenue) * 100).toFixed(2)
      : "N/A";

  const trendEmoji = revenueDifference > 0 ? "📈" : revenueDifference < 0 ? "📉" : "➖";

  function formatPercentage(value) {
      if (value === "N/A") return value;
      const formattedValue = `${value}%`;
      const previousRevenueFormatted = previousRevenue.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
      return parseFloat(value) >= 0
          ? <small class="text-success">+ {COIN} {formattedValue} em relação ao ano anterior {trendEmoji} ({previousRevenueFormatted} {COIN})</small>
          : <small class="text-danger">{COIN} {formattedValue} em relação ao ano anterior {trendEmoji} ({previousRevenueFormatted} {COIN})</small>;
  }

  const percentageMessage = previousRevenue
      ? <div className="ed-flex ed-wrap">{formatPercentage(revenueChangePercentage)}</div>
      : <small className="text-warning">Não existem dados anteriores para avaliação</small>;

  return {
      revenueDifference: {
          period: targetYear,
          revenue: currentRevenue.toFixed(2),
          previousPeriod: previousYear,
          previousRevenue: previousRevenue.toFixed(2),
          difference: revenueDifference.toFixed(2),
          percentageChangeFromPrevious: formatPercentage(revenueChangePercentage),
          percentageChangeFromCurrent: formatPercentage(previousChangePercentage),
          trend: trendEmoji,
          message: percentageMessage
      },
      projectedChange: {
          tenPercentMore: (currentRevenue * 1.1).toFixed(2),
          tenPercentLess: (currentRevenue * 0.9).toFixed(2)
      }
  };
}



export function calculateCategoryPercentage(paymentsTransport, paymentsTuition, paymentsServices, paymentsSales, displayPercentageFor) {
  let totalTransport = paymentsTransport.reduce((sum, item) => sum + item.totalNotFormated, 0);
  let totalTuition = paymentsTuition.reduce((sum, item) => sum + item.totalNotFormated, 0);
  let totalServices = paymentsServices.reduce((sum, item) => sum + item.totalNotFormated, 0);
  let totalSales = paymentsSales.reduce((sum, item) => sum + item.totalNotFormated, 0);
  
  let totalRevenue = totalTransport + totalTuition + totalServices + totalSales;
  
  let selectedCategoryTotal = 0;
  switch (displayPercentageFor) {
      case 1: selectedCategoryTotal = totalTuition; break;
      case 2: selectedCategoryTotal = totalTransport; break;
      case 3: selectedCategoryTotal = totalServices; break;
      case 4: selectedCategoryTotal = totalSales; break;
      default: return "Categoria inválida";
  }
  
  let percentage = totalRevenue ? ((selectedCategoryTotal / totalRevenue) * 100).toFixed(2) : "N/A";
  return {
      totalRevenue,
      selectedCategoryTotal,
      percentage: percentage !== "N/A" ? percentage : 0
  };
}


export function calculateTotalPayments(paymentsTransport, paymentsTuition, paymentsServices, paymentsSales) {
  const sumPayments = (payments) => 
    payments.reduce((sum, item) => sum + item.totalNotFormated, 0);

  let totalRevenue = 
    sumPayments(paymentsTransport) +
    sumPayments(paymentsTuition) +
    sumPayments(paymentsServices) +
    sumPayments(paymentsSales);

  return totalRevenue;
}



export function calculateCategoryTotals(
  paymentsTuition = [],
  paymentsServices = [],
  paymentsSales = [],
  paymentsTransport = [],
  accounts = []
) {
  let totalTuition = 0;
  let totalTransport = 0;
  let totalSales = 0;
  let totalServicesPaid = 0;
  let totalPayable = 0;
  let totalReceivable = 0;

  // Função segura para converter string/número e remover vírgulas
  const parseAmount = (val) => parseFloat(String(val).replace(/,/g, '')) || 0;

  // Função para formatar valores
  const formatCurrency = (value) => 
    parseFloat(value).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  // Processamento de contas a pagar e a receber
  accounts.forEach(item => {
    totalPayable += parseAmount(item.payable_price_totalNotFormated);
    totalReceivable += parseAmount(item.receivable_price_totalNotFormated);
  });

  // Processamento dos pagamentos
  paymentsTransport.forEach(item => {
    totalTransport += parseAmount(item.totalNotFormated);
  });

  paymentsTuition.forEach(item => {
    totalTuition += parseAmount(item.totalNotFormated);
  });

  paymentsServices.forEach(item => {
    totalServicesPaid += parseAmount(item.totalNotFormated);
  });

  paymentsSales.forEach(item => {
    totalSales += parseAmount(item.totalNotFormated);
  });

  // Construção dos objetos finais
  const totalTuitionObject = {
    total: totalTuition,
    formattedTotal: formatCurrency(totalTuition),
  };

  const totalTransportObject = {
    total: totalTransport,
    formattedTotal: formatCurrency(totalTransport),
  };

  const totalSalesObject = {
    total: totalSales,
    formattedTotal: formatCurrency(totalSales),
  };

  const totalServicesPaidObject = {
    total: totalServicesPaid,
    formattedTotal: formatCurrency(totalServicesPaid),
  };

  const totalPayableObject = {
    total: totalPayable,
    formattedTotal: formatCurrency(totalPayable),
  };

  const totalReceivableObject = {
    total: totalReceivable,
    formattedTotal: formatCurrency(totalReceivable),
  };

  return {
    totalTuitionObject,
    totalTransportObject,
    totalSalesObject,
    totalServicesPaidObject,
    totalPayableObject,
    totalReceivableObject,
  };
}

 