import React, {useState, useEffect} from 'react'
import axios from 'axios'
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import { Delete, Description, Edit , PreviewOutlined, Refresh } from '@mui/icons-material';
import Table from './Table';
import Hoot from '../../../General/components/Hoot';
import NewClassRoomModal from '../modal/NewClassRoomModal';
import DeleteModal from '../elements/DeleteModal';
import TableGrid from '../../../General/components/TableGrid';
import RefreshButton from '../../../General/components/RefreshButton';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import NewCoinModal from '../modal/NewCoinModal';

const TABLEURL = Hoot()+"eduallcoinsapi/get/";
 

const columns = [ 
  { 
   field: 'index',
   headerName: 'Nº',  
   resizable: true,
   width:90,
  }, 
   { 
    field: 'title',
    headerName: 'Moeda',  
    resizable: true,
   }, 
   { 
    field: 'code',
    headerName: 'Representação ou código',  
    resizable: true,
    width:250,
   },   
  {
    field: 'action',
    headerName: 'Ação',  
    width:90,
     resizable: true,
      cellRenderer:(props) => { 
      return   <div className="ed-flex">
      <NewCoinModal  title='Atualizar ' update='true' get={Hoot()+`eduallsinglecoinget/get/${props.data.id}`}  
        url={Hoot()+`eduallcoinupdate/update/${props.data.id}`}  toggle_btn={  
        <button classroom_code={props.data.id} className="btn-circle bg-success text-light">
            <Edit/>
        </button>  
        }/>  
     </div>;
    }
  } 
]; 
 

function CoinsTable() {
    const [data, setData] = useState([]); 
    const [load, setLoaded] = useState(false);
    const [LoadStatus, setLoadStatus] = useState(null);
  
    async function loadData(){
      setLoaded(false);
         try {
          setLoadStatus(0); 
          const response = await axios.get(TABLEURL); 
           const rows = []; 
           const rows1 = []; 
           response.data.map((item, index)=>{  
                rows.push({
                index:index+1,
                id:item.ed_coin_id,  
                code:item.ed_coin_code,
                title:item.ed_coin_title,   
                action:'',  
            })  
        });  
        setData(rows); 
        setTimeout(() => {
          setLoaded(true);
        }, 200);
        setLoadStatus(2); 
         } catch (error) {
          setLoaded(true);
          setLoadStatus(1); 
         }
    }
  
    useEffect(()=>{
        loadData();  
    },[]);
  
  if(load){
      return (
      <div>
        <TableGrid
            TableHead={columns}
            TableBody={data}  
            TableHeight={200}  
            NoSearch={true} 
            TableTitle='Moeda (apenas uma moeda por instituição)' 
            TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
    </div>
    )
  }else{
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
            TableHead={columns}
            TableBody={[]} 
            NoSearch={true} 
            TableTitle='Moeda (apenas uma moeda por instituição)' 
            TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
    </div>
    )
  } 
}

export default CoinsTable