import { AddCircleOutline, PrintOutlined, Search } from '@mui/icons-material';
import React, { useState, useRef } from 'react'
import { Form, Table } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import { ClassDataOptions, GetAcademiclevel_byclass, GetAcademicYear_byclass, GetClassroom_byclass, GetClasstitle_byclass, GetCourse_byclass, GetPeriod_byclass, SubjectDataOptions } from '../../../General/components/InstituteData';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import PdQuarterNotesTable from '../../components/Table/PdQuarterNotesTable';
import DashboardContainerWrapper from '../../components/elements/DashboardContainerWrapper';
import CustomTableContainer from '../../components/elements/CustomTableContainer';
import EmptyImage from '../../../Assets/images/svg/personal_info.svg';
import ReplaceWord from '../../../General/components/ReplaceWord';
import axios from 'axios';
import PdStudentMarksCollegeTable from '../../components/Table/PdStudentMarksCollegeTable';
import Hoot from '../../../General/components/Hoot';
const TABLEURL = Hoot() + "eduallgetstudentsbyclass/";

function PD_individualsemesternotes() {

    document.title = "Notas individuais";
    const [CurrentClass, SetCurrentClass] = useState(null);
    const [CurrentStudent, SetCurrentStudent] = useState(null);
    const [CurrentQuarter, SetCurrentQuarter] = useState(0);
    const [load, setLoaded] = useState(false);
    const ChildRef = useRef();
    const [data, setData] = useState([]);
    const [LoadStatus, setLoadStatus] = useState(null);

    async function loadData(e) {
        try {
            setLoaded(false);
            setLoadStatus(0)
            const response = await axios.get(TABLEURL + e);
            const rows = [];
            response.data.map((item, index) => {
                rows.push({
                    index: index + 1,
                    id: item.ed_student_id,
                    picture: item.ed_student_picture,
                    name: item.ed_student_name,
                    class: item.ed_student_class,
                    cicle: '',
                    status: item.ed_student_status,
                    gender: item.ed_student_gender,
                    action: '',
                })
            });
            setData(rows);
            setTimeout(() => {
                setLoaded(true);
            }, 200);
            setLoadStatus(2);
        } catch (error) {
            setLoadStatus(1);
        }
    }


    const Run = (e, t) => {
        setLoaded(false);
        setTimeout(() => {
            if (t === "c") {
                setTimeout(() => {
                    SetCurrentClass(e);
                    loadData(e);
                }, 500);
            } else if (t === "q") {
                setTimeout(() => {
                    SetCurrentQuarter(e);
                }, 500);
            } else {
                setTimeout(() => {
                    SetCurrentStudent(e);
                }, 500);
            }
            setLoaded(true);
        }, 300);

    }

    return (
        <DashboardContainerWrapper content={
            <div>
                <div className="ed-space">
                    <div className='col'>
                        <Form>
                            <div className='search-box mx'>
                                <Form.Group>
                                    <div className="ed-flex">
                                        <Search />
                                        <div className="block  ml-2"  >
                                            <Form.Select select onChange={(e) => Run(e.target.value, "q")} >
                                                <option value="0">Iº Semestre</option>
                                                <option value="1">IIº Semestre</option>
                                            </Form.Select>
                                        </div>
                                        <div className="block ml-2">
                                            <Form.Select onChange={(e) => Run(e.target.value, "c")}>
                                                <ClassDataOptions />
                                            </Form.Select>
                                        </div>
                                        <div className="block ml-2 ">
                                            <Form.Select onChange={(e) => Run(e.target.value, "s")}>
                                                <option selected disabled>Selecionar estudante</option>
                                                {data.map((item, index) => (<option value={item.id}>{item.name}</option>))}
                                            </Form.Select>
                                        </div>
                                    </div>
                                </Form.Group>
                            </div>
                        </Form>
                    </div>
                </div>

                <CustomTableContainer title="Notas individuais do estudante" content={
                    <div className="eduall-table">
                        <div className="ed-table-container">
                            {load ? <PdStudentMarksCollegeTable StudentCode={CurrentStudent} Semester={CurrentQuarter} ClassId={CurrentClass} /> :
                                <div className='empty-search'><img loading="lazy" role="presentation" src={EmptyImage} alt="" /> </div>}
                        </div>
                    </div>
                } />
            </div>
        } />
    )
}

export default PD_individualsemesternotes
