 import React, { useState } from "react";
import { Button, ProgressBar } from "react-bootstrap";
import axios from "axios";
import { toast } from "react-hot-toast";
import Hoot from "../../../General/components/Hoot";

function ImportarEstudantesButton() {
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [status, setStatus] = useState({ total: 0, enviados: 0, falharam: 0 });

  // 🔹 Array de estudantes de exemplo

  const fakeStudents = [];
 
  const handleClick = async () => {
    setLoading(true);
    setProgress(0);
    setStatus({ total: fakeStudents.length, enviados: 0, falharam: 0 });

    let enviados = 0;
    let falharam = 0;

    for (let i = 0; i < fakeStudents.length; i++) {
      const estudante = fakeStudents[i];
      try {
        // 🔹 envia 1 aluno por vez
        await axios.post(Hoot() + "importar-estudante", estudante);

        enviados++;
      } catch (err) {
        falharam++;
        console.error("❌ Falha ao enviar:", estudante.Nome, err.message);
      }

      // 🔹 atualiza progresso + contadores
      const percent = Math.round(((i + 1) / fakeStudents.length) * 100);
      setProgress(percent);
      setStatus({ total: fakeStudents.length, enviados, falharam });
    }

    toast.success(`✅ Envio concluído: ${enviados} sucesso(s), ${falharam} falha(s).`);

    setTimeout(() => {
      setLoading(false);
      setProgress(0);
    }, 2000);
  };

  return (
    <div>
      <Button
        variant="primary"
        disabled={loading}
        onClick={handleClick}
        className="d-flex align-items-center gap-2"
      >
        {loading ? "Enviando..." : "Importar estudantes"}
      </Button>

      {loading && (
        <div className="mt-3">
          <ProgressBar animated now={progress} label={`${progress}%`} />
          <div className="mt-2 text-center">
            <p>
              Total: <b>{status.total}</b> | 
              Enviados: <b>{status.enviados}</b> | 
              Falharam: <b>{status.falharam}</b>
            </p>
          </div>
        </div>
      )}
    </div>
  );
}

export default ImportarEstudantesButton;
