
export function ToggleWatchListAccordion() {
let Lists = document.querySelectorAll("body .watch-cr-list-container");
for (let a = 0; a < Lists.length; a++) {
    const List = Lists[a];
    let Acordions  =  List.querySelectorAll(".ply-section-item");
    for (let c = 0; c < Acordions.length; c++) {
        const ACD = Acordions[c];
        let ToggleBtns  =  ACD.querySelectorAll(".ply-toggle-section");
        for (let b = 0; b < ToggleBtns.length; b++) {
            const btn = ToggleBtns[b];
            btn.addEventListener("click", ()=>{
                ACD.classList.toggle("hide");
            });
        }
    }
 }
}