const Container = styled.div` 
   width:100%;

   .box-search{
      width:100%; 
      position:relative;
      margin-top:90px;


        .form-area{
            width:100%;
            height:100%;
            display:flex;
            align-items:center;
            justify-content:center;

              form{
                box-shadow:var(--ed-shadow-df);
                background:var(--ed-white);
                border-radius:60px;
                padding:5px 10px;
                width:100%;
                

                input{
                  width:100%; 
                  border:none !important;
                }
              }
        } 
      }
 
       .content{ 
          width:100%;
          padding:40px 20px;
       }

       .filters, 
       .result-area{
          display:block;  
          padding:20px;
          position:relative;  
          min-height:200px;
       }

 
       .result-area{
           width:100%; 

             .card{ 
                height:375px;
                width:280px;
                border-radius:10px;
                overflow:hidden;
                position:relative;
                margin:10px;

                .user{
                    img{
                        height:100%;
                        width:100%;
                    }
                }

                   .dets{
                      position:absolute;
                      top:0px;
                      left:0px;
                      width:100%;
                      height:100%;
                      padding:10px;
                         
                   }
             }
       }



`;

export default MentorShip