function MenuLeft(props) {
   let colorIndex = 0; // Índice global para cores

   return (
      <Container className='menu-left nav-theme'>

         {props.data.user_student_accounts.length === 0 && props.data.user_institutes.length === 0 && props.data.user_childs.length === 0 ?
            <div className="ed-block mt-4">
               <section className='p-4  empy-spaces ed-flex'>
                 <div className="empty-image">
                   <img src={EmptyImg} />
                 </div>
                 <div className="pd-1 pd1"></div>
                  <div className="rounded-xl shadow-md bg-white text-gray-800">
                     <h2 className="text-xl title font-semibold mb-2">Bem-vindo ao Eduall Workspaces</h2>
                     <p className="mb-4 grey-text">
                        Este é o seu espaço central de acesso aos portais do <strong>Estudante</strong>, <strong>Encarregado</strong> e <strong>Professor</strong> — tudo com uma única conta Eduall, mesmo que esteja ligado a várias escolas.
                     </p>
                     <p className="mb-2 grey-text">
                        No momento, sua conta ainda não foi associada por nenhuma instituição.
                     </p>
                     <ul className="list-disc grey-text list-inside space-y-1 mb-4">
                        <li><strong>Estudante:</strong> A escola pode associar sua conta a vários perfis (ex: estudante do ensino geral e técnico).</li>
                        <li><strong>Encarregado:</strong> Pode aceder com uma só conta aos portais de vários filhos, mesmo da mesma escola.</li>
                        <li><strong>Professor:</strong> Pode ter acesso a um portal de professor por escola onde for funcionário.</li>
                     </ul>
                     <p className='text-main'>
                        Assim que sua conta for associada, os portais aparecerão automaticamente aqui. Gestão simples, prática e centralizada.
                     </p>
                  </div>

               </section>
            </div>
            : ""}


         <div className={props.data.user_student_accounts.length >= 1 || props.data.user_institutes.length >= 1 || props.data.user_childs.length >= 1
            ? "mt-4 details" : "d-none"} >
            <div className="ed-flex ed-wrap ed-space-header">
               <div> <h5 className={props.data.user_student_accounts.length < 1 ? "d-none theme-light-txt" : "theme-light-txt"} >Contas de estudante<span className="grey-text mr-2 mb-2">({props.data.user_student_accounts.length})</span> </h5></div>
               <div> <h5 className={props.data.user_institutes.length < 1 ? "d-none theme-light-txt" : "theme-light-txt"} >Contas de professor<span className="grey-text mr-2 mb-2">({props.data.user_institutes.length})</span> </h5></div>
               <div><h5 className={props.data.user_childs.length < 1 ? "d-none theme-light-txt" : "theme-light-txt"} >Contas de encarregado<span className="grey-text mr-2 mb-2">({props.data.user_childs.length})</span> </h5></div>
            </div>
            <ul className='workspaces-card' >
               <menu className='ed-wrap ed-flex'>
                  {/* Loop para as contas de estudante */}
                  {props.data.user_student_accounts.map((item, index) => {
                     const color = gradientColors[colorIndex] || gradientColors[0];
                     colorIndex = (colorIndex + 1) % gradientColors.length; // Avançar o índice da cor para o próximo item
                     return (
                        <article key={index}>
                           <li>
                              <Link to={`student_portal/${item.ed_student_id}`} >
                                 <div key={index} className="gradient-box" style={{ backgroundImage: color }}></div>
                              </Link>
                              <div className="det">
                                 <div className="avatar-box">
                                    <Link to={`student_portal/${item.ed_student_id}`} >
                                       <div className="ed-flex">
                                          <Avatar className="df"  src={Hoot() + item.ed_student_picture} sx={{ width: 45, height: 45 }} alt={item.ed_student_name} />
                                          <div className="name ml-2 text-dark"><ReduceTextLength text={item.ed_student_name} length="25" /></div>
                                       </div>
                                    </Link>
                                 </div>
                                 <div className="block">
                                    <div className="ed-flex mt-1">
                                       <Avatar variant="rounded" className='nav-theme df'  src={Hoot() + item.ed_institute_logo} sx={{ width: 20, height: 20 }} />
                                       <small className="grey-text mt-2 ml-1">
                                          <ReduceTextLength text={item.ed_institute_name} length="25" />
                                       </small>
                                    </div>
                                    <div className="badge mt-2 bg-info">Conta de estudante</div>
                                 </div>
                              </div>
                           </li>
                        </article>
                     );
                  })}

                  {/* Loop para as contas de professores */}
                  {props.data.user_institutes.map((item, index) => {
                     const color = gradientColors[colorIndex] || gradientColors[0];
                     colorIndex = (colorIndex + 1) % gradientColors.length; // Avançar o índice da cor para o próximo item
                     return (
                        <article key={index}>
                           <li>
                              <Link to={`/teacher_dashboard/${item.ed_institute_code}`} >
                                 <div key={index} className="gradient-box" style={{ backgroundImage: color }}></div>
                              </Link>
                              <div className="det">
                                 <Link to={`/teacher_dashboard/${item.ed_institute_code}`} >
                                    <div className="ed-flex mt-3">
                                       <Avatar className='nav-theme df' variant="rounded" src={Hoot() + item.ed_institute_logo} sx={{ width: 60, height: 60 }} />
                                       <div className="block-dets ml-2">
                                          <div className="name text-dark"><ReduceTextLength text={item.ed_institute_name} length="15" /> </div>
                                          <small className="grey-text">Professor</small>
                                       </div>
                                    </div>
                                    <div className="badge mt-2 bg-warning">Conta de professor</div>
                                 </Link>
                              </div>
                           </li>
                        </article>
                     );
                  })}

                  {/* Loop para as contas de encarregados */}
                  {props.data.user_childs.map((item, index) => {
                     const color = gradientColors[colorIndex] || gradientColors[0];
                     colorIndex = (colorIndex + 1) % gradientColors.length; // Avançar o índice da cor para o próximo item
                     return (
                        <article key={index}>
                           <li>
                              <Link to={`parent_portal/${item.ed_student_id}`} >
                                 <div key={index} className="gradient-box" style={{ backgroundImage: color }}></div>
                              </Link>
                              <div className="det">
                                 <div className="avatar-box">
                                    <Link to={`parent_portal/${item.ed_student_id}`} >
                                       <div className="ed-flex">
                                          <Avatar className="df"  src={Hoot() + item.ed_student_picture} sx={{ width: 45, height: 45 }} alt={item.ed_student_name} />
                                          <div className="name ml-2 text-dark ml-1"><ReduceTextLength text={item.ed_student_name} length="25" /></div>
                                       </div>
                                    </Link>
                                 </div>
                                 <div className="block">
                                    <div className="ed-flex mt-1">
                                       <Avatar variant="rounded" className='nav-theme df'  src={Hoot() + item.ed_institute_logo} sx={{ width: 20, height: 20 }} />
                                       <small className="grey-text mt-2 ml-1">
                                          <ReduceTextLength text={item.ed_institute_name} length="25" />
                                       </small>
                                    </div>
                                    <div className="badge mt-2 bg-danger">Conta de encarregado</div>
                                 </div>
                              </div>
                           </li>
                        </article>
                     );
                  })}
               </menu>
               <br />
            </ul>
         </div>
      </Container>
   );
}




const Container = styled.div` 
   width:100%; 
   background:var(--ed-white); 
   border-radius:6px; 
   overflow:hidden;
   margin:20px 0px; 
   box-shadow:var(--ed-shadow-df);
   min-height:250px; 
   text-align:left; 
   padding-bottom:20px;

   .empty-image img{
      min-width:250px;
      max-width:350px; 
    }

   .ed-space-header{
      padding:10px 40px;
      border-bottom:1px solid var(--ed-silver-light);   
      margin-bottom:20px;  
    }

   ul{
       margin:0px; 
       padding:0px;
       list-style:none;

       li{
         margin:0px; 
         padding:0px;
         list-style:none;
       }
   }

   menu.ed-wrap{
       margin:0px;
       gap:15px;

        .det{
           padding:15px;
       }
   }

   article{
      width:calc(25% -  16px);
      min-width:250px;
      min-height:240px;
      border:1px solid var(--ed-silver-light);
      border-radius:6px;
      overflow:hidden;

      .gradient-box{
         width:100%;
         height:100px; 
          background-size: cover;
         background-position: center;
       }
   }
`;

export default MenuLeft