import React, { useEffect, useState } from 'react'
import Table from './Table';  
import axios from 'axios';
import { Delete,  Edit, Refresh} from '@mui/icons-material';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';

import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import NewRequestModal from '../modal/NewRequestModal';
import TableGrid from '../../../General/components/TableGrid';
import { Badge } from 'react-bootstrap';
import moment from 'moment';
import { Avatar } from '@mui/material';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import RefreshButton from '../../../General/components/RefreshButton';

const TABLEURL = Hoot()+"eduallgetrequests/get"; 

const RequestTypes  = [
  "",
  <Badge bg='info'><div className="text-dark">Boletim de notas</div></Badge>,
  <Badge bg='warning'><div className="text-dark">Transferencia escolar</div></Badge>,
  <Badge bg='primary'><div className="text-dark">Declaração estudantil</div></Badge>,
  <Badge bg='success'><div className="text-dark">Extrato geral do aluno</div></Badge>,
  <Badge bg='danger'><div className="text-dark">Outro</div></Badge>
];

 
 
const columns = [ 
    { 
     field: 'index',
     headerName: 'Nº',
     width:90,  
     resizable: true,
    },
    { 
      field: 'name',
      headerName: 'Nome',  
      resizable: true, 
      width:300,
      cellRenderer:(props)=>{
         return    <SwitchFromPages link={`studentinfo/${props.data.studentcode}`}
         menu='3'  menu_item='17'  toggle_btn={
         <div className='ed-flex'>
           <Avatar alt={props.data.name}   src={props.data.picture !== ""  ?  Hoot()+props.data.picture : ""} /> 
           <span className='ml-2'>{props.data.name}</span>
         </div>
       } />
      }
     },
     { 
      field:'type',
      headerName:'Tipo de solicitação',  
      resizable: true,
      width:240,
      cellRenderer:(props)=>{
        return <>{RequestTypes[props.data.type]}</>
      }
     },   
    { 
        field:'registerDate',
        headerName:'Data de solicitação',  
        resizable: true,
    },  
    { 
        field: 'status',
        headerName: 'Status',  
        resizable: true,
        width:140, 
        cellRenderer:(props)=>{
          return  <div className="ed-flex ed-center text-center"> 
           {
             props.data.status === 0 ? 
           <div className="ed-flex">
                <div className="dot-table bg-red"></div>
                <span className="ml-2">Pendente</span>
           </div> : 
            <div className="ed-flex">
               <div className="dot-table bg-green"></div>
               <span className="ml-2">Entregue</span>
            </div>
          }
      </div>
      }
    },  
    {
      field: 'action',
      headerName: 'Ação',  
       resizable: true,
        cellRenderer:(props) => { 
        return   <div className="ed-flex">
        <NewRequestModal  title='Atualizar ' update='true' get={Hoot()+`eduallgetsinglerequest/get/${props.data.id}`}  
         url={Hoot()+`eduallrequestupdate/update/${props.data.id}`} 
          toggle_btn={
           <button className="btn-circle btn-edit-timing bg-success text-light">
              <Edit/>
            </button> 
          }
        />
       <DeleteModal title='está solicitação' url={Hoot()+`eduallrequestdelete/delete/${props.data.id}`} 
          message='Solicitação deletada com sucesso !' toggle_btn={
           <button className="btn-circle btn-delete-timing bg-danger ml-2 text-light">
           <Delete/>
       </button>
          }/> 
     </div>
      }
    } 
  ];
function RequestsTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData(){
   try {
     setLoaded(false); 
     setLoadStatus(0);
       const response = await axios.get(TABLEURL);
       const rows = []; 
         response.data.map((item, index)=>{   
           rows.push({
             index:index+1,
             id:item.ed_request_id,
             picture:item.ed_student_picture,
             studentcode:item.ed_student_id,
             name:item.ed_student_name,    
             type:item.ed_request_type,
             status:item.ed_request_status,
             action:'',  
             registerDate:moment(item.ed_request_registerDate).format("YYYY-MM-DD HH:mm:ss"),
          }) 
           });  
       setData(rows); 
       setTimeout(() => {
         setLoaded(true); 
       }, 200);
       setLoadStatus(2);
   } catch (error) {
    setLoadStatus(1);
   }
  }

  useEffect(()=>{
      loadData(); 
  },[]);

 


if(load){
    return (
    <div>
      <TableGrid
          TableHead={columns}
          TableBody={data} 
          TableTitle='Solicitações'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
      />
  </div>
  )
}else{
  return (
    <div>
      <div className="d-none">*</div>
      <TableGrid
          TableHead={columns}
          TableBody={[]} 
          TableTitle='Solicitações'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
      />
  </div>
  )
}
}

export default RequestsTable