import React, { useRef, useState } from 'react';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap';
import { Save, Update } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import { toast } from 'react-hot-toast';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import { GetInstituteCode } from '../../../General/components/InstituteData';
import RefreshList from '../../../General/components/RefreshList';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import { ImagePreview } from '../elements/ImagePreview';
import UserOptionDropDown from '../elements/UserOptionDropDown';

function NewContactModal(props) {
    const [show, setShow] = useState(false);
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [showBox, setShowBox] = useState(false);
    const [ContactImageCover, SetContactImageCover] = useState("");
    const [form, setForm] = useState({});
    const [errors, setErrors] = useState({});
    const ChildRef = useRef();
    const [Image, setImage] = useState([]);

    const handleClose = () => {
        setShowBox(false);
        setTimeout(() => {
            setShow(false);
        }, 1200);
    };

    const handleShow = () => {
        setShowBox(true);
        SetContactImageCover("");
        setShow(true);
        setTimeout(() => {
            GET_DATA();
        }, 1000);
    };

    const GetAvatarImage = (e) => {
        setImage(e);
    }

    const FORMURL = [
        Hoot() + "eduallregisterinstitutecontact/post",
        props.get ? props.get : '',
        props.url ? props.url : ''
    ];

    const INPUTS = {
        contact_name: CRValue("#contact_name"),
        contact_phone: CRValue("#contact_phone"),
        contact_address: CRValue("#contact_address"),
        contact_email: CRValue("#contact_email"),
        contact_type: CRValue("#contact_type"),
    };

    const GET_DATA = async () => {
        if (props.update) {
            try {
                const response = await axios.get(FORMURL[1]);
                if (response.data.length > 0) {
                    INPUTS.contact_name = response.data[0].ed_contact_name;
                    INPUTS.contact_phone = response.data[0].ed_contact_phone;
                    INPUTS.contact_address = response.data[0].ed_contact_address;
                    INPUTS.contact_email = response.data[0].ed_contact_email;
                    INPUTS.contact_type = response.data[0].ed_contact_type;

                    setField("contact_name", response.data[0].ed_contact_name);
                    setField("contact_phone", response.data[0].ed_contact_phone);
                    setField("contact_address", response.data[0].ed_contact_address);
                    setField("contact_email", response.data[0].ed_contact_email);
                    setField("contact_type", response.data[0].ed_contact_type);
                    SetContactImageCover(Hoot() + response.data[0].ed_contact_picture);
                } else {
                    toast.error("Não foi possível encontrar a informação selecionada!");
                }
            } catch (error) {
                toast.error("Não foi possível encontrar a informação selecionada!");
            }
        }
    };

    const setField = (field, value) => {
        setForm({
            ...form,
            [field]: value
        });
        if (!!errors[field]) {
            setErrors({
                ...errors,
                [field]: null
            });
        }
    };

    const validateForm = () => {
        const { contact_name, contact_phone, contact_type } = form;
        const NewErrors = {};
        setRegisterStatus(0);

        if (INPUTS.contact_name === "" || INPUTS.contact_name === " ") {
            if (!contact_name || contact_name === '') NewErrors.contact_name = 'Nome  invalido !';
        } else { if (!contact_name) { setField("contact_name", INPUTS.contact_name); } }

        if (INPUTS.contact_phone === "" || INPUTS.contact_phone === " ") {
            if (!contact_phone || contact_phone === '') NewErrors.contact_phone = 'Telefone invalida !';
        } else { if (!contact_phone) { setField("contact_phone", INPUTS.contact_phone); } }

        if (INPUTS.contact_type === "" || INPUTS.contact_type === " ") {
            if (!contact_type || contact_type === '') NewErrors.contact_type = 'Tipo de contacto invalido !';
        } else { if (!contact_type) { setField("contact_type", INPUTS.contact_type); } }

        return NewErrors;
    };

    const FormSubmit = (e) => {
        e.preventDefault();
        const formErrors = validateForm();
        if (Object.keys(formErrors).length > 0) {
            setErrors(formErrors);
            toast.error("Verifique todos os campos !");
            setRegisterStatus(1);
        } else {
            const formData = new FormData();
            formData.append("contact_name", INPUTS.contact_name);
            formData.append("contact_address", INPUTS.contact_address);
            formData.append("contact_phone", INPUTS.contact_phone);
            formData.append("contact_email", INPUTS.contact_email);
            formData.append("contact_type", INPUTS.contact_type);
            formData.append("contact_picture", Image);

            if (!props.update) {
                try {
                    axios.post(FORMURL[0], formData).then(() => {
                        toast.success("contacto registrado com sucesso!");
                        setForm({});
                        ClearInputs();
                        RefreshList(`.el-refresh-list`);
                        setRegisterStatus(2);
                    }).catch((error) => {
                        toast.error("Não foi possível executar esta ação!");
                        setRegisterStatus(1);
                        console.clear()
                        console.error(error.response.data);
                    });
                } catch (error) {
                    toast.error("Não foi possível executar esta ação!");
                    setRegisterStatus(1);
                    console.clear()
                    console.error(error.response.data);
                }
            } else {
                try {
                    axios.put(FORMURL[2], formData).then(() => {
                        toast.success("Contacto atualizado com sucesso !");
                        setForm({});
                        ClearInputs();
                        RefreshList(`.el-refresh-list`)
                        setRegisterStatus(2);
                        setTimeout(() => {
                            handleClose();
                        }, 1000);
                    }).catch((error) => {
                        toast.error("Lamentamos mas não foi  possivel executar esta ação !")
                        setRegisterStatus(1);
                        console.clear()
                        console.log(error.response.data);
                    });
                } catch (error) {
                    toast.error("Lamentamos mas não foi  possivel executar esta ação !")
                    setRegisterStatus(1);
                    console.clear()
                    console.log(error.response.data);
                }
            }
        }
    };

    const handleInput = (e) => {
        setField(e.target.id, e.target.value);
        INPUTS[e.target.id] = e.target.value;
    };

    return (
        <div>
            <div onClick={handleShow}>
                {props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon /> Registrar contacto</button>}
            </div>
            <Modal size='lg' dialogAs={DraggableModal} centered className={showBox ? ModalAnimationShow() : ModalAnimationClose()} show={show} onHide={handleClose}>
                <Modal.Header closeButton>
                    <Modal.Title>
                        <div className="ed-wrap align-center">
                            <UserOptionDropDown />
                            <h5> {props.title ? props.title + ' Contacto' : 'Registrar contacto'}  </h5>
                        </div>
                    </Modal.Title>
                </Modal.Header>
                <Form onSubmit={FormSubmit}>
                    <Modal.Body className='scrollLimit'>
                        <div className="ed-flex">
                            <ImagePreview Cover={ContactImageCover} ref={ChildRef} Picture={GetAvatarImage} />
                            <div className="ed-block col">
                                <Form.Group className='mb-3'>
                                    <Form.Label>Nome<span className='text-danger ml-2'>*</span></Form.Label>
                                    <Form.Control type='text' required id='contact_name' onChange={handleInput} value={form.contact_name} className={!!errors.contact_name && 'is-invalid'} />
                                    <Form.Control.Feedback type='invalid'>{errors.contact_name}</Form.Control.Feedback>
                                </Form.Group>
                                <Form.Group className='mb-3'>
                                    <Form.Label>Telefone<span className='text-danger ml-2'>*</span></Form.Label>
                                    <Form.Control type='text' required id='contact_phone' onChange={handleInput} value={form.contact_phone} className={!!errors.contact_phone && 'is-invalid'} />
                                    <Form.Control.Feedback type='invalid'>{errors.contact_phone}</Form.Control.Feedback>
                                </Form.Group>
                            </div>
                        </div>
                        <Form.Group className='mb-3 mt-2'>
                            <Form.Label>Endereço</Form.Label>
                            <Form.Control type='text' id='contact_address' onChange={handleInput} value={form.contact_address}
                                className={!!errors.contact_address && 'is-invalid'} />
                            <Form.Control.Feedback type='invalid'>{errors.contact_address}</Form.Control.Feedback>
                        </Form.Group>
                        <Form.Group className='mb-3'>
                            <Form.Label>Email</Form.Label>
                            <Form.Control type='email' id='contact_email' onChange={handleInput} value={form.contact_email}
                                className={!!errors.contact_email && 'is-invalid'} />
                            <Form.Control.Feedback type='invalid'>{errors.contact_email}</Form.Control.Feedback>
                        </Form.Group>
                        <Form.Group className='mb-3'>
                            <Form.Label>Tipo<span className='text-danger ml-2'>*</span></Form.Label>
                            <Form.Select id='contact_type' onChange={handleInput} required value={form.contact_type} className={!!errors.contact_type && 'is-invalid'}>
                                <option selected disabled>Selecione</option>
                                <option value='1'>Estudante</option>
                                <option value='2'>Encarregado</option>
                                <option value='3'>Funcionário</option>
                                <option value='4'>Outro</option>
                            </Form.Select>
                            <Form.Control.Feedback type='invalid'>{errors.contact_type}</Form.Control.Feedback>
                        </Form.Group>
                    </Modal.Body>
                    <Modal.Footer>
                        <Button className='bg-light text-dark' onClick={handleClose}>Cancelar</Button> 
                       <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} /> 
                    </Modal.Footer>
                </Form>
            </Modal>
        </div>
    );
}

export default NewContactModal;