import React, { useState } from 'react'
import UsersStudentsAccounts from '../components/Grid/UsersStudentsAccounts';
import { SearchOutline } from 'react-ionicons'
import { Link } from 'react-router-dom';
import { Form } from 'react-bootstrap';
import NewStudentUserAccountModal from '../components/modal/NewStudentUserAccountModal';
import BulkStudentUserAccountModal from '../components/modal/BulkStudentUserAccountModal';

function UsersStudentsAccountsPage() {
  document.title = "Contas de estudante";
  const [value, setValue] = useState(null);

  return (
    <div>
      <div className="ed-space">
        <div>
          <div className="alert alert-info mt-2" role="alert" style={{ fontSize: '0.9rem' }}>
            Por padrão, a senha das contas dos alunos será: <strong className='underline'><u>765*eduall#</u></strong>
          </div>
        </div>
        <div>
          <BulkStudentUserAccountModal />
        </div>
      </div>
      <UsersStudentsAccounts FilterByName={value} />
    </div>
  )
}

export default UsersStudentsAccountsPage