import React, { useState, useEffect } from 'react';
import { Modal, Form, Button, Alert } from 'react-bootstrap';
import { AddCircleOutline, Save, Update, Delete, Edit, Link as LinkIcon } from '@mui/icons-material';
import axios from 'axios';
import moment from 'moment';
import { toast } from 'react-hot-toast';
import Hoot from '../../../General/components/Hoot';
import TableGrid from '../../../General/components/TableGrid';
import RefreshButton from '../../../General/components/RefreshButton';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import DraggableModal from '../../../General/components/DraggableModal';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import { PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import NumberToPrice from '../../../General/components/NumberToPrice';
import DeleteModal from '../../components/elements/DeleteModal';
import SaveButton from '../../components/elements/SaveButton';

// ====================== MODAL ======================
function OldPaymentModal({ refreshList, title, update, getUrl, putUrl, toggle_btn }) {
  const [show, setShow] = useState(false);
  const [showBox, setShowBox] = useState(false);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});
  const [registerStatus, setRegisterStatus] = useState(null);

  const handleClose = () => {
    setShowBox(false);
    setTimeout(() => setShow(false), 500);
  };

  const handleShow = async () => {
    setShowBox(true);
    setShow(true);
    if (update && getUrl) {
      try {
        const res = await axios.get(getUrl);
        if (res.data) setForm(res.data);
      } catch (err) {
        toast.error("Falha ao carregar dados para edição!");
      }
    }
  };

  const setField = (field, value) => {
    setForm({ ...form, [field]: value });
    if (errors[field]) setErrors({ ...errors, [field]: null });
  };

  const validateForm = () => {
    const newErrors = {};
    if (!form.ed_sc_old_pay_client) newErrors.ed_sc_old_pay_client = "Cliente é obrigatório";
    if (!form.ed_sc_old_pay_value) newErrors.ed_sc_old_pay_value = "Valor é obrigatório";
    if (!form.ed_sc_old_pay_date) newErrors.ed_sc_old_pay_date = "Data é obrigatória";
    return newErrors;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique os campos obrigatórios!");
      setRegisterStatus(1);
      return;
    }

    try {
      if (update && putUrl) {
        await axios.put(putUrl, form);
        toast.success("Pagamento atualizado com sucesso!");
      } else {
        await axios.post(Hoot() + "edualloldpayments/post/", form);
        toast.success("Pagamento registrado com sucesso!");
      }
      setForm({});
      setRegisterStatus(2);
      handleClose();
      if (refreshList) refreshList();
    } catch (err) {
      toast.error("Falha ao salvar pagamento!");
      setRegisterStatus(1);
    }
  };

  return (
    <div onClick={handleShow}>
      {toggle_btn ? toggle_btn : <Button className='mb-0' onClick={handleShow}><AddCircleOutline /> {update ? "Editar" : "Registrar"} Pagamento</Button>}
      <Modal
        size="lg"
        className={showBox ? ModalAnimationShow() : ModalAnimationClose()}
        centered
        dialogAs={DraggableModal}
        show={show}
        onHide={handleClose}
      >
        <Modal.Header closeButton>
          <Modal.Title>{title || (update ? "Editar Pagamento" : "Registrar Pagamento")}</Modal.Title>
        </Modal.Header>
        <Form onSubmit={handleSubmit}>
          <Modal.Body>
            <Form.Group className="mb-3">
              <Form.Label>Cliente<span className="text-danger">*</span></Form.Label>
              <Form.Control
                type="text"
                value={form.ed_sc_old_pay_client || ""}
                onChange={e => setField("ed_sc_old_pay_client", e.target.value)}
                isInvalid={!!errors.ed_sc_old_pay_client}
              />
              <Form.Control.Feedback type="invalid">{errors.ed_sc_old_pay_client}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Banco</Form.Label>
              <Form.Control
                type="text"
                value={form.ed_sc_old_pay_bank || ""}
                onChange={e => setField("ed_sc_old_pay_bank", e.target.value)}
              />
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Valor<span className="text-danger">*</span></Form.Label>
              <Form.Control
                type="number"
                value={form.ed_sc_old_pay_value || ""}
                onChange={e => setField("ed_sc_old_pay_value", e.target.value)}
                isInvalid={!!errors.ed_sc_old_pay_value}
              />
              <Form.Control.Feedback type="invalid">{errors.ed_sc_old_pay_value}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Data<span className="text-danger">*</span></Form.Label>
              <Form.Control
                type="date"
                value={form.ed_sc_old_pay_date || ""}
                onChange={e => setField("ed_sc_old_pay_date", e.target.value)}
                isInvalid={!!errors.ed_sc_old_pay_date}
              />
              <Form.Control.Feedback type="invalid">{errors.ed_sc_old_pay_date}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Descrição</Form.Label>
              <Form.Control
                as="textarea"
                rows={3}
                value={form.ed_sc_old_pay_description || ""}
                onChange={e => setField("ed_sc_old_pay_description", e.target.value)}
              />
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <Button variant="secondary" onClick={handleClose}>Cancelar</Button>
            <SaveButton title={update ? "Atualizar" : "Salvar"} status={registerStatus} icon={update ? <Update /> : <Save />} />
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  );
}

// ====================== TABELA ======================
function OldPaymentsList() {
  const [data, setData] = useState([]);
  const [loaded, setLoaded] = useState(false);
  const [total, setTotal] = useState(0);

  const loadData = async () => {
    setLoaded(false);
    try {
      const res = await axios.get(Hoot() + "edualloldpayments/get/");
      const rows = res.data || [];
      setData(rows);
      const totalValue = rows.reduce((acc, item) => acc + Number(item.ed_sc_old_pay_value || 0), 0);
      setTotal(totalValue);
      setLoaded(true);
    } catch (err) {
      toast.error("Erro ao carregar pagamentos antigos!");
      setLoaded(true);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const columns = [
    {
      field: 'client',
      headerName: 'Cliente',
      width: 200,
      cellRenderer: (props) => props.data.ed_sc_old_pay_client || "——————"
    },
    {
      field: 'bank',
      headerName: 'Banco',
      width: 120,
      cellRenderer: (props) => props.data.ed_sc_old_pay_bank || "-"
    },
    {
      field: 'value',
      headerName: 'Valor',
      width: 170,
      cellRenderer: (props) => NumberToPrice(props.data.ed_sc_old_pay_value) + " Kz"
    },
    {
      field: 'date',
      headerName: 'Data',
      width: 150,
      cellRenderer: (props) => moment(props.data.ed_sc_old_pay_date).format('DD/MM/YYYY')
    },
    {
      field: 'year',
      headerName: 'Ano',
      width: 150,
      cellRenderer: (props) =>  props.data.ed_sc_old_pay_year || ""
    },
    {
      field: 'description',
      headerName: 'Descrição',
      width: 300,
      cellRenderer: (props) => props.data.ed_sc_old_pay_description
    },
    {
      field: 'receipt',
      headerName: 'Recibo',
      width: 100,
      cellRenderer: (props) => {
        const link = props.data.ed_sc_old_pay_receipt_link;
        const exists = link && link.trim() !== "";
        return (
          <a
            href={exists ? link : "#"}
            target="_blank"
            rel="noopener noreferrer"
            style={{ color: exists ? "blue" : "red" }}
          >
            <LinkIcon />
          </a>
        );
      }
    },
    {
      field: 'actions',
      headerName: 'Ações',
      width: 180,
      cellRenderer: (props) => (
        <div className="ed-flex"> 
          <DeleteModal
            title="este pagamento"
            url={Hoot() + `edualloldpayments/delete/${props.data.ed_sc_old_pay_id}`}
            message="Pagamento deletado com sucesso!"
            toggle_btn={<Button className="btn-circle bg-danger ml-2 text-light"><Delete /></Button>}
            refreshList={loadData}
          />
        </div>
      )
    }
  ];

  return (
    <div className='col'>
      <Alert variant="info">
        <div className="ed-space mb-3">
          <div><h5 className='mb-0 m0 m-0'>Total de pagamentos antigos: {data.length} | Valor total: {NumberToPrice(total)} Kz</h5></div> 
        </div>

      </Alert>

      {loaded ? (
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle="Pagamentos Antigos"
          TableBtn={
            <div className='ed-flex'>
              <button className='btn-icon btn btn-export-data ml-2'
                onClick={() => ExportDataForTablesExcel("Pagamentos Antigos", ["Ações"])}>
                <PiMicrosoftExcelLogoDuotone />
              </button>
              <RefreshButton action={loadData} status={loaded ? 2 : 0} />
            </div>
          }
        />
      ) : (
        <div>
           <TableGrid
          TableHead={columns}
          TableBody={[]}
          TableTitle="Pagamentos Antigos"
          TableBtn={
            <div className='ed-flex'>
              <button className='btn-icon btn btn-export-data ml-2'
                onClick={() => ExportDataForTablesExcel("Pagamentos Antigos", ["Ações"])}>
                <PiMicrosoftExcelLogoDuotone />
              </button>
              <RefreshButton action={loadData} status={loaded ? 2 : 0} />
            </div>
          }
        />
        </div>
      )}
    </div>
  );
}

// ====================== PÁGINA ======================
function OldPaymentsPage() {
  document.title = "Pagamentos Antigos da Escola";
  return (
    <div className="col">
      <OldPaymentsList />
    </div>
  );
}

export default OldPaymentsPage;
