import React, {useState} from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import {Modal, Form, Button} from 'react-bootstrap'
import { Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import { RichTextEditor } from '../../../General/components/RichTextEditor';
import {toast} from 'react-hot-toast';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import { Update } from '@material-ui/icons';
import { GetInstituteCode } from '../../../General/components/InstituteData';
import AuditoryRegister from '../../../General/components/AuditoryRegister';
import RefreshList from '../../../General/components/RefreshList';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import CountryOptions from '../../../General/components/CountryOptions';


function NewSchoolsOfProvenanceModal(props) {
  const [show, setShow] = useState(false);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [Founded, SetFounded] = useState(null);

  const [showBox, SetshowBox] = useState(false);
  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200);
  }

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };


  const INPUTS = {
    schools_of_provenance_name: CRValue("#schools_of_provenance_name"),
    schools_of_provenance_address: CRValue("#schools_of_provenance_address"),
    schools_of_provenance_country: CRValue("#schools_of_provenance_country"),
    schools_of_provenance_email: CRValue("#schools_of_provenance_email"),
    schools_of_provenance_description: CRValue("#schools_of_provenance_description"),
  };


  const FORMURL = [
    Hoot() + "eduallregisterschoolofprovenance/post",
    props.get ? props.get : '',
    props.url ? props.url : ''
  ];


  async function GET_DATA() { 
      if (props.update) {
        try {
          const response = await axios.get(FORMURL[1]);
          if (response.data.length > 0) {
            document.querySelector("#schools_of_provenance_name").value = response.data[0].ed_schools_of_provenance_name;
            document.querySelector("#schools_of_provenance_address").value = response.data[0].ed_schools_of_provenance_address;
            document.querySelector("#schools_of_provenance_country").value = response.data[0].ed_schools_of_provenance_country;
            document.querySelector("#schools_of_provenance_email").value = response.data[0].ed_schools_of_provenance_email;
            document.querySelector("#schools_of_provenance_description").value = response.data[0].ed_schools_of_provenance_description;

            INPUTS.schools_of_provenance_name = response.data[0].ed_schools_of_provenance_name;
            INPUTS.schools_of_provenance_address = response.data[0].ed_schools_of_provenance_address;
            INPUTS.schools_of_provenance_country = response.data[0].ed_schools_of_provenance_country;
            INPUTS.schools_of_provenance_email = response.data[0].ed_schools_of_provenance_email;
            INPUTS.schools_of_provenance_description = response.data[0].ed_schools_of_provenance_description;
          } else {
            toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
          }
        } catch (error) {
          toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
        }
      } 
  }
 

  const setField = (field, value) => {
    setForm({
      ...form,
      [field]: value
    })

    if (!!errors[field]) {
      setErrors({
        ...errors,
        [field]: null
      });
    }
  }


  const validateForm = () => {
    const { schools_of_provenance_name, schools_of_provenance_address, schools_of_provenance_country, schools_of_provenance_email } = form;
    const NewErrors = {};
    setRegisterStatus(0);  

    if (INPUTS.schools_of_provenance_name === "" || INPUTS.schools_of_provenance_name === " ") {
      if (!schools_of_provenance_name || schools_of_provenance_name === '') NewErrors.schools_of_provenance_name = 'Nome da escola invalido';
    } else { if (!schools_of_provenance_name) { setField("schools_of_provenance_name", INPUTS.schools_of_provenance_name); } }

    if (INPUTS.schools_of_provenance_country === "" || INPUTS.schools_of_provenance_country === " ") {
      if (!schools_of_provenance_country || schools_of_provenance_country === '') NewErrors.schools_of_provenance_country = 'Selecione uma opção valida';
    } else { if (!schools_of_provenance_country) { setField("schools_of_provenance_country", INPUTS.schools_of_provenance_country); } }

    if (INPUTS.schools_of_provenance_address === "Preencha corretamente o campo" || INPUTS.schools_of_provenance_address === " ") {
      if (!schools_of_provenance_address || schools_of_provenance_address === '') NewErrors.schools_of_provenance_address = 'Endereço invalido';
    } else { if (!schools_of_provenance_address) { setField("schools_of_provenance_address", INPUTS.schools_of_provenance_address); } }
 
    return NewErrors;
  }



  const FormSubmit = (e) => {
    e.preventDefault();
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os  campos !");
      setRegisterStatus(1);  
    } else {
      const SUBMIT_INPUTS = {
        schools_of_provenance_name: INPUTS.schools_of_provenance_name,
        schools_of_provenance_country: INPUTS.schools_of_provenance_country,
        schools_of_provenance_email: INPUTS.schools_of_provenance_email,
        schools_of_provenance_address: INPUTS.schools_of_provenance_address,
        schools_of_provenance_description: INPUTS.schools_of_provenance_description,
      };

      if (!props.update) {
        try {
          axios.post(FORMURL[0], SUBMIT_INPUTS).then(()=>{  
            toast.success("Escola de info@eduall.aoência adicionada com sucesso !");
            setForm({});
            ClearInputs();
            RefreshList(`.el-refresh-list`)
            setRegisterStatus(2);   
          }).catch((error)=>{
            setRegisterStatus(1);  
            console.clear()
            console.log(error.response)
            toast.error("Lamentamos mas não foi  possivel executar esta ação !")
          }); 
        } catch (error) {
          setRegisterStatus(1);  
          console.clear()
          console.log(error.response)
          toast.error("Lamentamos mas não foi  possivel executar esta ação !");
        }
       } else {
          try {
            axios.put(FORMURL[2], SUBMIT_INPUTS) .then(()=>{  
              toast.success("Escola de info@eduall.aoência com sucesso !");
              setForm({});
              ClearInputs();
              RefreshList(`.el-refresh-list`)
              setRegisterStatus(2);  
              setTimeout(() => {
                handleClose(); 
              }, 1000);
            }).catch((error)=>{
              setRegisterStatus(1);  
              console.clear()
              console.log(error.response)
              toast.error("Lamentamos mas não foi  possivel executar esta ação !");
            }); 
          } catch (error) {
            setRegisterStatus(1);  
            console.clear()
            console.log(error.response)
            toast.error("Lamentamos mas não foi  possivel executar esta ação !");
          }
       }

    }
  };


  const handleInput = (e) => {
    switch (e.target.id) {
      case "schools_of_provenance_name":
        setField("schools_of_provenance_name", e.target.value);
        INPUTS.schools_of_provenance_name = e.target.value
        break;
      case "schools_of_provenance_email":
        setField("schools_of_provenance_email", e.target.value);
        INPUTS.schools_of_provenance_email = e.target.value
        break;
      case "schools_of_provenance_address":
        setField("schools_of_provenance_address", e.target.value);
        INPUTS.schools_of_provenance_address = e.target.value
        break;
      case "schools_of_provenance_country":
        setField("schools_of_provenance_country", e.target.value);
        INPUTS.schools_of_provenance_country = e.target.value
        break;
      case "schools_of_provenance_description":
        setField("schools_of_provenance_description", e.target.value);
        INPUTS.schools_of_provenance_description = e.target.value
        break;
    }
  }



  return (
    <div>
      <div onClick={handleShow}>
        {props.toggle_btn ? props.toggle_btn : (
          <button className='btn btn-main bg-main' onClick={handleShow}>
            <AddCircleOutlineIcon /> Registrar escola de info@eduall.aoência
          </button>
        )}
      </div>
      <Modal
        size='lg'
        className={showBox ? ModalAnimationShow() : ModalAnimationClose()}
        centered
        dialogAs={DraggableModal}
        show={show}
        onHide={handleClose}
      >
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>{props.title ? props.title : 'Registrar '} escola de info@eduall.aoência</h5>
            </div>
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={FormSubmit}>
          <Modal.Body className='scrollLimit'>
            <Form.Group className="mb-3">
              <Form.Label>Nome da escola<span className="text-danger ml-2">*</span></Form.Label>
              <Form.Control
                onChange={handleInput}
                className={!!errors.schools_of_provenance_name && 'is-invalid'}
                value={form.schools_of_provenance_name}
                isInvalid={!!errors.schools_of_provenance_name}
                type="text"
                id="schools_of_provenance_name"
                autoFocus
              />
              <Form.Control.Feedback type='invalid'>{errors.schools_of_provenance_name}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Email</Form.Label>
              <Form.Control
                onChange={handleInput}
                className={!!errors.schools_of_provenance_email && 'is-invalid'}
                value={form.schools_of_provenance_email}
                isInvalid={!!errors.schools_of_provenance_email}
                type="email"
                id="schools_of_provenance_email"
              />
              <Form.Control.Feedback type='invalid'>{errors.schools_of_provenance_email}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Endereço</Form.Label>
              <Form.Control
                onChange={handleInput}
                className={!!errors.schools_of_provenance_address && 'is-invalid'}
                value={form.schools_of_provenance_address}
                isInvalid={!!errors.schools_of_provenance_address}
                type="text"
                id="schools_of_provenance_address"
              />
              <Form.Control.Feedback type='invalid'>{errors.schools_of_provenance_address}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>País</Form.Label>
              <Form.Select
                onChange={handleInput}
                className={!!errors.schools_of_provenance_country && 'is-invalid'}
                value={form.schools_of_provenance_country}
                isInvalid={!!errors.schools_of_provenance_country}
                type="text"  
                id="schools_of_provenance_country"
              >
                <option selected disabled>Selecione um país</option>
                <CountryOptions/>
              </Form.Select>
              <Form.Control.Feedback type='invalid'>{errors.schools_of_provenance_country}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Descrição</Form.Label>
               <textarea onChange={handleInput} id="schools_of_provenance_description" rows={10} className="form-control"></textarea>
              <Form.Control.Feedback type='invalid'>{errors.schools_of_provenance_description}</Form.Control.Feedback>
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <div className="ed-space">
              <div className="ed-flex"></div>
              <div className="ed-flex">
                <Button className='bg-light text-dark' onClick={handleClose}>Cancelar</Button>
                {props.update ? (
                  Founded === false ? <div></div> : (
                    <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />
                  )
                ) : (
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />
                )}
              </div>
            </div>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  );

}

export default NewSchoolsOfProvenanceModal;

