import React, { useEffect, useState } from 'react';
import axios from 'axios';
import jwt_decode from 'jwt-decode';
import { useGoogleLogin } from '@react-oauth/google';
import { FcGoogle } from 'react-icons/fc';  
import Hoot from '../General/components/Hoot';

function GoogleOneTap({ setShowScreen, setRegisterStatus, setMessagewarning, hideMessage }) {
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  useEffect(() => {
    const checkSession = async () => {
      try {
        const res = await axios.get(Hoot() + "token");
        const token = res.data?.accessToken;
        if (token) {
          const decoded = jwt_decode(token);
          if (decoded) {
            setIsAuthenticated(true);  
          }
        }
      } catch {
        setIsAuthenticated(false);
      }
    };
    checkSession();
  }, []);

  async function fetchGoogleUser(accessToken) {
    try {
      const res = await axios.get("https://www.googleapis.com/oauth2/v3/userinfo", {
        headers: { Authorization: `Bearer ${accessToken}` },
        withCredentials: false,
      });
      await handleLoginGoogle(res.data);
      return res.data;
    } catch (err) {
      setRegisterStatus(1);
      setMessagewarning("Erro ao conectar com o Google. Tente novamente!");
      return null;
    }
  }

  const handleLoginGoogle = async (data) => {
    try {
      if (!data) throw new Error("Dados do usuário não disponíveis");
      const res = await axios.post(Hoot() + "google-auth", { payload: data }, { withCredentials: true });
      hideMessage();
      if (res.data.accessToken) {
        const decoded = jwt_decode(res.data.accessToken); 
        setShowScreen(false);
        setRegisterStatus(2);  
        if (decoded.cr_usertype === 1) {
          window.location.replace("/WorkSpaces");
        } else {   
          window.location.replace("/dashboard");
        }
        if (window.google?.accounts?.id) {
          window.google.accounts.id.cancel();
        }
      } else {
        throw new Error("Resposta inválida do servidor");
      } 
    } catch (error) { 
      setRegisterStatus(1);
      setMessagewarning(
        error.response?.data?.msg || error.message || "Não foi possível concluir a operação. Tente novamente em instantes !"
      );
    } 
  }; 

  const Auth = useGoogleLogin({
    onSuccess: tokenResponse => fetchGoogleUser(tokenResponse?.access_token),
    onError: () => {
      setRegisterStatus(1);
      setMessagewarning("Falha ao tentar autenticar com o Google!");
    },
  });
 
 
  return (
    <div className="col"> 
      <button 
        onClick={() => Auth()}  
        className='btn box-theme theme-light-txt mt-2 bg-white text-dark btn-social'
      >
        <FcGoogle /> <span className="theme-light-txt">Continuar com Google</span>
      </button>
    </div>
  );
}

export default GoogleOneTap;
