import React from 'react'
import styled from 'styled-components'

function TitleBlock(props){
  return (
    <Block  style={{marginBottom:`${props.nomargin ? "0px" : "40px"} `}} >
        <h1>
             <div className='txt ed-flex' >
                 {props.title ? props.title : ''}  
                 {props.maintext ? <div className="grey-text ml-1">({props.maintext ? props.maintext  : ""})</div>  : <></>}
              </div>
            <div className="line bg-main"></div>
        </h1>
    </Block>
  )
}


const Block = styled.div`  
    h1{
      position:relative;
      margin:0px;
      width:max-content;
      font-size:18px;
      color:var(--black);
      font-weight:bold;
      display:block;
       
        .line{ 
            position:absolute;
            left:0px;
            top:30px;
            width:90%;
            height:5px;
            border-radius:30px;
        }
    }
`;

export default TitleBlock