import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Delete, Edit } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import TableGrid from '../../../General/components/TableGrid';
import { Badge } from 'react-bootstrap';
import EditUserModal from '../modal/EditUserModal';
import Switch from 'react-bootstrap/Switch';
import { Avatar } from '@mui/material';
import { GetJobTitle } from '../../../General/components/InstituteData';
import RefreshButton from '../../../General/components/RefreshButton';
import { toast } from 'react-hot-toast';
import RefreshList from '../../../General/components/RefreshList';

const TABLEURL = Hoot() + 'eduallinstituteuseraccountsget/get';

const toggleAccountStatus = async (id, currentStatus) => {
  try {
    await axios.put(Hoot() + `edualluserinstituteaccountdelete/delete/${id}`, { status: currentStatus === 0 ? 1 : 0 });
    RefreshList(`.el-refresh-list`);
    toast.success("Estado da conta atualizado com sucesso!");
  } catch (error) {
    toast.error("Erro ao atualizar estado da conta!");
    console.clear();
    console.error("Erro ao atualizar status do usuário", error.response);
  }
};


const columns = [
  {
    field: 'index',
    headerName: 'Nº',
    width: 90,
    resizable: true,
  },
  {
    field: 'username',
    headerName: 'Nome de usuário',
    width: 190,
    resizable: true,
  },

  {
    field: 'name',
    headerName: 'Nome',
    resizable: true,
    cellRenderer: (props) => (
      <div className='ed-flex'>
        <Avatar className='df' alt={props.data.name} src={props.data.picture !== "" ? Hoot() + props.data.picture : ""} />
        <span className='ml-2'>{props.data.name}</span>
      </div>
    )
  },
  {
    field: 'email',
    headerName: 'Email',
    resizable: true,
  },
  {
    field: 'charge',
    headerName: 'Cargo',
    sortable: false,
    cellRenderer: (props) => <GetJobTitle ID={props.data.charge} />
  },
  {
    field: 'status',
    headerName: 'Estado',
    width: 120,
    resizable: true,
    cellRenderer: (props) => (
     <div className="mt-2">
       <Switch   checked={props.data.status === 0}
        onChange={() => toggleAccountStatus(props.data.id, props.data.status)}
      />
     </div>
    )
  },
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true,
    width: 80,
    cellRenderer: (props) => (
      <div className="ed-flex">
        <EditUserModal title='Atualizar ' update='true' get={Hoot() + `eduallgetsinglesystemuseracccount/get/${props.data.id}`}
          url={Hoot() + `edualluserinstituteaccountupdate/update/${props.data.id}`} toggle_btn={
            <button className="btn-circle btn-edit-timing bg-success text-light">
              <Edit />
            </button>
          } />
      </div>
    )
  }
];

function UsersAccountTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData() {
    try {
      setLoaded(false);
      setLoadStatus(0);
      const response = await axios.get(TABLEURL);
      console.clear();
      console.log("data", response.data);
      const rows = response.data.map((item, index) => ({
        id: item.ed_system_account_id,
        username: item.ed_system_account_name,
        name: item.ed_employee_name,
        index: index + 1,
        picture: item.ed_employee_picture,
        email: item.ed_employee_email,
        charge: item.ed_employee_charge,
        status: item.ed_system_account_deleted * 1,

      }));
      setData(rows);
      setLoaded(true);
      setLoadStatus(2);
    } catch (error) {
      setLoadStatus(1);
      setLoaded(false);
      console.clear();
      console.log(error);
    }
  }

  useEffect(() => {
    loadData();
  }, []);



  if (load) {
    return (
      <div>
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle={'Contas de usuários da instituição'}
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    )
  } else {
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle={'Contas de usuários da instituição'}
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>)
  }

}

export default UsersAccountTable;

 