import React ,{useState, useEffect} from 'react'
import Table from './Table'
import { Delete, Description, Edit ,OpenInBrowser, Refresh } from '@mui/icons-material';
import { Link } from 'react-router-dom';
import axios from 'axios'
import Hoot from '../../../General/components/Hoot'; 
import DeleteModal from '../elements/DeleteModal';
import NewSubject from '../modal/NewSubject';
import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import ReplaceWord from '../../../General/components/ReplaceWord';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';

const TABLEURL = Hoot()+"eduallsubjectsapi/get/"
const subject_type = ["","Teorica", "Pratica", "Teorica / Pratica"];
const Categories = ["","Designer", "Arte", "Engenharia", "Saude", "Ciencias", "Linguas"];
 
 

const columns = [ 
  { 
   field: 'index',
   headerName: 'Nº', 
   width: 90 , 
   resizable: true,
  },
  { 
      field: 'title',
      headerName: 'Nome da '+ReplaceWord("Disciplina", true),  
      resizable: true,
  }, 
   { 
    field: 'type',
    headerName: 'Tipo de '+ ReplaceWord("Disciplina", true),  
    resizable: true,
   },  
   { 
    field: 'category',
    headerName: 'Categoria',  
    resizable: true,
   },   
  {
    field: 'action',
    headerName: 'Ação',  
     resizable: true, 
     cellRenderer:(props) => { 
      return  <div className="ed-flex">
      <NewSubject title='Atualizar ' update='true' get={Hoot()+`eduallsinglesubject/get/${props.data.id}`}  
        url={Hoot()+`eduallsubjectupdate/update/${props.data.id}`}  
          toggle_btn={
           <button subject-code={props.data.id} className="btn-circle bg-success text-light">
                 <Edit/>
            </button> 
          }
      />
    <DeleteModal title={'esta ' + ReplaceWord("Disciplina", true)} url={Hoot()+`eduallsubjectdelete/delete/${props.data.id}`} message={ReplaceWord("Disciplina")+ ' deletada com sucesso'} toggle_btn={ 
     <button  className="btn-circle bg-danger ml-2 text-light">
         <Delete/>
     </button>} /> 
   </div>;
    }
  } 
];

function SubjectsTable() {  
  const [data, setData] = useState([]); 
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData(){
      try {
        setLoadStatus(0);
      setLoaded(false); 
      const response = await axios.get(TABLEURL); 
      const rows = []; 
      response.data.map((item, index)=>{  
        rows.push({
          index:index+1,
          id:item.ed_subject_id,  
          type:subject_type[Math.floor(item.ed_subject_type*1 )],
          title:item.ed_subject_title,   
          category:Categories[Math.floor(item.ed_subject_category*1)],
          action:'',  
      }); 
    });
      setData(rows); 
      setTimeout(() => {
        setLoaded(true); 
      }, 200);
      setLoadStatus(2);
      } catch (error) {
        setLoadStatus(1);
      }
  }

  useEffect(()=>{
      loadData(); 
  },[]);
  


if(load){
    return (
    <div id="ed-custom-table-data">
      <TableGrid
          TableHead={columns}
          TableBody={data} 
          TableTitle={ReplaceWord("Disciplinas")+' Académicas'}
          TableBtn={
            <div className='ed-flex' >

          <button id='ed-custom-table-data-btn'
            onClick={() =>
              ExportDataToTablesToPdf({
                fileName: "Lista das "+ReplaceWord("Disciplinas") + " Académicas",
                headerId: null,
                contentId: "ed-custom-table-data",
                footerId: null,
                rotation: "portrait",
                buttonId: "ed-custom-table-data-btn",
                customHeader: "Lista das "+ReplaceWord("Disciplinas")+ " Académicas",
                excludedColumns: ["Ação"]
              })
            }
            className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
          </button>

            <button className='btn-icon btn btn-export-data ml-2' 
               onClick={()=>ExportDataForTablesExcel(ReplaceWord("Disciplinas"), ["Ação"])}><PiMicrosoftExcelLogoDuotone />
            </button>
           <RefreshButton action={loadData} status={LoadStatus} />
       </div>}
      />
  </div>
  )
}else{
  return (
    <div>
      <div className="d-none">*</div>
      <TableGrid
          TableHead={columns}
          TableBody={data} 
          TableTitle={ReplaceWord("Disciplinas")+' Académicas'}
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
      />
  </div>
  )
}
}

export default SubjectsTable