import React, { useEffect, useMemo, useState, useCallback, useRef } from "react";
import styled from "styled-components";
import { Badge, Form } from "react-bootstrap";
import { Avatar } from "@mui/material";
import { Edit, Delete, Check, Close } from "@mui/icons-material";
import axios from "axios";
import { PiMicrosoftExcelLogoDuotone } from "react-icons/pi";
import TableGrid from "../../../../General/components/TableGrid";
import QuarterlyNotesModal from "../../../../Dashboard/components/modal/Pedagogy/QuarterlyNotesModal";
import DeleteModal from "../../../../Dashboard/components/elements/DeleteModal";
import ExportDataForTablesExcel from "../../../../General/components/ExportDataForTablesExcel";
import Hoot from "../../../../General/components/Hoot";
import { GetClasstitle_byclass, GetSubject } from "../../../../General/components/InstituteData";
import RefreshButton from "../../../../General/components/RefreshButton";
import ReplaceWord from "../../../../General/components/ReplaceWord";
import CRValue from "../../../../General/components/CRValue";
import CalculateNote from "../../../../General/components/CalculateNote";
import FloorNumber from "../../../../General/components/FloorNumber";
import MessageTypeSelectorSend from "../../../../General/components/MessageTypeSelectorSend";

const DATA_URL = [
  Hoot() + "eduallsingleclassapi/get/",
  Hoot() + "eduallsingleacademiclevelsapi/get/",
];

const CACHE_TTL = 30 * 60 * 1000; // 30 min

const StatusType = {
  aprovado: (
    <Badge bg="success">
      <Check /> Aprovado
    </Badge>
  ),
  reprovado: (
    <Badge bg="danger">
      <Close /> Reprovado
    </Badge>
  ),
};

const GetColor = (value, max) =>
  value < max / 2 ? (
    <span className="text-danger">{value}</span>
  ) : (
    <span className="text-success">{value}</span>
  );

const FinalScore = (md, exam, special) => {
  if (md > 13) return md;
  if (Math.floor((exam + md) / 2) >= 10) return Math.floor((exam + md) / 2);
  return special;
};

const ActionButtons = (props) => (
  <div className="ed-flex">
    <QuarterlyNotesModal
      data={props.data.data}
      maxvalue={props.data.MaxValue}
      title="Atualizar"
      update="true"
      get={`${Hoot()}eduallsinglequarterlynotebyid/get/${props.data.id}`}
      url={`${Hoot()}eduallquarterlynoteupdate/update/${props.data.id}`}
      toggle_btn={
        <button className="btn-circle btn-edit-timing bg-success text-light">
          <Edit />
        </button>
      }
    />
    <DeleteModal
      title="esta nota"
      url={`${Hoot()}eduallquarterlynotedelete/delete/${props.data.id}`}
      message="Nota deletada com sucesso"
      toggle_btn={
        <button className="btn-circle btn-delete-timing bg-danger ml-2 mr-2 text-light">
          <Delete />
        </button>
      }
    />
    <MessageTypeSelectorSend
      message={null}
      select
      mark
      subject={props.data.subject}
      classcode={props.data.class}
      quarter={props.data.quarter}
      student={props.data.studentid}
    />
  </div>
);

function TeacherStudentMarksTabItem({ Data, Institute }) {
  const [marks, setMarks] = useState([]);
  const [status, setStatus] = useState(null);
  const [selectedClassSub, setSelectedClassSub] = useState("");
  const [load, setLoad] = useState(false);
  const initialized = useRef(false);
  const DT = Data.data || [];

  const loadData = useCallback(
    async (classSub, quarter = "1") => {
      if (!classSub) return;
      setStatus(0);
      setLoad(false);

      const [classId, subjectId] = classSub.split("|") || [];
      const cacheKey = `marks_${classId}_${subjectId}_${quarter}`;
      const cached = localStorage.getItem(cacheKey);

      // Mostrar cache rápido
      if (cached) {
        const parsed = JSON.parse(cached);
        if (Date.now() - parsed.timestamp < CACHE_TTL) {
          setMarks(parsed.data);
          setLoad(true);
        }
      }

      try {
        const url =
          Institute.ed_institute_type === 0
            ? `${Hoot()}eduallsinglequarterlynotebyqrtsubcls/get/${quarter},${subjectId},${classId}`
            : `${Hoot()}eduallsinglesemesternotebysemsubcls/get/${quarter},${subjectId},${classId}`;

        const [res, classInfo] = await Promise.all([
          axios.get(url),
          axios.get(`${DATA_URL[0]}${classId}`),
        ]);

        const levelId = classInfo?.data?.[0]?.ed_class_academic_level;
        const levelInfo = levelId ? await axios.get(`${DATA_URL[1]}${levelId}`) : null;
        const MaxValue = levelInfo?.data?.[0]?.ed_academic_level_avaliationtype_endat || 20;

        const mapped = res.data.map((item, index) => {
          const mac = Number(item.ed_quarter_note_mac) || 0;
          const npp = Number(item.ed_quarter_note_npp) || 0;
          const npt = Number(item.ed_quarter_note_npt) || 0;
          const mt = FloorNumber((mac + npp + npt) / 3);
          const p1 = item.ed_semester_note_p1 || 0;
          const p2 = item.ed_semester_note_p2 || 0;
          const exam = item.ed_semester_note_exam || 0;
          const special = item.ed_semester_note_specialexam || 0;
          const md = FloorNumber((p1 + p2) / 2);
          const nf = FinalScore(md, exam, special);

          return {
            id: item.ed_quarter_note_id || item.ed_semester_note_id,
            studentid: item.ed_student_id,
            picture: item.ed_student_picture,
            name: `(#${item.ed_student_code}) - ${item.ed_student_name}`,
            sortName: item.ed_student_name,
            mac,
            npp,
            npt,
            mt,
            p1,
            p2,
            md,
            exam,
            specialexam: special,
            nf,
            MaxValue,
            status: mt < MaxValue / 2 ? "reprovado" : "aprovado",
            class: classId,
            subject: subjectId,
            quarter,
            data: Data.data,
            index: index + 1,
          };
        });

        setMarks(mapped);
        localStorage.setItem(
          cacheKey,
          JSON.stringify({ data: mapped, timestamp: Date.now() })
        );
        setStatus(2);
      } catch (err) {
        console.error(err);
        setMarks([]);
        setStatus(1);
      } finally {
        setLoad(true);
      }
    },
    [Data.data, Institute.ed_institute_type]
  );

  // carregar primeira turma/disciplina uma vez
  useEffect(() => {
    if (initialized.current) return;
    initialized.current = true;
    if (DT.length > 0) {
      const first = `${DT[0].ed_tch_subject_class}|${DT[0].ed_tch_subject_code}`;
      setSelectedClassSub(first);
      loadData(first, "1");
    }
  }, [DT, loadData]);

  const handleSelectChange = (e) => {
    const val = e.target.value;
    setSelectedClassSub(val);
    loadData(val, CRValue("#quarterly_note_quarter") || "1");
  };

  const handleQuarterChange = (e) => loadData(selectedClassSub, e.target.value);
  const refresh = () => loadData(selectedClassSub, CRValue("#quarterly_note_quarter") || "1");

  // ---- Colunas ----
  const columnsQuarter = [
    { field: "index", headerName: "Nº", width: 60 },
    {
      field: "student",
      headerName: "Nome do aluno",
      width: 330,
      cellRenderer: (props) => (
        <div className="ed-flex">
          <Avatar
            alt={props.data.sortName}
            src={props.data.picture ? Hoot() + props.data.picture : ""}
          />
          <span className="ml-2">{props.data.name}</span>
        </div>
      ),
    },
    { field: "mac", headerName: "MAC", width: 80, cellRenderer: (p) => GetColor(p.data.mac, p.data.MaxValue) },
    { field: "npp", headerName: "NPP", width: 80, cellRenderer: (p) => GetColor(p.data.npp, p.data.MaxValue) },
    { field: "npt", headerName: "NPT", width: 80, cellRenderer: (p) => GetColor(p.data.npt, p.data.MaxValue) },
    {
      field: "mt",
      headerName: "MT",
      width: 80,
      cellRenderer: (p) => GetColor(FloorNumber((p.data.mac + p.data.npp + p.data.npt) / 3), p.data.MaxValue),
    },
    { field: "finalresult", headerName: "Aproveito", width: 150, cellRenderer: (p) => StatusType[p.data.status] },
    { field: "action", headerName: "Ação", width: 370, cellRenderer: (p) => ActionButtons(p) },
  ];

  const columnsSemester = [
    { field: "index", headerName: "Nº", width: 60 },
    {
      field: "student",
      headerName: "Nome do aluno",
      width: 250,
      cellRenderer: (p) => (
        <div className="ed-flex">
          <Avatar alt={p.data.sortName} src={p.data.picture ? Hoot() + p.data.picture : ""} />
          <span className="ml-2">{p.data.name}</span>
        </div>
      ),
    },
    { field: "p1", headerName: "P1", width: 70, cellRenderer: (p) => GetColor(p.data.p1, p.data.MaxValue) },
    { field: "p2", headerName: "P2", width: 70, cellRenderer: (p) => GetColor(p.data.p2, p.data.MaxValue) },
    { field: "md", headerName: "Média", width: 80, cellRenderer: (p) => GetColor(p.data.md, p.data.MaxValue) },
    { field: "exam", headerName: "Exame", width: 80, cellRenderer: (p) => GetColor(p.data.exam, p.data.MaxValue) },
    {
      field: "specialexam",
      headerName: "Recurso",
      width: 80,
      cellRenderer: (p) =>
        p.data.nf < 10 ? GetColor(p.data.specialexam, p.data.MaxValue) : <></>,
    },
    {
      field: "nf",
      headerName: "Nota final",
      width: 80,
      cellRenderer: (p) => GetColor(FinalScore(p.data.md, p.data.exam, p.data.specialexam), p.data.MaxValue),
    },
    { field: "action", headerName: "Ação", width: 300, cellRenderer: (p) => ActionButtons(p) },
  ];

  const columns = Institute.ed_institute_type === 0 ? columnsQuarter : columnsSemester;

  return (
    <Container>
      <div className="top-container">
        <Box>
          <div className="ed-space">
            <div className="title"><h1>Lançar notas</h1></div>
            <div className="ed-flex">
              <Form className="ed-flex mt-1">
                <Form.Group className="ml-2">
                  <Form.Select
                    id="quarterly_note_subClass"
                    value={selectedClassSub}
                    onChange={handleSelectChange}
                    style={{ minWidth: "320px" }}
                  >
                    {DT.map((item, index) => (
                      <option key={index} value={item.ed_tch_subject_class + "|" + item.ed_tch_subject_code}>
                        Turma - <GetClasstitle_byclass ID={item.ed_tch_subject_class} /> (
                        <GetSubject ID={item.ed_tch_subject_code} /> )
                      </option>
                    ))}
                    {DT.length === 0 && <option value="">Sem associações disponíveis</option>}
                  </Form.Select>
                </Form.Group>

                <div className="ml-2">
                  <Form.Select id="quarterly_note_quarter" onChange={handleQuarterChange}>
                    {Institute.ed_institute_type === 1 ? (
                      <>
                        <option value="1">Iº Semestre</option>
                        <option value="2">IIº Semestre</option>
                      </>
                    ) : (
                      <>
                        <option value="1">Iº Trimestre</option>
                        <option value="2">IIº Trimestre</option>
                        <option value="3">IIIº Trimestre</option>
                      </>
                    )}
                  </Form.Select>
                </div>
              </Form>

              <button
                className="btn-icon btn btn-export-data ml-2"
                onClick={() => ExportDataForTablesExcel("Notas da turma ", ["Ação"], "score-notes-area")}
              >
                <PiMicrosoftExcelLogoDuotone /> Exportar notas
              </button>
              <div className="ml-2">
                <QuarterlyNotesModal Institute={Institute} data={Data.data} />
              </div>
            </div>
          </div>
        </Box>
      </div>

      <div className="table-box" id="score-notes-area">
        <TableGrid
          TableHead={columns}
          TableBody={load ? marks : []}
          TableHeight={420}
          TableTitle={`Notas por turma / ${ReplaceWord("Disciplina", true)}`}
          NoButtons
          TableBtn={<RefreshButton action={refresh} status={status} />}
        />
      </div>
    </Container>
  );
}

// ---------------- Styled ----------------
const Container = styled.section`
  display:block;
  width:100%;
  .top-container{ margin-top:20px; }
  .table-box{ margin-top:30px; }
`;

const Box = styled.div`
  width:100%;
  border-radius:6px;
  min-height:100px;
  margin-bottom:21px !important;
  background:var(--ed-white);
  box-shadow:var(--ed-shadow-df);
  padding:0px 20px;
  position:relative;
  display:flex;
  align-items:center;
  .ed-space{
    align-items:center;
    height:100%;
    div.ed-flex{ width:80%; justify-content:flex-end; }
  }
  .form-select{ max-width:200px; }
  .title h1{ font-size:18px; font-weight:600; margin:0px; }
  form{ width:80%; display:flex; align-items:center; justify-content:flex-end; }
`;

export default TeacherStudentMarksTabItem;
