/* ---------------------------------- Config --------------------------------- */

const DEFAULT_TABS = [
  "Minha Escola",
  "Secretaria",
  "Finanças",
  "Pedagogia",
  "Administração",
  "Biblioteca",
  "RH",
  "Segurança",
  "Configurações",
];

function toArraySafe(val) {
  if (!val) return [];
  return Array.isArray(val) ? val : [val];
}

function parseYouTubeId(linkOrId) {
  if (!linkOrId) return "";
  // If it looks like a pure ID (11 chars typical), accept it
  if (/^[a-zA-Z0-9_-]{10,}$/.test(linkOrId)) return linkOrId;

  try {
    const url = new URL(linkOrId);
    // Standard watch URL
    const v = url.searchParams.get("v");
    if (v) return v;
    // Shorts or embed or last path segment
    const paths = url.pathname.split("/").filter(Boolean);
    const last = paths[paths.length - 1] || "";
    return last;
  } catch {
    return linkOrId; // fallback
  }
}

/* -------------------------------- Components -------------------------------- */

function YouTubeEmbed({ videoId, title }) {
  const src = `https://www.youtube.com/embed/${videoId}?autoplay=1&rel=0&modestbranding=1`;
  return (
    <div className="yt-wrapper transparent">
      <iframe
        title={title || "Aula"}
        src={src}
        frameBorder="0"
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
        allowFullScreen
      />
    </div>
  );
}

function LessonCard({ lesson, onOpen }) {
  const youtubeId = parseYouTubeId(lesson.ed_link_video);
  const fallbackThumb = youtubeId
    ? `https://img.youtube.com/vi/${youtubeId}/hqdefault.jpg`
    : "";
  const thumb = lesson.ed_video_image || fallbackThumb;

  return (
    <button className="lesson-card" onClick={() => onOpen(lesson)}>
      <div className="lesson-thumb">
        <Avatar
          variant="square"
          className="df"
          alt={lesson.ed_video_title}
          src={thumb}
          sx={{ width: "100%", height: "100%", borderRadius: "14px" }}
        />
        <span className="lesson-play" aria-hidden>
          <FiPlayCircle />
        </span>
        {lesson.ed_video_time ? (
          <span className="lesson-duration">
            <FiClock style={{ marginRight: 6 }} />
            {lesson.ed_video_time}
          </span>
        ) : null}
      </div>
      <div className="lesson-meta">
        <h6 className="lesson-title" title={lesson.ed_video_title}>
          {lesson.ed_video_title}
        </h6>
        {lesson.ed_video_description ? (
          <p className="lesson-desc" title={lesson.ed_video_description}>
            {lesson.ed_video_description}
          </p>
        ) : null}
        <div className="lesson-tags">
          {Number(lesson.ed_video_favorite_status) === 1 ? (
            <Badge bg="warning" text="dark" title="Destaque">
              <FiStar style={{ marginRight: 6 }} />
              Destaque
            </Badge>
          ) : (
            <Badge bg="secondary" pill>
              <FiFilm style={{ marginRight: 6 }} />
              Vídeo
            </Badge>
          )}
          {lesson.ed_video_added_date ? (
            <Badge bg="light" text="dark">
              {new Date(lesson.ed_video_added_date).toLocaleDateString()}
            </Badge>
          ) : null}
        </div>
      </div>
    </button>
  );
}

/* ------------------------------ Main Component ------------------------------ */

export default function TutorialLessonsModal({
  apiUrl = "api/lessons", // endpoint que devolve array com os campos definidos
  tabs: tabsProp, // opcional: força ordem/nomes de tabs
  buttonLabel = "Tutoriais",
}) {
  const [show, setShow] = useState(false);
  const [lightboxOpen, setLightboxOpen] = useState(false);
  const [currentLesson, setCurrentLesson] = useState(null);

  const [loading, setLoading] = useState(false);
  const [err, setErr] = useState("");
  const [lessonsRaw, setLessonsRaw] = useState([]);

  // Pesquisa por tab (map de modulo -> query)
  const [queries, setQueries] = useState({});
  const setQuery = (tab, val) =>
    setQueries((q) => ({ ...q, [tab]: val || "" }));

  // FETCH
  useEffect(() => {
    let ok = true;
    (async () => {
      setLoading(true);
      setErr("");
      try {
        const res = await axios.get(Hoot()+"api/lessons", { withCredentials: true }); 
        const data = toArraySafe(res.data?.data ?? res.data);
        if (ok) setLessonsRaw(data);
      } catch (e) {
        if (ok) setErr("Não foi possível carregar as aulas agora." + Hoot()+"api/lessons");
        // eslint-disable-next-line no-console
        console.clear()
        console.error(e);
      } finally {
        if (ok) setLoading(false);
      }
    })();
    return () => {
      ok = false;
    };
  }, [apiUrl]);

  // TABS dinâmicas
  const dynamicTabs = useMemo(() => {
    if (tabsProp?.length) return tabsProp;
    const set = new Set();
    lessonsRaw.forEach((l) => {
      const m = l.ed_video_modulo?.trim();
      if (m) set.add(m);
    });
    const found = Array.from(set);
    const ordered = [
      ...DEFAULT_TABS.filter((t) => found.includes(t)),
      ...found.filter((t) => !DEFAULT_TABS.includes(t)),
    ];
    return ordered.length ? ordered : DEFAULT_TABS;
  }, [lessonsRaw, tabsProp]);

  const [active, setActive] = useState(dynamicTabs[0] || DEFAULT_TABS[0]);
  useEffect(() => {
    if (!dynamicTabs.includes(active)) {
      setActive(dynamicTabs[0] || DEFAULT_TABS[0]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [dynamicTabs]);

  // Agrupar por módulo
  const lessonsByTab = useMemo(() => {
    const map = {};
    dynamicTabs.forEach((t) => (map[t] = []));
    lessonsRaw.forEach((l) => {
      const m = l.ed_video_modulo?.trim();
      if (!m) return;
      if (!map[m]) map[m] = [];
      map[m].push(l);
    });
    // Ordena por data desc
    for (const t of Object.keys(map)) {
      map[t].sort((a, b) => {
        const da = new Date(a.ed_video_added_date || 0).getTime();
        const db = new Date(b.ed_video_added_date || 0).getTime();
        return db - da;
      });
    }
    return map;
  }, [lessonsRaw, dynamicTabs]);

  // Destaques / banner
  const favoriteLessons = useMemo(
    () => lessonsRaw.filter((l) => Number(l.ed_video_favorite_status) === 1),
    [lessonsRaw]
  );
  const latestLesson = useMemo(() => {
    return [...lessonsRaw].sort((a, b) => {
      const da = new Date(a.ed_video_added_date || 0).getTime();
      const db = new Date(b.ed_video_added_date || 0).getTime();
      return db - da;
    })[0];
  }, [lessonsRaw]);
  const bannerLesson = favoriteLessons[0] || latestLesson || null;
  const hasFavorite = favoriteLessons.length > 0;

  // Filtro por tab
  const filteredLessons = useMemo(() => {
    const q = (queries[active] || "").toLowerCase().trim();
    const base = lessonsByTab[active] || [];
    if (!q) return base;
    return base.filter((l) => {
      const hay =
        `${l.ed_video_title || ""} ${l.ed_video_description || ""}`.toLowerCase();
      return hay.includes(q);
    });
  }, [queries, lessonsByTab, active]);

  // Ações vídeo
  const openLightbox = (lesson) => {
    setShow(false);
    setCurrentLesson(lesson);
    setLightboxOpen(true);
  };
  const closeLightbox = () => {
    setLightboxOpen(false);
    setCurrentLesson(null);
  };

  return (
    <>
      <style>{css}</style>

      {/* Trigger */} 
        <div  onClick={() => setShow(true)} className="mr-2 ml-1 ed-flex error-badge cursor-pointer grey-text"
          role="button" aria-label={buttonLabel} title={buttonLabel}  >
          <FiVideo style={{ marginRight: 8 }} />
          <span className="ml-1">{buttonLabel}</span> 
        </div> 

      {/* Modal principal */}
      <Modal
        show={show}
        onHide={() => setShow(false)}
        size="xl"
        centered
        contentClassName="tuts-modal-content"
        dialogClassName="tuts-modal-dialog"
        className={show ? ModalAnimationShow() : ModalAnimationClose()}
      >
        <div className="modal-gradient" />
        <Modal.Header closeButton className="tuts-modal-header">
          <div className="title-wrap"> 
          <div className="ms-auto">
            <UserOptionDropDown />
          </div>
            <div>
              <h5 className="mb-0">Centro de Aprendizagem</h5>
              <small className="muted">Tutoriais e vídeo-aulas por módulo</small>
            </div>
          </div> 
        </Modal.Header>

        <Modal.Body className="tuts-modal-body scrollLimit">
          {/* MINI-BANNER */}
          <div className={bannerLesson?.ed_link_video ? "mini-banner" : "d-none"}>
            <div className="mini-banner-bg" />
            <div className="mini-banner-content">
              <div className="mini-banner-left">
                {bannerLesson  ? (
                  <div className="banner-thumb">
                     <div className="banner-actions">
                      <Button   className="over-play" onClick={() => openLightbox(bannerLesson)}>
                          <HiOutlinePlay />
                      </Button>
                    </div>
                    <Avatar
                      variant="square"
                      className="df"
                      src={
                        bannerLesson.ed_video_image ||
                        (bannerLesson.ed_link_video
                          ? `https://img.youtube.com/vi/${parseYouTubeId(
                              bannerLesson.ed_link_video
                            )}/hqdefault.jpg`
                          : "")
                      }
                      alt={bannerLesson.ed_video_title}
                      sx={{ width: "100%", height: "100%", borderRadius: "14px" }}
                    />
                    {Number(bannerLesson.ed_video_favorite_status) === 1 ? (
                      <span className="banner-star" aria-hidden>
                        <FiStar />
                      </span>
                    ) : null}
                  </div>
                ) : null}
              </div>

              <div className={bannerLesson?.ed_video_added_date  ? "mini-banner-right" : "d-none"}>
                {loading ? (
                  <div className="loading-inline">
                    <Spinner animation="border" size="sm" />
                    <span>A carregar aulas…</span>
                  </div>
                ) : bannerLesson ? (
                  <>
                    <h5 className="banner-title">{bannerLesson.ed_video_title}</h5>
                    <p className="banner-desc"><small>{bannerLesson.ed_video_description}</small></p>
                    <div className="banner-meta">
                      {bannerLesson.ed_video_modulo ? (
                        <Badge bg="light" text="dark">
                          {bannerLesson.ed_video_modulo}
                        </Badge>
                      ) : null}
                      {bannerLesson.ed_video_time ? (
                        <Badge bg="dark">
                          <FiClock style={{ marginRight: 6 }} />
                          {bannerLesson.ed_video_time}
                        </Badge>
                      ) : null}
                      {bannerLesson.ed_video_added_date ? (
                        <Badge bg="secondary">
                          {new Date(
                            bannerLesson.ed_video_added_date
                          ).toLocaleDateString()}
                        </Badge>
                      ) : null}
                    </div>
                  </>
                ) : (
                  <p className="mb-0">Sem vídeos para apresentar ainda.</p>
                )}
              </div>
            </div>
          </div>

          {/* ERRO */}
          {err ? (
            <Alert variant="danger" className="mx-3 my-3">
              {err}
            </Alert>
          ) : null}

          {/* TABS (Bootstrap tabs com bordas e fonte 11px) */}
          <div className="tabs-border-wrap">
            <br />
            <Tabs
              id="tutorial-tabs"
              activeKey={active}
              onSelect={(k) => k && setActive(k)}
              className="tuts-tabs nav-tabs tabs-bordered"
              justify
              mountOnEnter
              unmountOnExit
            >
              {dynamicTabs.map((tabKey) => {
                const allLessons = lessonsByTab[tabKey] || [];
                const q = queries[tabKey] || "";
                const filtered =
                  tabKey === active ? filteredLessons : allLessons;

                return (
                  <Tab key={tabKey} eventKey={tabKey} title={tabKey}>
                    <div className="tab-inner">
                      {/* Pesquisa */}
                      <div className="search-row">
                        <div className="search-input-wrap">
                          <FiSearch className="search-icon" />
                          <Form.Control
                            type="search"
                            placeholder={`Pesquisar aulas em “${tabKey}”...`}
                            value={q}
                            onChange={(e) => setQuery(tabKey, e.target.value)}
                            className="search-input"
                          />
                        </div>
                        <div className="count-chip">
                          <Badge bg="light" text="dark">
                            {filtered.length}/{allLessons.length} aulas
                          </Badge>
                        </div>
                      </div>

                      {/* Lista */}
                      {loading ? (
                        <div className="loading-area">
                          <Spinner animation="border" />
                          <div className="mt-2">A carregar…</div>
                        </div>
                      ) : Array.isArray(filtered) && filtered.length > 0 ? (
                        <Row xs={1} sm={2} md={3} lg={3} xl={4} className="g-4">
                          {filtered.map((lesson, idx) => (
                            <Col key={`${lesson.ed_link_video}-${idx}`}>
                              <LessonCard lesson={lesson} onOpen={openLightbox} />
                            </Col>
                          ))}
                        </Row>
                      ) : (
                        <div className="empty-state">
                          <div className="empty-badge">Sem resultados</div>
                          <p>
                            Não encontrámos aulas para{" "}
                            <strong>{tabKey}</strong>
                            {q ? (
                              <>
                                {" "}
                                com a pesquisa <em>“{q}”</em>.
                              </>
                            ) : (
                              "."
                            )}
                          </p>
                        </div>
                      )}
                    </div> 
                  </Tab>
                );
              })}
            </Tabs>
          </div>
        </Modal.Body>

        <Modal.Footer className="tuts-modal-footer">
          <div className="footer-left">
            <Badge bg="light" text="dark">
              Dica: clica numa aula para abrir o vídeo (o ecrã de aulas fecha
              automaticamente).
            </Badge>
          </div>
          <Button variant="outline-secondary" onClick={() => setShow(false)}>
            Fechar
          </Button>
        </Modal.Footer>
      </Modal>

      {/* LIGHTBOX */}
      <Modal
        show={lightboxOpen}
        onHide={closeLightbox}
        size="lg"
        centered
        contentClassName="lightbox-content transparent-bg"
        dialogClassName="lightbox-dialog"
        backdropClassName="lightbox-backdrop"
      >
        <button
          className="lightbox-close"
          onClick={closeLightbox}
          aria-label="Fechar"
          title="Fechar"
        >
          <FiX />
        </button>
        <Modal.Body className="lightbox-body only-video">
          {currentLesson ? (
            <YouTubeEmbed
              videoId={parseYouTubeId(currentLesson.ed_link_video)}
              title={currentLesson.ed_video_title}
            />
          ) : null}
        </Modal.Body>
      </Modal>
    </>
  );
}

