import React, { useState } from 'react';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap';
import { Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import { toast } from 'react-hot-toast';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import { Update } from '@material-ui/icons';
import { GetInstituteCode, ProvidersDataOptions } from '../../../General/components/InstituteData';
import RefreshList from '../../../General/components/RefreshList';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';

function NewAccountsPayableAndReceivableModal(props) {
  const [show, setShow] = useState(false);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [Founded, SetFounded] = useState(null);
  const [showBox, SetshowBox] = useState(false);
  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200); 
  };

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };

  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});

  const FORMURL = [
    Hoot() + 'eduallregisteraccount_payable_and_receivable/post/',
    props.get ? props.get : '',
    props.url ? props.url : ''
  ];

  const INPUTS = {
    description: CRValue('#description'),
    clientOrSupplier: CRValue('#clientOrSupplier'),
    paymentMethod: CRValue('#paymentMethod'),
    amountPayable: CRValue('#amountPayable'),
    amountReceivable: CRValue('#amountReceivable'),
    institute_code: GetInstituteCode()
  };

  const GET_DATA = async () => {
    if (props.update) {
      try {
        const response = await axios.get(FORMURL[1]);
        if (response.data.length > 0) { 
          document.querySelector('#description').value = response.data[0].ed_accounts_payable_and_receivable_description;
          document.querySelector('#clientOrSupplier').value = response.data[0].ed_accounts_payable_and_receivable_client_or_supplier;
          document.querySelector('#paymentMethod').value = response.data[0].ed_accounts_payable_and_receivable_payment_method;
          document.querySelector('#amountPayable').value = response.data[0].ed_accounts_payable_and_receivable_amount_payable;
          document.querySelector('#amountReceivable').value = response.data[0].ed_accounts_payable_and_receivable_amount_receivable;
 
          INPUTS.description = response.data[0].ed_accounts_payable_and_receivable_description;
          INPUTS.clientOrSupplier = response.data[0].ed_accounts_payable_and_receivable_client_or_supplier;
          INPUTS.paymentMethod = response.data[0].ed_accounts_payable_and_receivable_payment_method;
          INPUTS.amountPayable = response.data[0].ed_accounts_payable_and_receivable_amount_payable;
          INPUTS.amountReceivable = response.data[0].ed_accounts_payable_and_receivable_amount_receivable;
        } else {
          toast.error('Lamentamos, mas não foi possível encontrar a informação selecionada!');
        }
      } catch (error) {
        toast.error('Lamentamos, mas não foi possível encontrar a informação selecionada!');
      }
    }
  };

  const setField = (field, value) => {
    setForm({
      ...form,
      [field]: value
    });

    if (errors[field]) {
      setErrors({
        ...errors,
        [field]: null
      });
    }
  };

  const validateForm = () => {
    const { description, clientOrSupplier, paymentMethod, amountPayable, amountReceivable } = form;
    const NewErrors = {};
    setRegisterStatus(0);

    if (INPUTS.description === "" || INPUTS.description === " ") {
        if (!description || description === '') NewErrors.description = 'Descrição inválida!';
    } else {
        if (!description) setField("description", INPUTS.description);
    }

    if (INPUTS.clientOrSupplier === "" || INPUTS.clientOrSupplier === " ") {
        if (!clientOrSupplier || clientOrSupplier === '') NewErrors.clientOrSupplier = 'Cliente ou fornecedor inválido!';
    } else {
        if (!clientOrSupplier) setField("clientOrSupplier", INPUTS.clientOrSupplier);
    }

    if (INPUTS.paymentMethod === "" || INPUTS.paymentMethod === " ") {
        if (!paymentMethod || paymentMethod === '') NewErrors.paymentMethod = 'Método de pagamento inválido!';
    } else {
        if (!paymentMethod) setField("paymentMethod", INPUTS.paymentMethod);
    }

    if (INPUTS.amountPayable === "" || INPUTS.amountPayable === " ") {
        if (amountPayable === undefined || amountPayable === '') NewErrors.amountPayable = 'Valor a pagar inválido!';
    } else {
        if (amountPayable === undefined || amountPayable === '') setField("amountPayable", INPUTS.amountPayable);
    }

    if (INPUTS.amountReceivable === "" || INPUTS.amountReceivable === " ") {
        if (amountReceivable === undefined || amountReceivable === '') NewErrors.amountReceivable = 'Valor a receber inválido!';
    } else {
        if (amountReceivable === undefined || amountReceivable === '') setField("amountReceivable", INPUTS.amountReceivable);
    }

    if((INPUTS.amountPayable === 0 && INPUTS.amountReceivable <= 0) || (INPUTS.amountReceivable === 0 && INPUTS.amountPayable <= 0)){
        NewErrors.amountReceivable = 'Preencha um valor maior que zero em um dos campos e zero no outro!';
    } 

    if ((INPUTS.amountPayable === 0 && INPUTS.amountReceivable <= 0) || (INPUTS.amountReceivable === 0 && INPUTS.amountPayable <= 0)) {
        if (INPUTS.amountReceivable === "" || INPUTS.amountReceivable === " ") {
            NewErrors.amountReceivable = 'Preencha um valor maior que zero em um dos campos e zero no outro!';
        } else {
            if (amountReceivable === "" || amountReceivable === " ") setField("amountReceivable", INPUTS.amountReceivable);
        }
        
        if (INPUTS.amountPayable === "" || INPUTS.amountPayable === " ") {
            NewErrors.amountPayable = 'Preencha um valor maior que zero em um dos campos e zero no outro!';
        } else {
            if (amountPayable === "" || amountPayable === " ") setField("amountPayable", INPUTS.amountPayable);
        }
    }

    return NewErrors;
};



  const FormSubmit = (e) => {
    e.preventDefault();
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error('Verifique todos os campos');
      setRegisterStatus(1);
    } else {
      const SUBMIT_INPUTS = {
        ac_pay_rec_description: INPUTS.description,
        ac_pay_rec_client_or_supplier: INPUTS.clientOrSupplier,
        ac_pay_rec_payment_method: INPUTS.paymentMethod,
        ac_pay_rec_amount_payable: INPUTS.amountPayable,
        ac_pay_rec_amount_receivable: INPUTS.amountReceivable
      };

      if (!props.update) {
        try {
          axios.post(FORMURL[0], SUBMIT_INPUTS).then(() => {
            toast.success('Informações de contas a pagar e receber registradas com sucesso!');
            setForm({});
            ClearInputs();
            RefreshList('.el-refresh-list');
            setRegisterStatus(2);
          }).catch((error) => {
            toast.error('Lamentamos, mas não foi possível executar esta ação!');
            setRegisterStatus(1);
            console.clear();
            console.log(error.response?.data);
          });
        } catch (error) {
          toast.error('Lamentamos, mas não foi possível executar esta ação!');
          setRegisterStatus(1);
          console.clear();
          console.log(error.response?.data);
        }
      } else {
        try {
          axios.put(FORMURL[2], SUBMIT_INPUTS).then(() => {
            toast.success('Informações de contas a pagar e receber atualizadas com sucesso!');
            setForm({});
            ClearInputs();
            RefreshList('.el-refresh-list');
            setRegisterStatus(2);
            setTimeout(() => {
              handleClose();
            }, 1500);
          }).catch((error) => {
            toast.error('Lamentamos, mas não foi possível executar esta ação!');
            setRegisterStatus(1);
            console.clear();
            console.log(error.response?.data);
          });
        } catch (error) {
          toast.error('Lamentamos, mas não foi possível executar esta ação!');
          setRegisterStatus(1);
          console.clear();
          console.log(error.response?.data);
        }
      }
    }
  };

  const handleInput = (e) => {
    switch (e.target.id) {
      case 'description':
        setField('description', e.target.value);
        INPUTS.description = e.target.value;
        break;
      case 'clientOrSupplier':
        setField('clientOrSupplier', e.target.value);
        INPUTS.clientOrSupplier = e.target.value;
        break;
      case 'paymentMethod':
        setField('paymentMethod', e.target.value);
        INPUTS.paymentMethod = e.target.value;
        break;
      case 'amountPayable':
        setField('amountPayable', e.target.value);
        INPUTS.amountPayable = e.target.value;
        break;
      case 'amountReceivable':
        setField('amountReceivable', e.target.value);
        INPUTS.amountReceivable = e.target.value;
        break;
      default:
    }
  };

  return (
    <div>
      <div>
        <div onClick={handleShow}>
          {props.toggle_btn ? props.toggle_btn : <button className="btn btn-main bg-main"><AddCircleOutlineIcon /> Registrar</button>}
        </div>
        <Modal size="lg" dialogAs={DraggableModal} centered className={showBox ? ModalAnimationShow() : ModalAnimationClose()} show={show} onHide={handleClose}>
          <Modal.Header closeButton>
            <Modal.Title>
              <div className="ed-wrap align-center">
                <UserOptionDropDown />
                <h5>{props.title ? props.title : 'Registrar '}  conta a pagar e receber</h5>
              </div>
            </Modal.Title>
          </Modal.Header>
          <Form onSubmit={FormSubmit}>
            <Modal.Body className="scrollLimit">
            <div className="ed-flex">
            <Form.Group className="mb-3 col">
                <Form.Label>Descrição <span className="text-danger ml-2">*</span></Form.Label>
                <Form.Control required type="text" onChange={handleInput} className={!!errors.description && 'is-invalid'} value={form.description} isInvalid={!!errors.description} id="description" />
                <Form.Control.Feedback type="invalid">{errors.description}</Form.Control.Feedback>
              </Form.Group>
              <div className="pd1 pd-1"></div>
              <Form.Group className="mb-3 col">
                <Form.Label>Cliente ou Fornecedor <span className="text-danger ml-2">*</span></Form.Label>
                <Form.Control  required onChange={handleInput} className={!!errors.clientOrSupplier && 'is-invalid'} value={form.clientOrSupplier} isInvalid={!!errors.clientOrSupplier} id="clientOrSupplier" /> 
                <Form.Control.Feedback type="invalid">{errors.clientOrSupplier}</Form.Control.Feedback>
              </Form.Group>
            </div>
              <Form.Group className="mb-3">
                <Form.Label>Método de Pagamento <span className="text-danger ml-2">*</span></Form.Label>
                <Form.Select type="text" required onChange={handleInput} className={!!errors.paymentMethod && 'is-invalid'} value={form.paymentMethod} isInvalid={!!errors.paymentMethod} id="paymentMethod" >
                    <option value="0">Dinheiro a mão</option>
                    <option value="1">Transferência</option>
                    <option value="2">Depósito</option> 
                    <option value="3">TPA</option> 
                </Form.Select>
                <Form.Control.Feedback type="invalid">{errors.paymentMethod}</Form.Control.Feedback>
              </Form.Group> 
              <small className="text-main">
                  Para adicionar uma conta a pagar, preencha o campo 'valor a receber' com o número 0. Para adicionar uma conta a receber, faça o contrário, preenchendo o campo 'valor a pagar' com o número 0.
              </small>
              <br /> <br />
             <div className="ed-flex">
             <Form.Group className="mb-3 col">
                <Form.Label>Valor a Pagar <span className="text-danger ml-2">*</span></Form.Label>
                <Form.Control type="number" required onChange={handleInput} className={!!errors.amountPayable && 'is-invalid'} value={form.amountPayable} isInvalid={!!errors.amountPayable} id="amountPayable" />
                <Form.Control.Feedback type="invalid">{errors.amountPayable}</Form.Control.Feedback>
              </Form.Group>
              <div className="pd1 pd-1"></div>
              <Form.Group className="mb-3 col">
                <Form.Label>Valor a Receber <span className="text-danger ml-2">*</span></Form.Label>
                <Form.Control type="number" required onChange={handleInput} className={!!errors.amountReceivable && 'is-invalid'} value={form.amountReceivable} isInvalid={!!errors.amountReceivable} id="amountReceivable" />
                <Form.Control.Feedback type="invalid">{errors.amountReceivable}</Form.Control.Feedback>
              </Form.Group>
             </div>
            </Modal.Body>
            <Modal.Footer>
              <div className="ed-space">
                <div className="ed-flex"></div>
                <div className="ed-flex">
                  <Button className="bg-light text-dark" onClick={handleClose}>Cancelar</Button>
                  {props.update ? (Founded === false ? <div></div> :
                    <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />
                  ) :
                    <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />
                  }
                </div>
              </div>
            </Modal.Footer>
          </Form>
        </Modal>
      </div>
    </div>
  );
}

export default NewAccountsPayableAndReceivableModal;
