import ExcelJS from "exceljs";
import moment from "moment";
import "moment/locale/pt-br";
import { saveAs } from "file-saver";

const dataFormatada = moment().locale("pt-br").format("D [de] MMMM [de] YYYY, [às] HH:mm");

const ExportCustomTablesDataToExcel = (tableId, name = "eduall-file-export") => {
    const table = document.getElementById(tableId);
    if (!table) return;
 
    const rows = Array.from(table.rows);
    const headers = Array.from(rows[0].cells).map(cell => cell.innerText);
    const data = rows.slice(1).map(row => Array.from(row.cells).map(cell => cell.innerText));

    ConvertToExcel(headers, data, name);
};

async function ConvertToExcel(headers, data, name) {
    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet("Tabela de Devedores");

    // Criar cabeçalho
    const headerRow = worksheet.addRow(headers);
    headerRow.eachCell((cell) => {
        cell.fill = {
            type: "pattern",
            pattern: "solid",
            fgColor: { argb: "6051FF" }, // Roxo no cabeçalho
        };
        cell.font = {
            bold: true,
            color: { argb: "FFFFFF" }, // Texto branco
            name: "Poppins", // Fonte Poppins
            size: 12,
        };
        cell.alignment = { horizontal: "left" };
    });

    // Adicionar dados e aplicar estilo striped
    data.forEach((row, rowIndex) => {
        const rowExcel = worksheet.addRow(row);

        rowExcel.eachCell((cell) => {
            cell.fill = {
                type: "pattern",
                pattern: "solid",
                fgColor: { argb: rowIndex % 2 === 0 ? "F3F3F3" : "FFFFFF" }, // Linhas striped
            };
            cell.font = {
                name: "Poppins", // Fonte Poppins
                size: 12,
            };
            cell.alignment = { horizontal: "left" };
        });
    });

    // Ajustar largura das colunas automaticamente
    worksheet.columns = headers.map((header, index) => ({
        header,
        key: `col${index}`,
        width: Math.max(...data.map(row => row[index]?.length || 0), header.length) + 10,
    }));

    // Criar buffer e salvar arquivo
    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], { type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" });
    saveAs(blob, `${name} - ${dataFormatada}.xlsx`);
}

export default ExportCustomTablesDataToExcel;
