import React, { useEffect, useState } from 'react';
import { Avatar } from '@mui/material';
import axios from 'axios';
import moment from 'moment';
import Hoot from '../../../General/components/Hoot';
import TableGrid from '../../../General/components/TableGrid';
import RefreshButton from '../../../General/components/RefreshButton';
import NumberToPrice from '../../../General/components/NumberToPrice';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { DeleteButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import DeleteModal from '../elements/DeleteModal';
import PopPaymentDetailsModal from '../modal/PopPaymentDetailsModal';
import DownloadInvoicePDFButton from '../../../General/components/DownloadInvoicePDFButton';

const TypeOfPayments = [
  <div className="badge bg-success col col-lg-12">Dinheiro a mão</div>,
  <div className="badge bg-danger col col-lg-12">Transferência</div>,
  <div className="badge bg-warning col col-lg-12">Depósito</div>,
  <div className="badge bg-info col col-lg-12">TPA</div>
];

const PaymentsType = [
  <div className="badge bg-success col col-lg-12">Propinas</div>,
  <div className="badge bg-danger col col-lg-12">Transporte escolar</div>,
  <div className="badge bg-warning col col-lg-12">Serviços</div>,
  <div className="badge bg-info col col-lg-12">Pagamento de produtos</div>
];

const Months = [
  "Janeiro","Fevereiro","Março","Abril","Maio","Junho",
  "Julho","Agosto","Setembro","Outubro","Novembro","Dezembro"
];

// ===== COLUNAS (com suporte a fatura múltipla) =====
const columns = [
  {
    field: 'invoiceN',
    headerName: 'Nº da Fatura',
    width: 200,
    searchMap: row => row.invoiceN
  },
  {
    field: 'client',
    headerName: 'Cliente',
    width: 350,
    cellRenderer: (props) => {
      const d = props.data;
      return d.code !== null && d.code !== undefined ? (
        <div className="ed-flex">
          <Avatar alt={d.name} className="df" src={d.picture ? Hoot() + d.picture : ""} />
          <span className="ml-2">{d.name}</span>
        </div>
      ) : (
        <div className="badge bg-main">{d.name}</div>
      );
    },
    searchMap: row => row.name
  },
  {
    field: 'method',
    headerName: 'Metodo de pagamento',
    width: 200,
    cellRenderer: (props) => TypeOfPayments[props.data.method * 1] || <div>-</div>
  },
  {
    field: 'ptype',
    headerName: 'Tipo de pagamento',
    width: 240,
    cellRenderer: (props) => PaymentsType[props.data.paymentid * 1] || <div>-</div>
  },
  {
    field: 'service',
    headerName: 'Serviço / produto',
    width: 280,
    searchMap: row => row.service
  },
  {
    field: 'situation',
    headerName: 'Situação',
    width: 160,
    cellRenderer: (props) => {
      const c = props.data.invoiceCount * 1;
      return c > 1
        ? <div className="badge col-lg-12 bg-warning">{c} itens/meses</div>
        : <div className="badge col-lg-12 bg-success">PG. Simples</div>;
    },
    searchMap: row => row.invoiceCount > 1 ? `${row.invoiceCount} itens/meses` : 'PG. Simples'
  },
  {
    field: 'total',
    headerName: 'Total',
    width: 180,
    cellRenderer: (props) => (
      <div className="ed-flex">
        {NumberToPrice(props.data.balance)} {" " + (props.data.coin || "")}
      </div>
    ),
    searchMap: row => `${NumberToPrice(row.balance)} ${row.coin || ''}`
  },
  {
    field: 'date',
    headerName: 'Data de pagamento',
    width: 240,
    searchMap: row => row.date
  }, 
];

// ========== HELPERS ==========
function computeFeeTotals(item) {
  const price = item.ed_fee_payment_price * 1;
  const discountPct = item.ed_fee_payment_discount * 1 || 0;
  const ivaPct = item.ed_fee_payment_iva * 1 || 0;
  const fineType = item.ed_fee_payment_fineType * 1 || 0;
  const fineValue = item.ed_fee_payment_fineValue * 1 || 0;

  const afterDiscount = price - (price * discountPct) / 100;
  const base = ivaPct > 0 ? afterDiscount / (1 + ivaPct / 100) : afterDiscount;
  const ivaAmount = afterDiscount - base;
  const fineAmount = fineType === 1 ? fineValue : (base * fineValue) / 100;
  const total = afterDiscount + fineAmount;

  return { base, ivaAmount, fineAmount, total, afterDiscount };
}

function computeTransportTotals(item) {
  const price = item.ed_transport_payment_price * 1;
  const discountPct = item.ed_transport_payment_discount * 1 || 0;
  const ivaPct = item.ed_transport_payment_iva * 1 || 0;
  const fineType = item.ed_transport_payment_fineType * 1 || 0;
  const fineValue = item.ed_transport_payment_fineValue * 1 || 0;

  const afterDiscount = price - (price * discountPct) / 100;
  const base = ivaPct > 0 ? afterDiscount / (1 + ivaPct / 100) : afterDiscount;
  const ivaAmount = afterDiscount - base;
  const fineAmount = fineType === 1 ? fineValue : (base * fineValue) / 100;
  const total = afterDiscount + fineAmount;

  return { base, ivaAmount, fineAmount, total, afterDiscount };
}

function monthLabelFromValue(m) {
  if (!m) return "";
  let mm, yy, monthName;

  if (String(m).includes(".")) {
    [mm, yy] = String(m).split(".");
    const monthIndex = parseInt(mm, 10);
    monthName = !isNaN(monthIndex) && monthIndex >= 0 && monthIndex <= 11 ? Months[monthIndex] : mm;
  } else if (String(m).includes("-")) {
    const parts = String(m).split("-");
    monthName = parts[0] || "";
    yy = parts[1] || "";
  } else {
    monthName = m;
    yy = "";
  }
  return `${monthName}${yy ? ` de ${yy}` : ""}`;
}

// ========== COMPONENTE ==========
function PaymentsOfTheDayTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);
  const [TotalBalance, setTotalBalance] = useState("");
  const [CurrentCoin, SetCurrentCoin] = useState("");

  async function loadData() {
    try {
      setLoaded(false);
      setLoadStatus(0);

      const [
        FeePaymentData,
        TransportPaymentData,
        ServicePaymentData,
        SalesPaymentData
      ] = await Promise.all([
        axios.get(Hoot() + "eduallfeepaymentsapi/get/"),
        axios.get(Hoot() + "edualltransportpaymentsapi/get/"),
        axios.get(Hoot() + "eduallservicepaymentsapi/get"),
        axios.get(Hoot() + "eduallgetallproductsales/get/"),
      ]);

      // ---------- Normalizar linhas ----------
      const lines = [];

      // Propinas
      FeePaymentData.data.forEach(item => {
        const { total, base, ivaAmount, fineAmount, afterDiscount } = computeFeeTotals(item);
        SetCurrentCoin(item.ed_coin_code);

        lines.push({
          type: 0, // fee
          invoiceCode: item.ed_fee_payment_invoiceCode,
          invoiceFile: item.ed_fee_payment_invoiceFile || null,
          paymentCode: item.ed_fee_payment_code || null,
          deleteUrl: Hoot() + `eduallfeepaymentsdelete/delete/${item.ed_fee_payment_id}`,
          id: item.ed_fee_payment_id,
          registerDate: item.ed_fee_payment_registerDate,
          coin: item.ed_coin_code,
          method: item.ed_fee_payment_type * 1,
          month: item.ed_fee_payment_month,
          serviceTitle: item.ed_service_title,
          serviceId: item.ed_fee_payment_service,
          student: item.ed_fee_payment_student,
          studentcode: item.ed_student_code,
          name: item.ed_student_name,
          picture: item.ed_student_picture,
          base, ivaAmount, fineAmount, afterDiscount,
          lineTotal: total
        });
      });

      // Transporte
      TransportPaymentData.data.forEach(item => {
        const { total, base, ivaAmount, fineAmount, afterDiscount } = computeTransportTotals(item);
        SetCurrentCoin(item.ed_coin_code);

        lines.push({
          type: 1, // transport
          invoiceCode: item.ed_transport_payment_invoiceCode,
          invoiceFile: item.ed_transport_payment_invoiceFile || null,
          paymentCode: item.ed_transport_payment_code || null,
          // se tiveres um endpoint real, troca aqui:
          deleteUrl: Hoot() + `edualltransportpaymentsdelete/delete/${item.ed_transport_payment_id}`,
          id: item.ed_transport_payment_id,
          registerDate: item.ed_transport_payment_registerDate,
          coin: item.ed_coin_code,
          method: item.ed_transport_payment_type * 1,
          month: item.ed_transport_payment_month,
          serviceTitle: item.ed_service_title,
          serviceId: item.ed_transport_payment_service,
          student: item.ed_transport_payment_student,
          studentcode: item.ed_student_code,
          name: item.ed_student_name,
          picture: item.ed_student_picture,
          base, ivaAmount, fineAmount, afterDiscount,
          lineTotal: total
        });
      });

      // Serviços
      ServicePaymentData.data.forEach(item => {
        const total = (item.ed_service_payment_amount * item.ed_service_payment_price) -
          ((item.ed_service_payment_price * item.ed_service_payment_amount * item.ed_service_payment_discount) / 100);
        SetCurrentCoin(item.ed_coin_code);

        lines.push({
          type: 2, // service
          invoiceCode: item.ed_service_payment_invoiceCode,
          invoiceFile: item.ed_service_payment_invoiceFile || null,
          paymentCode: item.ed_service_payment_code || null,
          deleteUrl: Hoot() + `eduallservicepaymentsdelete/delete/${item.ed_service_payment_id}`, // ajuste se diferente
          id: item.ed_service_payment_id,
          registerDate: item.ed_service_payment_registerDate,
          coin: item.ed_coin_code,
          method: item.ed_service_payment_type * 1,
          month: null,
          serviceTitle: item.ed_service_title,
          serviceId: item.ed_service_payment_service,
          student: item.ed_service_payment_student || null,
          studentcode: item.ed_student_code || null,
          name: item.ed_student_name || (item.ed_service_payment_nif || 'N/A'),
          picture: item.ed_student_picture || "",
          base: total, ivaAmount: 0, fineAmount: 0, afterDiscount: total,
          lineTotal: total
        });
      });

      // Vendas (produtos)
      SalesPaymentData.data.forEach(item => {
        const discountPct = item.ed_product_sale_discount * 1 || 0;
        let totalPaid = 0;

        (item.products || []).forEach((product) => {
          const productTotal = (product.ed_sale_product_price * 1) * (product.ed_sale_product_quantity * 1);
          totalPaid += productTotal - (productTotal * discountPct / 100);
        });

        const coinSymbol = item.coin_symbol || item.ed_coin_code || '';
        SetCurrentCoin(coinSymbol);

        lines.push({
          type: 3, // sales
          invoiceCode: item.ed_product_sale_invoiceCode,
          invoiceFile: item.ed_product_sale_invoiceFile || null,
          paymentCode: item.ed_product_sale_code || null,
          deleteUrl: Hoot() + `eduallproductsalesdelete/delete/${item.ed_product_sale_id}`, // ajuste se diferente
          id: item.ed_product_sale_id,
          registerDate: item.ed_product_sale_date,
          coin: coinSymbol,
          method: item.ed_product_sale_payment_method * 1,
          month: null,
          serviceTitle: (item.products && item.products[0]) ? item.products[0].ed_product_name : 'Produtos',
          serviceId: null,
          student: null,
          studentcode: null,
          name: item.ed_product_sale_nif || 'N/A',
          picture: "",
          base: totalPaid, ivaAmount: 0, fineAmount: 0, afterDiscount: totalPaid,
          lineTotal: totalPaid
        });
      });

      // ---------- Agrupar por invoiceCode ----------
      const grouped = {};
      lines.forEach(line => {
        const key = line.invoiceCode || `NO-INVOICE-${line.id}`;
        const monthAsLabel = monthLabelFromValue(line.month);

        const paymentLine = {
          id: line.id,
          type: line.type,
          service: line.serviceTitle,
          month: monthAsLabel || null,
          method: line.method,
          registerDate: line.registerDate,
          coin: line.coin,
          base: line.base,
          ivaAmount: line.ivaAmount,
          fineAmount: line.fineAmount,
          total: line.lineTotal,
          paymentCode: line.paymentCode,
          invoiceFile: line.invoiceFile
        };

        if (!grouped[key]) {
          grouped[key] = {
            id: line.id,
            invoiceN: key,
            code: line.invoiceFile,          // p/ DownloadInvoicePDFButton
            paymentCode: line.paymentCode,   // anexos, se precisares
            coin: line.coin,
            method: line.method,
            paymentid: line.type,
            name: line.name,
            student: line.student,
            studentcode: line.studentcode,
            picture: line.picture,
            months: monthAsLabel ? [monthAsLabel] : [],
            services: [line.serviceTitle],
            balance: line.lineTotal,
            date: moment(line.registerDate).format('DD [de] MMMM [de] YYYY [às] HH:mm'),
            invoiceCount: 1,
            paymentsUrls: line.deleteUrl ? [line.deleteUrl] : [],
            payments: [paymentLine],
            // Para a coluna "Serviço / produto"
            service: line.serviceTitle
          };
        } else {
          grouped[key].balance += line.lineTotal;
          grouped[key].invoiceCount += 1;
          grouped[key].payments.push(paymentLine);
          if (line.deleteUrl) grouped[key].paymentsUrls.push(line.deleteUrl);
          if (monthAsLabel) grouped[key].months.push(monthAsLabel);
          grouped[key].services.push(line.serviceTitle);

          // preferir a data mais recente
          const prev = moment(grouped[key].date, 'DD [de] MMMM [de] YYYY [às] HH:mm').toDate();
          const cur = moment(line.registerDate).toDate();
          if (cur > prev) {
            grouped[key].date = moment(line.registerDate).format('DD [de] MMMM [de] YYYY [às] HH:mm');
          }
        }
      });

      // ---------- Converter para array | aplicar "pagamentos de hoje" ----------
      const allRows = Object.values(grouped).map(g => {
        // serviço/descrição resumida: primeiro + “(+n)”
        const extra = g.services.length > 1 ? ` (+${g.services.length - 1})` : '';
        const monthsLabel = (g.months || []).filter(Boolean).join(', ');

        return {
          ...g,
          monthsLabel,
          service: `${g.service}${extra}`
        };
      });

      // Filtrar por hoje usando a data do pagamento (pelo registerDate das linhas)
      const today = moment().format('DD-MM-YYYY');
      const rowsToday = allRows.filter(r => {
        // pegar a data do primeiro payment (mais robusto para “hoje” real)
        const firstLine = r.payments?.[0];
        if (!firstLine) return false;
        const isToday = moment(firstLine.registerDate).format('DD-MM-YYYY') === today;
        return isToday;
      });

      // Ordenar desc pela data do grupo (string “DD de MMMM de YYYY às HH:mm” → comparar por Date)
      rowsToday.sort((a, b) => {
        const parseDate = (d) => moment(d, 'DD [de] MMMM [de] YYYY [às] HH:mm').toDate();
        return parseDate(b.date) - parseDate(a.date);
      });

      // Total do dia (grupos)
      const total = rowsToday.reduce((acc, obj) => acc + (Number(obj.balance) || 0), 0);
      setTotalBalance(NumberToPrice(total));

      setData(rowsToday);
      setTimeout(() => setLoaded(true), 200);
      setLoadStatus(2);
    } catch (error) {
      console.error(error);
      setLoaded(true);
      setLoadStatus(1);
    }
  }

  useEffect(() => {
    loadData();
  }, []);

  return load ? (
    <div className='mt-4' id="ed-custom-table-data">
      <TableGrid
        TableHead={columns}
        TableBody={data}
        TableTitle={`Pagamentos do dia ( ${data.length} )`}
        TableBtn={
          <div className='ed-flex'>
            <div className="badge ml-2 bg-success mr-2">
              <h5 className='m0'>{TotalBalance} {CurrentCoin}</h5>
            </div>
            <button
              className='btn-icon btn btn-export-data'
              onClick={() => ExportDataForTablesExcel("Pagamentos do dia ", ["Ação"])}
            >
              <PiMicrosoftExcelLogoDuotone />
            </button>
            <RefreshButton action={loadData} status={LoadStatus} />
          </div>
        }
      />
    </div>
  ) : (
    <div>
      <div className="d-none">*</div>
      <TableGrid
        TableHead={columns}
        TableBody={[]}
        NoSearch
        TableTitle='Pagamentos do dia'
        TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
      />
    </div>
  );
}

export default PaymentsOfTheDayTable;
