import React, { useEffect, useState } from 'react';
import { Avatar } from '@mui/material';
import axios from 'axios';
import moment from 'moment';
import Hoot from '../../../General/components/Hoot';
import { Delete, PreviewOutlined } from '@mui/icons-material';
import { Link } from 'react-router-dom';
import TableGrid from '../../../General/components/TableGrid';
import { PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import NumberToPrice from '../../../General/components/NumberToPrice';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import DeleteModal from '../elements/DeleteModal';
import DownloadInvoicePDFButton from '../../../General/components/DownloadInvoicePDFButton';
import PopServicePaymentDetailsModal from '../modal/PopServicePaymentDetailsModal';

const TABLEURL = Hoot() + "eduallservicepaymentsapi/get";

const columns = [
  { field: 'invoice', headerName: 'Nº da Fatura', width: 150 },
  {
    field: 'name',
    headerName: 'Aluno',
    cellRenderer: (props) => (
      <div className="ed-flex">
        <Avatar className='df' alt={props.data.student} src={props.data.picture !== "" ? Hoot() + props.data.picture : ""} />
        <span className='ml-2'>{props.data.student}</span>
      </div>
    )
  },
  { field: 'services', headerName: 'Serviços', width: 280 },
  { field: 'quantity', headerName: 'Qtd. Total', width: 120 },
  { field: 'discount', headerName: 'Desconto', width: 130 },
  { field: 'total', headerName: 'Total da Fatura', width: 160 },
  {
    field: 'action',
    headerName: 'Ação',
    cellRenderer: (props) => (
      <div className="ed-flex"> 
        <DownloadInvoicePDFButton documentId={props.data.filecode} />
        <PopServicePaymentDetailsModal
          invoiceCode={props.data.invoice}
          invoiceCodeID={props.data.filecode}
          toggle_btn={<PreviewButton />}
        />
        <DeleteModal
          title='esta fatura'
          url={Hoot() + `eduallservicepaymentdeleteinvoice/delete/${props.data.invoice}`}
          message='Pagamentos desta fatura foram deletados'
          toggle_btn={<button className="btn-circle bg-danger ml-2 text-light"><Delete /></button>}
        />
      </div>
    )
  }
];

function PaidServicesTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData() {
    try {
      setLoaded(false);
      setLoadStatus(0);
      const response = await axios.get(TABLEURL);
      const grouped = {};

      response.data.forEach(item => {
        const invoice = item.ed_service_payment_invoiceCode;
        if (!grouped[invoice]) {
          grouped[invoice] = {
            invoice,
            filecode: item.ed_service_payment_file_code,
            student: item.ed_student_name,
            picture: item.ed_student_picture,
            discount: item.ed_service_payment_discount,
            coin: item.ed_coin_code,
            services: [],
            total: 0,
            quantity: 0
          };
        }
        const subtotal = (item.ed_service_payment_amount * item.ed_service_payment_price) -
          ((item.ed_service_payment_price * item.ed_service_payment_amount * item.ed_service_payment_discount) / 100);

        grouped[invoice].services.push(item.ed_service_title);
        grouped[invoice].total += subtotal;
        grouped[invoice].quantity += item.ed_service_payment_amount;
      });

      const rows = Object.values(grouped).map((inv, index) => ({
        id: index + 1,
        invoice: inv.invoice,
        filecode: inv.filecode,
        student: inv.student,
        picture: inv.picture,
        services: inv.services.join(', '),
        quantity: inv.quantity,
        discount: inv.discount + "%",
        total: NumberToPrice(inv.total) + " " + inv.coin
      }));

      setData(rows);
      setLoaded(true);
      setLoadStatus(2);
    } catch (error) {
      console.log(error);
      setLoaded(true);
      setLoadStatus(1);
    }
  }

  useEffect(() => {
    loadData();
  }, []);

  return (
    <div id="ed-custom-table-data">
      <TableGrid
        TableHead={columns}
        TableBody={data}
        TableTitle='Serviços pagos (agrupados por fatura)'
        TableBtn={
          <div className='ed-flex'>
            <button id='ed-custom-table-data-btn'
              onClick={() =>
                ExportDataToTablesToPdf({
                  fileName: "Pagamentos de Serviços Agrupados",
                  headerId: null,
                  contentId: "ed-custom-table-data",
                  footerId: null,
                  rotation: "landscape",
                  buttonId: "ed-custom-table-data-btn",
                  customHeader: "Lista dos pagamentos agrupados por fatura",
                  excludedColumns: ["Ação"]
                })
              }
              className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone /></button>
            <button className='btn-icon btn btn-export-data ml-2'
              onClick={() => ExportDataForTablesExcel("Pagamentos Agrupados", ["Ação"], "ed-custom-table-data")}>
              <PiMicrosoftExcelLogoDuotone />
            </button>
            <RefreshButton action={loadData} status={LoadStatus} />
          </div>
        }
      />
    </div>
  );
}

export default PaidServicesTable;
