import React , {useState, useEffect} from 'react'
import { styled } from 'styled-components';
import Odometer from 'react-odometerjs';

function CounterUsers() {
    const [value, setValue] = useState(1827787);

    useEffect(() => {
        const timeoutId = setTimeout(() => setValue(1827787), 2000);
        setInterval(() => {
          setValue(value++)
        }, 2000);  
    }, []);

    return (
      <Container className="ed-center ed-flex bg-main">
           <div>
             <h1 className="text-light">TOTAL USERS REGISTERED</h1>
              <div className="counter mt-4">
                 <Odometer value={value} format="(.ddd),dd" />
              </div>
           </div>
      </Container>    
    );
}

const Container = styled.div`
  width:100%;
  height:100vh;
  padding:20px;

     .counter{
          font-size:50px;
          padding:10px 20px;
          background:black;
     }
`;

export default CounterUsers