import React, { useEffect, useState } from 'react'
import styled from 'styled-components'
import Chart from 'react-apexcharts';
import { Badge, Form, Spinner } from 'react-bootstrap';
import TableGrid from '../../../../General/components/TableGrid';
import ProfileCalendar from '../../../Components/ProfileCalendar';
import { CiBookmarkPlus } from "react-icons/ci";
import { FaTasks } from 'react-icons/fa';
import { GetClasstitle_byclass, GetSubject } from '../../../../General/components/InstituteData';
import ShedulerComponent from '../../../../General/ShedulerComponent';
import AddsGenerator from '../../../Components/AddsGenerator';
import { BsClock } from 'react-icons/bs';
import axios from 'axios';
import Hoot from '../../../../General/components/Hoot';
import { Check, Close, InfoOutlined } from '@material-ui/icons';
import moment from "moment";
import ReplaceWord from '../../../../General/components/ReplaceWord';
import { toast } from 'react-hot-toast';
import SmallLoader from '../../../../General/components/SmallLoader';
 

const StatusType = [
   <div className="ml-2"><Badge bg={'success'}><Check /> Presente</Badge></div>,
   <div className="ml-2"><Badge bg={'danger'}> <Close /> Ausente</Badge></div>,
   <div className="ml-2"><Badge bg={'warning'}><InfoOutlined /> Atrasado</Badge></div>
];


const columns = [
   {
      field: 'index',
      headerName: 'Nº',
      width: 70,
      resizable: true
   },
   {
      field: 'subject',
      resizable: true,
      headerName: ReplaceWord("Disciplina"),
      width: 150
   },
   {
      field: 'class',
      headerName: 'Turma',
      width: 110,
      resizable: true,
      editable: true,
   },
   {
      field: 'date',
      headerName: 'Data & Hora',
      width: 190,
      resizable: true,
      editable: true,
   },
   {
      field: 'status',
      width: 180,
      headerName: 'Status',
      resizable: true,
      cellRenderer: (props) => {
         return <div className='ed-flex'> {StatusType[props.data.status]} </div>
      }
   },
   {
      field: 'action',
      headerName: 'Ação',
      width: 110,
      sortable: false,
   },
];




function TeacherDashboardTabItem(props) {
   const [EmployeePersonalAttendance, setEmployeePersonalAttendance] = useState([]);
   const [load, setLoaded] = useState(false);
   const [Absences, SetAbsences] = useState(0);

   const [Timings, setTimings] = useState({ day1: [], day2: [], day3: [], day4: [], day5: [], day6: [], day7: [] })
   const BoxCounts = [
      { color: "var(--ed-blue-light)", icon: <CiBookmarkPlus color='white' size={25} />, title: "Turmas que eu leciono", total: props.Data.ClassList.length },
      { color: "var(--ed-red-light)", icon: <FaTasks color='white' size={25} />, title: "Tarefas pendentes", total: "0" },
      { color: "var(--ed-green)", icon: <CiBookmarkPlus color='white' size={30} />, title: `${ReplaceWord("Disciplinas")} que leciono`, total: props.Data.SubjectsList.length },
      { color: "var(--ed-orange-light)", icon: <CiBookmarkPlus color='white' size={30} />, title: "Minhas Faltas", total: Absences },
   ];

   const [selectedClass, setSelectedClass] = useState(null);
   const [loadingClassData, setLoadingClassData] = useState(false);

   const [ChartOptions_donut, SetChartOptions_donut] = useState({
      series: [
         {
            name: 'Quantidade',
            data: [0, 0] // Masculino, Feminino
         }
      ],
      options: {
         chart: {
            type: 'bar',
            height: 200
         },
         plotOptions: {
            bar: {
               horizontal: true,
               borderRadius: 4
            }
         },
         colors: ['var(--ed-green)', 'var(--ed-purple)'],
         dataLabels: {
            enabled: true
         },
         xaxis: {
            categories: ['Masculino', 'Feminino']
         }
      }
   });




   const LoadStudentsAttandenceByClassAndGender = async (iddaturma) => {
      if (isNaN(iddaturma) || Number(iddaturma) <= 0) {
         toast.warning("ID da turma inválido.");
         return;
      }

      setLoadingClassData(true);

      try {
         const studentsResponse = await axios.get(`${Hoot()}eduallgetstudentsbyclass/${iddaturma}`);
         const attendanceResponse = await axios.get(`${Hoot()}eduallgetallstudentsattendance/get`);

         const students = studentsResponse.data || [];
         const attendance = attendanceResponse.data || [];

         let maleAbsences = 0;
         let femaleAbsences = 0;

         const absencesData = attendance.filter(
            (att) =>
               att.ed_student_attd_status >= 1 &&
               att.ed_student_attd_class === iddaturma
         );

         students.forEach(student => {
            absencesData.forEach(att => {
               if (student.ed_student_gender === "male" && att.ed_student_attd_student_code * 1 === student.ed_student_id * 1) {
                  maleAbsences += 1;
               } else if (student.ed_student_gender === "female" && att.ed_student_attd_student_code * 1 === student.ed_student_id * 1) {
                  femaleAbsences += 1;
               }
            });
         });

         SetChartOptions_donut({
            series: [
              {
                name: 'Quantidade',
                data: [maleAbsences, femaleAbsences]
              }
            ],
            options: {
              chart: { type: 'bar', height: 200 },
              plotOptions: { bar: { horizontal: true, borderRadius: 4, distributed: true } },
              colors: ['var(--ed-green)', 'var(--ed-purple)'],
              dataLabels: { enabled: true },
              xaxis: { categories: ['Masculino', 'Feminino'] }
            }
          });

      } catch (error) {
         console.log(error);
         toast.error("Erro ao carregar dados de presença: ");
      } finally {
         setLoadingClassData(false);
      }
   };





   const LoadData = async () => {
      const Timings = {
         day1: [], day2: [],
         day3: [], day4: [],
         day5: [], day6: [],
         day7: [],
      };

      const getTime = (item) => {
         return item.ed_timing_hour_start + ":" + item.ed_timing_minute_start + "-" + item.ed_timing_hour_end + ":" + item.ed_timing_minute_end;
      }

      props.Data.timings.map((item, index) => {
         switch (item.ed_tch_timing_weekday * 1) {
            case 0:
               Timings.day1.push({ subject: item.ed_subject_title, class: item.ed_class_title, timing: getTime(item) })
               break;
            case 1:
               Timings.day2.push({ subject: item.ed_subject_title, class: item.ed_class_title, timing: getTime(item) })
               break;
            case 2:
               Timings.day3.push({ subject: item.ed_subject_title, class: item.ed_class_title, timing: getTime(item) })
               break;
            case 3:
               Timings.day4.push({ subject: item.ed_subject_title, class: item.ed_class_title, timing: getTime(item) })
               break;
            case 4:
               Timings.day5.push({ subject: item.ed_subject_title, class: item.ed_class_title, timing: getTime(item) })
               break;
            case 5:
               Timings.day6.push({ subject: item.ed_subject_title, class: item.ed_class_title, timing: getTime(item) })
               break;
            case 6:
               Timings.day7.push({ subject: item.ed_subject_title, class: item.ed_class_title, timing: getTime(item) })
               break;
            default:
         }
      })
      setTimings(Timings);


      try {
         setLoaded(false);
         const response = await axios.get(Hoot() + "eduallgetemployeeattendencebycode/get/" + props?.Data?.employeeData[0]?.ed_employee_id);

         const rows = [];
         const rowsAbsences = [];

         response.data.map((item, index) => {
            rows.push({
               index: index + 1,
               id: item.ed_employee_attd_id,
               student: item.ed_employee_attd_code,
               class: item.ed_class_title,
               subject: item.ed_subject_title,
               timing: item.ed_employee_attd_timing,
               date: moment(item.ed_employee_attd_registerDate).format("YYYY-MM-DD HH:mm"),
               status: item.ed_employee_attd_status,
            })

            if (item.ed_employee_attd_status * 1 > 0) {
               rowsAbsences.push(item)
            }
         });
         SetAbsences(rowsAbsences.length)
         setEmployeePersonalAttendance(rows);
         setLoaded(true);
      } catch (error) {
         console.log(error);
         setLoaded(false);
      }
   }


   useEffect(() => {
      LoadData();
   }, []);



   useEffect(() => {
      if (props.Data?.ClassList?.length > 0) {
         const firstClass = props.Data.ClassList[0];
         setSelectedClass(firstClass);
         LoadStudentsAttandenceByClassAndGender(firstClass);
      }
   }, [props.Data?.ClassList]);

 

   return (
      <Container className='ed-emp-dash-dashboard-menu'>
         <div className="top-container">
            <Row className='ed-emp-dash_rowbox'>
               <FlexBox className='ed-emp-dash_flexbox'>
                  {
                     BoxCounts.map((item, index) => {
                        return (
                           <div key={index} className="small-box">
                              <Box className="bx nav-theme">
                                 <div className="ed-flex">
                                    <div className="icon bg-main">{item.icon}</div>
                                    <div className="ed-flex">
                                       <h1 className="text-main-light">{item.total}</h1>
                                    </div>
                                 </div>
                                 <div className="ed-block">
                                    <h4 className="title  ">{item.title}</h4>
                                 </div>
                              </Box>
                           </div>
                        )
                     })
                  }
               </FlexBox>
               <div className="Big-Box">
                  <Box className='f-height  nav-theme'>
                     <div className="ed-space">
                        <div><h5>Faltas por turma (Género)</h5></div>
                         <Form className="ed-flex" style={{ gap: "8px", alignItems: "center" }}>
                            {loadingClassData && (
                              <SmallLoader />
                           )}
                           <Form.Select
                           id='class-selector-element'
                               className='ml-1'
                              value={selectedClass || ""} 
                              onChange={(e) => {
                                 const classId = Number(e.target.value);
                                 setSelectedClass(classId);
                                 LoadStudentsAttandenceByClassAndGender(classId);
                              }}>
                              <option value="" disabled>
                                 Selecionar turma...
                              </option>

                              {[...new Set(props.Data.ClassList)].map((item, index) => (
                                 <option key={index} value={item}>
                                    <GetClasstitle_byclass ID={item} />
                                 </option>
                              ))}
                           </Form.Select> 
                        </Form>
                     </div>
                     <div className="center">
                        <div className="chart-box">
                           <Chart
                              options={ChartOptions_donut.options}
                              series={ChartOptions_donut.series}
                              type="bar"
                              width="99%"
                              height="100%"
                           /> 
                        </div>
                     </div>
                  </Box>
               </div>
            </Row>
            <Row className='ed-row-col mb-2'>
               <div className='calendar-box'>
                  <Box className='box-calendar nav-theme'>
                     <ProfileCalendar />
                  </Box>
               </div>
               <div className="pd-2"></div>
               <div className="table-box">
                  {load ?
                     <TableGrid
                        TableHead={columns}
                        TableBody={EmployeePersonalAttendance}
                        TableHeight={300}
                        NoButtons
                        TableTitle='Meu Histórico de presença' />
                     :
                     <>
                        <div className="d-none"><h1>*</h1></div>
                        <TableGrid
                           TableHead={columns}
                           TableBody={[]}
                           TableHeight={300}
                           NoButtons
                           TableTitle='Meu Histórico de presença' />
                     </>
                  }
               </div>
            </Row>
            <Row className='ed-row-col mt-4'>
               <div className="week-calendar-box  nav-theme">
                  <h1 className="title">Dias de trabalho</h1>
                  <section className="weekdays">
                     <article className="week-item wh1">
                        <div className="week-header-title">Segunda-feira</div>
                        <div className="week-body">
                           <ul>
                              {Timings.day2.map((item, index) => {
                                 return (
                                    <li key={index}>
                                       <div className="small-el-title">{item.subject}  na  turma {item.class}</div>
                                       <small className="time ed-flex"><BsClock />{item.timing}</small>
                                    </li>
                                 )
                              })}
                           </ul>
                        </div>
                     </article>
                     <article className="week-item wh2">
                        <div className="week-header-title">Terça-feira</div>
                        <div className="week-body">
                           <ul>
                              {Timings.day3.map((item, index) => {
                                 return (
                                    <li key={index}>
                                       <div className="small-el-title">{item.subject}  na turma {item.class}</div>
                                       <small className="time ed-flex"><BsClock />{item.timing}</small>
                                    </li>
                                 )
                              })}
                           </ul>
                        </div>
                     </article>
                     <article className="week-item wh3">
                        <div className="week-header-title">Quarta-feira</div>
                        <div className="week-body">
                           <ul>
                              {Timings.day4.map((item, index) => {
                                 return (
                                    <li key={index}>
                                       <div className="small-el-title">{item.subject}  na  turma {item.class}</div>
                                       <small className="time ed-flex"><BsClock />{item.timing}</small>
                                    </li>
                                 )
                              })}
                           </ul>
                        </div>
                     </article>
                     <article className="week-item wh4">
                        <div className="week-header-title">Quinta-feira</div>
                        <div className="week-body">
                           <ul>
                              {Timings.day5.map((item, index) => {
                                 return (
                                    <li key={index}>
                                       <div className="small-el-title">{item.subject}  na  turma {item.class}</div>
                                       <small className="time ed-flex"><BsClock />{item.timing}</small>
                                    </li>
                                 )
                              })}
                           </ul>
                        </div>
                     </article>
                     <article className="week-item wh5">
                        <div className="week-header-title">Sexta-feira</div>
                        <div className="week-body">
                           <ul>
                              {Timings.day6.map((item, index) => {
                                 return (
                                    <li key={index}>
                                       <div className="small-el-title">{item.subject}  na  turma {item.class}</div>
                                       <small className="time ed-flex"><BsClock />{item.timing}</small>
                                    </li>
                                 )
                              })}
                           </ul>
                        </div>
                     </article>
                     <article className="week-item wh6">
                        <div className="week-header-title">Sabado</div>
                        <div className="week-body">
                           <ul>
                              {Timings.day7.map((item, index) => {
                                 return (
                                    <li key={index}>
                                       <div className="small-el-title">{item.subject}  na  turma {item.class}</div>
                                       <small className="time ed-flex"><BsClock />{item.timing}</small>
                                    </li>
                                 )
                              })}
                           </ul>
                        </div>
                     </article>
                     <article className="week-item wh7">
                        <div className="week-header-title">Domingo</div>
                        <div className="week-body">
                           <ul>
                              {Timings.day1.map((item, index) => {
                                 return (
                                    <li key={index}>
                                       <div className="small-el-title">{item.subject}  na  turma {item.class}</div>
                                       <small className="time ed-flex"><BsClock />{item.timing}</small>
                                    </li>
                                 )
                              })}
                           </ul>
                        </div>
                     </article>
                  </section>
               </div>
               <div className="pd-2"></div>
               <div className="scheduler-box  nav-theme">
                  <h1 className="title">Calendário de eventos</h1>
                  <ShedulerComponent data={[{ start: new Date(2023, 35, 10), end: new Date(), title: "kiosso andre birthday ..." }]} title="Minhas tarefas & Eventos" />
               </div>
            </Row>
         </div>
      </Container>
   )
}

const Container = styled.section`
     display:block;
     width:100%; 

     .top-container{
         margin-top:20px;
     }

     .scheduler-box{
         width:100%;
         border-radius:6px; 
         min-height:150px;
         margin-bottom:21px !important;
         background:var(--ed-white);  
         box-shadow:var(--ed-shadow-df); 
         padding:20px;
         position: relative;
     }

     .calendar-box{
        height:360px; 
        max-width:600px;
        min-width:600px;
        margin-top:15px;

          .box-calendar {
            padding:0px;
            height:360px;


            div{
              box-shadow:none !important;
            }
          }
     }

     .table-box{
         width:100%;
         min-width:650px; 
     }
`;

const Row = styled.div`
   display:flex;
   justify-content:space-between;
   width:100%; 

   .chart-box{
      height:200px;

      @media screen and (max-width:1290px){
         height:300px; 
      }
   }



   h1.title{
      font-size: 18px;
      font-weight: 600;
      margin: 0px;
      margin-bottom:20px;
   }
   

   .weekdays{
      width:100%; 
      border-left:1px solid var(--ed-silver-light);
      padding-right:20px;
      padding-left:9px; 
      max-height:500px;
      overflow-y:auto;

      &::-webkit-scrollbar{
        width:6px !important;
        background-color:transparent !important;
      }
      
      &::-webkit-scrollbar-thumb{
          background:rgb(219, 219, 219) !important; 
      } 


        .week-item{
            position:relative; 
            margin-top:20px;

              &:after{
                 position:absolute;
                 left:0px;
                 top:9px; 
                 content:"";
                 width:30px;
                 height:1px;
                 background:var(--ed-silver-light);
              }

              &:before{
                position:absolute;
                left:-10px;
                top:-1px; 
                content:"";
                width:20px;
                height:20px;
                border-radius:100%; 
                border:2px solid var(--ed-white);
                box-shadow:var(--ed-shadow-1);
                z-index:100;
             }
              
              .week-header-title{
                padding-left:35px;
              }

           .week-body{
              ul{
                padding:0px; 
                  
                 li{
                    margin:15px 0px;
                    list-style:none;
                    border-bottom:1px solid var(--ed-silver-light);
                    padding-bottom:10px;
                    padding-left:10px; 

                      .small-el-title{
                          font-size:14px;
                          color:var(--ed-grey-text);   
                      }

                      .time{
                          font-size:13px;
                          margin-top:5px;

                          svg{
                              margin-right:5px;
                          }
                      }


                 }
              }
           }  
        }

        .week-item.wh1{&:before{background:var(--ed-orange);}}
        .week-item.wh2{&:before{background:var(--ed-green);}}
        .week-item.wh3{&:before{background:var(--ed-blue);}}
        .week-item.wh4{&:before{background:var(--ed-purple-light);}}
        .week-item.wh5{&:before{background:var(--ed-red);}}
        .week-item.wh6{&:before{background:var(--ed-brown);}}
        .week-item.wh7{&:before{background:var(--ed-gold);}} 

  } 

   .week-calendar-box{
      min-width:300px; 
      margin-bottom:21px !important;   
      border-radius:6px; 
      min-height:150px; 
      background:var(--ed-white);  
      box-shadow:var(--ed-shadow-df); 
      padding:20px;
      position: relative; 
   }
 
   .Big-Box{
       width:100%;
       min-height:320px;
       max-height:320px;
       padding-left:20px;

       .f-height{
           height:100%; 
           .center{
              margin-top:40px;
           }
       }
   }
`;

const FlexBox = styled.div`
   display:flex;
   width:100%;
   min-width:720px;
   max-width:520px;
   flex-wrap:wrap;
   justify-content:space-between;
   
   .small-box{
      min-width:350px;
      max-width:350px;

      .title{
          font-size:16px;
          font-weight:600;
      }

      .icon{
         width:50px;
         height:50px;
         border-radius:100%; 
         margin-right:10px;
         display:flex;
         align-items:center;
         justify-content:center;

            svg{
                 fill:var(--ed-white);
                 color:var(--ed-white);
            }
      }
   }

      react-beautiful-dnd
`;

const Box = styled.div`
   width:100%;
   border-radius:6px; 
   min-height:150px;
   margin-bottom:21px !important;
   background:var(--ed-white);  
   box-shadow:var(--ed-shadow-df); 
   padding:20px;
   position: relative;

   h4{ 
      font-size:20px;
      font-weight:600; 
      margin-top:20px !important;
   }

   h5{ 
      font-size:20px;
      font-weight:600;  
   }

   h1{ 
      font-size:24px;
      font-weight:600; 
   }
 
`

export default TeacherDashboardTabItem