import React, { useState, useEffect } from 'react'
import { Avatar } from '@mui/material';
import { flexbox } from '@mui/system';
import { Link } from 'react-router-dom';
import Table from './Table';
import axios from 'axios';
import { Delete, Description, Edit, PreviewOutlined, Refresh } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import { GetAcademiclevel_byclass, GetCicle_byclass, GetClass, GetClasstitle_byclass } from '../../../General/components/InstituteData';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import DeleteModal from '../elements/DeleteModal';
import TableGrid from '../../../General/components/TableGrid';
import { Badge } from 'react-bootstrap';
import CalcAgeByBirthday from '../../../General/components/CalcAgeByBirthday';
import RefreshButton from '../../../General/components/RefreshButton';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import EduallSmartBoot from '../../../General/components/EduallSmartBoot';


const TABLEURL = Hoot() + "eduallstudentsapi/get/";


const columns = [
  {
    field: 'index',
    headerName: 'Nº de matrícula',
    resizable: true,
    cellRenderer: (props) => {
      return <SwitchFromPages link={`studentinfo/${props.data.id}`}
        menu='3' menu_item='17' toggle_btn={<span className='text-dark'>{props.data.code}</span>} />
    }
  },
  {
    field: 'name',
    headerName: 'Nome',
    resizable: true,
    width: 400,
    cellRenderer: (props) => {
      return <SwitchFromPages link={`studentinfo/${props.data.id}`}
        menu='3' menu_item='17' toggle_btn={
          <div className='ed-flex'>
            <Avatar alt={props.data.sortName} className='df' src={props.data.picture !== "" ? Hoot() + props.data.picture : ""} />
            <span className='ml-2'>{props.data.name}</span>
          </div>
        } />
    }
  },
  {
    field: 'doc',
    headerName: 'Doc. de Identificação',
    resizable: true,
    width: 200,
  },
  {
    field: 'class',
    headerName: 'Turma',
    resizable: true,
    width: 170
  },
  {
    field: 'cicle',
    headerName: 'Ciclo',
    resizable: true,
    with:120
  }, 
  {
    field: 'sponsor',
    headerName: 'Bolseiro',
    resizable: true,
    width: 100,
    cellRenderer: (props) => {
      return props.data.sponsor ===  false ?
        <Badge bg='danger'>Não</Badge>
        : <Badge bg='info'>Sim</Badge>
    }
  },
  {
    field: 'gender',
    headerName: 'Genero',
    resizable: true,
    width: 130,
    cellRenderer: (props) => {
      return props.data.gender === "female" ?
        <Badge bg='danger'>Femenino</Badge>
        : <Badge bg='info'>Masculino</Badge>
    }
  },
  {
    field: 'status',
    headerName: 'Status',
    resizable: true,
    width:110,
    cellRenderer: (props) => {
      return Math.floor(props.data.status) === 1 ?
        <Badge bg='info'><div className="text-dark">Activo</div></Badge> :
        <Badge bg='danger'><div className="text-dark">Inactivo</div></Badge>
    }
  },
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true,
    cellRenderer: (props) => {
      return <div className="ed-flex">
        <Link to={`/updatestudent/${props.data.id}`}>
          <button className="btn-circle bg-success text-light">
            <Edit />
          </button>
        </Link>
        <DeleteModal title='este estudante' url={Hoot() + `eduallstudentdelete/delete/${props.data.id}`}
          message='Estudante deletado com sucesso' toggle_btn={
            <button className="btn-circle bg-danger ml-2 text-light">
              <Delete />
            </button>
          } />
      </div>;
    }
  }
];




function StudentList() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);


  async function loadData() {
    setLoadStatus(0);
    try {
      setLoaded(false);
      const response = await axios.get(TABLEURL);
      const rows = response.data
        .map((item) => ({
          id: item.ed_student_id,
          code: item.ed_student_code,
          picture: item.ed_student_picture,
          name: item.ed_student_name,
          doc: item.ed_student_identityCard,
          sortName: item.ed_student_name,
          age: CalcAgeByBirthday(item.ed_student_birthday) + " anos",
          class: item.ed_class_title,
          sponsor:item.ed_student_scholarshipHolder*1 === 1,
          cicle: item.ed_cicle_title,
          status: item.ed_student_status,
          gender: item.ed_student_gender,
          action: "",
        }))
        .sort((a, b) =>
          a.sortName.localeCompare(b.sortName, "pt", { sensitivity: "base" })
        )
        .map((item, index) => ({
          ...item,
          index: index + 1,
        }));



      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      console.clear();
      setInterval(() => {
          console.log(error);
      }, 3000);
      setLoadStatus(1);
      setLoaded(true);
    }
  }

  useEffect(() => {
    loadData();
  }, []);




  if (load) {
    return (
      <div id='ed-custom-table-data' >
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista dos estudantes'
          TableBtn={
            <div className='ed-flex' > 
              <button id='ed-custom-table-data-btn'
                onClick={() =>
                  ExportDataToTablesToPdf({
                    fileName: "Lista dos estudantes",
                    headerId: null,
                    contentId: "ed-custom-table-data",
                    footerId: null,
                    rotation: "landscape",
                    buttonId: "ed-custom-table-data-btn",
                    customHeader: "Lista dos estudantes",
                    gender: true,
                    excludedColumns: ["Ação"]
                  })
                }
                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
              </button>
              <button
                className='btn-icon btn btn-export-data ml-2'
                onClick={() => {
                  ExportDataForTablesExcel("lista dos estudanets", ["Ação"]);
                }}
              >
                <PiMicrosoftExcelLogoDuotone />
              </button>
              <RefreshButton action={loadData} status={LoadStatus} />
            </div>
          }
        />
      </div>
    )
  } else {
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista dos estudantes'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    )
  }

}

export default StudentList