import React, { useState } from 'react';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap';
import { Save, Update } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import { toast } from 'react-hot-toast';
import axios from 'axios';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import { GetInstituteCode } from '../../../General/components/InstituteData';
import { ImagePreview } from '../elements/ImagePreview';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import RefreshList from '../../../General/components/RefreshList';

function NewDriverModal(props) {
  const [show, setShow] = useState(false);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [Founded, SetFounded] = useState(null);
  const [image, setImage] = useState([]);
  const [founded, setFounded] = useState(null);
  const [Cover, setCover] = useState("");


  const [form, setForm] = useState({
    driver_name: "",
    driver_phone: "",
    driver_nif: "",
    driver_city: "",
    driver_email: "",
    driver_address: "",
    driver_status: "",
    driver_identification_number: "",
    driver_neighborhood: "",
    driver_picture: [],
  });
  const [errors, setErrors] = useState({});
  const [showBox, setShowBox] = useState(false);

  const handleClose = () => {
    setShowBox(false);
    setTimeout(() => setShow(false), 1200);
  };

  const handleShow = () => {
    setShowBox(true);
    setShow(true);
    setTimeout(() => GET_DATA(), 1000);
  };

  const FORM_URLS = [
    Hoot() + 'edualltransportdriverregister/post/',
    props.get || '',
    props.url || ''
  ];

  const GET_DATA = async () => {
    if (props.update) {
      try {
        const response = await axios.get(FORM_URLS[1]);
        if (response.data.length > 0) {
          setForm({
            driver_name: response.data[0].ed_transport_driver_name,
            driver_phone: response.data[0].ed_transport_driver_phone,
            driver_nif: response.data[0].ed_transport_driver_nif,
            driver_city: response.data[0].ed_transport_driver_city,
            driver_email: response.data[0].ed_transport_driver_email,
            driver_address: response.data[0].ed_transport_driver_address,
            driver_status: response.data[0].ed_transport_driver_status,
            driver_identification_number: response.data[0].ed_transport_driver_identification_number,
            driver_neighborhood: response.data[0].ed_transport_driver_neighborhood,
          });
          setCover(Hoot() + response.data[0].ed_transport_driver_picture)
        } else {
          toast.error("Não foi possível encontrar as informações do motorista!");
        }
      } catch (error) {
        console.clear();
        console.log(error.response);
        toast.error("Erro ao carregar os dados do motorista!");
      }
    }
  };

  const handleInput = (e) => {
    const { id, value } = e.target;
    setField(id, value);
  };

  const setField = (field, value) => {
    setForm({ ...form, [field]: value });
    if (!!errors[field]) setErrors({ ...errors, [field]: null });
  };

  const GetAvatarImage = (e) => {
    setImage(e);
    setField("driver_picture", e);
  };

  const validateForm = () => {
    const newErrors = {};
    setRegisterStatus(0);

    if (!form.driver_name.trim()) newErrors.driver_name = 'Nome do motorista é obrigatório!';
    if (!form.driver_phone.trim()) newErrors.driver_phone = 'Número de telefone é obrigatório!';
    if (!form.driver_nif.trim()) newErrors.driver_nif = 'NIF é obrigatório!';
    if (!form.driver_city.trim()) newErrors.driver_city = 'Cidade é obrigatória!';
    if (!form.driver_email.trim()) newErrors.driver_email = 'Email é obrigatório!';
    if (!form.driver_address.trim()) newErrors.driver_address = 'Endereço é obrigatório!';
    if (!form.driver_status * 1 === NaN) newErrors.driver_status = 'Status do motorista é obrigatório!';
    if (!form.driver_identification_number.trim()) newErrors.driver_identification_number = 'Número de identificação é obrigatório!';
    if (!form.driver_neighborhood.trim()) newErrors.driver_neighborhood = 'Bairro é obrigatório!';

    return newErrors;
  };

  const FormSubmit = (e) => {
    e.preventDefault();
    const formErrors = validateForm();

    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os campos obrigatórios!");
      setRegisterStatus(1);
    } else {
      const formData = new FormData();

      formData.append("driver_name", form.driver_name);
      formData.append("driver_phone", form.driver_phone);
      formData.append("driver_nif", form.driver_nif);
      formData.append("driver_city", form.driver_city);
      formData.append("driver_email", form.driver_email);
      formData.append("driver_address", form.driver_address);
      formData.append("driver_status", form.driver_status);
      formData.append("driver_identification_number", form.driver_identification_number);
      formData.append("driver_neighborhood", form.driver_neighborhood);
      formData.append("driver_picture", image);


      if (!props.update) {
        try {
          axios.post(FORM_URLS[0], formData).then(() => {
            toast.success("Motorista registrado com sucesso!");
            setForm({ ...form, driver_picture: [] });
            ClearInputs();
            setRegisterStatus(2);
            RefreshList(`.el-refresh-list`);
          }).catch((error) => {
            console.clear();
            console.log(error.response, image);
            toast.error("Lamentamos, mas não foi possível executar esta ação!");
            setRegisterStatus(1);
          });
        } catch (error) {
          console.clear();
          console.log(error.response, image);
          toast.error("Lamentamos, mas não foi possível executar esta ação!");
          setRegisterStatus(1);
        }
      } else {
        try {
          axios.put(FORM_URLS[2], formData).then(() => {
            toast.success("Motorista atualizado com sucesso!");
            setForm({ ...form, driver_picture: [] });
            ClearInputs();
            setRegisterStatus(2);
            RefreshList(`.el-refresh-list`);
            setTimeout(() => handleClose(), 1500);
          }).catch((error) => {
            const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
            toast.error(msg);
            setRegisterStatus(1);
          });
        } catch (error) {
          const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
          toast.error(msg);
          setRegisterStatus(1);
        }
      }
    }
  };

  return (
    <div>
      <div onClick={handleShow}>
        {props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main ml-2'><AddCircleOutlineIcon /> Registrar Motorista</button>}
      </div>
      <Modal size='lg' dialogAs={DraggableModal} centered className={showBox ? ModalAnimationShow() : ModalAnimationClose()} show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>{props.title ? props.title : 'Registrar '} Motorista</h5>
            </div>
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={FormSubmit}>
          <Modal.Body className='scrollLimit'>
            <div className="ed-flex mb-3">
              <ImagePreview Cover={Cover} Picture={GetAvatarImage} />
              <div className="block col">
                <Form.Group className="mb-3 mt-2"  >
                  <Form.Label>Nome<span className="text-danger ml-2">*</span> </Form.Label>
                  <Form.Control type="text" required onChange={handleInput} className={!!errors.driver_name && 'is-invalid'} value={form.driver_name}
                    isInvalid={!!errors.driver_name} id="driver_name" />
                  <Form.Control.Feedback type='invalid'>{errors.driver_name}</Form.Control.Feedback>
                </Form.Group>
                <Form.Group className="mb-3"  >
                  <Form.Label>Nº do bilhete de identificação<span className="text-danger ml-2">*</span> </Form.Label>
                  <Form.Control required type="text" onChange={handleInput} className={!!errors.driver_identification_number && 'is-invalid'} value={form.driver_identification_number}
                    isInvalid={!!errors.driver_identification_number} id="driver_identification_number" />
                  <Form.Control.Feedback type='invalid'>{errors.driver_identification_number}</Form.Control.Feedback>
                </Form.Group>
              </div>
            </div>
            <Form.Group className="mb-3"  >
              <Form.Label>Nif<span className="text-danger ml-2">*</span> </Form.Label>
              <Form.Control required onChange={handleInput} className={!!errors.driver_nif && 'is-invalid'} value={form.driver_nif}
                isInvalid={!!errors.driver_nif} id="driver_nif" />
              <Form.Control.Feedback type='invalid'>{errors.driver_nif}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Status <span className="text-danger ml-2">*</span> </Form.Label>
              <Form.Select onChange={handleInput} required className={!!errors.driver_status && 'is-invalid'} value={form.driver_status}
                isInvalid={!!errors.driver_status} id="driver_status" >
                <option value="0" selected>Activo</option>
                <option value="1" selected>Inactivo</option>
              </Form.Select>
              <Form.Control.Feedback type='invalid'>{errors.driver_status}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3"  >
              <Form.Label>Endereço <span className="text-danger ml-2">*</span> </Form.Label>
              <Form.Control required onChange={handleInput} className={!!errors.driver_address && 'is-invalid'} value={form.driver_address}
                isInvalid={!!errors.driver_address} id="driver_address" />
              <Form.Control.Feedback type='invalid'>{errors.driver_address}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3"  >
              <Form.Label>Bairro <span className="text-danger ml-2">*</span> </Form.Label>
              <Form.Control type="text" onChange={handleInput} required className={!!errors.driver_neighborhood && 'is-invalid'} value={form.driver_neighborhood}
                isInvalid={!!errors.driver_neighborhood} id="driver_neighborhood" />
              <Form.Control.Feedback type='invalid'>{errors.driver_neighborhood}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3"  >
              <Form.Label>Cidade <span className="text-danger ml-2">*</span> </Form.Label>
              <Form.Control type="text" onChange={handleInput} required className={!!errors.driver_city && 'is-invalid'} value={form.driver_city}
                isInvalid={!!errors.driver_city} id="driver_city" />
              <Form.Control.Feedback type='invalid'>{errors.driver_city}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3"  >
              <Form.Label>E-mail <span className="text-danger ml-2">*</span> </Form.Label>
              <Form.Control type="text" onChange={handleInput} required className={!!errors.driver_email && 'is-invalid'} value={form.driver_email}
                isInvalid={!!errors.driver_email} id="driver_email" />
              <Form.Control.Feedback type='invalid'>{errors.driver_email}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3"  >
              <Form.Label>Telefone<span className="text-danger ml-2">*</span> </Form.Label>
              <Form.Control type="text" onChange={handleInput} required className={!!errors.driver_phone && 'is-invalid'} value={form.driver_phone}
                isInvalid={!!errors.driver_phone} id="driver_phone" />
              <Form.Control.Feedback type='invalid'>{errors.driver_phone}</Form.Control.Feedback>
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <div className="ed-space">
              <div className="ed-flex"></div>
              <div className="ed-flex">
                <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                {props.update ? (Founded === false ? <div></div> :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />}
              </div>
            </div>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  );
}

export default NewDriverModal;


