 import React, { useEffect, useState } from "react";
import { Tabs, Tab, Form, Button, Table, Modal, Row, Col, InputGroup, Spinner, Alert, Badge, Card } from "react-bootstrap";
import ReactQuill from "react-quill";
import 'react-quill/dist/quill.snow.css';
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";
import Hoot from "../../General/components/Hoot";

// ================================
// Axios helper
// ================================
const http = axios.create({
  withCredentials: true,
  headers: { "Content-Type": "application/json" }
});

async function api(url_api, opts = {}) {
  const url = Hoot() + url_api;
  const { method = "GET", body, headers } = opts;
  try {
    const res = await http.request({
      url,
      method,
      data: body,
      headers: { ...(headers || {}) }
    });
    return res.data;
  } catch (err) {
    const msg =
      err?.response?.data?.message ||
      err?.message ||
      "Ocorreu um erro inesperado";
    throw new Error(msg);
  }
}

async function uploadFile(file, field = "file") {
  const fd = new FormData();
  fd.append(field, file);
  try {
    const res = await axios.post("/api/site/upload", fd, {
      withCredentials: true,
      headers: { "Content-Type": "multipart/form-data" },
      onUploadProgress: (e) => {
        // Opcional: poderias ligar isto a um estado/ barra de progresso
        // const pct = Math.round((e.loaded * 100) / (e.total || 1));
      }
    });
    return res.data; // { success, url }
  } catch (err) {
    const msg =
      err?.response?.data?.message ||
      err?.message ||
      "Upload falhou";
    throw new Error(msg);
  }
}

export default function WebsiteManagement() {
  const [key, setKey] = useState("template");
  const [loading, setLoading] = useState(false);

  // ====== ABA 0: Template & Domínio ======
  const [templates, setTemplates] = useState([]);
  const [settings, setSettings] = useState({ ed_template_code:"", ed_domain:"" });
  const [domainInput, setDomainInput] = useState("");
  const [domainCheck, setDomainCheck] = useState({ available: null, reason: "", suggestions: [] });



  const loadTemplates = async () => {
    const rows = await api("/api/site/templates");
    setTemplates(rows);
  };
  const loadSettings = async () => {
    const s = await api("/api/site/settings");
    setSettings(s || { ed_template_code:"", ed_domain:"" });
    setDomainInput(s?.ed_domain || "");
  };


  const setTemplate = async (code) => {
    setLoading(true);
    const id = toast.loading("A atualizar template…");
    try{
      await api("/api/site/template/select", { method:"POST", body: JSON.stringify({ ed_template_code: code }) });
      setSettings(s=>({ ...s, ed_template_code: code }));
      toast.success(`Template "${code}" definido como padrão.`, { id });
    } catch(e){ toast.error(e.message, { id }); }
    finally{ setLoading(false); }
  };


  const checkDomain = async () => {
    setLoading(true);
    const id = toast.loading("A verificar domínio…");
    try{
      const r = await api("/api/site/domain/check", { method:"POST", body: JSON.stringify({ ed_domain: domainInput }) });
      setDomainCheck(r);
      if (r.available) toast.success("Domínio disponível ✅", { id });
      else toast("Domínio indisponível", { id, icon: "⚠️" });
    } catch(e){ toast.error(e.message, { id }); }
    finally{ setLoading(false); }
  };


  const registerDomain = async () => {
    setLoading(true);
    const id = toast.loading("A registar domínio…");
    try{
      const r = await api("/api/site/domain/register", { method:"POST", body: JSON.stringify({ ed_domain: domainInput }) });
      setSettings(s=>({ ...s, ed_domain: r.ed_domain }));
      toast.success(`Domínio "${r.ed_domain}" registado para a escola.`, { id });
      setDomainCheck({ available: true, reason:"", suggestions: [] });
    } catch(e){ toast.error(e.message, { id }); }
    finally{ setLoading(false); }
  };



  // ====== Contactos ======
  const [contacts, setContacts] = useState({ ed_phone:"", ed_map_iframe:"", ed_whatsapp:"", ed_email:"", ed_address:"" });
  const loadContacts = async () => { setContacts(await api("/api/site/contacts")); };
  const saveContacts = async () => {
    setLoading(true);
    const id = toast.loading("A guardar contactos…");
    try{
      await api("/api/site/contacts",{method:"POST",body:JSON.stringify(contacts)});
      toast.success("Contactos guardados.", { id });
    }catch(e){ toast.error(e.message, { id }); }
    finally{ setLoading(false); }
  };




  // ====== Cursos ======
  const [courses, setCourses] = useState([]);
  const [courseModal, setCourseModal] = useState({ show:false, editing:null, form:{ ed_name:"", ed_description_html:"", ed_image_url:"" }});
  const loadCourses = async () => setCourses(await api("/api/site/courses"));
  const openCourseModal = (row=null)=> setCourseModal({
    show:true,
    editing:row?.ed_id||null,
    form: row ? { ed_name:row.ed_name, ed_description_html:row.ed_description_html||"", ed_image_url:row.ed_image_url||"" }
               : { ed_name:"", ed_description_html:"", ed_image_url:"" }
  });


  
  const saveCourse = async ()=>{ 
    setLoading(true);
    const id = toast.loading("A guardar curso…");
    try{ 
      const {editing,form}=courseModal; 
      const url = editing?`/api/site/courses/${editing}`:'/api/site/courses'; 
      const m = editing?'PUT':'POST'; 
      await api(url,{method:m,body:JSON.stringify(form)}); 
      setCourseModal(s=>({...s,show:false})); 
      await loadCourses(); 
      toast.success(`Curso ${editing?'atualizado':'criado'}.`, { id });
    }catch(e){ toast.error(e.message, { id }); }
    finally{ setLoading(false); } 
  };



  const deleteCourse = async idRow => { 
    if(!window.confirm("Eliminar este curso?"))return; 
    setLoading(true);
    const id = toast.loading("A eliminar curso…");
    try{ 
      await api(`/api/site/courses/${idRow}`,{method:"DELETE"}); 
      await loadCourses(); 
      toast.success("Curso eliminado.", { id });
    }catch(e){ toast.error(e.message, { id }); }
    finally{ setLoading(false); } 
  };




  // ====== Slides ======
  const [slides, setSlides] = useState([]);
  const [slideModal, setSlideModal] = useState({ show:false, editing:null, form:{ ed_title:"", ed_description:"", ed_link:"", ed_image_url:"", ed_order:1 }});
  const loadSlides = async ()=> setSlides(await api("/api/site/slides"));
  const openSlideModal = (row=null)=> setSlideModal({ 
    show:true, editing:row?.ed_id||null, 
    form: row ? { ed_title:row.ed_title||"", ed_description:row.ed_description||"", ed_link:row.ed_link||"", ed_image_url:row.ed_image_url||"", ed_order:row.ed_order||1 }
              : { ed_title:"", ed_description:"", ed_link:"", ed_image_url:"", ed_order:(slides.length+1) }
  });
  const saveSlide = async ()=>{ 
    setLoading(true); 
    const id = toast.loading("A guardar slide…");
    try{ 
      const {editing,form}=slideModal; 
      const url = editing?`/api/site/slides/${editing}`:'/api/site/slides'; 
      const m = editing?'PUT':'POST'; 
      await api(url,{method:m,body:JSON.stringify(form)}); 
      setSlideModal(s=>({...s,show:false})); 
      await loadSlides(); 
      toast.success(`Slide ${editing?'atualizado':'criado'}.`, { id });
    }catch(e){ toast.error(e.message, { id }); }
    finally{ setLoading(false); } 
  };
  const deleteSlide = async idRow => { 
    if(!window.confirm("Eliminar este slide?"))return; 
    setLoading(true); 
    const id = toast.loading("A eliminar slide…");
    try{ 
      await api(`/api/site/slides/${idRow}`,{method:"DELETE"}); 
      await loadSlides(); 
      toast.success("Slide eliminado.", { id });
    }catch(e){ toast.error(e.message, { id }); }
    finally{ setLoading(false); } 
  };

  // ====== Secções (30) ======
  const [sections, setSections] = useState([]);
  const loadSections = async()=> setSections(await api("/api/site/sections/30"));
  const saveSection = async (ed_idx, patch)=>{ 
    setLoading(true); 
    const id = toast.loading(`A guardar secção #${ed_idx}…`);
    try{ 
      await api(`/api/site/sections/${ed_idx}`,{method:"PUT",body:JSON.stringify(patch)}); 
      await loadSections(); 
      toast.success(`Secção #${ed_idx} guardada.`, { id });
    }catch(e){ toast.error(e.message, { id }); }
    finally{ setLoading(false); } 
  };

  // ====== Branding ======
  const [brand, setBrand] = useState({ ed_school_name:"", ed_slogan:"", ed_logo_url:"" });
  const loadBrand = async ()=> setBrand(await api("/api/site/branding"));
  const saveBrand = async ()=>{ 
    setLoading(true); 
    const id = toast.loading("A guardar branding…");
    try{ 
      await api("/api/site/branding",{method:"POST",body:JSON.stringify(brand)}); 
      toast.success("Branding guardado.", { id });
    }catch(e){ toast.error(e.message, { id }); }
    finally{ setLoading(false); } 
  };

  // ====== Blog ======
  const [posts, setPosts] = useState([]);
  const [postModal, setPostModal] = useState({ show:false, editing:null, form:{ ed_title:"", ed_description:"", ed_content_html:"", ed_image_url:"", ed_published_at:"", ed_status:"draft" }});
  const loadPosts = async ()=> setPosts(await api("/api/site/posts"));
  const openPostModal = (row=null)=> setPostModal({ 
    show:true, editing:row?.ed_id||null, 
    form: row ? { 
      ed_title:row.ed_title||"", 
      ed_description:row.ed_description||"", 
      ed_content_html:row.ed_content_html||"", 
      ed_image_url:row.ed_image_url||"", 
      ed_published_at:(row.ed_published_at||"").slice(0,10), 
      ed_status:row.ed_status||"draft" 
    } : { ed_title:"", ed_description:"", ed_content_html:"", ed_image_url:"", ed_published_at:"", ed_status:"draft" }
  });
  const savePost = async ()=>{ 
    setLoading(true); 
    const id = toast.loading("A guardar post…");
    try{ 
      const {editing,form}=postModal; 
      const url = editing?`/api/site/posts/${editing}`:'/api/site/posts'; 
      const m = editing?'PUT':'POST'; 
      await api(url,{method:m,body:JSON.stringify(form)}); 
      setPostModal(s=>({...s,show:false})); 
      await loadPosts(); 
      toast.success(`Post ${editing?'atualizado':'criado'}.`, { id });
    }catch(e){ toast.error(e.message, { id }); }
    finally{ setLoading(false); } 
  };
  const deletePost = async idRow => { 
    if(!window.confirm("Eliminar este post?"))return; 
    setLoading(true); 
    const id = toast.loading("A eliminar post…");
    try{ 
      await api(`/api/site/posts/${idRow}`,{method:"DELETE"}); 
      await loadPosts(); 
      toast.success("Post eliminado.", { id });
    }catch(e){ toast.error(e.message, { id }); }
    finally{ setLoading(false); } 
  };

  // ====== Pré-matrículas ======
  const [pres, setPres] = useState([]);
  const loadPreEnrolls = async ()=> setPres(await api("/api/site/pre-enrollments"));

  useEffect(()=>{ (async()=>{
    setLoading(true);
    const id = toast.loading("A iniciar gestão do site…");
    try{
      await api("/api/site/setup/ensure-tables");
      await Promise.all([
        loadTemplates(), loadSettings(),
        loadContacts(), loadCourses(), loadSlides(), loadSections(),
        loadBrand(), loadPosts(), loadPreEnrolls()
      ]);
      toast.success("Dados carregados.", { id });
    } catch(e){ toast.error(e.message, { id }); }
    finally{ setLoading(false); }
  })(); },[]);

  return (
    <div className="py-3">
      {/* React Hot Toast */}
      <Toaster position="top-right" />

      <h3 className="mb-3 title">Gestão do Site da Escola</h3>

      <Tabs activeKey={key} onSelect={(k)=>setKey(k)} className="mb-3" justify>
        {/* 0) Template & Domínio */}
        <Tab eventKey="template" title="Template & Domínio">
          <Row className="mb-3">
            <Col md={12}>
              <Alert variant="secondary" className="d-flex align-items-center justify-content-between">
                <div>
                  <div><strong>Template atual:</strong> {settings.ed_template_code || <em className="text-muted">— não definido —</em>}</div>
                  <div><strong>Domínio:</strong> {settings.ed_domain || <em className="text-muted">— não registado —</em>}</div>
                </div>
              </Alert>
            </Col>
          </Row>

          <h5 className="mb-2">Escolher Template</h5>
          <Row xs={1} md={3} className="g-3 mb-4">
            {templates.map(t=>(
              <Col key={t.ed_code}>
                <Card className={settings.ed_template_code===t.ed_code ? "border-primary" : ""}>
                  {t.ed_image_url && <Card.Img variant="top" src={t.ed_image_url} style={{objectFit:'cover',height:160}}/>}
                  <Card.Body>
                    <Card.Title className="d-flex justify-content-between align-items-center">
                      <span>{t.ed_title || t.ed_code}</span>
                      {settings.ed_template_code===t.ed_code && <Badge bg="primary">Selecionado</Badge>}
                    </Card.Title>
                    <Card.Text style={{minHeight:48}}>{t.ed_description}</Card.Text>
                    <div className="d-flex justify-content-end">
                      <Button variant={settings.ed_template_code===t.ed_code ? "secondary" : "outline-primary"} size="sm" onClick={()=>setTemplate(t.ed_code)} disabled={loading}>
                        {settings.ed_template_code===t.ed_code ? "Padrão" : "Definir como padrão"}
                      </Button>
                    </div>
                  </Card.Body>
                </Card>
              </Col>
            ))}
          </Row>

          <h5 className="mb-2">Domínio do Site</h5>
          <Row className="align-items-end">
            <Col md={8}>
              <Form.Group className="mb-2">
                <Form.Label>Nome do domínio (ex.: <code>suaescola.pt</code>)</Form.Label>
                <Form.Control value={domainInput} onChange={e=>setDomainInput(e.target.value.trim())} placeholder="ex.: escola-exemplo.pt"/>
              </Form.Group>
            </Col>
            <Col md={4} className="mb-2">
              <div className="d-flex gap-2">
                <Button variant="outline-primary" onClick={checkDomain} disabled={loading || !domainInput}>Verificar</Button>
                <Button onClick={registerDomain} disabled={loading || !domainInput || domainCheck.available===false}>Registar</Button>
              </div>
            </Col>
          </Row>

          {domainCheck.available === false && (
            <Alert variant="warning" className="mt-3">
              <div className="mb-2"><strong>Indisponível:</strong> {domainCheck.reason || "Este domínio já está em uso."}</div>
              {domainCheck.suggestions?.length > 0 && (
                <>
                  <div className="mb-1">Sugestões semelhantes (clique para usar):</div>
                  <div className="d-flex flex-wrap gap-2">
                    {domainCheck.suggestions.slice(0,10).map(sug=>(
                      <Badge key={sug} bg="light" text="dark" style={{cursor:'pointer'}} onClick={()=>setDomainInput(sug)}>{sug}</Badge>
                    ))}
                  </div>
                </>
              )}
            </Alert>
          )}

          {domainCheck.available === true && (
            <Alert variant="success" className="mt-3">✅ Este domínio parece disponível para registo interno.</Alert>
          )}
        </Tab>

        {/* 1) Contactos */}
        <Tab eventKey="contactos" title="Contactos">
          <Row>
            <Col md={6}>
              <Form.Group className="mb-3"><Form.Label>Telefone</Form.Label><Form.Control value={contacts.ed_phone||""} onChange={e=>setContacts(s=>({...s,ed_phone:e.target.value}))}/></Form.Group>
              <Form.Group className="mb-3"><Form.Label>WhatsApp</Form.Label><Form.Control value={contacts.ed_whatsapp||""} onChange={e=>setContacts(s=>({...s,ed_whatsapp:e.target.value}))}/></Form.Group>
              <Form.Group className="mb-3"><Form.Label>Email</Form.Label><Form.Control type="email" value={contacts.ed_email||""} onChange={e=>setContacts(s=>({...s,ed_email:e.target.value}))}/></Form.Group>
              <Form.Group className="mb-3"><Form.Label>Endereço</Form.Label><Form.Control value={contacts.ed_address||""} onChange={e=>setContacts(s=>({...s,ed_address:e.target.value}))}/></Form.Group>
              <Button onClick={saveContacts} disabled={loading}>{loading?<Spinner size="sm"/>:"Guardar"}</Button>
            </Col>
            <Col md={6}>
              <Form.Group className="mb-2"><Form.Label>Código do iFrame (Mapa)</Form.Label><Form.Control as="textarea" rows={6} value={contacts.ed_map_iframe||""} onChange={e=>setContacts(s=>({...s,ed_map_iframe:e.target.value}))}/></Form.Group>
              <div className="border rounded p-2">
                <div dangerouslySetInnerHTML={{ __html: contacts.ed_map_iframe || '<small class="text-muted">Pré-visualização do mapa</small>' }} />
              </div>
            </Col>
          </Row>
        </Tab>

        {/* 2) Cursos */}
        <Tab eventKey="cursos" title="Cursos">
          <div className="d-flex justify-content-end mb-2"><Button onClick={()=>openCourseModal(null)}>+ Novo Curso</Button></div>
          <Table striped hover responsive>
            <thead><tr><th>#</th><th>Imagem</th><th>Nome</th><th>Descrição</th><th>Ações</th></tr></thead>
            <tbody>
            {courses.map((c,i)=>(
              <tr key={c.ed_id}>
                <td>{i+1}</td>
                <td>{c.ed_image_url?<img src={c.ed_image_url} alt="" style={{height:40}}/>:'—'}</td>
                <td>{c.ed_name}</td>
                <td><div style={{maxWidth:320}} dangerouslySetInnerHTML={{ __html: (c.ed_description_html||'').slice(0,300) }} /></td>
                <td>
                  <Button size="sm" variant="outline-primary" className="me-2" onClick={()=>openCourseModal(c)}>Editar</Button>
                  <Button size="sm" variant="outline-danger" onClick={()=>deleteCourse(c.ed_id)}>Eliminar</Button>
                </td>
              </tr>
            ))}
            </tbody>
          </Table>

          <Modal show={courseModal.show} onHide={()=>setCourseModal(s=>({...s,show:false}))} size="lg" centered>
            <Modal.Header closeButton><Modal.Title>{courseModal.editing?"Editar Curso":"Novo Curso"}</Modal.Title></Modal.Header>
            <Modal.Body>
              <Form.Group className="mb-3"><Form.Label>Nome</Form.Label>
                <Form.Control value={courseModal.form.ed_name} onChange={e=>setCourseModal(s=>({...s,form:{...s.form,ed_name:e.target.value}}))}/>
              </Form.Group>
              <Form.Group className="mb-3"><Form.Label>Imagem</Form.Label>
                <InputGroup>
                  <Form.Control value={courseModal.form.ed_image_url} onChange={e=>setCourseModal(s=>({...s,form:{...s.form,ed_image_url:e.target.value}}))}/>
                  <Button variant="outline-secondary" onClick={async()=>{
                    const input=document.createElement('input');input.type='file';input.accept='image/*';
                    input.onchange=async ev=>{const file=ev.target.files?.[0];if(!file)return;setLoading(true);const tid=toast.loading("A fazer upload…");try{const up=await uploadFile(file);setCourseModal(s=>({...s,form:{...s.form,ed_image_url:up.url}}));toast.success("Upload concluído.",{id:tid});}catch(e){toast.error(e.message,{id:tid});}finally{setLoading(false);}};
                    input.click();
                  }}>Upload</Button>
                </InputGroup>
              </Form.Group>
              <Form.Group className="mb-2"><Form.Label>Descrição (HTML)</Form.Label>
                <ReactQuill theme="snow" value={courseModal.form.ed_description_html} onChange={v=>setCourseModal(s=>({...s,form:{...s.form,ed_description_html:v}}))}/>
              </Form.Group>
            </Modal.Body>
            <Modal.Footer>
              <Button variant="secondary" onClick={()=>setCourseModal(s=>({...s,show:false}))}>Fechar</Button>
              <Button onClick={saveCourse} disabled={loading}>{loading?<Spinner size="sm"/>:"Guardar"}</Button>
            </Modal.Footer>
          </Modal>
        </Tab>

        {/* 3) Slides */}
        <Tab eventKey="slides" title="Carrossel">
          <div className="d-flex justify-content-end mb-2"><Button onClick={()=>openSlideModal(null)}>+ Novo Slide</Button></div>
          <Table striped hover responsive>
            <thead><tr><th>Ordem</th><th>Imagem</th><th>Título</th><th>Descrição</th><th>Link</th><th>Ações</th></tr></thead>
            <tbody>
              {slides.map(s=>(
                <tr key={s.ed_id}>
                  <td><Badge bg="secondary">{s.ed_order}</Badge></td>
                  <td>{s.ed_image_url?<img src={s.ed_image_url} alt="" style={{height:40}}/>:'—'}</td>
                  <td>{s.ed_title}</td>
                  <td style={{maxWidth:300}}>{s.ed_description}</td>
                  <td><a href={s.ed_link} target="_blank" rel="noreferrer">{s.ed_link?.slice(0,32)}</a></td>
                  <td>
                    <Button size="sm" className="me-2" variant="outline-primary" onClick={()=>openSlideModal(s)}>Editar</Button>
                    <Button size="sm" variant="outline-danger" onClick={()=>deleteSlide(s.ed_id)}>Eliminar</Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </Table>
          <Modal show={slideModal.show} onHide={()=>setSlideModal(s=>({...s,show:false}))} size="lg" centered>
            <Modal.Header closeButton><Modal.Title>{slideModal.editing?"Editar Slide":"Novo Slide"}</Modal.Title></Modal.Header>
            <Modal.Body>
              <Row>
                <Col md={8}>
                  <Form.Group className="mb-2"><Form.Label>Título</Form.Label><Form.Control value={slideModal.form.ed_title} onChange={e=>setSlideModal(s=>({...s,form:{...s.form,ed_title:e.target.value}}))}/></Form.Group>
                  <Form.Group className="mb-2"><Form.Label>Descrição</Form.Label><Form.Control value={slideModal.form.ed_description} onChange={e=>setSlideModal(s=>({...s,form:{...s.form,ed_description:e.target.value}}))}/></Form.Group>
                  <Form.Group className="mb-2"><Form.Label>Link</Form.Label><Form.Control value={slideModal.form.ed_link} onChange={e=>setSlideModal(s=>({...s,form:{...s.form,ed_link:e.target.value}}))}/></Form.Group>
                </Col>
                <Col md={4}>
                  <Form.Group className="mb-2"><Form.Label>Imagem</Form.Label>
                    <InputGroup>
                      <Form.Control value={slideModal.form.ed_image_url} onChange={e=>setSlideModal(s=>({...s,form:{...s.form,ed_image_url:e.target.value}}))}/>
                      <Button variant="outline-secondary" onClick={async()=>{
                        const input=document.createElement('input');input.type='file';input.accept='image/*';
                        input.onchange=async ev=>{const file=ev.target.files?.[0];if(!file)return;setLoading(true);const tid=toast.loading("A fazer upload…");try{const up=await uploadFile(file);setSlideModal(s=>({...s,form:{...s.form,ed_image_url:up.url}}));toast.success("Upload concluído.",{id:tid});}catch(e){toast.error(e.message,{id:tid});}finally{setLoading(false);}};
                        input.click();
                      }}>Upload</Button>
                    </InputGroup>
                  </Form.Group>
                  <Form.Group><Form.Label>Ordem</Form.Label><Form.Control type="number" value={slideModal.form.ed_order} onChange={e=>setSlideModal(s=>({...s,form:{...s.form,ed_order:Number(e.target.value)||1}}))}/></Form.Group>
                </Col>
              </Row>
            </Modal.Body>
            <Modal.Footer>
              <Button variant="secondary" onClick={()=>setSlideModal(s=>({...s,show:false}))}>Fechar</Button>
              <Button onClick={saveSlide} disabled={loading}>{loading?<Spinner size="sm"/>:"Guardar"}</Button>
            </Modal.Footer>
          </Modal>
        </Tab>

        {/* 4) Secções (30) */}
        <Tab eventKey="seccoes" title="Secções (30)">
          <Alert variant="info">As 30 secções são criadas automaticamente por escola. Edite e guarde.</Alert>
          {sections.map(s=>(
            <div key={s.ed_idx} className="border rounded p-3 mb-3">
              <h5>Secção #{s.ed_idx}</h5>
              <Row>
                <Col md={5}>
                  <Form.Group className="mb-2"><Form.Label>Título</Form.Label>
                    <Form.Control value={s.ed_title||""} onChange={e=>setSections(arr=>arr.map(x=>x.ed_idx===s.ed_idx?{...x,ed_title:e.target.value}:x))}/>
                  </Form.Group>
                  <Form.Group className="mb-2"><Form.Label>Link</Form.Label>
                    <Form.Control value={s.ed_link||""} onChange={e=>setSections(arr=>arr.map(x=>x.ed_idx===s.ed_idx?{...x,ed_link:e.target.value}:x))}/>
                  </Form.Group>
                  <Form.Group className="mb-2"><Form.Label>Imagem (URL)</Form.Label>
                    <InputGroup>
                      <Form.Control value={s.ed_image_url||""} onChange={e=>setSections(arr=>arr.map(x=>x.ed_idx===s.ed_idx?{...x,ed_image_url:e.target.value}:x))}/>
                      <Button variant="outline-secondary" onClick={async()=>{
                        const input=document.createElement('input');input.type='file';input.accept='image/*';
                        input.onchange=async ev=>{const file=ev.target.files?.[0];if(!file)return;setLoading(true);const tid=toast.loading("A fazer upload…");try{const up=await uploadFile(file);setSections(arr=>arr.map(x=>x.ed_idx===s.ed_idx?{...x,ed_image_url:up.url}:x));toast.success("Upload concluído.",{id:tid});}catch(e){toast.error(e.message,{id:tid});}finally{setLoading(false);}};
                        input.click();
                      }}>Upload</Button>
                    </InputGroup>
                  </Form.Group>
                </Col>
                <Col md={7}>
                  <Form.Label>Descrição (HTML)</Form.Label>
                  <ReactQuill theme="snow" value={s.ed_description_html||""} onChange={v=>setSections(arr=>arr.map(x=>x.ed_idx===s.ed_idx?{...x,ed_description_html:v}:x))}/>
                </Col>
              </Row>
              <div className="text-end mt-2">
                <Button size="sm" onClick={()=>saveSection(s.ed_idx, sections.find(x=>x.ed_idx===s.ed_idx))} disabled={loading}>{loading?<Spinner size="sm"/>:"Guardar Secção"}</Button>
              </div>
            </div>
          ))}
        </Tab>

        {/* 5) Branding */}
        <Tab eventKey="branding" title="Branding">
          <Row>
            <Col md={6}>
              <Form.Group className="mb-3"><Form.Label>Nome da Escola</Form.Label>
                <Form.Control value={brand.ed_school_name||""} onChange={e=>setBrand(s=>({...s,ed_school_name:e.target.value}))}/>
              </Form.Group>
              <Form.Group className="mb-3"><Form.Label>Slogan</Form.Label>
                <Form.Control value={brand.ed_slogan||""} onChange={e=>setBrand(s=>({...s,ed_slogan:e.target.value}))}/>
              </Form.Group>
              <Form.Group className="mb-3"><Form.Label>Logotipo (URL)</Form.Label>
                <InputGroup>
                  <Form.Control value={brand.ed_logo_url||""} onChange={e=>setBrand(s=>({...s,ed_logo_url:e.target.value}))}/>
                  <Button variant="outline-secondary" onClick={async()=>{
                    const input=document.createElement('input');input.type='file';input.accept='image/*';
                    input.onchange=async ev=>{const file=ev.target.files?.[0];if(!file)return;setLoading(true);const tid=toast.loading("A fazer upload…");try{const up=await uploadFile(file);setBrand(s=>({...s,ed_logo_url:up.url}));toast.success("Upload concluído.",{id:tid});}catch(e){toast.error(e.message,{id:tid});}finally{setLoading(false);}};
                    input.click();
                  }}>Upload</Button>
                </InputGroup>
              </Form.Group>
              <Button onClick={saveBrand} disabled={loading}>{loading?<Spinner size="sm"/>:"Guardar"}</Button>
            </Col>
            <Col md={6}>
              <div className="border rounded p-3 text-center">
                {brand.ed_logo_url ? <img src={brand.ed_logo_url} alt="logo" style={{maxHeight:120}}/> : <div className="text-muted">Pré-visualização do logo</div>}
                <h4 className="mt-3">{brand.ed_school_name||"Nome da Escola"}</h4>
                <p className="text-muted">{brand.ed_slogan||"Slogan"}</p>
              </div>
            </Col>
          </Row>
        </Tab>

        {/* 6) Blog */}
        <Tab eventKey="blog" title="Blog">
          <div className="d-flex justify-content-end mb-2"><Button onClick={()=>openPostModal(null)}>+ Novo Post</Button></div>
          <Table striped hover responsive>
            <thead><tr><th>#</th><th>Imagem</th><th>Título</th><th>Status</th><th>Publicação</th><th>Ações</th></tr></thead>
            <tbody>
              {posts.map((p,i)=>(
                <tr key={p.ed_id}>
                  <td>{i+1}</td>
                  <td>{p.ed_image_url?<img src={p.ed_image_url} alt="" style={{height:40}}/>:'—'}</td>
                  <td>{p.ed_title}</td>
                  <td><Badge bg={p.ed_status==='published'?'success':p.ed_status==='draft'?'secondary':'warning'}>{p.ed_status}</Badge></td>
                  <td>{p.ed_published_at ? new Date(p.ed_published_at).toLocaleDateString() : '—'}</td>
                  <td>
                    <Button size="sm" className="me-2" variant="outline-primary" onClick={()=>openPostModal(p)}>Editar</Button>
                    <Button size="sm" variant="outline-danger" onClick={()=>deletePost(p.ed_id)}>Eliminar</Button>
                  </td>
                </tr>
              ))}
            </tbody>
          </Table>

          <Modal show={postModal.show} onHide={()=>setPostModal(s=>({...s,show:false}))} size="lg" centered>
            <Modal.Header closeButton><Modal.Title>{postModal.editing?"Editar Post":"Novo Post"}</Modal.Title></Modal.Header>
            <Modal.Body>
              <Row>
                <Col md={8}>
                  <Form.Group className="mb-2"><Form.Label>Título</Form.Label><Form.Control value={postModal.form.ed_title} onChange={e=>setPostModal(s=>({...s,form:{...s.form,ed_title:e.target.value}}))}/></Form.Group>
                  <Form.Group className="mb-2"><Form.Label>Descrição curta</Form.Label><Form.Control value={postModal.form.ed_description} onChange={e=>setPostModal(s=>({...s,form:{...s.form,ed_description:e.target.value}}))}/></Form.Group>
                  <Form.Group className="mb-2"><Form.Label>Conteúdo (HTML)</Form.Label>
                    <ReactQuill theme="snow" value={postModal.form.ed_content_html} onChange={v=>setPostModal(s=>({...s,form:{...s.form,ed_content_html:v}}))}/>
                  </Form.Group>
                </Col>
                <Col md={4}>
                  <Form.Group className="mb-2"><Form.Label>Imagem</Form.Label>
                    <InputGroup>
                      <Form.Control value={postModal.form.ed_image_url} onChange={e=>setPostModal(s=>({...s,form:{...s.form,ed_image_url:e.target.value}}))}/>
                      <Button variant="outline-secondary" onClick={async()=>{
                        const input=document.createElement('input');input.type='file';input.accept='image/*';
                        input.onchange=async ev=>{const file=ev.target.files?.[0];if(!file)return;setLoading(true);const tid=toast.loading("A fazer upload…");try{const up=await uploadFile(file);setPostModal(s=>({...s,form:{...s.form,ed_image_url:up.url}}));toast.success("Upload concluído.",{id:tid});}catch(e){toast.error(e.message,{id:tid});}finally{setLoading(false);}};
                        input.click();
                      }}>Upload</Button>
                    </InputGroup>
                  </Form.Group>
                  <Form.Group className="mb-2"><Form.Label>Status</Form.Label>
                    <Form.Select value={postModal.form.ed_status} onChange={e=>setPostModal(s=>({...s,form:{...s.form,ed_status:e.target.value}}))}>
                      <option value="draft">Rascunho</option>
                      <option value="scheduled">Agendado</option>
                      <option value="published">Publicado</option>
                    </Form.Select>
                  </Form.Group>
                  <Form.Group className="mb-2"><Form.Label>Data de publicação</Form.Label>
                    <Form.Control type="date" value={postModal.form.ed_published_at} onChange={e=>setPostModal(s=>({...s,form:{...s.form,ed_published_at:e.target.value}}))}/>
                  </Form.Group>
                </Col>
              </Row>
            </Modal.Body>
            <Modal.Footer>
              <Button variant="secondary" onClick={()=>setPostModal(s=>({...s,show:false}))}>Fechar</Button>
              <Button onClick={savePost} disabled={loading}>{loading?<Spinner size="sm"/>:"Guardar"}</Button>
            </Modal.Footer>
          </Modal>
        </Tab>

        {/* 7) Pré-matrículas */}
        <Tab eventKey="prematriculas" title="Pré-Matrículas">
          <Table striped hover responsive>
            <thead><tr><th>#</th><th>Nome</th><th>Email</th><th>Telefone</th><th>Curso</th><th>Data</th></tr></thead>
            <tbody>
              {pres.map((r,i)=>(
                <tr key={r.ed_id}>
                  <td>{i+1}</td><td>{r.ed_student_name}</td><td>{r.ed_email}</td><td>{r.ed_phone}</td>
                  <td>{r.ed_course}</td><td>{new Date(r.ed_created_at).toLocaleString()}</td>
                </tr>
              ))}
            </tbody>
          </Table>
        </Tab>

      </Tabs>
    </div>
  );
}
 
