import React, { useState, useEffect } from 'react'
import Table from './Table';
import { Delete, Edit, VisibilityOutlined } from '@mui/icons-material';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import TableGrid from '../../../General/components/TableGrid';
import RefreshButton from '../../../General/components/RefreshButton'; 
import { Avatar } from '@mui/material';
import NewMaintenenceModal from '../modal/NewMaintenenceModal';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
const TABLEURL = Hoot()+"edualltransportmaintenanceget/get/";

const StatusBadges = [
    <div className="badge col bg-warning">Pendente</div>,
    <div className="badge col bg-info">Em analise</div>,
    <div className="badge col bg-warning">Sem reparo</div>,
    <div className="badge col bg-success">Reparado</div>,
]
 
const columns = [
    {
      field: 'index',
      headerName: 'Nº',
      resizable: true,
      width: 90,
    },
    {
      field: 'vehicle',
      headerName: 'Viatura',
      resizable: true,
      width: 350, 
    },
    {
      field: 'status',
      headerName: 'Estado',
      resizable: true,
      width: 250,
      cellRenderer: (props) => {
        return <div className="col">{StatusBadges[props.data.status*1]}</div>
      }
    }, 
    {
      field: 'action',
      headerName: 'Ação',
      resizable: true, 
      cellRenderer: (props) => {
        return <div className="ed-flex">
          <NewMaintenenceModal title='Atualizar ' update='true' get={Hoot()+`edualltransportsinglemaintenanceget/get/${props.data.id}`}
            url={Hoot() + `edualltransportmainenanceupdate/update/${props.data.id}`} toggle_btn={
              <button className="btn-circle  bg-success text-light">
                <Edit />
              </button>} />
          <DeleteModal title='este registro' url={Hoot() + `edualltransportmaintenancedelete/delete/${props.data.id}`}
           message='Registro deletado com sucesso' toggle_btn={
            <button className="btn-circle bg-danger ml-2 text-light">
              <Delete />
            </button>} />
        </div>;
      }
    }
];
  


function MaintenanceTable() {
    const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData() {
    try {
      setLoadStatus(0);
      setLoaded(false);
      const response = await axios.get(TABLEURL);
      const rows = [];
      response.data.map((item, index) => {
        rows.push({
          index: index + 1,
          id:item.ed_transport_maintenance_id,
          vehicle:item.ed_transport_vehicle_model + " ("+ item.ed_transport_vehicle_plate +")" ,
          status:item.ed_transport_maintenance_status, 
          action: '',
        })
      });
      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoadStatus(1);
    }
  }

  useEffect(() => {
    loadData();
  }, []);


  if (load) {
    return (
      <div id="ed-custom-table-data" >
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista dos registros de manutenção'
          TableBtn={
            <div className='ed-flex'>
                <button id='ed-custom-table-data-btn'
                    onClick={() =>
                        ExportDataToTablesToPdf({
                            fileName: "Lista dos registros de manutenção",
                            headerId: null,
                            contentId:"ed-custom-table-data",
                            footerId: null,
                            rotation: "portrait",
                            buttonId: "ed-custom-table-data-btn",
                            customHeader: "Lista dos registros de manutenção",
                            excludedColumns: ["Ação"]
                        })
                    }
                    className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
                </button>
                <button className='btn-icon btn btn-export-data ml-2'
                    onClick={() => ExportDataForTablesExcel("Lista dos registros de manutenção", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
                </button>
                <RefreshButton action={loadData} status={LoadStatus} />
            </div>
        }
        />
      </div>
    )
  } else {
    return (
      <div>
        <><div className="d-none">*</div>
          <TableGrid
            TableHead={columns}
            TableBody={[]}
            TableTitle='Lista de motoristas'
            TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
          />
        </>
      </div>
    )
  }
}

export default MaintenanceTable