import React, { useState } from 'react';
import { Modal } from 'react-bootstrap';
import styled from "styled-components";
import DraggableModal from '../../../General/components/DraggableModal';
import { Avatar } from '@mui/material';
import { Link } from 'react-router-dom';
import { DeleteOutline, DownloadingOutlined } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import { GetAcademiclevel_byclass, GetClassroom_byclass, GetClasstitle_byclass, GetCourse_byclass, GetPeriod_byclass } from '../../../General/components/InstituteData';
import moment from 'moment';
import NumberToPrice from '../../../General/components/NumberToPrice';
import ReduceTextLength from '../../../General/components/ReduceTextLength';
import DeleteModal from '../elements/DeleteModal';
import { HiOutlineDocumentText } from 'react-icons/hi';
import { AccessTimeOutlined } from '@mui/icons-material';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import ReplaceWord from '../../../General/components/ReplaceWord';
import DownloadInvoicePDFButton from '../../../General/components/DownloadInvoicePDFButton';

function PopServicePaymentDetailsModal({ invoiceCode, toggle_btn, invoiceCodeID }) {
    const [show, setShow] = useState(false);
    const [Founded, SetFounded] = useState(null);
    const [CurrentFiles, SetCurrentFiles] = useState([]);
    const [Services, setServices] = useState([]);
    const [Student, setStudent] = useState({});
    const [Total, setTotal] = useState(0);
    const [Coin, setCoin] = useState('Kz');
    const [showBox, SetshowBox] = useState(false);

    const PaymentMethods = ["Dinheiro a mão", "Transferência", "Depósito", "TPA"];

    const handleClose = () => {
        SetshowBox(false);
        setTimeout(() => setShow(false), 1200);
    };

    const handleShow = () => {
        SetshowBox(true);
        setShow(true);
        setTimeout(() => {
            GET_DATA();
        }, 1000);
    };

    async function GET_DATA() {
        try {
            const response = await axios.get(Hoot() + "eduallservicepaymentsapi/get");
            const filtered = response.data.filter(i => i.ed_service_payment_invoiceCode === invoiceCode);

            if (filtered.length > 0) {
                SetFounded(true);
                setServices(filtered);
                setCoin(filtered[0].ed_coin_code);
                setStudent({
                    id: filtered[0].ed_student_id,
                    name: filtered[0].ed_student_name,
                    picture: filtered[0].ed_student_picture,
                    class: filtered[0].ed_student_class
                });

                const totalValue = filtered.reduce((sum, i) => {
                    const subtotal = (i.ed_service_payment_amount * i.ed_service_payment_price) -
                        ((i.ed_service_payment_price * i.ed_service_payment_amount * i.ed_service_payment_discount) / 100);
                    return sum + subtotal;
                }, 0);

                setTotal(totalValue);

                // carregar ficheiros do primeiro item (representante da fatura)
                const fileResponse = await axios.get(Hoot() + "eduallsingleuserfiles/get/" + filtered[0].ed_service_payment_file);
                if (fileResponse.data.length >= 1) SetCurrentFiles(fileResponse.data);
            } else {
                SetFounded(false);
            }
        } catch (error) {
            console.log(error);
            SetFounded(false);
        }
    }

    return (
        <div>
            <div onClick={handleShow}>
                {toggle_btn ? toggle_btn : <button className='btn btn-main bg-main'>Ver detalhes</button>}
            </div>

            <Modal size='md' centered className={showBox ? ModalAnimationShow() : ModalAnimationClose()} dialogAs={DraggableModal} show={show} onHide={handleClose}>
                <Modal.Header closeButton>
                    <Modal.Title>
                        <div className="ed-wrap align-center">
                            <UserOptionDropDown />
                            <div className="ed-block">
                                <h5 className='m0'>Detalhes da fatura</h5>
                                <small className='text-danger m0 sm-text'>Pagamentos de serviços</small>
                            </div>
                        </div>
                    </Modal.Title>
                </Modal.Header>

                <Modal.Body className='scrollLimit'>
                    {Founded === false && <p className='text-center text-danger'>Nenhum pagamento encontrado para esta fatura.</p>}
                    {Founded && (
                        <>
                            <Box className="boxItem">
                                <div className="ed-flex student-box">
                                    <SwitchFromPages link={`studentinfo/${Student.id}`}
                                        menu='3' menu_item='17' toggle_btn={
                                            <div className='ed-flex'>
                                                <Avatar alt={Student.name} className='df' src={Hoot() + Student.picture} sx={{ width: 90, height: 90 }} />
                                            </div>
                                        } />
                                    <div className="d-block ml-2 description">
                                        <h3 className='name '>Nome : <Link to='#' className='text-main label-student-name'>{Student.name}</Link></h3>
                                        <h5>Turma : <Link to='#' className='text-main label-student-class'><GetClasstitle_byclass ID={Student.class} /></Link></h5>
                                    </div>
                                </div>
                                <br /> 
                            </Box> 
                            <br />
                            <Main>
                                <ul>
                                    <li>Nº da Fatura : <b>{invoiceCode}</b></li>
                                    <li>Serviços incluídos nesta fatura:</li>
                                </ul>

                                {Services.map((srv, index) => (
                                    <ul key={index}>
                                        <li>Serviço : <b>{srv.ed_service_title}</b></li>
                                        <li>Quantidade : <b>{srv.ed_service_payment_amount}</b></li>
                                        <li>Preço unitário : <b>{NumberToPrice(srv.ed_service_payment_price)} {srv.ed_coin_code}</b></li>
                                        <li>Desconto : <b>{srv.ed_service_payment_discount}%</b></li>
                                        <li>Total deste serviço : <b>{NumberToPrice((srv.ed_service_payment_amount * srv.ed_service_payment_price) -
                                            ((srv.ed_service_payment_price * srv.ed_service_payment_amount * srv.ed_service_payment_discount) / 100))} {srv.ed_coin_code}</b></li>
                                        <li>Data de pagamento : <b>{moment(srv.ed_service_payment_registerDate).format("YYYY-MM-DD HH:mm")}</b></li>
                                        <li>Metodo : <b>{PaymentMethods[srv.ed_service_payment_type]}</b></li>
                                        {index < Services.length - 1 && <li><hr /></li>}
                                    </ul>
                                ))}

                                {CurrentFiles.length >= 1 && (
                                    <>
                                        <strong className="text-danger mb-2">Ficheiros anexados no momento de pagamento</strong>
                                        <div className='student-file-cp'>
                                            {CurrentFiles.map((item, index) => (
                                                <li className='student-file-el' id={`student-file-el-${index}`} key={index}>
                                                    <div className="ed-space">
                                                        <div className="ed-flex">
                                                            <div className="icon">
                                                                <HiOutlineDocumentText />
                                                            </div>
                                                            <div className="block">
                                                                <div className="title text-main"><ReduceTextLength text={item.ed_file_name.split("/")[1]} length={26} /></div>
                                                                <div className="ed-flex">
                                                                    <div className="date text-dark"><AccessTimeOutlined /><span>{moment(item.ed_file_register_date).format("YYYY-MM-DD HH:mm")}</span></div>
                                                                </div>
                                                            </div>
                                                        </div>
                                                        <div className="delete ed-flex">
                                                            <a href={Hoot() + item.ed_file_name} target="_blank" download={item.ed_file_name.split("/")[1]}>
                                                                <div className="btn-circle bg-main text-main">
                                                                    <DownloadingOutlined />
                                                                </div>
                                                            </a>
                                                            <DeleteModal remove_element={`#student-file-el-${index}`} title='este ficheiro' url={Hoot() + `eduallfiledelete/delete/${item.ed_file_id}`}
                                                                message='Ficheiro deletado com sucesso' toggle_btn={
                                                                    <div className="btn-circle bg-danger ml-2 text-light">
                                                                        <DeleteOutline />
                                                                    </div>} />
                                                        </div>
                                                    </div>
                                                </li>
                                            ))}
                                        </div>
                                    </>
                                )}

                                <div className="total mt-4">
                                    <div className="ed-space ed-flex">
                                        <div><h1 className='title'>Total Fatura : </h1></div>
                                        <div>
                                            <h1 className="title">{NumberToPrice(Total) + " " + Coin}</h1>
                                        </div>
                                    </div>
                                </div>
                            </Main>
                        </>
                    )}
                </Modal.Body>

                <Modal.Footer>
                    <div className="ed-space col">
                        <div></div>
                        <DownloadInvoicePDFButton toggle_btn documentId={invoiceCodeID} />
                    </div>
                </Modal.Footer>
            </Modal>
        </div>
    );
}

const Box = styled.div`
    width:100%; 
    border-radius:6px;   
    padding:0px 10px; 
    min-height:100px;  

    .student-box{
       position:absolute;
       left:0px;
       top:0px;
       width:100%;
       padding:10px 20px;
       background:var(--ed-background-color);
    }

    .description{
        .name{
            font-size:18px;
            margin-bottom:15px;
            margin-top:10px;
        }

        h5{
            font-size:16px;
        }
    }
`;

const Main = styled.main`
    ul{
        padding:0px;
        padding-left:10px;  
        li{
            padding:10px 0px;
            border-top:1px solid var(--ed-white-smoke);
            font-size:15px;
            font-weight:500;
            list-style:none;
            display:flex;
        }
        .total{
            padding:10px 0px;  
            border-top:4px double #000;
            border-bottom:4px double #000;
            h1{ font-size:18px; margin:0px; }
        }
    }
    .student-file-cp{
        li{ padding-left:10px; padding-right:10px; }
    }
`;

export default PopServicePaymentDetailsModal;
