import axios from 'axios'
import React, { useEffect, useState } from 'react'
import styled from "styled-components";
import Hoot from './Hoot';
import SwitchFromPages from './SwitchFromPages';
import {Avatar} from '@mui/material'; 
import SmallLoader from './SmallLoader';
import ReduceTextLength from './ReduceTextLength';
import { Form } from 'react-bootstrap'
import { Search } from '@mui/icons-material';
import { SadOutline, RefreshOutline } from 'react-ionicons'


function ClassInformationBox({ID}){
  const [Loaded, setLoaded] =  useState(null);
  const [Students, setStudents] =  useState([]);
  const [ActiveTab, setActiveTab] =  useState(1);


    const loadData = async()=>{
      setLoaded(null);
      try { 
        const [response1] = await Promise.all([ 
          axios.get(Hoot()+"eduallgetstudentsbyclass/"+ID)
       ]);  
       setStudents(response1.data); 
       setLoaded(true);
      } catch (error) {
        setLoaded(false);
      }
    } 

    const FilterValue = (e)=>{ 
      let val = e.target.value;
      let dt = Students.filter((item)=>
      item.ed_student_name.toLowerCase().includes(val) ||  
      item.ed_student_identityCard.toLowerCase().includes(val) ||
      item.ed_student_address.toLowerCase().includes(val)); 
      setStudents(dt); 
    }

    
 

    useEffect(() => {
      loadData();
    }, [ID]); 

  return (
    <Box>
      {Loaded !== null ? 
        <>
          {Loaded === true ? 
             <>
             <aside>
            <div className="header-area">
                 <div className="header-menu">
                      <div onClick={()=>setActiveTab(1)} className={ActiveTab === 1 ? "active bg-main col text-center ed-center ed-flex" : ""}>Estudantes</div>
                  </div>
            </div>
            <div className="body-area">
              <section className={ActiveTab === 1 ? "" : "d-none"}>
                 <h5 className="subtitle">Estudantes na turma ({Students.length})</h5>
                 <div className="search-box">
                    <Form onSubmit={(e)=> e.preventDefault()}>
                        <Form.Control onChange={FilterValue} placeholder="Pesquisar..." />
                        <Search/>
                    </Form>
                 </div>
                 <ul>
                    {Students.map((item, index)=>(
                     <SwitchFromPages link={`studentinfo/${item.ed_student_id}`}
                       menu='3'  menu_item='17'  toggle_btn={
                           <li className="ed-flex mb-2 student-item">
                              <Avatar alt={item.ed_student_name}  className='df' src={Hoot()+item.ed_student_picture} sx={{width:30,height:30}}/>
                              <div className="ml-2"><span><ReduceTextLength text={item.ed_student_name} length={20} /></span></div>
                           </li>
                       } /> 
                    ))}
                 </ul>
              </section>  
           </div>
            </aside>
            </>
            : 
            <div className="ed-flex ed-center col load-area pd-2">
               <div className="ed-block text-center">
                  <SadOutline color={'var(--ed-purple)'}   height="80px" width="80px"/>
                  <div className="mt-1">
                     <p>Lamentamos ocorreu um problema ao carregar as informações</p>
                  </div>
                  <button className="btn mt-1 btn-icon" onClick={()=>loadData()}><RefreshOutline color={"#ffff"} /></button>
               </div>
           </div>
          }
        </>
        :
        <>
          <div className="ed-flex ed-center col load-area pd-2">
              <SmallLoader size={60} />
          </div>
        </>
      }
    </Box>
  )
}

const Box = styled.div`
   min-width:250px;
   min-height:250px;
   font-family:var(--ed-font-1) !important;

   .search-box{
      margin:5px 0px;
      padding:2px 8px;
      border:1px solid var(--ed-silver-light);
      border-radius:6px;

      form{
         display:flex;
         align-items:center;

          input{
            width:100%;
            font-size:14px !important;
            width:100%;
            border:none !important;
            padding:4px !important;
          }

          svg{
            width:19px;
            height:19px;
          }
      }
   }

   .load-area{
      min-height:240px;

       p{
          color:var(--ed-grey-text);
       }
   }
   
   .body-area{ 
        padding:10px 4px;

        .subtitle{
            font-size:15px;
            font-weight:bolder;
            margin:5px 0px;
        }

        ul{
           padding:0px;
            margin:0px; 
            overflow-y:auto;
            max-height:130px; 

                    
            &::-webkit-scrollbar{
                width:6px !important;
                background-color:transparent !important;
            }
                
            &::-webkit-scrollbar-thumb{
                background:rgb(219, 219, 219) !important; 
                border-radius:30px;
            }

            .student-item{
              padding:5px;

                span{
                    font-size:14px;
                    font-weight:550;
                }
            }

            .student-item:hover{
                background:var(--ed-background-color);
            }
        }
    
   }

  .header-area{
      background:var(--ed-background-color);
      padding:10px;
      width:100%;

        .header-menu{
            display:flex;
              div{
                 margin-right:10px;
                 font-size:15px !important;
                 padding:4px 10px;
                 cursor:pointer;
              }

              .active{
                  color:var(--ed-white);
                  border-radius:30px;
              }
        }
  }
`;



export default ClassInformationBox