import React, {useState, useEffect} from 'react'
import Table from './Table';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import { Delete, Description, Edit ,OpenInBrowser, Refresh } from '@mui/icons-material';
import DeleteModal from '../elements/DeleteModal';
import NewCicleModal from '../modal/NewCicleModal';
import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import NewContactModal from '../modal/NewContactModal';
import { Avatar } from '@mui/material';

const contactTypes = ["",
    <div className="badge bg-info col">Estudante</div>,
    <div className="badge bg-warning col">Encarregado</div>,
    <div className="badge bg-danger col">Funcionário</div>,
    <div className="badge bg-success col">Outro</div>, 
];
const TABLEURL = Hoot()+"eduallgetinstitutecontacts/get"
const columns = [  
    { field: 'index', headerName: 'Nº', width:90},
    {
      field: 'name',
      headerName: 'Nome',
      resizable: true,
      width:300,
      cellRenderer:(props)=>{
        return  <div className='ed-flex'>
          <Avatar alt={props.data.name} className='df'  src={props.data.picture !== ""  ?  props.data.picture : ""} /> 
          <span className='ml-2'>{props.data.name}</span>
        </div> 
     }
    },
    {
      field: 'phone',
      headerName: 'Telefone',
      resizable: true,
      width:200
    },  
    {
        field: 'type',
        headerName: 'Tipo de contacto',
        resizable: true,
        width:200,
        cellRenderer:(props)=>{
            return contactTypes[props.data.type]  
         }
      },  
      {
        field: 'email',
        headerName: 'Email',
        resizable: true,
        width:300
      },  
    {
      field: 'action',
      headerName: 'Ação', 
       resizable: true,
       width:180,
       cellRenderer:(props) => { 
        return  <div className="ed-flex">
        <NewContactModal title='Atualizar ' update='true' get={Hoot()+`eduallgetsinglecontact/get/${props.data.id}`}  
         url={Hoot()+`eduallcontactupdate/update/${props.data.id}`} 
             toggle_btn={
               <button  className="btn-circle bg-success text-light">
                   <Edit/>
              </button> 
             } 
        />
       <DeleteModal title='este contacto ' url={Hoot()+`eduallcontactdelete/delete/${props.data.id}`} message='Contacto deletado com sucesso !' toggle_btn={ 
         <button  className="btn-circle bg-danger ml-2 text-light">
             <Delete/>
         </button>} />
       </div>;
      }
   }
  ];
  
  
function ContactsTable() {
    const [data, setData] = useState([]);  
    const [load, setLoaded] = useState(false);
    const [LoadStatus, setLoadStatus] = useState(null);
  
    async function loadData(){
     try {
       setLoadStatus(0); 
       setLoaded(false)
         const response = await axios.get(TABLEURL); 
         const rows = []; 
         response.data.map((item, index)=>{ 
           rows.push({
             id:item.ed_contact_id,
             index:index+1,
             type:item.ed_contact_type,
             name:item.ed_contact_name,
             phone:item.ed_contact_phone, 
             email:item.ed_contact_email, 
             picture:Hoot()+item.ed_contact_picture, 
          }) 
         }); 
         setData(rows); 
         setTimeout(() => {
           setLoaded(true);
         }, 200);
         setLoadStatus(2); 
     } catch (error) {
      setLoadStatus(1); 
     }
    };
    
    useEffect(()=>{ 
        loadData();  
    },[]);
   
   
  
    if(load){
        return (
        <div>
          <TableGrid
              TableHead={columns}
              TableBody={data}  
              TableTitle='Contactos da instituição'
              TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
          />
      </div>
      )
    }else{
      return (
        <div>
          <div className="d-none">*</div>
          <TableGrid
                TableHead={columns}
                TableBody={[]} 
                TableTitle='Contactos da instituição'
                TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
            />
      </div>
      )
    }
}

export default ContactsTable
