import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { Avatar } from '@mui/material';
import { Link } from 'react-router-dom';
import axios from 'axios';
import { Delete, Edit } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import TableGrid from '../../../General/components/TableGrid';
import { Badge } from 'react-bootstrap';
import { IoCloudDoneSharp, IoPersonCircleOutline, IoWarningOutline } from "react-icons/io5";
import NewTemporaryUserAccountModal from '../modal/NewTemporaryUserAccountModal';
import PopEmployeeDetailsModal from '../modal/PopEmployeeDetailsModal';
import { PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';

const TABLEURL = Hoot() + "eduallemployeesget/get/";

const columns = [
  { field: 'index', headerName: 'Nº', width: 90, resizable: true },
  {
    field: 'name',
    headerName: 'Nome do funcionário',
    resizable: true,
    minWidth: 300,
    cellRenderer: (props) => (
      <div className='ed-flex'>
        <Avatar className='df' alt={props.data.name} src={props.data.picture !== "" ? Hoot() + props.data.picture : ""} />
        <span className='ml-2'>{props.data.name}</span>
      </div>
    )
  },
  {
    field: 'gender',
    headerName: 'Genero',
    resizable: true,
    cellRenderer: (props) =>
      props.data.gender === 'male' ? <Badge bg='success'>Masculino</Badge> : <Badge bg='danger'>Femenino</Badge>
  },
  {
    field: 'charge',
    headerName: 'Cargo',
    resizable: true,
    sortable: false,
    cellRenderer: (props) => {
      if (props.value === 'Não atribuído') return <span className="text-danger" style={{ textDecoration: 'line-through' }}>{props.value}</span>;
      return <span>{props.value}</span>;
    }
  },
  {
    field: 'status',
    headerName: 'Status',
    minWidth: 130,
    resizable: true,
    cellRenderer: (props) =>
      Math.floor(props.data.status) === 1
        ? <Badge bg='info'><div className="text-dark">Activo</div></Badge>
        : <Badge bg='danger'><div className="text-dark">Inactivo</div></Badge>
  },
  {
    field: 'account',
    headerName: 'Conta Eduall',
    resizable: true,
    minWidth: 200,
    cellRenderer: (props) => {
      const hasAccount = props.data.has_active_account === 1;
      return (
        <div className="ed-flex col-lg-12">
          {hasAccount ? (
            <div className="col-lg-12">
              <button className="btn table-btn-large bg-green btn-small ed-flex ed-center text-light" disabled>
                <IoCloudDoneSharp />
                <span className="ml-1 text-light"> Conta ativa</span>
              </button>
            </div>
          ) : (
            <>
              {props.data?.email && /\S+@\S+\.\S+/.test(props.data.email) ? (
                <NewTemporaryUserAccountModal
                  email={props.data.email}
                  gender={props.data.gender}
                  userName={props.data.name}
                  toggle_btn={
                    <button className="btn table-btn-large bg-danger btn-small ed-flex ed-center text-light">
                      <IoPersonCircleOutline />
                      <span className="ml-1 text-light"> Criar conta</span>
                    </button>
                  }
                />
              ) : (
                <button className="btn table-btn-large bg-warning btn-small ed-flex ed-center text-dark" disabled>
                  <IoWarningOutline />
                  <span className="ml-1"> Email inválido</span>
                </button>
              )}
            </>
          )}
        </div>
      );
    }
  },
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true,
    cellRenderer: (props) => (
      <div className="ed-flex">
        <Link to={`/updateemployee/${props.data.id}`}>
          <button className="btn-circle bg-success text-light"><Edit /></button>
        </Link>
        <PopEmployeeDetailsModal get={Hoot() + `eduallsinglemployee/get/${props.data.id}`} toggle_btn={<PreviewButton />} />
        <DeleteModal
          title='este funcionário'
          url={Hoot() + `eduallemployeedelete/delete/${props.data.id}`}
          message='Funcionário deletado com sucesso'
          toggle_btn={<button className="btn-circle bg-danger ml-2 text-light"><Delete /></button>}
        />
      </div>
    )
  }
];

function EmployeeList() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData() {
    try {
      setLoaded(false);
      setLoadStatus(0);
      const response = await axios.get(TABLEURL);

      // Ordena A → Z e atualiza índice
      const sortedRows = response.data
        .map((item) => ({
          id: item.ed_employee_id,
          name: item.ed_employee_name,
          picture: item.ed_employee_picture,
          status: item.ed_employee_status,
          charge: item.job_title,
          email: item.ed_employee_email,
          gender: item.ed_employee_gender,
          has_active_account: item.has_active_account,
        }))
        .sort((a, b) => a.name.localeCompare(b.name))
        .map((item, index) => ({ ...item, index: index + 1 }));

      setData(sortedRows);
      setTimeout(() => setLoaded(true), 200);
      setLoadStatus(2);
    } catch (error) {
      setLoadStatus(1);
    }
  }

  useEffect(() => { loadData(); }, []);

  return (
    <div id="ed-custom-table-data">
      <TableGrid
        TableHead={columns}
        TableBody={data}
        TableTitle='Lista dos funcionários'
        TableBtn={
          <div className='ed-flex'>
            <button
              id='ed-custom-table-data-btn'
              onClick={() =>
                ExportDataToTablesToPdf({
                  fileName: "Lista dos funcionários",
                  headerId: null,
                  contentId: "ed-custom-table-data",
                  footerId: null,
                  rotation: "portrait",
                  buttonId: "ed-custom-table-data-btn",
                  customHeader: "Lista dos funcionários",
                  excludedColumns: ["Ação"]
                })
              }
              className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'>
              <PiFilePdfDuotone />
            </button>

            <button
              className='btn-icon btn btn-export-data ml-2'
              onClick={() => ExportDataForTablesExcel("Lista dos funcionários", ["Ação"])}>
              <PiMicrosoftExcelLogoDuotone />
            </button>
            <RefreshButton action={loadData} status={LoadStatus} />
          </div>
        }
      />
    </div>
  );
}

export default EmployeeList;
