function PaymentTooltip({ data, CurrentCoin }) {
  // Extraindo os totais dos objetos dentro de data
  const {
    totalTuitionObject,
    totalTransportObject,
    totalSalesObject,
    totalServicesPaidObject,
    totalPayableObject,
    totalReceivableObject
  } = data;

  // Extraindo os valores numéricos
  const totalTuition = totalTuitionObject.total;
  const totalTransport = totalTransportObject.total;
  const totalSales = totalSalesObject.total;
  const totalServicesPaid = totalServicesPaidObject.total;
  const totalPayable = totalPayableObject.total;
  const totalReceivable = totalReceivableObject.total;

  // Cálculo do total de serviços (somando propinas, transporte, vendas e serviços pagos)
  const totalServices = totalTuition + totalTransport + totalSales + totalServicesPaid;

  // Cálculo do total ajustado a receber (total de serviços + contas a receber - contas a pagar)
  const adjustedReceivable = totalServices + totalReceivable - totalPayable;

  // Formatação de moeda
  const formatCurrency = (value) => value.toLocaleString();

  // Conteúdo do Tooltip com os totais formatados
  const tooltipContent = (
    <div>
      <p><strong>Total Pagamento de Propinas:</strong> {formatCurrency(totalTuition)} {CurrentCoin}</p>
      <p><strong>Total Pagamento de Transporte:</strong> {formatCurrency(totalTransport)} {CurrentCoin}</p>
      <p><strong>Total Pagamento de Vendas:</strong> {formatCurrency(totalSales)} {CurrentCoin}</p>
      <p><strong>Total Pagamento de Serviços:</strong> {formatCurrency(totalServicesPaid)} {CurrentCoin}</p>
      <p><strong>Total Contas a Pagar:</strong> {formatCurrency(totalPayable)} {CurrentCoin}</p>
      <p><strong>Total Contas a Receber:</strong> {formatCurrency(totalReceivable)} {CurrentCoin}</p>
      <hr />
      <p><strong>Total de Serviços:</strong> {formatCurrency(totalServices)} {CurrentCoin}</p>
      <p><strong>Total a Receber Ajustado:</strong> {formatCurrency(adjustedReceivable)} {CurrentCoin}</p>
    </div>
  );

  return (
    <OverlayTrigger
      placement="bottom"
      overlay={<Tooltip id="tooltip-summary">{tooltipContent}</Tooltip>}
    >
      <div className="total-balance-badge badge bg-success">
        {/* Exibe o total ajustado no badge */}
        <h4>{CurrentCoin} {formatCurrency(adjustedReceivable)}</h4>
      </div>
    </OverlayTrigger>
  );
}

function PaymentsBarChart({ data, coin, YEAR }) {
  const [chartData, setChartData] = useState(null);
  const year = YEAR * 1;

  useEffect(() => {
    const labels = [
      "Jan", "Fev", "Mar", "Abr", "Mai", "Jun",
      "Jul", "Ago", "Set", "Out", "Nov", "Dez"
    ];

    const colors = [
      "#8a72ff", "#5c85ff", "#6298ff", "#7eb4ff", "#66cccc", "#85e085",
      "#99cc66", "#ffcc66", "#ff9966", "#ff6666", "#ff6699", "#b366ff"
    ];

    let paymentsByMonth = Array(12).fill(0);

    if (data && data.length > 0) {
      data.forEach((entry) => {
        if (!entry.paymentdate || !entry.totalNotFormated) return;

        const [day, month, yearStr] = entry.paymentdate.split(" ")[0].split("-");
        const entryDate = new Date(`${yearStr}-${month}-${day}`);

        if (entryDate.getFullYear() * 1 === year) {
          const monthIndex = entryDate.getMonth();
          paymentsByMonth[monthIndex] += entry.totalNotFormated;
        }
      });
    }

    const chartConfig = {
      series: [{ name: `Receita Mensal (${year})`, data: paymentsByMonth }],
      options: {
        chart: { type: "bar", height: 350 },
        colors: colors,
        plotOptions: {
          bar: {
            columnWidth: "55%",
            endingShape: "rounded",
            distributed: true
          }
        },
        dataLabels: { enabled: false },
        xaxis: { categories: labels },
        yaxis: {
          title: { text: `Receita (${coin})` },
          labels: { formatter: (value) => `${coin} ${value.toLocaleString()}` },
        },
        tooltip: { y: { formatter: (value) => `${coin} ${value.toLocaleString()}` } },
      },
    };

    setChartData(chartConfig);
  }, [data, coin, year]);

  return (
    <div>
      {chartData ? (
        <Chart options={chartData.options} series={chartData.series} type="bar" height={350} />
      ) : (
        <p>Carregando gráfico...</p>
      )}
    </div>
  );
}


const PayableReceivablePieChart = ({ data = [], coin = "Kz" }) => {
  // Função para formatar preço corretamente
  const formatPrice = (price) =>
    Number(price).toLocaleString("pt-BR", { minimumFractionDigits: 2 }) + " " + coin;

  // Somando corretamente os valores convertendo strings para número
  const totalPayable = data.reduce(
    (sum, item) => sum + Number(item.payable_price_totalNotFormated || 0),
    0
  );

  const totalReceivable = data.reduce(
    (sum, item) => sum + Number(item.receivable_price_totalNotFormated || 0),
    0
  );

  const chartOptions = {
    chart: { type: "pie" },
    labels: ["Contas a Pagar", "Contas a Receber"],
    colors: ["#6051ff", "#06D6A0"],
    legend: { position: "bottom" },
    tooltip: {
      y: { formatter: (value) => formatPrice(value) },
    },
  };

  const chartSeries = [totalPayable, totalReceivable];

  return (
    <div>
      <br />
      <Chart options={chartOptions} series={chartSeries} type="pie" width="400" />
      <div className="text-center">
        <p className="mt-2"><strong>Total a Pagar:</strong> {formatPrice(totalPayable)}</p>
        <p className="mt-2"><strong>Total a Receber:</strong> {formatPrice(totalReceivable)}</p>
      </div>
    </div>
  );
};


