function DashboardFinance() {
  document.title = "Dashboard finanças";
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [ToggleCounts, SetToggleCounts] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);
  const [TotalBalance, setTotalBalance] = useState("");
  const [CurrentCoin, SetCurrentCoin] = useState("");
  const [CurrentYear, SetCurrentYear] = useState(moment().year());

  const [FeePaymentData, SetFeePaymentData] = useState({});
  const [TransportPaymentData, SetTransportPaymentData] = useState({});
  const [ServicePaymentData, SetServicePaymentData] = useState({});
  const [SalesPaymentData, SetSalesPaymentData] = useState({});
  const [PayableAndReceivableDataInfo, SetPayableAndReceivableDataInfo] = useState({ data: [], payableData: {}, receivableData: {} });
  const [TotalData, SetTotalData] = useState({});



    async function loadData(YEAR) {
      setLoadStatus(0);
      setLoaded(false);

      try {
        const rows_payments = [];
        const rows_transportpayments = [];
        const rows_servicepayments = [];
        const rows_salespayments = [];
        const rows_PayableAndReceivableData = [];

        const [
          FeePaymentData,
          TransportPaymentData,
          ServicePaymentData,
          SallesPaymentData,
          PayableAndReceivableData
        ] = await Promise.all([
          axios.get(Hoot() + "eduallfeepaymentsapi/get/"), // agora com extras
          axios.get(Hoot() + "edualltransportpaymentsapi/get/"),
          axios.get(Hoot() + "eduallservicepaymentsapi/get"),
          axios.get(Hoot() + "eduallgetallproductsales/get/"),
          axios.get(Hoot() + "eduallgetaccounts_payable_and_receivable/get/"),
        ]);

        // =======================================================
        //  PAGAMENTOS DE PROPINAS COM EXTRAS INCLUÍDOS
        // =======================================================
        const grouped = {};

        FeePaymentData.data.forEach((item) => {
          const total = item.ed_fee_payment_price * 1 - ((item.ed_fee_payment_price * item.ed_fee_payment_discount) / 100);
          const base = item.ed_fee_payment_iva * 1 > 0 ? total / (1 + (item.ed_fee_payment_iva / 100)) : total;
          const fineValue =
            item.ed_fee_payment_fineType * 1 === 1
              ? item.ed_fee_payment_fineValue * 1
              : ((base * item.ed_fee_payment_fineValue * 1) / 100);
          const totalResult = total + fineValue;

          // calcular extras associados
          const extrasArray = item.extras ? JSON.parse(item.extras) : [];
          const extrasTotal = Array.isArray(extrasArray)
            ? extrasArray.reduce((sum, ex) => sum + (Number(ex.amount) || 0), 0)
            : 0;

          const key = item.ed_fee_payment_invoiceCode;
          if (!grouped[key]) {
            grouped[key] = {
              student: item.ed_fee_payment_student,
              name: item.ed_student_name,
              picture: item.ed_student_picture,
              invoiceCode: key,
              service: item.ed_service_title,
              coin: item.ed_coin_code,
              payments: [item],
              total: totalResult,
              extrasTotal,
              extrasAdded: false
            };
          } else {
            grouped[key].payments.push(item);
            grouped[key].total += totalResult;
          }

          // adicionar extras uma vez
          if (!grouped[key].extrasAdded && extrasTotal > 0) {
            grouped[key].total += extrasTotal;
            grouped[key].extrasAdded = true;
          }
        });

        // gerar linhas finais
        Object.values(grouped).forEach((g) => {
          SetCurrentCoin(g.coin);
          rows_payments.push({
            invoiceCode: g.invoiceCode,
            service: g.service,
            student: g.student,
            name: g.name,
            picture: g.picture,
            totalNotFormated: g.total,
            total: NumberToPrice(g.total) + " " + g.coin,
            paymentdate: moment(g.payments[0].ed_fee_payment_registerDate).format("DD-MM-YYYY HH:mm"),
            paymenttype: g.payments[0].ed_fee_payment_type,
            paymentid: 0
          });
        });

        // =======================================================
        //  TRANSPORTE
        // =======================================================
        TransportPaymentData.data.forEach((item) => {
          const total = item.ed_transport_payment_price * 1 - ((item.ed_transport_payment_price * item.ed_transport_payment_discount) / 100);
          const base = item.ed_transport_payment_iva * 1 > 0 ? total / (1 + (item.ed_transport_payment_iva / 100)) : total;
          const fineValue =
            item.ed_transport_payment_fineType * 1 === 1
              ? item.ed_transport_payment_fineValue * 1
              : ((base * item.ed_transport_payment_fineValue * 1) / 100);
          const totalResult = total + fineValue;

          SetCurrentCoin(item.ed_coin_code);
          rows_transportpayments.push({
            invoiceCode: item.ed_transport_payment_invoiceCode,
            service: item.ed_service_title,
            name: item.ed_student_name,
            picture: item.ed_student_picture,
            totalNotFormated: totalResult,
            total: NumberToPrice(totalResult) + " " + item.ed_coin_code,
            paymentdate: moment(item.ed_transport_payment_registerDate).format("DD-MM-YYYY HH:mm"),
            paymenttype: item.ed_transport_payment_type,
            paymentid: 1
          });
        });

        // =======================================================
        //  SERVIÇOS
        // =======================================================
        ServicePaymentData.data.forEach((item) => {
          const total = (item.ed_service_payment_amount * item.ed_service_payment_price) -
            ((item.ed_service_payment_price * item.ed_service_payment_amount * item.ed_service_payment_discount) / 100);
          SetCurrentCoin(item.ed_coin_code);
          rows_servicepayments.push({
            invoiceCode: item.ed_service_payment_invoiceCode,
            service: item.ed_service_title,
            name: item.ed_student_name,
            picture: item.ed_student_picture,
            totalNotFormated: total,
            total: NumberToPrice(total) + " " + item.ed_coin_code,
            paymentdate: moment(item.ed_service_payment_registerDate).format("DD-MM-YYYY HH:mm"),
            paymenttype: item.ed_service_payment_type,
            paymentid: 2
          });
        });

        // =======================================================
        //  VENDAS
        // =======================================================
        SallesPaymentData.data.forEach((item) => {
          let totalPaid = 0;
          const discountPercentage = item.ed_product_sale_discount;
          const coinSymbol = item.coin_symbol || '';

          item.products.forEach((product) => {
            const productTotal = product.ed_sale_product_price * product.ed_sale_product_quantity;
            totalPaid += productTotal - (productTotal * discountPercentage / 100);
          });

          SetCurrentCoin(coinSymbol);
          rows_salespayments.push({
            invoiceCode: item.ed_product_sale_invoiceCode,
            service: item.products[0].ed_product_name,
            name: item.ed_product_sale_nif || 'N/A',
            totalNotFormated: totalPaid,
            total: `${NumberToPrice(totalPaid)} ${coinSymbol}`,
            paymentdate: moment(item.ed_product_sale_date).format("DD-MM-YYYY HH:mm"),
            paymenttype: item.ed_product_sale_payment_method,
            paymentid: 3
          });
        });

        // =======================================================
        //  CONTAS A PAGAR / RECEBER
        // =======================================================
        const payableData = [];
        const receivableData = [];

        PayableAndReceivableData.data.forEach((item, index) => {
          rows_PayableAndReceivableData.push({
            index: index + 1,
            id: item.ed_account_payable_receivable_id,
            description: item.ed_accounts_payable_and_receivable_description,
            suplierorclient: item.ed_accounts_payable_and_receivable_client_or_supplier,
            payable_price_totalNotFormated: item.ed_accounts_payable_and_receivable_amount_payable,
            receivable_price_totalNotFormated: item.ed_accounts_payable_and_receivable_amount_receivable,
            payable_price: NumberToPrice(item.ed_accounts_payable_and_receivable_amount_payable) + " " + item.ed_coin_code,
            receivable_price: NumberToPrice(item.ed_accounts_payable_and_receivable_amount_receivable) + " " + item.ed_coin_code,
            paymentdate: moment(item.ed_accounts_payable_and_receivable_registration_date).format("DD-MM-YYYY HH:mm"),
          });

          payableData.push({
            totalNotFormated: item.ed_accounts_payable_and_receivable_amount_payable,
            total: NumberToPrice(item.ed_accounts_payable_and_receivable_amount_payable),
            paymentdate: moment(item.ed_accounts_payable_and_receivable_registration_date).format("DD-MM-YYYY HH:mm"),
          });

          receivableData.push({
            totalNotFormated: item.ed_accounts_payable_and_receivable_amount_receivable,
            total: NumberToPrice(item.ed_accounts_payable_and_receivable_amount_receivable),
            paymentdate: moment(item.ed_accounts_payable_and_receivable_registration_date).format("DD-MM-YYYY HH:mm"),
          });
        });

        // =======================================================
        //  FUNÇÕES AUXILIARES
        // =======================================================
        function filterDataByYear(data, year) {
          return data.filter(item => {
            const itemYear = new Date(item.paymentdate.split(" ")[0].split("-").reverse().join("-")).getFullYear();
            return itemYear === year;
          });
        }

        // =======================================================
        //  CÁLCULOS DE TOTAIS E PERCENTAGENS
        // =======================================================
        setTotalBalance(calculateTotalPayments(
          filterDataByYear(rows_transportpayments, YEAR),
          filterDataByYear(rows_payments, YEAR),
          filterDataByYear(rows_servicepayments, YEAR),
          filterDataByYear(rows_salespayments, YEAR)
        ));

        SetFeePaymentData({
          data: filterDataByYear(rows_payments, YEAR),
          percentageData: calculateCategoryPercentage(filterDataByYear(rows_payments, YEAR), rows_payments, rows_servicepayments, rows_salespayments, 1),
          revenueAna: calculateRevenueDifference(rows_payments, YEAR, 1, CurrentCoin)
        });

        SetTransportPaymentData({
          data: filterDataByYear(rows_transportpayments, YEAR),
          percentageData: calculateCategoryPercentage(filterDataByYear(rows_transportpayments, YEAR), rows_payments, rows_servicepayments, rows_salespayments, 2),
          revenueAna: calculateRevenueDifference(rows_transportpayments, YEAR, 1, CurrentCoin)
        });

        SetServicePaymentData({
          data: filterDataByYear(rows_servicepayments, YEAR),
          percentageData: calculateCategoryPercentage(filterDataByYear(rows_servicepayments, YEAR), rows_payments, rows_servicepayments, rows_salespayments, 3),
          revenueAna: calculateRevenueDifference(rows_servicepayments, YEAR, 1, CurrentCoin)
        });

        SetSalesPaymentData({
          data: filterDataByYear(rows_salespayments, YEAR),
          percentageData: calculateCategoryPercentage(filterDataByYear(rows_salespayments, YEAR), rows_payments, rows_servicepayments, rows_salespayments, 4),
          revenueAna: calculateRevenueDifference(rows_salespayments, YEAR, 1, CurrentCoin)
        });

        const TOTAL_BILLS = calculateCategoryTotals(
          filterDataByYear(rows_payments, YEAR),
          filterDataByYear(rows_servicepayments, YEAR),
          filterDataByYear(rows_salespayments, YEAR),
          filterDataByYear(rows_transportpayments, YEAR),
          filterDataByYear(rows_PayableAndReceivableData, YEAR)
        );

        const PAYABLEDATA_FILTERED = filterDataByYear(payableData, YEAR);
        const RECEIVEBLEDATA_FILTERED = filterDataByYear(receivableData, YEAR);

        SetTotalData(TOTAL_BILLS);
        SetPayableAndReceivableDataInfo({
          data: filterDataByYear(rows_PayableAndReceivableData, YEAR),
          payableData: {
            totalFormated: NumberToPrice(
              PAYABLEDATA_FILTERED.reduce((sum, item) => sum + Number(item.totalNotFormated || 0), 0)
            ),
            revenueData: calculateRevenueDifference(PAYABLEDATA_FILTERED, YEAR, 1, CurrentCoin)
          },
          receivableData: {
            totalFormated: NumberToPrice(
              RECEIVEBLEDATA_FILTERED.reduce((sum, item) => sum + Number(item.totalNotFormated || 0), 0)
            ),
            revenueData: calculateRevenueDifference(RECEIVEBLEDATA_FILTERED, YEAR, 1, CurrentCoin)
          },
        });

        setLoaded(true);
      } catch (error) {
        console.error("Erro ao carregar dados do dashboard:", error);
        setLoaded(true);
        setLoadStatus(1);
      }
    }

  useEffect(() => {
    setLoaded(false);
    setTimeout(() => {
      loadData(CurrentYear * 1);
    }, 50);
  }, [CurrentYear]);

  useEffect(() => {
    loadData(CurrentYear);
  }, [CurrentYear]);






  return (
    <Area>
      {load === true ?
        <>
          <SmallBox>
            <div className="ed-space col">
              <div><div className="badge bg-warning"><strong>Balanço total bruto</strong></div></div>
              <div className='ed-flex'>
                <PaymentTooltip data={TotalData} CurrentCoin={CurrentCoin} />
                <div className="ml-2">
                  <div className="total-balance-badge badge cursor-pointer bg-success" onClick={() => SetToggleCounts(ToggleCounts === true ? false : true)} >
                    <h4>{ToggleCounts === false ? <IoEyeOffOutline /> : <IoEyeOutline />}</h4>
                  </div>
                </div>
              </div>
              <div className='ed-flex'>
                <DownloadSaft />
                <select onChange={(e) => SetCurrentYear(e.target.value)} value={CurrentYear} className="form-control col-lg-4 select-year">
                  {Array.from({ length: new Date().getFullYear() - 2000 + 1 }, (_, i) => 2000 + i).map((year) => (
                    <option key={year} value={year}>{year}</option>
                  ))}
                </select>

              </div>
            </div>
            <div className={ToggleCounts === true ? "ed-block" : "d-none"}>
              <br /><PaymentBreakdown data={TotalData} CurrentCoin={CurrentCoin} />
            </div>
          </SmallBox>
          {FeePaymentData.percentageData !== null && FeePaymentData.percentageData !== undefined ?
            <>

              <div className="col ed-flex mt-2">
                <aside className="box-balance">
                  <Box>
                    <strong className="grey-text">Balanço total</strong>
                    <h1 className="text-green total-balance">{CurrentCoin} {NumberToPrice(TotalBalance)}</h1>
                    <small className="grey-text">{NumberToLetters(TotalBalance)} {CurrentCoin}  </small>
                    <hr />
                    <div className="col mb-4">
                      <strong>Pagamento de propinas ({FeePaymentData.percentageData.percentage}%)</strong>
                      <ProgressBar variant="info" now={FeePaymentData.percentageData.percentage} />
                    </div>
                    <div className="col mb-4">
                      <strong>Pagamento de transporte ({TransportPaymentData.percentageData.percentage}%)</strong>
                      <ProgressBar variant="danger" now={TransportPaymentData.percentageData.percentage} />
                    </div>
                    <div className="col mb-4">
                      <strong>Pagamento de serviços ({ServicePaymentData.percentageData.percentage}%)</strong>
                      <ProgressBar variant="warning" now={ServicePaymentData.percentageData.percentage} />
                    </div>
                    <div className="col mb-4">
                      <strong>Venda de produtos ({SalesPaymentData.percentageData.percentage}%)</strong>
                      <ProgressBar variant="success" now={SalesPaymentData.percentageData.percentage} />
                    </div>
                  </Box>
                </aside>
                <div className="pd1 pd-1"></div>
                <div className="pd1 pd-1"></div>
                <aside className="box-payments-balance">
                  <Box>
                    <div className="box-analy">
                      <article className="box">
                        <div className="ed-space">
                          <div> <strong className="grey-text">Total Pag. de propinas</strong></div>
                          <div><div className="dot bg-info"></div></div>
                        </div>
                        <h4 className="total">{CurrentCoin} {NumberToPrice(FeePaymentData.revenueAna.revenueDifference.revenue)}</h4>
                        {FeePaymentData.revenueAna.revenueDifference.message}
                      </article>
                      <article className="box">
                        <div className="ed-space">
                          <div> <strong className="grey-text">Total Pag. de transporte</strong></div>
                          <div><div className="dot bg-red"></div></div>
                        </div>
                        <h4 className="total">{CurrentCoin} {NumberToPrice(TransportPaymentData.revenueAna.revenueDifference.revenue)}</h4>
                        {TransportPaymentData.revenueAna.revenueDifference.message}
                      </article>
                      <article className="box">
                        <div className="ed-space">
                          <div> <strong className="grey-text">Total Pag. de serviços</strong></div>
                          <div><div className="dot bg-warning"></div></div>
                        </div>
                        <h4 className="total">{CurrentCoin} {NumberToPrice(ServicePaymentData.revenueAna.revenueDifference.revenue)}</h4>
                        {ServicePaymentData.revenueAna.revenueDifference.message}
                      </article>
                      <article className="box">
                        <div className="ed-space">
                          <div> <strong className="grey-text">Total vendas de produtos</strong></div>
                          <div><div className="dot bg-success"></div></div>
                        </div>
                        <h4 className="total">{CurrentCoin} {NumberToPrice(SalesPaymentData.revenueAna.revenueDifference.revenue)}</h4>
                        {SalesPaymentData.revenueAna.revenueDifference.message}
                      </article>

                    </div>
                  </Box>
                </aside>
              </div>
              <section>
                <aside className='charts-container col'>
                  <Box>
                    <Tabs defaultActiveKey="t-1" id="uncontrolled-tab-example" className="mb-3"    >
                      <Tab eventKey="t-1" title="Pagamentos de propinas">
                        <PaymentsBarChart YEAR={CurrentYear} coin={CurrentCoin} data={FeePaymentData.data} />
                      </Tab>
                      <Tab eventKey="t-2" title="Pagamentos de transporte escolar">
                        <PaymentsBarChart YEAR={CurrentYear} coin={CurrentCoin} data={TransportPaymentData.data} />
                      </Tab>
                      <Tab eventKey="t-3" title="Pagamentos de serviços" >
                        <PaymentsBarChart YEAR={CurrentYear} coin={CurrentCoin} data={ServicePaymentData.data} />
                      </Tab>
                      <Tab eventKey="t-4" title="Vendas de produtos" >
                        <PaymentsBarChart YEAR={CurrentYear} coin={CurrentCoin} data={SalesPaymentData.data} />
                      </Tab>
                    </Tabs>
                  </Box>
                </aside>
                <div className="col">
                  <Box>
                    {(PayableAndReceivableDataInfo.receivableData && PayableAndReceivableDataInfo.receivableData.revenueData) ?
                      <>
                        <h1 className="title">Contas a pagar e receber</h1>
                        <div className="ed-flex col">
                          <div className="chart-box">
                            <PayableReceivablePieChart coin={CurrentCoin} data={PayableAndReceivableDataInfo.data} />
                          </div>
                          <div className="ml-2 col">
                            <article className="box-accounts mb-4">
                              <div className="ed-space">
                                <div> <strong className="grey-text">Total de contas a pagar</strong></div>
                              </div>
                              <h4 className="total bg-main">{CurrentCoin} {PayableAndReceivableDataInfo.payableData.totalFormated}</h4>
                              {PayableAndReceivableDataInfo.payableData.revenueData.revenueDifference.message}
                            </article>
                            <article className="box-accounts">
                              <div className="ed-space">
                                <div> <strong className="grey-text">Total de contas a receber</strong></div>
                              </div>
                              <h4 className="total bg-green">{CurrentCoin} {PayableAndReceivableDataInfo.receivableData.totalFormated}</h4>
                              {PayableAndReceivableDataInfo.receivableData.revenueData.revenueDifference.message}
                            </article>
                          </div>
                        </div>
                      </>
                      :
                      <></>}
                  </Box>
                  <div>
                    <Box>
                      <div className="title-large py-2 bg-main text-center mb-2">
                        <h5 className="text-white m0">Pendências de Propinas por Turma</h5>
                      </div>
                      <ClassPaymentsTable />
                    </Box>
                  </div>
                  <div>
                    <Box>
                      <div className="title-large py-2 bg-main text-center mb-2">
                        <h5 className="text-white m0">Pendências de pagamentos de transporte escolar por Turma</h5>
                      </div>
                      <ClassTransportPaymentsTable />
                    </Box>
                  </div>


                </div>
              </section>
            </>
            : <></>}
        </>
        :
        <div className="ed-center ed-flex col-lg-12">
          <Loader />
        </div>
      }
    </Area>
  )
}



