import React, { useEffect, useState } from 'react'
import { ChatbubbleEllipsesOutline } from 'react-ionicons'
import MenuDropDown from '../components/MenuDropDown'
import socketIO from 'socket.io-client'; 
import ChatForm from './Components/ChatForm';
import ChatMessages from './ChatMessages';
import ChatMessageBubbles from './Components/ChatMessageBubbles';
import { Avatar } from '@mui/material';
import { ChevronBackOutline } from 'react-ionicons'
import { EllipsisVertical } from 'react-ionicons'
import Hoot from '../components/Hoot';
import axios from 'axios';
import ReduceTextLength from '../components/ReduceTextLength';
import { Skeleton } from '@mui/material';

function ChatWidget({socket}) {
  const URL = Hoot()+"eduallgetcurrentuserconnections/get";
  const [data, setData] = useState([]); 
  const [load, setLoaded] = useState(false);   
  const [CurrentUser, setCurrentUser] = useState({contact_id:66});
  const [ActiveTab, setActiveTab] =  useState(1);
  const [ActiveMenu, setActiveMenu] =  useState(1);

   
  async function loadData(){
    try {
      setLoaded(false);
        const response = await axios.get(URL); 
        const rows = [];
        response.data.map((item, index)=>{  
            rows.push({
                index:index+1, 
                contact_id:item.ed_user_account_id,
                contact_name:item.ed_user_account_name,
                contact_picture:Hoot()+item.ed_user_account_picture,
          })  
        });  
        setData(rows);
        setTimeout(() => {
           setLoaded(true);
        }, 200);
    } catch (error) {
      setLoaded(true);
    }
  };
  
  useEffect(()=>{ 
    loadData(); 
  },[]); 

  
  const ChangeCurrentUser=(e)=>{ 
    setCurrentUser(e); 
    setActiveMenu(2);
}


 

  return (
    <div className='ed-chat-widget'>
      <div className="ed-chat-widget-container">

        <aside>
          <MenuDropDown 
           toggle_btn={
            <div className="toggle-chat-widget bg-main text-light ed-flex ed-center">
                 <ChatbubbleEllipsesOutline   /> <div className="count">12</div>
            </div>} 
            ChatBox="true"
            content={
              <div className="chat-box-area">
              <section className={ActiveMenu === 2 ? "chat-box-menu" : "chat-box-menu d-none"} >
                 <div className="chat-box-header"> 
                 <div className="ed-flex">
                  <div className="mr-2">
                      <button onClick={()=>setActiveMenu(1)}><ChevronBackOutline/></button>
                  </div>
                  <Avatar sx={{width:35,height:35}} src={CurrentUser.contact_picture} alt={CurrentUser.contact_name} />
                  <div className="ed-block">
                      <h1>{CurrentUser.contact_name}</h1>
                      <div className="status">
                          <div className="dot"></div>
                          <span>Online</span>
                      </div>
                  </div> 
                 </div> 
                  </div>
                  <div className="chat-box-body">
                      <section className='chat-messages-area'>
                          <ChatMessageBubbles socket={socket} chatuser={CurrentUser} />  
                      </section>
                      <section></section> 
                  </div>
                  <div className="chat-box-form">
                     <ChatForm socket={socket} CurrentChatUser={CurrentUser} />
                  </div>
              </section>
              <section className={ActiveMenu === 1 ? "chat-box-contact" : "chat-box-contact d-none"}>
                   <div className="title">
                    <h2>Mensagens</h2>
                   </div>
                   <ul className='tbs'>
                      <li onClick={()=>setActiveTab(1)} className={ActiveTab === 1 ? "active" : ""}>Mensagens <div className="count">(45)</div> </li>
                      <li onClick={()=>setActiveTab(2)} className={ActiveTab === 2 ? "active" : ""}>Ocultadas <div className="count">(12)</div></li>
                   </ul> 
                   <aside className={ActiveTab === 1 ? "chat-users-area" : "d-none"}>
                   <ul className="user-list">
                      {load === true ? 
                            <>
                                {data.map((item, index)=>(
                                    <li className='active'  onClick={()=>ChangeCurrentUser(item)} key={index}>
                                    <div className="user-info"> 
                                    <div className="avatar-box">
                                        <div className="status"></div>
                                        <Avatar alt={item.contact_name} src={item.contact_picture} sx={{width:45,height:45}} />
                                    </div> 
                                    <div className="block-info">
                                            <div className="bx">
                                            <div> <h2><ReduceTextLength text={item.contact_name} length={20}/></h2></div>
                                            <div className="time"><small>5:17 PM</small></div> 
                                            </div>
                                        <div className="ed-space">
                                            <div><span className="msg">Nova tarefa atribuida</span></div>
                                            <div className="pr"><div className="icon">1</div> </div>
                                        </div>
                                    </div>
                                    </div> 
                                </li> 
                                ))}
                            </> :
                        <>
                            {[1,2,3,4,5].map((item, index)=>(
                                <div className="mt-2" key={index}>
                                    <Skeleton variant='rectangle' sx={{borderRadius:"6px"}} animation='wave' width='100%' height={63} />
                                </div>
                            ))}
                        </>}     
                    </ul> 
                   </aside> 
                   <aside className={ActiveTab === 2 ? "chat-users-area" : "d-none"}>
                        <h1>*********************</h1>
                   </aside>
              </section>
             </div>
            }
          />
        </aside>
           
        
      </div>
    </div>
  )
}

export default ChatWidget