import { AnchorTwoTone } from '@mui/icons-material';
import React, { useEffect } from 'react'
import styled from 'styled-components'
import ReduceTextLength from '../../General/components/ReduceTextLength';
import {AiOutlineLink } from "react-icons/ai";
import { Avatar } from '@mui/material';
import ImageLazyLoading from '../../General/components/ImageLazyLoading';
import { GlobeOutline } from 'react-ionicons'

function AdBox(props) { 
  
  useEffect(()=>{
    console.log("Ad number - "+props.data.code+ " added successfuly");
  },[]);

  return (
    <div>
     {props.cramb === true ? 
     <Cramb>
         <a href={props.data.link ? props.data.link : ''} target='_blank'>
           <div className="image-area">
              <ImageLazyLoading source={props.data.img ? props.data.img : ''} height={90} />
           </div>
           </a>
           <div className="dets">
               <div className="spon">
                  <strong>Patrocinado</strong>
               </div>
               <div>
                 <a href={props.data.link ? props.data.link : ''} target='_blank'>
                      <div className="ed-flex">
                         <GlobeOutline />
                         <small> <ReduceTextLength text={props.data.linkname ? props.data.linkname : ''} length="50" /></small>
                      </div> 
                   </a>
                  <h2>{props.data.title ? props.data.title : ''}</h2></div> 
                   <a href="#" target='_blank' className="ed-flex owner text-dark">
                      <Avatar className='df' src={props.data.owner_picture}  sx={{width:20, height:20}}  />
                      <div className="ml-1"><span><ReduceTextLength text={props.data.owner_name} length="17" /></span></div>
                   </a>
           </div> 
     </Cramb>
     :
   <a href={props.data.link ? props.data.link : ''} target='_blank'>
         {props.smaller ?
         <>
           <SmallBox>
                <a href="#">
                  <ImageLazyLoading source={props.data.img ? props.data.img : ''} height={60} />
                  </a>
           </SmallBox>
         </>
         :
          <Box>
            <div className={`block ${props.size ? props.size : ''} 
               ${props.small === true ? ' small ' : ''} 
               ${props.margin === true ? ' margin-t0 ' : ''} 
               ${props.text ? props.text : ''}`}>
             <div className="main">
               <ImageLazyLoading  source={props.data.img ? props.data.img : ''} height={130} alt={props.data.linkname ? props.data.linkname : ''} />
             </div>
              <div className="dts">
                  <div><h2>{props.data.title ? props.data.title : ''}</h2></div>
                  <div><small> {props.data.linkname ? props.data.linkname : ''} </small></div> 
                   <a href="#" target='_blank' className="ed-flex mt-2 owner text-dark">
                      <Avatar className='df' src={props.data.owner_picture}  sx={{width:30, height:30}}  />
                      <div className="ml-1"><span><ReduceTextLength text={props.data.owner_name} length="17" /></span></div>
                   </a>
              </div>
            </div>
         </Box>}
      </a>} 
    </div>
  )
}

const Cramb =  styled.div` 
  width:100%;
  min-width:450px;
  max-width:450px;
  height:190px;
  border:1px solid var(--ed-blue-dark);
  border-radius:10px;
  background:var(--ed-white);
  margin-bottom:10px;
  overflow:hidden;
  text-align:left;
  position:relative;

     .image-area{
      width:100%;
      height:90px;
      padding:4px;
      border-radius:6px;
      overflow:hidden;

        img{
            width:100%;
            border-radius:6px;
            height:100%;
            object-fit:cover;
        }
     }

     .dets{
        padding:0px 10px;
        color:var(--ed-blue-dark);

        small{
           color:var(--ed-grey-text);
          font-size:12px;
          margin:0px;
        }

        a{
            svg{
                width:18px;
                height:18px;
                color:var(--ed-grey-text);
                margin:0px;
                margin-right:10px;
            }
        }

        
       .owner{
        display:flex;
        margin:5px 0px;
        padding:5px;
        padding-right:10px;
        border-radius:30px;
        align-items:center; 
        width:max-content;
        background:var(--ed-silver-light);

          span{
             font-size:13px;
          }
       }

        .spon{
            position:absolute;
            top:10px;
            left:10px;
            padding:5px 10px;
            border-radius:10px;
            background:var(--ed-trp-5);

              strong{
                  color:var(--ed-white);
              }
        }

          h2{
            font-size:15px;
            margin:2px 0px;
            font-weight:600;
          }

          strong{
             font-size:13px;
             font-weight:600;
          }
     }
`;


const SmallBox = styled.div`
  min-width:302px;
  max-width:302px;
  height:62px;
  background:var(--ed-background-color);
  margin:0px 20px;

    h1{
        font-weight:bolder;
        font-size:20px;
    }

    img{
       object-fit:cover;
       height:61px;
       min-width:301px;
       margin:0px !important;
    }
`;

const Box = styled.div`
  width:100%;  
 
  .block{
      max-width:300px;
      text-align:left;
      display:flex;
       margin:20px 0px; 

       .dts{
         padding-left:20px;
         text-align:left;
       }

       .owner{
           display:flex;
           margin:5px 0px;
           padding:2px;
           padding-right:10px;
           border-radius:30px;
           align-items:center; 
           width:max-content;
           background:var(--ed-silver-light);

             span{
                font-size:12px;
             }
       }


  }

  .block.small{
      img{max-height:120px !important;margin:0px;} 
      display:flex;
      align-items:flex-end;
  }

  .block.margin-t0{
    margin-top:0px !important;
    margin-bottom:20px; 
  }

  .block.right{
    text-align:right;
  }

  .block.lg{
      max-width:400px; 

    .main{
      img{
        height:200px;
      }
    }
  }
  
.main{    
  img{
      width:120px;
      min-width:120px;
      background:var(--ed-white);
      object-fit:fill;
      height:130px;
      border-radius:6px;
      margin-bottom:10px;
      border:1px solid  #eaeaee;
    }
  }


  h2{
    font-size:13px;
    margin-bottom:10px;
    color:var(--black);
    letter-spacing:1px;
    font-weight:600;
  }

  small{
     color:grey;
     font-size:12px; 
  }

  p{
      font-size:14px;
      color:var(--ed-blue-dark);
       margin-top:8px;
  }
`;

export default AdBox