
import { Check, Error, ErrorOutline, Send } from '@material-ui/icons';
import { Avatar } from '@mui/material';
import React, { useEffect } from 'react';
import { useState } from 'react';
import { Alert, Form } from 'react-bootstrap';
import styled from 'styled-components';
import RandomAvatarColor from '../../General/components/RandomAvatarColor';
import axios from 'axios';
import Hoot from '../../General/components/Hoot';
import moment from "moment";
import { toast } from 'react-hot-toast';
import RefreshList from '../../General/components/RefreshList';
import { SlRefresh } from "react-icons/sl";
import NumberTo_KMB from '../../General/components/NumberTo_KMB';

function SmsServices() {
    document.title = "Serviços de SMS";
    const [data, setData] = useState([]);
    const [load, setLoaded] = useState(false);
    const [LoadStatus, setLoadStatus] = useState(null);
    const [FilterData, setFilterData] = useState([]);
    const [CreditsData, setCreditsData] = useState(0);
    const [SmSData, setSmSData] = useState([]);
    const [selectedContacts, setSelectedContacts] = useState([]);
    const [TextMessage, setTextMessage] = useState("");
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [form, setForm] = useState({});

    const TABLEURL = [
        Hoot() + "eduallgetinstitutecontacts/get",
        Hoot() + "eduallgetsmscredits/get",
        Hoot() + "eduallgetallsentsms/get",
        Hoot() + "eduallsendsmsmessage/post/",
        Hoot() + "eduallresendsmsmessage/post/"
    ];

    const [visibleMessages, setVisibleMessages] = useState({});

    const toggleMessage = (index) => {
        setVisibleMessages((prevState) => ({
            ...prevState,
            [index]: !prevState[index]
        }));
    };

    const handleCheck = (contact) => {
        setSelectedContacts((prevSelected) => {
            const isAlreadySelected = prevSelected.some((c) => c.id === contact.id);
            return isAlreadySelected
                ? prevSelected.filter((c) => c.id !== contact.id)
                : [...prevSelected, contact];
        });
    };

    const toggleSelectAll = () => {
        if (selectedContacts.length === FilterData.length) {
            setSelectedContacts([]);
        } else {
            setSelectedContacts([...FilterData]);
        }
    };


    async function loadData(nofresh) {
        try {
            setLoadStatus(0);
            setLoaded(false)
            const [response, response2, response3] = await Promise.all([
                axios.get(TABLEURL[0]),
                axios.get(TABLEURL[1]),
                axios.get(TABLEURL[2])
            ]);

            const rows = [];
            const sentsms = [];
            response.data.map((item, index) => {
                rows.push({
                    id: item.ed_contact_id,
                    index: index + 1,
                    type: item.ed_contact_type,
                    name: item.ed_contact_name,
                    phone: item.ed_contact_phone,
                    email: item.ed_contact_email,
                    picture: Hoot() + item.ed_contact_picture,
                })
            });


            setCreditsData(response2.data[0].ed_sms_credit_total);

            response3.data.map((item, index) => {
                sentsms.push({
                    id: item.ed_sms_record_id,
                    index: index + 1,
                    message: item.ed_sms_record_message,
                    status: item.ed_sms_record_status,
                    type: item.ed_contact_type,
                    name: item.ed_contact_name,
                    phone: item.ed_contact_phone,
                    date: item.ed_sms_sent_date,
                    picture: Hoot() + item.ed_contact_picture,
                })
            });

            if (nofresh === true) {
                setFilterData(rows);
            }


            setSmSData(sentsms);
            setData(rows);
            setTimeout(() => {
                setLoaded(true);
            }, 200);
            setLoadStatus(2);
        } catch (error) {
            console.clear();
            console.log(error.response);
            setLoadStatus(1);
        }
    };

    useEffect(() => {
        loadData(true);
    }, []);

    const contactTypes = ["",
        <div className="badge bg-info col">Estudante</div>,
        <div className="badge bg-warning col">Encarregado</div>,
        <div className="badge bg-danger col">Funcionário</div>,
        <div className="badge bg-success col">Outro</div>,
    ];


    const filterContacts = (value) => {
        const filteredDataArray = data.filter(contact =>
            contact.name.toLowerCase().includes(value.toLowerCase()) ||
            contact.phone.includes(value) ||
            contact.email.toLowerCase().includes(value.toLowerCase())
        );
        setFilterData(filteredDataArray);
    };


    const validateForm = () => {
        const NewErrors = {};

        if (selectedContacts.length === 0) {
            NewErrors.contacts_list = "Selecione os contactos !";
        }
        if (TextMessage.split("").length < 5) {
            NewErrors.contacts_message = "Escreva uma mensagem valida !";
        }
        setRegisterStatus(0);
        return NewErrors;
    }



    const ResendSmS = (data) => {
        setTimeout(() => {
            try {
                axios.post(TABLEURL[4] + data.id, {
                    phone: data.phone,
                    message: data.message,
                    usertype: data.type,
                    contact: data.contact
                }).then(() => {
                    toast.success("Mensagem enviada com sucesso para " + data.name + "( " + data.phone + " )" + " !");
                    RefreshList(`.el-refresh-list`);
                    setRegisterStatus(2);
                    loadData(false);
                }).catch((error) => {
                    console.clear()
                    console.log(error.response.data);
                    if (error.response.data.msg !== undefined && error.response.data.msg !== null) {
                        toast.error(error.response.data.msg);
                    } else {
                        toast.error("Lamentamos mas não foi possivel enviar a mensagem para " + data.name + "( " + data.phone + " )" + " !");
                    }
                    setRegisterStatus(1);
                });
            } catch (error) {
                console.clear();
                console.log(error.response.data);
                if (error.response.data.msg !== undefined && error.response.data.msg !== null) {
                    toast.error(error.response.msg);
                } else {
                    toast.error("Lamentamos mas não foi  possivel enviar a mensagem para " + data.name + "( " + data.phone + " )" + " !");
                }
                setRegisterStatus(1);
            }
        }, 200);
    }

    const FormSubmit = async (e) => {
        e.preventDefault();
        const formErrors = validateForm();
        if (Object.keys(formErrors).length > 0) {
            toast.error("Selecione os contactos e escreva uma mensagem válida!");
            setRegisterStatus(1);
            return;
        }

        try {
            const requests = selectedContacts.map((contact, index) => {
                return new Promise((resolve) => {
                    setTimeout(() => {
                        axios.post(TABLEURL[3], {
                            phone: contact.phone,
                            message: TextMessage,
                            usertype: contact.type,
                            contact: contact.id
                        }).then(() => {
                            toast.success(`Mensagem enviada com sucesso para ${contact.name} (${contact.phone})!`);
                            resolve(true);
                        }).catch((error) => {
                            console.clear();
                            console.log(error.response?.data);
                            if (error.response.data.msg !== undefined && error.response.data.msg !== null) {
                                toast.error(error.response.data.msg);
                            } else {
                                toast.error("Lamentamos mas não foi possivel enviar a mensagem para " + data.name + "( " + data.phone + " )" + " !");
                            }
                            resolve(false);
                        });
                    }, index * 200);
                });
            });

            Promise.all(requests).then((results) => {
                if (results.some(success => success)) {
                    RefreshList(".el-refresh-list");
                    setRegisterStatus(2);
                    loadData(false);
                    setTextMessage("");
                } else {
                    setRegisterStatus(1);
                }
            });

        } catch (error) {
            if (error.response.data.msg !== undefined && error.response.data.msg !== null) {
                toast.error(error.response.data.msg);
            } else {
                toast.error("Lamentamos parece que ocorreu um erro ao enviar as mensagens ! ");
            }
        }
    };



    const [showAlert, setShowAlert] = useState(true);

    const handleClose = () => setShowAlert(false);
  



    return (
        <>
        {showAlert && (
                <Alert variant="info" dismissible onClose={handleClose}>
                <Alert.Heading style={{ fontSize: '14px' }}>
                Atenção: O desconto de créditos depende do tamanho da mensagem:
                </Alert.Heading>
                <small style={{ fontSize: '12px' }}>
                        Mensagens com até 130 caracteres custam 1 crédito, 
                        Mensagens com caracteres especiais (como emojis) têm um limite de 70 caracteres por parte ,
                        Mensagens maiores que o limite serão divididas em partes e cada parte será cobrada.
                </small>
            </Alert>
            )}
            <WarningBox className='bg-white'>
                <div className="ed-flex"><div className="dot bg-green-light"></div><span>Mensagens por enviar (creditos) : </span> <div className="ml-2">{CreditsData}</div></div>
                <div className="ed-flex mt-2"><div className="dot bg-red"></div><span>Mensagens enviadas : </span> <div className="ml-2">{SmSData.length}</div> </div>
            </WarningBox> 
            <Container >
                <BoxContacts>
                    <Form>
                        <div className="ed-space mb-2">
                            <div>
                                <h3 className='title'>Contactos ({data.length} )</h3>
                                <small className="grey-text text-grey">contactos selecionados  - {selectedContacts.length} </small>
                            </div>
                        </div>
                        <div className="filters">
                            <Form.Group className="mb-3" controlId="exampleForm.ControlInput1">
                                <Form.Control onChange={(e) => filterContacts(e.target.value)} type="text" placeholder="Pesquisar ..." />
                            </Form.Group>
                        </div>
                        <a href="#" className="text-main" onClick={toggleSelectAll} >
                            {selectedContacts.length === data.length ? "Remover seleção" : "Selecionar todos"}
                        </a>
                    </Form>
                    <div className="contacts-list">
                        <ul>
                            {FilterData.map((contact, index) => (
                                <div className="block" key={contact.id}>
                                    <label htmlFor={`check-${contact.id}`}>
                                        <li>
                                            <div className="d-flex">
                                                <Avatar sx={{ height: 50, width: 50 }} className="df" src={contact.picture} alt={contact.name} />
                                                <div className="block ml-2">
                                                    <div className="name">{contact.name}</div>
                                                    <div className="phone">{contact.phone}</div>
                                                    <div className={`mt-1 type-${contact.type}`}>{contactTypes[contact.type]}</div>
                                                </div>
                                            </div>
                                            <div className="ed-flex">
                                                <div className="ml-1">
                                                    <input
                                                        type="checkbox"
                                                        aria-label={`select-${contact.id}`}
                                                        id={`check-${contact.id}`}
                                                        className='form-check'
                                                        checked={selectedContacts.some((c) => c.id === contact.id)}
                                                        onChange={() => handleCheck(contact)}
                                                    />
                                                </div>
                                            </div>
                                        </li>
                                    </label>
                                </div>
                            ))}
                        </ul>
                    </div>
                </BoxContacts>
                <MessageBox>
                    <Form className='form'>
                        <Form.Group className="mb-3" controlId="exampleForm.ControlTextarea1">
                            <Form.Label> <h3>Compor Mensagem</h3> </Form.Label>
                            <Form.Control value={TextMessage} onChange={(e) => setTextMessage(e.target.value)}
                                onPaste={(e) => setTextMessage(e.target.value)} as="textarea" rows={4} />
                        </Form.Group>
                        <div className="ed-space">
                            <div className="tollbar">

                            </div>
                            <div>
                                <button onClick={FormSubmit} className="btn bg-main"> <Send /> Enviar </button>
                            </div>
                        </div>
                    </Form>
                    <h3 className='title badge bg-main bg-primary'> <strong>Mensagens enviadas ( {NumberTo_KMB(SmSData.length)} sms ) </strong></h3>
                    <div className="latest-messages">
                        {SmSData.map((item, index) => (
                            <CardMessage key={index} className={`${item.status === 1 ? "error" : "success"}-card`}>
                                <div className="d-block col">
                                    <div className='ed-flex  col ed-space'>
                                        <div className="block">
                                            <div className='ed-wrap'>{item.name} <div className="ml-2">({item.phone})</div></div>
                                        </div>
                                        <div className="ed-flex ml-2">
                                            {item.status === 1 ? (
                                                <div onClick={() => ResendSmS(item)} className="icon cursor-pointer">
                                                    <SlRefresh />
                                                </div>
                                            ) : (
                                                <div className="icon">
                                                    <Check />
                                                </div>
                                            )}
                                        </div>
                                    </div><br />
                                    <div className="d-block">
                                        <div className='ed-flex'>
                                            <strong className="underline" onClick={() => toggleMessage(index)}
                                                style={{ cursor: "pointer" }}>{visibleMessages[index] ? "Esconder mensagem" : "Visualizar mensagem"}
                                            </strong>
                                            <div className="date ml-2">
                                                {moment(item.date).locale("pt").format("dddd, D [de] MMMM [de] YYYY")}
                                            </div>
                                        </div>
                                        <div className={`message ${visibleMessages[index] ? "" : "d-none"}`}>
                                            <br /><hr />
                                            <small>{item.message}</small>
                                        </div>
                                    </div>
                                </div>
                            </CardMessage>
                        ))}
                    </div>
                </MessageBox>
            </Container>
            <br />
        </>
    )
}




const Container = styled.div`
    width:100%;
    display:flex;
    justify-content:space-between;
`;

const WarningBox = styled.div`
   margin-bottom:20px;
   width:100%;
   padding:10px 20px; 
   font-size:15px;
   color:var(--ed-dark);
   box-shadow:var(--ed-shadow-df);
   border-radius:6px;

   .dot{
      width:6px;
      height:6px; 
      margin-right:10px;
      border-radius:100%;
   }

    div{
        align-items:center;

        span{
            font-weight:500;
        }

        strong{
            letter-spacing:1px;
        }
    }
`;

const BoxContacts = styled.div` 
   width:350px;
   min-width:400px !important; 
   min-height:50vh; 
   border-radius:6px;  
   margin-bottom:20px !important;
   background:var(--ed-white);  
   box-shadow:var(--ed-shadow-df); 
   padding:20px;
   position: relative;

  label{
     width:100%;
  }

     a.text-main{
        text-decoration:underline !important;
        font-size:14px;
     }

    h3{
        font-size:17px;
        font-weight:600;
    } 


    .contacts-list{
        ul{
            padding:0px;
            list-style:none;
            max-height:700px;
            overflow-y:auto; 

            &:hover{  
               padding-right:15px;
            }

            &::-webkit-scrollbar{
                width:6px;
                background-color:transparent;
            }

            .form-check-input{
                  width:30px;
            }

            &:hover{ 
                &::-webkit-scrollbar-thumb{
                    background:#eaeaee;   
                }
            }

            li{
                display:flex;
                width:100%;
                justify-content:space-between;
                position:relative;
                margin:20px 0px;

                .name{
                    font-size:14px;
                }

                .phone{
                      font-size:12px;
                      margin-top:5px;
                      font-weight:550;
                }

                .type{
                   font-size:12px;
                   color:var(--ed-dark);
                   padding:2px 10px;
                   border-radius:30px;
                   text-align:center;  
                }

                .type.st{background:#bde0fe;}
                .type.emp{background:#fbf8cc;}
                .type.prt{background:#98f5e1;} 
            }
        }
    }

`;

const MessageBox = styled.div`
     width:70%;
     padding-left:20px;
     min-width:200px;
     display:block; 


     .latest-messages{ 
        overflow-y:auto;
        max-height:700px;

           &:hover{  
               padding-right:15px;
            }
        
            &::-webkit-scrollbar{
                width:6px;
                background-color:transparent;
            }

            &:hover{ 
                &::-webkit-scrollbar-thumb{
                    background:#eaeaee;   
                }
            }
     }


     button{
        padding:8px 10px;
        font-size:14px;

         svg{
             width:18px;
             height:18px;
         }
     }
        

        .success-card {
            background: #e0fff8;
        }

        .error-card {
            background: #fff1f2;
        }

        .success-card .icon {
            background: #98f5e1;
        }

        .error-card .icon {
            background: #ffcfd2;
        }
        
     .form{
        border-radius:6px;  
        margin-bottom:20px !important;
        background:var(--ed-white);  
        box-shadow:var(--ed-shadow-df); 
        width:100%;
        padding:10px;

          h3{
             font-size:17px;
             font-weight:600;
          }
     }
`;

const CardMessage = styled.div`
       width:100%;
       height:auto;
       min-height:50px;
       display:flex;
       align-items:center;
       justify-content:space-between;
       position:relative;
       margin:20px 0px;
       padding:20px;
       border-radius:6px;
       border:4px solid var(--ed-white);
       transition:all 1s ease-in-out; 

       &:hover{
           transform:scaleX(1.02);
       }
       

       span{
           font-size:15px;
           font-weight:500;
       }

       .date{
         font-size:13px;
         margin-right:20px;
         background:var(--ed-dark);
         padding:6px 10px;
         border-radius:40px;
         color:var(--ed-white);
       }
 

       .icon{ 
            border-radius:100%;
            width:40px;
            height:40px;
            display:flex;
            align-items:center;
            justify-content:center; 

               
       }


`;

export default SmsServices;