import React, { useState } from "react";
import { Table, ProgressBar, Dropdown } from "react-bootstrap";
import styled from "styled-components";
import { FaVideo, FaQuestionCircle, FaFileAudio, FaFileAlt } from "react-icons/fa";
import { MdOutlinePlayLesson } from "react-icons/md";
import {Link} from "react-router-dom"; 

const curricularData = [
  {
    id: 1,
    chapterTitle: "Capítulo 1 - Matemática",
    items: [
      {
        id: "1.1",
        type: "lesson",
        title: "Álgebra Básica",
        status: "finalizado",
        lessonType: "video"
      },
      {
        id: "1.2",
        type: "lesson",
        title: "Geometria",
        status: "pendente",
        lessonType: "documento"
      }
    ]
  },
  {
    id: 2,
    chapterTitle: "Capítulo 2 - Ciências",
    items: [
      {
        id: "2.1",
        type: "subchapter",
        title: "Biologia",
        status: "em andamento",
        lessons: [
          { id: "2.1.1", title: "Microscopia", status: "finalizado", lessonType: "video" },
          { id: "2.1.2", title: "Classificação dos seres vivos", status: "pendente", lessonType: "questionario" },
          { id: "2.1.3", title: "Fotossíntese", status: "finalizado", lessonType: "audio" }
        ]
      },
      {
        id: "2.2",
        type: "lesson",
        title: "Química - Introdução",
        status: "pendente",
        lessonType: "documento"
      }
    ]
  }
];
 
const lessonIcons = {
  video: <div className="d-flex lesson-type-badge"><FaVideo /> video</div>,
  questionario: <div className="d-flex lesson-type-badge"><FaQuestionCircle /> Questionario</div>,
  audio: <div className="d-flex lesson-type-badge"><FaFileAudio /> Aúdio</div>,
  documento: <div className="d-flex lesson-type-badge"><FaFileAlt /> Documento</div>
};
 
const statusColors = {
  finalizado: "#06D6A0",
  "em andamento": "#ffc107",
  pendente: "#EF233C"
};

function CurricularPlan() {
  const [openItems, setOpenItems] = useState({});

  const toggleOpen = (id) => {
    setOpenItems((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  const getProgress = (lessons) => {
    const total = lessons.length;
    const done = lessons.filter((l) => l.status === "finalizado").length;
    return Math.round((done / total) * 100);
  };

  return (
    <div className="curricular-plan-section">
      <aside className="menu-box-panel">
        <div className="ed-space">
            <div className="ed-flex">
                <select name="" id="" className="form-select">
                  <option value="Matematica">Matematica</option>
                  <option value="Biologia">Biologia</option>
                </select>
                <div className="ml-2">
                    <Link className="bg-main text-light ed-flex btn watch-toggle"><MdOutlinePlayLesson/> Visualizar</Link>
                </div>
            </div>
            <div className="d-flex cp-text">
               <h5><div className="dot"></div> 35 Aulas </h5>
               <h5><div className="dot"></div> 6 Capitulos</h5>
               <h5><div className="dot"></div> 57 Subcapitulos</h5>
            </div>
        </div>
      </aside>
      <br />
      {curricularData.map((chapter) => (
        <section className="chapter-block" key={chapter.id} style={{ marginBottom: "2rem" }}>
          <h5 className="text-dark" style={{ fontWeight: "bold", marginBottom: "10px" }}>{chapter.chapterTitle}</h5>
         <div className="box-table">
         <Table bordered hover>
            <thead>
              <tr>
                <th style={{ width: "40px" }}></th>
                <th>Título</th>
                <th>Status</th>
                <th>Timeline</th>
                <th>Tipo de conteudo</th>
              </tr>
            </thead>
            <tbody>
              {chapter.items.map((item) => {
                if (item.type === "lesson") {
                  return (
                    <tr key={item.id}>
                      <td><div className="circle-simple"></div></td>
                      <td className="grey-text">{item.title}</td>
                      <td style={{ background: statusColors[item.status] }}>
                         <StatusSelector status={item.status} />
                      </td>
                      <td><div className="mt-1"><ProgressBar style={{ height:'15px'}} now={10} /></div></td>
                      <td>{lessonIcons[item.lessonType]}</td>
                    </tr>
                  );
                } 
                if (item.type === "subchapter") {
                  const progress = getProgress(item.lessons);
                  return (
                    <React.Fragment key={item.id}>
                      <tr style={{ background: "#f8f9fa", fontWeight: "bold", cursor: "pointer" }}>
                        <td onClick={() => toggleOpen(item.id)}>
                          {openItems[item.id] ? "▲" : "▼"}
                        </td>
                        <td className="cursor-pointer" onClick={() => toggleOpen(item.id)}>{item.title}</td> 
                        <td style={{ background: statusColors[item.status] }}>
                               <StatusSelector status={item.status} />
                        </td>
                        <td>
                          <div className="mt-1"><ProgressBar style={{ height:'15px'}} now={progress} /></div>
                        </td>
                        <td></td>
                      </tr>
                      {openItems[item.id] &&
                        item.lessons.map((lesson) => (
                          <tr key={lesson.id}>
                            <td><div className="circle-subchapter"></div> </td>
                            <td  className="grey-text" style={{ paddingLeft: "2rem" }}>{lesson.title}</td>
                            <td style={{ background: statusColors[lesson.status] }}>
                                <StatusSelector status={lesson.status} />
                            </td>
                            <td><div className="mt-1"><ProgressBar now={10} /></div></td>
                            <td>{lessonIcons[lesson.lessonType]}</td>
                          </tr>
                        ))}
                    </React.Fragment>
                  ); 
                }
              })}
            </tbody>
          </Table>
         </div>
        </section>
      ))}
    </div>
  );
}

function StatusSelector({ status, onChange }) {
    return (
      <Dropdown className="col">
        <TransparentDropdownToggle size="lg">
          {status}
        </TransparentDropdownToggle>
        <Dropdown.Menu className="col">
          <Dropdown.Item onClick={() => onChange("finalizado")}>finalizado</Dropdown.Item>
          <Dropdown.Item onClick={() => onChange("em andamento")}>em andamento</Dropdown.Item>
          <Dropdown.Item onClick={() => onChange("pendente")}>pendente</Dropdown.Item>
        </Dropdown.Menu>
      </Dropdown>
    );
  }
  


const TransparentDropdownToggle = styled(Dropdown.Toggle)`
  background-color: transparent !important;
  border: none !important;
  box-shadow: none !important;
  color: inherit !important;
  padding:0px 10px !important;
  text-transform:capitalize;

  &:hover,
  &:focus {
    background-color: transparent !important;
    box-shadow: none !important;
  }
`;

export default CurricularPlan;


