import React from 'react'
import UserNavbar from '../../Components/UserNavbar';
import styled from "styled-components";
import { Search } from 'react-ionicons'
import {Form} from "react-bootstrap";
import FormControlLabel from '@mui/material/FormControlLabel';
import Checkbox from '@mui/material/Checkbox';


function JobsSearch({userdata}) {
  document.title = "Empregos";

  const Locations = [
    "Angola, Luanda","Brazil-Sau paulo", "estados unidos da america", "Canada",
    "Africa do Sul", "Tailandia", "India"
  ];

  const Experience = ["", "", ""];

  return (
    <div>
       <UserNavbar data={userdata} />
       <Container>
        <div className="col search-area">
            <div className="ed-wrapper">
                <Form>
                    <div className="ed-flex col">
                        <Search /><Form.Control placeholder='Digite qualquer coisa...' />
                    </div>
                    <div className="ed-flex col">
                        <Search />
                         <Form.Select >
                             <option value="$87,000" selected>$87,000</option>
                        </Form.Select>
                    </div>
                    <div className="ed-flex col">
                        <Search />
                        <Form.Select>
                            <option value="Tempo-Integral">Tempo integral</option>
                        </Form.Select>
                    </div>
                    <div className="ed-flex col">
                        <Search />
                         <Form.Select>
                            <option value="Angola Luanda">Angola Luanda</option>
                        </Form.Select>
                    </div>
                    <button className="btn">Pesquisar</button>
                </Form>
            </div>   
         </div>
          <div className="ed-wrapper">
              <div className="container-content">
                 <div className="content-header">
                   <div className="ed-space">
                       <div className="ed-block">

                       </div>
                       <div className="ed-flex">
                           
                       </div>
                   </div>
                 </div>
                 <div className="content-body">
                   <div className="filters">

                       <aside className="drop-down-content">
                          <div className="toggle bg-white">Localização</div>
                          <ul>
                            {Locations.map((item, index)=>(
                               <li>
                                  <FormControlLabel control={<Checkbox  />} label={item} />  
                               </li>
                            ))}
                          </ul>
                       </aside>
                       <aside className="drop-down-content">
                          <div className="toggle bg-white">Nivel de experiencia</div>
                          <ul>
                            {Experience.map((item, index)=>(
                               <li>
                                  <FormControlLabel control={<Checkbox  />} label={item} />  
                               </li>
                            ))}
                          </ul>
                       </aside>



                    </div>
                    <div className="pd-1"></div>
                    <div className="jobs-list">
                        <div className="list-data">
                        
                        </div>
                    </div>
                 </div>
              </div>
          </div>
      </Container> 
    </div>
  );
}


const Container = styled.div`
   padding:70px 0px;
   position:relative;
   width:100%;
   min-height:100vh;
   background:var(--ed-background-color);

    .search-area{
        position:fixed; 
        width:100%;
        left:0px;
        top:73px;
        min-height:80px;
        box-shadow:var(--ed-shadow-df);
        border-bottom:1px solid var(--ed-silver-light);
        padding:10px 20px;
        background:var(--ed-white);

          form{
             background:var(--ed-background-color);
             display:flex;
             align-items:center;
             border-radius:6px;
             margin-top:5px;


             .ed-flex{
                border-right:1px solid  var(--ed-silver);

                  svg{
                     margin:0px 10px;
                     color:var(--ed-grey-text);
                     fill:var(--ed-grey-text);
                  }
             }

             input, select{
                background:var(--ed-background-color);
                border:none !important;
                padding:8px 10px;
                border-radius:0px;
             }
          }
     }



     .container-content{
          display:block; 
          margin-top:120px;

        .content-body{
            width:100%;
            height:100%;
            display:flex;

            .filters{
                width:350px;
                min-width:350px;
                border:1px solid red;
                min-height:400px;
            }

            .jobs-list{
                width:100%;
                background:var(--ed-white);
                box-shadow:var(--ed-shadow-df);
                padding:20px;
                border-radius:10px;
                display:flex;
            }
        }
     }


`;





export default JobsSearch