import React, { useEffect, useState } from 'react'
import PdSchoolMarksTable from '../../../../Dashboard/components/Table/PdSchoolMarksTable';
import PdStudentMarksTable from '../../../../Dashboard/components/Table/PdStudentMarksTable';
import { FormControl, FormControlLabel, FormLabel, Radio, RadioGroup } from '@mui/material';
import PdStudentMarksCollegeTable from '../../../../Dashboard/components/Table/PdStudentMarksCollegeTable';
import ExportTableAsImage from '../../../../General/components/ExportTableAsImage';
import { BsCloudDownload } from "react-icons/bs";
import { ExportDataToTablesToPdf } from '../../../../General/components/ExportDataToTablesToPdf';

function STD_marks(props) {
  const [ActiveTab, setActiveTab] = useState(0);
  const [studentId, setStudentId] = useState(0);
  const [StudentClass, setStudentClass] = useState(null);


  useEffect(() => {
    console.log(props.data.student)
    setStudentId(props.data.student.ed_student_id);
    setStudentClass(props.data.student.ed_student_class);
  }, [])

  return (
    <>
      <div className="ed-space">
        <div></div>
        {props.data.student.ed_student_type * 1 === 0 ?
          <div className='ed-flex'>
            <FormControl id="academic_level_forExam">
              <div className="ed-flex">
                <RadioGroup aria-labelledby="academic_level_forExam" defaultValue={0}
                  name="radio-buttons-group" id="academic_level_forExam" onChange={(e) => setActiveTab(e.target.value * 1)}  >
                  <div className="ml-2 ed-wrap">
                    <FormControlLabel value="1" control={<Radio />} label="Nota escolar" />
                    <FormControlLabel value="0" control={<Radio />} label="Boletim escolar" />
                  </div>
                </RadioGroup>
              </div>
            </FormControl>
          </div>
          :
          <div className='ed-flex'>
            <FormControl id="academic_level_forExam">
              <div className="ed-flex">
                <RadioGroup aria-labelledby="academic_level_forExam" defaultValue={0}
                  name="radio-buttons-group" id="academic_level_forExam" onChange={(e) => setActiveTab(e.target.value * 1)}  >
                  <div className="ml-2 ed-wrap">
                    <FormControlLabel value="0" control={<Radio />} label="I Semestre" />
                    <FormControlLabel value="1" control={<Radio />} label="II Semestre" />
                  </div>
                </RadioGroup>
              </div>
            </FormControl>
          </div>

        }
      </div>

      {(StudentClass !== null && props.data.student.ed_student_type * 1 === 0) ?
        <>
          <div className={ActiveTab === 0 ? "col" : "d-none"}>
            <div className="student-table-marks">
              <PdStudentMarksTable StudentCode={studentId} ClassId={StudentClass} />
            </div>
            <button id="student-table-marks-btn-2" className="btn student-table-marks-btn bg-main text-center  col-lg-12 mb-2"
              onClick={() => ExportTableAsImage("std-mk2", 'student-table-marks-btn-2', "( Boletim escolar ) - Nome do estudante : " + props.data.student.ed_student_name)}>
              <BsCloudDownload /> Exportar boletim escolar (PDF)
            </button>
          </div>
          <div className={ActiveTab === 1 ? "col" : "d-none"}>
          <div className="student-table-marks">
              <PdSchoolMarksTable StudentCode={studentId} ClassId={StudentClass} />
            </div>
            <button id='student-table-marks-btn-1' className="btn bg-main student-table-marks-btn text-center col-lg-12 mb-2"
              onClick={() => ExportTableAsImage("std-mk1", 'student-table-marks-btn-1', "( Nota escolar ) - Nome do estudante : " + props.data.student.ed_student_name)}>
              <BsCloudDownload /> Exportar nota escolar (PDF)</button>
          </div>
        </> :
        <>
          {(StudentClass !== null && props.data.student.ed_student_type * 1 === 1) ?
            <>
              <div className="mt-4">
                <PdStudentMarksCollegeTable StudentCode={studentId} Semester={ActiveTab} ClassId={StudentClass} />
              </div>
            </>
            : <></>}
        </>
      }
    </>
  )
}

export default STD_marks