import React, {useState} from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import {Modal, Form, Button} from 'react-bootstrap'
import { Save, Update } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal'; 
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import ReplaceWord from '../../../General/components/ReplaceWord';
function NewMarkModal(props) { 
    const [show, setShow] = useState(false); 
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [Founded, SetFounded] = useState(null);

    const [showBox, SetshowBox]  = useState(false);
    const handleClose = () => {
      SetshowBox(false);
      setTimeout(() => {
        setShow(false);
      }, 1200);
    } 

    const handleShow = () => {
          SetshowBox(true);
          setShow(true);  
    };

    
  return (
    <div>
    <button className='btn btn-main bg-main ml-2' onClick={handleShow}>
        <AddCircleOutlineIcon/> Registrar nota
   </button>  
   <Modal size='lg' dialogAs={DraggableModal} centered  className={showBox ? ModalAnimationShow() : ModalAnimationClose()}  show={show} onHide={handleClose}>
     <Modal.Header closeButton>
       <Modal.Title>
        <div className="ed-wrap align-center">
            <UserOptionDropDown />
              <h5>{ props.title ? props.title : 'Efetuar ' } #</h5>
        </div>   
        </Modal.Title>
     </Modal.Header>
     <Modal.Body className='scrollLimit'>
       <Form>
         <Form.Group className="mb-3"  >
           <Form.Label>Turma<span className="text-danger ml-2">*</span> </Form.Label>
           <Form.Select Select>
               <option value="1" selected>---</option>
           </Form.Select>
         </Form.Group>
         <Form.Group className="mb-3"  >
           <Form.Label>Estrutura academica<span className="text-danger ml-2">*</span> </Form.Label>
           <Form.Select Select>
               <option value="1" selected>---</option>
           </Form.Select>
         </Form.Group>
         <Form.Group className="mb-3"  >
           <Form.Label>{ReplaceWord("Disciplina")} <span className="text-danger ml-2">*</span> </Form.Label>
           <Form.Select Select>
               <option value="1" selected>Ingles</option>
           </Form.Select>
         </Form.Group>
         <Form.Group className="mb-3"  >
           <Form.Label>Nome do aluno<span className="text-danger ml-2">*</span> </Form.Label>
           <Form.Select Select>
               <option value="1" selected>---</option>
           </Form.Select>
         </Form.Group>
         <hr />
         <div className="ed-flex">
         <Form.Group className="mb-3 col-lg-6"  style={{paddingRight:'10px'}}  >
           <Form.Label>MAC1 (P1)<span className="text-danger ml-2">*</span> </Form.Label>
           <Form.Control type="time" required autoFocus/>
         </Form.Group> 
         <Form.Group className="mb-3 col-lg-6" style={{paddingLeft:'10px'}}  >
           <Form.Label>NPP1 (P2)<span className="text-danger ml-2">*</span> </Form.Label>
           <Form.Control type="time" required autoFocus/>
         </Form.Group>
         </div> 
       </Form>
     </Modal.Body>
     <Modal.Footer>
     <div className="ed-space">
             <div className="ed-flex"></div>
             <div className="ed-flex">
             <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button> 
            {props.update ? (Founded === false ? <div></div>  : 
            <SaveButton icon={props.title ? <Update/> : <Save/>} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
            <SaveButton icon={props.title ? <Update/> : <Save/>} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />} 
             </div>
          </div>
     </Modal.Footer>
   </Modal> 
 </div>
  ) 
}

export default NewMarkModal