import React, {useState, useEffect} from 'react'
 import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import { Delete, Description, Edit ,OpenInBrowser, Refresh } from '@mui/icons-material';
import DeleteModal from '../elements/DeleteModal';
 import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import CalendarEventModal from '../modal/CalendarEventModal';
import moment from 'moment';

const TABLEURL = Hoot()+"eduallgetcalendarevents/get";
const columns = [  
  { field: 'index', width:90, headerName: 'Nº'},
  {
    field: 'title',
    headerName: 'Titulo do evento',
    resizable: true,
  },
  {
    field: 'start',
    headerName: 'Data inicial',
    resizable: true,
  },
  {
    field: 'end',
    headerName: 'Data final',
    resizable: true,
  },  
  {
    field: 'action',
    headerName: 'Ação', 
     resizable: true,
     cellRenderer:(props) => { 
      return  <div className="ed-flex">
      <CalendarEventModal title='Atualizar ' update='true' get={Hoot()+`eduallgetsinglecalendarevent/get/${props.data.id}`}  
       url={Hoot()+`eduallupdatecalendarevent/update/${props.data.id}`} 
           toggle_btn={
             <button  className="btn-circle bg-success text-light">
                 <Edit/>
            </button> 
           } 
      />
     <DeleteModal title='este evento' url={Hoot()+`eduallcalendareventdelete/delete/${props.data.id}`} message='Evento deletado com sucesso' toggle_btn={ 
       <button  className="btn-circle bg-danger ml-2 text-light">
           <Delete/>
       </button>} />
     </div>;
    }
 }
];

function CalendarEventsTable() {
  const [data, setData] = useState([]); 
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData(){
   try {
     setLoadStatus(0); 
     setLoaded(false)
       const response = await axios.get(TABLEURL); 
       const rows = [];
       response.data.map((item, index)=>{ 
         rows.push({
            index:index+1,
           id:item.ed_calendar_event_id,
           title:item.ed_calendar_event_title,
           start:item.ed_calendar_event_start,
           end:moment(item.ed_calendar_event_end).format("YYYY-MM-DD HH:mm"),
           color:moment(item.ed_calendar_event_color).format("YYYY-MM-DD HH:mm"), 
        })
       }); 
       setData(rows);
       setTimeout(() => {
         setLoaded(true);
       }, 200);
       setLoadStatus(2); 
   } catch (error) {
    setLoadStatus(1); 
   }
  };
  
  useEffect(()=>{ 
      loadData();  
  },[]);
 
 

  if(load){
      return (
      <div>
        <TableGrid
            TableHead={columns}
            TableBody={data} 
            TableTitle='Calendário de eventos'
            TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
    </div>
    )
  }else{
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
              TableHead={columns}
              TableBody={[]} 
              TableTitle='Calendário de eventos'
              TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
          />
    </div>
    )
  }
  
}

export default CalendarEventsTable
