 

import React, { useEffect } from 'react'
import UserNavbar from '../Components/UserNavbar'
import styled from 'styled-components';
import SidebarLeft from './Components/SidebarLeft';
import { Link, useParams } from 'react-router-dom';
import SettingsOutlinedIcon from '@mui/icons-material/SettingsOutlined';
import CloudDownloadOutlinedIcon from '@mui/icons-material/CloudDownloadOutlined';
import CalendarMonthOutlinedIcon from '@mui/icons-material/CalendarMonthOutlined';
import NavigateNextOutlinedIcon from '@mui/icons-material/NavigateNextOutlined';
import { Avatar } from '@mui/material';
import { useState } from 'react';
import TeacherDashboardTabItem from './Components/Tabs/TeacherDashboardTabItem';
import TeacherStudentMarksTabItem from './Components/Tabs/TeacherStudentMarksTabItem';
import TeacherClassesTabItem from './Components/Tabs/TeacherClassesTabItem';
import TeacherTasksAnProjectsTabItem from './Components/Tabs/TeacherTasksAnProjectsTabItem';
import TeacherStudentContentTabItem from './Components/Tabs/TeacherStudentContentTabItem';
import TeacherAttendanceTabItem from './Components/Tabs/TeacherAttendanceTabItem';
import TeacherSettingsTabItem from './Components/Tabs/TeacherSettingsTabItem';
import TeacherSchedulerTabItem from './Components/Tabs/TeacherSchedulerTabItem';
import axios from 'axios';
import jwt_decode from 'jwt-decode';
import Hoot from '../../General/components/Hoot';
import ReduceTextLength from '../../General/components/ReduceTextLength';
import TeacherContinuousEvaluation from './Components/Tabs/TeacherContinuousEvaluation';
import { GetClasstitle_byclass, GetSubject } from '../../General/components/InstituteData';
import { Badge } from 'react-bootstrap';
import SliderComponent from './Components/SliderComponent';
import Loader from '../../General/components/Loader';
import NoData from '../../General/components/NoData';
import ImageLazyLoading from '../../General/components/ImageLazyLoading';
import { RiMenu4Line } from "react-icons/ri";
import Menu from '@mui/material/Menu';
import MenuItem from '@mui/material/MenuItem';
import { Offcanvas } from 'react-bootstrap';
import { IoClose } from "react-icons/io5";
import AddsGenerator from '../Components/AddsGenerator';
import { Tabs, Tab } from 'react-bootstrap';
import ImportarEstudantesButton from '../../Dashboard/components/modal/ImportarEstudantesButton';
import { MdOutlineRefresh } from "react-icons/md";

function EmployeeDashboard(props) {
    const [ActiveTab, SetActiveTab] = useState(1);
    const Data = props.userdata.user_Information;
    const Institutes = props.userdata.user_institutes;
    const [UserData, setUserData] = useState({});
    const [TeacherData, setTeacherData] = useState({ ClassList: [], SubjectsList: [], teacherCode: null, data: [], employeeData: [] });
    const [Loaded, setLoaded] = useState(false);
    const [Founded, setFounded] = useState(false);
    const [CurrentInstitute, SetCurrentInstitute] = useState("");

    const [anchorEl, setAnchorEl] = useState(null);
    const open = Boolean(anchorEl);
    const [activeMenu, SetActiveMenu] = useState(0);
    const [show, setShow] = useState(false);

    const handleClose1 = () => {
        setShow(false);
    };

    const handleShow = () => {
        setShow(true);
    }


    const handleClick = (event) => {
        setAnchorEl(event.currentTarget);
    };

    const handleClose = (e) => {
        setAnchorEl(null);
    };


    const DATA_URL = [
        Hoot() + 'eduallsingleuserdata/get/',
        Hoot() + 'token',
        Hoot() + 'eduallgetteachersubjects/get/',
        Hoot() + 'eduallgetallteachertiming/get/',
        Hoot() + "eduallupdatecurrentinstitutecode/post/",
        Hoot() + "eduallgetemployeeattendencebycode/get/",
        Hoot() + "eduallgetsingleuserandemployeedata/get"
    ];

    const { INSTITUTECODE } = useParams();
    console.log(Institutes);


    const CheckCurrentInstitute = async () => {
        const CODES = [];
        for (let i = 0; i < Institutes.length; i++) {
            CODES.push(Institutes[i].ed_user_institute_code.toLowerCase())
            if (Institutes[i].ed_user_institute_code.toLowerCase() === INSTITUTECODE.toLowerCase()) {
                SetCurrentInstitute(Institutes[i]);
            }
        }


        console.clear()
        console.log(CODES);

        if (CODES.includes(INSTITUTECODE.toLowerCase())) {
            try {
                await axios.post(DATA_URL[4] + INSTITUTECODE).then((e) => {
                    loadData();
                }).catch((error) => {
                    setLoaded(true);
                    setFounded(false);
                    console.log(error)
                });
            } catch (error) {
                setLoaded(true);
                setFounded(false);
            }
        } else {
            setLoaded(true);
            setFounded(false);
        }
    }


    function UpdatePage() {
        localStorage.removeItem("reload_attempts");
       CheckCurrentInstitute(); 
    }

    async function loadData() {
        try {
           setLoaded(false);
            setUserData({
                email: Data.ed_user_account_email,
                phone: Data.ed_userphone,
                picture: Hoot() + Data.ed_user_account_picture,
                code: Data.ed_user_account_id,
                name: Data.ed_user_account_name,
                gender: Data.ed_user_account_gender,
                firstname: (() => {
                    const fullName = Data?.ed_user_account_name?.trim();
                    if (!fullName) return '';
                    const parts = fullName.split(/\s+/);
                    return parts[0];
                })(),
                firstlastname: (() => {
                    const fullName = Data?.ed_user_account_name?.trim();
                    if (!fullName) return '';
                    const parts = fullName.split(/\s+/);
                    if (parts.length === 1) return parts[0];
                    return parts[0] + ' ' + parts[parts.length - 1];
                })(),
                lettername: (() => {
                    const fullName = Data?.ed_user_account_name?.trim();
                    if (!fullName) return '';

                    const parts = fullName.split(/\s+/);
                    const firstInitial = parts[0]?.[0]?.toUpperCase() || '';
                    const lastInitial =
                        parts.length > 1 ? (parts[parts.length - 1]?.[0]?.toUpperCase() || '') : '';

                    return firstInitial + lastInitial;
                })(),
            });
            document.title = "Portal professor(a) - " + Data.ed_user_account_name;

            const [response2, response3, response4] = await Promise.all([
                axios.get(DATA_URL[2] + Data.ed_user_account_id),
                axios.get(DATA_URL[3] + Data.ed_user_account_id),
                axios.get(DATA_URL[6]),
            ]);


            const subjects = [];
            const classes = [];
            response2.data.map((item, index) => {
                subjects.push(item.ed_tch_subject_code);
                classes.push(item.ed_tch_subject_class);
            });


            const dt = {
                ClassList: classes,
                SubjectsList: subjects,
                teacherCode: Data.ed_user_account_id,
                data: response2.data,
                timings: response3.data,
                employeeData: response4.data
            }
            setTeacherData(dt);
            setLoaded(true);
            setFounded(true);
            console.clear()
            console.log(dt)
        } catch (error) {
            setLoaded(true);
            setFounded(false);
            console.clear();
            console.log(error);
        }
    };


 


    useEffect(() => {
  CheckCurrentInstitute();

  const MAX_TRIES = 3;
  const STORAGE_KEY = "reload_attempts";

  let tries = parseInt(localStorage.getItem(STORAGE_KEY) || "0", 10);
  const reloadBtn = document.querySelector(".realod-page-button");

  async function verifyAndReload() {
    const selector = document.getElementById("class-selector-element");
    const subjectsContainer = document.getElementById("teacher-subjects-and-class");
    const smallEls = document.querySelectorAll(".small-el-title");

    const validOptions = selector
      ? Array.from(selector.options).filter(opt => !opt.disabled)
      : [];
    const hasBadges = subjectsContainer
      ? subjectsContainer.querySelectorAll(".badge").length > 0
      : false;
    const hasSmallEls = smallEls.length > 0;

    // Caso nenhum dos três exista, tenta recarregar
    if (validOptions.length === 0 && !hasBadges && !hasSmallEls) {
      if (tries < MAX_TRIES) {
        tries += 1;
        localStorage.setItem(STORAGE_KEY, tries);

        if (reloadBtn) {
          reloadBtn.innerHTML = `
            <div class="d-flex align-items-center justify-content-center">
              <div class="spinner-border spinner-border-sm text-dark me-2" role="status">
                <span class="visually-hidden">Carregando...</span>
              </div>
              Atualizando as suas informações...
            </div>
          `;
          reloadBtn.classList.remove("bg-green");
          reloadBtn.classList.add("bg-warning", "text-dark");
          reloadBtn.disabled = true;
        }

        console.log(`🔁 Tentativa automática ${tries}/${MAX_TRIES}...`);

        // chama loadData() e aguarda 1.5s antes de reavaliar
        await loadData();
        CheckCurrentInstitute();

        setTimeout(() => {
          verifyAndReload();
        }, 1500);
      } else {
        if (reloadBtn) {
          reloadBtn.innerHTML = `
            <i class="bi bi-arrow-repeat me-2"></i> Recarregar página
          `;
          reloadBtn.classList.remove("bg-warning");
          reloadBtn.classList.add("bg-danger", "text-light");
          reloadBtn.disabled = false;
        }
        console.warn("⚠️ Limite máximo de tentativas automáticas atingido.");
      }
    } else {
      // Resetar contador se dados forem encontrados
      localStorage.removeItem(STORAGE_KEY);
      if (reloadBtn) {
        reloadBtn.innerHTML = `
          <i class="bi bi-arrow-repeat me-2"></i> Recarregar página
        `;
        reloadBtn.classList.remove("bg-warning", "text-dark");
        reloadBtn.classList.add("bg-green", "text-light");
        reloadBtn.disabled = false;
      }
      console.log("✅ Dados encontrados, não é necessário recarregar.");
    }
  }

  // Primeira execução automática após 1s
  setTimeout(() => {
    verifyAndReload();
  }, 3000);
}, []);



    const ChangeActiveTab = (e) => {
        SetActiveTab(e);
        setShow(false);
    }


 


    return (
        <div className="eduall-network body-theme">
            <UserNavbar logoIndex={3} noquote data={props.userdata} />
            {Loaded ?
                <>
                    {Founded ?
                        <>
                            <ContainerBox className="ed-employee-dashboard body-theme">
                           
                                <section>
                                    <div className="container-header box-theme">
                                        <div className="ed-wrapper">
                                            <div className="block-content">
                                                <div className="ed-space ed-space-header">
                                                    <div className="block block-left">
                                                        <div className="ed-space">
                                                            <div className="ed-flex mb-3 box-theme itbadge">
                                                                <Avatar src={Hoot() + CurrentInstitute.ed_institute_logo} className='df' sx={{ width: 35, height: 35 }} />
                                                                <div className="col-lg-10 ml-2"> <small className='theme-light-txt'><ReduceTextLength text={CurrentInstitute.ed_institute_name} length="27" /></small></div>
                                                            </div>

                                                            <button onClick={()=>UpdatePage()} className='btn bg-main btn-bordered text-main realod-page-button'>
                                                               <MdOutlineRefresh /> Recareegar pagina
                                                            </button>

                                                        </div>
                                                        <div className="ed-flex info-block mb-2 user-info">
                                                            <Link to="#"><Avatar className="df" src={UserData.picture} alt={UserData.lettername} sx={{ width: 85, height: 85 }} /></Link>
                                                            <div className="block ml-2">
                                                                <span className='ed-flex theme-light-txt'>Nome  : <Link to="/"><div className=" ml-2 text-main">{UserData.firstlastname}</div></Link> </span>
                                                                <span className="ed-flex mt-2 theme-light-txt">Função : <div className="ml-2 grey-text">Professor (a)</div></span>
                                                            </div>
                                                        </div>
                                                        <div className="sbj">
                                                            {TeacherData.data.length >= 1 ?
                                                                <div className='ed-wrap mb-4'>
                                                                    {TeacherData.data.map((item, index) => {
                                                                        return (
                                                                            <div id="teacher-subjects-and-class" key={index} >
                                                                                <div className='badge text-light bg-main mr-2 pd-1 mt-2'>
                                                                                    Turma - <GetClasstitle_byclass ID={item.ed_tch_subject_class} />
                                                                                    (<GetSubject ID={item.ed_tch_subject_code} /> )
                                                                                </div>
                                                                            </div>
                                                                        )
                                                                    })}
                                                                </div>
                                                                :
                                                                <></>
                                                            }
                                                        </div>
                                                        <h2 className='welcome-text  '>Bem-vind{UserData.gender === 0 ? "o" : "a"} de volta , Prof. {UserData.firstname}</h2>
                                                        <div className="welcome-description grey-text"> <small>comece por  verificar os seus trabalhos  e tarefas do dia.</small></div>
                                                    </div>
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                    <br />
                                    <aside className="ed-teacher-dashboard-menu body-theme">
                                        <div className="ed-wrapper">
                                            <div className="container-content"> 
                                                <Tabs defaultActiveKey="1" id="teacher-dashboard-tabs" className="mb-3" variant="tabs"  >
                                                    <Tab eventKey="1" title="Dashboard">
                                                        <TeacherDashboardTabItem Data={TeacherData} />
                                                    </Tab>
                                                    <Tab eventKey="2" title="Lançar notas">
                                                        <TeacherStudentMarksTabItem Institute={CurrentInstitute} Data={TeacherData} />
                                                    </Tab>
                                                    <Tab eventKey="3" title="Lista de controle">
                                                        <TeacherAttendanceTabItem Data={TeacherData} />
                                                    </Tab>
                                                     


                                                     {/*


                                                    <Tab eventKey="4" title="Vida Acadêmica">
                                                        <TeacherStudentContentTabItem Data={TeacherData} />
                                                    </Tab>


                                                      */}

                                                    <Tab eventKey="5" title="Turmas">
                                                        <TeacherClassesTabItem Data={TeacherData} />
                                                    </Tab>
                                                    <Tab eventKey="6" title="Avaliação contínua">
                                                        <TeacherContinuousEvaluation Data={TeacherData} />
                                                    </Tab>
                                                </Tabs> 
                                                <br /><br /><br /><br />
                                            </div>
                                        </div>
                                    </aside>
                                    <br />
                                </section>
                            </ContainerBox>
                        </> :
                        <>
                            <Content>
                                <NoData />
                            </Content>
                        </>
                    }
                </>
                : <>
                    <Loader />
                </>}
        </div>
    )
}


const Content = styled.div`
   display:block;
   padding:20px; 
   width:100%;
   padding-top:90px;
   overflow-y:auto;
   min-height:99vh;
   max-height:99.5vh;
   background:var(--ed-background-color); 
   position:relative;

   .container-content{
      padding:0px;
   }


   
  &&::-webkit-scrollbar{
    width:6px !important;
    background-color:transparent !important;
  }
    
    &&::-webkit-scrollbar-thumb{
        background:rgb(219, 219, 219) !important; 
    }

   .ed-student-details{
           
     .code{
        margin:7px 0px;
        span{
           color:var(--ed-grey-text);
        }
     } 
 

     .ed-block{
        margin-left:20px;
      }
    }

   .box-content-tabs{
        padding:20px 0px;   
        padding-bottom:0px;  
        width:100%;  
        margin:0px;
        display:flex;
        align-items:center; 

         li{ 
            transition:all 1s ease-in-out;
            margin-right:20px;
            font-weight:500;
            cursor:pointer;
            color:var(--ed-dark); 
            padding:10px 20px; 
            border-radius:6px;
            cursor:pointer; 
            display:flex;
            align-items:center;
            border:1px solid  #eaeaee;
        }

     }


   .title, .name{
    font-size: 18px;
    font-weight: 600;
    margin: 0px;
   }

   .sc_tab{
       display:none;
    }

    .sc_tab.active{
        display:block !important;
    }

`;


const ContainerBox = styled.div`

#teacher-dashboard-tabs .nav-link {
  color: var(--ed-grey-text); 
}

 
#teacher-dashboard-tabs .nav-link.active {
  color: var(--ed-purple);
  font-weight: bold;  
}
 
.container-content{
    padding:0px 5px;
}

.itbadge{
      padding:4px 10px;
      margin:5px 0px;
      width:max-content;
      border-radius:30px;
      background:var(--ed-silver-light);
      
        small{
            color:var(--ed-dark);
        }
}

  .sbj{
    min-height:60px;
  }


  .header-buttons-2{
     display:none;
     width:50px;
  }

   

   .container-header{
      min-height:300px;
      width:100%;
      padding:20px;
      padding-top:20px; 
      background:var(--ed-white);
      border-bottom:1px solid var(--ed-silver-light); 
      color:var(--ed-blue-dark);
      

      .block small{
          max-width:200px;
      }


      .block-left{
          width:100%;
      }

      .block.text-right{
          min-width:40%;
          text-align:right;
          display:flex;
          align-items:flex-end;
          flex-direction:column;

          a{
             color:var(--ed-white);
          }

          ul{
            padding-top:20px;

            li{
              padding:10px 20px; 
              border-radius:6px;
              cursor:pointer; 
              display:flex;
              align-items:center;

                svg{
                    margin:0px;
                    margin-right:7px;
                }
            }
            
             li.blue-link{background:var(--ed-blue-light);}
             li.bg-white{
                svg{
                    fill:var(--ed-dark);
                }
             }
 
            li.mr-4{
               margin-right:20px; 
            }
          }
      }

        .header-tab{
            width:100%;
            padding:20px 0px;
            margin-top:20px;
            border-bottom:1px solid var(--ed-blue-dark);

              
             li.active{ 
                background:var(--ed-white) !important;
             }

             li{
                  padding:10px 20px;
                  margin-right:15px;
                  border-radius:6px;
                  cursor:pointer;
                  border:1px solid var(--ed-white);
             }
        }
    }
  
`;


export default EmployeeDashboard