 

 
function CommentsToggle() { 
    let Comments  =  document.querySelectorAll(".comment-box-area"); 

    for (let c = 0; c < Comments.length; c++) {
        const Comment = Comments[c];
        const Toggles =  Comment.querySelectorAll(".toggle-container .show-answers");
        let Answers = Comment.querySelectorAll(".comment-reply");
 
        Toggles.forEach(btn =>{
            btn.addEventListener("click", ()=>{  
                Answers.forEach(an => {
                   an.classList.toggle("show");
               });
            });
        });


        Answers.forEach(element => {
            let subAnswers =  element.querySelectorAll(".comment-sub-reply");
            const SubToggles  =  element.querySelectorAll(".show-answers");
            SubToggles.forEach(btn =>{
                btn.addEventListener("click", ()=>{  
                    subAnswers.forEach(an => {
                       an.classList.toggle("show");
                   });
                });
            });
        });
   
        
    }  
}
export default CommentsToggle;