import React, { useEffect, useState } from 'react' 
import { styled } from 'styled-components';
import Loader from '../../General/components/Loader';
import NoData from '../../General/components/NoData';
import { useParams } from 'react-router-dom';
import ImageLazyLoading from '../../General/components/ImageLazyLoading';
import { Avatar, AvatarGroup } from '@mui/material'; 
import ReduceTextLength from '../../General/components/ReduceTextLength';
import Hoot from '../../General/components/Hoot';
import axios from 'axios'; 
import UserNavbar from '../Components/UserNavbar';
import { Link} from 'react-router-dom';


function SchoolsPage({userdata}) {
    const {INSTITUTECODE} = useParams(); 
    const [Founded, setFounded] = useState(false);
    const [Loaded, setLoaded] = useState(false);
    const [ActiveTab, setActiveTab] = useState(1);
    const [Data, setData] =  useState([]);
    document.title = "Blog da instituição"; 

    const DATAURL = [
        Hoot()+"eduallgetallinstitutes/get", 
    ] 
  

    const LoadData = async()=>{  
      try {
        const [response] = await Promise.all([
            axios.get(DATAURL[0]),  
      ]); 
      if(response.data.length >= 1){
         setFounded(true);
         setLoaded(true);
         setData(response.data); 
      }else{
         setFounded(false);
         setLoaded(true);
      }

      
      } catch (error) {
         setFounded(false);
         setLoaded(true);
      }           
     }
     
 
     useEffect(()=>{
        LoadData();
     },[]);  

 
    if(Loaded){ 
        if(Founded){
            return (
                <div>
                 <UserNavbar data={userdata} /> 
                    <Container>
                    <div className="ed-wrapper">
                      <Content>  
                        <div className="search-area">
                            
                        </div>
                        <div className="ed-wrap">
                            {Data.map((item, index)=>{
                                return(
                                 <Card key={index+1}>
                                      <div className="wall">
                                         <ImageLazyLoading height={150} source={Hoot()+item.ed_institute_coverImage} />
                                      </div>
                                      <div className="dets">
                                      <div className="logo">
                                      <Link to={`/cppage/${item.ed_institute_code}`}>
                                          <Avatar className='df' variant="rounded" src={Hoot()+item.ed_institute_logo} sx={{width:100,height:100}} />
                                       </Link>
                                      </div>
                                      <div className="name">
                                         <Link to={`/cppage/${item.ed_institute_code}`}>
                                              <h1><ReduceTextLength length={60} text={item.ed_institute_name} /> </h1>
                                          </Link>
                                         </div>
                                      </div>
                                      <div className="details">

                                      </div>
                                </Card>);
                            })}
                        </div>
                       </Content>
                       </div>
                    </Container>
                </div>
              )
        }else{
         return (
           <div>
           <UserNavbar data={userdata} /> 
              <Content>
                 <NoData />
              </Content> 
           </div>
         );
        }
       }else{ 
         return (
           <div>
           <UserNavbar data={userdata} /> 
              <Content>
                 <Loader />
              </Content> 
           </div>
         );
    }
}

const Container = styled.div`
   width:100%;
   min-height:100vh;
   background:var(--ed-background-color);
   padding:40px;
   padding-top:120px; 
`;

const Content = styled.div`
   display:block; 
   width:100%; 
   padding:20px;
   position:relative;
   box-shadow:var(--ed-shadow-df);
   background:var(--ed-white) !important;
   border-radius:10px;
`;


const Card = styled.article`
     width:31%;
     height:300px;
     position:relative;
     border-radius:5px;
     color:var(--ed-dark); 
     margin:10px;
     overflow:hidden;
     border:1px solid var(--ed-silver-light);
  
       .wall{ 
             img{
               width:100%;height:150px;object-fit:cover;
             }
         }


         .logo{
              position:relative;
              margin-left:20px;
             margin-top:-55px;
             border:5px solid #ffff;
             box-shadow:var(--ed-shadow-df);  
             border-radius:6px;
             background:var(--ed-white); 
             width:110px;
             height:110px;
             display:flex;
             align-items:center;
             justify-content:center;
         }

       .dets{
         display:flex;

         .name{
            h1{
               font-size:17px;
               margin:0px;
               margin-left:10px;
               margin-top:10px; 
               color:var(--dark);
               line-height:30px;
               display:flex;
               align-items:flex-end;
          }
         }
       }

     .details{
        padding:20px;
     }

`;




export default SchoolsPage