import React, { useEffect, useState } from 'react';
import Hoot from './Hoot';
import axios from 'axios';
import moment from 'moment'; 
import { WarningOutline } from 'react-ionicons'


function LicenceCountDown({Access}) {
const [Text, setText] =  useState(null);

async function loadData(){ 
  if(Access*1 === 1){
    try { 
      const response = await axios.get(Hoot()+"eduallgetinstitutelicencestatus/get"  );    
      if(response.data.length >= 1){ 
        let date  = moment(response.data[0].ed_institute_licence_endDate).format("MM-DD-YYYY HH:mm:ss"); 
        CountDown(date);
      }
    } catch (error) {
      
    } 
  } 
}


    const CountDown = (licenceDate)=>{
        var countDownDate = new Date(licenceDate).getTime(); 
        var x = setInterval(function() { 
        var now = new Date().getTime(); 
        var distance = countDownDate - now;
            
        // Time calculations for days, hours, minutes and seconds
        var days = Math.floor(distance / (1000 * 60 * 60 * 24));
        var hours = Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
        var minutes = Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60));
        var seconds = Math.floor((distance % (1000 * 60)) / 1000);
            
        // Output the result in an textState
         if (distance <= 0) {
            clearInterval(x);
            setText("A SUA LICENÇA EXPIROU POR FAVOR ATUALIZE O SEU PLANO !");
         }else{
           if(days <= 7) setText("O prazo da sua licença termina em " + days + " dias " + hours + " horas "  + minutes + " minutos e " + seconds + " segundos ");
          }
        }, 1000);
    }

    useEffect(() => {
        loadData();
    }, []);


  return (
    <div >    
      {Text !== null ?
        <section>
          <div className="alert-area ed-flex ed-center">
            <div className="box ed-flex ed-center"> 
               <div className="ed-flex">
                 <WarningOutline color={"#ffff"} width={"25px"} height={"25px"} />
                 <div className="ml-2"><h1>{Text}</h1></div> 
              </div>
           </div> 
         </div> 
      </section> 
      : <></>}
    </div>
  )
}

export default LicenceCountDown