import { Axios } from 'axios';
import React, { useEffect, useState } from 'react' 
import styled from "styled-components";
import Hoot from '../../../../General/components/Hoot';
import { toast } from 'react-hot-toast';  
import SaveButton from '../../../../Dashboard/components/elements/SaveButton'; 
import { Avatar } from '@mui/material'; 
import TimeAgo from "javascript-time-ago";
import pt from "javascript-time-ago/locale/pt.json";
import ReactTimeAgo from 'react-time-ago'   
import {Form } from 'react-bootstrap';
import { createReactEditorJS } from 'react-editor-js'
import CommentsArea from '../../../../General/components/CommentsArea';


function LessonCommentsTab({data, filters, userdata ,  id, socket, total}){
  const [LessonComments , SetLessonComments] = useState([]);
  const [CommentText, setCommentText] = useState("");
  const [CommentGif, setCommentGif] = useState(""); 
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);
  const  [ReviewsStats, setReviewsStats] = useState({});
  const [LargestReview, setLargestReview]  = useState(0); 
  const [RegisterStatus, setRegisterStatus] = useState(null); 
  const ReactEditorJS = createReactEditorJS()

  async function loadData(){
    if(id !== null){
      try {
        setLoaded(false); 
        setLoadStatus(0) 
        const response = await Axios.get(Hoot()+"eduallgetlessoncommentsbylessonid/"+id); 
        SetLessonComments(response.data); 
        total(response.data.length);  
        setLoadStatus(2)
      } catch (error) {
        setLoadStatus(1)
      }
    } 
}


const GetRealTimeData =  (data)=>{ 
  console.clear();
  console.log(data, id);
  if(data !== null && data !== undefined){
    if(data.ed_comment_contentID*1 === id){ 
      setRegisterStatus(2)
      if(data !== null & data !== undefined){
        SetLessonComments([...LessonComments, data]);
        setTimeout(() => { 
          total(LessonComments.length);  
        }, 1000);
      };
    }else{
      setRegisterStatus(1);
    }
  }else{
    setRegisterStatus(1);
  }
} 


const FormSubmit = (e)=>{     
  e.preventDefault();
  setRegisterStatus(0);
  if(CommentText.split("").length >= 1){
    const FormData = { 
      comment_socketID: socket.id,
      comment_contentid:id,
      comment_text:CommentText,
      comment_gif:CommentGif,
      comment_image:"",
      comment_type:2,
   };  
    
    try { 
      socket.emit('eduall_send_content_commentIo', FormData);  
      setCommentText("");
      setCommentGif(null); 
    } catch (error) {
      console.clear();
      console.log(error);
      toast.error("Ocorreu um erro ao enviar o seu comentario !")
      setRegisterStatus(1)
    }  
  }else{
    setRegisterStatus(1);
  }
};


 
useEffect(() => { 
  socket.on('eduall_response_lesson_comments', (data) => GetRealTimeData(data.data, data.user)); 
}, [socket, LessonComments]);


useEffect(()=>{
  loadData(); 
},[id]);


 

 

  return (
    <Container> 
        <div className="comment-form">
           <Form onSubmit={FormSubmit}>
                <div className="d-flex mb-2">
                    <Avatar sx={{width:40,height:40}} src={Hoot()+userdata.user_Information.ed_user_account_picture} />
                    <div className="ml-2 col">
                       <Form.Control as="textarea" value={CommentText} onChange={(e)=>setCommentText(e.target.value)}
                        minLength={10} maxLength={500} placeholder='Partilhe a sua opnião ...' />
                       <div className="mt-2">
                           <SaveButton icon={<></>} title={'Enviar'} status={RegisterStatus} /> 
                         </div> 
                    </div>
                </div>  
             
            </Form> 
        </div>
       <div className="mt-4 mb-4">
          <h1 className="title">Comentarios ({LessonComments.length})</h1>
       </div>
        <CommentsArea id={id} type={2}  />
    </Container>
  )
}



const Container  = styled.div`

  .comment-form{
    textarea{
      min-height:100px;
    }

    button{
        margin-left:0px !important;
    }
  }




`;

export default LessonCommentsTab