import React from 'react'
import styled from "styled-components"
import ImageLazyLoading from '../../../General/components/ImageLazyLoading';
import ReduceTextLength from '../../../General/components/ReduceTextLength';
import { Link } from 'react-router-dom';

const Images  = [ 
    "https://pbs.twimg.com/media/FUrM63WWAAEkZBv.jpg",
    "https://neofeed.com.br/wp-content/uploads/2023/07/microsoft-produtos-1200x900.jpg",
    "https://i.cbc.ca/1.6717768.1674054979!/fileImage/httpImage/microsoft-earns.jpg",
    "https://m.media-amazon.com/images/S/aplus-media-library-service-media/1b0da748-526c-43f9-aa82-43a20046a947.__CR0,0,362,453_PT0_SX362_V1___.jpg",
    "https://cdn.vox-cdn.com/thumbor/_pOEhkYxLVyJVrGjRtNdBI13DA0=/0x0:3500x2333/1200x800/filters:focal(1470x887:2030x1447)/cdn.vox-cdn.com/uploads/chorus_image/image/71897646/GettyImages_1306394029.0.jpg",
    "https://hips.hearstapps.com/hmg-prod/images/do-you-really-need-to-buy-microsoft-office-1613572009.jpg?crop=0.668xw:1.00xh;0.0974xw,0&resize=640:*",
    "https://news.microsoft.com/wp-content/uploads/prod/sites/382/2019/09/452292672.jpg",
    "https://cdn-dynmedia-1.microsoft.com/is/image/microsoftcorp/MSFT-Five-characters-different-Disney-plus-shows-RE59Bs7:VP2-859x540",
];

function LatestPostBox({data}) {
  return (
    <Box>
       <div className="media-area">
          <Link to="#">
             <ImageLazyLoading source={Images[Math.floor(Math.random() * (Images.length-1))]}  height={200} />
          </Link>
        </div> 
        <div className="text-area">
           <Link to="#">
              <p><ReduceTextLength text="Texas Motor Speedway claims to be able to hold 180,000 people, but that includes the skybox seats high above too." length={30}  /> </p>
           </Link>
            <strong>43M visualizações</strong>
        </div>
    </Box>
  )
}

const Box = styled.div`
   min-width:200px;
   min-height:200px;
   border-radius:6px;
   border:1px solid var(--ed-silver-light);
   display:block;
   background:var(--ed-white);
   box-shadow:vat(--ed-shadow-df);


     .media-area{
         overflow: hidden;
         height:200px;

          img, .video-box{
              height:200px;
              width:100%;
              object-fit:cover;
          }
     }

     .text-area{
         padding:10px;
      
          p{
            font-size:15px;
            color:var(--ed-dark);
         }

          strong{
            font-size:13px;
            margin-top:10px;
          }
     }
`;

export default LatestPostBox