import React, {useState, useEffect} from 'react'
import axios from 'axios'
import { Delete,  Edit , Refresh } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import { GetServiceTitle, GetServicePriceNumb, GetServiceCointText } from '../../../General/components/InstituteData';
import DeleteModal from '../elements/DeleteModal'; 
import TableGrid from '../../../General/components/TableGrid';
import { Badge } from 'react-bootstrap';
import NewFinePriceModal from '../modal/NewFinePriceModal';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import moment from "moment";
import 'moment/locale/pt'; 
import PopAuditoryDetailsModal from '../modal/PopAuditoryDetailsModal';
moment.locale('pt'); 


const TABLEURL = Hoot()+"eduallgetcurrentinstituteauditory/get"; 
const Actions = [
  <div className='badge col-lg-12 bg-info'>Outro</div> ,
  <div className='badge col-lg-12 bg-success'>Registro</div> ,
  <div className='badge col-lg-12 bg-warning'>Atualização</div> ,
  <div className='badge col-lg-12 bg-danger'>Deleção</div> 
];



const columns = [ 
  {field:'index', headerName:'Nº', width:60},
  {
    field: 'form',
    headerName: 'Formulários',
    width:300,  
  }, 
  {
    field: 'action',
    headerName: 'Tipo de de ação',
    width:200, 
    resizable: true, 
    cellRenderer:(props)=>{
      return Actions[props.data.action*1]
    }
  },  
  {
    field: 'user',
    headerName: 'Usúario',
    width:160,
    sortable:false, 
  },
  {
    field: 'description',
    headerName: 'Descrição',
    width:250,  
    cellRenderer:(props)=>{
      return <PopAuditoryDetailsModal description={props.data.description} toggle_btn={
        <button className='col-lg-12 btn-circle mt-2 bg-main text-main'>Ver descrição</button>
      }  />
    }
  },
  {
    field: 'date',
    headerName: 'Data da ação',
    width:350, 
  }, 
]; 

function LogsHistoryTable() {
    const [data, setData] = useState([]);  
    const [load, setLoaded] = useState(false);
    const [LoadStatus, setLoadStatus] = useState(null);

    async function loadData(){
       try {
        setLoadStatus(0); 
        setLoaded(false);
          const response = await axios.get(TABLEURL); 
          const rows = [];
          response.data.map((item, index)=>{ 
            rows.push({
                index:index+1, 
                date: moment(item.ed_auditory_registerDate).format("dddd, D [de] MMMM [de] YYYY [às] HH:mm"), 
                form:item.ed_auditory_form, 
                user:item.user_name, 
                description:item.ed_auditory_description, 
                action:item.ed_auditory_action,  
            })
          });  
          setData(rows);
          setTimeout(() => {
            setLoaded(true);
          }, 200);
          setLoadStatus(2); 
       } catch (error) {
        console.clear()
        console.log(error);
        setLoadStatus(1); 
       }
    };
    
    useEffect(()=>{ 
      loadData();
    },[]);
   
 
if(load){ 
  return (
    <div>
      <TableGrid
          TableHead={columns}
          TableBody={data} 
          TableTitle='Histórico de Logs'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
      />
  </div>
) 
}else{ 
  return (
    <div>
      <div className="d-none">*</div>
      <TableGrid
          TableHead={columns}
          TableBody={[]} 
          TableTitle='Histórico de Logs'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
      />
  </div>
) 
}
}


export default LogsHistoryTable
