import React from 'react'
import styled from 'styled-components';

function Profile_gn_skills({data}) {
  return (
    <Container>
        <h1 className="title">Hablidades</h1>
        <ul className="skills-area">
            {[1,2,3,4,5,6,7,8].map((item , index)=>{
                return(<li key={index+1}>Javascript  <div className="dot bg-blue ml-2"></div></li>)
            })}
        </ul> 
    </Container>
  )
}

const Container = styled.div`
    margin:10px 0px;

    .skills-area{
       display:flex;
       flex-wrap:wrap;
       margin:10px 0px;
       padding:0px;
       margin-bottom:30px;

        li{
             border:1px solid var(--ed-silver-light);
             padding:10px 20px;
             border-radius:30px;
             margin-right:10px;
             margin-top:10px;
             display:flex;
             align-items:center;

              .dot{
                  width:10px;
                  height:10px;
                  border-radius:100%;
              }
        }
    }
`;



export default Profile_gn_skills
