import React, { useState, useEffect, useImperativeHandle, forwardRef } from "react";
import axios from "axios";
import { Avatar, Button } from "@mui/material";
import { Badge } from "react-bootstrap";
import { PiMicrosoftExcelLogoDuotone } from "react-icons/pi";
import Hoot from "../../../General/components/Hoot";
import SwitchFromPages from "../../../General/components/SwitchFromPages";
import TableGrid from "../../../General/components/TableGrid";
import ExportDataForTablesExcel from "../../../General/components/ExportDataForTablesExcel";
import NewfeeManualPaymentModal from "../modal/NewfeeManualPaymentModal";
import styled from "styled-components";
import EmptyImage from '../../../Assets/images/svg/personal_info.svg';

const TABLEURL = Hoot() + "eduallGetAllClassfeepaymentsStatus/get/";

const ListDebts = forwardRef((props, ref) => {
    const [data, setData] = useState([]);
    const [months, setMonths] = useState([]);
    const [loading, setLoading] = useState(false);

    async function loadData(classId) {
        if (!classId) return;
        setLoading(true);

        try {
            const response = await axios.get(TABLEURL + classId);
            if (response.data && response.data.length > 0) {
                const classData = response.data[0];
                if (classData.students?.length > 0) {
                    setData(classData.students);
                    if (classData.students[0].months) {
                        setMonths(classData.students[0].months);
                    }
                }
            }
        } catch (error) {
            console.error("Erro ao carregar propinas da turma:", error);
        } finally {
            setLoading(false);
        }
    }

    useEffect(() => {
        if (props.Class) {
            loadData(props.Class);
        }
    }, [props.Class]);

 
  useImperativeHandle(ref, () => ({
    loadData: () => loadData(props.Class)
  }));
 

    if (loading) {
        return (
              <div className="mt-4">
                <Container>
                     <h4 className="title">Carregando informações...</h4>
                </Container>
            </div> 
        );
    }

    if (data.length === 0) {
        return (
            <div className="mt-4">
                <Container>
                     <h5>Nenhum estudante encontrado nesta turma.</h5>
                </Container>
            </div>
        );
    }

    // Definição das colunas
    const columns = [
        {
            field: "student",
            headerName: "Nome do estudante",
            width: 320,
            resizable: true,
            cellRenderer: (props) => (
                <SwitchFromPages
                    link={`studentinfo/${props.data.id}`}
                    menu="3"
                    menu_item="17"
                    toggle_btn={
                        <div className="ed-flex">
                            <Avatar
                                className="df"
                                alt={props.data.student}
                                src={props.data.picture && props.data.picture !== "#" ? Hoot() + props.data.picture : ""}
                            />
                            <span className="ml-2">{props.data.student}</span>
                        </div>
                    }
                />
            ),
        },
    ];

    months.forEach((month, mIndex) => {
        columns.push({
            field: `month_${mIndex}`,
            headerName: month.month,
            width: 200,
            resizable: true,
            cellRenderer: (props) => {
                const value = props.value?.toLowerCase();
                if (value === "paid") return <Badge bg="success" className="col-lg-12">Propina paga</Badge>;
                if (value === "notpaid") {
                    return (
                        <div className="ed-flex col">
                            <Badge bg="warning" className="col-lg-12 mb-1">Propina não paga</Badge>
                        </div>
                    );
                }
                return <Badge bg="secondary" className="col-lg-12">Outro</Badge>;
            },
        });
    });

    // Definição das linhas
    const rows = data.map((student) => {
        const row = {
            id: student.id,
            student: student.name,
            picture: student.picture,
        };
        student.months?.forEach((item, i) => {
            row[`month_${i}`] = item.status;
        });
        return row;
    });

    return (
        <div className="mt-4" id="fee-payments-debts">
            <TableGrid
                TableHead={columns}
                TableBody={rows}
                TableHeight={650}
                TableTitle="Listar propinas em atraso"
                TableBtn={
                    <div className="ed-flex">
                        <button
                            className="btn-icon btn ml-2 btn-export-data"
                            onClick={() =>
                                ExportDataForTablesExcel(
                                    "Pagamentos de propinas em atraso",
                                    ["Ação"],
                                    "fee-payments-debts"
                                )
                            }
                        >
                            <PiMicrosoftExcelLogoDuotone />
                        </button>
                        <div className="ml-2">
                            <NewfeeManualPaymentModal />
                        </div>
                    </div>
                }
            />
        </div>
    );
});


const Container = styled.section`
    padding:20px;
    background:var(--ed-white);  
    box-shadow:var(--ed-shadow-df); 
    border-radius:6px;

    .empty-search{
        display:flex;
        align-items:center;
        justify-content:center;
        height:100%;
        min-height:440px; 
        img{
             max-width:600px;
             max-height:300px;
        }
   } 
`;

export default ListDebts;



 