import React, { useState } from 'react'

function CommentAnswer({}) {
 const [ToggleInput, setToggleInput] =  useState(false);

  return (
    <div className='comment-asnwer-input col'>
        <div className='cursor-poiter' onClick={()=>setToggleInput(ToggleInput === true ? false : true)} > <span>(0) responder</span></div>
        {ToggleInput === true ?
         <div className="ml-2 col ed-flex">
             <input type="text" placeholder='Fale algo legal...' className="form-control col" />
          </div>
        : <></>} 
    </div>
  )
}

export default CommentAnswer