import React ,{useState, useEffect} from 'react'
import Table from './Table'
import { Delete, Description, Edit ,OpenInBrowser, Refresh } from '@mui/icons-material';
import { Link } from 'react-router-dom';
import axios from 'axios'
import Hoot from '../../../General/components/Hoot'; 
import DeleteModal from '../elements/DeleteModal';
import NewSubject from '../modal/NewSubject';
import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton'; 
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';

const TABLEURL = Hoot()+"eduallgetfaculties/get/" 
 

const columns = [ 
  { 
   field: 'index',
   headerName: 'Nº', 
   width: 90 , 
   resizable: true,
  },
  { 
      field: 'title',
      headerName: 'Nome da faculdade',  
      resizable: true,
  },     
  {
    field: 'action',
    headerName: 'Ação',  
     resizable: true, 
     cellRenderer:(props) => { 
      return  <div className="ed-flex">
      <NewSubject title='Atualizar ' update='true' get={Hoot()+`eduallgetsinglefaculty/get/${props.data.id}`}  
        url={Hoot()+`eduallfacultyupdate/update/${props.data.id}`}  
          toggle_btn={
           <button subject-code={props.data.id} className="btn-circle bg-success text-light">
                 <Edit/>
            </button> 
          }
      />
    <DeleteModal title={'esta faculdade'} url={Hoot()+`eduallfacultydelete/delete/${props.data.id}`} message={'Faculdade deletada com sucesso'} toggle_btn={ 
     <button  className="btn-circle bg-danger ml-2 text-light">
         <Delete/>
     </button>} /> 
   </div>;
    }
  } 
];
function FacultiesTable() {
    const [data, setData] = useState([]);
    const [data1, setData1] = useState([]);
    const [load, setLoaded] = useState(false);
    const [LoadStatus, setLoadStatus] = useState(null);
  
    async function loadData(){
        try {
          setLoadStatus(0);
        setLoaded(false); 
        const response = await axios.get(TABLEURL); 
        const rows = [];
        const rows1 = [];
        response.data.map((item, index)=>{  
          rows.push({
            index:index+1,
            id:item.ed_faculty_id,   
            title:item.ed_faculty_title,    
            action:'',  
        }) 
        rows1.push({
          index:index+1,  
          title:item.ed_faculty_title,     
      }) 
      });
        setData(rows);
        setData1(rows1);
        setTimeout(() => {
          setLoaded(true); 
        }, 200);
        setLoadStatus(2);
        } catch (error) {
          setLoadStatus(1);
        }
    }
  
    useEffect(()=>{
        loadData(); 
    },[]);
    
  
  
  if(load){
      return (
      <div id="ed-custom-table-data">
        <TableGrid
            TableHead={columns}
            TableBody={data} 
            TableTitle={'Faculdades'} 
            TableBtn={
              <div className='ed-flex' >
              <button id='ed-custom-table-data-btn'
                onClick={() =>
                  ExportDataToTablesToPdf({
                    fileName: "Lista das Faculdades",
                    headerId: null,
                    contentId: "ed-custom-table-data",
                    footerId: null,
                    rotation: "portrait",
                    buttonId: "ed-custom-table-data-btn",
                    customHeader: "Lista das Faculdades",
                    excludedColumns: ["Ação", "Nº"]
                  })
                }
                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
              </button> 
              <button className='btn-icon btn btn-export-data ml-2'
                onClick={() => ExportDataForTablesExcel("Cursos ", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
              </button>
            <RefreshButton action={loadData} status={LoadStatus} />
            </div>
            }
        />
    </div>
    )
  }else{
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
            TableHead={columns}
            TableBody={data} 
            TableTitle={'Faculdades'}
            TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
    </div>
    )
  } 
}

export default FacultiesTable