import React, { useState } from 'react'
import Hoot from '../General/components/Hoot'
import styled from 'styled-components';
import UserGeneralSettings from './SettingsComponents/UserGeneralSettings';
import LogoItem from './Components/LogoItem';
import {AiOutlineUser} from "react-icons/ai";
import { RiLockPasswordLine } from "react-icons/ri";
import { HiOutlineAcademicCap } from "react-icons/hi2";
import { MdOutlineSportsBasketball } from "react-icons/md";
import { LiaCubeSolid } from "react-icons/lia";
import { TbFileCertificate } from "react-icons/tb";
import { BiCertification } from "react-icons/bi";
import { GoProjectTemplate } from "react-icons/go";
import { GiMuscleFat } from "react-icons/gi";
import UserSecuritySettings from './SettingsComponents/UserSecuritySettings';


function UserSettings({}) {
const [ActiveTab, setActiveTab] = useState(1);
const DATA_URL = [
     Hoot()+"eduallchangecurrentuserpassword",
     Hoot()+"",
     Hoot()+"",
];


const Menus = [
   {title:"Informações do usuário", icon:<AiOutlineUser/>, code:1},
   {title:"Segurança da conta", icon:<RiLockPasswordLine/>, code:2},
   {title:"Dados académicos", icon:<HiOutlineAcademicCap/>, code:3},
   {title:"Hobies", icon:<MdOutlineSportsBasketball />, code:4},
   {title:"Hablidades", icon:<LiaCubeSolid/>, code:5},
   {title:"Qualificações profissionais", icon:<TbFileCertificate/>, code:6},
   {title:"Formação academica", icon:<BiCertification/>, code:7},
   {title:"Portofolio", icon:<GoProjectTemplate />, code:8},
   {title:"Experiencia profissional", icon:<GiMuscleFat />, code:9}, 
];



  return (
     <Container>
          <div className="sidebar-settings">
               <div className="side-header">
                    <div className="ed-flex">
                       <LogoItem /><h3>Definições</h3>
                    </div>
               </div>
               <ul>
                  {Menus.map((item, index)=>{
                     return(<li className={item.code === ActiveTab ? "active" : ""} onClick={()=>setActiveTab(item.code)} key={index}>{item.icon} {item.title}</li>);
                  })}
               </ul>
          </div>
          <div className="settings-content">
               <div className="ed-wrapper">
                    <section className={ActiveTab === 1 ? "active" : "d-none"}>
                       <UserGeneralSettings />
                    </section>
                    <section className={ActiveTab === 2 ? "active" : "d-none"}>
                       <UserSecuritySettings />
                    </section>  
               </div>
          </div>
     </Container>
  );
}


const Container = styled.div`
   display:flex;
   width:100%;9201956490
   height:100vh;
   background:var(--ed-background-color);

   .dot{
      background:var(--ed-silver);
      border:1px solid var(--ed-grey);
      width:12px;
      height:12px;
      border-radius:100%;
      margin-left:8px;
   }
   
   .container-box{
      padding:20px;
      background: var(--ed-white);
      box-shadow:var(--ed-shadow-df);
      border-radius:6px;
   }

   .react-tel-input{ 

        .form-control{
           width:100% !important;
        }
   }


   .sidebar-settings{
      min-width:350px;
      height:100vh;
      background: var(--ed-white);
      box-shadow:var(--ed-shadow-df);
   }


   .settings-content{
      padding:20px;
      width:100%;
      height:100%;
      max-height:100vh;
      overflow-y:auto;
    }

    .side-header{
        padding:20px;
         
        h3{
           font-size:23px;
           margin:0px;
           margin-left:15px;
           font-weight:bolder;
         }
    }


    ul{
       margin:20px 0px;
       padding:0px 20px;

          li{
              padding:10px; 
              margin:10px 0px;
              list-style:none;
              cursor:pointer;
              position:relative;
              border-left:10px;

                 svg{
                    width:22px;
                    height:22px;
                    margin-right:10px;
                 }
          }

          

        li.active{
         border-left:6px solid var(--ed-purple-light);
         color:var(--ed-purple-light);

           svg{
                color:var(--ed-purple-light);
           }
       }


    }



`;



export default UserSettings




