import React, { useEffect, useState } from 'react'
import { Link } from 'react-router-dom'
import Hoot from '../../../General/components/Hoot'
import axios from 'axios'
import { GetAuthorName, GetBookCategoryTitle, GetBookPublisherName, GetTypeOfBookTitle } from '../../../General/components/InstituteData';
import DeleteModal from '../elements/DeleteModal';
import { Delete, Edit, Refresh } from '@mui/icons-material';
import Table from './Table';
import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import NewBookEditModal from '../modal/NewBookEditModal';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';

const TABLEURL = Hoot() + `edualllibrarybooks/get`;

const columns = [
  {
    field: 'index',
    headerName: 'Nº',
    width: 90,
    resizable: true,
  },
  {
    field: 'title',
    headerName: 'Nome do livro',
    resizable: true,
    width: 350,
    cellRenderer: (props) => {
      return <>
        <div className="ed-flex">
          <div className='tableImg'>
            <img loading="lazy" role="presentation" src={props.data.picture !== "" ? Hoot() + props.data.picture : "#"} alt="#" />
          </div>
          {props.data.title}
        </div>
      </>
    }
  },
  {
    field: 'author',
    headerName: 'Autor',
    resizable: true,
  },
  {
    field: 'type',
    headerName: 'Tipo de livro',
    resizable: true,
    width: 150,
  },
  {
    field: 'category',
    headerName: 'Cátegoria',
    resizable: true,
  },
  {
    field: 'date',
    headerName: 'Data de aquisição',
    resizable: true,
  },
  {
    field: 'publisher',
    headerName: 'Editora',
    resizable: true,
  },
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true,
    cellRenderer: (props) => {
      return <div className="ed-flex">
        <NewBookEditModal title='Atualizar ' update='true' get={Hoot() + `eduallsinglelibrarybook/get/${props.data.id}`}
          url={Hoot() + `edualllibrarybookupdate/update/${props.data.id}`} toggle_btn={
            <button className="btn-circle bg-success text-light">
              <Edit />
            </button>
          } />
        <DeleteModal title='este livro' url={Hoot() + `edualllibrarybookdelete/delete/${props.data.id}`}
          message='Livro deletado com sucesso' toggle_btn={
            <button className="btn-circle bg-danger ml-2">
              <Delete />
            </button>
          } />
      </div>
    }
  }
];

function BooksListTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData() {
    try {
      setLoadStatus(0);
      setLoaded(false);
      const response = await axios.get(TABLEURL);
      const rows = [];
      response.data.map((item, index) => {
        rows.push({
          index: index + 1,
          id: item.ed_library_book_id,
          picture: item.ed_library_book_picture,
          title: item.ed_library_book_title,
          author: item.ed_library_author_name,
          type: item.ed_library_typeofbook_title,
          category: item.ed_library_category_title,
          date: item.ed_library_book_acquisition_date,
          publisher: item.ed_library_publisher_name,
          action: ""
        });
      });
      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoadStatus(1);
    }
  }

  useEffect(() => {
    loadData();
  }, []);




  if (load) {
    return (
      <div id="ed-custom-table-data" >
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista dos livros'
          TableBtn={
            <div className='ed-flex'>
              <button id='ed-custom-table-data-btn'
                onClick={() =>
                  ExportDataToTablesToPdf({
                    fileName: "Lista dos livros",
                    headerId: null,
                    contentId: "ed-custom-table-data",
                    footerId: null,
                    rotation: "landscape",
                    buttonId: "ed-custom-table-data-btn",
                    customHeader: "Lista dos livros",
                    excludedColumns: ["Ação"]
                  })
                }
                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
              </button>
              <button className='btn-icon btn btn-export-data ml-2'
                onClick={() => ExportDataForTablesExcel("Lista dos livros", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
              </button>
              <RefreshButton action={loadData} status={LoadStatus} />
            </div>
          }
        />
      </div>
    )
  } else {
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={[]}
          TableTitle='Lista dos livros'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    )
  }

}

export default BooksListTable