import React, { useState, useRef } from 'react'
import { Modal, Form, Button } from 'react-bootstrap'
import AddCommentOutlined from '@mui/icons-material/AddCommentOutlined';
import { Save, Update } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import { toast } from 'react-hot-toast';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import FileUpload from '../../../General/components/FileUpload';
import styled from 'styled-components';
import { LuBug } from "react-icons/lu";
import { Alert } from 'react-bootstrap';

function ReportFeedbackModal(props) {
    const [show, setShow] = useState(false);
    const [showBox, setShowBox] = useState(false);
    const [form, setForm] = useState({});
    const [errors, setErrors] = useState({});
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [Docfile, setDocfile] = useState(false);
    const [Files, setFiles] = useState([]);
    const ChildRef = useRef();

    const handleClose = () => {
        setShowBox(false);
        setTimeout(() => setShow(false), 1200);
    };

    const handleShow = () => {
        setShowBox(true);
        setShow(true);
    };

    const setField = (field, value) => {
        setForm({
            ...form,
            [field]: value
        });

        if (!!errors[field]) {
            setErrors({
                ...errors,
                [field]: null
            });
        }
    };

    const validateForm = () => {
        const { type, description } = form;
        const NewErrors = {};
        setRegisterStatus(0);

        if (!type) NewErrors.type = 'Selecione o tipo';
        if (!description || description.trim() === '') NewErrors.description = 'Descrição inválida';

        return NewErrors;
    };

    const FormSubmit = (e) => {
        e.preventDefault();
        const formErrors = validateForm();
        if (Object.keys(formErrors).length > 0) {
            setErrors(formErrors);
            toast.error("Verifique todos os campos");
            setRegisterStatus(1);
        } else {
            const SUBMIT_INPUTS = new FormData();
            SUBMIT_INPUTS.append("type", form.type);
            SUBMIT_INPUTS.append("description", form.description);
            Files.forEach((file, i) => {
                SUBMIT_INPUTS.append("files", file);
            });

            axios.post(Hoot() + "edualldebugfeedback/post/", SUBMIT_INPUTS, {
                headers: { "Content-Type": "multipart/form-data" }
            }).then(() => {
                toast.success("👍 Obrigado! O seu feedback foi recebido com sucesso.");
                setForm({});
                ClearInputs();
                setFiles([]);
                setDocfile(false);
                setRegisterStatus(2); 
            }).catch((error) => {
                setRegisterStatus(1);
                const msg = error?.response?.data?.msg || "Erro ao enviar feedback";
                toast.error(msg);
            });
        }
    };

    const handleInput = (e) => {
        switch (e.target.id) {
            case "feedback_type":
                setField("type", e.target.value);
                break;
            case "feedback_description":
                setField("description", e.target.value);
                break;
            default:
        }
    };

    const GetFiles = (files) => {
        setFiles(files);
    };

    const showBoxFile = () => {
        setDocfile(!Docfile);
    };

    return (
        <div>
            <div onClick={handleShow}>
                {props.toggle_btn ? props.toggle_btn :
                    <div>
                        <div className="ed-flex error-badge cursor-pointer grey-text">
                            <LuBug /> <span className="ml-1">Erros e Feedbacks</span>
                        </div>
                    </div>
                }
            </div>
            <Modal size='lg' className={showBox ? ModalAnimationShow() : ModalAnimationClose()}
                centered dialogAs={DraggableModal} show={show} onHide={handleClose}>
                <Modal.Header closeButton>
                    <Modal.Title>
                        <div className="ed-wrap align-center">
                            <UserOptionDropDown />
                            <h5>{props.title ? props.title : 'Reportar Erro / Feedback'}</h5>
                        </div>
                    </Modal.Title>
                </Modal.Header>
                <Form onSubmit={FormSubmit}>
                    <Modal.Body className='scrollLimit'>
                        <Alert variant="info" className="d-flex align-items-start">
                            <div>
                                <h6 className="fw-bold">👋 Bem-vindo ao painel de Feedback</h6>
                                <p className="mb-0">
                                    <small>
                                        Aqui você pode <strong>reportar erros encontrados no sistema</strong> ou
                                        <strong> sugerir novas funcionalidades</strong> que gostaria de ver na EDUALL. <br />
                                        Também é possível <strong>anexar imagens ou vídeos</strong> para ilustrar melhor seu feedback.
                                        Sua contribuição é muito importante para melhorar a plataforma!
                                    </small>
                                </p>
                            </div>
                        </Alert>


                        <Form.Group className="mb-3 mt-2">
                            <Form.Label>Tipo <span className="text-danger">*</span></Form.Label>
                            <Form.Select id="feedback_type" onChange={handleInput}
                                className={!!errors.type && 'is-invalid'} isInvalid={!!errors.type}>
                                <option value="">Selecione...</option>
                                <option value="error">Erro</option>
                                <option value="feedback">Feedback</option>
                            </Form.Select>
                            <Form.Control.Feedback type="invalid">{errors.type}</Form.Control.Feedback>
                        </Form.Group>

                        <Form.Group className="mb-3">
                            <Form.Label>Descrição <span className="text-danger">*</span></Form.Label>
                            <textarea className="form-control" id="feedback_description" rows={6}
                                onChange={handleInput}></textarea>
                            <Form.Control.Feedback type="invalid">{errors.description}</Form.Control.Feedback>
                        </Form.Group>

                        <BoxContainerBorder>
                            <h2 className="title">Carregar ficheiros</h2>
                            <FileUpload input_name="feedback_files" Icon="0"
                                type_of_files="image/x-png,image/jpeg,video/mp4,application/pdf"
                                extensions="pdf, docx, png, jpeg, jpg, mp4"
                                Files={GetFiles} ref={ChildRef} />
                        </BoxContainerBorder>
                    </Modal.Body>

                    <Modal.Footer>
                        <div className="ed-space">
                            <div className="ed-flex"></div>
                            <div className="ed-flex">
                                <Button className='bg-light text-dark' onClick={handleClose}>Cancelar</Button>
                                <SaveButton icon={<Save />} title={'Enviar'} status={RegisterStatus} />
                            </div>
                        </div>
                    </Modal.Footer>
                </Form>
            </Modal>
        </div>
    )
}



const BoxContainerBorder = styled.div`  
    width:auto;
    border-radius:6px;
    margin:10px 0;
    padding:20px;
    min-height:200px;
    background:var(--ed-white);  
    border:1px solid var(--ed-silver-light); 

    .ed-flex{
        margin-bottom:0px;
    }

    h2.title{
        font-size:18px; 
        text-transform:uppercase;
        font-weight:600;
        margin-top:10px;
        margin-bottom:25px;
    }
  
`;

export default ReportFeedbackModal;
