import React, { useEffect, useState } from 'react'
import ShedulerComponent from '../../../General/ShedulerComponent'
import { styled } from 'styled-components';
import {BsClock} from "react-icons/bs";
import ReplaceWord from '../../../General/components/ReplaceWord';



function PP_calendar(props) { 
   const [Timings , setTimings] = useState({day1:[],day2:[],day3:[],day4:[],day5:[],day6:[],day7:[]})
    
   const LoadData = async()=>{ 
      const Timings = {
           day1:[],day2:[],
           day3:[],day4:[],
           day5:[],day6:[],
           day7:[],
      };

      const getTime = (item)=>{
         return item.ed_timing_hour_start+":"+item.ed_timing_minute_start + "-"+item.ed_timing_hour_end+":"+item.ed_timing_minute_end;
      }
 
      props.data.map((item, index)=>{
         switch (item.ed_tch_timing_weekday*1) {
             case 0:
               Timings.day1.push({subject:item.ed_subject_title, class:item.ed_class_title, timing:getTime(item)})
              break; 
              case 1:
               Timings.day2.push({subject:item.ed_subject_title, class:item.ed_class_title, timing:getTime(item)})
              break; 
              case 2:
               Timings.day3.push({subject:item.ed_subject_title, class:item.ed_class_title, timing:getTime(item)})
              break; 
              case 3:
               Timings.day4.push({subject:item.ed_subject_title, class:item.ed_class_title, timing:getTime(item)})
              break; 
              case 4:
               Timings.day5.push({subject:item.ed_subject_title, class:item.ed_class_title, timing:getTime(item)})
              break; 
              case 5:
               Timings.day6.push({subject:item.ed_subject_title, class:item.ed_class_title, timing:getTime(item)})
              break; 
              case 6:
               Timings.day7.push({subject:item.ed_subject_title, class:item.ed_class_title, timing:getTime(item)})
              break; 
         default:
      } 
    }) 
    setTimings(Timings);  

    console.log(props.data);
   }


   useEffect(()=>{
      LoadData();
   },[]);

  return (
     <Container>
         <h1 className="title">Calendário de aulas</h1>
          <div className="content"> 
          <section className="weekdays">
                   <article className="week-item wh1"> 
                        <div className="week-header-title">Segunda-feira</div>
                        <div className="week-body">
                             <ul>
                              {Timings.day2.map((item, index)=>{
                                   return(
                                    <li key={index}>
                                        <div className="small-el-title">{ReplaceWord("Disciplina")} - {item.subject}</div>
                                        <small className="time ed-flex"><BsClock />{item.timing}</small>
                                     </li>
                                   )
                                })}   
                             </ul>
                        </div>
                   </article>
                   <article className="week-item wh2"> 
                        <div className="week-header-title">Terça-feira</div>
                        <div className="week-body">
                             <ul>
                               {Timings.day3.map((item, index)=>{
                                   return(
                                    <li key={index}>
                                        <div className="small-el-title">{ReplaceWord("Disciplina")} - {item.subject}  </div>
                                        <small className="time ed-flex"><BsClock />{item.timing}</small>
                                     </li>
                                   )
                                })} 
                             </ul>
                        </div>
                   </article>
                   <article className="week-item wh3"> 
                        <div className="week-header-title">Quarta-feira</div>
                        <div className="week-body">
                             <ul>
                             {Timings.day4.map((item, index)=>{
                                   return(
                                    <li key={index}>
                                        <div className="small-el-title">{ReplaceWord("Disciplina")} - {item.subject}</div>
                                        <small className="time ed-flex"><BsClock />{item.timing}</small>
                                     </li>
                                   )
                                })} 
                             </ul>
                        </div>
                   </article>
                   <article className="week-item wh4"> 
                        <div className="week-header-title">Quinta-feira</div>
                        <div className="week-body">
                             <ul>
                             {Timings.day5.map((item, index)=>{
                                   return(
                                    <li key={index}>
                                        <div className="small-el-title">{ReplaceWord("Disciplina")} - {item.subject}</div>
                                        <small className="time ed-flex"><BsClock />{item.timing}</small>
                                     </li>
                                   )
                                })} 
                             </ul>
                        </div>
                   </article>
                   <article className="week-item wh5"> 
                        <div className="week-header-title">Sexta-feira</div>
                        <div className="week-body">
                             <ul>
                             {Timings.day6.map((item, index)=>{
                                   return(
                                    <li key={index}>
                                        <div className="small-el-title">{ReplaceWord("Disciplina")} - {item.subject}</div>
                                        <small className="time ed-flex"><BsClock />{item.timing}</small>
                                     </li>
                                   )
                                })} 
                             </ul>
                        </div>
                   </article>
                   <article className="week-item wh6"> 
                        <div className="week-header-title">Sabado</div>
                        <div className="week-body">
                             <ul>
                             {Timings.day7.map((item, index)=>{
                                   return(
                                    <li key={index}>
                                        <div className="small-el-title">{ReplaceWord("Disciplina")} - {item.subject}</div>
                                        <small className="time ed-flex"><BsClock />{item.timing}</small>
                                     </li>
                                   )
                                })} 
                             </ul>
                        </div>
                   </article>
                   <article className="week-item wh7"> 
                        <div className="week-header-title">Domingo</div>
                        <div className="week-body">
                             <ul>
                               {Timings.day1.map((item, index)=>{
                                   return(
                                    <li key={index}>
                                        <div className="small-el-title">{ReplaceWord("Disciplina")} - {item.subject}</div>
                                        <small className="time ed-flex"><BsClock />{item.timing}</small>
                                     </li>
                                   )
                                })} 
                             </ul>
                        </div>
                   </article>
              </section>
            <div className="custom-portal-calendar">
              <ShedulerComponent data={props.data  ? props.data : []} />
            </div>
          </div>
     </Container>
  )
}


const Container = styled.div` 
  width:100%;
  background:var(--ed-white); 
  border-radius:6px; 
  box-shadow:var(--ed-shadow-df);
  padding:20px;

   .content{
     display:flex; 
     margin-top:20px; 


      .weekdays{
          min-width:250px; 
          border-left:1px solid var(--ed-silver-light);
          padding-right:20px;
          padding-left:9px;
          margin-right:20px;
          max-height:520px;
          overflow-y:auto;

          &::-webkit-scrollbar{
            width:6px !important;
            background-color:transparent !important;
          }
          
          &::-webkit-scrollbar-thumb{
              background:rgb(219, 219, 219) !important; 
          } 


            .week-item{
                position:relative; 
                margin-top:20px;

                  &:after{
                     position:absolute;
                     left:0px;
                     top:9px; 
                     content:"";
                     width:30px;
                     height:1px;
                     background:var(--ed-silver-light);
                  }

                  &:before{
                    position:absolute;
                    left:-10px;
                    top:-1px; 
                    content:"";
                    width:20px;
                    height:20px;
                    border-radius:100%; 
                    border:2px solid var(--ed-white);
                    box-shadow:var(--ed-shadow-1);
                    z-index:100;
                 }
                  
                  .week-header-title{
                    padding-left:35px;
                  }

               .week-body{
                  ul{
                    padding:0px; 
                      
                     li{
                        margin:15px 0px;
                        list-style:none;
                        border-bottom:1px solid var(--ed-silver-light);
                        padding-bottom:10px;
                        padding-left:10px; 

                          .small-el-title{
                              font-size:14px;
                              color:var(--ed-grey-text);   
                          }

                          .time{
                              font-size:13px;
                              margin-top:5px;

                              svg{
                                  margin-right:5px;
                              }
                          }


                     }
                  }
               }  
            }

            .week-item.wh1{&:before{background:var(--ed-orange);}}
            .week-item.wh2{&:before{background:var(--ed-green);}}
            .week-item.wh3{&:before{background:var(--ed-blue);}}
            .week-item.wh4{&:before{background:var(--ed-purple-light);}}
            .week-item.wh5{&:before{background:var(--ed-red);}}
            .week-item.wh6{&:before{background:var(--ed-brown);}}
            .week-item.wh7{&:before{background:var(--ed-gold);}} 

      } 
   }
`;

export default PP_calendar
