 import React, { useState, useEffect, useImperativeHandle, forwardRef } from "react";
import axios from "axios";
import { Badge, Button } from "react-bootstrap";
import { Avatar } from "@mui/material";
import { Link } from "react-router-dom";
import Hoot from "../../../General/components/Hoot";
import SwitchFromPages from "../../../General/components/SwitchFromPages";
import TableGrid from "../../../General/components/TableGrid";
import ExportDataForTablesExcel from "../../../General/components/ExportDataForTablesExcel";
import NewTransportPaymentsModal from "../modal/NewTransportPaymentsModal";
import { PiMicrosoftExcelLogoDuotone } from "react-icons/pi";
import styled from "styled-components";

const TABLEURL = Hoot() + "eduallGetAllClasstransportaymentsStatus/get/";

const ListTransportsDebts = forwardRef((props, ref) => {
  const [data, setData] = useState([]);
  const [months, setMonths] = useState([]);
  const [loading, setLoading] = useState(false);

  const CurrentTab = props.CurrentMenu || 0;

  const loadData = async (classId) => {
    if (!classId) return;
    setLoading(true);

    try {
      const response = await axios.get(TABLEURL + classId);
      const resData = response.data;

      if (resData.students?.length > 0) {
        setData(resData.students);
        setMonths(resData.students[0].months || []);
      } else {
        setData([]);
        setMonths([]);
      }
    } catch (error) {
      console.error("Erro ao carregar dados de transporte:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData(props.Class);
  }, [props.Class]);

  useImperativeHandle(ref, () => ({
    reload: () => loadData(props.Class),
  }));


    useImperativeHandle(ref, () => ({
      loadData: () => loadData(props.Class)
    }));

    if (loading) {
        return (
              <div className="mt-4">
                <Container>
                     <h4 className="title">Carregando informações...</h4>
                </Container>
            </div> 
        );
    }

    if (data.length === 0) {
        return (
            <div className="mt-4">
                <Container>
                      <h5>Nenhum estudante encontrado nesta turma.</h5>
                </Container>
            </div>
        );
    }

 

  // Definição das colunas
  const columns = [
    {
      field: "student",
      headerName: "Nome do estudante",
      width: 320,
      resizable: true,
        cellRenderer: (props) => (
                <SwitchFromPages
                    link={`studentinfo/${props.data.id}`}
                    menu="3"
                    menu_item="17"
                    toggle_btn={
                        <div className="ed-flex">
                            <Avatar
                                className="df"
                                alt={props.data.student}
                                src={props.data.picture && props.data.picture !== "#" ? Hoot() + props.data.picture : ""}
                            />
                            <span className="ml-2">{props.data.student}</span>
                        </div>
                    }
                />
            ),
    },
  ];

  months.forEach((month, mIndex) => {
    columns.push({
      field: `month_${mIndex}`,
      headerName: month.month,
      width: 220,
      resizable: true,
      cellRenderer: (props) => {
        const value = props.value?.toLowerCase();
        switch (value) {
          case "paid":
            return <Badge bg="success" className="col-lg-12">Propina paga</Badge>;
          case "notpaid":
            return (
              <div className="ed-flex col">
                <Badge bg="warning" className="col-lg-12 mb-1">Propina não paga</Badge> 
              </div>
            );
          case "null":
            return <Badge bg="danger" className="col-lg-12">Pagamento anulado</Badge>;
          default:
            return <Badge bg="secondary" className="col-lg-12">Outro</Badge>;
        }
      },
    });
  });

  // Definição das linhas
  const rows = data.map((student) => {
    const row = { id: student.id, student: student.name, picture:student.picture };
    student.months?.forEach((item, i) => {
      row[`month_${i}`] = item.status;
    });
    return row;
  });

  return (
    <div className="mt-4" id="transport-payments-debts">
      <TableGrid
        TableHead={columns}
        TableBody={rows}
        TableHeight={650}
        TableTitle="Listar Pagamentos do transporte em atraso"
        TableBtn={
          <div className="ed-flex"> 
            <button
              className="btn-icon btn btn-export-data ml-2"
              onClick={() =>
                ExportDataForTablesExcel(
                  "Pagamentos de transporte em atraso",
                  ["Ação"],
                  "transport-payments-debts"
                )
              }
            >
              <PiMicrosoftExcelLogoDuotone />
            </button> 
            <div className="ml-2">
              <NewTransportPaymentsModal />
            </div>
          </div>
        }
      /> 
    </div>
  );
});


const Container = styled.section`
    padding:20px;
    background:var(--ed-white);  
    box-shadow:var(--ed-shadow-df); 
    border-radius:6px;

    .empty-search{
        display:flex;
        align-items:center;
        justify-content:center;
        height:100%;
        min-height:440px; 
        img{
             max-width:600px;
             max-height:300px;
        }
   } 
`;

export default ListTransportsDebts;
