import React, { useState, useEffect } from 'react';
import Alert from 'react-bootstrap/Alert';
import Form from 'react-bootstrap/Form'
import styled from "styled-components";
import logo from '../Assets/images/logo-small-white.png';
import { Link } from 'react-router-dom';
import MainAuthScreen from './MainAuthScreen';
import Hoot from '../General/components/Hoot';
import axios from 'axios';
import SaveButton from '../Dashboard/components/elements/SaveButton';
import { useHistory } from 'react-router-dom';
import jwt_decode from 'jwt-decode';
import { WarningOutline } from 'react-ionicons'

const ForgotPassword = () => {
  document.title = "Resetar senha";
  const [messageWarning, setMessagewarning] = useState(null);
  const [show, setShow] = useState(true);
  const [ed_email, setEd_email] = useState(null);
  const [switchuser, SetSwitchUser] = useState(false);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [LatestLoggedinUsers, SetLatestLoggedinUsers] = useState([]);
  const [MessageType, setMessageType] = useState(1);
  const navigate = useHistory();

  function hideMessage() {
    setMessagewarning(null);
    setShow(false);
  }



  useEffect(() => {
    CheckLogin();
  }, []);



  const CheckLogin = async () => {
    try {
      const response = await axios.get(Hoot() + 'token');
      const decoded = jwt_decode(response.data.accessToken);

      if (decoded.cr_usertype !== null) {
        console.clear();
        console.log(decoded);
        if (decoded.cr_usertype === 1) {
          navigate.push("/WorkSpaces");
        } else {
          navigate.push('/dashboard');
        }
      } else {
        setRegisterStatus(1);
      }
    } catch (e) {
      console.log(e);
      localStorage.removeItem("CurrentTab");
      localStorage.removeItem("CurrentPage");
    }
  }



  const ResetPassword = async () => {
    setRegisterStatus(0);
    setMessagewarning(null);
    try {
      if (ed_email === null) {
        setMessagewarning("Preencha corretamente os campos !");
        setRegisterStatus(1);
      } else {
        await axios.post(Hoot() + 'eduallpasswordreset', { ed_user_email: ed_email }).then((e) => {
          setRegisterStatus(2);
          setMessagewarning("Verifique a sua caixa de correio !");
          setMessageType(2);
        }).catch((error) => {
          setRegisterStatus(1);
          console.clear();
          console.log(error);
          if (error.response.data) {
            setRegisterStatus(1);
            setMessagewarning(error.response.data.msg);
          } else {
            setRegisterStatus(1);
            setMessagewarning('Não foi possível concluir a operação. Tente novamente em instantes !');
          }
        });
      }
    } catch (error) {
      console.clear();
      console.log(error);
      if (error.response) {
        if (error.response.data) {
          setRegisterStatus(1);
          setMessagewarning(error.response.data.msg);
          console.log(error);
        } else {
          setRegisterStatus(1);
          setMessagewarning('Não foi possível concluir a operação. Tente novamente em instantes !');
          console.log(error);
        }
      } else {
        console.log(error)
        setRegisterStatus(1);
        setMessagewarning("Não foi possível concluir a operação neste momento !");
      }
    }
  }

  const Reset = async (e) => {
    e.preventDefault();
    ResetPassword();
  }



  const handleInput = (e) => {
    switch (e.target.id) {
      case "ed_user_account_email":
        setEd_email(e.target.value);
        break;
      default:
    }
  }


  return (

    <MainAuthScreen content={
      <div>
        <section>
          <div className="form-area nav-theme">
            <h1 className="theme-light-txt">Resetar</h1>
            <p >Digite o seu email e nos enviaremos um link de recuperação para o seu correio eletronico.</p>
            <div className="form-message">
              {
                messageWarning !== null ? <Alert dismissible variant={MessageType === 1 ? "danger" : 'success'} onClose={() => hideMessage()}>
                  {MessageType === 1 ?
                    <div className={MessageType === 1 ? "ed-flex text-danger" : 'ed-flex text-success'} ><WarningOutline color={MessageType === 1 ? "red" : 'green'} /><h5 className={MessageType === 1 ? "text-danger" : 'text-success'} > {messageWarning} </h5></div> :
                    <div className={MessageType === 1 ? "ed-flex text-danger" : 'ed-flex text-success'}><WarningOutline color={MessageType === 1 ? "red" : 'green'} /><h5 className={MessageType === 1 ? "text-danger" : 'text-success'} > {messageWarning} </h5></div>}
                </Alert> : ''
              }
            </div>
            <Form onSubmit={Reset} >
              <Form.Group className="mb-3" >
                <Form.Label className="theme-light-txt" >Email</Form.Label>
                <Form.Control onChange={handleInput} value={ed_email} id="ed_user_account_email" type="email" className='mb-2' required placeholder="Digite o seu email" />
              </Form.Group>
              <SaveButton class='btn mt-2 col-lg-12 bg-main text-light' title={'Enviar'} status={RegisterStatus} />
              <br />
              <div className="d-flex">
                <small className="ed-flex theme-light-txt">
                  Não tem uma conta ?<Link to='/signup' className='text-main ml-2'>Cadastre-se</Link>
                </small>
              </div>
            </Form>
          </div>
        </section>
      </div>
    } />


  );

}



export default ForgotPassword;