import React, {useEffect, useState} from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import {Modal, Form, Button} from 'react-bootstrap'
import { Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal'; 
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import ClearInputs from '../../../General/components/ClearInputs'; 
import {GetInstituteCode, VehiclesDataOptions} from '../../../General/components/InstituteData'; 
import { RichTextEditor } from '../../../General/components/RichTextEditor';
import CRValue from '../../../General/components/CRValue';
import {toast} from 'react-hot-toast';
import { Update } from '@material-ui/icons';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import RefreshList from '../../../General/components/RefreshList';


function NewMaintenenceModal(props) {
    const [show, setShow] = useState(false);
    const [form, setForm] = useState({});
    const [errors, setErrors] = useState({});  
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [Founded, SetFounded] = useState(null);
       
    const [showBox, SetshowBox]  = useState(false);
    const handleClose = () => {
      SetshowBox(false);
      setTimeout(() => {
        setShow(false);
      }, 1200);
    } 

    const handleShow = () => {
          SetshowBox(true);
          setShow(true);  
          setTimeout(() => {  
            GET_DATA(); 
         }, 1000);   
    };

     
    const INPUTS = {
         maintenence_vehicle:CRValue("#maintenence_vehicle"),  
         maintenence_description:CRValue(".modal #maintenence_description"),
         maintenence_status:CRValue("#maintenence_status"),
    }; 

    const FORMURL = [
      Hoot()+"edualltransportmaintenanceeregister/post/",
      props.get ? props.get : '',
      props.url ? props.url : ''
    ];

    const GET_DATA = async()=>{
    if (props.update){
      try {
        const response = await axios.get(FORMURL[1]); 
        if(response.data.length > 0){ 

          console.clear();
          console.log(response.data[0]);
          const CurrentData = response.data[0]; 

          
            INPUTS.maintenence_description = CurrentData.ed_transport_maintenance_description; 
            INPUTS.maintenence_vehicle = CurrentData.ed_transport_maintenance_vehicle; 
            INPUTS.maintenence_status = CurrentData.ed_transport_maintenance_status;   

            setField("maintenence_status", CurrentData.ed_transport_maintenance_status);
            setField("maintenence_vehicle", CurrentData.ed_transport_maintenance_vehicle);
            setField("maintenence_description", CurrentData.ed_transport_maintenance_description);

            setTimeout(() => {
                 console.log("##################### DATABASE #######################");
                 console.log(INPUTS);
            }, 2000);
  
        }else {
           toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
        }
      } catch (error) {
          toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
      }
    }
  }

    const setField = (field, value)  =>{
      setForm({
          ...form,
          [field]:value
      })
  
      if(!!errors[field]){
           setErrors({
              ...errors,
              [field]:null
           });  
      }
  }
   

    const validateForm = ()=>{
      const {maintenence_vehicle , maintenence_status} = form; 
      const NewErrors = {};
      setRegisterStatus(0);  

      if (INPUTS.maintenence_status === "" || INPUTS.maintenence_status === " ") {
      if (!maintenence_status || maintenence_status === '') NewErrors.maintenence_status = 'Estado invalido !';
      } else { if (!maintenence_status) { setField("maintenence_status", INPUTS.maintenence_status); } }

      if (INPUTS.maintenence_vehicle === "" || INPUTS.maintenence_vehicle === " ") {
      if (!maintenence_vehicle || maintenence_vehicle === '') NewErrors.maintenence_vehicle = 'Veiculo  invalido !';
      } else { if (!maintenence_vehicle) { setField("maintenence_vehicle", INPUTS.maintenence_vehicle); } }

      return NewErrors;
  }
  
     const FormSubmit = (e)=>{  
      e.preventDefault();   
      const formErrors = validateForm();
      if(Object.keys(formErrors).length > 0){
           setErrors(formErrors);
           toast.error("Verifique todos os  campos");   
             setRegisterStatus(1);   
        }else{
          const SUBMIT_INPUTS = {
             maintenence_vehicle:INPUTS.maintenence_vehicle,
             maintenence_status:INPUTS.maintenence_status,
             maintenance_description:form.maintenence_description
          };

          if(!props.update){
              try {
                axios.post(FORMURL[0], SUBMIT_INPUTS).then(()=>{  
                  toast.success("Manutenção registrada com sucesso !");
                  setForm({});
                  ClearInputs();
                  setRegisterStatus(2);  
                  RefreshList(`.el-refresh-list`);
                }).catch((error)=>{
                  setRegisterStatus(1);  
                const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
                toast.error(msg);
                }); 
              } catch (error) {
                setRegisterStatus(1);  
                const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
                toast.error(msg);
              }
          } else {
             try {
              axios.put(FORMURL[2] , SUBMIT_INPUTS).then(()=>{  
                toast.success("Manutenção atualizada com sucesso !");
                setForm({});
                setRegisterStatus(2);  
                RefreshList(`.el-refresh-list`); 
                ClearInputs(); 
                setTimeout(() => { 
                    handleClose();
                }, 1500);
              }).catch((error)=>{
                setRegisterStatus(1);  
                const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
                toast.error(msg);
              }); 
             } catch (error) {
              setRegisterStatus(1);  
              const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
              toast.error(msg);
             }
          }
        }  
    };

      
    const handleInput = (e)=>{ 
       switch (e.target.id) {
        case "maintenence_vehicle":
           INPUTS.maintenence_vehicle = e.target.value
           setField("maintenence_vehicle", e.target.value);
          break; 
          case "maintenence_description":
            INPUTS.maintenence_description = e.target.value
            setField("maintenence_description", e.target.value);
           break; 
           case "maintenence_status":
            INPUTS.maintenence_status = e.target.value
            setField("maintenence_status", e.target.value);
           break; 
        default:
       }
    }
  return (
    <div>  
      <div onClick={handleShow}>
            {
              props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon/>Efetuar registro de manutenção</button>  
            }
       </div>
      <Modal className={showBox ? ModalAnimationShow() : ModalAnimationClose()}  centered  size='lg' dialogAs={DraggableModal}  show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
            <UserOptionDropDown />
             <h5>{ props.title ? props.title : 'Efetuar ' } registro de  manutenção</h5>
           </div>   
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={FormSubmit}> 
        <Modal.Body className='scrollLimit'> 
            <Form.Group className="mb-3">
              <Form.Label>Viatura<span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Select  onChange={handleInput} className={!!errors.maintenence_vehicle && 'is-invalid'} value={form.maintenence_vehicle} isInvalid={!!errors.maintenence_vehicle}
              id="maintenence_vehicle">
                   <VehiclesDataOptions/>
              </Form.Select>
              <Form.Control.Feedback type='invalid'>{errors.maintenence_vehicle}</Form.Control.Feedback>
            </Form.Group>     
            <Form.Group className="mb-3">
              <Form.Label>Estado<span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Select  onChange={handleInput} className={!!errors.maintenence_status && 'is-invalid'} value={form.maintenence_status} 
              isInvalid={!!errors.maintenence_status}
              id="maintenence_status">
                   <option disabled>Selecionar estado</option>
                   <option value="0">Pendente</option>
                   <option value="1">Em analise</option>
                   <option value="2">Sem reparo</option>
                   <option value="3">Reparado</option>
              </Form.Select>
              <Form.Control.Feedback type='invalid'>{errors.maintenence_status}</Form.Control.Feedback>
            </Form.Group>     
            <Form.Group className="mb-3">
              <Form.Label >Descrição </Form.Label> 
              <div className="maintenence-description-input">
                   <textarea name="maintenence-description" onChange={handleInput}  id="maintenence_description"
                   value={form.maintenence_description}  rows={10} className="form-control"></textarea>
              </div>
            </Form.Group>  
        </Modal.Body>
        <Modal.Footer>
        <div className="ed-space">
             <div className="ed-flex"></div>
             <div className="ed-flex">
             <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button> 
            {props.update ? (Founded === false ? <div></div>  : 
            <SaveButton icon={props.title ? <Update/> : <Save/>} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
            <SaveButton icon={props.title ? <Update/> : <Save/>} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />} 
             </div>
          </div>
        </Modal.Footer>
        </Form>
      </Modal>
    </div>
  )
} 

export default NewMaintenenceModal