const TABLEURL = Hoot() + "edualllibraryborrowedbooks/get";

function BookLoansBarChart({ data, YEAR }) {
  const [chartData, setChartData] = useState(null);
  const year = YEAR * 1;

  useEffect(() => {
    if (!data || data.length === 0) {
      console.warn("Nenhum dado recebido para o gráfico.");
      return;
    }

    const labels = [
      "Jan", "Fev", "Mar", "Abr", "Mai", "Jun",
      "Jul", "Ago", "Set", "Out", "Nov", "Dez"
    ];

    const colors = [
      "#8a72ff", "#5c85ff", "#6298ff", "#7eb4ff", "#66cccc", "#85e085",
      "#99cc66", "#ffcc66", "#ff9966", "#ff6666", "#ff6699", "#b366ff"
    ];

    let loansByMonth = Array(12).fill(0);

    data.forEach((entry) => {
      if (!entry.registerDate) return;

      // Converte "29-03-2025" para um formato válido: "2025-03-29"
      const [day, month, yearStr] = entry.registerDate.split("-");
      const formattedDate = `${yearStr}-${month}-${day}`;
      const registerDate = new Date(formattedDate);

      const entryYear = registerDate.getFullYear();
      const monthIndex = registerDate.getMonth();

      if (entryYear === year) {
        loansByMonth[monthIndex] += entry.borrowed_books.length;
      }
    });

    console.clear();
    console.log("Dados Recebidos:", data);
    console.log("Dados Processados (loansByMonth):", loansByMonth);

    const chartConfig = {
      series: [{ name: `Empréstimos (${year})`, data: loansByMonth }],
      options: {
        chart: { type: "bar", height: 350 },
        colors: colors,
        plotOptions: {
          bar: {
            columnWidth: "55%",
            endingShape: "rounded",
            distributed: true
          }
        },
        dataLabels: { enabled: false },
        xaxis: { categories: labels },
        yaxis: {
          title: { text: "Quantidade de Empréstimos" },
          labels: { formatter: (value) => value.toLocaleString() },
        },
        tooltip: { y: { formatter: (value) => `${value.toLocaleString()} livros` } },
      },
    };

    setChartData(chartConfig);
  }, [JSON.stringify(data), year]);

  return (
    <div>
      {chartData ? (
        <Chart options={chartData.options} series={chartData.series} type="bar" height={350} />
      ) : (
        <p>Carregando gráfico...</p>
      )}
    </div>
  );
}






function LibraryDashboard() {
  document.title = "Dashboard bibliotecario";
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);
  const [CurrentYear, SetCurrentYear] = useState(moment().year());

  async function loadData() {
    setLoaded(false);
    try {
      setLoadStatus(0);
      const response = await axios.get(TABLEURL);
      const rows = response.data.map((item, index) => {
        return {
          index: index + 1,
          id: item.id,
          studentname: item.studentname,
          studentpicture: item.studentpicture,
          studentid: item.studentid,
          date: `${moment(item.date).format("D [de] MMMM [de] YYYY")} / ${moment(item.devolutionDate).format("D [de] MMMM [de] YYYY")}`,
          book: item.book,
          registerDate:moment(item.date).format("DD-MM-YYYY"),
          borrowed_books: item.borrowed_books,
          status: item.status,
          action: ''
        };
      });

      console.clear()
      console.log(response.data);
      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoaded(true);
      setLoadStatus(1);
    }
  }

  useEffect(() => {
    loadData();
  }, [CurrentYear]);




  return (
    <div>  
      <LargeChart>
        <div className="ed-space">
          <div><h1 className="title">Gráfico de emprestimo de livros</h1> </div>
          <div>
            <select onChange={(e) => SetCurrentYear(e.target.value)} value={CurrentYear} className="form-control col-lg-4 select-year">
              {[1, 2, 3, 4, 5, 6, 7, 8, 9].map((item, index) => (
                <option value={2020 + index}>{2020 + index}</option>
              ))}
            </select>
          </div>
        </div>
        {load !== false ?  <BookLoansBarChart YEAR={CurrentYear} data={data} /> : <></>} 
      </LargeChart>



    </div>
  )
}


