import React, { forwardRef, useEffect, useImperativeHandle, useState } from 'react'
import TableGrid from '../../../General/components/TableGrid';
import Hoot from '../../../General/components/Hoot';
import { Avatar } from '@mui/material';
import { Check, Close, Delete, Edit, Refresh } from '@mui/icons-material';
import { Badge } from 'react-bootstrap';
import FloorNumber from '../../../General/components/FloorNumber';
import CalculateNote from '../../../General/components/CalculateNote';
import RefreshButton from '../../../General/components/RefreshButton';
import ReplaceWord from '../../../General/components/ReplaceWord';
import axios from 'axios';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';


const DATA_URL = [
  Hoot() + 'eduallsingleclassapi/get/',
  Hoot() + 'eduallsingleacademiclevelsapi/get/',
];


const StatusType = [
  <Badge className="col" bg={'success'}><Check /> Transito</Badge>,
  <Badge className="col" bg={'danger'}> <Close /> Não transito</Badge>,
];


const StatusType1 = [
  <Badge className="col" bg={'success'}>Dispensado</Badge>,
  <Badge className="col" bg={'warning'}>Exame</Badge>,
];


const StatusType2 = [
  <Badge className="col" bg={'success'}>Apto</Badge>,
  <Badge className="col" bg={'warning'}>Recurso</Badge>,
];



const StatusType3 = [
  <Badge className="col" bg={'success'}>Apto</Badge>,
  <Badge className="col" bg={'danger'}>Reprovado</Badge>,
];


const GetColor = (e, max) => {
  return (e < (max / 2)) ?
    <span className='text-danger'>{e}</span>
    : <span className='text-success'>{e}</span>
}



const FinalScore = (md, exam, special) => {
  if (md > 13) return md;
  if (Math.floor((exam + md) / 2) >= 10) return Math.floor((exam + md) / 2);
  return special;
}



const columns2 = [
  { field: 'index', headerName: 'Nº', width: 60, resizable: true, },
  {
    field: 'student',
    headerName: 'Nome do aluno',
    resizable: true,
    width: 300,
    cellRenderer: (props) => {
      return <div className='ed-flex'>
        <Avatar className='df' alt={props.data.name} src={props.data.picture !== "" ? Hoot() + props.data.picture : ""} />
        <span className='ml-2'>{props.data.name}</span>
      </div>
    }
  },
  {
    field: 'p1',
    headerName: 'P1',
    width: 70,
    resizable: true,
    editable: true,
    cellRenderer: (props) => {
      return GetColor(props.data.p1 * 1, props.data.MaxValue)
    }
  },
  {
    field: 'p2',
    headerName: 'P2',
    width: 70,
    resizable: true,
    editable: true,
    cellRenderer: (props) => {
      return GetColor(props.data.p2 * 1, props.data.MaxValue)
    }
  },
  {
    field: 'md',
    headerName: 'Media',
    width: 80,
    resizable: true,
    editable: true,
    cellRenderer: (props) => {
      return GetColor(props.data.md * 1, props.data.MaxValue)
    }
  },
  {
    field: 'status',
    headerName: 'Estado',
    width: 150,
    resizable: true,
    editable: true,
    cellRenderer: (props) => {
      return <div className='ed-flex'> {StatusType1[props.data.status]} </div>
    }
  },
  {
    field: 'exam',
    headerName: 'Exame',
    width: 100,
    resizable: true,
    editable: true,
    cellRenderer: (props) => {
      return GetColor(props.data.exam * 1, props.data.MaxValue, null)
    }
  },
  {
    field: 'result',
    headerName: 'Resultado',
    width: 110,
    editable: true,
    resizable: true,
    cellRenderer: (props) => {
      return <div className='ed-flex col'> {StatusType2[props.data.status * 1 === 0 ? 0 : props.data.result]}</div>
    }
  },
  {
    field: 'specialexam',
    headerName: 'Recurso',
    width: 100,
    resizable: true,
    editable: true,
    cellRenderer: (props) => {
      return props.data.result < 10 ? GetColor(props.data.specialexam * 1, props.data.MaxValue, null) : <></>
    }
  },
  {
    field: 'nf',
    headerName: 'Nota final',
    width: 100,
    resizable: true,
    editable: true,
    cellRenderer: (props) => {
      return GetColor(FinalScore(props.data.md, props.data.exam, props.data.specialexam), props.data.MaxValue)
    }
  },
  {
    field: 'nf',
    headerName: 'Estado',
    width: 130,
    resizable: true,
    editable: true,
    cellRenderer: (props) => {
      return (FinalScore(props.data.md, props.data.exam, props.data.specialexam) >= 10 ?
        <div className='ed-flex col'> {StatusType3[props.data.status * 1 === 0 ? 0 : 0]}</div> :
        <div className='ed-flex col'> {StatusType3[props.data.status * 1 === 0 ? 0 : 1]}</div>
      )
    }
  },
];


const PdSemesterNotesTable = forwardRef((props, ref) => {

  const [MarksData, setMarksData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);
  const Class = props.Class;
  const Subject = props.Subject;
  const Semester = props.Semester;

  const TABLEURL = [
    Hoot() + "eduallsinglesemesternotebysemsubcls/get/",
    Hoot() + "eduallsemesternotesbysubclasssm/get/"
  ];


  async function loadData(C, S, Q) {
    try {
      setLoaded(false);
      if ((Q !== null && Q * 1 >= 0) && (S !== null && S * 1 >= 0) && (C !== null && C * 1 >= 0)) {
        setLoadStatus(0);

        let MaxValue = 0;
        const response = await axios.get(TABLEURL[0] + Q + "," + S + "," + C);
        const response1 = await axios.get(DATA_URL[0] + `${C}`);

        if (response1.data.length >= 1) {

          const info = await axios.get(DATA_URL[1] + `${response1.data[0].ed_class_academic_level}`);

          if (info.data.length >= 1) {
            MaxValue = info.data[0].ed_academic_level_avaliationtype_endat * 1;
          } else {
            MaxValue = 0;
          }

          const Marks = [];
          response.data.map((item, index) => {
            Marks.push({
              index: index + 1,
              id: item.ed_semester_note_id,
              studentid: item.ed_student_id,
              picture: item.ed_student_picture,
              name: `(#${item.ed_student_name} ) - ` + item.ed_student_name,
              student: item.ed_quarter_note_studentcode,

              p1: item.ed_semester_note_p1,
              p2: item.ed_semester_note_p2,
              exam: item.ed_semester_note_exam,
              specialexam: item.ed_semester_note_specialexam,

              md: CalculateNote(item.ed_semester_note_p1, item.ed_semester_note_p2, item.ed_semester_note_exam, item.ed_semester_note_specialexam, 0),
              result: CalculateNote(item.ed_semester_note_p1, item.ed_semester_note_p2,
                item.ed_semester_note_exam, item.ed_semester_note_specialexam, 1) * 1 < 10 ? 1 : 0,
              fn: CalculateNote(item.ed_semester_note_p1, item.ed_semester_note_p2, item.ed_semester_note_exam,
                item.ed_semester_note_specialexam, 2),
              status: CalculateNote(item.ed_semester_note_p1, item.ed_semester_note_p2,
                item.ed_semester_note_exam, item.ed_semester_note_specialexam, 0) * 1 <= 13 ? 1 : 0,

              semester: Q,
              subject: S,
              class: C,
              action: true,
              MaxValue: MaxValue,
            });
          });

          console.log("************************************************");
          console.log(Marks);
          console.log("*************************************************");
          setMarksData(Marks);

        }
        setLoadStatus(2);
      }
    } catch (error) {
      console.log(error);
      setLoadStatus(1);
    }
    setLoaded(true);
  }


  useImperativeHandle(ref, () => ({
    RunGetNotes() {
      loadData(Class, Subject, Semester);
      console.clear();
      console.log(props);
    }
  }))

  useEffect(() => {
    loadData(Class, Subject, Semester);
  }, []);

  useEffect(() => {
    console.clear();
    console.log(props);
  }, [props]);



  return (
    <div>
      <div className="table-box" id='ed-custom-table-data'>
        {load ?
          <TableGrid
            TableHead={columns2}
            TableBody={MarksData}
            TableHeight={420}
            TableTitle={`Notas por turma / ${ReplaceWord("Disciplina", true)} `}
            NoButtons
            TableBtn={
              <div className='ed-flex'> 
                <button id='ed-custom-table-data-btn'
                  onClick={() =>
                    ExportDataToTablesToPdf({
                      fileName:`Notas por turma / ${ReplaceWord("Disciplina", true)} `,
                      headerId: null,
                      contentId: "ed-custom-table-data",
                      footerId: null,
                      rotation: "landscape",
                      buttonId: "ed-custom-table-data-btn",
                      customHeader:`Notas por turma / ${ReplaceWord("Disciplina", true)} `,
                      excludedColumns: ["Ação", "Nº"]
                    })
                  }
                  className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
                </button>
                <button className='btn-icon btn btn-export-data ml-2'
                  onClick={() => ExportDataForTablesExcel(`Notas por turma / ${ReplaceWord("Disciplina", true)} ` ["Ação"])}><PiMicrosoftExcelLogoDuotone />
                </button>
                <RefreshButton action={load} status={LoadStatus} />
              </div>
            }
          />
          :
          <>
            <div className="d-none">*</div>
            <TableGrid
              TableHead={columns2}
              TableBody={[]}
              TableHeight={420}
              NoButtons
              TableTitle={`Notas por turma / ${ReplaceWord("Disciplina", true)} `}
              TableBtn={<RefreshButton action={load} status={LoadStatus} />}
            />
          </>
        }
      </div>
    </div>
  )
});

export default PdSemesterNotesTable
