import React, { useEffect, useState } from 'react'
import { Form } from 'react-bootstrap';
import SendSmsAndEmailFunc from './SendSmsAndEmailFunc';
import Hoot from './Hoot';
import axios from 'axios';
import {toast} from 'react-hot-toast';
import { getStudentData } from './InstituteData';
import SmallLoader from './SmallLoader';



async function SendMessage(student, subject, classcode, quarter, mark, message) {
    const { name, scholl, mac, npp, npt, mt, exame, recurso } = await getStudentData(student, subject, classcode, quarter);
    if (mark === true) {
        const msg = `${scholl}\nAssunto: Notas do(a) aluno(a): ${name}\nInformamos que as últimas notas do ${quarter}º trimestre são as seguintes:\n\n- MAC: ${mac}\n- NPP: ${npp}\n- NPT: ${npt}\n- MT (Média Total): ${mt}\n- Exame: ${exame}\n- Recurso: ${recurso}\nCaso necessite de mais informações, por favor contacte a instituição.\n\nObrigado pela atenção.`;
        const tt = `Notas do(a) aluno(a): ${name}`;
        return { msg, tt }
    }else{
        const msg = `${scholl}\nAssunto: Presença do(a) aluno(a): ${name}\nInformamos que o(a) aluno(a) esteve marcado(a) como "${message?.status}" na aula de ${message?.subject} realizada no dia ${message?.date} às ${message?.time}.\n\nCaso necessite de mais informações, por favor contacte a instituição.\n\nObrigado pela atenção.`;
        const tt = `Presença do(a) aluno(a): ${name}`;        
        return { msg, tt }
    }
}
 

function MessageTypeSelectorSend({ message, student, title, send, select, subject, classcode, quarter, mark }) {
    const [MessageType, setMessageType] = useState(null);
    const [LoadingStatus ,setLoadingStatus] = useState(false);

    async function Send() {
        try {
            const URLS = [
                Hoot() + 'eduallsinglestudentapi/get/',
                Hoot() + "eduallparentkidsparents/get/"
            ]

            let sendStatus = select ? true : send;
            let MSG = null;
            let title = null;

            if (MessageType !== null && MessageType <= 6) {

                if (!select) {
                    MSG = message;
                    title = title;
                } else { 
                    setLoadingStatus(true);
                    const { tt, msg } = await SendMessage(student, subject, classcode, quarter, mark, message);
                    title = tt;
                    MSG = msg; 
                    setLoadingStatus(false);
                }
                if (student !== null && MSG !== null && sendStatus === true) {
                    setLoadingStatus(true); 
                    let contacts = [];
                    const [StudentData, ParentsResponse] = await Promise.all([
                        axios.get(URLS[0] + student),
                        axios.get(URLS[1] + student)
                    ]);

                    const studentContacts = [];
                    const parentContacts = [];

                    StudentData.data.forEach(ct => {
                        studentContacts.push({ phone: ct.ed_student_phone, id: 0, email: ct.ed_student_email, type: 0, name: ct.ed_student_name });
                    });

                    ParentsResponse.data.forEach(ct => {
                        parentContacts.push({ phone: ct.ed_parent_phone, id: 0, email: ct.ed_parent_email, type: 0, name: ct.ed_parent_name });
                    });

                    let type = null;
                    if (MessageType === 1) {
                        type = 1;
                        contacts = studentContacts;
                    }

                    if (MessageType === 2) {
                        type = 1;
                        contacts = parentContacts;
                    }

                    if (MessageType === 3) {
                        type = 2;
                        contacts = studentContacts;
                    }

                    if (MessageType === 4) {
                        type = 2;
                        contacts = parentContacts;
                    }

                    if (MessageType === 5) {
                        type = 1;
                        contacts = [...parentContacts, ...studentContacts];
                    }

                    if (MessageType === 6) {
                        type = 3;
                        contacts = [...parentContacts, ...studentContacts];
                    }

                    if (MessageType === 6) {
                        SendSmsAndEmailFunc(contacts, MSG, title, [], 1);
                        SendSmsAndEmailFunc(contacts, MSG, title, [], 2);
                    } else {
                        SendSmsAndEmailFunc(contacts, MSG, title, [], type);
                    }

                }
            }
            setLoadingStatus(false);
        } catch (error) {
            console.clear();
            console.log(error);
            const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
            toast.error(msg);
            setLoadingStatus(false);
        }
    }


    useEffect(() => {
        setTimeout(() => {
            Send();
        }, 1000);
    }, [message, student, title, send, MessageType, select, subject, classcode, quarter, mark])


    return (
        <div className='ed-flex'>
            {LoadingStatus === true ? <div className='ed-flex'><div className="mr-2"></div> <SmallLoader /></div> : <></>}
            <Form.Select onChange={(e) => setMessageType(e.target.value * 1)} >
                <option disabled selected>Enviar mensagem ...</option>
                <option value="1">Enviar sms para o(a) aluno(a)</option>
                <option value="2">Enviar sms para o(a) encarregado(a)</option>
                <option value="3">Enviar email para o(a) aluno(a)</option>
                <option value="4">Enviar email para o(a) encarregado(a)</option>
                <option value="5">Enviar sms ( Encarregado(a) / aluno(a))</option>
                <option value="6">Enviar sms / email ( Encarregado(a) / aluno(a))</option>
            </Form.Select> 
        </div>
    )
}

export default MessageTypeSelectorSend
