import axios from 'axios';
import React, { useEffect, useState } from 'react' 
import styled from 'styled-components';
import { Avatar, Skeleton } from '@mui/material'; 
import { Link } from 'react-router-dom/cjs/react-router-dom'; 
import ReduceTextLength from '../../../../General/components/ReduceTextLength';
import Hoot from '../../../../General/components/Hoot';
import { Table } from 'react-bootstrap';


function STD_classmates(props) {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);


  async function loadData(e){  
      try {
        setLoaded(false); 
        const response =  await axios.get(Hoot()+"eduallgetstudentsbyclass/"+e); 
         setData(response.data); 
        setTimeout(() => {
           setLoaded(true); 
        }, 200);
      } catch (error) {
        setLoaded(true); 
      }
  }

  useEffect(()=>{
      loadData(props.class); 
  },[props]);

  return (
    <div className=''>

      <Table bordered > 
         <tbody>
         {data.map((item, index)=>{
                  return(<tr key={index+1} > 
                    <td>
                        <div className="ed-flex">
                            <Avatar className='df' src={Hoot()+item.ed_student_picture} sx={{width:40,height:40}} 
                            alt={item.ed_student_name}>{item.ed_student_name.split("")[0]}</Avatar>
                              <div className="ed-block ml-2">
                                <p><ReduceTextLength text={item.ed_student_name} length={50}/></p> 
                              </div>
                        </div>
                    </td> 
                </tr> )
              })}   
         </tbody>
        </Table> 
    </div>
  )
}

export default STD_classmates
