// Função utilitária para verificar se um elemento está visível
import ExcelJS from "exceljs";
import moment from "moment";
import "moment/locale/pt-br";
import { saveAs } from "file-saver";
import toast from "react-hot-toast";

// Função utilitária para verificar se um elemento está visível
const isVisible = (el) => {
  if (!el || !(el instanceof HTMLElement)) return false;
  const style = window.getComputedStyle(el);
  return (
    style.display !== "none" &&
    style.visibility !== "hidden" &&
    el.offsetParent !== null
  );
};

// Função para obter texto correto da célula, tratando <select> com option selecionada
const getCellTextContent = (cell) => {
  const select = cell.querySelector("select");
  if (select) {
    const selectedOption = select.options[select.selectedIndex];
    return selectedOption?.text?.trim() || "";
  }
  return cell.innerText.trim();
};

const ExportPdTablesToExcel = async (tableIds, buttonId = null, topText = "") => {
  const button = buttonId ? document.getElementById(buttonId) : null;
  let originalButtonHTML = "";

  try {
    const tables = Array.isArray(tableIds)
      ? tableIds.map((id) => document.getElementById(id))
      : [document.getElementById(tableIds)];

    if (tables.some((t) => !t)) {
      toast.error("Uma ou mais tabelas não foram encontradas!");
      return;
    }

    if (button) {
      originalButtonHTML = button.innerHTML;
      button.disabled = true;
      button.innerHTML =
        `<span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span> Exportando...`;
    }

    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet("Exportação");
    const dataFormatada = moment().locale("pt-br").format("D [de] MMMM [de] YYYY, [às] HH:mm");
    const mergeMap = new Map();

    let currentRow = 1;

    if (topText) {
      worksheet.mergeCells(currentRow, 1, currentRow, 20);
      const titleCell = worksheet.getCell(currentRow, 1);
      titleCell.value = topText;
      titleCell.font = { name: "Poppins", bold: true, size: 16 };
      titleCell.alignment = { horizontal: "center", vertical: "middle" };
      currentRow += 2;
    }

    for (let tableIndex = 0; tableIndex < tables.length; tableIndex++) {
      const table = tables[tableIndex];
      const rows = Array.from(table.rows).filter((row) => isVisible(row));
      const startRow = currentRow;

      rows.forEach((row, rowIndex) => {
        const realRow = currentRow + rowIndex;
        let colIndex = 1;

        Array.from(row.cells).forEach((cell) => {
          if (!isVisible(cell)) return;

          while (mergeMap.has(`${realRow},${colIndex}`)) colIndex++;

          const cellValue = getCellTextContent(cell);
          const colSpan = cell.colSpan || 1;
          const rowSpan = cell.rowSpan || 1;
          const endRow = realRow + rowSpan - 1;
          const endCol = colIndex + colSpan - 1;
          const cellRef = worksheet.getCell(realRow, colIndex);

          const isHeader = row.parentElement.tagName === "THEAD" || rowIndex === 0;

          cellRef.value = cellValue;
          cellRef.font = {
            name: "Poppins",
            bold: isHeader,
            size: isHeader ? 13 : 12,
            color: isHeader ? { argb: "FFFFFF" } : undefined,
          };
          cellRef.alignment = { horizontal: "center", vertical: "middle" };
          cellRef.border = {
            top: { style: "thin" },
            left: { style: "thin" },
            bottom: { style: "thin" },
            right: { style: "thin" },
          };

          if (isHeader) {
            cellRef.fill = {
              type: "pattern",
              pattern: "solid",
              fgColor: { argb: "6051FF" },
            };
            worksheet.getRow(realRow).height = 40;
          } else {
            worksheet.getRow(realRow).height = 40;

            let textColor = null;
            const children = Array.from(cell.querySelectorAll("span, div, strong")).filter(isVisible);
            children.forEach((child) => {
              if (child.classList.contains("text-danger") || child.classList.contains("bg-danger")) textColor = "FF0000";
              else if (child.classList.contains("text-success") || child.classList.contains("bg-success")) textColor = "28A745";
              else if (child.classList.contains("text-warning") || child.classList.contains("bg-warning")) textColor = "FFC107";
              else if (child.classList.contains("text-main")) textColor = "808080";
            });

            if (textColor) {
              cellRef.font = { ...cellRef.font, color: { argb: textColor } };
            }

            const striped = (realRow - startRow) % 2 === 0;
            cellRef.fill = {
              type: "pattern",
              pattern: "solid",
              fgColor: { argb: striped ? "F3F3F3" : "FFFFFF" },
            };
          }

          if (colSpan > 1 || rowSpan > 1) {
            let canMerge = true;
            for (let r = realRow; r <= endRow; r++) {
              for (let c = colIndex; c <= endCol; c++) {
                if (mergeMap.has(`${r},${c}`)) {
                  canMerge = false;
                  break;
                }
              }
              if (!canMerge) break;
            }

            if (canMerge) {
              worksheet.mergeCells(realRow, colIndex, endRow, endCol);
              for (let r = realRow; r <= endRow; r++) {
                for (let c = colIndex; c <= endCol; c++) {
                  mergeMap.set(`${r},${c}`, true);
                }
              }
              mergeMap.delete(`${realRow},${colIndex}`);
            }
          } else {
            mergeMap.set(`${realRow},${colIndex}`, true);
          }

          colIndex += colSpan;
        });
      });

      currentRow += rows.length + 2;
    }

    worksheet.columns.forEach((col) => {
      let max = 10;
      col.eachCell({ includeEmpty: true }, (cell) => {
        if (cell.value) {
          const len = cell.value.toString().length;
          if (len > max) max = len;
        }
      });
      col.width = max + 5;
    });

    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], {
      type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    });

    const fileNameFinal = `eduall_${topText} - ${dataFormatada}.xlsx`;
    saveAs(blob, fileNameFinal);
    toast.success("Exportação concluída com sucesso!");
  } catch (error) {
    console.error(error);
    toast.error("Erro ao exportar para Excel.");
  } finally {
    if (button) {
      button.disabled = false;
      button.innerHTML = originalButtonHTML;
    }
  }
};

export default ExportPdTablesToExcel;

