import React, { useEffect, useState } from 'react'
import UserNavbar from '../../Components/UserNavbar'
import styled from 'styled-components'
import AddsGenerator from '../../Components/AddsGenerator';
import { Avatar, AvatarGroup, Skeleton } from '@mui/material';
import { Link } from 'react-router-dom';
import { Form } from 'react-bootstrap';
import {AiOutlineHeart} from "react-icons/ai";
import {GoPersonAdd,GoBriefcase}from "react-icons/go";
import {FiMapPin} from "react-icons/fi";
import {PiUsers,PiListMagnifyingGlass} from "react-icons/pi";
import {TbListSearch} from "react-icons/tb";
import SidebarLeft from '../../Employees/Components/SidebarLeft';
import AddContactButton from '../../Components/AddContactButton';
import FollowPageButton from '../../Components/FollowPageButton';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import ReduceTextLength from '../../../General/components/ReduceTextLength';
import { useLocation } from 'react-router-dom';


function SearchMain({userdata}){  
    const [InstituteData, setInstituteData] =  useState([]);
    const [Loaded, setLoaded] =  useState(false); 
    const [searchData, SetSearchData] =  useState([]); 
    const { search } = useLocation();
     const searchParams = new URLSearchParams(search);
     const param = searchParams.get("search");

    const DATAURL = [
        Hoot()+"eduallinstitutessearch/search/",
        Hoot()+"eduallsearchusers/search/"
    ];

    const LoadData = async()=>{  
     setLoaded(false);
      try {
        const [response, response1] = await Promise.all([
            axios.get(DATAURL[0]+param), 
            axios.get(DATAURL[1]+param), 
      ]); 
       
       let data = [];

       response.data.map((item,index)=>{
            let mewItem = item;
            mewItem.inst = true;
            mewItem.key = item.ed_institute_name;
            data.push(mewItem);
       });

       
       response1.data.map((item,index)=>{
            let mewItem = item;
            mewItem.user = true;
            mewItem.key = item.ed_user_account_name;
            data.push(mewItem);
       });
 
       data.sort((a, b) => {
        let fa =  a.key.toLowerCase(),
            fb = b.key.toLowerCase();
    
        if (fa < fb)   return -1; 
        if (fa > fb)  return 1; 
        return 0;
      });

       SetSearchData(data);
       setLoaded(true);


      } catch (error) {
        
      }            
     }
    
    
 
     useEffect(()=>{
        LoadData();
     },[param]); 
    

  return (
    <div className="eduall-network">
    <UserNavbar data={userdata} />
     <Container className='ed_search_page'> 
        <div className="ed-wrapper">
        <div className="content">
        <div className="filter-box">
                     <div className="box">
                          <div className="ed-flex title"><TbListSearch/>  Filtrar resultados</div>
                          <Form>
                            <div className="mt-4">
                                <Form.Select>
                                    <option disabled selected>Localização</option>
                                </Form.Select>
                            </div>
                            <div className="mt-4">
                                <Form.Select>
                                    <option disabled selected >Categoria</option>
                                </Form.Select>
                            </div>
                            <div className="mt-4">
                                <Form.Select>
                                    <option disabled selected >Ver tudo</option>
                                </Form.Select>
                            </div>
                            <div className="mt-4 col">
                                <button className="btn bg-main col-lg-12">Aplicar filtros</button>
                            </div>
                          </Form>
                     </div> 
                </div>
                <section>
                    <div className="mb-2">
                          <div className="total-search">{searchData.length} resultados emcontrados</div>
                    </div>
                     <ul className="result-container">  
                       {Loaded === true ?
                        <>
                          {searchData.map((item, index)=>{  
                              if(item.inst === true){ 
                                return(
                                 <li className="clg-item" key={index+1} >
                                    <div className="ed-space">
                                        <div className="ed-flex">
                                            <Link to={"/institute_blog/"+item.ed_institute_code}>
                                                <Avatar src={Hoot()+item.ed_institute_logo} alt={item.ed_institute_name} 
                                                variant="rounded" sx={{width:70,height:70}} className='df'  />
                                            </Link>
                                            <div className="ed-block ml-2">
                                                <Link to={"/institute_blog/"+item.ed_institute_code}>
                                                    <h5 className="name"><ReduceTextLength text={item.ed_institute_name}  length={70} /></h5>
                                                </Link>
                                                <div className="ed-flex mt-2">
                                                    <div className="location mr-2"><FiMapPin/> Angola, Luanda capolo 2</div>  
                                                    <div className="ml-2"><span><PiUsers/> +24.000.00 seguem está instituição</span></div>
                                                </div>
                                            </div>
                                        </div>
                                        <div className="btn-st">
                                            <FollowPageButton TYPE={1} CODE={item.ed_institute_code} />
                                        </div>
                                    </div>
                                 </li> 
                                ) 
                              }else if(item.user === true){
                              let name = item.ed_user_account_name.split(" ");
                              let linkcode = "";
                              for(let i = 0; i < name.length; i++) {
                                 if(i < name.length-1){linkcode += name[i]+"-";}else{linkcode += name[i]+"_";}
                              }
                              linkcode += item.ed_user_account_id;
                              return(
                                <li className="ctt-item" key={index+1}>
                                <div className="ed-space">
                                    <div className="ed-flex">
                                        <Link to={"/profile/"+linkcode.toLowerCase()}>
                                            <Avatar src={Hoot()+item.ed_user_account_picture} sx={{width:60,height:60}} className='df'  />
                                        </Link>
                                        <div className="ed-block ml-2">
                                            <Link to={"/profile/"+linkcode.toLowerCase()}>
                                                <h5 className="name"><ReduceTextLength text={item.ed_user_account_name}  length={70} /></h5>
                                            </Link>
                                            <div className="ed-flex mt-2">
                                                <div className="job"><GoBriefcase/> {item.ed_user_account_charge}</div>  
                                            </div>
                                        </div>
                                    </div>
                                    {(userdata.user_Information.ed_user_account_id*1  === item.ed_user_account_id) ? <></> : 
                                    <div className="btn-st"><AddContactButton TYPE={0} CODE={item.ed_user_account_id} /></div> }
                                </div>
                                </li>
                                )
                              }
                          })} 
                        </>:
                        <>
                           {[1,2,3,4,5,6].map((item,index)=>{
                              return(
                                <li key={index+1}>
                                    <div className="ed-flex">
                                          <Skeleton variant='circle' animation='wave' width='70px' height={70} />
                                        <div className="ed-block ml-2 col-lg-10">
                                           <Skeleton variant='rectangle' animation='wave' width='60%' height={25} />
                                           <div className="mt-2">
                                              <Skeleton variant='rectangle' animation='wave' width='35%' height={18} />
                                           </div>
                                        </div>
                                    </div>
                                </li>
                              )
                           })}
                        </>
                       }



                         

                   <div className="d-none">


         
                 <li className="ptb-item">
                    <div className="pt-box">
                        <div className="ed-space">
                        <div className="ed-flex">
                            <Link to="#">
                                <Avatar variant="rounded" sx={{width:90,height:90}} className='df'  />
                            </Link>
                            <div className="ed-block ml-2">
                                <Link to="#"><p className="description">Lorem ipsum consectetur adipisicing elit. Voluptates numquam maiores commodi cupiditate incidunt soluta!</p></Link>
                                <div className="ed-flex user-bx mt-2">
                                    <Avatar sx={{width:30,height:30}} className='df'  />
                                    <div className="username ml-2 mr-2">Carlos manuel</div>  
                                </div>
                            </div>
                        </div> 
                        </div>
                    </div>
                    </li>

                    <li className="pag-item">
                    <div className="ed-space">
                        <div className="ed-flex">
                            <Link to="#">
                                <Avatar variant="rounded" sx={{width:70,height:70}} className='df'  />
                            </Link>
                            <div className="ed-block ml-2">
                                <Link to="#"><h5 className="name">Colegio xxxxx do novo centro</h5></Link>
                                <div className="ed-flex mt-2">
                                    <div className="location mr-2"><FiMapPin/>  Angola, Luanda capolo 2</div>  
                                    <div className="ml-2"><span><PiUsers/> 34.000 seguidores</span> </div>
                                </div>
                            </div>
                        </div>
                        <div className="btn-st">
                            <button className="btn btn-bordered text-main"><AiOutlineHeart />Seguir</button>
                        </div>
                    </div>
                    </li>



                   </div>





                    </ul>
                </section>
             
           </div>
        </div>
     </Container>
   </div>
  )
}

const Container = styled.div`
    padding:100px 20px; 
    width:100%;
    min-height:100vh; 
    background:var(--ed-background-color);   

    .content{  
       display:flex; 
       width:100%;   

       section{
        width:100%;
        padding-left:40px;

          .total-search{
            font-style: italic;
            color:var(--ed-grey-text);
          }
       }
    }

    .result-container{
        width:100%; 
        border-radius:6px;   
        min-height:200px;
        background:var(--ed-white);  
        box-shadow:var(--ed-shadow-df);
        margin-bottom:20px; 
        padding:20px;

          li{
           padding:10px  0px;
           padding-bottom:20px;
           margin:10px 0px;
           border-bottom:1px solid  #eaeaee;

           .pt-box{
              padding:10px;
              border-radius:6px;
              border:1px solid  #eaeaee;
           }

           .ed-space{
              align-items:unset !important;
           }

           .user-bx{
              border-radius:30px;
              padding:6px;
              width:max-content;
              background:var(--ed-background-color);  
            }
 
            .btn-st{
              padding-left:20px;
                
              button{
                border:1px solid var(--ed-purple-light) !important;
                display:flex;
                align-items:center;
                min-width:150px;
                text-align:center;
                justify-content:center;

                 svg{
                   margin-right:10px !important;
                   width:20px;
                   height:20px;
                 }
              }
            }

            

              .description, h5{
                 color:var(--ed-dark);
              }

              h5{
                  font-size:16px;
                  font-weight:600;
              }

              .description ,p, span, .location, .job{
                 font-size:15px;

                 svg{
                     margin-right:5px;
                     width:20px;
                     height:20px;
                 }
              }


         }




    }


    .filter-box{ 
        min-width:350px;
        width:400px; 

        .box{
            width:100%; 
            border-radius:6px;   
            min-height:200px;
            background:var(--ed-white);  
            box-shadow:var(--ed-shadow-df);
            margin-bottom:20px; 
            padding:20px;

              .title{
                position: relative;
                margin: 0px;
                width: max-content;
                font-size: 18px;
                color: var(--black);
                font-weight: bold; 

                svg{
                    margin-right:10px;
                    width:25px;
                    height:25px;
                }
              }
        }

    }





`;


export default SearchMain