import React, { useEffect, useState } from 'react'
import ReactApexChart from 'react-apexcharts';
import styled from 'styled-components';
import moment from 'moment';
import axios from 'axios';
import Hoot from '../../General/components/Hoot';
import { Form } from 'react-bootstrap';

function EnrollmentDashboardReport() {
  document.title = "Relatorio anual de Matrículas e confirmações";
  const [ChartData, setChartData] = useState({});
  const [ChartData1, setChartData1] = useState({});
  const [CurrentYear, setCurrentYear] = useState(moment().year());
  const [load, setLoaded] = useState(false);

  const TABLEURL = [
    Hoot() + "eduallstudentenrollments/get",
    Hoot() + "eduallenrollmentconfirmations/get"
  ];

  async function loadData(year) {
    try {
      const [response, response1] = await Promise.all([
        axios.get(TABLEURL[0]),
        axios.get(TABLEURL[1])
      ]);

      const rows = response.data.map(item => ({
        name: item.ed_student_name,
        gender: item.ed_student_gender,
        date: moment(item.ed_enrollment_registerDate).format("YYYY-MM-DD HH:mm:ss"),
        year: moment(item.ed_enrollment_registerDate).year()
      }));

      const rows1 = response1.data.map(item => ({
        name: item.ed_student_name,
        gender: item.ed_student_gender,
        date: moment(item.ed_enrollment_confirmation_registerdate).format("YYYY-MM-DD HH:mm:ss"),
        year: moment(item.ed_enrollment_confirmation_registerdate).year()
      }));

      setChartData(processEnrollmentData(rows, year, "bar", { c1: "var(--ed-purple)", c2: "var(--ed-gold)" }, "Matrículas"));
      setChartData1(processEnrollmentData(rows1, year, "bar", { c1: "var(--ed-green)", c2: "var(--ed-blue)" }, "Confirmação de matrículas"));
    } catch (error) {
      console.error('Erro ao buscar os dados:', error);
    }
  }

  const processEnrollmentData = (data, year, chartType = 'line', colors, title) => {
    const genderCountByMonth = {
      Janeiro: { masculino: 0, feminino: 0 },
      Fevereiro: { masculino: 0, feminino: 0 },
      Março: { masculino: 0, feminino: 0 },
      Abril: { masculino: 0, feminino: 0 },
      Maio: { masculino: 0, feminino: 0 },
      Junho: { masculino: 0, feminino: 0 },
      Julho: { masculino: 0, feminino: 0 },
      Agosto: { masculino: 0, feminino: 0 },
      Setembro: { masculino: 0, feminino: 0 },
      Outubro: { masculino: 0, feminino: 0 },
      Novembro: { masculino: 0, feminino: 0 },
      Dezembro: { masculino: 0, feminino: 0 }
    };

    const filteredData = data.filter(item => moment(item.date).year() === year);

    filteredData.forEach(item => {
      const enrollmentDate = moment(item.date).locale('pt').format('MMMM');
      const month = enrollmentDate.charAt(0).toUpperCase() + enrollmentDate.slice(1);

      if (genderCountByMonth[month]) {
        const gender = item.gender.toLowerCase();
        if (gender === 'male') {
          genderCountByMonth[month].masculino += 1;
        } else {
          genderCountByMonth[month].feminino += 1;
        }
      }
    });

    const months = Object.keys(genderCountByMonth);
    const maleData = months.map(month => genderCountByMonth[month].masculino);
    const femaleData = months.map(month => genderCountByMonth[month].feminino);

    const options = {
      chart: {
        height: 350,
        type: chartType,
        toolbar: { show: false }
      },
      stroke: {
        curve: chartType === 'line' || chartType === 'area' ? 'smooth' : 'straight',
        width: chartType === 'bar' ? 0 : 3
      },
      plotOptions: chartType === 'bar' ? {
        bar: {
          horizontal: false,
          columnWidth: '40%',
          endingShape: 'rounded'
        }
      } : {},
      markers: {
        size: chartType === 'line' || chartType === 'area' ? 5 : 0,
        hover: {
          size: chartType === 'line' || chartType === 'area' ? 7 : 0
        }
      },
      colors: [colors.c1, colors.c2],
      xaxis: {
        categories: months,
        title: { text: 'Meses' }
      },
      yaxis: {
        title: { text: 'Número de ' + title }
      },
      legend: {
        position: 'top',
        horizontalAlign: 'center'
      },
      title: {
        text: title + ` por Gênero em ${year}`,
        align: 'center'
      }
    };

    const series = [
      { name: 'Masculino', data: maleData },
      { name: 'Feminino', data: femaleData }
    ];

    return { options, series };
  };

  useEffect(() => {
    loadData(CurrentYear);
  }, [CurrentYear]);

  return (
    <div>
      <Container>
        <div className="ed-center ed-flex mb-3 col">
          <Form className="pd bg-white shadow-sm">
            <Form.Group className='ed-block'>
              <Form.Label>Selecione o Ano</Form.Label>
              <div className="col text-center">
                <Form.Control className='text-center' as="select" value={CurrentYear} onChange={(e) => setCurrentYear(Number(e.target.value))}>
                  {Array.from({ length: new Date().getFullYear() - 2015 + 1 }, (_, i) => 2015 + i)
                    .reverse() // opcional: para exibir do mais recente ao mais antigo
                    .map((year) => (
                      <option key={year} value={year}>{year}</option>
                    ))}
                </Form.Control>
              </div>
            </Form.Group>

          </Form>
        </div>

        <Box>
          {ChartData.options &&
            <ReactApexChart options={ChartData.options} series={ChartData.series} type="bar" height={400} />
          }
        </Box>

        <div className="mt-4 col">
          <Box>
            {ChartData1.options &&
              <ReactApexChart options={ChartData1.options} series={ChartData1.series} type="bar" height={400} />
            }
          </Box>
        </div>
      </Container>
    </div>
  )
}



const Container = styled.div`
         width:100%;
         display:flex;
         width:100%; 
         flex-wrap:wrap;
         justify-content:space-between;

         
         .bx3{
             min-width:300px;
             width:30%;
         }

            
         .pd{
              padding:10px;
              min-width:200px;
         }

         .bx7{
            min-width:300px;
            width:68%;
        }
    `;

const Box = styled.div`
        width:100%;  
        padding:20px;
        border-radius:6px;  
        min-height:450px;
        background:var(--ed-white);  
        box-shadow:var(--ed-shadow-df);

           h1.title{
              font-size:18px;
              font-weight:600;
           }
`;


export default EnrollmentDashboardReport