// NotificationModal.jsx
import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import axios from "axios";
import io from "socket.io-client";
import styled, { keyframes } from "styled-components";
import { Avatar } from "@mui/material";
import { PiBellSimpleRingingBold } from "react-icons/pi";
import MenuDropDown from "./MenuDropDown";
import Hoot from "./Hoot";
import toast, { Toaster } from "react-hot-toast";

export default function NotificationModal({
  currentUser,
  apiBase = process.env.REACT_APP_API_BASE || Hoot(),
  notificationSoundUrl = "/assets/sounds/notify.mp3",
  autoMarkOnOpen = true
}) {
  const [items, setItems] = useState([]);
  const [nextCursor, setNextCursor] = useState(null); 
  const [unread, setUnread] = useState(0);
  const [loading, setLoading] = useState(false);
  const [notifEnabled, setNotifEnabled] = useState(true);
  const [detail, setDetail] = useState(null);
  const [audioBlocked, setAudioBlocked] = useState(true);

  const socketRef = useRef(null);
  const audioRef = useRef(null);
  const firstLoadRef = useRef(false);

  const client = useMemo(() => {
    return axios.create({
      baseURL: apiBase.replace(/\/+$/, "") + "/",
      withCredentials: true,
      headers: { "Content-Type": "application/json" }
    });
  }, [apiBase]);

  /* ---------- audio ---------- */
  const playSound = useCallback(async () => {
    if (!notifEnabled || !audioRef.current) return;
    try {
      audioRef.current.currentTime = 0;
      await audioRef.current.play();
    } catch {
      setAudioBlocked(true);
    }
  }, [notifEnabled]);

  useEffect(() => {
    const unlockAudio = () => {
      if (!audioRef.current) return;
      audioRef.current
        .play()
        .then(() => {
          audioRef.current.pause();
          audioRef.current.currentTime = 0;
          setAudioBlocked(false);
          document.removeEventListener("click", unlockAudio);
          document.removeEventListener("keydown", unlockAudio);
        })
        .catch(() => {
          // mantém blocked true
        });
    };
    document.addEventListener("click", unlockAudio);
    document.addEventListener("keydown", unlockAudio);
    return () => {
      document.removeEventListener("click", unlockAudio);
      document.removeEventListener("keydown", unlockAudio);
    };
  }, []);

  /* ---------- helpers ---------- */
  const calcUnread = useCallback(
    (arr) => arr.reduce((acc, n) => acc + (n.seen ? 0 : 1), 0),
    []
  );

  const mergePage = useCallback(
    (page) => {
      setItems((prev) => {
        const map = new Map(prev.map((n) => [n.id, n]));
        page.forEach((n) => map.set(n.id, { ...map.get(n.id), ...n }));
        const merged = Array.from(map.values()).sort((a, b) => b.id - a.id);
        setUnread(calcUnread(merged));
        return merged;
      });
    },
    [calcUnread]
  );

  const fetchPage = useCallback(
    async (cursor = null) => {
      if (!currentUser?.id || !currentUser?.instituteCode) return;
      if (loading) return;
      setLoading(true);
      try {
        const res = await client.get("api/notifications", {
          params: { limit: 25, ...(cursor ? { cursor } : {}) }
        });
        if (res.data?.ok) {
          const data = res.data.data || [];
          mergePage(data);
          setNextCursor(res.data.nextCursor || null);
        }
      } catch {
        toast.error("Falha ao carregar notificações.", { style: { background: "#fff" } });
      } finally {
        setLoading(false);
      }
    },
    [client, loading, mergePage, currentUser]
  );

  const refreshUnreadCount = useCallback(async () => {
    try {
      const r = await client.get("api/notifications/unread-count");
      if (r.data?.ok && typeof r.data.count === "number") setUnread(r.data.count);
    } catch {}
  }, [client]);

  const markSeen = useCallback(
    async (ids) => {
      const idsArr = Array.isArray(ids) ? ids : [ids];
      if (!idsArr.length) return;
      try {
        await client.post("api/notifications/mark-seen", { ids: idsArr });
        setItems((prev) => {
          const up = prev.map((n) => (idsArr.includes(n.id) ? { ...n, seen: 1 } : n));
          setUnread(calcUnread(up));
          return up;
        });
      } catch {}
    },
    [client, calcUnread]
  );

  const markUnseen = useCallback(
    async (ids) => {
      const idsArr = Array.isArray(ids) ? ids : [ids];
      if (!idsArr.length) return;
      try {
        await client.post("api/notifications/mark-unseen", { ids: idsArr });
      } catch {}
      setItems((prev) => {
        const up = prev.map((n) => (idsArr.includes(n.id) ? { ...n, seen: 0 } : n));
        setUnread(calcUnread(up));
        return up;
      });
    },
    [client, calcUnread]
  );

  const markAllSeen = useCallback(async () => {
    try {
      await client.post("api/notifications/mark-all-seen");
      setItems((prev) => {
        const up = prev.map((n) => ({ ...n, seen: 1 }));
        setUnread(0);
        return up;
      });
    } catch {}
  }, [client]);

  const loadMySetting = useCallback(async () => {
    try {
      const r = await client.get("api/me/notifications");
      if (r.data?.ok) setNotifEnabled(Boolean(r.data.allow));
    } catch {}
  }, [client]);

  const toggleMySetting = useCallback(async () => {
    try {
      const r = await client.post("api/me/notifications/toggle");
      if (r.data?.ok) {
        setNotifEnabled(Boolean(r.data.allow));
        toast.success(r.data.allow ? "Notificações ativadas" : "Notificações desativadas", {
          style: { background: "#fff" }
        });
      }
    } catch {}
  }, [client]);

  /* ---------- socket ---------- */
  useEffect(() => {
    if (!currentUser?.id || !currentUser?.instituteCode) return;

    // carrega preferências antes
    loadMySetting();

    const s = io(apiBase, {
      withCredentials: true,
      transports: ["websocket"],
      auth: {
        userId: currentUser.id,
        instituteCode: currentUser.instituteCode
      }
    });
    socketRef.current = s;

    s.on("connect", () => {
      s.emit("join", {
        userId: currentUser.id,
        instituteCode: currentUser.instituteCode
      });
      if (!firstLoadRef.current) {
        firstLoadRef.current = true;
        fetchPage(null);
      }
      refreshUnreadCount();
    });

    s.on("notification:new", (payload) => {
      // não notificar a mim próprio
      if (payload?.actor_user_id && String(payload.actor_user_id) === String(currentUser.id)) return;

      const tempId = Date.now();
      const item = {
        id: tempId,
        audit_id: payload?.audit_id,
        actor_user_id: payload?.actor_user_id,
        actor_name: payload?.actor_name || "Utilizador",
        actor_avatar: payload?.actor_avatar || null,
        title: payload?.title || payload?.form || "Atividade",
        body_html: payload?.body_html || null,
        body_text: payload?.body_text || payload?.description || "",
        seen: 0,
        created_at: payload?.created_at || new Date().toISOString()
      };

      setItems((prev) => {
        const newList = [item, ...prev];
        setUnread(calcUnread(newList));
        return newList;
      });

      toast.custom(
        () => (
          <div
            style={{
              background: "#fff",
              border: "1px solid #eee",
              borderRadius: 10,
              minWidth: 360,
              maxWidth: 420,
              padding: 12,
              display: "flex",
              gap: 12,
              boxShadow: "0 10px 30px rgba(0,0,0,.06)"
            }}
          >
            <Avatar
              className="df"
              src={
                item.actor_avatar
                  ? Hoot() + item.actor_avatar
                  : currentUser?.avatar
                  ? Hoot() + currentUser.avatar
                  : undefined
              }
              sx={{ width: 44, height: 44 }}
            />
            <div style={{ flex: 1 }}>
              <div style={{ fontWeight: 600, fontSize: 14 }}>{item.actor_name}</div>
              <div style={{ fontSize: 13, opacity: 0.8 }}>
                {(item.body_text || "").slice(0, 70)}
                {(item.body_text || "").length > 70 ? "…" : ""}
              </div>
            </div>
          </div>
        ),
        { duration: 4500 }
      );

      if (!audioBlocked) playSound();
    });

    return () => {
      try {
        s.emit("leave", { userId: currentUser.id, instituteCode: currentUser.instituteCode });
        s.disconnect();
      } catch {}
    };
  }, [apiBase, currentUser, fetchPage, loadMySetting, playSound, refreshUnreadCount, audioBlocked]);

  // Primeiro carregamento se não tiver socket
  useEffect(() => {
    if (!socketRef.current && !firstLoadRef.current) {
      firstLoadRef.current = true;
      fetchPage(null);
    }
  }, [fetchPage]);

  const onOpenDetail = (n) => {
    setDetail(n);
    if (autoMarkOnOpen && !n.seen && n.id) markSeen(n.id);
  };

  const loadMore = () => {
    if (nextCursor && !loading) fetchPage(nextCursor);
  };

  return (
    <>
      <Toaster
        position="top-right"
        toastOptions={{
          style: { background: "#fff", color: "#111", border: "1px solid #eee" }
        }}
      />

      <audio ref={audioRef} src={notificationSoundUrl} preload="auto" />

      <MenuDropDown
        toggle_btn={
          <button className="nav-toggle" aria-label="Abrir notificações">
            <PiBellSimpleRingingBold />
            {!!unread && <Count className="count">{unread}</Count>}
          </button>
        }
        header={
          <Header>
            <div className="top">
              <h1 className="title">Notificações</h1>
              <div className="actions">
                <div className="form-check form-switch d-inline-flex align-items-center">
                  <input
                    className="form-check-input"
                    type="checkbox"
                    role="switch"
                    id="notifSwitch"
                    checked={notifEnabled}
                    onChange={toggleMySetting}
                  />
                  <label className="form-check-label ms-2" htmlFor="notifSwitch" title={notifEnabled ? "Desativar" : "Ativar"} />
                </div>
              </div>
            </div>

            <div className="sub">
              <button className="link text-main" onClick={markAllSeen}>
                Marcar todas como lidas
              </button>
              {audioBlocked && (
                <small style={{ color: "#7c3aed" }}>
                  Clique em qualquer parte para ativar o som das notificações.
                </small>
              )}
            </div>
          </Header>
        }
        content={
          <Body>
            {items.length === 0 && !loading && (
              <div className="empty">Nenhuma notificação encontrada</div>
            )}
            <ul className="list">
              {items.map((n) => (
                <li key={n.id} className={n.seen ? "" : "unread"}>
                  <Avatar
                    className="df"
                    src={n.actor_avatar ? Hoot() + n.actor_avatar : undefined}
                    sx={{ width: 35, height: 35 }}
                  />
                  <div className="block" onClick={() => onOpenDetail(n)}>
                    <div className="name">
                      <small>{n.actor_name || "Utilizador"}</small>
                      <span>
                        <strong>
                          <small className="grey-text ml-1">{n.title || "Atividade"}</small>
                        </strong>
                      </span>
                    </div>
                    <div className="small-info">
                      <small className="text-muted">{formatRelative(n.created_at)}</small>
                    </div>
                    {!!n.body_text && (
                      <div className="text grey-text">
                        {String(n.body_text).slice(0, 60)}
                        {String(n.body_text).length > 60 ? "…" : ""}
                      </div>
                    )}
                  </div>
                  <div className="row-actions">
                    {n.seen ? (
                      <button className="gHoot" onClick={() => markUnseen(n.id)} title="Marcar como não lida">
                        Não lida
                      </button>
                    ) : (
                      <button className="gHoot" onClick={() => markSeen(n.id)} title="Marcar como lida">
                        Lida
                      </button>
                    )}
                  </div>
                </li>
              ))}
            </ul>

            <div className="footer">
              {nextCursor ? (
                <button className="load" disabled={loading} onClick={loadMore}>
                  {loading ? "A carregar…" : "Carregar mais"}
                </button>
              ) : (
                <span className="end">{loading ? "A carregar…" : "— fim —"}</span>
              )}
            </div>
          </Body>
        }
      />

      {detail && (
        <DetailBackdrop onClick={() => setDetail(null)}>
          <DetailCard onClick={(e) => e.stopPropagation()}>
            <div className="head">
              <div className="who">
                <Avatar
                  className="df"
                  src={detail.actor_avatar ? Hoot() + detail.actor_avatar : undefined}
                  sx={{ width: 44, height: 44 }}
                />
                <div className="info">
                  <div className="name">{detail.actor_name || "Utilizador"}</div>
                  <div className="time">{formatDateTime(detail.created_at)}</div>
                </div>
              </div>
              <strong className="close cursor-pointer" onClick={() => setDetail(null)}>
                ×
              </strong>
            </div>

            <div className="tags">
              <span className="badge bg-danger">Ação #{detail.ed_auditory_action || "-"}</span>
              <span className="badge muted">{detail.title || detail.ed_auditory_form || "Atividade"}</span>
            </div>

            <div className="content">
              {detail.body_html ? (
                <div
                  className="html"
                  dangerouslySetInnerHTML={{
                    __html: String(detail.body_html).replace(/^```html\s*/i, "").replace(/```$/i, "").trim()
                  }}
                />
              ) : (
                <div className="text">{detail.body_text || detail.ed_auditory_description}</div>
              )}
            </div>

            <div className="buttons">
              {!detail.seen && (
                <button
                  className="primary"
                  onClick={() => {
                    markSeen(detail.id);
                    setDetail({ ...detail, seen: 1 });
                  }}
                >
                  Marcar como lida
                </button>
              )}
              {detail.seen && (
                <button
                  className="gHoot"
                  onClick={() => {
                    markUnseen(detail.id);
                    setDetail({ ...detail, seen: 0 });
                  }}
                >
                  Marcar como não lida
                </button>
              )}
              <button className="secondary" onClick={() => setDetail(null)}>
                Fechar
              </button>
            </div>
          </DetailCard>
        </DetailBackdrop>
      )}
    </>
  );
}

/* ---------- helpers ---------- */
function formatRelative(dateStr) {
  try {
    const d = new Date(dateStr || Date.now());
    const diff = (Date.now() - d.getTime()) / 1000;
    if (diff < 60) return "agora mesmo";
    if (diff < 3600) return `${Math.floor(diff / 60)} min atrás`;
    if (diff < 86400) return `${Math.floor(diff / 3600)} h atrás`;
    return d.toLocaleDateString();
  } catch {
    return "";
  }
}
function formatDateTime(dateStr) {
  try {
    const d = new Date(dateStr || Date.now());
    return d.toLocaleString();
  } catch {
    return "";
  }
}

/* ---------- styles ---------- */
const pulse = keyframes`
  0% { transform: scale(1); box-shadow: 0 0 0 0 rgba(124,58,237,.6); }
  70% { transform: scale(1.08); box-shadow: 0 0 0 12px rgba(124,58,237,0); }
  100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(124,58,237,0); }
`;
const Count = styled.div`
  background: #7c3aed;
  color: #fff;
  border-radius: 999px;
  padding: 2px 7px;
  font-size: 12px;
  margin-left: 6px; 
`;

const Header = styled.div`
  padding: 12px 16px;
  .top { display:flex; align-items:center; justify-content:space-between; gap:12px; }
  .title { margin:0; font-size:16px; font-weight:700; }
  .actions { display:flex; gap: 4px; align-items:center; }
  .sub { margin-top:6px; display:flex; justify-content:space-between; align-items:center; }
  .link { background: transparent; border: 0; color: var(--ed-main, #0d6efd); text-decoration: underline; cursor: pointer; font-size: 13px; padding: 0; }
`;

const Body = styled.div`
  width: 420px; max-width: 90vw; max-height: 70vh; overflow:auto; padding: 6px 0;
  .empty { padding:24px; text-align:center; color:#777; }
  .list { list-style: none; margin:0; padding:0; }
  .list > li {
    display:grid; grid-template-columns: 40px 1fr auto; gap:10px; padding:10px 14px;
    border-bottom: 1px solid #f4f4f4; align-items:flex-start;
  }
  .list > li.unread { background: #f4e8ff; } /* roxo leve */
  .block { cursor:pointer; }
  .name { font-weight: 600; display:flex; gap:6px; align-items:center; flex-wrap:wrap; }
  .small-info { font-size:12px; color:#777; margin-top:2px; }
  .text { font-size: 13px; margin-top: 6px; color:#444; }
  .row-actions .gHoot {
    border:1px solid #ddd; background:#fff; border-radius:8px; padding:6px 8px; font-size:12px; cursor:pointer;
  }
  .footer { display:flex; align-items:center; justify-content:center; padding:10px; }
  .load { border:1px solid #ddd; background:#fff; border-radius:10px; padding:8px 12px; cursor:pointer; }
  .end { font-size:12px; color:#aaa; }
`;

const DetailBackdrop = styled.div`
  position: fixed; inset: 0; background: rgba(0,0,0,.35);
  display:flex; align-items:center; justify-content:center; z-index: 10000;
`;
const DetailCard = styled.div`
  background:#fff; border-radius:16px; width:min(560px, 96vw);
  box-shadow: 0 30px 70px rgba(0,0,0,.15); padding:16px;
  .head { display:flex; align-items:center; justify-content:space-between; }
  .who { display:flex; align-items:center; gap:12px; }
  .info .name { font-weight:700; }
  .info .time { font-size:12px; color:#666; }
  .close { border:0; background:transparent; font-size:28px; line-height:1; cursor:pointer; }
  .tags { display:flex; gap:8px; margin:10px 0 6px; }
  .badge { background:#fff; border:1px solid #eee; border-radius:999px; padding:4px 10px; font-size:12px; }
  .badge.muted { color:#666; }
  .content { border:1px solid #f1f1f1; border-radius:12px; padding:12px; }
  .html :where(p,div,ul,ol,li,small,strong,em,span){ color:#333; }
  .text { color:#333; white-space: pre-wrap; }
  .buttons { display:flex; gap:10px; justify-content:flex-end; margin-top:12px; }
  .primary { background:#198754; color:#fff; border:0; border-radius:10px; padding:8px 12px; cursor:pointer; }
  .secondary { background:#e9ecef; color:#111; border:0; border-radius:10px; padding:8px 12px; cursor:pointer; }
  .gHoot { background:#fff; border:1px solid #ddd; border-radius:10px; padding:8px 12px; cursor:pointer; }
`;
