import React from 'react'
import { Link } from 'react-router-dom';
import styled from 'styled-components'
import Logo from  '../../Assets/images/logo-small-white.png';

function NavbarBussines() {
  return ( 
     <NavbarMenu>
         <menu className="ed-flex">
         <Link to='/WorkSpaces' >
            <div className="ed-flex">
                <div className='bg-main logo-menu'>
                    <img loading="lazy" role="presentation" src={Logo} alt="eduall" />
                </div>
                <h2 className="text-main">duallForBussiness</h2>
            </div>
          </Link>
          <div>
            
          </div>
        </menu> 
    </NavbarMenu>  
  )
}


const NavbarMenu = styled.div`
width:100%;
height:70px; 
position:fixed;
z-index:1000; 
top:0px;
left:0px;
padding:0px; 
display:flex;
align-items:center;
background:var(--ed-white);
justify-content:space-between;  
box-shadow:var(--ed-shadow-df);

.ed-flex{
   align-items:center;
   
 h2{
    font-size:25px;
    margin:0px;
 }
}

.logo-menu{
  min-width:45px;
  width:45px;
  height:45px;
  border-radius:6px;
  display:flex;
  align-items:center;
  justify-content:center;
  margin-right:5px;

     img{
         width:26px;
         height:26px;
         margin:0px;
     }
}

menu { 
  margin:0px !important; 
  padding:10px 20px;
  align-items:center;
  height:100%; 
}

`;

export default NavbarBussines
