import React, { useEffect, useState } from 'react'
import Chart from 'react-apexcharts'
import Hoot from '../../../../General/components/Hoot'
import axios from 'axios'
import Loader from '../../../../General/components/Loader'
import styled from 'styled-components'

function StudentsNByAcademicLevelChart() {
  const [data, setData] = useState([])
  const [loaded, setLoaded] = useState(false)

  async function loadData() {
    try {
      const [academicLevel_response, class_response, students_response] =
        await Promise.all([
          axios.get(Hoot() + 'eduallacademiclevelsapi/get'),
          axios.get(Hoot() + 'eduallclassapi/get'),
          axios.get(Hoot() + 'eduallstudentsapi/get')
        ])

      const academicLevels = academicLevel_response.data || []
      const classes = class_response.data || []
      const students = students_response.data || []

      const ChartOptions = {
        series: [
          { name: 'Masculino', data: [] },
          { name: 'Feminino', data: [] }
        ],
        options: {
          chart: { type: 'bar', height: 350 },
          colors: ['var(--ed-purple-light)', 'var(--ed-green)'],
          plotOptions: {
            bar: { horizontal: false, columnWidth: '55%', endingShape: 'rounded' }
          },
          dataLabels: { enabled: false },
          stroke: { show: true, width: 2 },
          xaxis: { categories: [] },
          yaxis: { title: { text: 'Estudantes' } },
          fill: { opacity: 1 },
          tooltip: {
            y: { formatter: val => val + ' estudantes' }
          }
        }
      }

      // Criar mapa de níveis académicos
      const levelMap = new Map()
      academicLevels.forEach(level => {
        levelMap.set(Number(level.ed_academic_level_id), {
          level_title: level.ed_academic_level_title,
          students: new Set(),
          gender: [new Set(), new Set()] // masculino, feminino
        })
      })

      // Agrupar classes por nível académico
      const classesByLevel = new Map()
      classes.forEach(CL => {
        const levelId = Number(CL.ed_class_academic_level)
        if (!classesByLevel.has(levelId)) classesByLevel.set(levelId, [])
        classesByLevel.get(levelId).push(CL.ed_class_id)
      })

      // Garantir que estudantes são únicos
      const uniqueStudents = new Map()
      students.forEach(student => uniqueStudents.set(student.ed_student_id, student))

      // Distribuir estudantes por nível correto
      Array.from(uniqueStudents.values()).forEach(student => {
        const studentClassId = student.ed_student_class
        for (let [levelId, classIds] of classesByLevel.entries()) {
          if (classIds.includes(studentClassId)) {
            const levelEntry = levelMap.get(levelId)
            if (levelEntry) {
              levelEntry.students.add(student.ed_student_id)

              const gender = (student.ed_student_gender || '').toLowerCase()
              const genderIndex = gender === 'male' || gender === 'masculino' ? 0 : 1
              levelEntry.gender[genderIndex].add(student.ed_student_id)
            }
            break
          }
        }
      })

      // Preparar dados para o gráfico
      const levels = Array.from(levelMap.values())
      ChartOptions.options.xaxis.categories = levels.map(l => l.level_title)
      ChartOptions.series[0].data = levels.map(l => l.gender[0].size)
      ChartOptions.series[1].data = levels.map(l => l.gender[1].size)

      setData(ChartOptions)
      setLoaded(true)
    } catch (error) {
      console.clear()
      console.log(error)
      setLoaded(true)
    }
  }

  useEffect(() => { loadData() }, [])

  return (
    <Container>
      {!loaded ? <Loader absolute small /> :
        data.options ? <Chart options={data.options} series={data.series} type="bar" height={350} /> : null
      }
    </Container>
  )
}

const Container = styled.div`
  min-height: 350px;
  position: relative;
  width: 99%;
`

export default StudentsNByAcademicLevelChart
