
import React, { useState, useEffect } from 'react';
import Alert from 'react-bootstrap/Alert';
import Form from 'react-bootstrap/Form'
import styled from "styled-components";
import FormControlLabel from '@mui/material/FormControlLabel';
import Checkbox from '@mui/material/Checkbox';
import Color from '../Dashboard/components/elements/Color';
import axios from 'axios';
import Hoot from '../General/components/Hoot';
import jwt_decode from 'jwt-decode';
import { Link } from 'react-router-dom';
import { useHistory } from "react-router-dom";
import Loader from '../General/components/Loader';
import { Avatar } from '@mui/material';
import AvatarImg from '../Assets/images/avatars/avatar-6.jpg';
import CoverImg from '../Assets/images/svg/cover.png';
import { AdminPanelSettings, CloseOutlined, Remove } from '@mui/icons-material';
import { Close } from '@material-ui/icons';
import Tooltip from '../General/components/Tooltip';
import NewspaperIcon from '@mui/icons-material/Newspaper';
import CastForEducationIcon from '@mui/icons-material/CastForEducation';
import SaveButton from '../Dashboard/components/elements/SaveButton';
import { FcGoogle } from "react-icons/fc";
import { FaFacebook, FaLinkedinIn, FaGithub } from "react-icons/fa";
import { IoClose, IoAddOutline } from "react-icons/io5";
import RandomColor from '../General/components/RandomColor';
import MainAuthScreen from './MainAuthScreen';
import LoginModal from './LoginModal';
import GoogleOneTap from './GoogleOneTap';
import { Swiper, SwiperSlide } from 'swiper/react';
import { WarningOutline } from 'react-ionicons'

const Login = () => {
  const [messageWarning, setMessagewarning] = useState(null);
  const [show, setShow] = useState(true);
  const [showScreen, setShowScreen] = useState(null);
  const [ed_email, setEd_email] = useState(null);
  const [ed_password, setEd_password] = useState(null);
  const [loading, setLoading] = useState(true);
  const [Checked, setChecked] = useState(false);
  const navigate = useHistory();
  const [switchuser, SetSwitchUser] = useState(false);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [LatestLoggedinUsers, SetLatestLoggedinUsers] = useState([]);
  let list = localStorage.getItem("eduall_local_credencials") !== null ?
    JSON.parse(localStorage.getItem("eduall_local_credencials")) : [];
  document.title = "eduall";


  const [Text, setText] = useState("")

  useEffect(() => { 
    CheckLogin();
    setTimeout(() => {
      GetValue();
    }, 2000);
  }, []);





  const CheckLogin = async (e) => {
    try {
      const response = await axios.get(Hoot() + 'token');
      const decoded = jwt_decode(response.data.accessToken);
      setShowScreen(false);

      if (decoded.cr_usertype !== null) {
        setRegisterStatus(2);
        setTimeout(() => {
          if (Checked) { AddNewCredencial(ed_email, ed_password); }
          if (decoded.cr_usertype === 1) {
            navigate.push("/WorkSpaces");
          } else {
            const tenantURL = getTenantURL(decoded.cr_institutecode);
            navigate.push('/dashboard');
          }
        }, 1000);
      } else {
        setRegisterStatus(1);
        setMessagewarning("Erro ao estabelecer ligação com o servidor 1 !");
      }

    } catch (error) {
      if (e === 1) {
        if (error.response) {
          if (error.response.data) {
            setRegisterStatus(1);
            setMessagewarning(error.response.data.msg);
          }
        } else {
          setRegisterStatus(1);
          setMessagewarning('Não foi possível concluir a operação. Tente novamente em instantes ! 2 !');
        }
      }
      setShowScreen(true);
      localStorage.removeItem("CurrentTab");
      localStorage.removeItem("CurrentPage");
    }
  }



  const GetValue = async () => {

  }


  function hideMessage() {
    setMessagewarning(null);
    setShow(false);
  }

  function getTenantURL(tenantCode) {
    const { protocol, hostname, port } = window.location;
    const baseDomainParts = hostname.split('.');
    if (hostname === "localhost" || hostname.match(/localhost/)) {
      return `${protocol}//${tenantCode}.localhost${port ? `:${port}` : ''}`;
    }
    if (baseDomainParts.length > 2) {
      baseDomainParts.shift();
    }
    const baseDomain = baseDomainParts.join('.');
    return `${protocol}//${tenantCode}.${baseDomain}${port ? `:${port}` : ''}`;
  }


  const Signin = async (e_mail, password) => {
    let Nemail = (e_mail === null) ? ed_email : e_mail;
    let Npassword = (password === null) ? ed_password : password;

    setMessagewarning(null);
    setRegisterStatus(0);
    try {
      if (Nemail === null || Npassword === null) {
        setMessagewarning("Preencha corretamente os campos !");
        setRegisterStatus(1);
      } else {
        await axios.post(Hoot() + "login",
          { ed_user_account_email: Nemail, ed_user_account_password: Npassword }, { withCredentials: true }).then((e) => {

            hideMessage();


            if (e.data.accessToken) {
              setTimeout(() => {
                setTimeout(() => {
                  const decoded = jwt_decode(e.data.accessToken);
                  setShowScreen(false);

                  setRegisterStatus(1);

                  if (decoded.cr_usertype !== null) {
                    setRegisterStatus(2);
                    if (Checked) { AddNewCredencial(ed_email, ed_password); }
                    if (decoded.cr_usertype === 1) {
                      window.location.replace("/WorkSpaces");
                    } else {
                      const tenantURL = getTenantURL(decoded.cr_institutecode);
                      console.clear()
                      console.log(decoded);
                      window.location.replace("/dashboard");
                    }
                  } else {
                    setRegisterStatus(1);
                    setMessagewarning("Erro ao estabelecer ligação com o servidor 1 !");
                  }

                }, 100);
              }, 100);
            } else {
              setRegisterStatus(1);
              setMessagewarning("Não foi possível concluir a operação neste momento !");
            }


          }).catch((error) => {

            setRegisterStatus(1);
            setMessagewarning('Não foi possível concluir a operação. Tente novamente em instantes ! !');

            if (error.response) {
              if (error.response.data) {
                setRegisterStatus(1);
                setMessagewarning(error.response.data.msg);
              } else {
                setRegisterStatus(1);
                setMessagewarning('Não foi possível concluir a operação. Tente novamente em instantes ! 3 !');
              }
            } else {
              setRegisterStatus(1);
              setMessagewarning('Não foi possível concluir a operação. Tente novamente em instantes ! !');
            }
          });
      }
    } catch (error) {
      if (error.response) {
        if (error.response.data) {
          setRegisterStatus(1);
          setMessagewarning(error.response.data.msg);
        } else {
          setRegisterStatus(1);
          setMessagewarning("Erro ao estabelecer ligação com o servidor 4 !");
        }
      } else {
        setRegisterStatus(1);
        setMessagewarning("Erro ao estabelecer ligação com o servidor 5 !");
      }
    }

  }


  const Auth = async (e) => {
    e.preventDefault();
    Signin(null, null);
  }





  function AuthStored(email, password) {
    setEd_email(email);
    setEd_password(password);
    Signin(email, password);
  }


  const GoogleAuth = async () => {
    window.open(Hoot() + "eduallgoogleuserauthentication/signin", "_self");
  }


  const FacebookAuth = async () => {
    window.open(Hoot() + "eduallfacebookuserauthentication/signin", "_self");
  }


  const handleInput = (e) => {
    switch (e.target.id) {
      case "ed_user_account_email":
        setEd_email(e.target.value);
        break;
      case "ed_user_account_password":
        setEd_password(e.target.value);
        break;
      default:
    }
  }







  /*  account storage */

  const AddNewCredencial = (email, password) => {
    let StoredCredencials = [];
    if (typeof list !== "object") { list = []; }
    if (list.length === 0) {
      StoredCredencials.push({ ed_password: password, ed_email: email.toLowerCase(), ed_image: "" });
    } else {
      if (list.length > 0) {
        for (let i = 0; i < list.length; i++) {
          StoredCredencials.push(list[i]);
        }
      }
      if (CheckExistentUser(email.toLowerCase())) {
        StoredCredencials.push({ ed_password: password, ed_email: email.toLowerCase(), ed_image: "" });
      } else {
        console.log("already added");
      }
    }

    localStorage.setItem("eduall_local_credencials", JSON.stringify(StoredCredencials));
    list = JSON.parse(localStorage.getItem("eduall_local_credencials")); 
    return true;
  }

  const RemoveStoredCredencial = (email) => {
    if (typeof list !== "object") { list = []; }
    let x = null;
    for (let i = 0; i < list.length; i++) {
      if (list[i].ed_email.toLowerCase() === email.toLowerCase()) {
        x = i;
      }
    }

    if (x !== null) {
      list.splice(x, 1);
      let newData = list;
      localStorage.setItem("eduall_local_credencials", JSON.stringify(newData));
      list = JSON.parse(localStorage.getItem("eduall_local_credencials"));
      console.log("****************************************************")
      console.log(list) 
    }
  }

  const CheckExistentUser = (e) => {
    if (typeof list !== "object") { list = []; }
    if (list !== null && list.length >= 1) {
      const found = list.some(el => el.ed_email.toLowerCase() === e);
      if (!found) return true;
    }
    return false;
  }


 
  /*end **/


  function RemindChecked(e) {
    setChecked(e.target.checked);
  }



async function GetViews() {
  try {
    const result = await axios.post(
      Hoot() + "login",
      {
        ed_user_account_email: "kiossocamuegi",
        ed_user_account_password: "123Eduall##"
      },
      {
        withCredentials: true
      }
    );

    console.clear()
    console.log("✅ Sucesso:", result?.data);
  } catch (error) {
    console.clear()
    if (error.response) {
      console.error("❌ Erro (response):", error.response.data);
    } else if (error.request) {
      console.error("❌ Erro (request, sem resposta):", error.request);
    } else {
      console.error("❌ Erro (configuração):", error.message);
    }
  }
}



  return (
    <MainAuthScreen content={
      <div>
        <section>
          <div className="form-area nav-theme"> 
            <h1 className="theme-light-txt" >Entrar</h1>
            <p>Entre na sua conta ou crie uma conta. Ao continuar, você indica que concorda com os
              Termos de Uso e a Política de Privacidade da eduall.</p>
            <div className="form-message">
              {messageWarning !== null ? <Alert dismissible variant='danger' onClose={() => hideMessage()}>
                <div className="ed-flex"><WarningOutline /><h5 className='text-danger'> {messageWarning} </h5></div>   </Alert> : ''}
            </div>
            <Form onSubmit={Auth}>
              <>
                <Form.Group className="mb-3" >
                  <Form.Label className="theme-light-txt">Email ou nome de usuário</Form.Label>
                  <Form.Control onChange={handleInput} value={ed_email} id="ed_user_account_email" type="text" className='mb-2' required placeholder="Email ou nome de usuário" />
                </Form.Group>
                <Form.Group className="mb-3">
                  <Form.Label className="theme-light-txt">Password</Form.Label>
                  <Form.Control onChange={handleInput} id="ed_user_account_password" value={ed_password} type="password" required placeholder="Password" />
                </Form.Group>
              </>
              <div className="ed-space">
                <div>
                  <div >
                    <FormControlLabel  className="theme-light-txt" onChange={(e) => RemindChecked(e)} control={<Checkbox />} label="Lembrar sempre" />
                  </div>
                </div>
                <div> <small><Link to='/forgot_password' className='text-main'>Esqueceu a sua palavra-passe ?</Link></small> </div>
              </div>
              <SaveButton class='btn mt-2 bg-main text-light' title={'Entrar'} status={RegisterStatus} />
            </Form>
            <div >
            <div >
            <div className="or mt-2 theme-light-txt">
                <div className="ln"></div>
                ou
                <div className="ln"></div>
              </div>
              <div className="ed-center mt-2">
                <GoogleOneTap
                  setShowScreen={setShowScreen}
                  setRegisterStatus={setRegisterStatus}
                  setMessagewarning={setMessagewarning}
                  hideMessage={hideMessage}
                />
              </div>
            </div>
              <br />
              <div className="d-flex">
                <small className="theme-light-txt">
                  Não tem uma conta ?<Link to='/signup' className='text-main ml-2'>Cadastre-se</Link>
                </small>
              </div>
            </div>
          </div>
          {LatestLoggedinUsers.length >= 1000 ?
            <div className="latest-accounts">
              <ul>
                <LoginModal toggle_btn={
                  <li>
                    <div className="icon bg-main">
                      <IoAddOutline />
                    </div>
                  </li>
                } />
                {LatestLoggedinUsers.map((item, index) => {
                  const emailRegexp = /^[a-zA-Z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?(?:\.[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?)*$/;
                  if (emailRegexp.test(item.ed_email)) {
                    return (
                      <li key={index}>
                        <div className="bg-white remove" onClick={() => RemoveStoredCredencial(item.ed_email)}><IoClose /></div>
                        <div onClick={() => AuthStored(item.ed_email, item.ed_password)}>
                          <Avatar variant="rounded" src={item.ed_image} className='df'
                            alt={(item.ed_email.split("")[0]).toUpperCase()}
                            sx={{ width: 50, height: 50 }} />
                        </div>
                      </li>
                    )
                  } else {
                    return (
                      <li key={index}>
                        <div className="admin"><AdminPanelSettings /></div>
                        <div className="bg-white remove" onClick={() => RemoveStoredCredencial(item.ed_email)}><IoClose /></div>
                        <div onClick={() => AuthStored(item.ed_email, item.ed_password)}>
                          <Avatar variant="rounded" src={item.ed_image} className='df'
                            alt={(item.ed_email.split("")[0]).toUpperCase()}
                            sx={{ width: 50, height: 50 }} />
                        </div>
                      </li>
                    )
                  }
                })}
              </ul>
            </div>
            : <></>}
        </section>
      </div>
    } />
  );
}


export default Login;