import axios from 'axios';
import React, { useEffect, useImperativeHandle, useState } from 'react'
import { forwardRef } from 'react';
import { Table } from 'react-bootstrap'
import Hoot from '../../../General/components/Hoot';
import { GetSchoolNotes, GetSubject } from '../../../General/components/InstituteData';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';

const TABLEURL = [ 
    Hoot()+"eduallsingleclassapi/get/"
];

const  PDStudentMarksByQuarterTable = forwardRef((props, ref)=>{
  const Class = props.ClassId ? props.ClassId : 0;
  const StudentCode = props.StudentCode ? props.StudentCode : null;  
  const Quarter = props.Quarter ? props.Quarter : null; 



  const [CurrentSubjects , SetCurrentSubjects]= useState([]); 
  const [load, setLoaded] = useState(false);
  
  async function loadData(){ 
    try {
        const response2 = await axios.get(TABLEURL[0]+`${Class}`);
        if(Class !== 0) SetCurrentSubjects(response2.data.length >= 1 ? response2.data[0].ed_class_subjects.split(',')  : []); 
    } catch(error){
      
    }
   };

    useEffect(()=>{ 
        loadData(); 
    },[]);  

    useImperativeHandle(ref, ()=>({
    RunGetNotes(){
      console.log("printing the class code : "+Class);
      loadData();
    }
  }))
    
    
  return (
    <div>
        <Table striped={props.nostriped  ? false : true } responsive bordered>
       <thead>
          <tr className='text-left'>
              <th rowSpan="2">Nº</th>
             <th  style={{minWidth:'300px'}} className='text-left' rowSpan="2" >Disciplinas</th>    
          </tr>  
          <tr className='text-center'>
            <th>MAC{Quarter*1}</th>
            <th>NPP{Quarter*1}</th>
            <th>NPT{Quarter*1}</th>
            <th>MT{Quarter*1}</th> 
          </tr>
        </thead>
          <tbody>
               
               {
               CurrentSubjects.map((item, index)=>{
                  return  <tr>
                       <td>{index+1}</td>
                       <td className='text-left'><GetSubject ID={item} /></td> 
                         <td className="text-center">{StudentCode  !== null ? <GetSchoolNotes quarter={Quarter} class={Class} student={StudentCode ? StudentCode : 0} subject={item} type={1} />: <span className='text-warning'>#</span>} </td>
                         <td className="text-center">{StudentCode  !== null ? <GetSchoolNotes quarter={Quarter} class={Class} student={StudentCode ? StudentCode : 0} subject={item} type={2} />: <span className='text-warning'>#</span>} </td>
                         <td className="text-center">{StudentCode  !== null ? <GetSchoolNotes quarter={Quarter} class={Class} student={StudentCode ? StudentCode : 0} subject={item} type={3} />: <span className='text-warning'>#</span>} </td>
                         <td className="text-center">{StudentCode  !== null ? <GetSchoolNotes quarter={Quarter} class={Class} student={StudentCode ? StudentCode : 0} subject={item} type={4} />: <span className='text-warning'>#</span>} </td>
                   </tr>  
               })
             }  
          </tbody> 
        </Table>
        <br />
    </div>
  )
})

export default PDStudentMarksByQuarterTable; 