// FAZER SCROOLL PARA O FINAL DO .ai-chat-box-list ao enviar mensagem e ao listar


import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';
import Hoot from '../components/Hoot';
import { IoSparklesOutline, IoCopyOutline, IoStopOutline } from 'react-icons/io5';
import { PiBrainLight } from 'react-icons/pi';
import MenuDropDown from '../components/MenuDropDown';
import moment from 'moment';
import 'moment/locale/pt';
import  toast  from 'react-hot-toast';
import 'react-toastify/dist/ReactToastify.css';
import { FaStopCircle } from 'react-icons/fa';
import { CgCloseO } from "react-icons/cg";


moment.locale('pt');

function EDChatBot() {
    const [input, setInput] = useState('');
    const [chat, setChat] = useState([]);
    const [isTyping, setIsTyping] = useState(false);
    const [expandedMsgs, setExpandedMsgs] = useState({});
    const [controller, setController] = useState(null);
    const [timestamps, setTimestamps] = useState([]);
    const [closeChat, SetcloseChat]  = useState(false);
    const chatListRef = useRef(null);

    const MAX_LENGTH = 300;


    const scrollToBottom = () => {
        if (chatListRef.current) {
          chatListRef.current.scrollTop = chatListRef.current.scrollHeight;
        }
      };

    useEffect(() => {
        const fetchConversations = async () => {
            try {
                const res = await axios.get(Hoot() + 'eduallgeminiallconversations', { withCredentials: true });
                const formatted = res.data.map(item => ([
                    { sender: 'user', text: item.ed_ai_chat_message, timestamp: item.ed_ai_chat_created_at },
                    { sender: 'bot', text: item.ed_ai_chat_reply, timestamp: item.ed_ai_chat_created_at }
                ])).flat();
                setChat(formatted);
            } catch (err) {
                console.error('Erro ao carregar histórico', err);
            }
        };
        fetchConversations();
        setTimeout(() => {
            scrollToBottom();
        }, 1500);
    }, []);

    const sendMessage = async () => {
        if (!input.trim()) return;

        const now = new Date();
        const userMsg = { sender: 'user', text: input, timestamp: now };
        setChat(prev => [...prev, userMsg]);
        setTimestamps(prev => [...prev, now]);
        setInput('');
        setIsTyping(true);

        const ctrl = new AbortController();
        setController(ctrl);

        try {
            const res = await axios.post(
                Hoot() + 'eduallgeminiiarequest/post',
                { message: input },
                { withCredentials: true, signal: ctrl.signal }
            );
            const aiMsg = { sender: 'bot', text: res.data.reply, timestamp: new Date() };
            setChat(prev => [...prev, aiMsg]);
        } catch (error) {
            if (axios.isCancel(error)) {
                console.log('Requisição cancelada');
            } else {
                setChat(prev => [...prev, { sender: 'bot', text: 'Erro ao comunicar com a IA', timestamp: new Date() }]);
            }
        } finally {
            setIsTyping(false);
        }
    };

    const stopTyping = () => {
        if (controller) controller.abort();
        setIsTyping(false);
    };

    const toggleExpand = (index) => {
        setExpandedMsgs(prev => ({
            ...prev,
            [index]: !prev[index]
        }));
    };

    const closeDrop = ()=>{
        SetcloseChat(true);
        setTimeout(() => {
           SetcloseChat(false);
        }, 2000);
    }
 

      useEffect(() => {
        scrollToBottom();
        setTimeout(() => {
            scrollToBottom();
        }, 2000);
      }, [chat, isTyping]);
      

      function ScrollDown(params) {
        setTimeout(() => {
            scrollToBottom();
        }, 1000);
      }

    const copyToClipboard = (text) => {
        navigator.clipboard.writeText(text);
        toast.success('Texto copiado com sucesso!');
    };

    return (
        <div className='ai-chat'> 
            <div className='ed-chat-widget'>
                <div className="ed-chat-widget-container">
                    <aside>
                        <MenuDropDown
                          closeItem={closeChat}
                            toggle_btn={
                                <div className="toggle-chat-widget bg-main text-light ed-flex ed-center">
                                   <div onClick={ScrollDown} >
                                      <IoSparklesOutline  />
                                   </div>
                                </div>
                            }
                            ChatBox="true"
                            content={
                                <section className='ai-chat-body'>
                                    <div className="chat-box-area">
                                        <div className="ai-chat-header bg-main col text-light ed-flex ed-center ed-space">
                                          <div className="ed-flex">  <PiBrainLight /><strong className="ml-1">Eduall AI</strong></div>
                                          <div className="ed-flex">
                                            <div onClick={()=>closeDrop()} className='close-ai-chat-button'><CgCloseO size="1.5em" /></div>
                                          </div>
                                        </div>
                                        <div className='ai-chat-box-list' ref={chatListRef}>
                                            {chat.map((msg, i) => {
                                                const isLong = msg.text.length > MAX_LENGTH;
                                                const isExpanded = expandedMsgs[i];
                                                const displayText = isExpanded || !isLong ? msg.text : msg.text.slice(0, MAX_LENGTH) + '...';
                                                const isUser = msg.sender === 'user';
                                                const relativeTime = moment(msg.timestamp).fromNow();

                                                return (
                                                    <div key={i} style={{
                                                        display: 'flex',
                                                        justifyContent: isUser ? 'flex-end' : 'flex-start',
                                                        marginBottom: 8
                                                    }}>
                                                        <div className={`ai-chat-box ${isUser ? 'bg-main text-light' : 'bot'} p-2`}
                                                            style={{
                                                                maxWidth: '75%',
                                                                borderRadius: 12,
                                                                whiteSpace: 'pre-wrap',
                                                                overflowX: 'auto',
                                                                position: 'relative'
                                                            }}>
                                                            <div style={{ fontSize: 12, opacity: 0.5 }}>{relativeTime}</div>
                                                            <div style={{ whiteSpace: 'pre-wrap' }}>{displayText}</div>
                                                            <div className='ed-space'>
                                                                <div>
                                                                    {isLong && !isExpanded && (
                                                                        <div>
                                                                            <button className='text-main underline'
                                                                                onClick={() => toggleExpand(i)}
                                                                                style={{
                                                                                    marginTop: 5,
                                                                                    background: 'none',
                                                                                    border: 'none',
                                                                                    cursor: 'pointer',
                                                                                    fontSize: 14
                                                                                }}
                                                                            >
                                                                                Ver mais
                                                                            </button>
                                                                        </div>
                                                                    )}
                                                                </div>
                                                                {!isUser && (
                                                                    <div className="ed-flex ed-between mt-1">
                                                                        <div></div>
                                                                        <div onClick={() => copyToClipboard(msg.text)}
                                                                            className="cursor-pointer"
                                                                            title="Copiar resposta">
                                                                            <IoCopyOutline />
                                                                        </div>
                                                                    </div>
                                                                )}
                                                            </div>
                                                        </div>
                                                    </div>
                                                );
                                            })}

                                            {isTyping && (
                                                <div style={{ display: 'flex', justifyContent: 'flex-start', marginBottom: 8 }}>
                                                    <div className='bot ai-chat-box p-2' style={{
                                                        maxWidth: '75%',
                                                        borderRadius: 12
                                                    }}>
                                                      <div className="spinner-border spinner-border-sm text-secondary mr-1" role="status" /> Pensando... 
                                                    </div>
                                                </div>
                                            )}
                                        </div>

                                        <div className="ai-chat-form col mt-2">
                                            <div style={{ display: 'flex', gap: 8 }}>
                                                <input
                                                    className='form-control'
                                                    value={input}
                                                    onChange={e => setInput(e.target.value)}
                                                    onKeyDown={e => e.key === 'Enter' && sendMessage()}
                                                    placeholder="Digite algo interessante ..."
                                                    style={{ flex: 1, padding: 10 }}
                                                />
                                                {!isTyping ? (
                                                    <button className='btn bg-main text-light' onClick={sendMessage}>
                                                        Enviar
                                                    </button>
                                                ) : (
                                                    <button className='btn btn-icon  bg-danger' onClick={stopTyping} title="Parar resposta">
                                                        <FaStopCircle />
                                                    </button>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                </section>
                            }
                        />
                    </aside>
                </div>
            </div>
        </div>
    );
}

export default EDChatBot;
