import React, {useState} from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import {Modal, Form, Button} from 'react-bootstrap'
import { Password, Save, Update } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';

function NewUserAccount(props) {
    const [show, setShow] = useState(false); 
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [Founded, SetFounded] = useState(null);

         
    const [showBox, SetshowBox]  = useState(false);
    const handleClose = () => {
      SetshowBox(false);
      setTimeout(() => {
        setShow(false);
      }, 1200);
    } 

    const handleShow = () => {
          SetshowBox(true);
          setShow(true);  
          setTimeout(() => {  
             
         }, 1000);   
    };

    
  return (
    <div>
    <button className='btn btn-main bg-main' onClick={handleShow}>
        <AddCircleOutlineIcon/> Registrar novo usuário
   </button> 
    <Modal  centered size='lg'  className={showBox ? ModalAnimationShow() : ModalAnimationClose()}  dialogAs={DraggableModal}  show={show} onHide={handleClose}>
    <Modal.Header closeButton>
      <Modal.Title>
        <div className="ed-wrap align-center">
            <UserOptionDropDown />
            <h5> Registrar novo usuário</h5>
        </div>   
      </Modal.Title>
    </Modal.Header>
    <Form>
    <Modal.Body className='scrollLimit'>
        <Form.Group className="mb-3">
          <Form.Label>Nome de usuário<span className="text-danger">*</span> </Form.Label>
          <Form.Control required type="text" autoFocus/>
        </Form.Group>
        <Form.Group className="mb-3">
          <Form.Label>Código de funcionário<span className="text-danger">*</span> </Form.Label>
          <Form.Control required type="text" autoFocus/>
        </Form.Group>
        <Form.Group className="mb-3">
          <Form.Label>Email<span className="text-danger">*</span></Form.Label>
          <Form.Control type="text" required/>
        </Form.Group> 
        <Form.Group className="mb-3"  >
          <Form.Label>Nivel de Acesso<span className="text-danger">*</span></Form.Label>
          <Form.Select>
               <option value="0">Superadmin</option>
               <option value="1">Admin</option>
               <option value="2">Professor</option> 
          </Form.Select>
        </Form.Group> 
       <div className="ed-flex password-generator">
           <Form.Group className="mb-3"  >
             <Form.Label>Senha <span className="text-danger">*</span></Form.Label>
             <Form.Control readOnly disabled value='' type="password" required/>
         </Form.Group> 
         <button className='bg-primary btn'><Password/></button>
       </div>
    </Modal.Body>
    <Modal.Footer>
    <div className="ed-space">
        <div className="ed-flex"></div>
        <div className="ed-flex">
        <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button> 
      {props.update ? (Founded === false ? <div></div>  : 
      <SaveButton icon={props.title ? <Update/> : <Save/>} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
      <SaveButton icon={props.title ? <Update/> : <Save/>} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />} 
        </div>
    </div>
    </Modal.Footer>
    </Form>
  </Modal>
   </div>
  )
}

export default NewUserAccount