import React, { useEffect, useState } from 'react'
import { BiSend, BiSmile, BiSticker, BiSolidFile } from 'react-icons/bi'
import {MdAttachFile} from "react-icons/md";
import {FiSend} from "react-icons/fi";
import GifPicker from 'gif-picker-react';
import InputEmoji from 'react-input-emoji'
import CheckinternetStatus from '../../components/CheckinternetStatus';
import Hoot from '../../components/Hoot';
import { toast } from 'react-hot-toast';
import axios from 'axios';
import RandomCodeGenerator from '../../components/RandomCodeGenerator';
import { TextOutline } from 'react-ionicons'
import { SendOutline } from 'react-ionicons'
import { AttachOutline } from 'react-ionicons'
import { TrashBinOutline } from 'react-ionicons'
import { CloseOutline } from 'react-ionicons'
import ImageLazyLoading from '../../components/ImageLazyLoading';
import { CloudUploadOutline } from 'react-ionicons'
import { FileUploader } from "react-drag-drop-files";

const fileTypes = ["JPG", "PNG", "GIF"];


function ChatForm(props) {
  const [show, setShow] = useState(false);
  const [GifItem , setGifItem] = useState(null);
  const [MessageText, setMessageText] = useState("");
  const [CurrentUserData, setCurrentUserData] = useState(null);
  const URL = Hoot()+"eduallcreatechatmessage/post/";
  const [file, setFile] = useState(null);
  const socket = props.socket;
  const handleChange = (file) => {
    setFile(file);
  };


  const [fileList, setFileList] = useState([]); 
  let UploadedFiles  = [];

  const InputChange = (e)=>{  
     /*setFileList(e);  
     console.clear();*/
     console.log(e.target.files);  
  }

  const ClearFiles = ()=>{
     setFileList([]); 
  }

 const Images = [];
 
  useEffect(()=>{
    setCurrentUserData(props.CurrentChatUser);
  },[props]);
  
  
   
 

 const validateForm = ()=>{ 
   const NewErrors = {}; 
   return NewErrors;
}


 const FormSubmit = (e)=>{   
      let Code  =  `${socket.id}${RandomCodeGenerator(1000)}`;

       const Message_Data = {
          chat_msg_code:Code,  
          chat_msg_to:CurrentUserData.contact_id,
          chat_msg_group_code:0, 
          chat_msg_content:MessageText, 
          chat_msg_gif:(e !== undefined && e !== null) ? e : GifItem,
          chat_msg_files:[],
          socketID: socket.id,
       };  
        
        try { 
          socket.emit('eduall_send_chat_messageIo', Message_Data);   
          console.clear();
          console.log(Message_Data);
          setMessageText(null);
          setGifItem(null); 

        } catch (error) {
          console.clear()
          console.log(error);
          toast.error("Ocorreu um erro ao enviar a mensagem !")
        }  
 };
 


  const getGifImage = (e)=>{  
     console.log(e.preview.url);
     setGifItem(e.preview.url);
     setShow(false); 
     FormSubmit(e.preview.url);
  }


  function handleMessageText(text) {
    setMessageText(text); 
  }  

  function handleOnEnter(){ 
    FormSubmit();
  }

  return (
    <div className='chat-messages-form'> 
    <div className="upload-area d-none">
      <div className="upload-header  ed-space ed-flex">
         <div><h3 className="title">Anexar ficheiros</h3> </div>
         <div><button className="btn"><CloseOutline/></button></div>
      </div>
     <section >
      <input type="file" name="" onChange={InputChange} multiple id="" />
     <FileUploader handleChange={InputChange} onDrop={InputChange} multiple name="file" types={fileTypes} />

     <div className="dragdrop-area d-none">
           <CloudUploadOutline />
           <p>Lorem ipsum dolor sit amet consectetur adipisicing elit. Amet praesentiu</p>
        </div>
        <ul>
        { 
            Array.from(fileList).map((item, index)=>{  
              console.log(item)
              if(item) console.log(URL.createObjectURL(item));
              /*
                return(
                  <li className="upl-item bg-danger" key={index+1}>
                     <div className="item-prev">
                          <ImageLazyLoading source={URL.createObjectURL(item)}  height={110} />
                     </div>
                     <div className="item-remove-btn"><TrashBinOutline /></div>
                  </li>) 
               */
            })
          } 
        </ul>
     </section>
    </div>
        <div className='form' action="">
         <InputEmoji   onChange={handleMessageText}   cleanOnEnter
          onEnter={handleOnEnter} borderRadius={6} theme="light" 
           placeholder="Pesquisar ..." /> 
            <div className="ed-flex messages-assets">
              <div className="gif-toggle">
                  <div className={show ? "" : "d-none"}> 
                { CheckinternetStatus() === true ? <GifPicker locale="pt_PT" onGifClick={getGifImage} tenorApiKey={"AIzaSyAs6jyixfg6l_1hMawHp317rRdN0Fpc1dg"} />: <></> }
              </div> 
                  <div onClick={()=>setShow(show ? false : true)}><BiSticker /> </div>
              </div>
           
            <div className="file-attach">
                 <input type="file" name="" hidden id="chat-form-files" />
                 <label htmlFor="chat-form-files"><MdAttachFile /></label>
            </div>
            </div>
            <button className="btn" onClick={()=>FormSubmit()}><SendOutline color="#ffff" /></button>
        </div>
        <div className="file-preview">

        </div>
    </div>
  )
}

/*
 <InputEmoji
          value={text}
          onChange={setText}
          cleanOnEnter
          onEnter={handleOnEnter}
          placeholder="Type a message"
        />
*/

export default ChatForm
  