import React, { useEffect, useState } from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap'
import { InfoOutlined, Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import ClearInputs from '../../../General/components/ClearInputs';
import { BooksDataOptionsSelector, GetClassroom_byclass, GetClasstitle_byclass, GetCourse_byclass, GetInstituteCode, GetPeriod_byclass, StudentsArray, StudentsDataOptions } from '../../../General/components/InstituteData';
import CRValue from '../../../General/components/CRValue';
import { toast } from 'react-hot-toast';
import { Update } from '@material-ui/icons';
import styled from 'styled-components';
import { Avatar } from '@mui/material';
import { Link } from 'react-router-dom';
import { MultiSelect } from 'react-multi-select-component';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import StudentDetailsMenu from '../elements/StudentDetailsMenu';
import { SaveOutline } from 'react-ionicons';
import { RefreshOutline } from 'react-ionicons';
import SelectSearch from 'react-select-search';
import RefreshList from '../../../General/components/RefreshList';
import moment from 'moment';


function BorrowBookModal(props) {
  const [show, setShow] = useState(false);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});
  const [monthError, setMonthError] = useState(null);
  const [Select, setSelected] = useState([]);
  const [Books, SetBooks] = useState(null);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [studentCode, setStudentCode] = useState(null);
  const [StudentClass, setStudentClass] = useState('#');
  const [StudentName, setStudentName] = useState('#');
  const [StudentPicture, setStudentPicture] = useState('#');
  const [Founded, SetFounded] = useState(null);



  const [showBox, SetshowBox] = useState(false);
  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200);
  }

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };


  const INPUTS = {
    borrow_book_devolution_date: CRValue("#borrow_book_devolution_date"),
    borrow_book_student: CRValue("#borrow_book_student"),
    borrow_book_data: Books,
    borrow_book_status: CRValue("#borrow_book_status"),
  };

  const FORMURL = [
    Hoot() + "edualllibraryborrowbookregister/post",
    props.get ? props.get : '',
    props.url ? props.url : '',
    Hoot() + "eduallsinglestudentapi/get/"
  ];

  const GET_DATA = async () => {
    if (props.update) {
      try {
        const response = await axios.get(FORMURL[1]);
        if (response.data.length > 0) {


          console.log("DATA = ", response.data[0]);
          const BooksRows = await axios.get(Hoot() + `edualllibrarybooks/get`);

          const codes = response.data[0].ed_library_borrowed_book_code.split(',').map(code => parseInt(code.trim(), 10)).filter(code => !isNaN(code));
          let SelectedBooks = [];
          BooksRows.data.forEach(element => {
            codes.forEach(cd => {
              if (element.ed_library_book_id * 1 === cd) {
                SelectedBooks.push({ label: element.ed_library_book_title, value: element.ed_library_book_id });
              }
            });
          });


          var books = "";
          for (let i = 0; i < SelectedBooks.length; i++) {
            books += "," + SelectedBooks[i].value;
          }
          SetBooks(books);
          setSelected(SelectedBooks);

          const DevDate = moment(response.data[0].ed_library_borrowed_book_devolutionDate).format("YYYY-MM-DD");
          document.querySelector("#borrow_book_devolution_date").value = DevDate;
          INPUTS.borrow_book_devolution_date = DevDate; 
          setField("borrow_book_devolution_date", DevDate);

          document.querySelector("#borrow_book_status").value = response.data[0].ed_library_borrowed_book_status;
          INPUTS.borrow_book_status = response.data[0].ed_library_borrowed_book_status;
          setField("borrow_book_status", response.data[0].ed_library_borrowed_book_status);

          setStudentCode(response.data[0].ed_library_borrowed_book_usercode);
        } else {
          toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
        }
      } catch (error) {
        toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
      }
    }
  }





  const setField = (field, value) => {
    setForm({
      ...form,
      [field]: value
    })

    if (!!errors[field]) {
      setErrors({
        ...errors,
        [field]: null
      });
    }
  }


  function selectedBooks(e) {
    setSelected(e)
    setField("borrow_books", "month");
    var books = "";
    for (let i = 0; i < e.length; i++) {
      books += "," + e[i].value;
    }
    SetBooks(books);
  }



  const validateForm = () => {
    setRegisterStatus(0);
    const { borrow_book_devolution_date, borrow_book_student } = form;
    const NewErrors = {};

    if (INPUTS.borrow_book_devolution_date === "" || INPUTS.borrow_book_devolution_date === " ") {
      if (!borrow_book_devolution_date || borrow_book_devolution_date === '') NewErrors.borrow_book_devolution_date = 'Data de devolução invalida';
    } else { if (!borrow_book_devolution_date) { setField("borrow_book_devolution_date", INPUTS.borrow_book_devolution_date); } }

    if (studentCode === null) NewErrors.borrow_book_student = 'Estudante selecionado invalido !';
    if (Books === null) NewErrors.borrow_book_data = 'Selecione um ou mais livros !';


    return NewErrors;
  }

  const FormSubmit = (e) => {
    e.preventDefault();
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os  campos !");
      setRegisterStatus(1);
    } else {

      const SUBMIT_INPUTS = {
        borrow_book_devolution_date: INPUTS.borrow_book_devolution_date,
        borrow_book_student: studentCode,
        borrow_book_status:INPUTS.borrow_book_status,
        borrow_book_data: INPUTS.borrow_book_data,
      };

      if (!props.update) {
        try {
          axios.post(FORMURL[0], SUBMIT_INPUTS).then(() => {
            toast.success("Emprestimo de livro registrado com sucesso !");
            setForm({});
            setRegisterStatus(2);
            ClearInputs();
            RefreshList(`.el-refresh-list`);
          }).catch((error) => {
            console.clear()
            console.log(error.response);
            setRegisterStatus(1);
            toast.error("Lamentamos mas não foi  possivel executar esta ação  !");
          });
        } catch (error) {
          console.clear()
          console.log(error.response);
          setRegisterStatus(1);
          toast.error("Lamentamos mas não foi  possivel executar esta ação  !");
        }
      } else {
        try {
          axios.put(FORMURL[2], SUBMIT_INPUTS).then(() => {
            toast.success("Emprestimo de livro atualizado com sucesso !");
            setForm({});
            ClearInputs();
            setRegisterStatus(2);
            RefreshList(`.el-refresh-list`);
            setTimeout(() => {
              handleClose();
            }, 1000);
          }).catch((error) => {
            console.clear()
            console.log(error.response);
            setRegisterStatus(1);
            toast.error("Lamentamos mas não foi  possivel executar esta ação  !")
          });
        } catch (error) {
          console.clear()
          console.log(error.response);
          setRegisterStatus(1);
          toast.error("Lamentamos mas não foi  possivel executar esta ação  !")
        }
      }
    }
  };


  const handleInput = (e) => {
    switch (e.target.id) {
      case "borrow_book_devolution_date":
        console.clear();
        console.log(e.target.value);
        INPUTS.borrow_book_devolution_date = e.target.value
        setField("borrow_book_devolution_date", e.target.value);
        break;
      case "borrow_book_status":
        console.clear();
        console.log(e.target.value);
        INPUTS.borrow_book_status = e.target.value
        setField("borrow_book_status", e.target.value);
        break;
      default:
    }
  }


  useEffect(() => {
    setTimeout(() => {
      if (studentCode !== null) {
        const StudentData = async () => {
          try {
            const response = await axios.get(FORMURL[3] + `${studentCode}`)
            if (response.data.length > 0) {
              setStudentName(response.data[0].ed_student_name);
              setStudentClass(response.data[0].ed_student_class);
              setStudentPicture(response.data[0].ed_student_picture);
            } else {
              setRegisterStatus(1);
              toast.error("Lamentamos mas não foi  possivel executar esta ação  !");
            }
          } catch (error) {
            setRegisterStatus(1);
            toast.error("Lamentamos mas não foi  possivel executar esta ação  !");
          }
        }
        StudentData();
      }
    }, 100);
  }, [studentCode]);




  return (
    <div>
      <div onClick={handleShow}>
        {
          props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon />Cadastrar emprestimo de livro</button>
        }
      </div>
      <Modal className={showBox ? ModalAnimationShow() : ModalAnimationClose()} centered size='lg' dialogAs={DraggableModal} show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>{props.title ? props.title : 'Cadastrar '} emprestimo de livro</h5>
            </div>
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={FormSubmit}>
          <Modal.Body className='scrollLimit'>

            {studentCode !== null ?
              <div className="col mt-2 mb-2">
                <Box className="boxItem">
                  <div className="ed-flex">
                    <Link to='#'><Avatar alt={StudentName} src={StudentPicture !== "#" ? Hoot() + StudentPicture : ""} sx={{ width: 106, height: 106 }} /></Link>
                    <div className="d-block ml-2 description">
                      <div className="ed-wrap">
                        <h3 >Turma : <Link to='#' className='text-main label-student-name'> <GetClasstitle_byclass ID={StudentClass} /></Link></h3>
                        <h3 className='ml-2 '>Sala  : <Link to='#' className='text-main label-student-name'>  {<GetClassroom_byclass ID={StudentClass} />} </Link></h3>
                        <h3 className='ml-2 '>Periodo : <Link to='#' className='text-main label-student-name'>  <GetPeriod_byclass ID={StudentClass} />  </Link></h3>
                      </div>
                      <h5>Curso : <Link to='#' className='text-main label-student-class'> <GetCourse_byclass ID={StudentClass} /> </Link></h5>
                    </div>
                  </div>
                </Box>
              </div>
              : <></>}


            <Form.Group className="mb-3">
              <div className="ed-space">
                <div>
                  <Form.Label>Nome do estudante <span className='text-danger ml-2'>*</span></Form.Label>
                </div>
                <div className='ed-flex'>
                  {studentCode !== null ? <StudentDetailsMenu student_id={studentCode} toggle_btn={<div className='btn-pm-info'><InfoOutlined /></div>} /> : <></>}
                </div>
              </div>
              <div className={`select-search-item  ${errors.borrow_book_student ? 'error' : ''}`}>
                <SelectSearch onChange={(e) => setStudentCode(e)} value={studentCode} options={StudentsArray()[0]} search={true}
                  placeholder="Selecione um aluno" />
              </div>
              <small className="text-danger">{errors.borrow_book_student}</small>
            </Form.Group>

            <Form.Group className="mb-3">
              <Form.Label>Livros<span className='text-danger ml-2'>*</span></Form.Label>
              <MultiSelect
                options={BooksDataOptionsSelector()}
                value={Select}
                className={monthError !== null ? 'border-red' : ''}
                onChange={selectedBooks}
                labelledBy='select'
              />
              <Form.Control.Feedback type='invalid'>{errors.borrow_book_data}</Form.Control.Feedback>
            </Form.Group>
            <div className="block">
              <Form.Label>Data de devolução <span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Control required type='date' onChange={handleInput} className={!!errors.borrow_book_devolution_date && 'is-invalid'}
                value={form.borrow_book_devolution_date} isInvalid={!!errors.borrow_book_devolution_date}
                name='borrow_book_devolution_date' id="borrow_book_devolution_date" />
              <Form.Control.Feedback type='invalid'>{errors.borrow_book_devolution_date}</Form.Control.Feedback>
            </div> 

            {props.update ?
              <div className="col mt-2 mb-2">
                <div className="block">
                  <Form.Label>Situação <span className='text-danger ml-2'>*</span></Form.Label>
                  <Form.Select onChange={handleInput} className={!!errors.borrow_book_status && 'is-invalid'}
                    value={form.borrow_book_status} isInvalid={!!errors.borrow_book_status} name='borrow_book_status' id="borrow_book_status">
                    <option selected disabled>Selecionar situação</option>
                    <option value="0">Não retornado</option>
                    <option value="1">Retornado</option>
                  </Form.Select>
                  <Form.Control.Feedback type='invalid'>{errors.borrow_book_status}</Form.Control.Feedback>
                </div>
              </div>
              : <></>}
 
          </Modal.Body>
          <Modal.Footer>
            <div className="ed-space">
              <div className="ed-flex"></div>
              <div className="ed-flex">
                <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                {props.update ? (Founded === false ? <div></div> :
                  <SaveButton icon={props.title ? <RefreshOutline /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
                  <SaveButton icon={props.title ? <RefreshOutline /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />}
              </div>
            </div>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  )
}


const Box = styled.div`
    width:auto; 
    border-radius:6px;   
    padding:20px; 
    min-height:100px;
    background:#f0f3f7;
    color:var(--ed-dark);   
    border:1px solid var(--ed-silver-light);
    margin:10px 0;
    min-width:430px;

 

    .description{
        h3{
            font-size:16px;
            margin-bottom:15px;
            margin-top:10px;
        }

        h5{
            font-size:16px;
        }
    }

    h2{
        margin:10px 0;
        font-size:18px;
        font-weight:600;
    }
`;



export default BorrowBookModal