import React, { useEffect, useState } from 'react'
import TableGrid from '../../../../General/components/TableGrid';
import NumberToPrice from '../../../../General/components/NumberToPrice';
import moment from 'moment';

const Months = [
  "Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho",
  "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"
];

const columns = [
  { field: 'index', headerName: 'Nº', width: 60 },
  { field: 'invoiceN', headerName: 'Nº da Fatura', width: 180 },
  { field: 'service', headerName: 'Serviço', width: 280 },
  {
    field: 'monthsLabel',
    headerName: 'Meses pagos',
    width: 240,
  },
  {
    field: 'price',
    headerName: 'Preçário',
    width: 140,
    cellRenderer: (props) => (
      <div className='ed-flex'>
        {NumberToPrice(props.data.price)} {props.data.coin}
      </div>
    ),
  },
  {
    field: 'total',
    headerName: 'Total',
    width: 140,
    cellRenderer: (props) => (
      <div className='ed-flex'>
        {NumberToPrice(props.data.balance)} {props.data.coin}
      </div>
    ),
  },
  {
    field: 'situation',
    headerName: 'Situação',
    width: 150,
    cellRenderer: (props) =>
      props.data.invoiceCount > 1 ? (
        <div className="badge col-lg-12 bg-warning">
          {props.data.invoiceCount} meses
        </div>
      ) : (
        <div className="badge col-lg-12 bg-success">PG. Simples</div>
      ),
  },
  {
    field: 'date',
    headerName: 'Data de pagamento',
    width: 250,
  },
];

function STD_payments(props) {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);

  // Calcula o total de cada linha
  function computeTotal(item) {
    let price = item.ed_fee_payment_price * 1;
    let discount = item.ed_fee_payment_discount * 1 || 0;
    let iva = item.ed_fee_payment_iva * 1 || 0;
    let fineType = item.ed_fee_payment_fineType * 1 || 0;
    let fineValue = item.ed_fee_payment_fineValue * 1 || 0;

    let afterDiscount = price - (price * discount) / 100;
    let base = iva > 0 ? afterDiscount / (1 + iva / 100) : afterDiscount;
    let fineAmount = fineType === 1 ? fineValue : (base * fineValue) / 100;
    return afterDiscount + fineAmount;
  }

  async function loadData() {
    setLoaded(false);
    try {
      const grouped = {};

      props.data.Data.forEach((item) => {
        const total = computeTotal(item);
        const key = item.ed_fee_payment_invoiceCode;

        if (!grouped[key]) {
          grouped[key] = {
            id: item.ed_fee_payment_id,
            invoiceN: item.ed_fee_payment_invoiceCode,
            service: item.ed_service_title,
            coin: item.ed_coin_code,
            code: item.ed_fee_payment_invoiceFile,
            student: item.ed_fee_payment_student,
            name: item.ed_student_name,
            balance: total,
            price: item.ed_fee_payment_price,
            months: [item.ed_fee_payment_month],
            invoiceCount: 1,
            date: moment(item.ed_fee_payment_registerDate).format(
              'DD [de] MMMM [de] YYYY [às] HH:mm'
            ),
          };
        } else {
          grouped[key].balance += total;
          grouped[key].months.push(item.ed_fee_payment_month);
          grouped[key].invoiceCount += 1;
        }
      });

      // Converter em array formatado
      const rows = Object.values(grouped).map((g, index) => ({
        ...g,
        index: index + 1,
        monthsLabel: g.months
          .map((m) => {
            if (!m) return '';
            const [mm, yy] = m.split('.');
            const monthName = Months[parseInt(mm, 10)] || mm;
            return `${monthName} de ${yy}`;
          })
          .join(', '),
      }));

      setData(rows);
    } catch (err) {
      console.error(err);
    } finally {
      setTimeout(() => setLoaded(true), 200);
    }
  }

  useEffect(() => {
    loadData();
  }, []);

  return (
    <div>
      <TableGrid
        TableHead={columns}
        TableBody={data}
        TableTitle='Propinas pagas'
        TableHeight={data.length <= 5 ? 200 : 600}
        NoButtons
        TWOBAR
      />
      <br />
    </div>
  );
}

export default STD_payments;
