import React from 'react'
import styled from 'styled-components'
import { Link } from 'react-router-dom';
import { Avatar } from '@mui/material';
import FormControlLabel from '@mui/material/FormControlLabel';
import Checkbox from '@mui/material/Checkbox';

function Notifications() {
    document.title = "Notificações";
    const Data = [
        {

        },
        {

        },
        {

        },
        {

        },
        {

        },
        {

        },
    ]


    return (
        <Container>
            <BoxContainer>
                <h1 className="title">Notificações</h1><br />
                <ul>
                    {Data.map((item, index) => (
                        <li className='not-el' >
                            <div className="info-flex">
                                <div className="image">
                                    <Avatar alt="name here" className='df' src="" sx={{ width: 60, height: 60 }} />
                                    <div className="type-box ed-center ed-flex"></div>
                                </div>
                                <div className="block">
                                    <div className="name">
                                        <strong>Carlos</strong>
                                        <div className="grey-text ml-1">@professor</div>
                                    </div>
                                    <div className="not-dets">
                                        <small className="grey-text">Apagou o estudante do sistema </small>
                                        <strong className='ml-1'><small>#27635</small></strong>
                                    </div>
                                    <div className="mt-1 mb-2">
                                        <p>Uma nova tarefa foi atualizada recentemenete...</p>
                                    </div>
                                    <div><small className="text-main underline">Ver detalhes</small></div>
                                </div>
                            </div>
                        </li>
                    ))}
                </ul>
            </BoxContainer>
            <div className="pd-1"></div>
            <div className="filters-box">
                <BoxContainer>
                    <h1 className="title">Filtros</h1> 
                    <div className="space-item ed-flex ed-space mb-2">
                        <div className="label"><strong>funcionários da  <span className="grey-text">(12)</span> </strong></div>
                        <div className="checkbox-el">
                            <FormControlLabel control={<Checkbox />} label={""} />
                        </div>
                    </div>
                    <div className="space-item ed-flex ed-space mb-2">
                        <div className="label"> <strong>Avisos do sistema  <span className="grey-text">(12)</span></strong> </div>
                        <div className="checkbox-el">
                            <FormControlLabel control={<Checkbox />} label={""} />
                        </div>
                    </div>
                    <div className="space-item ed-flex ed-space mb-2">
                        <div className="label"><strong>Encarregados de educação  <span className="grey-text">(12)</span></strong></div>
                        <div className="checkbox-el">
                            <FormControlLabel control={<Checkbox />} label={""} />
                        </div>
                    </div>
                    <div className="space-item ed-flex ed-space mb-2">
                        <div className="label"><strong>Solicitações  <span className="grey-text">(12)</span></strong></div>
                        <div className="checkbox-el">
                            <FormControlLabel control={<Checkbox />} label={""} />
                        </div>
                    </div>
                    <div className="space-item ed-flex ed-space mb-2">
                        <div className="label"><strong>Estudantes  <span className="grey-text">(12)</span></strong></div>
                        <div className="checkbox-el">
                            <FormControlLabel control={<Checkbox />} label={""} />
                        </div>
                    </div>
                </BoxContainer>
            </div>
        </Container>
    )
}

const Container = styled.div`
   width:100%; 
   display:flex;

   .filters-box{
       width:400px;
       min-width:400px;

 
    }
`;



const BoxContainer = styled.div` 
    width:100%; 
    border-radius:6px;
    margin-bottom:20px;  
    padding:20px;
    min-height:200px;
    background:var(--ed-white);  
    box-shadow:var(--ed-shadow-df); 

    .title{
        font-size:18px;  
        font-weight:600;
        margin-top:10px;
        margin-bottom:25px;
    } 


    ul{
    padding:0px;
    margin:0px;

       .not-el{  
         width:100%;
         list-style:none;
         margin-bottom:20px;
         padding-bottom:20px;
         border-bottom:1px solid #E9ECEF; 

             
            .info-flex{
               display:flex;

                 .image{
                    width:60px;
                    height:60px;
                    position:relative;

                      .type-box{
                         box-shadow:var(--ed-shadow-1);
                         width:25px;
                         height:25px;
                         border-radius:100%;
                         border:3px solid var(--white);
                         background:var(--ed-green);
                         color:var(--white);
                         font-size:13px;
                         right:-5px;
                         top:40px;
                         position:absolute;
                      }
                  }


                .block{
                    padding-left:20px;

                    .name, .not-dets{
                        display:flex;
                    }

                    p{
                      font-size:15px;
                    }
                }
            }
           
       }
     }
`;

export default Notifications
