import React, { useState } from 'react';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap';
import { Save, Update } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import { toast } from 'react-hot-toast';
import axios from 'axios';
import ClearInputs from '../../../General/components/ClearInputs';
import RefreshList from '../../../General/components/RefreshList';
import Hoot from '../../../General/components/Hoot';
import ReplaceWord from '../../../General/components/ReplaceWord';
import { GetInstituteCode, StudentsArray } from '../../../General/components/InstituteData';
import SelectSearch from 'react-select-search';

function NewDeclarationModal(props) {
    const [show, setShow] = useState(false);
    const [registerStatus, setRegisterStatus] = useState(null);
    const [founded, setFounded] = useState(null);
    const [form, setForm] = useState({
        declaration_student: "",
        declaration_effect: "",
        declaration_with_marks: "0",
        declaration_class: "",
    });
    const [errors, setErrors] = useState({});
    const [showBox, setShowBox] = useState(false);
    const [showClassField, setShowClassField] = useState(false);

    const handleClose = () => {
        setShowBox(false);
        setTimeout(() => setShow(false), 1200);
    };

    const handleShow = () => {
        setShowBox(true);
        setShow(true);
        setTimeout(() => GET_DATA(), 1000);
    };

    const FORM_URLS = [
        Hoot() + "edualldeclarationregister/post/",
        props.get ? props.get : '',
        props.url ? props.url : ''
    ];

    const GET_DATA = async () => {
        if (props.update) {
            try {
                const response = await axios.get(FORM_URLS[1]);
                if (response.data.length > 0) {
                    setForm({
                        declaration_student: response.data[0].ed_declaration_student,
                        declaration_effect: response.data[0].ed_declaration_effect,
                        declaration_with_marks: response.data[0].ed_declaration_with_marks.toString(),
                        declaration_class: response.data[0].ed_declaration_class,
                    });
                    setShowClassField(response.data[0].ed_declaration_with_marks === "1");
                } else {
                    toast.error("Não foi possível encontrar as informações selecionadas!");
                }
            } catch {
                toast.error("Erro ao carregar os dados da declaração!");
            }
        }
    };

    const handleInput = (e) => {
        const { id, value } = e.target;
        setField(id, value);
        if (id === "declaration_with_marks") setShowClassField(value === "1");
    };

    const setField = (field, value) => {
        setForm({ ...form, [field]: value });
        if (!!errors[field]) setErrors({ ...errors, [field]: null });
    };

    const validateForm = () => {
        const { declaration_student, declaration_effect, declaration_with_marks, declaration_class } = form;
        const newErrors = {};
        setRegisterStatus(0);
        if (!declaration_student.trim()) newErrors.declaration_student = 'Estudante inválido!';
        if (!declaration_effect.trim()) newErrors.declaration_effect = 'Efeito da declaração é obrigatório!';
        if (!declaration_with_marks.trim()) newErrors.declaration_with_marks = 'Selecione uma opção válida!';
        if (showClassField && !declaration_class.trim()) newErrors.declaration_class = 'Selecione uma opção válida!';
        return newErrors;
    };

    const FormSubmit = async (e) => {
        e.preventDefault();
        const formErrors = validateForm();

        if (Object.keys(formErrors).length > 0) {
            setErrors(formErrors);
            toast.error("Verifique todos os campos obrigatórios!");
            setRegisterStatus(1);
        } else {
            if (!props.update) {
                try {
                    await axios.post(FORM_URLS[0], form);
                    toast.success("Declaração registrada com sucesso!");
                    setForm({ declaration_student: "", declaration_effect: "", declaration_with_marks: "0", declaration_class: "" });
                    ClearInputs();
                    RefreshList(`.el-refresh-list`);
                    setRegisterStatus(2);
                    setTimeout(() => handleClose(), 1000);
                } catch (error) {
                    const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
                    toast.error(msg);
                    setRegisterStatus(1);
                }
            } else {
                try {
                    await axios.put(FORM_URLS[2], form);
                    toast.success("Declaração atualizada com sucesso!");
                    setForm({ declaration_student: "", declaration_effect: "", declaration_with_marks: "0", declaration_class: "" });
                    ClearInputs();
                    RefreshList(`.el-refresh-list`);
                    setRegisterStatus(2);
                    setTimeout(() => handleClose(), 1000);
                } catch (error) { 
                    const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
                    toast.error(msg);
                    setRegisterStatus(1);
                }
            }
        }
    };

    return (
        <div>
            <div onClick={handleShow}>
                {props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon /> Emitir Declaração</button>}
            </div>
            <Modal className={showBox ? ModalAnimationShow() : ModalAnimationClose()} centered size='lg' dialogAs={DraggableModal} show={show} onHide={handleClose}>
                <Modal.Header closeButton>
                    <Modal.Title>
                        <div className="ed-wrap align-center">
                            <UserOptionDropDown />
                            <h5>{props.title ? props.title : 'Emitir '} Declaração</h5>
                        </div>
                    </Modal.Title>
                </Modal.Header>
                <Form onSubmit={FormSubmit}>
                    <Modal.Body className='scrollLimit'>
                        {!props.update &&
                            <Form.Group className="mb-3">
                                <Form.Label>Nome do estudante <span className='text-danger ml-2'>*</span></Form.Label>
                                <SelectSearch onChange={(e) => setField("declaration_student", e)} options={StudentsArray()[0]} search={true} placeholder="Selecione um aluno" />
                                <Form.Control.Feedback type='invalid'>{errors.declaration_student}</Form.Control.Feedback>
                            </Form.Group>
                        }
                        <Form.Group className="mb-3">
                            <Form.Label>Efeito<span className='text-danger ml-2'>*</span></Form.Label>
                            <Form.Control type='text' id="declaration_effect" value={form.declaration_effect} onChange={handleInput} isInvalid={!!errors.declaration_effect} />
                            <Form.Control.Feedback type='invalid'>{errors.declaration_effect}</Form.Control.Feedback>
                        </Form.Group>
                        <Form.Group className="mb-3">
                            <Form.Label>Declaração com notas<span className='text-danger ml-2'>*</span></Form.Label>
                            <Form.Select id="declaration_with_marks" value={form.declaration_with_marks} onChange={handleInput} isInvalid={!!errors.declaration_with_marks}>
                                <option value="1">Sim</option>
                                <option value="0">Não</option>
                            </Form.Select>
                            <Form.Control.Feedback type='invalid'>{errors.declaration_with_marks}</Form.Control.Feedback>
                        </Form.Group>
                    </Modal.Body>
                    <Modal.Footer>
                        <Button className='bg-light text-dark' onClick={handleClose}>Cancelar</Button>
                        <SaveButton icon={props.update ? <Update /> : <Save />} title={props.title || 'Salvar'} status={registerStatus} />
                    </Modal.Footer>
                </Form>
            </Modal>
        </div>
    );
}

export default NewDeclarationModal;
