import React, { useState } from 'react';
import { Modal, Button, Table, Badge } from 'react-bootstrap';
import styled from "styled-components";
import DraggableModal from '../../../General/components/DraggableModal';
import { Avatar } from '@mui/material';
import { Link } from 'react-router-dom';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import { GetJobTitle } from '../../../General/components/InstituteData';
import { AccessTimeOutlined, DeleteOutline, DownloadingOutlined } from '@mui/icons-material';
import DeleteModal from '../elements/DeleteModal';
import ReduceTextLength from '../../../General/components/ReduceTextLength';
import { HiOutlineDocumentText } from 'react-icons/hi';
import moment from 'moment';

function PopEmployeeDetailsModal(props) {
  const [show, setShow] = useState(false);
  const [Founded, SetFounded] = useState(null);
  const [CurrentFiles, SetCurrentFiles] = useState([]);
  const [Data, setData] = useState({});


  const [showBox, SetshowBox] = useState(false);
  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200);
  }

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };


  const CivilStates = ["Solteiro (a)", "Noivo(a)", "Casado(a)"];


  const FORMURL = [
    Hoot() + "eduallsingleuserfiles/get/",
    props.get ? props.get : '',
    props.print ? props.print : '',
  ];


  async function GET_DATA() {
    try {
      const response = await axios.get(FORMURL[1]);
      console.log("working on it ....")
      if (response.data !== null) {
        if (response.data.length >= 1) {
          SetFounded(true);
          const responseFiles = await axios.get(FORMURL[0] + response.data[0].ed_employee_code);
          if (responseFiles.data.length >= 1) SetCurrentFiles(responseFiles.data);
          let info = response.data[0];
          setData(info);

        } else {
          console.log("oi 1")
          SetFounded(false);
        }
      } else {
        SetFounded(false);
        console.log("oi 2")
      }
    } catch (error) {
      console.log(error);
      SetFounded(false);
    }
  }


  return (
    <div>
      <div onClick={handleShow}>
        {props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'>Ver detalhes</button>}
      </div>
      <Modal size='md' centered className={showBox ? ModalAnimationShow() : ModalAnimationClose()} dialogAs={DraggableModal} show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <div className="ed-block">
                <h5 className='m0'>Detalhes do funcionário  </h5>
              </div>
            </div>
          </Modal.Title>
        </Modal.Header>
        <Modal.Body className='scrollLimit'>
          <Box className="boxItem">
            <div className="ed-flex student-box">
              <SwitchFromPages link={`#`}
                menu='3' menu_item='17' toggle_btn={
                  <div className='ed-flex'>
                    <Avatar alt={Data.ed_student_name} className='df' src={Hoot() + Data.ed_employee_picture} sx={{ width: 90, height: 90 }} />
                  </div>
                } />
              <div className="d-block ml-2 description">
                <h3 className='name '>Nome : <Link to='#' className='text-main label-student-name'>{Data.ed_employee_name}</Link></h3>
                <h5>Cargo :
                  <Link
                    to="#"
                    className={Data.job_title === "Não atribuído"
                      ? "text-danger ml-1 label-student-class"
                      : "text-main ml-1 label-student-class"
                    }
                    style={Data.job_title === "Não atribuído"
                      ? { textDecoration: "line-through" }
                      : {}
                    }
                  >
                    {Data.job_title}
                  </Link> 
                </h5>
              </div>
            </div>
            <br /><br /><br /> <br />
          </Box>
          <br />
          <Main>
            <Table hover>
              <tbody>
                <tr>
                  <td>
                    <div className="ed-flex">
                      <strong>Endereço:</strong><div className="ml-2 grey-text">{Data.ed_employee_address}</div>
                    </div>
                  </td>
                </tr>
                <tr>
                  <td>
                    <div className="ed-flex">
                      <strong>Nacionalidade:</strong><div className="ml-2 grey-text">{Data.ed_employee_nacionality}</div>
                    </div>
                  </td>
                </tr>
                <tr>
                  <td>
                    <div className="ed-flex">
                      <strong>Naturalidade:</strong><div className="ml-2 grey-text">{Data.ed_employee_naturalness}</div>
                    </div>
                  </td>
                </tr>
                <tr>
                  <td>
                    <div className="ed-flex">
                      <strong>Gênero:</strong><div className="ml-2 grey-text">{Data.ed_employee_gender === "female" ? "Femenino" : "Masculino"}</div>
                    </div>
                  </td>
                </tr>
                <tr>
                  <td>
                    <div className="ed-flex">
                      <strong>Religião:</strong><div className="ml-2 grey-text">{Data.ed_employee_religion}</div>
                    </div>
                  </td>
                </tr>
                <tr>
                  <td>
                    <div className="ed-flex">
                      <strong>Data de Nascimento:</strong><div className="ml-2 grey-text">{Data.ed_employee_birthday}</div>
                    </div>
                  </td>
                </tr>
                <tr>
                  <td>
                    <div className="ed-flex">
                      <strong>Telefone 1:</strong><div className="ml-2 grey-text">{Data.ed_employee_phone}</div>
                    </div>
                  </td>
                </tr>
                <tr>
                  <td>
                    <div className="ed-flex">
                      <strong>Telefone 2:</strong><div className="ml-2 grey-text">{Data.ed_employee_phone2}</div>
                    </div>
                  </td>
                </tr>
                <tr>
                  <td>
                    <div className="ed-flex">
                      <strong>NIF:</strong><div className="ml-2 grey-text">{Data.ed_employee_nif}</div>
                    </div>
                  </td>
                </tr>
                <tr>
                  <td>
                    <div className="ed-flex">
                      <strong>Email:</strong><div className="ml-2 grey-text">{Data.ed_employee_email}</div>
                    </div>
                  </td>
                </tr>
                <tr>
                  <td>
                    <div className="ed-flex">
                      <strong>Estado Civil:</strong><div className="ml-2 grey-text">{CivilStates[Data.ed_employee_civil_state * 1]}</div>
                    </div>
                  </td>
                </tr>
                <tr>
                  <td>
                    <div className="ed-flex">
                      <strong>Cartão de Identidade (BI):</strong><div className="ml-2 grey-text">{Data.ed_employee_identityCard}</div>
                    </div>
                  </td>
                </tr>
                <tr>
                  <td>
                    <div className="ed-flex">
                      <strong>Status:</strong><div className="ml-2 grey-text">{Data.ed_employee_status === 1 ?
                        <Badge bg='info'><div className="text-dark">Activo</div></Badge> :
                        <Badge bg='danger'><div className="text-dark">Inactivo</div></Badge>
                      }
                      </div>
                    </div>
                  </td>
                </tr>
              </tbody>
            </Table>
            <br />
            {CurrentFiles.length >= 1 ? <strong className="text-danger mb-2">Ficheiros anexados no registro do funcionário</strong> : <></>}
            <div className='student-file-cp'>
              {
                CurrentFiles.map((item, index) => {
                  return (
                    <li className='student-file-el' id={`student-file-el-${index}`} key={index}>
                      <div className="ed-space">
                        <div className="ed-flex">
                          <div className="icon">
                            <HiOutlineDocumentText />
                          </div>
                          <div className="block">
                            <div className="title text-main"><ReduceTextLength text={item.ed_file_name.split("/")[1]} length={26} /></div>
                            <div className="ed-flex">
                              <div className="date text-dark"><AccessTimeOutlined /><span>{moment(item.ed_file_register_date).format("YYYY-MM-DD HH:mm")}</span></div>
                            </div>
                          </div>
                        </div>
                        <div className="delete ed-flex">
                          <a href={Hoot() + item.ed_file_name} target="_blank" download={item.ed_file_name.split("/")[1]}>
                            <div className="btn-circle bg-main text-main">
                              <DownloadingOutlined />
                            </div>
                          </a>
                          <DeleteModal remove_element={`#student-file-el-${index}`} title='este ficheiro' url={Hoot() + `eduallfiledelete/delete/${item.ed_file_id}`}
                            message='Ficheiro deletada com sucesso' toggle_btn={
                              <div className="btn-circle bg-danger ml-2 text-light">
                                <DeleteOutline />
                              </div>} />
                        </div>
                      </div>
                    </li>
                  )
                })
              }
            </div>
          </Main>
        </Modal.Body>
      </Modal>
    </div>
  )
}

const Box = styled.div`
    width:100%; 
    border-radius:6px;   
    padding:0px 10px; 
    min-height:100px;  

    .ex{
        font-size:16px;
        margin-top:8px;
        margin-right:25px; 
    }

    .student-box{
       position:absolute;
       left:0px;
       top:0px;
       width:100%;
       padding:10px 20px;
       background:var(--ed-background-color);
    }



    .description{
        .name{
            font-size:18px;
            margin-bottom:15px;
            margin-top:10px;
        }

        h5{
            font-size:16px;
        }
    }
 
`;

const Main = styled.main`
      ul{
        padding:0px;
        padding-left:10px;  
        
        li{
            padding:10px 0px;
            border-top:1px solid var(--ed-white-smoke);
            font-size:15px;
            font-weight:500;
            list-style:none;
            display:flex;

            .text-blue{
                color:var(--ed-blue-light);

                svg{
                    width:20px;
                    fill:var(--ed-blue-light);
                }
            }
        }

        .total{
            padding:10px 0px;  
            border-top:4px double #000;
            border-bottom:4px double #000;

            h1{ 
                font-size:18px;
                margin:0px;
            }
        }
      }

      .student-file-cp{
           li{
               padding-left:10px;
               padding-right:10px;
           }
      }
`;

export default PopEmployeeDetailsModal;
