import React, { useState } from 'react';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap';
import { Save, Update } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import { toast } from 'react-hot-toast';
import axios from 'axios';
import ClearInputs from '../../../General/components/ClearInputs';
import RefreshList from '../../../General/components/RefreshList';
import Hoot from '../../../General/components/Hoot';
import { GetInstituteCode } from '../../../General/components/InstituteData';

function NewCoinModal(props) {
    const [show, setShow] = useState(false);
    const [registerStatus, setRegisterStatus] = useState(null);
    const [founded, setFounded] = useState(null);

    const [form, setForm] = useState({
        coin_title: "",
        coin_code: "",
    });
    const [errors, setErrors] = useState({});
    const [showBox, setShowBox] = useState(false);

    const handleClose = () => {
        setShowBox(false);
        setTimeout(() => setShow(false), 1200);
    };

    const handleShow = () => {
        setShowBox(true);
        setShow(true);
        setTimeout(() => GET_DATA(), 1000);
    };

    const FORM_URLS = [
        Hoot() + "eduallregistercoins/post/",
        props.get ? props.get : '',
        props.url ? props.url : ''
    ];

    const GET_DATA = async () => {
        if (props.update) {
            try {
                const response = await axios.get(FORM_URLS[1]);
                if (response.data.length > 0) {
                    setForm({
                        coin_title: response.data[0].ed_coin_title,
                        coin_code: response.data[0].ed_coin_code,
                    });
                } else {
                    toast.error("Não foi possível encontrar as informações selecionadas!");
                }
            } catch {
                toast.error("Erro ao carregar os dados da moeda!");
            }
        }
    };

    const handleInput = (e) => setField(e.target.id, e.target.value);

    const setField = (field, value) => {
        setForm({ ...form, [field]: value });
        if (!!errors[field]) setErrors({ ...errors, [field]: null });
    };

    const validateForm = () => {
        const { coin_title, coin_code } = form;
        const newErrors = {};
        setRegisterStatus(0);
        if (!coin_title.trim()) newErrors.coin_title = 'Nome da moeda é obrigatório !';
        if (!coin_code.trim()) newErrors.coin_code = 'O código da moeda é obrigatório! ';
        return newErrors;
    };

    const FormSubmit = async (e) => {
        e.preventDefault();
        const formErrors = validateForm();

        if (Object.keys(formErrors).length > 0) {
            setErrors(formErrors);
            toast.error("Verifique todos os campos obrigatórios!");
            setRegisterStatus(1);
        } else {
            try {
                if (!props.update) {
                    await axios.post(FORM_URLS[0], form);
                    toast.success("Moeda registrada com sucesso!");
                } else {
                    await axios.put(FORM_URLS[2], form);
                    toast.success("Moeda atualizada com sucesso!");
                }
                setForm({});
                ClearInputs();
                RefreshList(`.el-refresh-list`);
                setRegisterStatus(2);
                setTimeout(() => handleClose(), 1500);
            } catch (error) {
                setRegisterStatus(1);

                const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
                toast.error(msg);
            }
        }
    };

    return (
        <div>
            <div onClick={handleShow}>
                {props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon /> Definir moedas</button>}
            </div>
            <Modal className={showBox ? ModalAnimationShow() : ModalAnimationClose()} centered size='lg' dialogAs={DraggableModal} show={show} onHide={handleClose}>
                <Modal.Header closeButton>
                    <Modal.Title>
                        <div className="ed-wrap align-center">
                            <UserOptionDropDown />
                            <h5>{props.title ? props.title : 'Definir '} moeda</h5>
                        </div>
                    </Modal.Title>
                </Modal.Header>
                <Form onSubmit={FormSubmit}>
                    <Modal.Body className='scrollLimit'>
                        <Form.Group className="mb-3">
                            <Form.Label>Moeda<span className='text-danger ml-2'>*</span></Form.Label>
                            <Form.Control type="text" id="coin_title" value={form.coin_title} onChange={handleInput} isInvalid={!!errors.coin_title} />
                            <Form.Control.Feedback type='invalid'>{errors.coin_title}</Form.Control.Feedback>
                        </Form.Group>
                        <Form.Group className="mb-3">
                            <Form.Label>Representação ou código<span className='text-danger ml-2'>*</span></Form.Label>
                            <Form.Control type="text" id="coin_code" value={form.coin_code} onChange={handleInput} isInvalid={!!errors.coin_code} />
                            <Form.Control.Feedback type='invalid'>{errors.coin_code}</Form.Control.Feedback>
                        </Form.Group>
                    </Modal.Body>
                    <Modal.Footer>
                        <Button className='bg-light text-dark' onClick={handleClose}>Cancelar</Button>
                        <SaveButton icon={props.update ? <Update /> : <Save />} title={props.title || 'Salvar'} status={registerStatus} />
                    </Modal.Footer>
                </Form>
            </Modal>
        </div>
    );
}

export default NewCoinModal;
