import React, { useEffect, useState } from 'react'
import { Check, CheckBox, CheckBoxOutlineBlank, Done } from '@mui/icons-material'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap'
import { Save } from '@mui/icons-material';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import ClearInputs from '../../../General/components/ClearInputs';
import { CourseDataOptions, AcademicYearDataOptions, ClassroomsDataOptions, CicleDataOptions, GetInstituteCode, AcademiclevelDataOptions, TitlesAndHeadersDataOptions, GetAcademiclevel_byclass, GetCourse_byclass } from '../../../General/components/InstituteData';
import { toast } from 'react-hot-toast';
import { Print } from '@material-ui/icons';
import { useRef } from 'react';
import { useReactToPrint } from 'react-to-print';
import RandomCodeGenerator from '../../../General/components/RandomCodeGenerator';
import { useParams } from 'react-router-dom';
import Loader from '../../../General/components/Loader';
import NotFounded from '../../../General/components/NotFounded';
import BackButton from '../elements/BackButton';
import moment from "moment";
import ReplaceWord from '../../../General/components/ReplaceWord';
import CalcAgeByBirthday from '../../../General/components/CalcAgeByBirthday';

function EnrollmentPrint() {
    const EnrollmentsData = [""];
    const containerPrint = useRef();
    const [Total, setTotal] = useState([""]);
    const [data, setData] = useState([]);
    const [studentData, setStudentData] = useState({});
    const [InstituteData, setInstituteData] = useState({});
    const [StudentPersonalInformation, setStudentPersonalInformation] = useState([]);
    const [StudentFatherData, SetStudentFatherData] = useState(null);
    const [StudentMotherData, SetStudentMotherData] = useState(null);
    const [Loaded, setLoaded] = useState(false);
    const [Founded, SetFounded] = useState(null);
    const schollarship = ["Não", "Sim"];

    const CurrentDay = new Date().getMonth();
    const CurrentMonth = new Date().getDay();
    const CurrentYear = new Date().getFullYear();
    const CurrentDate = new Date().toLocaleString();

    const { id } = useParams();

    const DATAURL = [
        Hoot() + "eduallgetsingletitleandheader/get/",
        Hoot() + "eduallfeepaymentsingle/get/",
        Hoot() + "eduallgetsingleenrolledstudent/get/",
        Hoot() + "eduallgetcurentuserinstitute/get",
        Hoot() + "eduallparents/get"
    ];

    const StudentData = async (e) => {
        if (Math.floor(e) >= 0) {
            try {
                const response = await axios.get(DATAURL[0] + `${e}`)
                if (response.data.length >= 1) {
                    let outputs = document.querySelectorAll(".box .header-print");
                    for (let i = 0; i < outputs.length; i++) {
                        outputs[i].innerHTML = JSON.parse(response.data[0].ed_title_description);
                    }
                }
            } catch (error) {

            }
        }
    }



    async function loadData() {
        try {
            const [response, response2, response3] = await Promise.all([
                axios.get(DATAURL[2] + id),
                axios.get(DATAURL[3]),
                axios.get(DATAURL[4]),
            ]);

            let ParentsData = [];
            const Parta = [];
            if (response3.data.length >= 1 && response.data.length > 0) {
                response3.data.map((item, index) => {
                    if (item.ed_parent_students_code !== null) {

                        let students = item.ed_parent_students_code.split('|');
                        if (item.ed_parent_students_code * 1 > 0) students.push(item.ed_parent_students_code * 1);

                        Parta.push(item.ed_parent_students_code)

                        for (let i = 0; i < students.length; i++) {
                            if ((students[i] * 1) >= 0) {
                                if (Math.floor(students[i]) === Math.floor(response.data[0].ed_student_id)) {
                                    let SH = item.ed_parent_name.split('')[0] + item.ed_parent_name.split('')[item.ed_parent_name.split('').length - 1]


                                    ParentsData.push({
                                        parent_id: item.ed_parent_id,
                                        parent_type: item.ed_parent_degree_of_kinship,
                                        parent_avatar_letter: SH.toUpperCase(),
                                        parent_name: item.ed_parent_name,
                                        parent_picture: Hoot() + item.ed_parent_picture
                                    });



                                }
                            }
                        }
                    }
                })
            }

            function removeDuplicates() {
                let newArray = [];
                let uniqueObject = {};
                for (let i in ParentsData) {
                    let objTitle = ParentsData[i]['parent_id'];
                    uniqueObject[objTitle] = ParentsData[i];
                }
                for (let i in uniqueObject) {
                    newArray.push(uniqueObject[i]);
                }
                ParentsData = newArray;
            }
            removeDuplicates();


            console.clear();
            console.log(response.data, response2.data);
            console.log("------------------")
            console.log(ParentsData);
            console.log(Parta);


            ParentsData.map((item) => {
                if ((item.parent_type * 1) === 0) {
                    SetStudentMotherData(item);
                } else if ((item.parent_type * 1) === 1) {
                    SetStudentFatherData(item);
                }
            })





            if (response.data.length > 0 && response2.data.length > 0) {
                setStudentData(response.data[0]);
                setInstituteData(response2.data[0]);
                SetFounded(true);
            } else {
                SetFounded(false);
            }
        } catch (error) {
            console.clear()
            console.log(error.response.data);
            SetFounded(false);
        }
    }


    useEffect(() => {
        loadData();
        setLoaded(true);
    }, []);


    const setTitleCode = (e) => {
        StudentData(e);
    }



    const ToggleCheckBox = (e) => {
        e.target.classList.toggle("checked")
    }


    const Multiplicate = (e) => {
        let Amount = [];
        for (let i = 0; i < e; i++) {
            Amount.push("");
        }
        setTotal(Amount);
    }



    const handlePrint = useReactToPrint({
        content: () => containerPrint.current,
        documentTitle: 'eduall_matrícula_&_confirmação' + '_' + CurrentDate,
        copyStyles: true
    });






    if (Loaded) {
        if (Founded === true) {
            let ITD = StudentPersonalInformation;
            let ST = studentData;


            console.log(ST)


            return (
                <div className="eduall-print-area">
                    <div className="box">
                        <div>
                            <div className="print-enrollment-header">
                                <div className="ed-space">
                                    <div className="ed-flex">
                                        <button className="btn bg-main btn-icon-m0" onClick={handlePrint}><Print /> </button>
                                        <Form.Group className='ml-2' >
                                            <Form.Select onChange={(e) => Multiplicate(e.target.value)} style={{ maxWidth: '100px' }} >
                                                <option value="1">1X</option>
                                                <option value="2">2X</option>
                                                <option value="3">3X</option>
                                                <option value="4">4X</option>
                                                <option value="5">5X</option>
                                                <option value="6">6X</option>
                                            </Form.Select>
                                        </Form.Group>
                                    </div>
                                    <div className="ed-flex">
                                        <div>
                                            <BackButton />
                                        </div>
                                    </div>
                                </div>
                            </div>
                            <div ref={containerPrint} style={{ width: '100%', height: window.innerHeight }} >
                                {
                                    Total.map((item, index) => {
                                        return (
                                            <div class="ed-enrollment-report-box" key={index} >
                                                <section class="paper-container" >
                                                    <div class="PaperBox">
                                                        <div class="enrollment-print-data" >
                                                            <div class="report-body">
                                                                <section class="student-fc-report">
                                                                    <div class="top-information">
                                                                        <div class="logo-area">
                                                                            <img src={Hoot() + InstituteData.ed_institute_logo} alt="" />
                                                                        </div>
                                                                        <div class="top-text">
                                                                            <h1>Ficha de  Matrícula</h1>
                                                                            <div class="line"></div>
                                                                            <h5>{studentData.ed_academic_year_title}</h5>
                                                                            <div class="line"></div>
                                                                        </div>
                                                                    </div>
                                                                    <div class="mg-v">
                                                                        <div class="ed-space">
                                                                            <div>
                                                                                <h1>{InstituteData.ed_institute_name}</h1>
                                                                                <small className="grey-text text-grey">{InstituteData.ed_institute_slogan}</small>
                                                                            </div>
                                                                            <div><h5>Nº de matricula : {studentData.ed_student_code}</h5></div>
                                                                        </div>
                                                                    </div>
                                                                    <div class="student-name-box ed-flex ed-center col text-light">
                                                                        <h3>{studentData.ed_student_name}</h3>
                                                                    </div>

                                                                    <section>
                                                                        <div class="mt-4 mb-2"><strong>Informações pessoais</strong></div>
                                                                        <div class="table-content">
                                                                            <table class="table col   table-bordered">
                                                                                <tbody>
                                                                                    <tr>
                                                                                        <td>
                                                                                            <div class="ed-flex">
                                                                                                <div><strong>Data de nascimento:</strong></div>
                                                                                                <div class="ml-2">
                                                                                                    {moment(studentData.ed_student_birthday).format("MM-DD-YYYY")}
                                                                                                </div>
                                                                                            </div>
                                                                                        </td>
                                                                                        <td colSpan={3} >
                                                                                            <div class="ed-flex">
                                                                                                <div><strong>Bilhete de identidade :</strong></div>
                                                                                                <div class="ml-2">{studentData.ed_student_identityCard}</div>
                                                                                            </div>
                                                                                        </td>
                                                                                    </tr>
                                                                                    <tr>
                                                                                        <td>
                                                                                            <div class="ed-flex">
                                                                                                <div><strong>Nacionalidade :</strong></div>
                                                                                                <div class="ml-2">{studentData.ed_student_nacionality}</div>
                                                                                            </div>
                                                                                        </td>
                                                                                        <td>
                                                                                            <div class="ed-flex">
                                                                                                <div><strong>Idade :</strong></div>
                                                                                                <div class="ml-2">{CalcAgeByBirthday(studentData.ed_student_birthday)}</div>
                                                                                            </div>
                                                                                        </td>
                                                                                        <td>
                                                                                            <div class="ed-flex">
                                                                                                <div><strong>Sexo :</strong></div>
                                                                                                <div class="ml-2">{studentData.ed_student_gender === "male" ? "Masculino" : "Femenino"}</div>
                                                                                            </div>
                                                                                        </td>
                                                                                    </tr>
                                                                                </tbody>
                                                                            </table>
                                                                        </div>
                                                                        <section>
                                                                            <div class="mt-4 mb-2"><strong>Filiação</strong></div>
                                                                            <div class="table-content">
                                                                                <table class="table col   table-bordered">
                                                                                    <tbody>
                                                                                        <tr>
                                                                                            <td>
                                                                                                <div class="ed-flex">
                                                                                                    <div><strong>Nome do pai:</strong></div>
                                                                                                    <div class="ml-2">{StudentFatherData !== null ? StudentFatherData.parent_name : ""}</div>
                                                                                                </div>
                                                                                            </td>
                                                                                            <td>
                                                                                                <div class="ed-flex">
                                                                                                    <div><strong>Nome da mãe :</strong></div>
                                                                                                    <div class="ml-2">{StudentMotherData !== null ? StudentMotherData.parent_name : ""}</div>
                                                                                                </div>
                                                                                            </td>
                                                                                        </tr>
                                                                                    </tbody>
                                                                                </table>
                                                                            </div>
                                                                        </section>
                                                                    </section>

                                                                    <section>
                                                                        <div class="mt-4 mb-2"><strong>Informações de contacto</strong></div>
                                                                        <div class="table-content">
                                                                            <table class="table col   table-bordered">
                                                                                <tbody>
                                                                                    <tr>
                                                                                        <td>
                                                                                            <div class="ed-flex">
                                                                                                <div><strong>Morada:</strong></div>
                                                                                                <div class="ml-2">{studentData.ed_student_address}</div>
                                                                                            </div>
                                                                                        </td>
                                                                                        <td>
                                                                                            <div class="ed-flex">
                                                                                                <div><strong>Telefone :</strong></div>
                                                                                                <div class="ml-2">{studentData.ed_student_phone}</div>
                                                                                            </div>
                                                                                        </td>
                                                                                    </tr>
                                                                                    <tr>
                                                                                        <td>
                                                                                            <div class="ed-flex">
                                                                                                <div><strong>Email :</strong></div>
                                                                                                <div class="ml-2">{studentData.ed_student_email}</div>
                                                                                            </div>
                                                                                        </td>
                                                                                        <td>
                                                                                            <div class="ed-flex">
                                                                                                <div><strong>Telefone em caso de emergencia :</strong></div>
                                                                                                <div class="ml-2">{studentData.ed_student_phone2}</div>
                                                                                            </div>
                                                                                        </td>
                                                                                    </tr>
                                                                                </tbody>
                                                                            </table>
                                                                        </div>
                                                                    </section>

                                                                    <section>
                                                                        <div class="mt-4 mb-2"><strong>Documentação</strong></div>
                                                                        <div class="table-content">
                                                                            <table class="table col   table-bordered">
                                                                                <tbody>
                                                                                    <tr>
                                                                                        <td>
                                                                                            <div class="ed-flex ed-space">
                                                                                                <div><strong>Certificado de habilitações:</strong></div>
                                                                                                <div class="ml-2"><div className="check"></div></div>
                                                                                            </div>
                                                                                        </td>
                                                                                        <td>
                                                                                            <div class="ed-flex ed-space">
                                                                                                <div><strong>Fotocópias do documento de identificação :</strong></div>
                                                                                                <div class="ml-2"><div className="check"></div></div>
                                                                                            </div>
                                                                                        </td>
                                                                                    </tr>
                                                                                    <tr>
                                                                                        <td>
                                                                                            <div class="ed-flex ed-space">
                                                                                                <div><strong>Documento Militar :</strong></div>
                                                                                                <div class="ml-2"><div className="check"></div></div>
                                                                                            </div>
                                                                                        </td>
                                                                                        <td>
                                                                                            <div class="ed-flex ed-space">
                                                                                                <div><strong>Atestado Médico :</strong></div>
                                                                                                <div class="ml-2"><div className="check"></div></div>
                                                                                            </div>
                                                                                        </td>
                                                                                    </tr>
                                                                                    <tr>
                                                                                        <td>
                                                                                            <div class="ed-flex ed-space">
                                                                                                <div><strong>Fotografias :</strong></div>
                                                                                                <div class="ml-2"><div className="check"></div></div>
                                                                                            </div>
                                                                                        </td>
                                                                                        <td>
                                                                                            <div class="ed-flex ed-space">
                                                                                                <div><strong>Outros documentos :</strong></div>
                                                                                                <div class="ml-2"><div className="check"></div></div>
                                                                                            </div>
                                                                                        </td>
                                                                                    </tr>
                                                                                </tbody>
                                                                            </table>
                                                                        </div>
                                                                    </section>

                                                                    <section>
                                                                        <div class="mt-4 mb-2"><strong>Dados académicos</strong></div>
                                                                        <div class="table-content">
                                                                            <table class="table col   table-bordered">
                                                                                <tbody>
                                                                                    <tr>
                                                                                        <td>
                                                                                            <div class="ed-flex">
                                                                                                <div><strong>Turma:</strong></div>
                                                                                                <div class="ml-2">{studentData.ed_class_title}</div>
                                                                                            </div>
                                                                                        </td>
                                                                                        <td>
                                                                                            <div class="ed-flex">
                                                                                                <div><strong>Sala:</strong></div>
                                                                                                <div class="ml-2">{studentData.ed_classroom_title}</div>
                                                                                            </div>
                                                                                        </td>
                                                                                    </tr>
                                                                                    <tr>
                                                                                        <td>
                                                                                            <div class="ed-flex">
                                                                                                <div><strong>Nº de matrícula:</strong></div>
                                                                                                <div class="ml-2">{studentData.ed_student_code}</div>
                                                                                            </div>
                                                                                        </td>
                                                                                        <td>
                                                                                            <div class="ed-flex">
                                                                                                <div><strong>Curso:</strong></div>
                                                                                                <div class="ml-2">{studentData.ed_course_title}</div>
                                                                                            </div>
                                                                                        </td>
                                                                                    </tr>
                                                                                    <tr>
                                                                                        <td>
                                                                                            <div class="ed-flex">
                                                                                                <div><strong>Faculdade :</strong></div>
                                                                                                <div class="ml-2">{studentData.ed_faculty_title}</div>
                                                                                            </div>
                                                                                        </td>
                                                                                        <td>
                                                                                            <div class="ed-flex">
                                                                                                <div><strong>Nº de disciplinas (cadeiras) :</strong></div>
                                                                                                <div class="ml-2">{studentData.ed_class_subjects.split(",").length}</div>
                                                                                            </div>
                                                                                        </td>
                                                                                    </tr>
                                                                                </tbody>
                                                                            </table>
                                                                        </div>
                                                                    </section>
                                                                    <br />
                                                                    <div class="ed-space ed-flex auth">
                                                                        <div class="d-block">
                                                                            <div> <span>{InstituteData.ed_institute_state}</span></div>
                                                                            <span className='upercase'>
                                                                                {moment(studentData.ed_student_registerDate).format("MM-DD-YYYY, h:mm:ss a")}
                                                                            </span>
                                                                        </div>
                                                                        <div class="d-block auth-area">
                                                                            <div class="line"></div>
                                                                            <span>O aluno / Responsavel</span>
                                                                        </div>
                                                                    </div>
                                                                </section>
                                                            </div>
                                                        </div><br /><br />
                                                    </div>
                                                </section>
                                            </div>
                                        )
                                    })


                                }
                            </div>
                        </div>
                    </div>
                </div>
            )



        } else if (Founded === false) {
            return (
                <NotFounded />
            )
        }
    } else {
        return (
            <div className="loader-content-box">
                <Loader />
            </div>
        )
    }







}

export default EnrollmentPrint