import axios from "axios"; 
import Hoot from "./Hoot";

async function GetPersonData(id, type) {
  try {
    let url = "";
    switch (type) {
      case "employee":
        url = `${Hoot()}eduallsinglemployee/get/${id}`;
        break;
      case "parent":
        url = `${Hoot()}eduallsingleparent/get/${id}`;
        break;
      case "student":
        url = `${Hoot()}eduallsinglestudentapi/get/${id}`;
        break;
      default:
        return { name: null, gender: null };
    }

    const response = await axios.get(url);
    const data = Array.isArray(response.data) ? response.data[0] : response.data;

    if (!data) return { name: null, gender: null };

    if (type === "employee") return { name: data.ed_employee_name, gender: data.ed_employee_gender };
    if (type === "parent") return { name: data.ed_parent_name, gender: data.ed_parent_gender };
    if (type === "student") return { name: data.ed_student_name, gender: data.ed_student_gender };

    return { name: null, gender: null };
  } catch {
    return { name: null, gender: null };
  }
}

export default GetPersonData;
