import React, { useEffect, useState } from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap'
import { Save } from '@mui/icons-material';
import { Update } from '@material-ui/icons';
import { Link } from 'react-router-dom';
import DraggableModal from '../../../General/components/DraggableModal';
import { toast } from 'react-hot-toast';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import { GetInstituteCode } from '../../../General/components/InstituteData';
import RefreshList from '../../../General/components/RefreshList';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import ReplaceWord from '../../../General/components/ReplaceWord';



function NewSubject(props) {
  const [show, setShow] = useState(false);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [Founded, SetFounded] = useState(null);


  const [showBox, SetshowBox] = useState(false);
  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200);
  }

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };

  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});

  const INPUTS = {
    subject_title: CRValue("#subject_title"),
    subject_type: CRValue("#subject_type"),
    subject_category: CRValue("#subject_category"),
    institute_code: GetInstituteCode()
  };



  const FORMURL = [
    Hoot() + "eduallsubjectregisterapi/post/",
    props.get ? props.get : '',
    props.url ? props.url : ''
  ];

  const GET_DATA = async () => {
    if (props.update) {
      try {
        const response = await axios.get(FORMURL[1]);
        if (response.data.length > 0) {
          if (response.data[0] !== null) {
            document.querySelector("#subject_title").value = response.data[0].ed_subject_title;
            document.querySelector("#subject_type").value = response.data[0].ed_subject_type;
            document.querySelector("#subject_category").value = response.data[0].ed_subject_category;

            INPUTS.subject_title = response.data[0].ed_subject_title;
            INPUTS.subject_type = response.data[0].ed_subject_type;
            INPUTS.subject_category = response.data[0].ed_subject_category;
          }
        } else {
          toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
        }
      } catch (error) {
        toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
      }
    }
  }

  const setField = (field, value) => {
    setForm({ ...form, [field]: value });

    if (!!errors[field]) {
      setErrors({ ...errors, [field]: null });
    }
  }


  const validateForm = () => {
    const { subject_title, subject_category, subject_type } = form;
    const NewErrors = {};
    setRegisterStatus(0);
    if (INPUTS.subject_title === "" || INPUTS.subject_title === " ") {
      if (!subject_title || subject_title === '') NewErrors.subject_title = ReplaceWord("Disciplina") + ' invalido';
    } else { if (!subject_title) { setField("subject_title", INPUTS.subject_title); } }

    if (INPUTS.subject_category === "" || INPUTS.subject_category === " ") {
      if (!subject_category || subject_category === '') NewErrors.subject_category = 'Categoria  invalida';
    } else { if (!subject_category) { setField("subject_category", INPUTS.subject_category); } }

    if (INPUTS.subject_type === "" || INPUTS.subject_type === " ") {
      if (!subject_type || subject_type === '') NewErrors.subject_type = `Tipo de ${ReplaceWord("disciplina", true)} invalida`;
    } else { if (!subject_type) { setField("subject_type", INPUTS.subject_type); } }

    return NewErrors;
  }

  const SUBMIT_INPUTS = {
    subject_title: INPUTS.subject_title, subject_category: INPUTS.subject_category,
    subject_type: INPUTS.subject_type, institute_code: INPUTS.institute_code
  };

  const FormSubmit = (e) => {
    console.log(INPUTS);
    e.preventDefault();
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os  campos");
      setRegisterStatus(1);
    } else {
      if (!props.update) {
        try {
          axios.post(FORMURL[0], SUBMIT_INPUTS).then(() => {
            toast.success(ReplaceWord("Disciplina") + " registrada com sucesso !");
            setForm({});
            ClearInputs();
            setRegisterStatus(2);
            RefreshList(`.el-refresh-list`)
          }).catch((error) => {
            setRegisterStatus(1);
            const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
            toast.error(msg);
          });
        } catch (error) {
          setRegisterStatus(1);
          const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
          toast.error(msg);
        }
      } else {
        try {
          axios.put(FORMURL[2], SUBMIT_INPUTS)
            .then(() => {
              toast.success(ReplaceWord("Disciplina") + " atualizada com sucesso !");
              setForm({});
              ClearInputs();
              RefreshList(`.el-refresh-list`)
              setRegisterStatus(2);
              setTimeout(() => {
                handleClose();
              }, 500);
            }).catch((error) => {
              setRegisterStatus(1);
              const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
              toast.error(msg);
            });
        } catch (error) {
          setRegisterStatus(1);
          const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
          toast.error(msg);
        }

      }
    }
  };


  const handleInput = (e) => {
    switch (e.target.id) {
      case "subject_title":
        setField("subject_title", e.target.value)
        INPUTS.subject_title = e.target.value
        break;
      case "subject_type":
        setField("subject_type", e.target.value)
        INPUTS.subject_type = e.target.value;
        break;
      case "subject_category":
        setField("subject_category", e.target.value)
        INPUTS.subject_category = e.target.value;
        break;
      default:
    }
  }


  return (
    <div>
      <div onClick={handleShow}>
        {
          props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon /> Registrar nova {ReplaceWord("Disciplina", true)} </button>
        }
      </div>
      <Modal className={showBox ? ModalAnimationShow() : ModalAnimationClose()} centered dialogAs={DraggableModal} show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>{props.title ? props.title : 'Registrar '}  {ReplaceWord("Disciplina", true)}</h5>
            </div>
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={FormSubmit}>
          <Modal.Body className='scrollLimit'>
            <Form.Group className="mb-3"  >
              <Form.Label>Nome da {ReplaceWord("Disciplina", true)} <span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Control onChange={handleInput} className={!!errors.subject_title && 'is-invalid'} value={form.subject_title} isInvalid={!!errors.subject_title}
                type="text" id="subject_title" autoFocus />
              <Form.Control.Feedback type='invalid'>{errors.subject_title}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3 mt-3"  >
              <Form.Label>Tipo de {ReplaceWord("Disciplina", true)}<span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Select onChange={handleInput} className={!!errors.subject_type && 'is-invalid'} value={form.subject_type}
                isInvalid={!!errors.subject_type}
                id="subject_type">
                <option disabled selected>Selecionar uma opção...</option>
                <option value="1">Teórica</option>
                <option value="2">Prática</option>
                <option value="3">Teórico-Prática</option>
                <option value="4">Laboratorial</option>
                <option value="5">Seminário</option>
                <option value="6">Projeto</option>
                <option value="7">Estágio</option>
                <option value="8">Trabalho de Campo</option>
                <option value="9">Tutorada</option>
                <option value="10">Ensino à Distância</option>
              </Form.Select>
              <Form.Control.Feedback type='invalid'>{errors.subject_type}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3"  >
              <Form.Label>Categoria  da   {ReplaceWord("Disciplina")} </Form.Label>
              <Form.Select onChange={handleInput} id='subject_category' className={!!errors.subject_category && 'is-invalid'}
                value={form.subject_category}
                isInvalid={!!errors.subject_category} >
                <option disabled selected>Selecionar uma opção...</option>
                <option value="1">Design</option>
                <option value="2">Arte</option>
                <option value="3">Engenharia</option>
                <option value="4">Saúde</option>
                <option value="5">Ciências</option>
                <option value="6">Línguas</option>
                <option value="7">Tecnologia</option>
                <option value="8">Matemática</option>
                <option value="9">Humanidades</option>
                <option value="10">Economia</option>
                <option value="11">Gestão</option>
                <option value="12">Informática</option>
                <option value="13">Direito</option>
                <option value="14">Educação</option>
                <option value="15">Filosofia</option>
                <option value="16">Religião</option>
                <option value="17">História</option>
                <option value="18">Geografia</option>
              </Form.Select>
              <Form.Control.Feedback type='invalid'>{errors.subject_category}</Form.Control.Feedback>
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <div className="ed-space">
              <div className="ed-flex"></div>
              <div className="ed-flex">
                <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                {props.update ? (Founded === false ? <div></div> :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />}
              </div>
            </div>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  )
}

export default NewSubject