import React, { useEffect, useState } from 'react'
import { Avatar } from '@mui/material';  
import { styled } from '@mui/material/styles';
import Button from '@mui/material/Button';
import Tooltip, { TooltipProps, tooltipClasses } from '@mui/material/Tooltip';
import Typography from '@mui/material/Typography';
import {Form} from "react-bootstrap";
import GifPicker from 'gif-picker-react';
import InputEmoji from 'react-input-emoji'
import CheckinternetStatus from '../CheckinternetStatus';
import { BiSend, BiSmile, BiSticker, BiSolidFile } from 'react-icons/bi'
import {MdAttachFile} from "react-icons/md";
import {FiSend} from "react-icons/fi";
import { ImageOutline } from 'react-ionicons'
import { ArrowRedoOutline } from 'react-ionicons'
import { toast } from 'react-hot-toast';
import Hoot from '../Hoot';
import axios from 'axios';

const HtmlTooltip = styled(({ className, ...props }) => (
    <Tooltip placement="top" {...props} classes={{ popper: className }} />
  ))(({ theme }) => ({
    [`& .${tooltipClasses.tooltip}`]: {
      backgroundColor: '#ffff',
      color: 'rgba(0, 0, 0, 0.87)',
      maxWidth: 220,
      fontSize: theme.typography.pxToRem(12),
      border: '1px solid #fdfdfd',
      borderRadius:30,
      boxShadow:"var(--ed-shadow-1)",
      paddingLeft:10,
      paddingRight:10
    },
  }));

function CommentReactions({socket, url, no, id, type}) {
    const [ToggleInput, setToggleInput] =  useState(false);
    const [ReactionType, setReactionType] =  useState(null); 
    const [show, setShow] = useState(false);
    const [GifItem , setGifItem] = useState("");
    const [MessageText, setMessageText] = useState(""); 
    const [Reactions, setReactions] = useState([]);   
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [CommentsData , SetCommentsData] = useState([]); 
    const Icons = [{icon:"👍", class:"thumbsup"}, {icon:"👎", class:"thumbsdown"}, 
    {icon:"😥", class:"tears"}, {icon:"😍", class:"love"}, {icon:"❤", class:"heart"}, {icon:"👏", class:"clap"}];



async function loadData(){
  if(id !== null){
    try { 
      const response = await axios.get(Hoot()+"eduallgetcommentreactionbyidandtype/"+id+","+type);  
      setReactions(response.data);  
    } catch (error) {
      
    }
  } 
}

                
useEffect(()=>{ 
  loadData() 
},[]);


    const FormSubmit = ()=>{    
        setRegisterStatus(0);
        if(MessageText.split("").length >= 1){ 
          const FormData = { 
            comment_socketID: socket.id,
            comment_contentid:id,
            comment_text:MessageText,
            comment_gif:GifItem,
            comment_image:"",
            comment_type:type,
         };  
          
          try { 
            console.clear();
            console.log(url, FormData);

            socket.emit(url, FormData);  
            setMessageText("");
            setGifItem(1); 
          } catch (error) {
            console.clear();
            console.log(error);
            toast.error("Ocorreu um erro ao enviar a sua resposta !")
            setRegisterStatus(1)
          }  
        }else{
          setRegisterStatus(1);
        }
    };  
    
    const SendReaction = (e)=>{    
      setRegisterStatus(0);
      if(e !== null && e !== undefined){ 
        const FormData = {  
          reaction_contentid:id,
          reaction_contenttype:type,
          reaction_type:e, 
       };   
        try { 
          console.clear(); 
          socket.emit("eduall_send_content_commentreactionIo", FormData);   
          setReactionType(null);
        } catch (error) {
          console.clear();
          console.log(error);
          toast.error("Ocorreu um erro ao reagir ao comentario !");
        }  
      } 
  };
  
  

 const GetRealTimeData =  (data)=>{  
  console.log(data, id);
  if(data !== null && data !== undefined){
    if((data.ed_comment_reaction_contentID*1 === id*1)){ 
      if(data !== null & data !== undefined){
        SetCommentsData([...CommentsData, data]);
      };
    } 
  }
} 
  
useEffect(() => { 
  socket.on('eduall_response_content_reactions', (data) => GetRealTimeData(data.data, data.user)); 
}, [socket, CommentsData]); 


  const getGifImage = (e)=>{  
    console.log(e.preview.url);
    setGifItem(e.preview.url);
    setShow(false); 
   setTimeout(() => {
    FormSubmit();
   }, 1500);
 }


 function handleMessageText(text) {
   setMessageText(text); 
 }  

 function handleOnEnter(){ 
   FormSubmit();
 }

  


  return (
    <div className="ed-block col">  
    <div className='ed-flex'>
    {Reactions.length >= 1 ?
        <div className="reactions-area mr-2 ed-flex">
        {Reactions.map((reaction, index)=>{
        return(
        <div className="userrt" key={index+1} >
            <Avatar className='df'  src={Hoot()+reaction.ed_user_account_picture} sx={{width:24,height:24}}  />
            <div className="reaction-icon">{Icons[reaction.ed_comment_reaction_type].icon}</div>
        </div>
        )})}
      </div>
    : <></>}
        <div className="cursor-pointer like-comment">
        <HtmlTooltip placement="top"
           title={  
           <React.Fragment>
               <div className="ed-flex ed-center">
               {Icons.map((item, index)=>{
                  return(<div className={`cursor-pointer reaction-type  ${item.class}`} onClick={()=>SendReaction(index)}>{item.icon}</div>)
                })}
               </div>
          </React.Fragment>
          } >
       <span>Curtir</span>
      </HtmlTooltip> 
        </div>
       {!no ?
        <div className="ml-2 ed-flex">
        <div className="ed-flex cursor-pointer show-answers">
           <ArrowRedoOutline /> <span>(0) respostas</span>
        </div>
        <div className='comment-asnwer-input col'>
           <div className='cursor-pointer ml-2' onClick={()=>setToggleInput(ToggleInput === true ? false : true)} > <span>responder</span></div>
        </div>
      </div>
       : <></> }
    </div>  
    {ToggleInput === true ?
               <div className="mt-2 col">
               <Form> 
                   <div className="ed-flex col">
                       <div className="form-area col ed-flex">
                       <InputEmoji className="col"  onChange={handleMessageText}   cleanOnEnter
                     onEnter={handleOnEnter} borderRadius={6} theme="light" 
                      placeholder="Pesquisar ..." /> 
                       <div className="ed-flex messages-assets">
                         <div className="gif-toggle"> 
                         { CheckinternetStatus() === true ? 
                            <HtmlTooltip placement="top"
                            title={  
                            <React.Fragment>
                                <div className="ed-flex ed-center"> 
                                  <div className="cm-gif">
                                     <GifPicker locale="pt_PT" onGifClick={getGifImage} tenorApiKey={"AIzaSyAs6jyixfg6l_1hMawHp317rRdN0Fpc1dg"} />
                                  </div>
                                </div>
                           </React.Fragment>
                           } >
                         <div onClick={()=>setShow(show ? false : true)}><BiSticker /></div>
                       </HtmlTooltip>  
                           : <></> }  
                         </div> 
                       <div className="file-attach">
                            <input type="file" name="" hidden id="form-image" />
                            <label htmlFor="form-image"><ImageOutline /></label>
                       </div>
                       </div>
                       </div>
                       <div className="loader-area">
           
                       </div>
                   </div>
                </Form>
               </div>  
           : <></>}   
    </div>
  )
}

export default CommentReactions