// ==================== Modal: Criar/Editar Formulário ====================
function FormDesignerModal({ show, onClose, onSaved, defaultValue }) {
  const [savingStatus, setSavingStatus] = useState(null); // 0 processo, 1 erro, 2 sucesso
  const [schema, setSchema] = useState(() => defaultValue?.schema || []);
  const [meta, setMeta] = useState(() => ({
    name: defaultValue?.name || "",
    layout: defaultValue?.layout || "stack",
  }));

  useEffect(()=>{
    if (show) {
      setSchema(defaultValue?.schema || []);
      setMeta({ name: defaultValue?.name || "", layout: defaultValue?.layout || "stack" });
      setSavingStatus(null);
    }
  }, [show, defaultValue]);

  const addField = () => {
    setSchema((prev) => [
      ...prev,
      {
        id: `fld_${Date.now()}`,
        label: "Novo campo",
        key: `field_${prev.length + 1}`,
        type: "text",
        required: false,
        width: "12",
        options: [],
        placeholder: "",
      },
    ]);
  };

  const updateField = (id, patch) => setSchema((prev) => prev.map((f) => (f.id === id ? { ...f, ...patch } : f)));
  const removeField = (id) => setSchema((prev) => prev.filter((f) => f.id !== id));

  const persist = async () => {
    if (!meta.name.trim()) {
      toast.error("Dá um nome ao formulário.");
      setSavingStatus(1);
      return;
    }
    setSavingStatus(0);
    try {
      if (defaultValue?.id) {
        await api.put(`formbuilder/forms/${defaultValue.id}`, {
          name: meta.name.trim(),
          layout: meta.layout,
          schema,
        });
        toast.success("Formulário atualizado!");
      } else {
        await api.post("formbuilder/forms", {
          name: meta.name.trim(),
          layout: meta.layout,
          schema,
        });
        toast.success("Formulário criado!");
      }
      setSavingStatus(2);
      onSaved?.();
      setTimeout(onClose, 300);
    } catch (e) {
      setSavingStatus(1);
      toast.error(e?.response?.data?.message || "Erro ao salvar formulário.");
    }
  }; 

  {/** 
   size='lg' className={showBox ? ModalAnimationShow() : ModalAnimationClose()} centered dialogAs={DraggableModal} show={show} onHide={handleClose}  
    
  */}

  return (
    <Modal size="lg" centered  show={show} onHide={onClose}>
      <Modal.Header closeButton>
        <Modal.Title>
          <div className="ed-wrap align-center">
            <UserOptionDropDown />
            <h5 className="ml-2">{defaultValue?.id ? "Editar Formulário" : "Criar Formulário"}</h5>
          </div>
        </Modal.Title>
      </Modal.Header>
      <Modal.Body className="scrollLimit">
        <div className="fb-grid">
          <div className="fb-toolbar">
            <div style={{display:"flex", gap:8, alignItems:"center"}}>
              <Input placeholder="Nome do formulário" value={meta.name} onChange={(e)=>setMeta({...meta, name:e.target.value})}/>
              <Select
                className="ml-2"
                styles={{container:(p)=>({...p, minWidth:220})}}
                options={[
                  {value:"stack", label:"1 coluna (stack)"},
                  {value:"two", label:"2 colunas (flex)"}
                ]}
                value={meta.layout === "stack" ? {value:"stack", label:"1 coluna (stack)"} : {value:"two", label:"2 colunas (flex)"}}
                onChange={(opt)=>setMeta({...meta, layout: opt.value})}
              />
            </div>
            <div className="fb-actions">
              <button className="fb-btn-light" onClick={addField}><AddIcon fontSize="small"/> Adicionar Campo</button>
            </div>
          </div>

          {/* Lista de campos */}
          <div className="fb-grid">
            {schema.map((f)=>(
              <div key={f.id} className="fb-card" style={{border:"1px dashed #e7e8f0"}}>
                <div className="fb-actions">
                  <div className="fb-badge">key: {f.key}</div>
                  <div style={{display:"flex", gap:6}}>
                    <button className="btn btn-light" onClick={()=>removeField(f.id)}><DeleteIcon fontSize="small"/></button>
                  </div>
                </div>
                <div className="fb-row" style={{marginTop:8}}>
                  <div className="col-6">
                    <Form.Label>Label</Form.Label>
                    <Input value={f.label} onChange={(e)=>updateField(f.id, {label:e.target.value})}/>
                  </div>
                  <div className="col-6">
                    <Form.Label>Chave (name)</Form.Label>
                    <Input value={f.key} onChange={(e)=>updateField(f.id, {key:e.target.value.replace(/\s+/g,"_")})}/>
                  </div>
                  <div className="col-6">
                    <Form.Label>Tipo</Form.Label>
                    <Select options={FIELD_TYPES} value={FIELD_TYPES.find(t=>t.value===f.type)} onChange={(opt)=>updateField(f.id,{type:opt.value})}/>
                  </div>
                  <div className="col-6">
                    <Form.Label>Largura</Form.Label>
                    <Select options={[
                      {value:"12", label:"Linha inteira"},
                      {value:"6", label:"Meia linha"}
                    ]} value={{value:f.width,label:f.width==="12"?"Linha inteira":"Meia linha"}} onChange={(opt)=>updateField(f.id,{width:opt.value})}/>
                  </div>
                  <div className="col-6">
                    <Form.Label>Placeholder</Form.Label>
                    <Input value={f.placeholder || ""} onChange={(e)=>updateField(f.id, {placeholder:e.target.value})}/>
                  </div>
                  <div className="col-6" style={{display:"flex", alignItems:"flex-end", gap:10}}>
                    <Form.Check type="switch" label="Obrigatório" checked={!!f.required} onChange={(e)=>updateField(f.id, {required:e.target.checked})}/>
                    {["select","radio"].includes(f.type) && (
                      <span className="grey-text">Defina as opções abaixo</span>
                    )}
                  </div>
                  {["select","radio"].includes(f.type) && (
                    <div className="col-12">
                      <Form.Label>Opções (uma por linha)</Form.Label>
                      <Form.Control as="textarea" rows={3} value={(f.options||[]).join("\n")}
                        onChange={(e)=>updateField(f.id, {options: e.target.value.split("\n").map(s=>s.trim()).filter(Boolean)})}/>
                    </div>
                  )}
                </div>
              </div>
            ))}
            {schema.length===0 && (<div className="grey-text">Adiciona campos para construir o formulário.</div>)}
          </div>
        </div>
      </Modal.Body>
      <Modal.Footer>
        <div className="ed-space">
          <div/>
          <div className="ed-flex">
            <Button className="bg-light text-dark" onClick={onClose}>Cancelar</Button>
            <SaveButton className="ml-2" title={defaultValue?.id ? "Salvar" : "Criar"} status={savingStatus} onClick={persist} />
          </div>
        </div>
      </Modal.Footer>
    </Modal>
  );
}

// ==================== Modal: Registar/Editar Dados ====================
function EntryModal({ show, onClose, form, editing, onSaved }) {
  const [model, setModel] = useState(()=>editing?.data || {});
  const [savingStatus, setSavingStatus] = useState(null);
  const [errors, setErrors] = useState({});

  useEffect(()=>{ if (show) { setModel(editing?.data || {}); setErrors({}); setSavingStatus(null);} }, [show, editing]);

  const setField = (key, value) => setModel((m)=>({...m, [key]: value}));

  const validate = () => {
    const errs = {};
    for (const f of form.schema || []) {
      if (f.required) {
        const v = model[f.key];
        const empty = v === undefined || v === null || String(v).trim() === "";
        if (empty) errs[f.key] = requiredMsg(f.label);
      }
    }
    setErrors(errs);
    return errs;
  };

  const persist = async () => {
    const errs = validate();
    if (Object.keys(errs).length) {
      toast.error("Preenche os campos obrigatórios.");
      setSavingStatus(1);
      return;
    }
    setSavingStatus(0);
    try {
      if (editing?.id) {
        await api.put(`formbuilder/forms/${form.id}/entries/${editing.id}`, { data: model });
        toast.success("Registo atualizado!");
      } else {
        await api.post(`formbuilder/forms/${form.id}/entries`, { data: model });
        toast.success("Registo criado!");
      }
      setSavingStatus(2);
      onSaved?.();
      setTimeout(onClose, 300);
    } catch (e) {
      setSavingStatus(1);
      toast.error(e?.response?.data?.message || "Erro ao salvar.");
    }
  };

  const renderField = (fld) => {
    const common = {
      className: errors[fld.key] ? "is-invalid" : "",
      placeholder: fld.placeholder || "",
      value: model[fld.key] || "",
      onChange: (e)=>setField(fld.key, e.target.value),
    };

    switch (fld.type) {
      case "text": return <Form.Control {...common} type="text"/>;
      case "number": return <Form.Control {...common} type="number"/>;
      case "date": return <Form.Control {...common} type="date"/>;
      case "textarea": return <Form.Control {...common} as="textarea" rows={3}/>;
      case "quill":
        return (
          <ReactQuill value={model[fld.key] || ""} onChange={(v)=>setField(fld.key, v)} />
        );
      case "select":
        return (
          <Form.Select value={model[fld.key] || ""} onChange={(e)=>setField(fld.key, e.target.value)}>
            <option value="">— selecione —</option>
            {(fld.options||[]).map((opt,i)=><option key={i} value={opt}>{opt}</option>)}
          </Form.Select>
        );
      case "radio":
        return (
          <div style={{display:"flex", gap:14, flexWrap:"wrap"}}>
            {(fld.options||[]).map((opt,i)=>(
              <Form.Check
                key={i}
                type="radio"
                name={`radio_${fld.key}`}
                id={`radio_${fld.key}_${i}`}
                label={opt}
                checked={model[fld.key] === opt}
                onChange={()=>setField(fld.key, opt)}
              />
            ))}
          </div>
        );
      case "checkbox":
        return (
          <Form.Check
            type="checkbox"
            id={`chk_${fld.key}`}
            label=""
            checked={!!model[fld.key]}
            onChange={(e)=>setField(fld.key, e.target.checked)}
          />
        );
      default: return <Form.Control {...common} type="text"/>;
    }
  };

  return (
    <Modal size="lg" className={show ? ModalAnimationShow() : ModalAnimationClose()} centered dialogAs={DraggableModal} show={show} onHide={onClose}>
      <Modal.Header closeButton>
        <Modal.Title>
          <div className="ed-wrap align-center">
            <UserOptionDropDown />
            <h5 className="ml-2">{editing?.id ? "Editar Registo" : "Novo Registo"}</h5>
          </div>
        </Modal.Title>
      </Modal.Header>
      <Modal.Body>
        <div className="fb-grid">
          <div className="fb-row">
            {(form.schema||[]).map((fld)=>(
              <div key={fld.id} className={ (form.layout==="two" && fld.width==="6") ? "col-6" : "col-12"}>
                <Form.Group className="mb-3">
                  <Form.Label>{fld.label}{fld.required && <span className="text-danger ml-1">*</span>}</Form.Label>
                  {renderField(fld)}
                  {!!errors[fld.key] && <div className="invalid-feedback d-block">{errors[fld.key]}</div>}
                </Form.Group>
              </div>
            ))}
            {(!form.schema || form.schema.length===0) && <div className="grey-text">Este formulário ainda não tem campos.</div>}
          </div>
        </div>
      </Modal.Body>
      <Modal.Footer>
        <div className="ed-space">
          <div/>
          <div className="ed-flex">
            <Button className="bg-light text-dark" onClick={onClose}>Cancelar</Button>
            <SaveButton className="ml-2" title="Guardar" status={savingStatus} onClick={persist} />
          </div>
        </div>
      </Modal.Footer>
    </Modal>
  );
}

// ==================== Modal: Importar Excel ====================
function ImportModal({ show, onClose, formId, formSchema }) {
  const [file, setFile] = useState(null);
  const [sheet, setSheet] = useState(null);
  const [columns, setColumns] = useState([]);
  const [rows, setRows] = useState([]);
  const [mapping, setMapping] = useState({});
  const [loading, setLoading] = useState(false);
  const [progress, setProgress] = useState({ total:0, processed:0, jobId:null });

  useEffect(()=>{
    const onProg = (p) => {
      if (p?.form_id === Number(formId)) {
        setProgress({ total: p.total_rows||0, processed: p.processed_rows||0, jobId: p.job_id });
      }
    };
    socket.on("formbuilder:import:progress", onProg);
    return () => socket.off?.("formbuilder:import:progress", onProg);
  }, [formId]);

  const parseExcel = async (f) => {
    const buf = await f.arrayBuffer();
    const wb = XLSX.read(buf, { type: "array" });
    const wsname = wb.SheetNames[0];
    const ws = wb.Sheets[wsname];
    const data = XLSX.utils.sheet_to_json(ws, { header: 1 });
    const hdr = (data[0] || []).map(String);
    const body = data.slice(1).map(row=>{
      const o = {};
      hdr.forEach((c, idx)=>o[c]=row[idx]);
      return o;
    });
    setSheet(wsname);
    setColumns(hdr);
    setRows(body);
    setMapping({});
  };

  const startImport = async () => {
    if (!rows.length) {
      toast.error("Nenhum dado detetado.");
      return;
    }
    const formKeys = new Set(formSchema.map(f=>f.key));
    const usedKeys = new Set(Object.values(mapping).filter(Boolean));
    if (usedKeys.size===0) {
      toast.error("Mapeia pelo menos uma coluna.");
      return;
    }
    const data = rows.map(r => {
      const obj = {};
      for (const [col, key] of Object.entries(mapping)) {
        if (key && key !== "__ignore__" && formKeys.has(key)) {
          obj[key] = r[col];
        }
      }
      return obj;
    });

    setLoading(true);
    setProgress({ total: data.length, processed: 0, jobId: null });
    try {
      const { data: resp } = await api.post(`formbuilder/forms/${formId}/import`, { rows: data });
      if (resp?.job_id) {
        toast("Importação iniciada…");
      } else {
        toast.success("Importação concluída!");
      }
    } catch (e) {
      toast.error(e?.response?.data?.message || "Falha ao iniciar importação.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Modal size="lg" className={show ? ModalAnimationShow() : ModalAnimationClose()} centered dialogAs={DraggableModal} show={show} onHide={onClose}>
      <Modal.Header closeButton>
        <Modal.Title>
          <div className="ed-wrap align-center">
            <UserOptionDropDown />
            <h5 className="ml-2">Importar do Excel</h5>
          </div>
        </Modal.Title>
      </Modal.Header>
      <Modal.Body>
        <div className="fb-grid">
          <div className="fb-card">
            <div className="fb-actions">
              <div>
                <input type="file" accept=".xlsx,.xls" onChange={(e)=>setFile(e.target.files?.[0]||null)}/>
              </div>
              <div>
                <button className="fb-btn-light" onClick={()=>file && parseExcel(file)} disabled={!file}><UploadIcon/> Ler ficheiro</button>
              </div>
            </div>
            {sheet && <div className="mt-2 grey-text">Folha: <b>{sheet}</b> • Linhas: <b>{rows.length}</b></div>}
          </div>

          {!!columns.length && (
            <div className="fb-card">
              <div className="fb-title">Mapeamento de colunas</div>
              <div className="fb-grid" style={{gap:10}}>
                {columns.map((col)=>(
                  <div key={col} className="fb-row" style={{alignItems:"center"}}>
                    <div className="col-6">
                      <Badge bg="light" text="dark" style={{fontSize:12}}>{col}</Badge>
                    </div>
                    <div className="col-6">
                      <Select
                        options={[
                          {value:"__ignore__", label:"(Ignorar)"},
                          ...formSchema.map(f=>({value:f.key, label:`${f.label} (${f.key})`})),
                        ]}
                        value={
                          mapping[col] ?
                          (mapping[col]==="__ignore__" ? {value:"__ignore__", label:"(Ignorar)"} :
                          {value:mapping[col], label: `${(formSchema.find(f=>f.key===mapping[col])||{}).label || mapping[col]} (${mapping[col]})`}) : null
                        }
                        onChange={(opt)=>setMapping((m)=>({...m, [col]: opt?.value}))}
                      />
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {!!progress.total && (
            <div className="fb-card">
              <div className="fb-title">Progresso</div>
              <div className="grey-text">Processados: {progress.processed} / {progress.total}</div>
              <div className="progress mt-2">
                <div className="progress-bar" role="progressbar" style={{width: `${Math.round(progress.processed*100/(progress.total||1))}%`}} />
              </div>
            </div>
          )}
        </div>
      </Modal.Body>
      <Modal.Footer>
        <div className="ed-space">
          <div/>
          <div className="ed-flex">
            <Button className="bg-light text-dark" onClick={onClose}>Fechar</Button>
            <SaveButton className="ml-2" title="Iniciar Importação" status={loading ? 0 : null} onClick={startImport} />
          </div>
        </div>
      </Modal.Footer>
    </Modal>
  );
}

// ==================== Página principal ====================
export default function FormBuilder() {
  const [forms, setForms] = useState([]);
  const [selected, setSelected] = useState(null);
  const [designerOpen, setDesignerOpen] = useState(false);
  const [designerDefault, setDesignerDefault] = useState(null);
  const [entryOpen, setEntryOpen] = useState(false);
  const [importOpen, setImportOpen] = useState(false);
  const [loadingForms, setLoadingForms] = useState(false);

  const [entries, setEntries] = useState([]);
  const [entriesLoading, setEntriesLoading] = useState(false);
  const [editingEntry, setEditingEntry] = useState(null);
  const [loadStatus, setLoadStatus] = useState(null);

  const loadForms = async () => {
    setLoadingForms(true);
    try {
      const { data } = await api.get("formbuilder/forms");
      setForms(data || []);
      if (data?.length && !selected) setSelected(data[0]);
    } catch (e) {
      toast.error("Falha ao carregar formulários");
    } finally {
      setLoadingForms(false);
    }
  };

  const loadEntries = async (formId) => {
    if (!formId) return;
    setLoadStatus(0);
    setEntriesLoading(true);
    try {
      const { data } = await api.get(`formbuilder/forms/${formId}/entries?limit=100`);
      setEntries(data?.items || []);
      setLoadStatus(2);
    } catch (e) {
      setLoadStatus(1);
      toast.error("Falha ao carregar registos");
    } finally {
      setEntriesLoading(false);
    }
  };

  useEffect(()=>{ loadForms(); },[]);
  useEffect(()=>{ if (selected?.id) loadEntries(selected.id); }, [selected?.id]);

  useEffect(()=>{
    const onCreated = (p)=> { if (p?.form?.id) loadForms(); };
    const onUpdated = (p)=> { if (p?.form?.id) loadForms(); };
    const onDeleted = (p)=> {
      if (p?.form_id) {
        setForms((prev)=>prev.filter(f=>Number(f.id)!==Number(p.form_id)));
        if (selected && Number(selected.id)===Number(p.form_id)) setSelected(null);
      }
    };
    const onEntry = (p)=> { if (selected && Number(selected.id)===Number(p.form_id)) loadEntries(selected.id); };
    socket.on("formbuilder:form:created", onCreated);
    socket.on("formbuilder:form:updated", onUpdated);
    socket.on("formbuilder:form:deleted", onDeleted);
    socket.on("formbuilder:entry:changed", onEntry);
    return ()=> {
      socket.off?.("formbuilder:form:created", onCreated);
      socket.off?.("formbuilder:form:updated", onUpdated);
      socket.off?.("formbuilder:form:deleted", onDeleted);
      socket.off?.("formbuilder:entry:changed", onEntry);
    };
  }, [selected]);

  const deleteForm = async (id) => {
    if (!window.confirm("Eliminar este formulário?")) return;
    try {
      await api.delete(`formbuilder/forms/${id}`);
      toast.success("Formulário eliminado");
      await loadForms();
    } catch (e) {
      toast.error("Não foi possível eliminar");
    }
  };

  const deleteEntry = async (id) => {
    if (!selected?.id) return;
    if (!window.confirm("Eliminar este registo?")) return;
    try {
      await api.delete(`formbuilder/forms/${selected.id}/entries/${id}`);
      toast.success("Registo eliminado");
      loadEntries(selected.id);
    } catch (e) {
      toast.error("Falha ao eliminar");
    }
  };

  const columns = [
    { field:"index", headerName:"#", width:60, resizable:true },
    ...((selected?.schema||[]).slice(0,4).map((f)=>({
      field: f.key,
      headerName: f.label,
      resizable: true,
      width: 220
    }))),
    { field:"created_at", headerName:"Criado em", width:160, resizable:true },
    {
      field:"action", headerName:"Ação", resizable:true,
      cellRenderer:(props)=>{
        return (
          <div className="ed-flex">
            <button className="btn-circle bg-info text-light" onClick={()=>setEditingEntry({id: props.data.id, data: props.data.__raw})}><EditIcon/></button>
            <button className="btn-circle bg-danger ml-2 text-light" onClick={()=>deleteEntry(props.data.id)}><DeleteIcon/></button>
            <button className="btn-circle bg-success ml-2 text-light" onClick={()=>{ toast(`${JSON.stringify(props.data.__raw,null,2)}`) }}><VisibilityIcon/></button>
          </div>
        );
      }
    }
  ];

  const tableRows = entries.map((e,idx)=>({
    index: idx+1,
    id: e.id,
    created_at: new Date(e.created_at).toLocaleString(),
    __raw: e.data,
    ...Object.fromEntries((selected?.schema||[]).slice(0,4).map(f=>[f.key, stripHtml(e.data?.[f.key])]))
  }));

  function stripHtml(v){
    if (!v) return "";
    const el = document.createElement("div");
    el.innerHTML = v;
    return el.textContent || el.innerText || "";
  }

  const exportPdf = () => {
    ExportDataToTablesToPdf({
      fileName: `Registos - ${selected?.name || "Formulário"}`,
      headerId: null,
      contentId: "fb-entries-wrapper",
      footerId: null,
      rotation: "landscape",
      buttonId: "fb-export-pdf-btn",
      customHeader: `Registos — ${selected?.name || ""}`,
      excludedColumns: ["Ação"]
    });
  };

  const exportXlsx = () => {
    ExportDataForTablesExcel(`Registos - ${selected?.name || "Formulário"}`, ["Ação"]);
  };

  return (
    <div className="fb-shell">
      <Global/>

      {/* Sidebar */}
      <div className="fb-sidebar">
        <div className="fb-card">
          <div className="fb-actions">
            <div className="fb-title">Formulários</div>
            <button className="fb-btn" onClick={()=>{ setDesignerDefault(null); setDesignerOpen(true); }}>
              <AddIcon/> Novo
            </button>
          </div>
          <div className="mt-2">
            <div className="position-relative mb-2">
              <Input placeholder="Pesquisar…" />
              <SearchIcon style={{position:"absolute", right:10, top:10, color:"#98a0b3"}}/>
            </div>
            {loadingForms && <div className="grey-text"><Spinner size="sm" className="mr-2"/> a carregar…</div>}
            {forms.map((f)=>(
              <div key={f.id} className={`fb-form-item ${selected?.id===f.id ? "active":""}`} onClick={()=>setSelected(f)}>
                <Avatar sx={{width:36, height:36}} />
                <div style={{flex:1}}>
                  <div style={{fontWeight:700}}>{f.name}</div>
                  <div className="grey-text" style={{fontSize:12}}>{(f.schema||[]).length} campos</div>
                </div>
                <button className="btn btn-light" onClick={(e)=>{e.stopPropagation(); setDesignerDefault(f); setDesignerOpen(true);}}><EditIcon fontSize="small"/></button>
                <button className="btn btn-light ml-1" onClick={(e)=>{e.stopPropagation(); deleteForm(f.id);}}><DeleteIcon fontSize="small"/></button>
              </div>
            ))}
            {(!forms || forms.length===0) && !loadingForms && <div className="grey-text">Sem formulários ainda.</div>}
          </div>
        </div>

        <div className="fb-card">
          <div className="fb-title">Ações</div>
          <div className="fb-grid" style={{gridTemplateColumns:"1fr 1fr"}}>
            <button className="fb-btn-light" onClick={()=>selected && setEntryOpen(true)} disabled={!selected}><AddIcon/> Registar</button>
            <button className="fb-btn-light" onClick={()=>selected && setImportOpen(true)} disabled={!selected}><UploadIcon/> Importar</button>
          </div>
        </div>
      </div>

      {/* Main */}
      <div className="fb-grid">
        <div className="fb-card">
          <div className="fb-actions">
            <div>
              <div className="fb-title">{selected?.name || "Selecione um formulário"}</div>
              {selected && <div className="grey-text">{selected?.layout==="two" ? "Layout: 2 colunas" : "Layout: 1 coluna"}</div>}
            </div>
            <div className="ed-flex">
              <button className="fb-btn-light" onClick={()=>selected && setEntryOpen(true)} disabled={!selected}><AddIcon/> Novo Registo</button>
              <button className="fb-btn-light ml-2" onClick={()=>selected && setImportOpen(true)} disabled={!selected}><UploadIcon/> Importar</button>
              <button className="fb-btn ml-2" onClick={()=>selected && navigator.clipboard.writeText(JSON.stringify(selected,null,2)).then(()=>toast.success("Schema copiado!"))} disabled={!selected}><CopyIcon/> Copiar schema</button>
            </div>
          </div>

          {/* Preview do form */}
          {selected ? (
            <div className="fb-row">
              {(selected.schema||[]).map((f)=>(
                <div key={f.id} className={ (selected.layout==="two" && f.width==="6") ? "col-6": "col-12"}>
                  <Form.Group className="mb-3">
                    <Form.Label>{f.label}{f.required && <span className="text-danger ml-1">*</span>}</Form.Label>
                    <Input placeholder={f.placeholder || f.key} readOnly/>
                  </Form.Group>
                </div>
              ))}
              {(selected.schema||[]).length===0 && <div className="grey-text">Sem campos.</div>}
            </div>
          ) : (
            <div className="grey-text">Escolhe um formulário no painel à esquerda.</div>
          )}
        </div>

        {/* Registos */}
        <div className="fb-card" id="fb-entries-wrapper">
          <div className="fb-actions">
            <div className="fb-title">Registos</div>
            <div className="ed-flex">
              <button className="fb-btn-light" onClick={()=>selected && loadEntries(selected.id)} disabled={!selected}>
                <RefreshButton status={loadStatus} action={()=>selected && loadEntries(selected.id)}/>
              </button>
              <button id="fb-export-pdf-btn" className="fb-btn-light ml-2" onClick={exportPdf} disabled={!selected}><DownloadIcon/> PDF</button>
              <button className="fb-btn-light ml-2" onClick={exportXlsx} disabled={!selected}><DownloadIcon/> Excel</button>
            </div>
          </div>

          {entriesLoading ? (
            <div className="grey-text"><Spinner size="sm" className="mr-2"/> a carregar…</div>
          ) : (
            <TableGrid TableHead={columns} TableBody={tableRows} TableTitle={`Registos de ${selected?.name || ""}`} TableBtn={<div/>} />
          )}
        </div>
      </div>

      {/* Modais */}
      <FormDesignerModal
        show={designerOpen}
        onClose={()=>setDesignerOpen(false)}
        onSaved={()=>loadForms()}
        defaultValue={designerDefault && {
          id: designerDefault.id,
          name: designerDefault.name,
          layout: designerDefault.layout,
          schema: designerDefault.schema || []
        }}
      />
      {selected && (
        <>
          <EntryModal
            show={entryOpen || !!editingEntry}
            onClose={()=>{ setEntryOpen(false); setEditingEntry(null); }}
            form={selected}
            editing={editingEntry}
            onSaved={()=>loadEntries(selected.id)}
          />
          <ImportModal
            show={importOpen}
            onClose={()=>setImportOpen(false)}
            formId={selected.id}
            formSchema={selected.schema || []}
          />
        </>
      )}
    </div>
  );
}
