import React, { useState } from 'react';  
import Alert from 'react-bootstrap/Alert';
import Form from 'react-bootstrap/Form';  
import { Link, useParams } from 'react-router-dom'; 
import MainAuthScreen from './MainAuthScreen';
import Hoot from '../General/components/Hoot';
import axios from 'axios';
import SaveButton from '../Dashboard/components/elements/SaveButton';
import { passwordStrength } from 'check-password-strength';

function NewPassword() {
    document.title = "Trocar password";

    const [messageWarning, setMessageWarning] = useState(null);
    const [show, setShow] = useState(true);
    const [ed_password, setEd_password] = useState("");
    const [ed_password2, setEd_password2] = useState("");
    const [RegisterStatus, setRegisterStatus] = useState(null); 
    const [MessageType, setMessageType] = useState(1);
    const [PasswordStrength, setPasswordStrength] = useState(0);

    const { id, code } = useParams(); // pega id e código da URL

    function hideMessage() {
        setMessageWarning(null); 
        setShow(false);
    } 

    const ResetPassword = async () => {  
        setRegisterStatus(0);  
        setMessageWarning(null);

        try {
            if (!ed_password || !ed_password2) {
                setMessageWarning("Preencha corretamente os campos"); 
                setRegisterStatus(1);   
                return;
            }

            if (ed_password !== ed_password2) {
                setRegisterStatus(1);  
                setMessageWarning('As passwords não combinam !'); 
                return;
            }

            if (passwordStrength(ed_password).value.toLowerCase() === "weak") {
                setRegisterStatus(1);  
                setMessageWarning("Senha muito fraca!");
                return;
            }
 
            const res = await axios.post(Hoot() + 'eduallpasswordupdate', {
                ed_verification_code: code,
                ed_verification_user: id,
                ed_user_password: ed_password
            });

            setRegisterStatus(2); 
            setMessageWarning("Password modificada com sucesso !");
            setMessageType(2);

        } catch (error) {
            setRegisterStatus(1);
            console.log(error);
            if (error?.response?.data?.msg) {
                setMessageWarning(error.response.data.msg);
            } else {
                setMessageWarning("Erro ao estabelecer ligação com o servidor");
            }
        }
    }

    const Reset = async (e) => {
        e.preventDefault();  
        ResetPassword();
    }

    const handleInput = (e) => {  
        const { id: inputId, value } = e.target;

        switch (inputId) { 
            case "ed_user_password": 
                setEd_password(value);
                const strength = passwordStrength(value).value.toLowerCase();
                if (value.length === 0) setPasswordStrength(0);
                else if (strength === "weak") setPasswordStrength(1);
                else if (strength === "medium") setPasswordStrength(2);
                else if (strength === "strong") setPasswordStrength(3);
                else setPasswordStrength(1);
                break; 
            case "ed_user_password2": 
                setEd_password2(value);
                break; 
            default:
                break;
        }
    }

    return (
        <MainAuthScreen content={
            <div>
                <div className="block-header">
                    <h1>Trocar password</h1>
                    <p>Explore mais da sua criatividade, encontre tranquilidade e sonhos.</p>
                </div>
                <section> 
                    <div className="form-area">
                        <h1>Trocar password</h1>
                        <p>Parece que esqueceu a sua password, aproveite este momento para trocar a sua senha e acessar a nossa plataforma.</p>
                        
                        <div className="form-message">
                            {messageWarning && 
                                <Alert dismissible variant={MessageType === 1 ? "danger" : 'success'} onClose={hideMessage}>
                                    <h5 className={MessageType === 1 ? 'text-danger' : ''}>{messageWarning}</h5>
                                </Alert>
                            }
                        </div> 

                        <Form onSubmit={Reset}> 
                            <Form.Group className="mb-3">
                                <div className="ed-space">
                                    <Form.Label>Nova password</Form.Label>
                                    <div className="ed-flex">
                                        <div className={PasswordStrength >= 1 ? "dot bg-green" : "dot"}></div>
                                        <div className={PasswordStrength >= 2 ? "dot bg-green" : "dot"}></div>
                                        <div className={PasswordStrength >= 3 ? "dot bg-green" : "dot"}></div>
                                    </div>
                                </div> 
                                <Form.Control
                                    onChange={handleInput} 
                                    value={ed_password} 
                                    id="ed_user_password"  
                                    type="password" 
                                    className='mb-2' 
                                    required 
                                    placeholder="Digite a nova password" 
                                />
                            </Form.Group> 

                            <Form.Group className="mb-3">
                                <Form.Label>Repetir nova password</Form.Label>
                                <Form.Control
                                    onChange={handleInput} 
                                    value={ed_password2} 
                                    id="ed_user_password2"  
                                    type="password" 
                                    className='mb-2' 
                                    required 
                                    placeholder="Redigite a nova password" 
                                />
                            </Form.Group> 

                            <SaveButton class='btn mt-2 col-lg-12 bg-main text-light' title={'Salvar'} status={RegisterStatus} /> 
                            <br />
                            <Link to='/signup' className='text-main'>Ainda não se cadastrou ?</Link>
                        </Form> 
                    </div>
                </section> 
            </div>
        }/> 
    ); 
} 

export default NewPassword;
