import React, { useEffect, useState } from "react";
import AddCircleOutlineIcon from "@mui/icons-material/AddCircleOutline";
import { Modal, Form, Button, Badge } from "react-bootstrap";
import { InfoOutlined, Save } from "@mui/icons-material";
import { Update } from "@material-ui/icons";
import DraggableModal from "../../../General/components/DraggableModal";
import axios from "axios";
import Hoot from "../../../General/components/Hoot";
import ClearInputs from "../../../General/components/ClearInputs";
import { toast } from "react-hot-toast";
import {
  ClassDataOptions,
  GetAcademicYear_byclass,
  GetAcademiclevel_byclass,
  GetClassroom_byclass,
  GetCourse_byclass,
  GetPeriod_byclass,
  GetServicePrice,
  ServiceDataOptions,
  useStudentsArrayNew, // ✅ novo hook customizado
} from "../../../General/components/InstituteData";
import CRValue from "../../../General/components/CRValue";
import SelectSearch from "react-select-search";
import RefreshList from "../../../General/components/RefreshList";
import StudentDetailsMenu from "../elements/StudentDetailsMenu";
import UserOptionDropDown from "../elements/UserOptionDropDown";
import SaveButton from "../elements/SaveButton";
import {
  ModalAnimationClose,
  ModalAnimationShow,
} from "../../../General/components/ModalAnimations";
import ReplaceWord from "../../../General/components/ReplaceWord";
import { MultiSelect } from "react-multi-select-component";

function NewEnrollmentConfirmationModal(props) {
  const [show, setShow] = useState(false);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});
  const [studentCode, setStudentCode] = useState(null);
  const [Class, setClass] = useState(null);
  const [serviceCode, setServiceCode] = useState(null);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [showBox, SetshowBox] = useState(false);
  const [multiStudents, setMultiStudents] = useState([]);

  // ✅ obtém a lista de estudantes via hook
  const { students, loading } = useStudentsArrayNew();
  const [studentsOptions, setStudentsOptions] = useState([]);

  useEffect(() => {
    if (!loading && students.length > 0) {
      const formatted = students.map((item) => ({
        label: item.name,
        value: item.value,
      }));
      setStudentsOptions(formatted);
    }
  }, [students, loading]);

  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => setShow(false), 1200);
  };

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      setServiceCode(CRValue("#enrollment_service_code"));
      GET_DATA();
    }, 800);
  };

  const INPUTS = {
    enrollment_student_code: props.studentCode ? props.studentCode : studentCode,
    enrollment_class: CRValue("#enrollment_class"),
    enrollment_service_code: CRValue("#enrollment_service_code"),
  };

  const FORMURL = [
    Hoot() + "eduallregisterstudentenrollmentconfirmation/post",
    Hoot() + "eduallstudentenrollmentregister/post",
    props.url ? props.url : "",
    props.get ? props.get : "",
  ];

  const GET_DATA = async () => {
    if (props.update) {
      try {
        const response = await axios.get(FORMURL[3]);
        if (response.data.length > 0) {
          const data = response.data[0];
          if (props.confirmation) {
            document.querySelector("#enrollment_class").value =
              data.ed_enrollment_confirmation_class;
            document.querySelector("#enrollment_service_code").value =
              data.ed_enrollment_confirmation_service;
            setClass(data.ed_enrollment_confirmation_class);
            setServiceCode(data.ed_enrollment_confirmation_service);
          } else {
            document.querySelector("#enrollment_service_code").value =
              data.ed_enrollment_service;
            if (document.querySelectorAll("#enrollment_class").length > 0)
              document.querySelector("#enrollment_class").value =
                data.ed_enrollment_class;
            setClass(data.ed_enrollment_class);
            setServiceCode(data.ed_enrollment_service);
          }
        } else {
          toast.error("Não foi possível carregar os dados!");
        }
      } catch (error) {
        toast.error("Erro ao carregar dados da matrícula!");
      }
    }
  };

  const setField = (field, value) => {
    setForm({
      ...form,
      [field]: value,
    });
    if (!!errors[field]) {
      setErrors({
        ...errors,
        [field]: null,
      });
    }
  };

  const validateForm = async () => {
    const NewErrors = {};
    setRegisterStatus(0);

    if (!form.enrollment_service_code && !INPUTS.enrollment_service_code)
      NewErrors.enrollment_service_code = "Serviço inválido!";

    if (!props.update) {
      if (multiStudents.length === 0)
        NewErrors.enrollment_student_code = "Selecione pelo menos um estudante!";
    } else if (!form.enrollment_student_code && !INPUTS.enrollment_student_code) {
      NewErrors.enrollment_student_code = "Selecione um estudante!";
    }

    if (props.confirmation && !form.enrollment_class && !INPUTS.enrollment_class)
      NewErrors.enrollment_class = "Turma inválida!";

    return NewErrors;
  };

  const FormSubmit = async (e) => {
    e.preventDefault();
    const formErrors = await validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os campos!");
      setRegisterStatus(1);
      return;
    }

    if (!props.update) {
      const payload = {
        enrollment_class: CRValue("#enrollment_class"),
        enrollment_service: CRValue("#enrollment_service_code"),
        enrollment_students:
          multiStudents.length > 0
            ? multiStudents.map((item) => item.value)
            : [INPUTS.enrollment_student_code],
      };

      const link = props.confirmation ? 0 : 1;

      try {
        await axios.post(FORMURL[link], payload);
        toast.success(
          props.confirmation
            ? "Confirmações efetuadas com sucesso!"
            : "Matrículas efetuadas com sucesso!"
        );
        RefreshList(); 
        setMultiStudents([]);
        setRegisterStatus(2);
        handleClose();
      } catch (error) {
        const msg = error.response?.data?.msg || "Erro ao efetuar ação!";
        toast.error(msg);
        setRegisterStatus(1);
      }
    } else {
      const SUBMIT_INPUTS = {
        enrollment_class: CRValue("#enrollment_class"),
        enrollment_service: CRValue("#enrollment_service_code"),
        enrollment_student: props.studentCode,
      };
      try {
        await axios.put(FORMURL[2], SUBMIT_INPUTS);
        toast.success(
          props.confirmation
            ? "Confirmação de matrícula atualizada!"
            : "Matrícula atualizada!"
        );
        setRegisterStatus(2);
        RefreshList(".el-refresh-list");
        handleClose();
      } catch (error) {
        const msg = error.response?.data?.msg || "Erro ao atualizar!";
        toast.error(msg);
        setRegisterStatus(1);
      }
    }
  };

  return (
    <div>
      <div onClick={handleShow}>
        {props.toggle_btn ? (
          props.toggle_btn
        ) : (
          <button className="btn btn-main bg-main">
            <AddCircleOutlineIcon />
            {props.confirmation ? " Confirmar Matrícula" : " Efetuar Matrícula"}
          </button>
        )}
      </div>

      <Modal
        className={showBox ? ModalAnimationShow() : ModalAnimationClose()}
        centered
        size="lg"
        dialogAs={DraggableModal}
        show={show}
        onHide={handleClose}
      >
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>
                {props.update ? "Atualizar " : "Efetuar "}
                {props.confirmation
                  ? "Confirmação de Matrícula"
                  : "Matrícula"}
              </h5>
            </div>
          </Modal.Title>
        </Modal.Header>

        <Form onSubmit={FormSubmit}>
          <Modal.Body className="scrollLimit">
            {/* SELEÇÃO DE ESTUDANTES */}
            {!props.update && (
              <Form.Group className="mb-3">
                <Form.Label>
                  Selecionar Estudantes
                  <span className="text-danger ml-2">*</span>
                </Form.Label>
                <MultiSelect
                  options={studentsOptions}
                  value={multiStudents}
                  onChange={setMultiStudents}
                  labelledBy="Selecionar"
                  hasSelectAll
                  disableSearch={loading}
                />
                {loading && <small>Carregando estudantes...</small>}
                <Form.Control.Feedback type="invalid">
                  {errors.enrollment_student_code}
                </Form.Control.Feedback>
              </Form.Group>
            )}

            {/* TURMA */}
            {props.confirmation && (
              <>
                <Form.Group className="mb-3">
                  <Form.Label>
                    Turma<span className="text-danger ml-2">*</span>
                  </Form.Label>
                  <Form.Select
                    onChange={(e) => setClass(e.target.value)}
                    id="enrollment_class"
                  >
                    <ClassDataOptions code={Class} />
                  </Form.Select>
                </Form.Group>

                {Class && (
                  <div className="mb-3 ed-wrap">
                    <div className="badge bg-main mr-2 mt-1">
                      Ano lectivo : <GetAcademicYear_byclass ID={Class} />
                    </div>
                    <div className="badge bg-main mr-2 mt-1">
                      {ReplaceWord("Classe")} :
                      <GetAcademiclevel_byclass ID={Class} />
                    </div>
                    <div className="badge bg-main mt-1 mr-2">
                      Sala : <GetClassroom_byclass ID={Class} />
                    </div>
                    <div className="badge bg-main mt-1 mr-2">
                      Curso : <GetCourse_byclass ID={Class} />
                    </div>
                    <div className="badge bg-main mt-1">
                      Periodo : <GetPeriod_byclass ID={Class} />
                    </div>
                  </div>
                )}
              </>
            )}

            {/* SERVIÇO */}
            <Form.Group className="mb-3">
              <Form.Label>
                Selecionar Serviço
                <span className="text-danger ml-2">*</span>
              </Form.Label>
              <Form.Select
                onChange={(e) => setServiceCode(e.target.value)}
                id="enrollment_service_code"
              >
                <ServiceDataOptions />
              </Form.Select>

              {serviceCode && (
                <div className="mt-2">
                  <Badge className="bg-main">
                    <small>
                      <div className="ed-flex">
                        Valor do serviço :
                        <div className="ml-1">
                          <GetServicePrice ID={serviceCode} />
                        </div>
                      </div>
                    </small>
                  </Badge>
                </div>
              )}
            </Form.Group>
          </Modal.Body>

          <Modal.Footer>
            <Button className="bg-light text-dark" onClick={handleClose}>
              Cancelar
            </Button>
            <SaveButton
              icon={props.update ? <Update /> : <Save />}
              title={props.update ? "Atualizar" : "Salvar"}
              status={RegisterStatus}
            />
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  );
}

export default NewEnrollmentConfirmationModal;
