import React, { useEffect, useState } from 'react'
import Table from './Table';
import axios from 'axios';
import { Delete, Edit, Refresh } from '@mui/icons-material';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import NewCourseModal from '../modal/NewCourseModal';
import TableGrid from '../../../General/components/TableGrid';
import RefreshButton from '../../../General/components/RefreshButton';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
const TABLEURL = Hoot() + "eduallcoursesapi/get/";

let Categories  = [
  "",
  "Designer",
  "Arte",
  "Engenharia",
  "Saúde",
  "Ciências",
  "Tecnologia",
  "Educação",
  "Negócios",
  "Direito",
  "Arquitetura",
  "Administração",
  "Matemática",
  "Comunicação",
  "Agricultura",
  "Desporto",
  "Meio Ambiente",
  "Humanidades",
  "Turismo",
  "Transporte",
  "Outra"
];





const TAX = ["Sim", "Não"];


const columns = [
  {
    field: 'index',
    headerName: 'Nº',
    resizable: true,
    width: 90,
  },
  {
    field: 'title',
    headerName: 'Nome do Curso',
    resizable: true,
    width: 300,
  },
  {
    field: 'category',
    headerName: 'Categoria',
    resizable: true,
  },
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true, cellRenderer: (props) => {
      return <div className="ed-flex">
        <NewCourseModal title='Atualizar ' update='true' get={Hoot() + `eduallsinglecoursesapi/get/${props.data.id}`}
          url={Hoot() + `eduallcourseupdate/update/${props.data.id}`} toggle_btn={
            <button className="btn-circle  bg-success text-light">
              <Edit />
            </button>} />
        <DeleteModal title='este curso' url={Hoot() + `eduallcoursedelete/delete/${props.data.id}`} message='Curso deletado com sucesso' toggle_btn={
          <button className="btn-circle bg-danger ml-2 text-light">
            <Delete />
          </button>} />
      </div>;
    }
  }
];


function CoursesList() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);
  const [data1, setData1] = useState([]);

  async function loadData() {
    try {
      setLoadStatus(0);
      setLoaded(false);
      const response = await axios.get(TABLEURL);
      const rows = [];
      const rows1 = [];
      response.data.map((item, index) => {
        rows.push({
          index: index + 1,
          id: item.ed_course_id,
          category: Categories[item.ed_course_category * 1],
          title: item.ed_course_title,
          action: '',
        })

        rows1.push({
          index: index + 1,
          category: Categories[item.ed_course_category * 1],
          title: item.ed_course_title,
        })
      });
      setData(rows);
      setData1(rows1);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoadStatus(1);
    }
  }

  useEffect(() => {
    loadData();
  }, []);




  if (load) {
    return (
      <div id='ed-custom-table-data' >
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista dos cursos'
          TableBtn={
            <div className='ed-flex' >
              <button id='ed-custom-table-data-btn'
                onClick={() =>
                  ExportDataToTablesToPdf({
                    fileName: "Lista dos cursos",
                    headerId: null,
                    contentId: "ed-custom-table-data",
                    footerId: null,
                    rotation: "portrait",
                    buttonId: "ed-custom-table-data-btn",
                    customHeader: "Lista dos cursos",
                    excludedColumns: ["Ação"]
                  })
                }
                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
              </button>

              
              <button className='btn-icon btn btn-export-data ml-2'
                onClick={() => ExportDataForTablesExcel("Cursos ", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
              </button>
              <RefreshButton action={loadData} status={LoadStatus} />
            </div>
          }
        />
      </div>
    )
  } else {
    return (
      <div>
        <><div className="d-none">*</div>
          <TableGrid
            TableHead={columns}
            TableBody={[]}
            NoButtons
            TableTitle='Lista dos cursos'
            TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
          />
        </>
      </div>
    )
  }
}

export default CoursesList