import React, { useEffect, useState } from 'react'
import styled from 'styled-components'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button, Badge, Alert } from 'react-bootstrap'
import { InfoOutlined, Save } from '@mui/icons-material';
import DraggableModal from '../../../../../../General/components/DraggableModal';
import axios from 'axios';
import Hoot from '../../../../../../General/components/Hoot';
import ClearInputs from '../../../../../../General/components/ClearInputs';
import CRValue from '../../../../../../General/components/CRValue';
import { RichTextEditor } from '../../../../../../General/components/RichTextEditor';
import FileUpload from '../../../../../../General/components/FileUpload';
import { toast } from 'react-hot-toast';
import { Update } from '@material-ui/icons';
import SelectSearch from 'react-select-search';
import { ClassDataOptions, GetClasstitle_byclass, GetSubject, GetTime, StudentsArray } from '../../../../../../General/components/InstituteData';
import StudentDetailsMenu from '../../../../../../Dashboard/components/elements/StudentDetailsMenu';
import { MultiSelect } from 'react-multi-select-component';
import Radio from '@mui/material/Radio';
import RadioGroup from '@mui/material/RadioGroup';
import FormControlLabel from '@mui/material/FormControlLabel';
import FormControl from '@mui/material/FormControl';
import FormLabel from '@mui/material/FormLabel';
import SmallLoader from '../../../../../../General/components/SmallLoader';
import RefreshList from '../../../../../../General/components/RefreshList';
import UserOptionDropDown from '../../../../../../Dashboard/components/elements/UserOptionDropDown';
import SaveButton from '../../../../../../Dashboard/components/elements/SaveButton';
import { BsEmojiSmile, BsStarFill, BsStarHalf, BsStar } from "react-icons/bs";
import { ModalAnimationClose, ModalAnimationShow } from '../../../../../../General/components/ModalAnimations';
import ReplaceWord from '../../../../../../General/components/ReplaceWord';

function StudentBehaviorModal(props) {
  const [show, setShow] = useState(false);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});
  const [studentCode, setStudentCode] = useState([]);
  const [StudentsData, setStudentsData] = useState([]);
  const [StudentList, setStudentList] = useState([]);
  const [NotSelectedStatus, setNotSelectedStatus] = useState(null);
  const [LoadingStudents, setLoadingStudents] = useState(false);
  const [CurrentStatus, setCurrentStatus] = useState(null);
  const [DT, SetDT] = useState([]);
  const [TM, SetTM] = useState([]);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [Founded, SetFounded] = useState(null);
  const [RateValue, setRateValue] = useState(0)
  const [BehaviorType, setBehaviorType] = useState(0);
  const [BehaviorEmployeeCode, setBehaviorEmployeeCode] = useState(0);


  const [showBox, SetshowBox] = useState(false);
  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200);
  }

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };


  const INPUTS = {
    student_behavior_classSubject: CRValue("#student_behavior_classSubject").split("|")[2],
    student_behavior_subject: CRValue("#student_behavior_classSubject").split("|")[1],
    student_behavior_class: CRValue("#student_behavior_classSubject").split("|")[0],
    student_behavior_type: BehaviorType,
    student_behavior_status: CRValue("#student_behavior_status"),
    student_behavior_description: CRValue("#student_behavior_description"),
    student_behavior_studentCode: studentCode,
    student_behavior_status_notselected: NotSelectedStatus,
  };

  const FORMURL = [
    Hoot() + "eduallstudentbehaviorregister/post/",
    props.get ? props.get : '',
    props.url ? props.url : '',
    Hoot() + "eduallgetstudentsbyclass/"
  ];



  const GET_DATA = async () => {
    if (props.update) {
      try {
        console.log(FORMURL[1]);
        const response = await axios.get(FORMURL[1]);
        console.log(response.data);
        if (response.data.length > 0) {
          setCurrentStatus(response.data[0].ed_student_attd_status);
          setField("student_behavior_type", response.data[0].ed_student_attd_timing);
          setField("student_behavior_status", response.data[0].ed_student_attd_status);
          setField("student_behavior_description", response.data[0].ed_student_attd_date);
        } else {
          toast.error("Lamentamos mas não foi possivel encontrar a informação selecionada !");
        }
      } catch (error) {
        toast.error("Lamentamos mas não foi possivel encontrar a informação selecionada !");
      }
    }
  }


  const GetStudentsByClass = async (e) => {
    setStudentsData([]);
    setStudentCode([]);
    setStudentList([]);
    setLoadingStudents(true);
    try {
      const response = await axios.get(FORMURL[3] + e);
      const students = [];
      const ListOfStudents = [];
      if (response.data !== null) {
        response.data.map((item, index) => {
          students.push({ label: item.ed_student_name, value: item.ed_student_id });
          ListOfStudents.push(item.ed_student_id);
        })
      }
      setTimeout(() => {
        setStudentsData(students);
        setStudentList(ListOfStudents);
        setLoadingStudents(false);
      }, 500);
      console.log("************************")
      console.log(students);
      console.log("*************************");
    } catch (error) {
      setLoadingStudents(false);
      toast.error("Lamentamos mas não foi possivel encontrar a informação selecionada !");
    }
  }


  const setField = (field, value) => {
    setForm({
      ...form,
      [field]: value
    })

    if (!!errors[field]) {
      setErrors({
        ...errors,
        [field]: null
      });
    }
  }


  const validateForm = () => {
    const { student_behavior_classSubject, student_behavior_status, student_behavior_status_notselected,
      student_behavior_type, student_behavior_description } = form;
    const NewErrors = {};

    if (INPUTS.student_behavior_type === "" || INPUTS.student_behavior_type === " ") {
      if (!student_behavior_type || student_behavior_type === '') NewErrors.student_behavior_type = 'Selecione uma das opções de comportamento !';
    } else { if (!student_behavior_type) { setField("student_behavior_type", INPUTS.student_behavior_type); } }

    if (INPUTS.student_behavior_description === "" || INPUTS.student_behavior_description === " ") {
      if (!student_behavior_description || student_behavior_description === '') NewErrors.student_behavior_description = 'Selecione uma data valida';
    } else { if (!student_behavior_description) { setField("student_behavior_description", INPUTS.student_behavior_description); } }

    if (!props.update) {
      if (((studentCode.length !== StudentsData.length) && studentCode.length > 0 && StudentsData.length > 0)) {
        if (INPUTS.student_behavior_status_notselected === "" || INPUTS.student_behavior_status_notselected === " ") {
          if (!student_behavior_status_notselected || student_behavior_status_notselected === '') NewErrors.student_behavior_status_notselected = 'Selecione o estado de presença dos alunos';
        } else { if (!student_behavior_status_notselected) { setField("student_behavior_status_notselected", INPUTS.student_behavior_status_notselected); } }
      }

      if (INPUTS.student_behavior_classSubject === "" || INPUTS.student_behavior_classSubject === " ") {
        if (!student_behavior_classSubject || student_behavior_classSubject === '') NewErrors.student_behavior_classSubject = 'Selecione a turma';
      } else { if (!student_behavior_classSubject) { setField("student_behavior_classSubject", INPUTS.student_behavior_classSubject); } }
      if (studentCode.length <= 0) NewErrors.student_behavior_code = 'Selecione os estudantes';
    }

    return NewErrors;
  }


  const FormSubmit = (e) => {
    e.preventDefault();
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os  campos !");
      console.clear();
      console.log(formErrors);
      setRegisterStatus(1);
    } else {
      const SUBMIT_INPUTS = {
        student_behavior_type: INPUTS.student_behavior_type,
        student_behavior_subClass: INPUTS.student_behavior_classSubject,
        student_behavior_code: studentCode,
        student_behavior_stars: RateValue,
        student_behavior_employee: BehaviorEmployeeCode,
        student_behavior_description: INPUTS.student_behavior_description
      };

      if (!props.update) {
        /*** Para todos os que não foram selecionados **/
        const Studentscode = [];
        for (let i = 0; i < INPUTS.student_behavior_studentCode.length; i++) {
          Studentscode.push(INPUTS.student_behavior_studentCode[i].value * 1);
        }


        console.clear();
        console.log(SUBMIT_INPUTS);
        console.log(props.data);

        Studentscode.map((student, index) => {
          SUBMIT_INPUTS.student_behavior_code = student;
          try {
            axios.post(FORMURL[0], SUBMIT_INPUTS).then((e) => {
              if (index === (Studentscode.length - 1)) {
                setRegisterStatus(2);
                toast.success("Avaliação de comportamento registrado com sucesso !");
                setRegisterStatus(2);
                setForm({});
                setBehaviorEmployeeCode(0);
                setBehaviorType(0);
                RefreshList(`.el-refresh-list`);
              }
              console.log(e.data);
            }).catch((error) => {
              console.clear();
              console.log(error.response.data);
              setRegisterStatus(1);
              toast.error("Erro ao marcar presença ao estudante Nº :" + student);
            });
          } catch (error) {
            console.clear();
            console.log(error.response.data);
          }
        });
      } else {
        try {
          axios.put(FORMURL[2], SUBMIT_INPUTS).then(() => {
            toast.success("Presença atualizada com sucesso !");
            setStudentsData([]);
            setStudentCode([]);
            setStudentList([]);
            setForm({});
            RefreshList(`.el-refresh-list`);
          }).catch((error) => {
            console.clear();
            console.log(error.response.data);
            toast.error("Lamentamos mas não foi  possivel executar esta ação !");
          });
        } catch (error) {
          console.clear();
          console.log(error.response.data);
          toast.error("Lamentamos mas não foi  possivel executar esta ação !");
        }
      }
    }
  };



  const GetStudentCode = (e) => {
    setStudentCode(e);
    var row = "";
    for (let i = 0; i < e.length; i++) {
      row += "," + e[i].value;
    }
  }

  const handleInput = (e) => {
    if (e.target.className.split(" ")[0].toLowerCase() === "PrivateSwitchBase-input".toLowerCase()) {
      setField("student_behavior_type", e.target.value);
      setBehaviorType(e.target.value);
    }

    switch (e.target.id) {
      case "student_behavior_classSubject":
        GetClassAndSubject(e);
        break;
      case "student_behavior_status":
        setField("student_behavior_status", e.target.value);
        INPUTS.student_behavior_status = e.target.value
        break;
      case "student_behavior_description":
        setField("student_behavior_description", e.target.value);
        INPUTS.student_behavior_description = e.target.value
        break;
      default:
    }
  }


  const GetClassAndSubject = (e) => {
    setField("student_behavior_class", e.target.value.split("|")[0]);
    INPUTS.student_behavior_class = e.target.value.split("|")[0];

    setField("student_behavior_subject", e.target.value.split("|")[1]);
    INPUTS.student_behavior_subject = e.target.value.split("|")[1];

    setField("student_behavior_classSubject", e.target.value);
    INPUTS.student_behavior_classSubject = e.target.value;

    setBehaviorEmployeeCode(props.data[0].ed_tch_subject_teacher_code);
    GetStudentsByClass(e.target.value.split("|")[0] * 1);

    INPUTS.student_behavior_tch_subClass = e.target.value.split("|")[2];
    setField("student_behavior_tch_subClass", e.target.value.split("|")[2]);
  }


  useEffect(() => {
    SetDT(typeof props.data === 'object' ? props.data : []);
    SetTM(typeof props.timings === 'object' ? props.timings : []);
    setTimeout(() => {
      GetStudentsByClass(CRValue("#student_behavior_classSub").split("|")[0] * 1);
    }, 500);
  }, []);



  return (
    <div>
      <div onClick={handleShow}>
        {props.toggle_btn ? props.toggle_btn : <button className="btn bg-warning"><div className="d-flex text-dark"><AddCircleOutlineIcon /> Avaliar comportamento</div></button>}
      </div>
      <Modal size="md" className={showBox ? ModalAnimationShow() : ModalAnimationClose()} centered dialogAs={DraggableModal} show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>{props.title ? props.title : 'Avaliar'} comportamento</h5>
            </div>
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={FormSubmit}>
          <Modal.Body className='scrollLimit'>
            {props.update ? <></> :
              <div>
                <Alert variant="warning" className="mt-3">
                  <strong>Atenção:</strong>{" "}
                  <small>
                    Após enviar a validação ou o comentário final, <u>não será possível editar ou desfazer esta ação</u>.
                    Verifique se todas as informações estão corretas antes de confirmar o envio.
                  </small>
                </Alert>

                <Form.Group className="mb-3 mt-2">
                  <Form.Label>Turma - {ReplaceWord("Disciplina", true)} <span className='text-danger ml-2'>*</span></Form.Label>
                  <div className="ed-flex">
                    <Form.Select text="number" onChange={handleInput} className={!!errors.student_behavior_classSubject && 'is-invalid'} value={form.student_behavior_classSubject}
                      isInvalid={!!errors.student_behavior_classSubject} id="student_behavior_classSubject">
                      {props.data.map((item, index) => {
                        return (<option value={item.ed_tch_subject_class + "|" + item.ed_tch_subject_code + "|" + item.ed_tch_subject_id}>
                          <GetClasstitle_byclass ID={item.ed_tch_subject_class} />
                          (<GetSubject ID={item.ed_tch_subject_code} /> )
                        </option>)
                      })}
                    </Form.Select>
                    {LoadingStudents ? <div className='ed-flex'><div className="pd-2"></div>
                      <SmallLoader />
                    </div> : <></>}
                  </div>
                  <Form.Control.Feedback type='invalid'>{errors.student_behavior_classSubject}</Form.Control.Feedback>
                </Form.Group>
              </div>
            }
            {
              props.update ? <></> :
                <>
                  {StudentsData.length >= 1 ?
                    <>
                      <Form.Group className="mb-3">
                        <div>
                          <Form.Label>Nome do estudante <span className='text-danger ml-2'>*</span></Form.Label>
                        </div>
                        <MultiSelect
                          options={StudentsData}
                          value={studentCode}
                          className={errors.feepayment_months ? 'border-red' : ''}
                          onChange={GetStudentCode}
                          labelledBy='select'
                        />
                        <small className="text-danger">{errors.student_behavior_code}</small>
                      </Form.Group>
                    </> :
                    <></>
                  }
                </>
            }
            <div className="mb-3">
              <Rating>
                <div className="ed-flex">
                  <div className="ed-flex stars">
                    <span className="mr-2">{RateValue}</span>
                    <div className={RateValue >= 1 ? "selected" : ""} onClick={() => setRateValue(1)} ><BsStarFill /></div>
                    <div className={RateValue >= 2 ? "selected" : ""} onClick={() => setRateValue(2)} ><BsStarFill /></div>
                    <div className={RateValue >= 3 ? "selected" : ""} onClick={() => setRateValue(3)} ><BsStarFill /></div>
                    <div className={RateValue >= 4 ? "selected" : ""} onClick={() => setRateValue(4)} ><BsStarFill /></div>
                    <div className={RateValue >= 5 ? "selected" : ""} onClick={() => setRateValue(5)} ><BsStarFill /></div>
                  </div>
                  <small className="ml-2">avaliação do estudante</small>
                </div>
              </Rating>
            </div>
            {((studentCode.length !== StudentsData.length) && studentCode.length > 0 && StudentsData.length > 0) ?
              <>
                <FormControl id="student_behavior_status_notselected">
                  <div className="ed-block mb-3">
                    <FormLabel className='text-main' id="student_behavior_status_notselected">Marcar os alunos selecionados como :</FormLabel>
                    <RadioGroup aria-labelledby="student_behavior_status_notselected1" defaultValue="0"
                      name="radio-buttons-group" id="student_behavior_status_notselected1" onChange={handleInput}  >
                      <div className="mt-2 ed-wrap">
                        <div className="mt-2"><FormControlLabel value="0" control={<Radio />} label="Bem educado" /></div>
                        <div className="mt-2"><FormControlLabel value="1" control={<Radio />} label="Distraido nas aulas" /></div>
                        <div className="mt-2"><FormControlLabel value="2" control={<Radio />} label="Participação activa" /></div>
                        <div className="mt-2"><FormControlLabel value="3" control={<Radio />} label="Rebelde e confusionista" /></div>
                        <div className="mt-2"><FormControlLabel value="4" control={<Radio />} label="Atrasado nas aulas" /></div>
                      </div>
                    </RadioGroup>
                    <Form.Control.Feedback type='invalid'>{errors.student_behavior_status_notselected}</Form.Control.Feedback>
                  </div>
                </FormControl>
              </>
              : <></>}
            <div>
              <Form.Group className="mb-3">
                <Form.Label>Descrição do Comportamento <span className='text-danger ml-2'>*</span></Form.Label>
                <Form.Control type='text' required as="textarea" onChange={handleInput} rows={6} className={!!errors.student_behavior_description && 'is-invalid'} value={form.student_behavior_description}
                  isInvalid={!!errors.student_behavior_description} placeholder='Fale algo interessante ...' id="student_behavior_description" />
                <Form.Control.Feedback type='invalid'>{errors.student_behavior_description}</Form.Control.Feedback>
              </Form.Group>
            </div>
          </Modal.Body>
          <Modal.Footer>
            <div className="ed-space">
              <div className="ed-flex">

              </div>
              <div className="ed-flex">
                <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                {props.update ? (Founded === false ? <div></div> :
                  <SaveButton icon={props.title ? <Update /> : <BsEmojiSmile />} title={props.title ? props.title : ' Avaliar'} status={RegisterStatus} />) :
                  <SaveButton icon={props.title ? <Update /> : <BsEmojiSmile />} title={props.title ? props.title : ' Avaliar'} status={RegisterStatus} />}
              </div>
            </div>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  )
}


const Rating = styled.div`
    .stars{
       div{
          cursor:pointer;
          margin-right:10px;
          cursor:pointer;
          color:var(--ed-grey-text);
        }

        div.selected{
             color:var(--ed-gold) !important;
        }
    }
`;

export default StudentBehaviorModal