import React, { useEffect, useState } from 'react' 
import axios from 'axios';
import { Delete,  Edit, Refresh} from '@mui/icons-material'; 
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import NewCourseModal from '../modal/NewCourseModal';
import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
const TABLEURL = Hoot()+"eduallcoursesapi/get/";

  

const columns = [  
    { 
      field: 'title',
      headerName: 'Evento',  
      resizable: true,
     },
     { 
        field: 'start_date',
        headerName: 'Data Início',  
        resizable: true,
     }, 
     { 
        field: 'start_date',
        headerName: 'Data de Finalização',  
        resizable: true,
     }, 
     { 
        field: 'status',
        headerName: 'Situação',  
        resizable: true,
     }, 
];
  
function DashboardEventsTable() {
    const [data, setData] = useState([]);
    const [load, setLoaded] = useState(false);
    const [LoadStatus, setLoadStatus] = useState(null);

    async function loadData(){
        try {
          setLoadStatus(0); 
          const response = await axios.get(TABLEURL); 
          const rows = []; 
          setData(rows);
          setLoaded(true); 
          setLoadStatus(2); 
        } catch (error) {
          setLoadStatus(1); 
        }
    }
  
    useEffect(()=>{
        loadData(); 
    },[]);
  
 
  
  
  if(load){
      return (
      <div>
        <TableGrid
            TableHead={columns}
            TableBody={data} 
            TableHeight={350}
            TableTitle='Eventos Recentes'
            TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
    </div>
    )
  }
}

export default DashboardEventsTable
