/* ----------------------------------------------------------------------------
   SOCKET SIMULADO
---------------------------------------------------------------------------- */
const listeners = new Map();
const socket = {
  on(event, cb) {
    if (!listeners.has(event)) listeners.set(event, new Set());
    listeners.get(event).add(cb);
    return () => listeners.get(event)?.delete(cb);
  },
  emit(event, payload) {
    listeners.get(event)?.forEach((cb) => cb(payload));
  },
};




