function randInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }
function randomUser() { return USERS[Math.floor(Math.random() * USERS.length)]; }

function seedPosts(count = 16) {
  const out = [];
  for (let i = 0; i < count; i++) {
    const u = randomUser();
    const hasVideo = Math.random() < 0.35;
    const imgCount = randInt(1, 5); // 👉 mais imagens
    const imgs = Array.from({ length: hasVideo ? 0 : imgCount }, () => IMG[Math.floor(Math.random() * IMG.length)]);
    out.push({
      id: uuid(),
      author: u,
      createdAt: Date.now() - Math.floor(Math.random() * 86400000 * 7),
      text:
        i % 3 === 0
          ? "Explorando novas ideias 🤩 #design #team"
          : i % 3 === 1
          ? "Resultados da sprint – parabéns a toda a equipa!"
          : "Partilho fotos do nosso encontro 🌿",
      images: imgs,
      video: hasVideo ? VIDS[Math.floor(Math.random() * VIDS.length)] : null,
      likes: Math.floor(Math.random() * 200),
      comments: Math.floor(Math.random() * 40),
    });
  }
  return out;
}

