/* ----------------------------------------------------------------------------
   UTILS: visibilidade + registry (1 vídeo a tocar de cada vez)
---------------------------------------------------------------------------- */
function useVisibility(ref, rootMargin = "-20% 0px -30% 0px", threshold = 0.6) {
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const io = new IntersectionObserver(
      (entries) => entries.forEach((e) => setVisible(e.isIntersecting)),
      { root: null, rootMargin, threshold }
    );
    io.observe(el);
    return () => io.disconnect();
  }, [ref, rootMargin, threshold]);
  return visible;
}
const playingRegistry = new Set();

/* ----------------------------------------------------------------------------
   VIDEO PLAYER (Netflix-style, com som por padrão + fallback)
---------------------------------------------------------------------------- */
function formatTime(s = 0) {
  if (!Number.isFinite(s)) return "0:00";
  const m = Math.floor(s / 60);
  const ss = Math.floor(s % 60).toString().padStart(2, "0");
  return `${m}:${ss}`;
}

function VideoNetflix({ src, poster }) {
  const wrapRef = useRef(null);
  const videoRef = useRef(null);
  const visible = useVisibility(wrapRef, "-20% 0px -30% 0px", 0.6);

  const [playing, setPlaying] = useState(false);
  const [muted, setMuted] = useState(false);            // queremos som por padrão
  const [vol, setVol] = useState(1);
  const [time, setTime] = useState(0);
  const [dur, setDur] = useState(0);
  const [fs, setFs]   = useState(false);
  const [hint, setHint] = useState(null);               // mensagem de fallback autoplay

  // listeners
  useEffect(() => {
    const v = videoRef.current; if (!v) return;
    const onPlay = () => setPlaying(true);
    const onPause = () => setPlaying(false);
    const onTime = () => setTime(v.currentTime || 0);
    const onLoaded = () => setDur(v.duration || 0);
    v.addEventListener("play", onPlay);
    v.addEventListener("pause", onPause);
    v.addEventListener("timeupdate", onTime);
    v.addEventListener("loadedmetadata", onLoaded);
    return () => {
      v.removeEventListener("play", onPlay);
      v.removeEventListener("pause", onPause);
      v.removeEventListener("timeupdate", onTime);
      v.removeEventListener("loadedmetadata", onLoaded);
    };
  }, []);

  // visibilidade => auto play/pause + só um de cada vez
  useEffect(() => {
    const v = videoRef.current; if (!v) return;

    const tryPlayWithSound = async () => {
      v.muted = false; setMuted(false);
      v.volume = vol;
      try {
        // pausa os outros
        playingRegistry.forEach((p) => { if (p !== v) { try{p.pause();}catch{} }});
        await v.play();                 // tenta tocar com som
        playingRegistry.add(v);
        setHint(null);
      } catch (err) {
        // fallback: tocar muted (autoplay policy)
        v.muted = true; setMuted(true);
        try {
          await v.play();
          playingRegistry.add(v);
          setHint("O teu browser bloqueou autoplay com som. Clica em 🔊 para ativar o áudio.");
        } catch {
          setHint("Clica no vídeo para iniciar a reprodução.");
        }
      }
    };

    if (visible) {
      tryPlayWithSound();
    } else {
      try { v.pause(); } catch {}
      playingRegistry.delete(v);
    }

    return () => {
      try { v.pause(); } catch {}
      playingRegistry.delete(v);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [visible]);

  // Controles
  const toggle = () => {
    const v = videoRef.current; if (!v) return;
    v.paused ? v.play() : v.pause();
  };
  const toggleMute = () => {
    const v = videoRef.current; if (!v) return;
    v.muted = !v.muted; setMuted(v.muted);
    if (!v.muted && v.volume === 0) { v.volume = 0.2; setVol(0.2); }
  };
  const onVol = (val) => {
    const v = videoRef.current; if (!v) return;
    v.volume = val; setVol(val);
    if (val === 0) { v.muted = true; setMuted(true); }
    else { v.muted = false; setMuted(false); }
  };
  const onSeek = (pct) => {
    const v = videoRef.current; if (!v || !Number.isFinite(dur)) return;
    v.currentTime = pct * dur;
  };
  const toggleFs = async () => {
    const el = wrapRef.current; if (!el) return;
    if (!document.fullscreenElement) { await el.requestFullscreen?.(); setFs(true); }
    else { await document.exitFullscreen?.(); setFs(false); }
  };

  // progress %
  const pct = dur ? Math.max(0, Math.min(1, time / dur)) : 0;

  return (
    <div ref={wrapRef} className="post-media" style={{ position: "relative", background: "#000", borderRadius: 12, overflow: "hidden" }}>
      <video
        ref={videoRef}
        src={src}
        poster={poster}
        playsInline
        preload="metadata"
        style={{ width: "100%", display: "block", aspectRatio: "16/9", background: "#000" }}
        onClick={toggle}
      />
      {/* Overlay Controles */}
      <div
        style={{
          position: "absolute", left: 0, right: 0, bottom: 0,
          background: "linear-gradient(180deg, rgba(0,0,0,0) 0%, rgba(0,0,0,.6) 60%, rgba(0,0,0,.85) 100%)",
          color: "#fff", padding: 12
        }}
      >
        {/* Barra de progresso */}
        <div
          onClick={(e) => {
            const rect = e.currentTarget.getBoundingClientRect();
            const ratio = (e.clientX - rect.left) / rect.width;
            onSeek(Math.max(0, Math.min(1, ratio)));
          }}
          style={{ height: 6, borderRadius: 999, background: "rgba(255,255,255,.25)", cursor: "pointer", position: "relative" }}
        >
          <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: `${pct * 100}%`, background: "#fff", borderRadius: 999 }} />
        </div>

        {/* Linha controles */}
        <div style={{ display:"flex", alignItems:"center", gap:10, marginTop:8 }}>
          <button onClick={toggle} style={cBtn}>
            {playing ? <TbPlayerPause size={20}/> : <TbPlayerPlay size={20}/>}
          </button>

          <button onClick={toggleMute} style={cBtn} title={muted ? "Ativar som" : "Silenciar"}>
            {muted || vol === 0 ? <TbVolumeOff size={20}/> : vol < 0.6 ? <TbVolume size={20}/> : <TbVolume3 size={20}/>}
          </button>

          <input
            type="range" min={0} max={1} step={0.01}
            value={muted ? 0 : vol}
            onChange={(e)=>onVol(parseFloat(e.target.value))}
            aria-label="Volume" style={rangeLine}
          />

          <div style={{ marginLeft: 6, fontVariantNumeric:"tabular-nums", opacity:.9, fontSize:13 }}>
            {formatTime(time)} / {formatTime(dur)}
          </div>

          <div style={{ marginLeft:"auto" }}>
            <button onClick={toggleFs} style={cBtn} title={fs ? "Sair de fullscreen" : "Fullscreen"}>
              {fs ? <TbArrowsMinimize size={20}/> : <TbArrowsMaximize size={20}/>}
            </button>
          </div>
        </div>

        {/* Hint de autoplay policy */}
        {hint && (
          <div style={{ marginTop: 8, fontSize: 12, opacity: .9 }}>
            {hint}
          </div>
        )}
      </div>
    </div>
  );
}
const cBtn = { background: "rgba(255,255,255,.12)", color: "#fff", border: "none", borderRadius: 8, padding: "6px 10px", cursor: "pointer" };
const rangeLine = { appearance: "none", width: 110, height: 4, borderRadius: 4, background: "linear-gradient(90deg, #fff 0%, #fff 60%, rgba(255,255,255,.3) 60%)", outline: "none", cursor: "pointer" };

