function Composer({ onCreated }) {
  const [text, setText] = useState("");
  const [files, setFiles] = useState([]); // {id, kind, preview, file}
  const [posting, setPosting] = useState(false);

  const onDrop = useCallback((accepted) => {
    accepted.forEach((file) => {
      const isVideo = file.type.startsWith("video/");
      const isImage = file.type.startsWith("image/");
      const reader = new FileReader();
      reader.onload = () => {
        setFiles((prev) => [
          ...prev,
          { id: uuid(), kind: isVideo ? "video" : isImage ? "image" : "file", preview: reader.result, file },
        ]);
      };
      reader.readAsDataURL(file);
    });
  }, []);

  const { getRootProps, getInputProps, open } = useDropzone({
    onDrop, noClick: true, maxFiles: 10,
    accept: {
      "image/*": [], "video/*": [],
      "application/pdf": [".pdf"], "application/msword": [".doc", ".docx"],
      "application/vnd.ms-excel": [".xls", ".xlsx"],
    },
  });

  const hasVideo = files.some((f) => f.kind === "video");

  const handlePost = async () => {
    if (!text.trim() && files.length === 0) return;
    setPosting(true);
    const images = files.filter((f) => f.kind === "image").map((f) => f.preview);
    const video = files.find((f) => f.kind === "video")?.preview || null;
    await api.post("/posts", { text, images, video });
    setText(""); setFiles([]); setPosting(false); onCreated?.();
  };

  return (
    <Card className="mb-4" {...getRootProps()}>
      <input {...getInputProps()} />
      <Row style={{ alignItems: "flex-start" }}>
        <Avatar src={USERS[0].avatar} sx={{ width: 44, height: 44 }} />
        <div style={{ flex: 1 }}>
          <ReactQuill theme="snow" value={text} onChange={setText} placeholder="Escreva algo para a equipa…" />
          <div style={{ display: "flex", gap: 8, marginTop: 10, flexWrap: "wrap" }}>
            <IconButton onClick={() => open()}><TbPhotoPlus />&nbsp;Imagem</IconButton>
            <IconButton onClick={() => open()} disabled={hasVideo}><TbVideoPlus />&nbsp;Vídeo</IconButton>
            <IconButton onClick={() => open()}><TbFilePlus />&nbsp;Ficheiro</IconButton> 
            <IconButton><TbCalendarTime />&nbsp;Agendar</IconButton>
            <div style={{ marginLeft: "auto" }}><Btn className="bg-main" disabled={posting} onClick={handlePost}><TbSend style={{ verticalAlign:"-2px" }}/> Publicar</Btn></div>
          </div>

          {!!files.length && (
            <div style={{ marginTop: 12, display: "grid", gap: 10 }}>
              {files.map((f) => (
                <Card key={f.id} p="8px 10px">
                  <Row style={{ justifyContent: "space-between" }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 8 }}>
                      <Pill>{f.kind === "image" ? "Imagem" : f.kind === "video" ? "Vídeo" : "Ficheiro"}</Pill>
                      <small className="grey-text">{f.file?.name || "Anexo"}</small>
                    </div>
                    <button className="text-main" onClick={() => setFiles((prev) => prev.filter((x) => x.id !== f.id))} style={{ background: "transparent", border: "none", cursor: "pointer" }}>
                      <TbX size={18} />
                    </button>
                  </Row>
                  {f.kind === "image" && <img src={f.preview} alt="" style={{ width: "100%", maxHeight: 260, objectFit: "cover", borderRadius: 12 }} />}
                  {f.kind === "video" && <video src={f.preview} controls style={{ width: "100%", borderRadius: 12, maxHeight: 360 }} />}
                </Card>
              ))}
            </div>
          )}
        </div>
      </Row>
    </Card>
  );
}

/* ----------------------------------------------------------------------------
   TEXTO truncado "# ver mais"
---------------------------------------------------------------------------- */
function TruncatedHtml({ html = "", limit = 220 }) {
  const [expanded, setExpanded] = useState(false);
  const plain = html.replace(/<[^>]+>/g, "");
  const isLong = plain.length > limit;
  const shown = expanded ? html : `${plain.slice(0, limit)}${isLong ? "…" : ""}`;
  return (
    <div>
      <div style={{ marginTop: 8, lineHeight: 1.6 }} dangerouslySetInnerHTML={{ __html: shown.replace(/\n/g, "<br/>") }} />
      {isLong && (
        <a href="#ver" className="text-main underline see-more" onClick={(e) => { e.preventDefault(); setExpanded((s) => !s); }}>
          {expanded ? "# ver menos" : "# ver mais"}
        </a>
      )}
    </div>
  );
}

