/* ----------------------------------------------------------------------------
   FEED (Virtuoso) — Birthdays + Composer + Posts (com padding 20px)
---------------------------------------------------------------------------- */
const ListContainer = styled.div`
  padding-left: 20px; padding-right: 20px; overflow: hidden;
`;
function Feed() {
  const [items, setItems] = useState([]);
  const [nextPage, setNextPage] = useState(2);
  const [loading, setLoading] = useState(false);

  const load = async (pg) => {
    if (!pg || loading) return;
    setLoading(true);
    const { data } = await api.get(`/feed?page=${pg}`);
    setItems((prev) => [...prev, ...data.items]);
    setNextPage(data.nextPage);
    setLoading(false);
  };

  useEffect(() => {
    load(1);
    const off = socket.on("new_post", (p) => setItems((prev) => [p, ...prev]));
    return off;
  }, []);

  // 0: birthdays, 1: composer, resto: posts
  const data = [{ _type: "birthdays" }, { _type: "composer" }, ...items];

  return (
    <ListContainer>
      <Virtuoso
        style={{ height: "calc(100vh - 40px)" }}
        data={data}
        endReached={() => load(nextPage)}
        overscan={300}
        itemContent={(index, item) => {
          if (item._type === "birthdays") return <BirthdaysStrip />;
          if (item._type === "composer") return <Composer onCreated={() => {}} />;
          return <PostCard key={item.id} post={item} />;
        }}
        components={{
          Footer: () => (
            <div style={{ padding: 14, textAlign: "center" }}>
              {nextPage ? (
                <small className="grey-text">A carregar mais publicações…</small>
              ) : (
                <small className="grey-text">Chegaste ao fim ✨</small>
              )}
            </div>
          ),
        }}
      />
    </ListContainer>
  );
}

