import React, { useState } from 'react';
import { Modal, Button, Spinner } from 'react-bootstrap';
import DraggableModal from '../../../General/components/DraggableModal';
import { Close, DeleteOutline, Done } from '@material-ui/icons';
import { toast } from 'react-hot-toast';
import axios from 'axios';
import RefreshList from '../../../General/components/RefreshList';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';

function DeleteModal({ toggle_btn, title, url, urlsArray, message, remove_element, fullmessage }) {
  const [show, setShow] = useState(false);
  const [showBox, setShowBox] = useState(false);
  const [deleted, setDeleted] = useState(false);
  const [loading, setLoading] = useState(false); // <-- novo estado de carregamento

  const handleClose = () => {
    setShowBox(false);
    setTimeout(() => setShow(false), 1200);
  };

  const handleShow = () => {
    setShowBox(true);
    setShow(true);
    setDeleted(false);
    setLoading(false);
  };

  const DeleteElement = async (e) => {
    e.preventDefault();
    setLoading(true); // ativa o spinner e desabilita o botão

    try {
      if (Array.isArray(urlsArray) && urlsArray.length > 0) {
        for (const singleUrl of urlsArray) {
          await axios.put(singleUrl);
        }
      } else if (url) {
        await axios.put(url);
      } else {
        toast.error("Lamentamos mas não foi possível realizar esta ação!");
        setLoading(false);
        return;
      }

      setDeleted(true);
      RefreshList();
      toast.success(message || "Informação deletada com sucesso!");
      handleClose();

      if (remove_element) document.querySelector(remove_element).classList.toggle("d-none");
    } catch (error) {
      const msg = error?.response?.data?.msg || "Lamentamos mas não foi possível deletar esta informação!";
      toast.error(msg);
    } finally {
      setLoading(false); // desativa o spinner
    }
  };

  return (
    <div>
      <div onClick={handleShow}>{toggle_btn}</div>
      <Modal
        className={showBox ? ModalAnimationShow() : ModalAnimationClose()}
        centered
        dialogAs={DraggableModal}
        show={show}
        onHide={handleClose}
      >
        <div className="prt">
          <div className={deleted ? "deleteIcon deleted" : "deleteIcon"} style={{ marginTop: '-10px' }}>
            <div className="icon">
              {deleted ? <Done /> : <DeleteOutline />}
            </div>
          </div>
        </div>

        <div className="close-modal" onClick={handleClose}>
          <div className="top-icon"><Close /></div>
        </div>

        <div className="ed-flex">
          <div className="block text-center modal-delete-details pd-2 mt-4">
            {!deleted ?
              <>
                <h2>{fullmessage ? '' : 'Está prestes a deletar '} {title}</h2>
                <p>Todo e qualquer registro no sistema que contenha esta informação será modificado ou deletado permanentemente.</p>
              </>
              :
              <h2 className='text-green'>Bom trabalho! {message}</h2>
            }
          </div>
        </div>

        <Modal.Body className='scrollLimit'>
          <div className="modal-delete-body">
            {!deleted ?
              <div className="ed-center">
                <div className="ed-flex">
                  <Button className='bg-light text-dark' onClick={handleClose} disabled={loading}>
                    Cancelar
                  </Button>

                  <Button
                    className="btn bg-danger btn-outlined ml-2 d-flex align-items-center justify-content-center"
                    onClick={DeleteElement}
                    disabled={loading} // desativa enquanto processa
                  >
                    {loading ? (
                      <>
                        <Spinner animation="border" size="sm" className="mr-2" /> 
                        Processando...
                      </>
                    ) : (
                      'Apagar'
                    )}
                  </Button>
                </div>
              </div>
              :
              <div className="ed-center">
                <Button className='bg-light text-dark' onClick={handleClose}>Ok</Button>
              </div>
            }
          </div>
        </Modal.Body>
      </Modal>
    </div>
  );
}

export default DeleteModal;
