 import { Check, Close, Delete, Edit, InfoOutlined } from '@mui/icons-material';
import { Avatar } from '@mui/material';
import React, { useEffect, useState } from 'react'
import { Badge, Form } from 'react-bootstrap';
import styled from 'styled-components'
import DatePickerBox from '../../../../General/components/DatePickerBox';
import Hoot from '../../../../General/components/Hoot';
import { ClassDataOptions, GetClasstitle_byclass, GetStudentNameAndPicture, GetSubject, GetTime, SubjectDataOptions } from '../../../../General/components/InstituteData';
import TableGrid from '../../../../General/components/TableGrid';
import AttendanceModal from './SubTabs/Modal/AttendanceModal';
import CRValue from '../../../../General/components/CRValue';
import axios from 'axios';
import DeleteModal from '../../../../Dashboard/components/elements/DeleteModal';
import { Refresh } from '@material-ui/icons';
import StudentBehaviorModal from './SubTabs/Modal/StudentBehaviorModal';
import SwitchFromPages from '../../../../General/components/SwitchFromPages';
import ExportDataForTablesExcel from '../../../../General/components/ExportDataForTablesExcel';
import { PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import MessageTypeSelectorSend from '../../../../General/components/MessageTypeSelectorSend';


const StatusType = [
   <div className="ml-2"><Badge bg={'success'}><Check /> Presente</Badge></div>,
   <div className="ml-2"><Badge bg={'danger'}> <Close /> Ausente</Badge></div>,
   <div className="ml-2"><Badge bg={'warning'}><InfoOutlined /> Atrasado</Badge></div>
];

const StatusTypeText = [
   "✅ Presente",
   "❌ Ausente",
   "⏰ Atrasado"
];

const columns = [
   {
      field: 'index',
      width: 90,
      headerName: 'Nº',
      resizable: true,
   },
   {
      field: 'student',
      headerName: 'Nome do aluno',
      resizable: true,
      width: 400,
      cellRenderer: (props) => {
         return <div className='ed-flex'>
            <Avatar className='df'
               alt={
                  props.data?.name
                     ? props.data.name.split("-").pop().trim()
                     : "Usuário"
               }
               src={props.data.picture !== "" ? Hoot() + props.data.picture : ""} />
            <span className='ml-2'>{props.data.name}</span>
         </div>
      }
   },
   {
      field: 'status',
      width: 180,
      headerName: 'Status',
      resizable: true,
      cellRenderer: (props) => {
         return <div className='ed-flex'> {StatusType[props.data.status]} </div>
      }
   },
   {
      field: 'timing',
      width: 120,
      headerName: 'Horário',
      resizable: true,
   },
   {
      field: 'date',
      width: 180,
      headerName: 'Data',
   },
   {
      field: 'action',
      headerName: 'Ação',
      width: 380,
      resizable: true,
      cellRenderer: (props) => {
         return <div className="ed-flex">
            <AttendanceModal data={props.data.Data.data} timings={props.data.Data.timings} title='Atualizar ' update='true' get={Hoot() + `eduallgetsinglestudentattendance/get/${props.data.id}`}
               url={Hoot() + `eduallstudentattendanceupdate/update/${props.data.id}`}
               toggle_btn={
                  <button className="btn-circle btn-edit-timing bg-success text-light">
                     <Edit />
                  </button>
               }
            />
            <DeleteModal title='esta informação' url={Hoot() + `eduallstudentattendancedelete/delete/${props.data.id}`}
               message='Marcação de presença deletado com sucesso' toggle_btn={
                  <button className="btn-circle mr-2 btn-delete-timing bg-danger ml-2 text-light">
                     <Delete />
                  </button>
               } />
            <MessageTypeSelectorSend
               message={props.data.msg}
               select={true}
               mark={false}
               title={null}
               send={null}
               student={props.data.studentid}
            />
         </div>;
      }
   },
];

function TeacherAttendanceTabItem(props) {
   const [data, setData] = useState([]);
   const [AttendanceGender, setAttendanceGender] = useState(null);
   const [AttendanceClass, setAttendanceClass] = useState(null);
   const [AttendanceSubject, setAttendanceSubject] = useState(null);
   const [DT, SetDT] = useState([]);
   const [load, setLoaded] = useState(false);

   const TABLEURL = [
      Hoot() + 'eduallgetstudentsbyclass/',
      Hoot() + 'eduallgetstudentattendancebyteacherclassandsub/get/',
      Hoot() + "eduallgetemployeeattendencebycode/get/"
   ];

   async function loadData(C, CS, G) {
      let students = { data: [], dataFilter: [] };
      setLoaded(false);
      try {
         if (CS !== null && CS !== undefined && C !== null && G !== null && C !== undefined && G !== undefined) {
            const response = await axios.get(TABLEURL[1] + CS);

            console.log("API Response:", response.data);

            // Garante que seja um array
            const apiData = Array.isArray(response.data)
               ? response.data
               : response.data?.data || [];

            apiData.forEach((item, index) => {
               students.data.push(item);
            });

            students.dataFilter = students.data
               .map((item) => ({
                  id: item.ed_student_attd_id,
                  studentid: item.ed_student_id,
                  picture: item.ed_student_picture,
                  name: `(#${item.ed_student_code}) - ${item.ed_student_name}`,
                  sortName: item.ed_student_name,
                  student: item.ed_student_attd_student_code,
                  timing:
                     item.ed_timing_hour_start +
                     ":" +
                     item.ed_timing_minute_start +
                     "-" +
                     item.ed_timing_hour_end +
                     ":" +
                     item.ed_timing_minute_end,
                  date: item.ed_student_attd_date,
                  status: item.ed_student_attd_status,
                  action: true,
                  msg: {
                     status: StatusTypeText[item.ed_student_attd_status * 1],
                     date: item.ed_student_attd_date,
                     time:
                        item.ed_timing_hour_start +
                        ":" +
                        item.ed_timing_minute_start +
                        "-" +
                        item.ed_timing_hour_end +
                        ":" +
                        item.ed_timing_minute_end,
                     subject: item.ed_subject_title,
                  },
                  Data: { data: props.Data.data, timings: props.Data.timings },
               }))
               .sort((a, b) =>
                  a.sortName.localeCompare(b.sortName, "pt", { sensitivity: "base" })
               )
               .map((item, ind) => ({
                  ...item,
                  index: ind + 1,
               }));
         }
      } catch (error) {
         console.log("Erro ao carregar dados:", error);
      }
      setData(students.dataFilter);
      setLoaded(true);
   }

   useEffect(() => {
      SetDT(props.Data.data);
      setTimeout(() => {
         loadData(
            CRValue("#student_attendance_classSub").split("|")[0],
            CRValue("#student_attendance_classSub").split("|")[1],
            CRValue("#student_attendance_gender")
         );
      }, 500);
      document.querySelector("#student_attendance_date").valueAsDate = new Date();
   }, []);

   const handleInput = (e) => {
      e.preventDefault();
      switch (e.target.id) {
         case "student_attendance_classSub":
            loadData(
               e.target.value.split("|")[0],
               e.target.value.split("|")[1],
               CRValue("#student_attendance_gender")
            );
            break;
         case "student_attendance_gender":
            loadData(
               CRValue("#student_attendance_classSub").split("|")[0],
               CRValue("#student_attendance_classSub").split("|")[1],
               CRValue("#student_attendance_gender")
            );
            break;
         default:
      }
   }

   return (
      <Container>
         <div className="top-container">
            <Box className="ed-dashboard-attendance-item">
               <div className="ed-space">
                  <div className='ed-flex mr-2 mt-2'>
                     <h1 className='mr-2'>Marcar presença</h1>
                     <Form className='mt-2'>
                        <Form.Group className="ml-2" >
                           <Form.Select id='student_attendance_classSub' onChange={handleInput}>
                              {DT.map((item, index) => {
                                 return (<option value={item.ed_tch_subject_class + "|" + item.ed_tch_subject_id}>
                                    Turma - <GetClasstitle_byclass ID={item.ed_tch_subject_class} />
                                    ( <GetSubject ID={item.ed_tch_subject_code} /> )
                                 </option>)
                              })}
                           </Form.Select>
                        </Form.Group>
                     </Form>
                  </div>
                  <div className="ed-flex" >
                     <div className="mr-2">
                        <StudentBehaviorModal data={props.Data.data} timings={props.Data.timings} />
                     </div>
                     <AttendanceModal data={props.Data.data} timings={props.Data.timings} />
                  </div>
               </div>
               <AttendanceBox className='at-box'>
                  <div className="d-none">
                     <FilterBox className="filter-box">
                        <Form>
                           <div className='mt-4'>
                              <DatePickerBox />
                           </div>
                           <div className="d-none">
                              <Form.Group className='mt-4'>
                                 <Form.Label>Data</Form.Label>
                                 <Form.Control type='date' id='student_attendance_date' onChange={handleInput} />
                              </Form.Group>
                              <Form.Group className='mt-4'>
                                 <Form.Label>Horário</Form.Label>
                                 <Form.Select id='student_attendance_timing' onChange={handleInput}>
                                    {props.Data.timings.map((item, index) => {
                                       return (
                                          <option value={item.ed_tch_timing_code}>
                                             <GetTime ID={item.ed_tch_timing_code} />
                                          </option>)
                                    })}
                                 </Form.Select>
                              </Form.Group>
                           </div>
                        </Form>
                     </FilterBox>
                  </div>
                  <div className='col'>
                     <div className='d-none'>
                        <button className="btn table-btn-small el-refresh-list bg-main  ml-2"
                           onClick={() => loadData(
                              CRValue("#student_attendance_classSub").split("|")[0],
                              CRValue("#student_attendance_classSub").split("|")[1],
                              CRValue("#student_attendance_gender")
                           )}><Refresh /></button>
                     </div>
                     <div className="table-box-area" id='TeacherAttendanceTabItem-area' >
                        {load ?
                           <TableGrid
                              TableHead={columns}
                              TableBody={data}
                              TableHeight={600}
                              TableBtn={
                                 <div className='ed-flex' >
                                    <button className='btn-icon btn btn-export-data ml-2'
                                       onClick={() => ExportDataForTablesExcel("Lista de presença", ["Marcar", "Ação", "action"], "TeacherAttendanceTabItem-area")}><PiMicrosoftExcelLogoDuotone />
                                    </button>
                                 </div>}
                              TableTitle="" />
                           :
                           <>
                              <div className="d-none"><h1>*</h1></div>
                              <TableGrid
                                 TableHead={columns}
                                 TableBody={[]}
                                 TableHeight={600}
                                 NoButtons
                                 TableTitle="" />
                           </>
                        }
                     </div>
                  </div>
               </AttendanceBox>
            </Box>
         </div>
         <br />
      </Container>
   );
}

export default TeacherAttendanceTabItem;

const Container = styled.section`
     display:block;
     width:100%; 
     .top-container{
         margin-top:20px;
         z-index:100;
     }  
`;

const AttendanceBox = styled.div`
  display:flex;
  width:100%;
`;

const FilterBox = styled.section`
   width:330px;
   min-width:330px;
   padding-right:40px;
`;

const Box = styled.div`
   width:100%;
   border-radius:6px; 
   min-height:90px; 
   background:var(--ed-white);  
   box-shadow:var(--ed-shadow-df); 
   padding:20px;
   position: relative; 

    .ed-space{
        h1{
          font-size:22px;
          font-weight:600;
          margin:0px;
        }
    }

   .custom-table{
       box-shadow:none !important;
   }
`
