import React, { useEffect, useState } from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap'
import { InfoOutlined, Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import ClearInputs from '../../../General/components/ClearInputs';
import { CourseDataOptions, AcademicYearDataOptions, ClassroomsDataOptions, CicleDataOptions, GetInstituteCode, AcademiclevelDataOptions, StudentsArray } from '../../../General/components/InstituteData';
import { RichTextEditor } from '../../../General/components/RichTextEditor';
import CRValue from '../../../General/components/CRValue';
import { toast } from 'react-hot-toast';
import { Update } from '@material-ui/icons';
import SelectSearch from 'react-select-search';
import RefreshList from '../../../General/components/RefreshList';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import StudentDetailsMenu from '../elements/StudentDetailsMenu';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';

function NewRequestModal(props) {
  const [show, setShow] = useState(false);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});
  const [studentCode, setStudentCode] = useState(null);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [Founded, SetFounded] = useState(null);

  const [showBox, SetshowBox] = useState(false);
  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200);
  }

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };

  const INPUTS = {
    request_type: CRValue("#request_type"),
    request_description:CRValue("#request_description"),
    request_status: CRValue("#request_status"),
  };

  const FORMURL = [
    Hoot() + "eduallregisterrequest/post/",
    props.get ? props.get : '',
    props.url ? props.url : ''
  ];

  const GET_DATA = async () => {
    if (props.update) {
      try {
        const response = await axios.get(FORMURL[1]);
        if (response.data.length > 0) {
          setField("request_type", response.data[0].ed_request_type);
          INPUTS.request_type = response.data[0].ed_request_type;
          setStudentCode(response.data[0].ed_request_made_by);
          setField("request_status", response.data[0].ed_request_status);
          INPUTS.request_status = response.data[0].ed_request_status;

          setField("request_description", response.data[0].ed_request_description);
          INPUTS.request_description = response.data[0].ed_request_description;
        } else {
          toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
        }
      } catch (error) {
        toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
      }
    }
  }

  const setField = (field, value) => {
    setForm({
      ...form,
      [field]: value
    })

    if (!!errors[field]) {
      setErrors({
        ...errors,
        [field]: null
      });
    }
  }


  const validateForm = () => {
    const { request_type, request_made_by } = form;
    const NewErrors = {};
    setRegisterStatus(0);
    if (INPUTS.request_type === "" || INPUTS.request_type === " ") {
      if (!request_type || request_type === '') NewErrors.request_type = 'Tipo de solicitação invalida';
    } else { if (!request_type) { setField("request_type", INPUTS.request_type); } }


    if (INPUTS.request_made_by === "" || INPUTS.request_made_by === " ") {
      if (!request_made_by || request_made_by === '') NewErrors.request_made_by = 'Selecione um estudante';
    } else { if (!request_made_by) { setField("request_made_by", INPUTS.request_made_by); } }

    if (studentCode === null) NewErrors.request_made_by = 'Selecione um estudante';

    return NewErrors;
  }
 
  const FormSubmit = (e) => {
    e.preventDefault();
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os  campos");
      setRegisterStatus(1);
    } else {

      const SUBMIT_INPUTS = {
        request_type: INPUTS.request_type,
        request_made_by: studentCode,
        request_description: INPUTS.request_description,
        request_status: INPUTS.request_status
      };

      if (!props.update) {

        try {
          axios.post(FORMURL[0], SUBMIT_INPUTS).then(() => {
            toast.success("Solicitação  registrada com sucesso !");
            setForm({});
            ClearInputs();
            setRegisterStatus(2);
            RefreshList(`.el-refresh-list`)
            setTimeout(() => {
              handleClose();
            }, 1500);
          }).catch((error) => {
            setRegisterStatus(1);
            toast.error("Lamentamos mas não foi  possivel executar esta ação !");
            console.clear();
            console.log(error.response);
          });
        } catch (error) {
          setRegisterStatus(1);
          toast.error("Lamentamos mas não foi  possivel executar esta ação !");
          console.clear();
          console.log(error.response);
        }
      } else {
        try {
          axios.put(FORMURL[2], SUBMIT_INPUTS).then(() => {
            toast.success("Solicitação  atualizada com sucesso !");
            setForm({});
            ClearInputs();
            setRegisterStatus(2);
            RefreshList(`.el-refresh-list`)
            setTimeout(() => {
              handleClose();
            }, 1000);
          }).catch((error) => {
            setRegisterStatus(1);
            toast.error("Lamentamos mas não foi  possivel executar esta ação !");
            console.clear();
            console.log(error.response);
          });
        } catch (error) {
          setRegisterStatus(1);
          toast.error("Lamentamos mas não foi  possivel executar esta ação !");
          console.clear();
          console.log(error.response);
        }
      }
    }
  };


  const GetStudentCode = (e) => {
    setStudentCode(e);
    setField("request_made_by", e);
  }

  const handleInput = (e) => {
    switch (e.target.id) {
      case "request_type":
        INPUTS.request_type = e.target.value
        setField("request_type", e.target.value);
        break;
      case "request_status":
        INPUTS.request_status = e.target.value;
        setField("request_status", e.target.value);
        break;
      case "request_description":
        INPUTS.request_description = e.target.value;
        setField("request_description", e.target.value);
        break;
      default:
    }
  }


  return (
    <div>
      <div onClick={handleShow}>
        {
          props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon /> Efetuar solicitação</button>
        }
      </div>
      <Modal className={showBox ? ModalAnimationShow() : ModalAnimationClose()} centered size='lg' dialogAs={DraggableModal} show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>{props.title ? props.title : 'Efetuar '} solicitação</h5>
            </div>
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={FormSubmit}>
          <Modal.Body className='scrollLimit'>
            <Form.Group className='mb-3'>
              <div className="ed-space">
                <div>
                  <Form.Label>Nome do estudante <span className='text-danger ml-2'>*</span></Form.Label>
                </div>
                <div className='ed-flex'>
                  {studentCode !== null ? <StudentDetailsMenu student_id={studentCode} toggle_btn={<div className='btn-pm-info'><InfoOutlined /></div>} /> : <></>}
                </div>
              </div>
              <SelectSearch onChange={(e) => GetStudentCode(e)} value={studentCode} options={StudentsArray()[0]}
                search={true} name='request_user_name' placeholder='Selecione um estudante' />
              <Form.Control.Feedback type='invalid'>{errors.request_made_by}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3"  >
              <Form.Label>Tipo de solicitação<span className="text-danger ml-2">*</span> </Form.Label>
              <Form.Select onChange={handleInput} className={!!errors.request_type && 'is-invalid'} value={form.request_type} isInvalid={!!errors.request_type}
                id="request_type">
                <option value="1" selected>Boletim de notas</option>
                <option value="2">Transferencia escolar</option>
                <option value="3">Declaração estudantil</option>
                <option value="4">Extrato geral do aluno</option>
                <option value="5">Outro</option>
              </Form.Select>
              <Form.Control.Feedback type='invalid'>{errors.request_type}</Form.Control.Feedback>
            </Form.Group>
            {props.update ?
              <>
                <Form.Group className="mb-3">
                  <Form.Label>Status da solicitação<span className='text-danger ml-2'>*</span></Form.Label>
                  <Form.Select onChange={handleInput} className={!!errors.request_status && 'is-invalid'} value={form.request_status}
                    isInvalid={!!errors.request_status} type="text" id="request_status">
                    <option value="0" selected>Pendente</option>
                    <option value="1">Entregue</option>
                  </Form.Select>
                  <Form.Control.Feedback type='invalid'>{errors.request_status}</Form.Control.Feedback>
                </Form.Group>
              </>
              : <></>}
            <Form.Group>
              <Form.Label>Descrição do pedido<span className="text-danger ml-2">*</span> </Form.Label>
              <div className="request-description">
                <textarea name="request_description" onChange={handleInput} rows={10} id="request_description" value={form.request_description} className="form-control"></textarea>
              </div>
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <div className="ed-space">
              <div className="ed-flex"></div>
              <div className="ed-flex">
                <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                {props.update ? (Founded === false ? <div></div> :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />}
              </div>
            </div>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  )
}

export default NewRequestModal