import { BookOutlined, ErrorOutline, HomeOutlined, MailOutlineRounded, NotificationsNoneRounded, } from '@material-ui/icons';
import { CurrencyPoundOutlined, QuizOutlined } from '@mui/icons-material';
import { Avatar, IconButton } from '@mui/material';
import React, { useEffect, useState } from 'react'
import axios from 'axios';
import jwt_decode from 'jwt-decode';
import FactCheckOutlinedIcon from '@mui/icons-material/FactCheckOutlined';
import HomeOutlinedIcon from '@mui/icons-material/HomeOutlined';
import PaidOutlinedIcon from '@mui/icons-material/PaidOutlined';
import { Search } from '@material-ui/icons'
import { GoBell } from "react-icons/go";
import { BsJournalBookmark, BsChat, BsCollectionPlay, BsHouse, BsQuestionCircle, BsCalendarEvent, } from "react-icons/bs";
import { Link } from 'react-router-dom';
import styled from 'styled-components'
import Logo from '../../Assets/images/logo-small-white.png';
import { deepOrange } from '@material-ui/core/colors';
import NotificationUserPop from './NotificationUserPop';
import NavbarSearchForm from './NavbarSearchForm';
import Hoot from '../../General/components/Hoot';
import Menu from '@mui/material/Menu';
import MenuItem from '@mui/material/MenuItem';
import ListItemIcon from '@mui/material/ListItemIcon';
import Divider from '@mui/material/Divider';
import PersonAdd from '@mui/icons-material/PersonAdd';
import Settings from '@mui/icons-material/Settings';
import Logout from '@mui/icons-material/Logout';
import ReduceTextLength from '../../General/components/ReduceTextLength';
import { useHistory } from 'react-router-dom';
import { LiaEllipsisVSolid } from "react-icons/lia";
import { GrHomeRounded, GrBook, GrNotification, GrGroup, GrSearch, GrServicePlay, GrMoney } from "react-icons/gr";
import { PiChatCenteredBold } from "react-icons/pi"
import LogoItem from './LogoItem';
import ToggleMenuNavbar from './ToggleMenuNavbar';
import MessagesDropDownMenu from '../../General/components/MessagesDropDownMenu';
import NotificationModal from "../../General/components/NotificationModal";
import { getMotivationalWorkQuote } from './getMotivationalWorkQuote';
import ImageLazyLoading from '../../General/components/ImageLazyLoading';
import ThemeModal from '../../Dashboard/components/elements/ThemeModal';
import ThemeToggle from '../../Dashboard/components/elements/ThemeToggle';
import ReportFeedbackModal from '../../Dashboard/components/modal/ReportFeedbackModal';




function UserNavbar({ data, menu, nologo, logoIndex, noquote }) {
  const LogoImg = [
    require('../../Assets/images/logos/black/eduall-workspaces.png'),
    require('../../Assets/images/logos/black/eduallportalENC-8.png'),
    require('../../Assets/images/logos/black/eduallportalEST-8.png'),
    require('../../Assets/images/logos/black/eduallportalPF-8.png')
  ];

  const [UserData, setUserData] = useState({});
  const [anchorEl, setAnchorEl] = useState(null);
  const [ActiveMenu, setActiveMenu] = useState(1);
  const [ShowLogos, SetShowLogos] = useState(false);

  const open = Boolean(anchorEl);
  const history = useHistory();


  const handleClick = (event) => {
    setAnchorEl(event.currentTarget);
  };
  const handleClose = () => {
    setAnchorEl(null);
  };

  const DATA_URL = [
    Hoot() + 'eduallsingleuserdata/get/',
    Hoot() + 'token',
    Hoot() + 'logout',
  ];

  function getFirstAndLastName(fullName) {
    if (!fullName || typeof fullName !== "string") return "";
    const parts = fullName.trim().split(/\s+/);

    if (parts.length === 0) return "";

    if (parts.length === 1) {
      return parts[0];
    }
    return parts[0] + " " + parts[parts.length - 1];
  }

  async function loadData() {
    setUserData({
      email: data.user_Information.ed_user_account_email,
      phone: data.user_Information.ed_userphone,
      picture: Hoot() + data.user_Information.ed_user_account_picture,
      code: data.user_Information.ed_user_account_id,
      name: data.user_Information.ed_user_account_name,
      color: data.user_Information.ed_user_account_detAvatarColor,
      fisrtlastname: getFirstAndLastName(data.user_Information?.ed_user_account_name || ""),
      lettername: (() => {
        const fullName = data?.user_Information?.ed_user_account_name?.trim();
        if (!fullName) return '';

        const parts = fullName.split(/\s+/);
        const firstInitial = parts[0]?.[0]?.toUpperCase() || '';
        const lastInitial = parts[parts.length - 1]?.[0]?.toUpperCase() || '';

        return firstInitial + lastInitial;
      })(),
    });
  };

  useEffect(() => {
    setTimeout(() => {
      SetShowLogos(true);
    }, 10);
  }, [data, menu, nologo, logoIndex, noquote]);


  useEffect(() => {
    loadData();
    if (menu && menu >= 0) setActiveMenu(menu);
    console.log(data.user_Information);
  }, []);


  const AccountLogout = async () => {
    try {
      localStorage.setItem("CurrentTab", 1);
      localStorage.setItem("CurrentPage", null);
      await axios.delete(DATA_URL[2]);
      history.push('/');
    } catch (error) {
      console.log("something went wrong");
    }
  }

  return (
    <>
      <NavbarMenu className={noquote ? 'ed-user-navbar nav-theme fixed' : 'nav-theme no-quote-nav ed-user-navbar'} >
        <div className="ed-wrapper">
          <div className="ed-flex ed-space">
            <div>
              <menu className={ShowLogos ? "ed-flex" : "d-none"} >
                <div className="workspace-logo">
                  <Link to='/WorkSpaces'> {nologo ? <></> : <ImageLazyLoading source={LogoImg[logoIndex ? logoIndex : 0]} />}</Link>
                </div>
                {noquote ? <></> :
                  <div className="d-block  text-user">
                    <small className='grey-text'>
                      Seja bem-vindo de volta {UserData?.fisrtlastname?.trim().split(" ")[0] || ""}
                    </small>

                    <h5 className="theme-light-txt">{getMotivationalWorkQuote()}</h5>
                  </div>
                }
              </menu>
            </div>
            <menu className="ed-flex navbar-links d-none">
              <div onClick={() => setActiveMenu(1)}  >
                <Link to='/WorkSpaces' className={ActiveMenu === 1 ? "active" : ""}><BsHouse />Noticias</Link>
              </div>
              <div onClick={() => setActiveMenu(2)}  >
                <Link to='#' className={ActiveMenu === 2 ? "active" : ""}><BsCollectionPlay />Cursos</Link>
              </div>
              <div onClick={() => setActiveMenu(3)}  >
                <Link to='#' className={ActiveMenu === 3 ? "active" : ""}><BsQuestionCircle />Forum</Link>
              </div>
              <div onClick={() => setActiveMenu(4)}  >
                <Link to='/mentorship' className={ActiveMenu === 4 ? "active" : ""}><BsJournalBookmark />Mentoria</Link>
              </div>
              <div onClick={() => setActiveMenu(5)}  >
                <Link to='/jobs' className={ActiveMenu === 5 ? "active" : ""}><BsCalendarEvent />Empregos</Link>
              </div>
            </menu>
            <menu className='ed-flex ed-nav-item'>
              <ul>
                <div className="ed-icons d-none">
                  <div className="mr-2">
                    <NotificationModal />
                  </div>
                  <div className="mr-2">
                    <MessagesDropDownMenu />
                  </div>
                </div>
              </ul> 
               <ReportFeedbackModal />
              <Link to='#'>
                <IconButton onClick={handleClick} size="small" sx={{ ml: 2 }} aria-controls={open ? 'account-menu' : undefined}
                  aria-haspopup="true" aria-expanded={open ? 'true' : undefined} >
                  <Avatar className='df' src={UserData.picture} alt={UserData.lettername} sx={{ width: 40, height: 40, bgcolor: UserData.color }}>{UserData.lettername}</Avatar>
                </IconButton>
                <Menu anchorEl={anchorEl} id="account-menu" open={open} onClose={handleClose} onClick={handleClose}
                  PaperProps={{
                    elevation: 0,
                    style: {
                      maxHeight: 400,
                      width: '300px',
                    },
                    sx: {
                      overflow: 'visible',
                      filter: 'drop-shadow(0px 2px 8px rgba(0,0,0,0.32))',
                      mt: 1.5,
                      '& .MuiAvatar-root': {
                        width: 32,
                        height: 32,
                        ml: -0.5,
                        mr: 1,
                      },
                      '&:before': {
                        content: '""',
                        display: 'block',
                        position: 'absolute',
                        top: 0,
                        right: 14,
                        width: 10,
                        height: 10,
                        bgcolor: 'background.paper',
                        transform: 'translateY(-50%) rotate(45deg)',
                        zIndex: 0,
                      },
                    },
                  }}
                  transformOrigin={{ horizontal: 'right', vertical: 'top' }} anchorOrigin={{ horizontal: 'right', vertical: 'bottom' }} >
                  <div className="scrollLimit2">
                    <Link to="#" className='text-dark d-none'>
                      <MenuItem onClick={handleClose}>
                        <Avatar className='df' src={UserData.picture} alt={UserData.lettername} sx={{ bgcolor: UserData.color }} /> {UserData.fisrtlastname}
                      </MenuItem>
                    </Link>
                    {data.user_childs.length >= 1 ?
                      <div className='d-none' >
                        <Divider />
                        <div className="navbar-menu-details">
                          <h5 className='nav-menu-title'>Filhos<span className="text-main ml-1">({data.user_childs.length})</span> </h5>
                          <div className="block mt-2">
                            {data.user_childs.map((item, index) => {
                              return (
                                <Link to={`/parent_portal/${item.ed_student_id}`}>
                                  <MenuItem onClick={handleClose}>
                                    <Avatar className='df' src={Hoot() + item.ed_student_picture} alt={item.ed_student_name} sx={{ bgcolor: UserData.color }} />
                                    <ReduceTextLength text={item.ed_student_name} length="20" />
                                  </MenuItem>
                                </Link>
                              )
                            })}
                          </div>
                        </div>
                      </div>
                      :
                      <></>
                    }
                    {data.user_institutes.length >= 1 ?
                      <div className='d-none' >
                        <Divider />
                        <div className="navbar-menu-details">
                          <h5 className='nav-menu-title'>Instituições de ensino <span className="text-main ml-1">({data.user_institutes.length})</span> </h5>
                          <div className="block mt-2">
                            {data.user_institutes.map((item, index) => {
                              return (
                                <Link to={`/teacher_dashboard/${item.ed_institute_code}`}>
                                  <MenuItem onClick={handleClose}>
                                    <Avatar className='df' rounded src={Hoot() + item.ed_institute_logo} alt={item.ed_institute_name} sx={{ bgcolor: UserData.color }} />
                                    <ReduceTextLength text={item.ed_institute_name} length="20" />
                                  </MenuItem>
                                </Link>
                              )
                            })}
                          </div>
                        </div>
                      </div>
                      :
                      <></>
                    }
                    {data.user_student_accounts.length >= 1 ?
                      <div className='d-none' >
                        <Divider />
                        <div className="navbar-menu-details">
                          <h5 className='nav-menu-title'>Contas de estudante <span className="text-main ml-1">({data.user_student_accounts.length})</span> </h5>
                          <div className="block mt-2">
                            {data.user_student_accounts.map((item, index) => {
                              return (
                                <Link to={`/student_portal/${item.ed_student_id}`}>
                                  <MenuItem onClick={handleClose}>
                                    <Avatar className='df' src={Hoot() + item.ed_student_picture} alt={item.ed_student_name} sx={{ bgcolor: UserData.color }} />
                                    <ReduceTextLength text={item.ed_student_name} length="20" />
                                  </MenuItem>
                                </Link>
                              )
                            })}
                          </div>
                        </div>
                      </div>
                      :
                      <></>}
                    <MenuItem onClick={AccountLogout} >
                      <ListItemIcon>
                        <Logout fontSize="small" />
                      </ListItemIcon>
                      Terminar sessão
                    </MenuItem>
                  </div>
                </Menu>
              </Link>
            </menu>
          </div>
        </div>
      </NavbarMenu>
      {noquote ? <div> <br /><br /><br />  </div> : <></>}
    </>
  )
}




const NavbarMenu = styled.div`
    width:100%;
    height:80px;  
    z-index:1000; 
    top:0px;
    left:0px;
    padding:0px 20px;  
    background:var(--ed-white); 
    box-shadow:var(--ed-shadow-df);


    .workspace-logo{
       img{ 
           max-width:250px;
           margin-right:20px; 
       }
    }


    .text-user{
       h5{
          font-size:17px;
          font-weight:bolder;
          margin:0px;
          margin-top:5px;
       }
    }

    .toggle-search,
    .toggle-menu{
       display:none;
    }

      
    .nav-toggle{
      background:transparent;
      color:var(--ed-dark) !important;
      border:0px !important;
      padding:0px;
      position:relative;

        svg{
            color:var(--ed-dark) !important;
            fill:var(--ed-dark) !important;
        }
  }

  
    input{
        border:none !important;
    }

 

    menu { 
      margin:0px !important; 
      padding:10px 0px;
      align-items:center;
      height:100%; 

    ul{
      display:flex;
      align-items:center;
      padding:0px;
      margin:0px !important;
    }

      ul li {
          position:relative;
          margin-left:10px;
          list-style:none;
          cursor:pointer;
          width:40px;
          height:40px;
          border-radius:100%;
          background:var(--ed-silver-light);
          display:flex;
          align-items:center;
          justify-content:center;

          svg{
            width:20px;
            height:20px;
            fill:var(--dark);
          }

          .count{
            padding:3px 5px;
            border-radius:20px;
            position: absolute;
            top:-10px;
            left:15px;
            font-size:11px;
            font-weight:400;
            color:var(--ed-white);
            background:var(--ed-red);
          }
      }
      
   
    }
 
    .navbar-links {
    a{
      margin:0px 15px;
      color:var(--dark);
      font-size:17px;
      display:flex;
      align-items:center;
      font-weight:500;
      position:relative;

      svg{
        fill:var(--dark);
        margin-right:5px;
      }
    }

    a.active{ 
      color:var(--ed-purple);

      svg{
         color:var(--ed-purple);
         fill:var(--ed-purple);
      }

       &:after{
        content:"";
         position:absolute;
         transition:all 1s ease-in-out;
         top:25px;
         left:0px;
         min-width:100px;
         width:max-content;
         height:5px;
         border-radius:30px;
         background:var(--ed-purple);
       }
    }

  }


`;
export default UserNavbar