const SidebarContainer = ({ toggle, content }) => {
  const [show, setShow] = useState(false);
  const handleClose = () => setShow(false);
  const handleShow = () => setShow(true);
  return (
    <div>
      <div onClick={handleShow}>{toggle}</div>
      <Offcanvas show={show} onHide={handleClose}>
        <Offcanvas.Body>
          <div className="sidebar-panel-menu">
            {content}
            <button className="btn btn-close-sidebar-panel" onClick={handleClose}>close</button>
          </div>
        </Offcanvas.Body>
      </Offcanvas>
    </div>
  )
};

