/** ---------- Helpers ---------- */
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const chunk = (arr, size) => {
  const out = [];
  for (let i = 0; i < arr.length; i += size) out.push(arr.slice(i, i + size));
  return out;
};

const TYPE_CHECKERS = {
  // string agora aceita números também
  string: (v) =>
    v === undefined || v === null || v === "" || typeof v === "string" || typeof v === "number",
  number: (v) => v === undefined || v === null || v === "" || !isNaN(Number(v)),
  boolean: (v) =>
    typeof v === "boolean" ||
    v === "true" ||
    v === "false" ||
    v === 1 ||
    v === 0 ||
    v === "1" ||
    v === "0",
  date: (v) => !isNaN(new Date(v).getTime()),
  email: (v) => typeof v === "string" && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v),
};

function coerceValueByType(v, type) {
  if (v === "" || v === undefined || v === null) return undefined;
  switch (type) {
    case "number":
      return Number(v);
    case "boolean":
      return v === true || v === "true" || v === 1 || v === "1";
    case "date": {
      // aceita YYYY-MM-DD diretamente (input type=date)
      const d = new Date(v);
      return isNaN(d.getTime()) ? undefined : d.toISOString();
    }
    case "string":
      return String(v);
    default:
      return v;
  }
}

const priceFmt = (v) => {
  const n = Number(v);
  if (isNaN(n)) return v;
  return n.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
};

/** ---------- Regras especiais ---------- */
const isBinaryField = (field) => {
  const label = String(field?.label || "");
  const type = String(field?.type || "").toLowerCase();
  return (
    /0\/1/i.test(label) ||
    type === "boolean" ||
    /status$/i.test(field?.key || "") ||
    /workstatus/i.test(field?.key || "") ||
    /forExam|forFt/i.test(field?.key || "")
  );
};

const isClassPickerOnly = (field) => {
  const key = String(field?.key || "");
  const label = String(field?.label || "");
  return /_class$/i.test(key) || /Turma/i.test(label);
};

/** ---------- Docked Bar ---------- */
function DockedUploaderBar({ visible, progress, inserted, errors, onShowModal }) {
  if (!visible) return null;
  return (
    <div
      style={{
        position: "fixed",
        right: 16,
        bottom: 16,
        zIndex: 2000,
        maxWidth: 460,
        width: "92%",
        background: "#fff",
        border: "1px solid #e5e5e5",
        borderRadius: 12,
        boxShadow: "0 10px 30px rgba(0,0,0,.15)",
        padding: 12,
      }}
    >
      <div className="d-flex align-items-center mb-2" style={{ gap: 8 }}>
        <div className="ed-wrap align-center">
          <UserOptionDropDown />
          <h5> Importar dados dinámicos</h5>
        </div>
        <span className="ms-auto">
          <Button size="sm" variant="outline-primary" onClick={onShowModal}>
            Ver detalhes
          </Button>
        </span>
      </div>
      <ProgressBar now={progress} label={`${progress}%`} />
      <div className="mt-2 d-flex" style={{ gap: 12, fontSize: 13 }}>
        <span className="text-success">
          <b>{inserted}</b> inseridos
        </span>
        <span className="text-danger">
          <b>{errors}</b> erros
        </span>
      </div>
    </div>
  );
}

