  /** Validação + construção do payload */
  const validateRows = (rows, fieldCfgs, form) => {
    const errors = [];
    const ok = [];
    const specByKey = Object.fromEntries(form.fields.map((f) => [f.key, f]));

    rows.forEach((row, idx) => {
      const obj = { __rowIndex: idx, __runId: runId };
      const rowErrors = [];

      form.fields.forEach((field) => {
        const spec = specByKey[field.key];
        const conf = fieldCfgs[field.key] || {};
        let raw;

        if (isClassPickerOnly(field)) {
          raw = conf.value;
        } else if (isBinaryField(field)) {
          raw = conf.value;
        } else {
          if (conf.sourceType === "fixed") raw = conf.value;
          else if (conf.sourceType === "system") raw = conf.value;
          else if (conf.sourceType === "excel") {
            const colName = conf.excelColumn;
            const excelIndex = columns.indexOf(colName);
            raw = excelIndex >= 0 ? row[excelIndex] : undefined;
          } else {
            const excelIndex = columns.indexOf(field.key);
            raw = excelIndex >= 0 ? row[excelIndex] : undefined;
          }
        }

        if (spec?.required && (raw === undefined || raw === null || String(raw).trim?.() === "")) {
          rowErrors.push({ field: field.key, message: "Obrigatório" });
        } else if (raw !== undefined && raw !== null && String(raw).trim?.() !== "") {
          const checker = TYPE_CHECKERS[spec?.type || "string"] || TYPE_CHECKERS.string;
          if (!checker(raw)) {
            rowErrors.push({ field: field.key, message: `Tipo inválido (${spec?.type})` });
          } else {
            obj[field.key] = coerceValueByType(raw, spec?.type || "string");
          }
        } else {
          obj[field.key] = undefined;
        }
      });

      if (rowErrors.length) {
        errors.push({ index: idx, errors: rowErrors, rowData: row });
      } else {
        ok.push(obj);
      }
    });

    return { ok, errors };
  };

