  /** Processamento da fila */
  const processQueue = async () => {
    if (uploading || queue.length === 0) return;
    setUploading(true);
    setRejected([]);
    setProgress(0);
    setInsertedCount(0);
    setErrorCount(0);
    insertedRowIndexes.current = new Set();

    const current = queue[0];
    const form = current.form;
    const { insertUrl, checkUrl } = form;

    // 1) Validar localmente
    const { ok, errors } = validateRows(excelData, fieldConfigs, form);
    setErrorCount((c) => c + errors.length);
    if (errors.length > 0) setRejected(errors);

    if (ok.length === 0) {
      setUploading(false);
      setQueue((prev) => prev.slice(1));
      setProgress(100);
      return;
    }

    // 2) Checar duplicados no servidor
    let validAfterCheck = ok;
    try {
      const checkRes = await axios.post(Hoot() + checkUrl, ok, { timeout: 60000 });
      const { duplicates = [], valid = ok } = checkRes.data || {};

      if (duplicates.length) {
        setDuplicateCount((c) => c + duplicates.length);
        setRejected((prev) => [
          ...prev,
          ...duplicates.map((d) => ({
            index: d.index ?? d.__rowIndex ?? -1,
            errors: d.errors ?? [{ message: "Duplicado" }],
            rowData: excelData[d.index ?? d.__rowIndex] || [],
          })),
        ]);
      }

      validAfterCheck = valid;
    } catch (_) {
      // se o check falhar, seguimos com ok
    }

    if (validAfterCheck.length === 0) {
      setProgress(100);
      setUploading(false);
      setQueue((prev) => prev.slice(1));
      return;
    }

    // 3) Inserção em lotes
    const batches = chunk(validAfterCheck, chunkSize);
    const totalBatches = batches.length;
    let completedBatches = 0;

    const runBatch = async (batch, batchIndex) => {
      try {
        const res = await axios.post(Hoot() + insertUrl, batch, { timeout: 120000 });
        const { inserted = batch.length, failed = [] } = res.data || {};

        // marca os que entraram
        if (Array.isArray(res.data?.insertedRows)) {
          res.data.insertedRows.forEach((r) => {
            const idx = r.__rowIndex ?? r.index;
            if (idx != null) insertedRowIndexes.current.add(idx);
          });
        } else {
          const failedIdx = new Set(
            failed.map((f) => f.__rowIndex ?? f.index).filter((v) => v != null)
          );
          batch.forEach((b) => {
            const idx = b.__rowIndex;
            if (idx != null && !failedIdx.has(idx)) insertedRowIndexes.current.add(idx);
          });
        }

        setInsertedCount((c) => c + inserted);

        // filtra falsos duplicados para a MESMA run/id de linha
        const filteredFailed = (failed || []).filter((f) => {
          const idx = f.__rowIndex ?? f.index;
          const msg = (f.errors?.map((e) => e.message).join(" ") || "").toLowerCase();
          const looksDuplicate =
            msg.includes("duplic") || msg.includes("já foi inserido") || msg.includes("already");
          if (!looksDuplicate) return true;
          if (idx != null && insertedRowIndexes.current.has(idx)) return false;
          return true;
        });

        setErrorCount((c) => c + filteredFailed.length);
        if (filteredFailed.length) {
          setRejected((prev) => [
            ...prev,
            ...filteredFailed.map((f) => ({
              index: f.__rowIndex ?? f.index ?? -1,
              errors: f.errors ?? [{ message: "Falha na inserção" }],
              rowData:
                f.__rowIndex != null && excelData[f.__rowIndex]
                  ? excelData[f.__rowIndex]
                  : f.index != null && excelData[f.index]
                  ? excelData[f.index]
                  : [],
            })),
          ]);
        }
      } catch (err) {
        // Lote inteiro falhou
        setErrorCount((c) => c + batch.length);
        setRejected((prev) => [
          ...prev,
          ...batch.map((b) => ({
            index: b.__rowIndex ?? -1,
            errors: [{ message: `Falha rede/servidor (lote ${batchIndex + 1})` }],
            rowData: b.__rowIndex != null ? excelData[b.__rowIndex] : [],
          })),
        ]);
      } finally {
        completedBatches += 1;
        setProgress(Math.round((completedBatches * 100) / totalBatches));
      }
    };

    let cursor = 0;
    const runners = new Array(Math.min(maxConcurrent, batches.length))
      .fill(0)
      .map(async () => {
        while (cursor < batches.length) {
          const myIndex = cursor++;
          await runBatch(batches[myIndex], myIndex);
          await sleep(50);
        }
      });
    await Promise.all(runners);

    setProgress(100);
    setUploading(false);
    setQueue((prev) => prev.slice(1));
  };

