import React, { useEffect, useState, useRef } from 'react';
import StyleBadge from './StyleBadge';
import { Link } from 'react-router-dom';
import Hoot from '../../../General/components/Hoot';
import styled from 'styled-components';
import axios from "axios";
import { Avatar } from '@mui/material';
import { LogInOutline } from 'react-ionicons';
import Logout from '../../../General/components/Logout';
import { MdOutlineAccountCircle } from "react-icons/md";
import { Dropdown, Modal } from 'react-bootstrap';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import { LockOutlined } from '@material-ui/icons';

let ImageSize = { width: 40, height: 40 };

function UserModalMenu({ data }) {

   const userdata = data?.user_Information;

   /**  Idle logout switch */
   const IDLE_ENABLED_KEY = "idleLogoutEnabled";
   const [idleEnabled, setIdleEnabled] = useState(() => {
      const saved = localStorage.getItem(IDLE_ENABLED_KEY);
      return saved ? saved === "true" : false;
   });

   const toggleIdleEnabled = (value) => {
      setIdleEnabled(value);
      localStorage.setItem(IDLE_ENABLED_KEY, value ? "true" : "false");
   };

   /**  AUTO LOGOUT LOGIC */
   const INACTIVITY_MS = 4 * 60 * 1000;
   const COUNTDOWN_SECONDS = 3 * 60;

   const [showIdleModal, setShowIdleModal] = useState(false);
   const [secondsLeft, setSecondsLeft] = useState(COUNTDOWN_SECONDS);

   const idleTimerRef = useRef(null);
   const countdownRef = useRef(null);

   const resetIdleTimer = () => {
      if (!idleEnabled) return;
      clearTimeout(idleTimerRef.current);
      idleTimerRef.current = setTimeout(() => {
         setSecondsLeft(COUNTDOWN_SECONDS);
         setShowIdleModal(true);
      }, INACTIVITY_MS);
   };

   const logoutNow = async () => {
      try {
         await axios.delete(Hoot() + "logout");
         window.location.href = "/";
      } catch (err) {
         console.log("Logout error");
      }
   };

   const beginCountdown = () => {
      clearInterval(countdownRef.current);
      countdownRef.current = setInterval(() => {
         setSecondsLeft((s) => {
            if (s <= 1) {
               clearInterval(countdownRef.current);
               logoutNow();
            }
            return s - 1;
         });
      }, 1000);
   };

   /**  Monitorizar atividade */
   useEffect(() => {
      const events = ["mousemove", "click", "keydown", "scroll", "touchstart"];
      const handler = () => {
         if (showIdleModal) {
            setShowIdleModal(false);
            clearInterval(countdownRef.current);
         }
         resetIdleTimer();
      };

      events.forEach(e => window.addEventListener(e, handler, { passive: true }));
      if (idleEnabled) resetIdleTimer();

      return () => {
         events.forEach(e => window.removeEventListener(e, handler));
         clearTimeout(idleTimerRef.current);
         clearInterval(countdownRef.current);
      };
   }, [idleEnabled, showIdleModal]);

   /**  Iniciar countdown quando modal abrir */
   useEffect(() => {
      if (showIdleModal) beginCountdown();
      else clearInterval(countdownRef.current);
   }, [showIdleModal]);

   /**  Format time */
   const formatTime = (s) => {
      const m = String(Math.floor(s / 60)).padStart(2, "0");
      const sec = String(s % 60).padStart(2, "0");
      return `${m}:${sec}`;
   };

   if (!userdata) return null;

   const fullName = userdata.ed_user_account_name || "";
   const parts = fullName.trim().split(/\s+/).filter(Boolean);

   const CurrentUsername =
      parts.length === 0 ? "" :
      parts.length === 1 ? parts[0] :
      parts[0] + " " + parts[parts.length - 1];

   const firstLastLetter =
      parts.length === 0 ? "" :
      parts.length === 1 ? parts[0][0].toUpperCase() :
      parts[0][0].toUpperCase() + parts[parts.length - 1][0].toUpperCase();

   return (
      <>
         <div className='ed-flex'>
            <Dropdown id='user-menu-dropdown'>

               <Dropdown.Toggle variant="success" id="dropdown-basic">
                  <li className="ed-flex me-2 user-menu-avatar">
                     <StyleBadge
                        userdata={userdata}
                        size={ImageSize}
                        source={Hoot() + userdata.ed_user_account_picture}
                        alt={userdata.ed_user_account_name}
                     />
                  </li>
               </Dropdown.Toggle>

               <Dropdown.Menu>

                  {/* PERFIL */}
                  <Dropdown.Item>
                     <ProfileBox>
                        <div className='avatarimage'>
                           <Avatar
                              src={Hoot() + userdata.ed_user_account_picture}
                              sx={{ width: 50, height: 50 }}
                           >
                              {firstLastLetter}
                           </Avatar>
                        </div>

                        <div className="ed-block">
                           <h1>{CurrentUsername}</h1>
                           <span>{userdata.ed_user_account_email}</span>
                        </div>
                     </ProfileBox>
                  </Dropdown.Item>

                  {/* DEFINIÇÕES */}
                  <Dropdown.Item>
                     <SwitchFromPages link={`usersettings`}
                        menu='12' menu_item='46750'
                        toggle_btn={
                           <li className="ed-flex">
                              <MdOutlineAccountCircle className='mr-1' />
                              Definições de conta
                           </li>
                        }
                     />
                  </Dropdown.Item>

                  {/*  SWITCH AUTO LOGOUT */}
                  <Dropdown.Item>
                     <div className="w-100 px-1">

                        <div className="d-flex justify-content-between align-items-center">

                           <div className="d-flex align-items-center">
                              <LockOutlined style={{ fontSize: "21px", marginRight: "6px" }} />
                              <span className='text-dark'>
                                 Encerrar sessão ao ficar inativo
                              </span>
                           </div>

                           <div className="form-check ml-2 form-switch">
                              <input
                                 className="form-check-input"
                                 type="checkbox"
                                 checked={idleEnabled}
                                 onClick={(e) => e.stopPropagation()}
                                 onChange={(e) => {
                                    e.stopPropagation();
                                    toggleIdleEnabled(e.target.checked);
                                    resetIdleTimer();
                                 }}
                              />
                           </div>

                        </div>

                        <small className='grey-text' style={{ fontSize: "13px" }}>
                           Após 4 min sem atividade será mostrado um aviso<br />
                           antes de terminar automaticamente a sessão.
                        </small>
                     </div>
                  </Dropdown.Item>

                  {/* LOGOUT */}
                  <Dropdown.Item>
                     <Logout toggle_btn={
                        <li className="ed-flex">
                           <LogInOutline className='mr-1' />
                           Terminar sessão
                        </li>
                     } />
                  </Dropdown.Item>

               </Dropdown.Menu>
            </Dropdown>
         </div>

         {/*  MODAL REACT-BOOTSTRAP */}
         <Modal show={showIdleModal} centered backdrop="static" keyboard={false}>
            <div className="p-4 position-relative">

               {/* CLOSE BUTTON */}
               <button
                  className="btn-close position-absolute"
                  style={{ right: "12px", top: "12px" }}
                  onClick={() => setShowIdleModal(false)}
               />

               {/* COUNTDOWN */}
               <div className="text-center" style={{ paddingTop: "10px" }}>
                  <h1 style={{
                     fontSize: "65px",
                     fontWeight: "800",
                     lineHeight: "1",
                     marginBottom: "20px"
                  }}>
                     {formatTime(secondsLeft)}
                  </h1>

                  {/* DESCRIPTION */}
                  <p className="grey-text" style={{ fontSize: "16px" }}>
                     A sua sessão será terminada automaticamente<br />
                     caso não haja atividade no sistema.
                  </p>
               </div>

            </div>
         </Modal>
      </>
   );
}

const ProfileBox = styled.div`  
    display:flex;
    align-items:center;

    .avatarimage{
        width:50px;
    }

   .ed-block{
      padding-left:10px; 
      color:var(--ed-dark);

      h1{
         margin:0px;
         font-size:16px;
      }

      span{
         font-size:13px;
         color:var(--ed-grey-text);
      }
   }
`;

export default UserModalMenu;
