import React, { useEffect, useState } from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button, Alert } from 'react-bootstrap'
import { Delete, InfoOutlined, Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import ClearInputs from '../../../General/components/ClearInputs';
import { CourseDataOptions, AcademicYearDataOptions, ClassroomsDataOptions, CicleDataOptions, GetInstituteCode, AcademiclevelDataOptions, SubjectMultipleSelect, GetAcademiclevel_byclass, GetClassroom_byclass, GetPeriod_byclass, GetClasstitle_byclass, GetCourse_byclass, StudentsArray } from '../../../General/components/InstituteData';
import { RichTextEditor } from '../../../General/components/RichTextEditor';
import CRValue from '../../../General/components/CRValue';
import { toast } from 'react-hot-toast';
import { Update } from '@material-ui/icons';
import { MultiSelect } from 'react-multi-select-component';
import RefreshList from '../../../General/components/RefreshList';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import styled from 'styled-components';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import { Link } from 'react-router-dom';
import { Avatar } from '@mui/material';
import SelectSearch from 'react-select-search';
import StudentDetailsMenu from '../elements/StudentDetailsMenu';
import { Checkbox, FormControlLabel, FormControl, Radio, RadioGroup, getStepButtonUtilityClass } from '@mui/material';
import DeleteModal from '../elements/DeleteModal';
import GetPersonData from '../../../General/components/GetPersonData';
import CreateTemporaryEduallAccountAlert from './CreateTemporaryEduallAccountAlert';

function NewStudentUserAccountModal(props) {
  const [show, setShow] = useState(false);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});
  const [Select, setSelected] = useState([]);
  const [UserWithStudentDataAccess, SetUserWithStudentDataAccess] = useState([]);
  const Periods = ["Manhã", "Tarde", "Noturno"];
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [Founded, SetFounded] = useState(null);
  const [Data, setData] = useState({});
  const [studentCode, setStudentCode] = useState(null);
  const [showBox, SetshowBox] = useState(false);
  const [Loaded, setLoaded] = useState(false);
  const [FoundedUserAccount, SetFoundedUserAccount] = useState(false);
  const [FormMessage, setFormMessage] = useState(null);
  const [MessageType, setMessageType] = useState(1);
  const [StudentCreateAccount, setStudentCreateAccount] = useState(0);
  const [UserCode, setUserCode] = useState(null);
  const [UserData, setUserData] = useState({ name: "", gender: "" });
  const SEARCHURL = Hoot() + 'eduallcheckexistentuseraccountemail/'




  function hideMessage() {
    setFormMessage(null);
    setShow(false);
  }


  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200);
  }

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };

  const INPUTS = {
    user_account_student: studentCode,
    user_account_user: UserCode,
  };

  const FORMURL = [
    Hoot() + "edualluserstudentaccountregister/post",
    props.get ? props.get : '',
    Hoot() + "" + props.code ? props.code : '',

  ];

  const GET_DATA = async () => {
    if (props.update) {
      try {
        setStudentCode(props.code);
        INPUTS.user_account_student = props.code;
        setField("user_account_student", props.code);

        const response = await axios.get(FORMURL[1]);
        console.clear();
        console.log(response.data);

        if (response.data.length > 0) {
          SetUserWithStudentDataAccess(response.data);
        } else {
          toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
        }
      } catch (error) {
        console.clear();
        console.log(error.response.data);
        toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
      }
    }

  }

  const setField = (field, value) => {
    setForm({
      ...form,
      [field]: value
    })

    if (!!errors[field]) {
      setErrors({
        ...errors,
        [field]: null
      });
    }
  }


  const validateForm = () => {
    const { user_account_student } = form;
    const NewErrors = {};
    setRegisterStatus(0);
    if (INPUTS.user_account_student === "" || INPUTS.user_account_student === " ") {
      if (!user_account_student || user_account_student === '') NewErrors.user_account_student = 'Selecione um estudante valido';
    } else { if (!user_account_student) { setField("user_account_student", INPUTS.user_account_student); } }
    return NewErrors;
  }


  const FormSubmit = (e) => {
    e.preventDefault();
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os  campos !");
      setRegisterStatus(1);
    } else {
      const SUBMIT_INPUTS = {
        student_account_usercode: UserCode,
        student_account_studentcode: INPUTS.user_account_student
      };

      console.clear();
      console.log(SUBMIT_INPUTS);
      try {
        axios.post(FORMURL[0], SUBMIT_INPUTS).then(() => {
          toast.success("Conta atribuida com sucesso !");
          setForm({});
          ClearInputs();
          RefreshList(`.el-refresh-list`);
          setRegisterStatus(2);
        }).catch((error) => {
          if (error.response.data.msg) { toast.error(error.response.data.msg); } else { toast.error("Lamentamos mas não foi  possivel executar esta ação !"); }
          setRegisterStatus(1);
          console.clear();
          console.log(error.response.data);
        });
      } catch (error) {
        if (error.response.data.msg) { toast.error(error.response.data.msg); } else { toast.error("Lamentamos mas não foi  possivel executar esta ação !"); }
        setRegisterStatus(1);
        console.clear();
        console.log(error.response.data);
      }
    }
  };


  const GetStudentCode = async (e) => {
    setStudentCode(e);
    const data = await GetPersonData(e, "student");
    setUserData(data);
  }





  const handleInput = (e) => {
    switch (e.target.id) {
      case "user_account_student":
        INPUTS.user_account_student = e.target.value
        setField("user_account_student", e.target.value);
        break;
      case "user_account_email":
        setField("user_account_email", e.target.value);
        CheckCurentUserAccount(e.target.value);
        break;
      default:
    }
  }




  async function CheckCurentUserAccount(email) {
    setFormMessage(null);
    setStudentCreateAccount(0)
    setUserCode(null);
    try {
      const response = await axios.get(SEARCHURL + email);
      console.clear();
      console.log(response.data);
      if (response.data.length >= 1) {
        console.clear();
        console.log(response.data[0])
        setUserCode(response.data[0].ed_user_account_id)
        setData(response.data[0]);
        setLoaded(true);
        SetFoundedUserAccount(true);
        setFormMessage("founded");
      } else {
        setLoaded(true);
        SetFoundedUserAccount(false);
        setData({});
        setUserCode(null);
      }
    } catch (error) {
      console.clear();
      console.log(error.response);
      setLoaded(true);
      setData({});
      setUserCode(null);
      SetFoundedUserAccount(false);
    }
  }



  return (
    <div>
      <div onClick={handleShow}>
        {
          props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon />  Atribuir contas</button>
        }
      </div>
      <Modal className={showBox ? ModalAnimationShow() : ModalAnimationClose()} centered size='lg' dialogAs={DraggableModal} show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>{props.title ? props.title : 'Atribuir '} contas</h5>
            </div>
          </Modal.Title>
        </Modal.Header>
        <div className='scrollLimit'>
                  <Form onSubmit={FormSubmit}>
<Modal.Body  >
            {!props.update ?
              <Form.Group className="mb-3">
                <div className="ed-space">
                  <div>
                    <button className="el-refresh-list d-none" onClick={() => GET_DATA()}>refresh</button>
                    <Form.Label>Nome do estudante <span className='text-danger ml-2'>*</span></Form.Label>
                  </div>
                  <div className='ed-flex'>
                    {studentCode !== null ? <StudentDetailsMenu student_id={studentCode} toggle_btn={<div className='btn-pm-info'><InfoOutlined /></div>} /> : <></>}
                  </div>
                </div>
                <div className={`select-search-item  ${errors.feepayment_student_code ? 'error' : ''}`}>
                  <SelectSearch onChange={(e) => GetStudentCode(e)} value={studentCode} options={StudentsArray()[0]} search={true}
                    placeholder="Selecione um aluno" />
                </div>
                <small className="text-danger">{errors.feepayment_student_code}</small>
              </Form.Group>
              : <></>
            }
            <div className="block mt-4">
              <Form.Label>Email de usuário </Form.Label><br />
              <div className="mb-2">
                <small className="text-main">O email do usuário devera estar associado a uma conta eduall para que o mesmo possa ter acesso as informações do estudante.</small>
              </div>
              <Form.Control placeholder='Ex: info@eduall.ao' type="text" onChange={handleInput} className={!!errors.user_account_email && 'is-invalid'} value={form.user_account_email}
                isInvalid={!!errors.user_account_email} id="user_account_email" />
              <Form.Control.Feedback type='invalid'>{errors.user_account_email}</Form.Control.Feedback>
            </div>

            <Box>
              <div className="box-components">
                <div className="form-message">
                  {
                    FormMessage !== null ? <div className="mt-2">
                      <Alert dismissible variant={(FoundedUserAccount === false) ? "danger" : 'primary'} onClose={() => hideMessage()}>
                        <>
                          {FoundedUserAccount === false ?
                            <>
                              <h5 className='text-danger'>{FormMessage}</h5>
                            </> :
                            <>
                              {
                                FoundedUserAccount === false ?
                                  <>

                                  </>

                                  :
                                  <h5>
                                    <>
                                      <div className="ed-flex">
                                        <Avatar sx={{ width: 70, height: 70 }} src={Hoot() + Data.ed_user_account_picture} />
                                        <div className="ed-block ml-2">
                                          <h2 className="name">{Data.ed_user_account_name} </h2>
                                          <div><small>{Data.ed_user_account_email}</small></div>
                                        </div>
                                      </div>
                                      <div className="mt-2 ed-block">
                                        <div>
                                          <small className="text-main">
                                            Ao clicar em salvar, permitirá a este usuário visualizar as informações do estudante (notas, reclamações, pagamentos, turmas, exames, etc.).
                                          </small>

                                        </div>
                                      </div>
                                    </>
                                  </h5>
                              }
                            </>
                          }
                        </>
                      </Alert>
                    </div> : ''
                  }
                </div>
                <div className="mt-2">
                  <CreateTemporaryEduallAccountAlert
                    email={form.user_account_email}
                    userName={UserData.name}
                    country="ao"
                    gender={UserData.gender}
                  />
                </div>
              </div>
            </Box>
            {props.update ?
              <List>
                {UserWithStudentDataAccess.map((item, index) => {
                  return (
                    <li key={index + 1}>
                      <div className="ed-space">
                        <div className="ed-flex">
                          <Avatar className='df' src={Hoot() + item.ed_user_account_picture} alt={item.ed_user_account_name} />
                          <div className="ml-2"><span>{item.ed_user_account_name}</span></div>
                        </div>
                        <div className="ed-flex">
                          <DeleteModal title="o acesso aos dados de estudante" url={Hoot() + "edualluserstudentsaccountdelete/delete/" + item.ed_user_std_account_id} toggle_btn={
                            <div className="btn-circle  bg-danger ml-2 text-light">
                              <Delete />
                            </div>} />
                        </div>
                      </div>
                    </li>)
                })}
              </List>
              : <></>
            }
          </Modal.Body>
          <Modal.Footer>
            <div className="ed-space">
              <div className="ed-flex"></div>
              <div className="ed-flex">
                <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                {props.update ? (Founded === false ? <div></div> :
                  <SaveButton icon={<Save />} title={'Salvar'} status={RegisterStatus} />) :
                  <SaveButton icon={<Save />} title={'Salvar'} status={RegisterStatus} />}
              </div>
            </div>
          </Modal.Footer>
                  </Form>
        </div> 
      </Modal>
    </div>
  )
}


const Box = styled.div`

.box-components{
    display:flex;
    width:100%; 
    flex-direction:column;

     h2{
        font-size:16px;
     }

     h5{
          font-size:16px !important;
          margin:0px !important;
     }

     small{
        font-size:14px !important;
     }

     .alert{
          padding:10px 20px;
          margin:0px !important;
     }
}
 
`;


const List = styled.div`
   padding:10px 0px;

     li{
        display:flex;
        align-items:center;
        margin: 10px 0px;
        border:1px solid var(--ed-white-smoke);
        background:var(--ed-background-color);
        padding:10px;
        border-radius:6px;
        list-style:none;
     }
`;
export default NewStudentUserAccountModal