import React from 'react'
import styled from 'styled-components'

function AuthError() {
  return (
    <Container className='error-auth'>
        <h1>Erro ao tentar autenticar a sua conta , tente novamente !</h1>
    </Container>
  )
}

const Container = styled.div`
   width:100%;
   height:100vh;
   padding:20px;
   display:flex;
   align-items:center;
   background:var(--ed-purple);
   justify-content:center;

      h1{
          font-size:40px;
          color:var(--ed-white);
          text-align:center;
          font-weight:bolder;
      }
`;

export default AuthError
