import React, { useEffect, useState } from 'react';
import { GetStudentNameAndPicture, GetSubject, GetTime } from '../../../General/components/InstituteData';
import { Check, Close, InfoOutlined, Refresh } from '@mui/icons-material';
import { Badge } from 'react-bootstrap';
import TableGrid from '../../../General/components/TableGrid';
import { BsTypeH1 } from 'react-icons/bs';
import ReplaceWord from '../../../General/components/ReplaceWord';




const StatusType = [
    <div className="ml-2"><Badge bg={'success'}><Check/> Presente</Badge></div>,
    <div className="ml-2"><Badge bg={'danger'}> <Close/> Ausente</Badge></div>,
    <div className="ml-2"><Badge bg={'warning'}><InfoOutlined/> Atrasado</Badge></div>
 ];
 
 const columns = [ 
   { 
     field: 'index', 
     headerName: 'Nº',
     resizable: true, 
     width:90, 
   },
   {
     field: 'status',
     width:180,
     headerName: 'Status',
     resizable: true,
      cellRenderer:(props)=>{ 
       return <div className='ed-flex'>{StatusType[props.data.status]}</div>
     }
   }, 
   {
    field: 'timing',
    width:180,
    headerName: 'Horário',
    resizable: true, 
    }, 
    {
      field: 'subject',
      width:180,
      headerName:ReplaceWord("Disciplina"),
      resizable: true, 
      }, 
    {
     field: 'date',
     width:180,
     headerName: 'Data',
    },    
 ]; 

function PP_attedance(props){
  const [data, setData] = useState([]); 
  const [Loaded, setLoaded] = useState(false);
     
   function loadData(){ 
    setLoaded(false);
    let students = [];    
      props.data.Data.map((item, index)=>{
        let hs = item.ed_timing_hour_start; 
        let he = item.ed_timing_hour_end; 
        let ms = item.ed_timing_minute_start; 
        let me = item.ed_timing_minute_end;  
        students.push({ 
              index:index+1,
              id:item.ed_student_attd_id,
              student:item.ed_student_attd_student_code,  
              timing:hs+'H'+ ' : '+  ms+' MN' + ' | ' +  he+' H'+ ' : '+  me+' MN',
              date:item.ed_student_attd_date,
              status:item.ed_student_attd_status,
              subject:item.ed_subject_title,
              action:true, 
            });
      });
     setData(students);
    setLoaded(true); 
 }
 
  useEffect(()=>{
   loadData();
  }, []);

  return (
    <div>
      {Loaded  ?
      <> 
       <div className="d-none"> {data.map((item, index)=>{return( <>{index}</>) })} </div>
       <TableGrid TableHead={columns} TableBody={data} NoButtons  TableHeight={500} 
       TableTitle="Presença escolar do aluno na turma"  
       /> 
      </> 
        :
        <TableGrid TableHead={columns} NoButtons TableBody={[]}  TableHeight={500} 
        TableTitle="Presença escolar do aluno na turma" /> 
      }
    </div>
  )
}

export default PP_attedance
