import React from 'react'
import styled from "styled-components"
import Comp_LatestPost from './components/About/Comp_LatestPost';
import Comp_focus from './components/About/Comp_focus';
import Comp_overview from './components/About/Comp_overview';
import Comp_offices from './components/About/Comp_offices';
import Comp_LatestJobs from './components/About/Comp_LatestJobs';
import Comp_employees from './components/About/Comp_employees';
import ReduceTextLength from '../../../General/components/ReduceTextLength';
import { Avatar, AvatarGroup } from '@mui/material';

import {AiOutlineHeart, AiOutlineLike, AiOutlineDislike} from "react-icons/ai";
import {LuMail} from "react-icons/lu";
import { Swiper, SwiperSlide } from 'swiper/react'; 
import Masonry from "react-responsive-masonry"
import { Link } from 'react-router-dom';
import {BsTelephone, BsChatDots, BsLinkedin} from "react-icons/bs";
import {TfiWorld} from "react-icons/tfi";
import { BsInfoCircle } from "react-icons/bs";
import ImageLazyLoading from '../../../General/components/ImageLazyLoading';

const Images = [
    "https://s2-g1.glbimg.com/zLfFeoQU4FFCjgssc7ndz0KJB-Q=/0x0:5184x3456/984x0/smart/filters:strip_icc()/i.s3.glbimg.com/v1/AUTH_59edd422c0c84a879bd37670ae4f538a/internal_photos/bs/2021/b/H/woqlKySeG6BsfeEK1gfg/2021-09-09t184655z-2067533641-rc2imp9qsldc-rtrmadp-3-health-coronavirus-microsoft.jpg",
    "https://cdn-dynmedia-1.microsoft.com/is/image/microsoftcorp/Highlight-Slim-Multi-Canvas-M365-Anthem-Attract-Image-Create:VP2-859x540",
    "https://cdn-dynmedia-1.microsoft.com/is/image/microsoftcorp/RF-Microsoft-M365-Sizzle_tbmnl_en-us?scl=1",
    "https://images-eds-ssl.xboxlive.com/image?url=qitYpaWI4rA4q5qG2AjZyppiNRjTCv4tLDfYlg.uMBcee9EnGDGvvZ7eC.FuUUY7hq4TusVuO3dyKUCR571hKsBfJ.ZC.AB8Aul4ywH9VaoGNIXWZLVd.Z4K6c5tAN1B&h=1080",
    "https://intelequia.com/DesktopModules/Blog/BlogImage.ashx?TabId=276&ModuleId=1172&Blog=14&Post=3645&w=991&h=714&c=1&key=03b7260f-7e3a-4201-a010-6051b31aa9fd",
    "https://www.livemint.com/lm-img/img/2023/12/04/600x338/Microsoft-Altman-0_1700835685121_1701675936323.jpg",
    "https://pplware.sapo.pt/wp-content/uploads/2017/11/microsoft.jpg",
    "https://cdn-dynmedia-1.microsoft.com/is/image/microsoftcorp/M365-across-devices-business-Highlight-2120x1190:VP2-859x540",
    "https://cdn-dynmedia-1.microsoft.com/is/image/microsoftcorp/gldn-smb-m365sfb-CP02?wid=834&hei=470&fit=crop",
];


const Founders  = [
    {
     name:"Bill Gates", 
     charge:"CEO", 
     account:null, 
     picture:"https://upload.wikimedia.org/wikipedia/commons/thumb/f/fc/Bill_Gates_-_2023_-_P062021-967902_%28cropped%29.jpg/800px-Bill_Gates_-_2023_-_P062021-967902_%28cropped%29.jpg"
    },
    {
     name:"Paul Allen", 
     charge:"CTO", 
     account:"", 
     picture:"https://hips.hearstapps.com/hmg-prod/images/gettyimages-457922246.jpg"
    }
];

function AboutComp({data}) {
  return (
    <Container className="box-area">
        <div className="box">
        <main>
            <div className="dets">
                <div className="icon"><BsInfoCircle /></div>
                <p>{data.ed_page_description}</p>
            </div>
            <hr />
            <div className="dets lt">
                 <h2 className="subtitle">Fotos</h2>
                 <ul className="gallery">
                    {Images.map((item)=>(<li><ImageLazyLoading source={item} height={80} /> </li>))}
                 </ul>
                 <Link to="#" className='text-main'>ver mais</Link>
            </div>
            <hr />
            <div className="dets lt">
                <h2 className="subtitle">Porque trabalhar connosco</h2>
                <div className="video-box">
                <iframe  height="200" src="https://www.youtube.com/embed/yLbcWloJ_tI?si=IGFDzmU47GgnQKwY&amp;controls=0" title="YouTube video player" frameborder="0"
                   allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>
                </div>
            </div>
        </main>
        </div>
        <div className="ct-area">
        <div className="main-content">
            <Comp_LatestPost />
            <Comp_focus />
            <Comp_overview />
            <Comp_offices />
            <Comp_LatestJobs />
            <Comp_employees />
        </div>
        </div>
        <div className="sidebar-content box">
                <main> 
                <div className="principal mb-4">
                    <Avatar src={"https://cionews.co.in/wp-content/uploads/2023/11/Article-Main-Image-71.png"} sx={{width:60,height:60}} />
                    <div className="ed-block">
                        <h5>Satya Nadella</h5>
                        <small className='dt' >Diretor geral</small>
                    </div>
                </div>   
                <h2 className="subtitle mb-2">Sede empresarial</h2>
                <Link to="#">
                    <div className="headquarter">
                        <div className="image">
                            <ImageLazyLoading  source="https://www.theconstructionindex.co.uk/assets/news_articles/2016/10/1476949979_20oct16-microsoft-germany-turner1.jpg"  height={350} />
                        </div>
                        <h5>Gensler and RKD Architects create digital waterfall for Microsoft Ireland's HQ</h5>
                    </div>
                  </Link>
                  <div className="founders mt-4">
                      <h2 className="subtitle mb-2">Fundadores ({Founders.length})</h2>
                      <ul>
                         {Founders.map((item, index)=>(
                            <li key={index}>
                               <div className="ed-flex">
                                 <Avatar  variant="rounded" className='df' sx={{width:90,height:110}} src={item.picture}  />
                                  <div className="ed-block ml-2">
                                      <h5>{item.name}</h5>
                                     <div> <span className="charge">{item.charge}</span></div>
                                     <div> <Link><button className="btn btn-bordered text-main btn-small">Visitar perfil</button></Link></div>
                                  </div>
                               </div>
                            </li>
                         ))}
                      </ul>
                  </div>
                </main>
           </div>
     </Container>
  )
}


const Container = styled.div`

.founders{

    ul{
        padding:0px;
        margin:10px 0px;

        li{
           list-style:none;
           margin:10px 0px;
           padding:10px;
           border:1px solid var(--ed-silver-light);
           border-radius:10px;

              h5{
                font-size:16px;
                font-weight:600;
                margin:4px 0px;
              }

              span{
                 font-size:15px;
                 color:var(--ed-grey-text);
              }

              a{
                color:var(--ed-purple);
                margin:3px 0px;
                font-size:15px;
              }
        }
    }
}

.headquarter{
    border-radius:6px;
    border:1px solid var(--ed-silver-light);
    display:block;
    background:var(--ed-white);
    box-shadow:vat(--ed-shadow-df); 
    overflow:hidden;

    .image{
        height:350px;

        img{
            height:350px;
            object-fit:cover;
        }
    }

     h5{
         padding:10px;
         font-size:16px;
         color:var(--ed-dark);
     }
  }

  
  .principal{
    padding:10px;
    border:1px solid var(--ed-silver-light);
    border-radius:10px;
}



   .dets.lt{
      text-align:left !important;
      align-items:flex-start;

      .video-box{
          height:200px;
          width:100%;
          background:var(--ed-dark);
          margin:10px 0px;

             iframe{
                  width:100%;
             }
      }


      ul{
         align-items:flex-start;
         display:flex;
         flex-wrap:wrap;
         padding:0px;
         margin:10px 0px;
 

          li{
              width:86.5px;
              height:80px;
              margin:5px;
              list-style:none !important;


                img{
                     width:100%;
                     height:100%;
                     object-fit:cover;
                }
          }
      }
   }
`;


export default AboutComp