  function getTableMetaFromDom(contentEl, excludedColumns = []) {
    const preview = contentEl?.querySelector(".table-preview");
    if (!preview) throw new Error("Tabela de preview não encontrada dentro do conteúdo.");
  
    const shouldExclude = (name) =>
      excludedColumns.some((ex) => ex.toLowerCase() === String(name || "").toLowerCase());
  
    const ths = Array.from(preview.querySelectorAll("thead tr th"));
    const allHeaders = ths.map((th) => th.textContent.trim());
  
    const headerIndices = allHeaders
      .map((h, i) => ({ label: h, index: i }))
      .filter((obj) => !shouldExclude(obj.label));
  
    const rows = Array.from(preview.querySelectorAll("tbody tr")).map((tr) =>
      Array.from(tr.children).map((td) => td.textContent.trim())
    );
  
    return { preview, allHeaders, headerIndices, rows };
  }
  
  // Normalização simples de género (tolerante a acentos/maiúsculas/abreviações)
  function deburrLower(s) {
    return String(s || "")
      .normalize("NFD")
      .replace(/\p{Diacritic}/gu, "")
      .toLowerCase()
      .trim();
  }
  function classifyGender(s) {
    const v = deburrLower(s);
    // Positivos masculinos
    const isM =
      v === "m" ||
      v.includes("masculin") ||
      v.includes("male") ||
      v.includes("homem") ||
      v === "masc";
    // Positivos femininos
    const isF =
      v === "f" ||
      v.includes("feminin") ||
      v.includes("female") ||
      v.includes("mulher") ||
      v === "fem";
    return isM ? "M" : isF ? "F" : null;
  }
  
  // Mapeia classes Bootstrap comuns para cores RGB
  function bootstrapClassToRgb(cls) {
    // Fundo (fillColor) e texto (textColor) — prioridades simples
    const fills = {
      "table-primary": [204, 229, 255],
      "table-secondary": [226, 230, 234],
      "table-success": [209, 231, 221],
      "table-danger": [248, 215, 218],
      "table-warning": [255, 243, 205],
      "table-info": [207, 226, 243],
      "table-light": [248, 249, 250],
      "table-dark": [52, 58, 64],
    };
    const texts = {
      "text-primary": [13, 110, 253],
      "text-secondary": [108, 117, 125],
      "text-success": [25, 135, 84],
      "text-danger": [220, 53, 69],
      "text-warning": [255, 193, 7],
      "text-info": [13, 202, 240],
      "text-light": [248, 249, 250],
      "text-dark": [33, 37, 41],
      "text-white": [255, 255, 255],
    };
    return { fill: fills[cls], text: texts[cls] };
  }
  
  // Extrai dados/estilos de uma tabela HTML passada por id
  function parseHeaderHtmlTable(tableEl) {
    const headRows = Array.from(tableEl.querySelectorAll("thead tr"));
    const bodyRows = Array.from(tableEl.querySelectorAll("tbody tr"));
    const head = headRows.map((tr) =>
      Array.from(tr.children).map((td) => {
        const txt = td.textContent.trim();
        const classes = Array.from(td.classList || []);
        // Aplica apenas a primeira classe de cor que encontrar
        let fillColor, textColor;
        for (const c of classes) {
          const m = bootstrapClassToRgb(c);
          if (!fillColor && m.fill) fillColor = m.fill;
          if (!textColor && m.text) textColor = m.text;
        }
        return { content: txt, styles: { fillColor, textColor } };
      })
    );
    const body = bodyRows.map((tr) =>
      Array.from(tr.children).map((td) => {
        const txt = td.textContent.trim();
        const classes = Array.from(td.classList || []);
        let fillColor, textColor;
        for (const c of classes) {
          const m = bootstrapClassToRgb(c);
          if (!fillColor && m.fill) fillColor = m.fill;
          if (!textColor && m.text) textColor = m.text;
        }
        return { content: txt, styles: { fillColor, textColor } };
      })
    );
    return { head, body };
  }
  
  /** =================== HEADER DRAW =================== */
  /**
   * Desenha o bloco de cabeçalho (logo + textos institucionais + título + campos)
   * - Campos com layout automático (wrap): mede e quebra linha quando necessário.
   * - Aceita genderSummary para desenhar "Estudantes por género : M(12) F(44)" com cores.
   * - Se headerMiniTable for passado, desenha a mini-tabela em vez dos campos customizados.
   */
  function drawHeaderBlock({
    doc,
    pageWidth,
    loadedImg,
    institute,
    customTitle,
    titleTopMargin = 0,
    customFields = [],
    layoutMode = "auto", // "auto" (wrap) | number (fixo por linha)
    genderSummary = null, // {label, maleCount, femaleCount}
    headerMiniTable = null, // {head, body} (da parseHeaderHtmlTable)
    headFontSize = 10,
  }) {
    let y = 10;
  
    // Logo
    if (loadedImg) {
      const img = loadedImg;
      const scale = Math.min(200 / img.width, 120 / img.height);
      const logoWpx = img.width * scale;
      const logoHpx = img.height * scale;
      const logoWmm = logoWpx * 0.264583;
      const logoHmm = logoHpx * 0.264583;
      doc.addImage(img, "PNG", (pageWidth - logoWmm) / 2, y, logoWmm, logoHmm);
      y += logoHmm + 4;
    }
  
    // Textos institucionais
    doc.setFontSize(10);
    doc.setTextColor("#000");
    if (institute?.ed_institute_name) {
      doc.setFont(undefined, "bolditalic");
      doc.text(institute.ed_institute_name, pageWidth / 2, y, { align: "center" });
      y += 6;
    }
    if (institute?.ed_institute_docheader) {
      doc.setFont(undefined, "bolditalic");
      doc.text(institute.ed_institute_docheader, pageWidth / 2, y, { align: "center" });
      y += 6;
    }
  
    // Margem extra antes do título
    y += Number(titleTopMargin || 0);
  
    // Título
    if (customTitle) {
      doc.setFont(undefined, "bold");
      doc.setFontSize(13);
      doc.text(customTitle, pageWidth / 2, y, { align: "center" });
      doc.setLineWidth(0.3);
      const w = doc.getTextWidth(customTitle);
      doc.line((pageWidth - w) / 2, y + 1.2, (pageWidth + w) / 2, y + 1.2);
      y += 8;
    }
  
    // Se foi fornecida mini-tabela de header, desenha-a aqui e devolve y final
    if (headerMiniTable) {
      const startY = y;
      autoTable(doc, {
        head: headerMiniTable.head,
        body: headerMiniTable.body,
        startY,
        margin: { left: 10, right: 10 },
        styles: { fontSize: headFontSize, cellPadding: 2 },
        theme: "grid",
        headStyles: { fillColor: [248, 249, 250], textColor: [0, 0, 0], fontStyle: "bold" },
        bodyStyles: { textColor: [0, 0, 0] },
      });
      // devolve o Y após a tabela
      return doc.lastAutoTable.finalY + 4;
    }
  
    // Campos customizados com layout automático (wrap)
    const marginX = 10;
    const usableWidth = pageWidth - marginX * 2;
    const gapX = 4; // mm
    const gapY = 4; // mm
    const lineHeight = 5.5; // mm
    const labelStyle = () => doc.setFont(undefined, "bold");
    const valueStyle = () => doc.setFont(undefined, "normal");
  
    doc.setFontSize(headFontSize);
  
    // Constrói lista de "itens" a desenhar: [ ...customFields, genderSummary? ]
    const items = [...(customFields || [])];
  
    if (genderSummary && Number.isFinite(genderSummary.maleCount) && Number.isFinite(genderSummary.femaleCount)) {
      items.push({ __gender: true, label: genderSummary.label || "Estudantes por género" });
    }
  
    // Medição e fluxo (wrap)
    let x = marginX;
    if (items && items.length) {
      for (const f of items) {
        // Calcula largura necessária
        let wBlock = 0;
        let draw = null;
  
        if (f.__gender) {
          // "Estudantes por género : M(12)  F(44)"
          const label = `${f.label}: `;
          labelStyle();
          const wLabel = doc.getTextWidth(label);
          valueStyle();
          const mText = `M(${genderSummary.maleCount})`;
          const fText = `F(${genderSummary.femaleCount})`;
          const space = "   ";
          // mede M e F (cores não afetam largura)
          const wM = doc.getTextWidth(mText);
          const wSpace = doc.getTextWidth(space);
          const wF = doc.getTextWidth(fText);
          wBlock = wLabel + wM + wSpace + wF;
  
          draw = () => {
            // Label
            labelStyle();
            doc.setTextColor(0, 0, 0);
            doc.text(label, x, y);
            let curX = x + wLabel;
  
            // M(…)
            valueStyle();
            doc.setTextColor(22, 163, 74); // verde
            doc.text(mText, curX, y);
            curX += wM + wSpace;
  
            // F(…)
            doc.setTextColor(220, 38, 38); // vermelho
            doc.text(fText, curX - wSpace, y); // inclui o espaço entre M e F
  
            // reset
            doc.setTextColor(0, 0, 0);
          };
        } else {
          const labelRaw = f.label ? String(f.label).trim() : "";
          const labelText = labelRaw.endsWith(":") ? labelRaw : `${labelRaw}:`;
          const valueString = f.value != null ? String(f.value) : "";
  
          labelStyle();
          const wLabel = doc.getTextWidth(labelText) + 1.5;
          valueStyle();
          const wVal = doc.getTextWidth(valueString);
          wBlock = wLabel + wVal;
  
          draw = () => {
            // Label
            labelStyle();
            doc.setTextColor(0, 0, 0);
            doc.text(labelText, x, y);
  
            // Value
            valueStyle();
            if (f.valueColor) {
              const [r, g, b] = hexToRgb(f.valueColor);
              doc.setTextColor(r, g, b);
            }
            doc.text(valueString, x + wLabel, y);
            doc.setTextColor(0, 0, 0);
          };
        }
  
        // Se não couber na linha, quebra
        if (x !== marginX && x + wBlock > marginX + usableWidth) {
          // nova linha
          x = marginX;
          y += lineHeight + gapY;
        }
  
        // Desenha e avança X
        draw();
        x += wBlock + gapX;
      }
  
      // espaço adicional após blocos
      y += lineHeight + 2;
    }
  
    return y;
  }
  
