  /** =================== API PÚBLICA =================== */
  export async function ExportDataToTablesToPdf({
    fileName = "export.pdf",
    headerId,
    footerId,
    contentId,
    rotation = "portrait",
    customHeader, // título
    excludedColumns = [],
    gender = false, // habilita UI de género
    headerTableId = null, // <- NOVO: id de uma mini-tabela HTML a usar no header
  }) {
    let modalUnmount = null;
    const mountNode = document.createElement("div");
    document.body.appendChild(mountNode);
  
    const unmount = () => {
      ReactDOM.unmountComponentAtNode(mountNode);
      mountNode.remove();
      modalUnmount = null;
    };
    modalUnmount = unmount;
    const handleHide = () => modalUnmount?.();
  
    // Pre-render do modal (placeholder)
    ReactDOM.render(
      <PdfOptionsModal
        show
        onHide={handleHide}
        onExportDefault={() => {}}
        onExportWithOptions={() => {}}
        detectedColumns={[]}
        defaultFileName={fileName}
        genderEnabled={gender}
        headerTableProvided={Boolean(headerTableId)}
      />,
      mountNode
    );
  
    try {
      const contentEl = document.getElementById(contentId);
      if (!contentEl) {
        toast.error("Elemento de conteúdo não encontrado.");
        handleHide();
        return;
      }
  
      const tableMeta = getTableMetaFromDom(contentEl, excludedColumns);
      const defaultDetectedCols = tableMeta.headerIndices;
  
      const exportDefault = async () => {
        await generatePdf({
          rotation,
          headerId,
          footerId,
          customHeader,
          contentId,
          fileName,
          useOptions: null,
          excludedColumns,
          headerTableId,
        });
        handleHide();
      };
  
      const exportWithOptions = async (opts) => {
        await generatePdf({
          rotation: opts.orientation,
          headerId,
          footerId,
          customHeader,
          contentId,
          fileName: opts.fileName,
          useOptions: opts,
          excludedColumns,
          headerTableId,
        });
        handleHide();
      };
  
      ReactDOM.render(
        <PdfOptionsModal
          show
          onHide={handleHide}
          onExportDefault={exportDefault}
          onExportWithOptions={exportWithOptions}
          detectedColumns={defaultDetectedCols}
          defaultFileName={fileName}
          genderEnabled={gender}
          headerTableProvided={Boolean(headerTableId)}
        />,
        mountNode
      );
    } catch (err) {
      console.error(err);
      toast.error(err.message || "Erro ao carregar dados.");
      handleHide();
    }
  }
  
  /** =================== EXPORT REAL =================== */
  async function generatePdf({
    rotation,
    headerId,
    footerId,
    customHeader,
    contentId,
    fileName,
    useOptions, // null => defaults
    excludedColumns = [],
    headerTableId = null,
  }) {
    const contentElement = document.getElementById(contentId);
    if (!contentElement) throw new Error("Elemento de conteúdo não encontrado.");
    const headerElement = document.getElementById(headerId);
    const footerElement = document.getElementById(footerId);
    const headerTableEl = headerTableId ? document.getElementById(headerTableId) : null;
  
    const { headerIndices, rows } = getTableMetaFromDom(contentElement, excludedColumns);
  
    const institute = await fetchInstituteData();
  
    // LOGO
    let headerImg = null;
    try {
      if (useOptions?.logo?.mode === "upload" && useOptions?.logo?.fileDataUrl) {
        headerImg = await loadImageFromUrl(useOptions.logo.fileDataUrl);
      } else if (useOptions?.logo?.mode === "url" && useOptions?.logo?.url) {
        headerImg = await loadImageFromUrl(useOptions.logo.url);
      } else {
        const logoUrlFromCloud = await fetchDefaultLogoUrl();
        headerImg = await loadImageFromUrl(logoUrlFromCloud);
      }
    } catch {
      headerImg = null;
    }
  
    // DOC
    const doc = new jsPDF({ orientation: rotation || "portrait", unit: "mm", format: "a4" });
    const pageWidth = doc.internal.pageSize.getWidth();
    const pageHeight = doc.internal.pageSize.getHeight();
  
    // Font
    const fontFamily = useOptions?.fontFamily || DEFAULT_FONT;
    try {
      doc.setFont(fontFamily);
    } catch {
      doc.setFont(DEFAULT_FONT);
    }
    const fontSize = useOptions?.fontSize || 9;
  
    // Cores do header da tabela principal
    const headBgColor = useOptions ? hexToRgb(useOptions.headerBg || DEFAULT_HEADER_BG) : hexToRgb(DEFAULT_HEADER_BG);
    const headTextColor = useOptions ? hexToRgb(useOptions.headerText || DEFAULT_HEADER_TEXT) : hexToRgb(DEFAULT_HEADER_TEXT);
  
    // Colunas selecionadas/ordenadas
    let selectedColumns = headerIndices;
    if (useOptions?.selectedCols?.length) {
      const validMap = new Map(headerIndices.map((x) => [x.label, x.index]));
      selectedColumns = useOptions.selectedCols
        .filter((c) => validMap.has(c.label))
        .map((c) => ({ label: c.label, index: validMap.get(c.label) }));
    }
  
    // Detectar coluna de género se não for indicada (procura headers “género”, “genero”, “gender”, “sexo”)
    let genderColumnLabel = useOptions?.genderColumn || "";
    if (!genderColumnLabel) {
      const guess = headerIndices.find((c) => /gen[eé]ro|gender|sexo/i.test(c.label));
      if (guess) genderColumnLabel = guess.label;
    }
  
    // Contagem por género (se ativa e sem headerTable)
    let genderSummary = null;
    if (useOptions?.genderActive && genderColumnLabel && !headerTableEl) {
      const colIdx =
        selectedColumns.find((c) => c.label === genderColumnLabel)?.index ??
        headerIndices.find((c) => c.label === genderColumnLabel)?.index;
  
      if (typeof colIdx === "number") {
        let maleCount = 0,
          femaleCount = 0;
  
        // Usa matches custom (maleValue/femaleValue) + fallback classifier
        const maleKey = deburrLower(useOptions.maleValue || "Masculino");
        const femaleKey = deburrLower(useOptions.femaleValue || "Feminino");
  
        rows.forEach((r) => {
          const raw = String(r[colIdx] ?? "");
          const norm = deburrLower(raw);
          if (norm.includes(maleKey) || classifyGender(raw) === "M") maleCount++;
          else if (norm.includes(femaleKey) || classifyGender(raw) === "F") femaleCount++;
        });
  
        genderSummary = { label: "Estudantes por género", maleCount, femaleCount };
      }
    }
  
    // Campos custom + (resumo de género vai como último)
    const customFields = [...(useOptions?.customFields || [])];
  
    // Header mini-tabela (se existir)
    let headerMiniTable = null;
    if (headerTableEl) {
      headerMiniTable = parseHeaderHtmlTable(headerTableEl);
    }
  
    // Cabeçalhos da tabela principal
    const commonHeaderStyle = {
      halign: "left",
      fontStyle: "bold",
      fillColor: headBgColor,
      textColor: headTextColor,
      lineColor: [0, 0, 0],
      lineWidth: 0.1,
    };
    const headRow = [
      ...(useOptions?.includeCounter ? [{ content: "Nº", styles: { ...commonHeaderStyle, halign: "center" } }] : []),
      ...selectedColumns.map((c) => ({ content: c.label, styles: commonHeaderStyle })),
    ];
    const head = [headRow];
  
    // Corpo
    const body = rows.map((r, idx) => {
      const cells = selectedColumns.map((c) => ({
        content: r[c.index] ?? "",
        styles: { textColor: "#000", lineColor: [0, 0, 0], lineWidth: 0.1 },
      }));
      if (useOptions?.includeCounter) {
        return [
          { content: String(idx + 1), styles: { textColor: "#000", lineColor: [0, 0, 0], lineWidth: 0.1, halign: "right" } },
          ...cells,
        ];
      }
      return cells;
    });
  
    // Texto extra (headerId) — centralizado antes da tabela
    const headerExtraText = headerElement?.innerText?.trim() || "";
    const titleTopMargin = useOptions?.titleTopMargin || 0;
    const repeatHeaderAllPages = useOptions?.repeatHeaderAllPages !== false;
    const layoutMode = useOptions?.layoutMode || "auto"; // "auto" | "2" | "3"
  
    // Primeiro desenho de header para definir startY:
    const firstY = drawHeaderBlock({
      doc,
      pageWidth,
      loadedImg: headerImg,
      institute,
      customTitle: customHeader,
      titleTopMargin,
      customFields,
      layoutMode,
      genderSummary, // vai como último, já dentro da função
      headerMiniTable,
      headFontSize: Math.max(9, fontSize), // ligeiro boost para header
    });
  
    let startY = firstY + 4;
    if (headerExtraText && !headerMiniTable) {
      doc.setFont(undefined, "normal");
      doc.setFontSize(9);
      const lines = doc.splitTextToSize(headerExtraText, pageWidth - 20);
      lines.forEach((ln) => {
        doc.text(ln, pageWidth / 2, startY, { align: "center" });
        startY += 4;
      });
      startY += 2;
    }
  
    autoTable(doc, {
      head,
      body,
      margin: { top: 10 },
      styles: { fontSize, cellPadding: 2, font: fontFamily },
      startY,
      theme: "grid",
      didDrawPage: (data) => {
        const currentPage = doc.internal.getNumberOfPages();
  
        // Redesenha header em todas as páginas
        const y = drawHeaderBlock({
          doc,
          pageWidth,
          loadedImg: headerImg,
          institute,
          customTitle: customHeader,
          titleTopMargin,
          customFields: repeatHeaderAllPages && !headerMiniTable ? customFields : [],
          layoutMode,
          genderSummary: repeatHeaderAllPages && !headerMiniTable ? genderSummary : null,
          headerMiniTable: repeatHeaderAllPages ? headerMiniTable : null,
          headFontSize: Math.max(9, fontSize),
        });
  
        // Texto extra (somente na primeira página se repeatHeaderAllPages=false e sem mini-tabela)
        let yAfter = y + 4;
        if (headerExtraText && (repeatHeaderAllPages || currentPage === 1) && !headerMiniTable) {
          doc.setFont(undefined, "normal");
          doc.setFontSize(9);
          const lines = doc.splitTextToSize(headerExtraText, pageWidth - 20);
          lines.forEach((ln) => {
            doc.text(ln, pageWidth / 2, yAfter, { align: "center" });
            yAfter += 4;
          });
          yAfter += 2;
        }
  
        // Ajusta top
        data.settings.margin.top = (headerMiniTable && currentPage > 1 && !repeatHeaderAllPages)
          ? y + 4 // nas páginas seguintes, sem repetir mini-tabela
          : yAfter + 4;
  
        drawFooterBlock(
          doc,
          pageWidth,
          pageHeight,
          footerElement?.innerText || "",
          currentPage,
          doc.internal.getNumberOfPages()
        );
      },
    });
  
    const stamp = moment().format("D [de] MMMM [de] YYYY, [às] HH:mm");
    const safeName = ensurePdfExtension((fileName || "export") + "_" + getTimestamp());
    doc.save(safeName);
  
    toast.success(`PDF exportado com sucesso! (${stamp})`);
  }
  
  
