import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import StudentList from '../components/Table/StudentList';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import BallotOutlinedIcon from '@mui/icons-material/BallotOutlined';
import Radio from '@mui/material/Radio';
import RadioGroup from '@mui/material/RadioGroup';
import FormControlLabel from '@mui/material/FormControlLabel';
import FormControl from '@mui/material/FormControl';
import PdClassList from './Pedagogy/PdClassList';

function Students() {
  const [value, setValue] = useState('geral');

  const handleChange = (event) => {
    setValue(event.target.value);
  };

  
  useEffect(() => {
    if (value === 'geral') {
      document.title = 'Lista dos estudantes';
    } else {
      document.title = 'Estudantes por turma';
    }
  }, [value]);

  return (
    <div>
      <div className="eduall-table">
        <div className="ed-flex mb-4">
          <FormControl>
            <RadioGroup
              aria-labelledby="students-view-selector"
              name="students-view"
              value={value}
              onChange={handleChange}
              row
            >
              <FormControlLabel
                value="geral"
                control={<Radio color="primary" />}
                label="Estudantes geral"
              />
              <FormControlLabel
                value="porturma"
                control={<Radio color="primary" />}
                label="Estudantes por turma"
              />
            </RadioGroup>
          </FormControl>
        </div>

        <aside>
          {value === "geral" ? (
            <section>
              <div className="ed-space">
                <div></div>
                <div>
                  <Link className="btn btn-icon bg-green-light" to="/StudentsGrid">
                    <BallotOutlinedIcon />
                  </Link>
                  <Link className="btn bg-main ml-2" to="/NewStudentBase">
                    <AddCircleOutlineIcon /> Registrar novo estudante
                  </Link>
                </div>
              </div>
              <StudentList />
            </section>
          ) : (
            <aside>
              <PdClassList />
            </aside>
          )}
        </aside>
      </div>
    </div>
  );
}

export default Students;
