import React, { useState, useEffect } from 'react'
import axios from 'axios'
import { Refresh } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import TableGrid from '../../../General/components/TableGrid';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import { Avatar } from '@mui/material';
import { Badge, Table } from 'react-bootstrap';
import CalcAgeByBirthday from '../../../General/components/CalcAgeByBirthday';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import { GetAcademiclevel_byclass, GetAcademicYear_byclass, GetClassroom_byclass, GetClasstitle_byclass, GetCourse_byclass, GetPeriod_byclass } from '../../../General/components/InstituteData';
import ReplaceWord from '../../../General/components/ReplaceWord';


const TABLEURL = Hoot() + "eduallgetstudentsbyclass/";
//const TABLEURL = Hoot()+"eduallstudentsapi/get/";


const columns = [
  {
    field: 'index',
    headerName: 'Nº de matrícula',
    resizable: true,
    cellRenderer: (props) => {
      return <SwitchFromPages link={`studentinfo/${props.data.id}`}
        menu='3' menu_item='17' toggle_btn={<span className='text-dark'>{props.data.code}</span>} />
    }
  },
  {
    field: 'name',
    headerName: 'Nome do aluno',
    resizable: true,
    width: 400,
    cellRenderer: (props) => {
      return <SwitchFromPages link={`studentinfo/${props.data.id}`}
        menu='3' menu_item='17' toggle_btn={
          <div className='ed-flex'>
            <Avatar className='df' alt={props.data.name} src={props.data.picture !== "" ? Hoot() + props.data.picture : ""} />
            <span className='ml-2'>{props.data.name}</span>
          </div>
        } />
    }
  },
  {
    field: 'gender',
    headerName: 'Genero',
    resizable: true,
    width: 140,
    cellRenderer: (props) => {
      return props.data.gender === "female" ?
        <Badge bg='danger'>Feminino</Badge>
        : <Badge bg='info'>Masculino</Badge>
    }
  },
  {
    field: 'age',
    headerName: 'Idade',
    sortable: false,
    resizable: true,
    width: 100,
  },
  {
    field: 'status',
    headerName: 'Status',
    resizable: true,
    width: 120,
    cellRenderer: (props) => {
      return Math.floor(props.data.status) === 1 ?
        <Badge bg='info'><div className="text-dark">Activo</div></Badge> :
        <Badge bg='danger'><div className="text-dark">Inactivo</div></Badge>
    }
  },
];


function PdStudentsByClass(props) {
  const ClassCode = props.ClassId ? props.ClassId : 0;
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  // 🆕 Estados para contagem por género
  const [maleCount, setMaleCount] = useState(0);
  const [femaleCount, setFemaleCount] = useState(0);

  async function loadData() {
    try {
      setLoaded(false);
      setLoadStatus(0);
      const response = await axios.get(TABLEURL + ClassCode);
      const rows = [];
      let males = 0;
      let females = 0;

      response.data.map((item, index) => {
        // Contar género 🆕
        if (item.ed_student_gender === "male") males++;
        if (item.ed_student_gender === "female") females++;

        rows.push({
          index: index + 1,
          id: item.ed_student_id,
          code: item.ed_student_code,
          picture: item.ed_student_picture,
          name: item.ed_student_name,
          age: CalcAgeByBirthday(item.ed_student_birthday) + " anos",
          class: item.ed_student_class, 
          cicle: '',
          status: item.ed_student_status,
          gender: item.ed_student_gender,
          action: '',
        });
      });

      // Atualizar contadores 🆕
      setMaleCount(males);
      setFemaleCount(females);

      setData(rows);
      setTimeout(() => setLoaded(true), 200);
      setLoadStatus(2);
    } catch (error) {
      setLoadStatus(1);
    }
  }

  useEffect(() => {
    loadData();
  }, [ClassCode]);

 
  if (load) {
    return (
      <div id="ed-custom-table-data"> 
        {ClassCode !== null && ClassCode * 1 > 0 ?
          <div className="boxitem boxItem boxContentSM">
            <Table responsive bordered id='class_student_details'>
              <tbody>
                <tr> 
                  <td>
                    <div className="ed-flex">
                      <div><strong>Turma : </strong></div>
                      <div className='ml-2'><GetClasstitle_byclass ID={ClassCode} /></div>
                    </div>
                  </td>
                  <td>
                    <div className="ed-flex">
                      <div><strong>{ReplaceWord("Classe")} : </strong></div>
                      <div className='ml-2'><GetAcademiclevel_byclass ID={ClassCode} /></div>
                    </div>
                  </td> 
                  <td>
                    <div className="ed-flex">
                      <div><strong>Nº de estudantes  : </strong></div>
                      <div className="ml-2">
                        <span className="text-green">M ({maleCount})</span> {' --- '}{' '}  
                        <span className='text-red ml-2'>F ({femaleCount})</span> {' '} {' '} 
                        <span className='text-dark ml-2'>Total =  ({femaleCount + maleCount})</span>  
                      </div>
                    </div>
                  </td> 
                </tr>  
                <tr>
                  <td>
                    <div className="ed-flex">
                      <div><strong>Período : </strong></div>
                      <div className='ml-2'><GetPeriod_byclass ID={ClassCode} /></div>
                    </div>
                  </td>
                  <td>
                    <div className="ed-flex">
                      <div><strong>Ano letivo : </strong></div>
                      <div className='ml-2'><GetAcademicYear_byclass ID={ClassCode} /></div>
                    </div>
                  </td>
                  <td>
                    <div className="ed-flex">
                      <div><strong>Curso : </strong></div>
                      <div className='ml-2'><GetCourse_byclass ID={ClassCode} /></div>
                    </div>
                  </td>
                </tr> 
              </tbody>
            </Table>
          </div>
          : <></>
        } 

        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista dos estudantes por turma'
          TableBtn={
            <div className='ed-flex'>
              <button
                id='ed-custom-table-data-btn'
                onClick={() =>
                  ExportDataToTablesToPdf({
                    fileName: "Lista de Estudantes por turma",
                    headerId: null,
                    contentId: "ed-custom-table-data",
                    footerId: null,
                    rotation: "landscape",
                    buttonId: "ed-custom-table-data-btn",
                    customHeader: "Lista de Estudantes por turma",
                    gender:false,
                    headerTableId:"class_student_details",
                    excludedColumns: ["Ação"]
                  })
                }
                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'>
                <PiFilePdfDuotone />
              </button> 
              <button
                className='btn-icon btn btn-export-data ml-2'
                onClick={() => ExportDataForTablesExcel("Estudantes por turma", ["Ação"])}>
                <PiMicrosoftExcelLogoDuotone />
              </button>
              <RefreshButton action={loadData} status={LoadStatus} />
            </div>
          }
        />
      </div>
    )
  } else {
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista dos estudantes por turma'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    )
  }
}

export default PdStudentsByClass
