import React, {useEffect, useState} from 'react'
import Table from './Table';
import { Delete, Edit, Refresh } from '@mui/icons-material'; 
import axios from 'axios'  
import DeleteModal from '../elements/DeleteModal'; 
import { Link } from 'react-router-dom';
import Hoot from '../../../General/components/Hoot';
import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import NewSchoolsOfProvenanceModal from '../modal/NewSchoolsOfProvenanceModal';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';

const TABLEURL = Hoot()+"eduallschoolsofprovenance/get/";



const columns = [ 
  { field: 'index', headerName: 'Nº', width: 90 },
  {
    field: 'title',
    headerName: 'Nome da escola',
    width:200,
    editable: true,
  },
  {
    field: 'country',
    headerName: 'País',
    width:200,
    editable: true,
  },
  {
    field: 'address',
    headerName: 'Endereço',
    width:200,
    editable: true,
  },
  {
    field: 'email',
    headerName: 'Email',
    width:200,
    editable: true,
  }, 
  {
    field: 'action',
    headerName: 'Ação', 
    width: 150, 
    sortable:false,
     resizable: true, cellRenderer:(props) => { 
      return <div className="ed-flex">   
      <NewSchoolsOfProvenanceModal  title='Atualizar ' update='true' 
         get={Hoot()+`eduallgetsingleschoolofprovenance/get/${props.data.id}`}  
         url={Hoot()+`eduallschoolofprovenanceupdate/update/${props.data.id}`} 
          toggle_btn={
           <button className="btn-circle btn-edit-timing bg-success text-light">
              <Edit/>
            </button> 
          }
        />
      <DeleteModal title='esta escola de proveniência' url={Hoot()+`eduallschoolofprovenancedelete/delete/${props.data.id}`} 
       message='Turma deletada com sucesso' toggle_btn={
        <button  className="btn-circle bg-danger ml-2 text-light">
           <Delete/>
        </button>
       }/> 
    </div>; 
    }
  }  
];

function SchoolsOfProvenanceTable() { 
    const [data, setData] = useState([]);  
    const [load, setLoaded] = useState(false);
    const [LoadStatus, setLoadStatus] = useState(null);

    async function loadData(){
       try {
        setLoadStatus(0);
        setLoaded(false);
         const response = await axios.get(TABLEURL); 
         const rows = []; 
         const rows1 = []; 
         response.data.map((item, index)=>{ 
           rows.push({
             id:item.ed_schools_of_provenance_id,
             index:index+1,  
             title:item.ed_schools_of_provenance_name, 
             country:item.ed_schools_of_provenance_country,
             address:item.ed_schools_of_provenance_address, 
             email:item.ed_schools_of_provenance_email, 
             action:'',  
          }) 
         }); 
         setData(rows); 
         setTimeout(() => {
           setLoaded(true);
         }, 200);
         setLoadStatus(2);
       } catch (error) {
        setLoadStatus(1);
       }
    };
    
    useEffect(()=>{ 
        loadData();  
    },[]);
   
   
  
    if(load){
        return (
        <div id="ed-custom-table-data" >
          <TableGrid
              TableHead={columns}
              TableBody={data} 
              TableTitle="Lista das escolas de proveniência"
              TableBtn={
                <div className='ed-flex' >
                  <button id='ed-custom-table-data-btn'
                    onClick={() =>
                      ExportDataToTablesToPdf({
                        fileName: "Lista das escolas de proveniência ",
                        headerId: null,
                        contentId: "ed-custom-table-data",
                        footerId: null,
                        rotation: "portrait",
                        buttonId: "ed-custom-table-data-btn",
                        customHeader: "Lista das escolas de proveniência ",
                        excludedColumns: ["Ação"]
                      })
                    }
                    className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
                  </button>
                <button className='btn-icon btn btn-export-data ml-2' 
                   onClick={()=>ExportDataForTablesExcel("escolas de proveniência ", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
                </button>
               <RefreshButton action={loadData} status={LoadStatus} />
           </div>}
          />
      </div>
      )
    }else{
      return (
        <div>
          <div className="d-none">*</div>
          <TableGrid
              TableHead={columns}
              TableBody={[]} 
              TableTitle="Lista das escolas de proveniência"
              TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
          />
      </div>
      )
    }
   
}

export default SchoolsOfProvenanceTable