import React, { useState } from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap'
import { Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import { toast } from 'react-hot-toast';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import { Update } from '@material-ui/icons';
import { GetInstituteCode } from '../../../General/components/InstituteData';
import RefreshList from '../../../General/components/RefreshList';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';

function NewFacultyModal(props) {
  const [show, setShow] = useState(false);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [Founded, SetFounded] = useState(null);

  const [showBox, SetshowBox] = useState(false);
  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200);
  }

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };


  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});


  const FORMURL = [
    Hoot() + "eduallregisterfaculty/post/",
    props.get ? props.get : '',
    props.url ? props.url : ''
  ];


  const INPUTS = {
    title: CRValue("#title"),
  };



  const GET_DATA = async () => {
    if (props.update) {
      try {
        const response = await axios.get(FORMURL[1]);
        if (response.data.length > 0) {
          document.querySelector("#title").value = response.data[0].ed_faculty_title;
          INPUTS.title = response.data[0].ed_faculty_title;
        } else {
          toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
        }
      } catch (error) {
        toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
      }
    }
  }
  const setField = (field, value) => {
    setForm({
      ...form,
      [field]: value
    })

    if (!!errors[field]) {
      setErrors({
        ...errors,
        [field]: null
      });
    }
  }


  const validateForm = () => {
    const { title } = form;
    const NewErrors = {};
    setRegisterStatus(0);
    if (!title || title === '') NewErrors.title = 'Faculdade  invalida !';
    return NewErrors;
  }


  const FormSubmit = (e) => {
    console.log(INPUTS);
    e.preventDefault();
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os  campos");
      setRegisterStatus(1);
    } else {
      const SUBMIT_INPUTS = { faculty_title: INPUTS.title };

      if (!props.update) {
        try {
          axios.post(FORMURL[0], SUBMIT_INPUTS).then(() => {
            toast.success("Faculdade registrada com sucesso !");
            setForm({});
            ClearInputs();
            RefreshList(`.el-refresh-list`)
            setRegisterStatus(2);
          }).catch((error) => {

            const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
            toast.error(msg);
            setRegisterStatus(1);
          });
        } catch (error) {
                      
            const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
            toast.error(msg);
          setRegisterStatus(1);
        }
      } else {
        try {
          axios.put(FORMURL[2], SUBMIT_INPUTS).then(() => {
              toast.success("Faculdade atualizada com sucesso !");
              setForm({});
              ClearInputs();
              RefreshList(`.el-refresh-list`)
              setRegisterStatus(2);
              setTimeout(() => {
                handleClose();
              }, 1000);
            }).catch((error) => { 
            const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
            toast.error(msg);
              setRegisterStatus(1);
            });
        } catch (error) { 
          const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
          toast.error(msg);
          setRegisterStatus(1);
        }
      }
    }
  };


  const handleInput = (e) => {
    switch (e.target.id) {
      case "title":
        setField("title", e.target.value);
        INPUTS.title = e.target.value;
        break;
    }
  }


  return (
    <div>
      <div>
        <div onClick={handleShow}>
          {
            props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon /> Registrar Faculdade</button>
          }
        </div>
        <Modal size='lg' dialogAs={DraggableModal} centered className={showBox ? ModalAnimationShow() : ModalAnimationClose()} show={show} onHide={handleClose}>
          <Modal.Header closeButton>
            <Modal.Title>
              <div className="ed-wrap align-center">
                <UserOptionDropDown />
                <h5>{props.title ? props.title : 'Registrar '} Faculdade</h5>
              </div>
            </Modal.Title>
          </Modal.Header>
          <Form onSubmit={FormSubmit}>
            <Modal.Body className='scrollLimit'>
              <Form.Group className="mb-3"  >
                <Form.Label>Nome da faculdade<span className="text-danger ml-2">*</span> </Form.Label>
                <Form.Control type="text" onChange={handleInput} className={!!errors.title && 'is-invalid'} value={form.title}
                  isInvalid={!!errors.title} id="title" />
                <Form.Control.Feedback type='invalid'>{errors.title}</Form.Control.Feedback>
              </Form.Group>
            </Modal.Body>
            <Modal.Footer>
              <div className="ed-space">
                <div className="ed-flex"></div>
                <div className="ed-flex">
                  <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                  {props.update ? (Founded === false ? <div></div> :
                    <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
                    <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />}
                </div>
              </div>
            </Modal.Footer>
          </Form>
        </Modal>
      </div>
    </div>
  )
}

export default NewFacultyModal