import React, { useEffect, useState } from 'react'
import { AiOutlineHeart, AiFillHeart } from 'react-icons/ai'
import Hoot from '../../General/components/Hoot';
import axios from 'axios';
import { toast } from 'react-hot-toast';

function FollowPageButton(props){
  const [Follow, SetFollow] = useState(0);

  const DATAURL =  [
      Hoot()+"eduallstartfollowinginstitute/post/",
      Hoot()+"eduallcheckiffollowinginstitute/get/",
  ];

  const CheckIfFollowing = async(code, type)=>{
      if(type === 1){
        try {
          const [response] = await Promise.all([
            axios.get(DATAURL[1]+code),  
          ]); 
          if(response.data.length >= 1){
            SetFollow(true);
          }else{
            SetFollow(false);
          }
        } catch (error) {
          SetFollow(null);
        }
      }
  }


  
  const StartFollowing = async(code, type)=>{
    if(type === 1){
      try {
        axios.post(DATAURL[0], {CODE:code}).then(()=>{   
          SetFollow(1);
        }).catch((error)=>{
          toast.error("Lamentamos mas não foi  possivel executar esta ação"); 
          SetFollow(false);
          console.clear();
          console.log(error);
        });  
      } catch (error) {
        SetFollow(null);
      }
    }else{
      alert("error");
    }
}
  useEffect(()=>{
    CheckIfFollowing(props.CODE, props.TYPE);
  },[props]);


  return (
    <div>
       {props.SHOW ?
        <>
        {
        <div className={Follow === 0 ? "d-none" : "" }>
          {Follow === null ? <></> : <>{Follow !== 1 ? <>{Follow === true ? <><button className="btn btn-sm bg-main text-light"><AiFillHeart /> Seguindo</button></>  : 
           <button onClick={()=>StartFollowing(props.CODE, props.TYPE)} className={props.WHITE ? "btn btn-sm bg-white btn-sm text-main" : "btn btn-sm btn-bordered text-main"}>
          <AiOutlineHeart /> Seguir</button>}</>  :  <button className="btn btn-sm bg-main text-light"><AiFillHeart /> Seguindo</button>   } </> } 
        </div>
       }
        </>
        :
       <>
       <div className={Follow === 0 ? "d-none" : "" }>
          {Follow === null ? <></> : <>{Follow !== 1 ? <>{Follow === true ? <></>  :  <button onClick={()=>StartFollowing(props.CODE, props.TYPE)} 
          className={props.WHITE ? "btn bg-white btn-sm text-main" : "btn  btn-bordered text-main"}>
          <AiOutlineHeart /> Seguir</button>}</>  : <></>   } </> }
          {Follow === null ? <></> : <>{Follow === 1 ? <button className="btn bg-main btn-sm text-light"><AiFillHeart /> Seguindo</button>  :  <></> } </> }
        </div>
       </>
       }
    </div>
  )
}

export default FollowPageButton