import jsPDF from "jspdf";
import moment from "moment";
import autoTable from "jspdf-autotable";
import "moment/locale/pt-br";
import { toast } from "react-toastify";

const dataFormatada = moment().locale("pt-br").format("D [de] MMMM [de] YYYY, [às] HH:mm");

async function ExportTableAsImage(tableId, buttonId, topText = "") {
  const button = document.getElementById(buttonId);
  if (!button) {
    toast.error("Botão não encontrado!");
    return;
  }

  const originalButtonHTML = button.innerHTML;
  try {
    // Ativa loader do Bootstrap no botão (spinner)
    button.innerHTML = `<span class="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span> A processar...`;
    button.disabled = true;

    const table = document.getElementById(tableId);
    if (!table) throw new Error("Tabela não encontrada!");

    const doc = new jsPDF("l", "pt", "a4");
    doc.setFont("helvetica");
    doc.setFontSize(13);

    function cleanRow(row) {
      return row.filter(cell => {
        if (typeof cell === "string") return cell.trim() !== "";
        if (typeof cell === "object" && cell.content) return cell.content.trim() !== "";
        return true;
      });
    }

    const finalRows = [];
    const spans = [];
    const rows = Array.from(table.rows);

    for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
      const row = rows[rowIndex];
      const cells = Array.from(row.cells);
      const finalRow = [];
      let colIndex = 0;

      cells.forEach((cell) => {
        while (spans.some((s) => s.row > rowIndex && s.col === colIndex)) {
          finalRow.push("");
          colIndex++;
        }

        const cellContent = cell.innerText.trim();
        if (cellContent === "") {
          colIndex += parseInt(cell.getAttribute("colspan") || "1");
          return;
        }

        const colSpan = parseInt(cell.getAttribute("colspan") || "1");
        const rowSpan = parseInt(cell.getAttribute("rowspan") || "1");

        finalRow.push({
          content: cellContent,
          colSpan,
          rowSpan,
        });

        if (rowSpan > 1) {
          for (let i = 1; i < rowSpan; i++) {
            spans.push({ row: rowIndex + i, col: colIndex });
          }
        }

        for (let i = 1; i < colSpan; i++) {
          finalRow.push("");
        }

        colIndex += colSpan;
      });

      const cleanedRow = cleanRow(finalRow);
      if (cleanedRow.length > 0) finalRows.push(cleanedRow);
    }

    const thead = table.querySelector("thead");
    const headRowsCount = thead ? thead.rows.length : 1;
    const headRows = finalRows.slice(0, headRowsCount);
    const bodyRows = finalRows.slice(headRowsCount);

    autoTable(doc, {
      head: headRows,
      body: bodyRows,
      startY: 40,
      theme: "grid",
      styles: {
        font: "helvetica",
        fontSize: 13,
        cellPadding: 5,
        valign: "middle",
        halign: "center",
        lineWidth: 0.8,
        lineColor: "#000000",
      },
      headStyles: {
        fillColor: "#6051ff",
        textColor: "#ffffff",
        fontStyle: "bold",
        halign: "center",
        valign: "middle",
      },
      columnStyles: {
        0: { halign: "left" },
      },
      didParseCell: (data) => {
        if (data.row.section === "body" && data.column.index === 0) {
          data.cell.styles.halign = "left";
        }
      },
    });

    const finalY = doc.lastAutoTable.finalY || 40;
    const pageWidth = doc.internal.pageSize.getWidth();

    if (topText.trim()) {
      doc.setTextColor("#000000");
      doc.setFontSize(13);
      doc.setFont("helvetica", "normal");
      const topTextWidth = doc.getTextWidth(topText);
      const topTextX = (pageWidth - topTextWidth) / 2;
      const topTextY = finalY + 20;
      doc.text(topText, topTextX, topTextY);

      // Underline topText
      doc.setDrawColor("#000000");
      doc.setLineWidth(0.8);
      doc.line(topTextX, topTextY + 2, topTextX + topTextWidth, topTextY + 2);
    }

    const linkText = "www.about.eduall.ao";
    doc.setTextColor("#6051ff");
    doc.setFontSize(13);
    doc.setFont("helvetica", "bold");
    const textWidth = doc.getTextWidth(linkText);
    const x = (pageWidth - textWidth) / 2;
    const y = finalY + 50; // ajusta para ficar abaixo do topText

    doc.textWithLink(linkText, x, y, { url: "https://www.about.eduall.ao" });
    doc.setDrawColor("#6051ff");
    doc.setLineWidth(0.8);
    doc.line(x, y + 2, x + textWidth, y + 2);

    doc.save(`EDUALL ficheiros - ${dataFormatada}.pdf`);

    toast.success("PDF gerado com sucesso!");
  } catch (error) {
    toast.error(`Erro ao gerar PDF: ${error.message}`);
  } finally {
    button.innerHTML = originalButtonHTML;
    button.disabled = false;
  }
}

export default ExportTableAsImage;
