

import React, { useState } from 'react';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap';
import { Save, Update } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import { toast } from 'react-hot-toast';
import axios from 'axios';
import ClearInputs from '../../../General/components/ClearInputs';
import RefreshList from '../../../General/components/RefreshList';
import Hoot from '../../../General/components/Hoot';
import { GetTransportRoutesDataOptions } from '../../../General/components/InstituteData';

function NewBusStop(props) {
    const [show, setShow] = useState(false);
    const [registerStatus, setRegisterStatus] = useState(null);
    const [founded, setFounded] = useState(null);
    const [form, setForm] = useState({
        stop_name: "",
        stop_route: "",
        stop_estimate_of_arrival: "",
        stop_description: "",
    });
    const [errors, setErrors] = useState({});
    const [showBox, setShowBox] = useState(false);

    const handleClose = () => {
        setShowBox(false);
        setTimeout(() => {
            setShow(false);
        }, 1200);
    };

    const handleShow = () => {
        setShowBox(true);
        setShow(true);
        setTimeout(() => {
            GET_DATA();
        }, 1000);
    };


    const FORM_URLS = [
        Hoot() + "edualltransportstopsregister/post/",
        props.get ? props.get : '',
        props.url ? props.url : ''
    ];


    const GET_DATA = async () => {
        if (props.update) {
            try {
                const response = await axios.get(FORM_URLS[1]);
                if (response.data.length > 0) {
                    setForm({
                        stop_name: response.data[0].ed_transport_stop_name,
                        stop_route: response.data[0].ed_transport_stop_route,
                        stop_estimate_of_arrival: response.data[0].ed_transport_stop_estimate_of_arrival, 
                    });
                } else {
                    toast.error("Não foi possível encontrar as informações selecionadas!");
                }
            } catch (error) {
                toast.error("Erro ao carregar os dados da paragem!");
            }
        }
    };


    const handleInput = (e) => {
        setField(e.target.id, e.target.value);
    };

    const setField = (field, value) => {
        setForm({ ...form, [field]: value });

        if (!!errors[field]) {
            setErrors({ ...errors, [field]: null });
        }
    };


    const validateForm = () => {
        const { stop_name, stop_route, stop_estimate_of_arrival, stop_description } = form;
        const newErrors = {};
        setRegisterStatus(0);

        if (!stop_name || stop_name.trim() === '') newErrors.stop_name = 'Nome da paragem é obrigatório!';
        if (!stop_route || stop_route.trim() === '') newErrors.stop_route = 'Rota é obrigatória!';
        if (!stop_estimate_of_arrival || stop_estimate_of_arrival.trim() === '') newErrors.stop_estimate_of_arrival = 'Tempo de chegada é obrigatório!';

        return newErrors;
    };


    const FormSubmit = async (e) => {
        e.preventDefault();
        const formErrors = validateForm();

        if (Object.keys(formErrors).length > 0) {
            setErrors(formErrors);
            toast.error("Verifique todos os campos obrigatórios!");
            setRegisterStatus(1);
        } else {
            try {
                if (!props.update) {
                    await axios.post(FORM_URLS[0], form);
                    toast.success("Paragem registrada com sucesso!");
                } else {
                    await axios.put(FORM_URLS[2], form);
                    toast.success("Paragem atualizada com sucesso!");
                }

                setForm({ stop_name: "", stop_route: "", stop_estimate_of_arrival: "", stop_description: "" });
                ClearInputs();
                RefreshList(`.el-refresh-list`);
                setRegisterStatus(2); 
            } catch (error) {
                toast.error("Lamentamos, mas não foi possível executar esta ação!");
                setRegisterStatus(1);
                console.clear();
                console.log(error.response);
            }
        }
    };

    return (
        <div>
            <div onClick={handleShow}>
                {
                    props.toggle_btn ? props.toggle_btn :
                    <button className='btn btn-main bg-main ml-2' onClick={handleShow}>
                        <AddCircleOutlineIcon /> Registrar paragem
                    </button>
                }
            </div> 
            <Modal className={showBox ? ModalAnimationShow() : ModalAnimationClose()} centered dialogAs={DraggableModal} show={show} onHide={handleClose}>
                <Modal.Header closeButton>
                    <Modal.Title>
                        <div className="ed-wrap align-center">
                            <UserOptionDropDown />
                            <h5>{props.title ? props.title : 'Registrar '} Paragem</h5>
                        </div>
                    </Modal.Title>
                </Modal.Header>
                <Form onSubmit={FormSubmit}>
                    <Modal.Body className='scrollLimit'>
                        <Form.Group className="mb-3">
                            <Form.Label>Nome da Paragem<span className="text-danger ml-2">*</span></Form.Label>
                            <Form.Control type="text" required id="stop_name" value={form.stop_name} onChange={handleInput} isInvalid={!!errors.stop_name} />
                            <Form.Control.Feedback type='invalid'>{errors.stop_name}</Form.Control.Feedback>
                        </Form.Group>
                        <Form.Group className="mb-3">
                            <Form.Label>Rota<span className="text-danger ml-2">*</span></Form.Label>
                            <Form.Select required id="stop_route" value={form.stop_route} onChange={handleInput} isInvalid={!!errors.stop_route}>
                                 <GetTransportRoutesDataOptions />
                            </Form.Select>
                            <Form.Control.Feedback type='invalid'>{errors.stop_route}</Form.Control.Feedback>
                        </Form.Group>
                        <Form.Group className="mb-3">
                            <Form.Label>Tempo Estimado de Chegada<span className="text-danger ml-2">*</span></Form.Label>
                            <Form.Control type="text" required id="stop_estimate_of_arrival" value={form.stop_estimate_of_arrival} onChange={handleInput} isInvalid={!!errors.stop_estimate_of_arrival} />
                            <Form.Control.Feedback type='invalid'>{errors.stop_estimate_of_arrival}</Form.Control.Feedback>
                        </Form.Group>
                    </Modal.Body>
                    <Modal.Footer>
                        <Button className='bg-light text-dark' onClick={handleClose}>Cancelar</Button>
                        <SaveButton icon={props.update ? <Update /> : <Save />} title={props.title || 'Salvar'} status={registerStatus} />
                    </Modal.Footer>
                </Form>
            </Modal>
        </div>
    );
}

export default NewBusStop;
