

function ReplaceWord(word, lowercase) {
  let val =    localStorage.getItem("institutetype");
  if(val*1 >= 0){
  if(val*1 === 1){
    
    let output  =  word;
    let Words = [
      {options:["Classe", "Nivel académico"]},
      {options:["Classes", "Niveis académicos"]},
      {options:["Classes académicas", "Niveis académicos"]},
      {options:["Disciplina", "Cadeira"]}, 
      {options:["Disciplinas", "Cadeiras"]}, 
  ];

      for (let i = 0; i < Words.length; i++) {
           const options = Words[i].options;
           for (let o = 0; o < options.length; o++) {
               if(word.toLowerCase() === options[o].toLowerCase()){
                  if(o === 0){
                      output = options[1];
                  }else{
                    output = options[0];
                  }
               } 
           } 
      }    
    
   if(lowercase === true){return output.toLowerCase()}else{return output;} 

  } else{
    return word;
  }
 
  }else{
      return word;
  } 
}

export default ReplaceWord