import React, {useState, useEffect, forwardRef, useImperativeHandle} from 'react' 
import axios from 'axios'; 
import Hoot from '../../../General/components/Hoot';   
import SmallPassengersCard from './GridComponents/SmallPassengersCard';
const URL = Hoot()+"edualltransportpassengerget/get/";


const  SmallPassengersGrid = forwardRef((props, ref)=>{
    const [data, setData] = useState([]);
    const [FilterType, SetFilterType] = useState(1); 
    const [Loaded, SetLoaded] = useState(false);
    
 
    async function loadData(){
        try {
           const response = await axios.get(URL);
           setData(response.data);
        } catch (error) {
              console.clear();
              console.log(error);
        } 
    } 


    let filterValue = props.FilterByName ? props.FilterByName : '';
    let filterClassValue = props.FilterByClass ? props.FilterByClass : '';

    useImperativeHandle(ref, ()=>({
        ChangeFilter(e){
            SetFilterType(e);
        }
    }))
   

    useEffect(()=>{
        loadData(); 
        setTimeout(() => {
            SetLoaded(true);
        }, 1000);
    },[]);
    

    const FilterData = (data)=>{ 
        return data.filter((item)=>
          item.ed_student_name.toLowerCase().includes(filterValue) ||
          item.ed_student_code.toString().toLowerCase().includes(filterValue) ||
          item.ed_student_email.toLowerCase().includes(filterValue) 
       ); 
    }

  return (<><SmallPassengersCard GetData={props.GetData} data={FilterData(data)} /></>)
  
})
 
export default SmallPassengersGrid