import React, { useState, useEffect } from 'react'
import axios from 'axios'
import { Delete, Description, Edit, PreviewOutlined, Refresh } from '@mui/icons-material';
import Table from './Table';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal'; 
import TableGrid from '../../../General/components/TableGrid';
import { Link } from 'react-router-dom'; 
import RefreshButton from '../../../General/components/RefreshButton';
import NewBusStop from '../modal/NewBusStop';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';

const TABLEURL = Hoot() + "edualltransportstopsget/get/";


const columns = [
  {
    field: 'index',
    headerName: 'Nº',
    resizable: true,
    width: 80
  },   
  {
    field: 'stop_name',
    headerName: 'Paragem',
    sortable: false,
    resizable: true,
    width: 280,
  },

  {
    field: 'stop_arrival',
    headerName: 'Estivamativa de chegada',
    sortable: false,
    resizable: true,
    width: 220,
  }, 

  {
    field: 'stop_route',
    headerName: 'Rota',
    sortable: false,
    resizable: true,
    width: 230,
  }, 
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true,
    cellRenderer: (props) => {
      return <div className="ed-flex">
        <NewBusStop title='Atualizar ' update='true' get={Hoot()+`edualltransportsinglestopget/get/${props.data.id}`}
          url={Hoot()+`edualltransportstopupdate/update/${props.data.id}`}
          toggle_btn={
            <button className="btn-circle  bg-success text-light">
              <Edit />
            </button>
          }
        />
        <DeleteModal title='esta paragem' url={Hoot() + `edualltransportstopsdelete/delete/${props.data.id}`}
          message='Paragem deletada com sucesso' toggle_btn={
            <button className="btn-circle bg-danger ml-2 text-light">
              <Delete />
            </button>
          } />
      </div>;
    }
  }
]; 

function BusStopsTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);
 
  async function loadData() {
    try {
      setLoaded(false);
      setLoadStatus(0);
      const response = await axios.get(TABLEURL);
      const rows = [];
      response.data.map((item, index) => {
        rows.push({
           index: index + 1,
           id:item.ed_transport_stop_id,
           stop_name:item.ed_transport_stop_name,
           stop_route: item.ed_transport_route_name,
           stop_arrival: item.ed_transport_stop_estimate_of_arrival,  
        })
      });
      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoaded(true);
      setLoadStatus(1);
    }
  }

  useEffect(() => {
    loadData();
  }, []);



  if (load) {
    return (
      <div id="ed-custom-table-data" >
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista das paragens do transporte'
          TableBtn={
            <div className='ed-flex'>
                <button id='ed-custom-table-data-btn'
                    onClick={() =>
                        ExportDataToTablesToPdf({
                            fileName: "Lista das paragens do transporte",
                            headerId: null,
                            contentId:"ed-custom-table-data",
                            footerId: null,
                            rotation: "portrait",
                            buttonId: "ed-custom-table-data-btn",
                            customHeader: "Lista das paragens do transporte",
                            excludedColumns: ["Ação"]
                        })
                    }
                    className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
                </button>
                <button className='btn-icon btn btn-export-data ml-2'
                    onClick={() => ExportDataForTablesExcel("Lista das paragens do transporte", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
                </button>
                <RefreshButton action={loadData} status={LoadStatus} />
            </div>
        }
        />
      </div>
    )
  } else {
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista das paragens do transporte'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    )
  }
}

export default BusStopsTable; 
