import React, { useState, useEffect } from 'react';
import { EditorState, convertToRaw } from 'draft-js';
import { Editor } from 'react-draft-wysiwyg';
import draftToHtml from 'draftjs-to-html';
import htmlToDraft from 'html-to-draftjs';
import { convertToHTML } from 'draft-convert';
import DOMPurify from 'dompurify';

import "react-draft-wysiwyg/dist/react-draft-wysiwyg.css";


export function RichTextEditor(props){ 
  const [editorState, setEditorState] = useState(
    () => EditorState.createEmpty(),
  );
  const [convertedContent, setConvertedContent] = useState(null);

  useEffect(() => {
    let html = convertToHTML(editorState.getCurrentContent());
    setConvertedContent(html);
    if(props.description) props.description(JSON.stringify(html));
  }, [editorState]);

  function createMarkup(html) {
    return {
      __html: DOMPurify.sanitize(html)
    }
  }

 
    return (
      <div className='custom-editor'>
         <Editor
              editorState={editorState}
              onEditorStateChange={setEditorState}
              wrapperClassName="wrapper-class"
              editorClassName="editor-class"
              toolbarClassName="toolbar-class"
            />
              <div className="preview d-none"  dangerouslySetInnerHTML={createMarkup(convertedContent)}></div>

        <textarea  disabled  value={draftToHtml(convertToRaw(editorState.getCurrentContent()))} className="d-none" />
      </div>
    ); 




}