import React from 'react' 
import parse from 'html-react-parser';

function LessonDescriptionTab({data, filters}){
  return (
    <div>
       <h1 className="title">Sobre a Aula</h1>
       <div className="content">
           {parse(data)}
       </div>
    </div>
  )
}

export default LessonDescriptionTab