import ExcelJS from "exceljs";
import moment from "moment";
import "moment/locale/pt-br";
import { saveAs } from "file-saver";  
import toast from "react-hot-toast";

const ExportDataForTablesExcel = async (filename, ignoredHeaders = [], containerId = null) => {
  try { 
    let container;

    if (containerId) {
      container = document.getElementById(containerId);
      if (!container) return toast.error(`Container com id "${containerId}" não encontrado!`);
    } else {
      container = document.querySelector(".table-preview");
      if (!container) return toast.error("Tabela de preview não encontrada!");
    }

    const table = container.querySelector("table");
    if (!table) return toast.error("Nenhuma <table> encontrada dentro do container.");

    const workbook = new ExcelJS.Workbook();
    const worksheet = workbook.addWorksheet("Exportação");

    const rows = Array.from(table.rows);
    const mergeMap = new Map();
    const dataFormatada = moment().locale("pt-br").format("D [de] MMMM [de] YYYY, [às] HH:mm");

    let validColIndexes = [];

    rows.forEach((row, rowIndex) => {
      let colIndex = 1;

      Array.from(row.cells).forEach((cell, realIndex) => {
        while (mergeMap.has(`${rowIndex + 1},${colIndex}`)) colIndex++;

        const cellValue = cell.innerText.trim();

        if (rowIndex === 0) {
          if (!ignoredHeaders.includes(cellValue)) {
            validColIndexes.push(realIndex);

            const cellRef = worksheet.getCell(rowIndex + 1, colIndex);
            cellRef.value = cellValue;
            cellRef.alignment = { horizontal: "center", vertical: "middle" };
            cellRef.font = { name: "Poppins", bold: true, color: { argb: "FFFFFF" }, size: 14 };
            cellRef.fill = { type: "pattern", pattern: "solid", fgColor: { argb: "6051FF" } };
            worksheet.getRow(rowIndex + 1).height = 40;

            if (cell.colSpan > 1 || cell.rowSpan > 1) {
              const endRow = rowIndex + cell.rowSpan;
              const endCol = colIndex + cell.colSpan;
              worksheet.mergeCells(rowIndex + 1, colIndex, endRow, endCol - 1);
              for (let r = rowIndex + 1; r <= endRow; r++) {
                for (let c = colIndex; c < endCol; c++) {
                  mergeMap.set(`${r},${c}`, true);
                }
              }
            }

            colIndex++;
          }
        } else {
          if (!validColIndexes.includes(realIndex)) return;

          const cellRef = worksheet.getCell(rowIndex + 1, colIndex);
          cellRef.value = cellValue;
          cellRef.alignment = { horizontal: "center", vertical: "middle" };
          cellRef.font = { name: "Poppins", size: 12 };
          worksheet.getRow(rowIndex + 1).height = 40;

          // Detecta cores baseado em classes do span/div/strong
          let textColor = null;
          const children = Array.from(cell.querySelectorAll("span, div, strong"));
          children.forEach((child) => {
            if (child.classList.contains("text-danger") || child.classList.contains("bg-danger")) textColor = "FF0000";
            else if (child.classList.contains("text-success") || child.classList.contains("bg-success")) textColor = "28A745";
            else if (child.classList.contains("text-warning") || child.classList.contains("bg-warning")) textColor = "FFC107";
            else if (child.classList.contains("text-main")) textColor = "808080";
          });

          if (textColor) {
            cellRef.font = { ...cellRef.font, color: { argb: textColor } };
          }

          cellRef.fill = {
            type: "pattern",
            pattern: "solid",
            fgColor: { argb: rowIndex % 2 === 0 ? "F3F3F3" : "FFFFFF" },
          };

          if (cell.colSpan > 1 || cell.rowSpan > 1) {
            const endRow = rowIndex + cell.rowSpan;
            const endCol = colIndex + cell.colSpan;
            worksheet.mergeCells(rowIndex + 1, colIndex, endRow, endCol - 1);
            for (let r = rowIndex + 1; r <= endRow; r++) {
              for (let c = colIndex; c < endCol; c++) {
                mergeMap.set(`${r},${c}`, true);
              }
            }
          }

          colIndex++;
        }
      });
    });

    // Ajusta largura das colunas automaticamente
    worksheet.columns.forEach((column) => {
      let maxLength = 0;
      column.eachCell({ includeEmpty: true }, (cell) => {
        maxLength = Math.max(maxLength, cell.value ? cell.value.toString().length : 10);
      });
      column.width = maxLength + 5;
    });

    const buffer = await workbook.xlsx.writeBuffer();
    const blob = new Blob([buffer], {
      type: "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    });
    saveAs(blob, `eduall - ${filename} - ${dataFormatada}.xlsx`);
    toast.success("Excel exportado com sucesso!");
  } catch (err) {
    console.error(err);
    toast.error("Erro ao exportar para Excel.");
  }
};

export default ExportDataForTablesExcel;
