import React, { useEffect, useRef, useState } from 'react'
import { Check } from '@mui/icons-material'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button, Table } from 'react-bootstrap'
import { Save } from '@mui/icons-material';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import { Link, useParams } from "react-router-dom";
import ClearInputs from '../../../General/components/ClearInputs';
import {
    CourseDataOptions, AcademicYearDataOptions, ClassroomsDataOptions, CicleDataOptions, GetInstituteCode,
    AcademiclevelDataOptions, TitlesAndHeadersDataOptions, GetClasstitle_byclass, GetAcademiclevel_byclass, GetPeriod_byclass,
    GetAcademicYear_byclass, GetClassroom_byclass, GetCourse_byclass, GetServiceTitle, GetServiceCointText, GetserviceCoin
} from '../../../General/components/InstituteData';
import { toast } from 'react-hot-toast';
import { Print } from '@material-ui/icons';
import { useReactToPrint } from 'react-to-print';
import NotFounded from '../../../General/components/NotFounded';
import Loader from '../../../General/components/Loader';
import RandomCodeGenerator from '../../../General/components/RandomCodeGenerator';
import { UserAccountData } from '../../../General/components/UserAccountData';
import NumberToPrice from '../../../General/components/NumberToPrice';
import BackButton from '../elements/BackButton';
import CRValue from '../../../General/components/CRValue';
import moment from 'moment';



const TABLEURL = Hoot() + "eduallgetstudentsbyclass/";
const FORMURL = [
    Hoot() + "eduallsinglestudentfeepayment/get/",
    Hoot() + "eduallsinglestudentapi/get/",
    Hoot() + "eduallsingleserviceapi/get/",
    Hoot() + "eduallsingleacademicyearapi/get/",
    Hoot() + "eduallfeepaymentcheckpaidmonth/",
    Hoot()+"eduallgetsingletitleandheader/get/", 
];


function FeeDebtsReport({ userdata }) {
    const { id } = useParams();
    const [Total, setTotal] = useState([""]);
    const containerPrint = useRef();
    const [Data, setData] = useState([]);
    const [ClassMonths, setClassMonths] = useState([]);
    const [LoadStatus, setLoadStatus] = useState(null);
    const [Loaded, setLoaded] = useState(true);
    const [Founded, SetFounded] = useState(true);
    const [InstituteData, setInstituteData] = useState([]);
    const [ClassTitle, setClassTitle] = useState("")

    let month = new Date().getMonth();
    let currentMonth = month + 1 <= 12 ? month + 1 : month;

    const user = userdata.user_Information;

    let Months = [];
    const CY = new Date().getFullYear();
    const MonthsList = ["Janeiro", "Fevereiro", "Março",
        "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro",
        "Outubro", "Novembro", "Dezembro"];


    async function loadData(e) {
        setLoaded(false);
        try {
            if (e !== null && e * 1 >= 0) {
                const response2 = await axios.get(TABLEURL + e);
                const rows = [];
                const TableHeader = [];
                setClassMonths([]);
                setData([]);

                response2.data.map((student, stIndex) => {

                    const GetPaymentData = (studentCode, Academic_year) => {

                        let CurrentStudentData = {};
                        setTimeout(() => {
                            if (studentCode !== null) {
                                async function CheckStudentPayment() {
                                    try {

                                        const [AcademicYearData, response] = await Promise.all([
                                            axios.get(FORMURL[3] + Academic_year),
                                            axios.get(FORMURL[0] + `${studentCode}` + "," + `${Academic_year}`)
                                        ]);
                                        if (AcademicYearData.data.length >= 1) {
                                            let CurrentAcademicYearData = AcademicYearData.data[0];

                                            /// start getting the academic year data 
                                            let M1, M2 = null;
                                            let Y1, Y2 = null;
                                            let currentYear = new Date().getFullYear();
                                            M1 = CurrentAcademicYearData.ed_academic_year_startDate.split('-')[1] * 1;
                                            M2 = CurrentAcademicYearData.ed_academic_year_endDate.split('-')[1] * 1;
                                            Y1 = CurrentAcademicYearData.ed_academic_year_startDate.split('-')[0] * 1;
                                            Y2 = CurrentAcademicYearData.ed_academic_year_endDate.split('-')[0] * 1;


                                            let CRY = Y2 - Y1 === 1 ? 1 : 0;
                                            let DF = 12;

                                            if (M2 === 0 || M2 === null || M1 === 0 || M1 === null) return false;
                                            if (Y2 - Y1 <= 1) {


                                                if (CRY === 1) {
                                                    if ((M2 * 1) <= (M1 * 1)) {
                                                        let CurrentMonths = [];
                                                        let EX = 0;
                                                        let R = (DF - (M1 * 1) === 0 ? 1 : DF - (M1 * 1)) + (M2 * 1);
                                                        EX = R > DF ? R - DF : null;


                                                        for (let i = (M1 - 1) + 1; i <= 12; i++) {
                                                            CurrentMonths.push({ month: (MonthsList[i - 1] + " de " + Y1), status: 'other', code: ((i - 1 + "." + Y1) * 1) })
                                                        }

                                                        if (EX !== 0 && EX !== null) {
                                                            for (let i = 0; i <= (EX - 1); i++) {
                                                                CurrentMonths.push({ month: (MonthsList[i - 1] + " de " + Y2), status: 'other', code: ((i - 1 + "." + Y2) * 1) })
                                                            }
                                                        }

                                                        for (let i = 0; i <= (M2 - 1); i++) {
                                                            CurrentMonths.push({ month: (MonthsList[i] + " de " + Y2), status: 'other', code: ((i + "." + Y2) * 1) })
                                                        }


                                                        Months = CurrentMonths;

                                                    } else {
                                                        let CurrentMonths = [];
                                                        let EX = M1 === M2 ? M2 : (M1 - M2 < 0 ? M2 : M1 - M2);
                                                        let DM = DF - M1;


                                                        for (let i = (M1 * 1); i <= DF; i++) {
                                                            CurrentMonths.push({ month: (MonthsList[i - 1] + " de " + Y1), status: 'other', code: ((i - 1 + "." + Y1) * 1) })
                                                        }


                                                        if (EX >= 1) {
                                                            for (let i = 1; i <= EX; i++) {
                                                                CurrentMonths.push({ month: (MonthsList[i - 1] + " de " + Y2), status: 'other', code: ((i - 1 + "." + Y2) * 1) })
                                                            }
                                                        }
                                                        Months = CurrentMonths;
                                                    }

                                                } else {
                                                    let CurrentMonths = [];
                                                    CurrentMonths.push({ month: (MonthsList[(M1 * 1) - 1] + " de " + Y1), status: 'other', code: ((((M1 * 1) - 1) + "." + Y1) * 1) })

                                                    if (M2 !== null) {
                                                        for (let i = (M1 * 1) + 1; i <= M2; i++) {
                                                            CurrentMonths.push({ month: (MonthsList[i - 1] + " de " + Y1), status: 'other', code: (((i - 1) + "." + Y1) * 1) })
                                                        }
                                                    }

                                                    //  console.log("Senario n 3");

                                                    Months = CurrentMonths;
                                                }


                                                /// end 

                                                /*** ADDING PAYMENT STATUS */
                                                if (Months.length >= 1) {
                                                    let Months1 = Months;

                                                    const StudentData = async () => {
                                                        if (student !== null) {
                                                            CurrentStudentData.name = student.ed_student_name;
                                                            CurrentStudentData.class = student.ed_student_class;
                                                            CurrentStudentData.picture = Hoot() + student.ed_student_picture;
                                                            CurrentStudentData.id = student.ed_student_id;
                                                            CurrentStudentData.class_title = student.ed_class_title;
                                                            setClassTitle(student.ed_class_title)
                                                        }
                                                    }
                                                    StudentData();



                                                    setTimeout(() => {
                                                        const ServiceData = async () => {
                                                            let paidMonths = []

                                                            if (response.data.length >= 1) {
                                                                for (let i = 0; i < response.data.length; i++) {
                                                                    const e = response.data[i];
                                                                    if (e.ed_fee_payment_month !== "") {
                                                                        for (let a = 0; a < Months1.length; a++) {
                                                                            if ((Months1[a].code * 1) === (e.ed_fee_payment_month * 1)) {
                                                                                let thisMonthYear = Months1[a].month.split(" ")[2] * 1;
                                                                                Months1[a].status = "paid"
                                                                                paidMonths.push(Months1[a].code * 1);
                                                                                //console.log("Case 0 = "+thisMonthYear + " | "+currentYear);

                                                                            } else {

                                                                                if ((Months1[a].code * 1) < (((currentMonth - 1) + "." + CY) * 1) && Months1[a].status !== 'paid') {
                                                                                    let thisMonthYear = Months1[a].month.split(" ")[2] * 1;
                                                                                    if (thisMonthYear <= currentYear) {
                                                                                        Months1[a].status = "notpaid";
                                                                                    };
                                                                                    //console.log("Case 1= "+thisMonthYear + " | "+currentYear);
                                                                                } else {

                                                                                    if (Y2 - Y1 === 0) {
                                                                                        let thisMonthYear = Months1[a].month.split(" ")[2] * 1;
                                                                                        if (thisMonthYear <= currentYear) {
                                                                                            if (Months1[a].status !== 'paid') Months1[a].status = "notpaid";
                                                                                        };
                                                                                        //  console.log("Case 2= "+thisMonthYear + " | "+currentYear);
                                                                                    }

                                                                                }
                                                                            }
                                                                        }
                                                                    }
                                                                }



                                                                for (let i = 0; i <= paidMonths.length; i++) {
                                                                    for (let p = 0; p <= Months1.length; p++) {

                                                                        console.log("***************************************");
                                                                        console.log(Months1[i]);

                                                                        if (Months1[i] !== undefined && Months1[i].code !== undefined && Months1[i].code !== null) {
                                                                            if (Months1[i].code !== paidMonths[p]) {
                                                                                if (Months1[i].code < (((currentMonth - 1) + "." + CY) * 1) && Months1[i].status !== 'paid') {
                                                                                    let thisMonthYear = Months1[i].month.split(" ")[2] * 1;
                                                                                    if (thisMonthYear <= currentYear) Months1[i].status = "notpaid";
                                                                                    // console.log("Case 3 = "+thisMonthYear + " | "+currentYear);
                                                                                }
                                                                            }
                                                                        }

                                                                    }
                                                                }
                                                            }


                                                            if (paidMonths.length === 0) {
                                                                let x = null;
                                                                for (let i = 0; i < Months1.length; i++) {
                                                                    if (Months1[i].code === (((currentMonth - 1) + "." + CY) * 1)) {
                                                                        x = i;
                                                                        if (i >= x) {
                                                                            Months1[i].status = "other";
                                                                        }
                                                                    } else {
                                                                        if (x !== null) {
                                                                            if (i > x) {
                                                                                Months1[i].status = "other";
                                                                            }
                                                                        } else {
                                                                            let thisMonthYear = Months1[i].month.split(" ")[2] * 1;
                                                                            if (thisMonthYear <= currentYear) Months1[i].status = "notpaid";
                                                                            // console.log("Case 4 = "+thisMonthYear + " | "+currentYear);
                                                                        }
                                                                    }
                                                                }
                                                            }

                                                            CurrentStudentData.months = Months1;
                                                            setClassMonths(Months1);

                                                            if (stIndex === response2.data.length - 1) {
                                                                TableHeader.push({ field: 'index', headerName: 'Nº', width: 90 });
                                                                TableHeader.push({ field: 'name', headerName: 'Nome', width: 300 })

                                                            }

                                                            if (Months1.length >= 1) { CurrentStudentData.founded = true } else { CurrentStudentData.founded = false; }

                                                        }
                                                        ServiceData();
                                                    }, 100);

                                                }
                                                // END 
                                            }
                                        }
                                    } catch (error) {
                                        CurrentStudentData.founded = false;
                                    }
                                }
                                CheckStudentPayment();
                            }
                        }, 10);

                        rows.push(CurrentStudentData);
                    }
                    GetPaymentData(student.ed_student_id, student.ed_class_year);
                    setData(rows);
                })


                setLoaded(true);
            }
        } catch (error) {

        }
    }

    useEffect(() => {
        loadData(id);
    }, []);

  
    async function TitleData(e){ 
        if(Math.floor(e) >= 0){ 
            const response = await axios.get(FORMURL[5]+`${e}`)  
            if(response.data.length >= 1) {    
                let outputs = document.querySelectorAll(".paper-container .header-print");
                for (let i = 0; i < outputs.length; i++) {
                    outputs[i].innerHTML = JSON.parse(response.data[0].ed_title_description);
                }  
            }
          }
        }  
    
        let titleCode = 0;
        const setTitleCode = (e)=>{
              TitleData(e);
            titleCode = e;
        }
    
 
        
    const Multiplicate = (e) => {
        let Amount = [];
        for (let i = 0; i < e; i++) {
            Amount.push("");
        }
        setTotal(Amount);
        if(titleCode !== 0) TitleData(titleCode);
    }

    const handlePrint = useReactToPrint({
        content: () => containerPrint.current,
        documentTitle: 'eduall_lista_de_devedores' + '_' + Date.now() + RandomCodeGenerator(10),
        copyStyles: true,
    
    });



    if (Loaded) {
        if (id !== null && id !== undefined) {
            return (

                <div className="eduall-print-area">
                    <div className="box">
                        <div className="print-enrollment-header">
                            <div className="ed-space">
                                <div className="ed-flex">
                                    <button className="btn bg-main btn-icon-m0" onClick={handlePrint}><Print /> </button>
                                    <Form.Group className='ml-2' >
                                        <Form.Select onChange={(e) => Multiplicate(e.target.value)} style={{ maxWidth: '100px' }} >
                                            <option value="1">1X</option>
                                            <option value="2">2X</option>
                                            <option value="3">3X</option>
                                            <option value="4">4X</option>
                                            <option value="5">5X</option>
                                        </Form.Select>
                                    </Form.Group>
                                    <div className="ml-2">
                                        <Form >
                                            <Form.Group >
                                                <Form.Select onChange={(e) => setTitleCode(e.target.value)} id="doc-header-type">
                                                    <TitlesAndHeadersDataOptions code={2} />
                                                </Form.Select>
                                            </Form.Group>
                                        </Form>
                                    </div>
                                </div>
                                <div>
                                    <BackButton />
                                </div>
                            </div>
                        </div>
                        <div ref={containerPrint} style={{ width: '100%', height: window.innerHeight }} >
                            {
                                <>

                                    {(user !== null) ? <>
                                        {
                                            Total.map((item, index) => {
                                                return (
                                                    <section className={`paper-container`} key={index}  >
                                                        <div className="PaperBox">
                                                            <div className="enrollment-print-data tuition-document" key={index}>
                                                                <div className="header-doc">
                                                                    <div className="header-print"></div>
                                                                    <div className="header-subtitle"></div>
                                                                </div>
                                                                <div className="report-body">
                                                                    <section className="student-tuition-payment-report-invoice">
                                                                        <div className="container-fluid" >
                                                                            <div className="ed-wrapper-1" style={{ maxWidth: "1300px" }}  >
                                                                                <div className='debts-report-container' >
                                                                                    <div className="mb-2 mt-4">
                                                                                        <div className="ed-flex"><strong style={{fontWeight:"bolder"}}>Turma : </strong>
                                                                                        <div className="ml-1">{ClassTitle}</div> 
                                                                                     </div>
                                                                                    </div>
                                                                                    <Table responsive bordered >
                                                                                        <thead>
                                                                                            {ClassMonths.length !== 0 ?
                                                                                                <tr>
                                                                                                    <th>Nº</th>
                                                                                                    <th style={{ minWidth: '300px', verticalAlign: "middle" }} className='text-left' rowspan="4">Nome do estudante</th>
                                                                                                    {ClassMonths.map((month, index) => {
                                                                                                        return (<th style={{ minWidth: '40px', verticalAlign: "middle" }} key={index}>
                                                                                                            {month.month.split(" ")[0].slice(0,3)}  {month.month.split(" ")[2].slice(0,4)} 
                                                                                                        </th>)
                                                                                                    })}
                                                                                                </tr>
                                                                                                :
                                                                                                <tr>
                                                                                             </tr>}
                                                                                        </thead>
                                                                                        <tbody>
                                                                                            {Data.map((student, index) => {
                                                                                                return (
                                                                                                    <tr>
                                                                                                        <td>{index + 1}</td>
                                                                                                        <td>{student.name}</td>
                                                                                                        {student.months !== undefined ?
                                                                                                            <>
                                                                                                                {student.months.map((item) => {
                                                                                                                    return (<td className='col'>{item.status.toLowerCase() === "paid" ?
                                                                                                                        <span className='text-success'>Pago</span> : <span className='text-danger'>Não pago</span>}</td>)
                                                                                                                })}
                                                                                                            </> :
                                                                                                            <></>
                                                                                                        }
                                                                                                    </tr>
                                                                                                )
                                                                                            })}
                                                                                        </tbody>
                                                                                    </Table>
                                                                                </div>
                                                                            </div>
                                                                        </div>
                                                                    </section>


                                                                </div>
                                                            </div>
                                                           <br /><br /><br /><br /> <br /><br /> 
                                                        </div> 
                                                    </section>
                                                )
                                            })
                                        }
                                    </> : <></>}
                                </>

                            }
                        </div>
                    </div>

                </div>

            )
        } else if (Founded === false) {
            return (
                <NotFounded />
            )
        }
    } else {
        return (
            <div className="loader-content-box">
                <Loader />
            </div>
        )
    }

}

export default FeeDebtsReport
