/* =================== Extração DOM (para preview gerado) =================== */
function extractStructuredDataFromRoot(root) {
  if (!root) return { blocks: [] };
  const blocks = [];
  root.querySelectorAll("table").forEach((table, idx) => {
    try {
      const thead = table.querySelector("thead");
      const headers = thead
        ? Array.from(thead.querySelectorAll("th")).map((th) => norm(th.textContent))
        : Array.from(table.querySelectorAll("tr:first-child th, tr:first-child td")).map((el) =>
            norm(el.textContent)
          );
      const rows = Array.from(table.querySelectorAll("tbody tr")).map((tr) => {
        const obj = {};
        Array.from(tr.children).forEach((td, i) => {
          const label = headers[i] ?? `col_${i + 1}`;
          obj[label] = norm(td.textContent);
        });
        return obj;
      });

      toast.success(rows.length)
      blocks.push({
        kind: "table",
        id: table.id || `table_${idx + 1}`,
        headers,
        rows
      });
    } catch {}
  });

  return { blocks };
}

/* =================== Fonte de dados para export =================== */
function deriveTablesForExport({ previewHTML, planJSON }) {
  const tables = [];
  if (previewHTML) {
    try {
      const dom = new DOMParser().parseFromString(previewHTML, "text/html");
      const fromDom = extractStructuredDataFromRoot(dom.body || dom);
      fromDom.blocks
        .filter((b) => b.kind === "table" && b.rows?.length)
        .forEach((b, i) => {
          tables.push({
            name: b.id || `Tabela_${i + 1}`,
            headers: b.headers,
            rows: b.rows
          });
        });
    } catch {}
  }
  if (tables.length === 0 && planJSON?.actions?.length) {
    planJSON.actions.forEach((a, i) => {
      const sampleRows =
        a.previewRows && Array.isArray(a.previewRows) && a.previewRows.length
          ? a.previewRows
          : a.data && typeof a.data === "object"
          ? [a.data]
          : [];
      if (sampleRows.length) {
        const headers = Object.keys(sampleRows[0]);
        tables.push({
          name: `${a.type || "acao"}_${a.entity || "entidade"}_${i + 1}`,
          headers,
          rows: sampleRows
        });
      }
    });
  }
  return tables;
}

/* =================== Exporters (cliente) =================== */
async function exportTablesToPDF({ tables, title = "Relatório", fileName = "relatorio.pdf" }) {
  if (!tables?.length) {
    toast.error("Não há dados tabulares para exportar.");
    return;
  }
  const doc = new jsPDF({ orientation: "landscape", unit: "mm", format: "a4" });
  const pageWidth = doc.internal.pageSize.getWidth();
  let y = 12;

  doc.setFontSize(14);
  doc.setFont(undefined, "bold");
  doc.text(title, pageWidth / 2, y, { align: "center" });
  y += 6;

  tables.forEach((t, idx) => {
    if (idx > 0) doc.addPage();
    doc.setFontSize(11);
    doc.setFont(undefined, "bold");
    doc.text(t.name, 10, y);
    autoTable(doc, {
      startY: y + 2,
      head: [t.headers],
      body: t.rows.map((r) => t.headers.map((h) => String(r[h] ?? ""))),
      styles: { fontSize: 9, cellPadding: 2 },
      theme: "grid",
      headStyles: { fillColor: [247, 249, 252], textColor: [0, 0, 0] }
    });
  });

  doc.save(ensureExt(fileName.replace(/\s+/g, "_"), "pdf"));
}

async function exportTablesToExcel({ tables, fileName = "relatorio.xlsx" }) {
  if (!tables?.length) {
    toast.error("Não há dados tabulares para exportar.");
    return;
  }
  const wb = XLSX.utils.book_new();
  tables.forEach((t) => {
    const sheetData =
      t.rows && t.rows.length
        ? [t.headers, ...t.rows.map((r) => t.headers.map((h) => r[h]))]
        : [t.headers];
    const ws = XLSX.utils.aoa_to_sheet(sheetData);
    XLSX.utils.book_append_sheet(wb, ws, (t.name || "Sheet").substring(0, 31));
  });
  XLSX.writeFile(wb, ensureExt(fileName.replace(/\s+/g, "_"), "xlsx"));
}

