import React, { useEffect, useState, useCallback, useMemo } from "react";
import axios from "axios";
import Radio from "@mui/material/Radio";
import FormControlLabel from "@mui/material/FormControlLabel";
import { Modal, Spinner } from "react-bootstrap";
import { FiX } from "react-icons/fi";
import Hoot from "./Hoot";

const API_BASE = (typeof Hoot === "function" ? Hoot() : "") || "";

/* Extrair ID do YouTube */
function parseYouTubeId(linkOrId) {
  if (!linkOrId) return "";
  if (/^[a-zA-Z0-9_-]{10,}$/.test(linkOrId)) return linkOrId;

  try {
    const u = new URL(linkOrId);
    const v = u.searchParams.get("v");
    if (v) return v;
    const p = u.pathname.split("/").filter(Boolean);
    return p.pop() || linkOrId;
  } catch {
    return linkOrId;
  }
}

/* IFRAME SEM RADIUS */
function YouTubeEmbed({ videoId }) {
  const src = `https://www.youtube.com/embed/${videoId}?autoplay=1&rel=0&modestbranding=1`;
  return (
    <div className="yt-wrapper-news transparent">
      <iframe
        title="Novidade"
        src={src}
        frameBorder="0"
        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share"
        allowFullScreen
      />
    </div>
  );
}

export default function NewsVideoPopup({ auto = true }) {
  const [loading, setLoading] = useState(false);
  const [news, setNews] = useState(null);
  const [open, setOpen] = useState(false);
  const [marking, setMarking] = useState(false);
  const [seen, setSeen] = useState(false);

  const videoId = useMemo(
    () => parseYouTubeId(news?.ed_news_video_link),
    [news]
  );

  /* Buscar notícia não vista */
  const fetchLatestUnseen = useCallback(async (abortSignal) => {
    setLoading(true);
    try {
      const res = await axios.get(`${API_BASE}news/unseen/latest`, {
        withCredentials: true,
        signal: abortSignal,
      });

      const item = res.data?.data || null;

      if (item) {
        setNews(item);
        setSeen(false);
        setOpen(true);
      }
    } catch (e) {
      if (!axios.isCancel(e)) console.error(e);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!auto) return;
    const ctrl = new AbortController();
    fetchLatestUnseen(ctrl.signal);
    return () => ctrl.abort();
  }, [auto, fetchLatestUnseen]);

  /* Marcar como vista — NÃO FECHA MAIS O MODAL */
  const handleMarkSeen = async () => {
    if (!news?.ed_news_id || marking || seen) return;

    setMarking(true);
    setSeen(true);

    try {
      await axios.put(
        `${API_BASE}news/videos/${news.ed_news_id}/seen`,
        {},
        { withCredentials: true }
      );
 

    } catch (e) {
      console.error(e);
    } finally {
      setMarking(false);
    }
  };

  return (
    <>
      <style>{css}</style>

      <Modal
        show={open}
        onHide={() => setOpen(false)}
        size="lg"
        centered
        contentClassName="news-lightbox-content transparent-bg"
        dialogClassName="news-lightbox-dialog"
        backdropClassName="news-lightbox-backdrop"
      >
        {/* BOTÃO X */}
        <button
          className="mr-2 mt-2 news-lightbox-close"
          onClick={() => setOpen(false)}
          aria-label="Fechar"
        >
          <FiX />
        </button>

        <Modal.Body className="news-lightbox-body">
          {loading ? (
            <div className="news-loading">
              <Spinner animation="border" />
              <div className="mt-3">A verificar novidades…</div>
            </div>
          ) : news ? (
            <>
              <h3 className="news-title">{news.ed_news_title}</h3>

              <div className="ml-1">
                <FormControlLabel
                  control={
                    <Radio
                      checked={seen}
                      onChange={handleMarkSeen}
                      disabled={marking}
                      sx={{ padding: 0 }}
                    />
                  }
                  label="Confirmo que li e tomei conhecimento desta comunicação"
                  className="radio-seen"
                />
              </div>

              <YouTubeEmbed videoId={videoId} />
            </>
          ) : null}
        </Modal.Body>
      </Modal>
    </>
  );
}

