import React, { useState } from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap'
import { Delete, InfoOutlined, Save, SaveAlt } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import { toast } from 'react-hot-toast';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import { Update } from '@material-ui/icons';
import RefreshList from '../../../General/components/RefreshList';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import StudentDetailsMenu from '../elements/StudentDetailsMenu';
import SelectSearch from 'react-select-search';
import { StudentsArray } from '../../../General/components/InstituteData';
import { Avatar } from '@mui/material';
import DeleteModal from '../elements/DeleteModal';
import styled from 'styled-components';


function ParentsChildsPopup(props) {
    const [show, setShow] = useState(false);
    const [Data, setData] = useState([]);
    const [showBox, SetshowBox] = useState(false);
    const [studentCode, setStudentCode] = useState(null);
    const [RegisterStatus, setRegisterStatus] = useState(null);


    const handleClose = () => {
        SetshowBox(false);
        setTimeout(() => {
            setShow(false);
        }, 1200);
    }

    const handleShow = () => {
        SetshowBox(true);
        setShow(true);
        setTimeout(() => {
            GET_DATA();
        }, 1000);
    };

    function GetStudentCode(e) {
        setStudentCode(e);
    }

    const FORMURL = [
        props.get ? props.get : '',
        props.url ? props.url : '',
        Hoot() + "eduallparentkids/register"
    ];


    const GET_DATA = async () => {
        try {
            const response = await axios.get(FORMURL[0]);
            setData(response.data)
        } catch (error) {
            toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
        }
    }


    const FormSubmit = async (e) => {
        e.preventDefault();
        setRegisterStatus(0);
        if (studentCode === null) {
            toast.error("Selecione um estudante !");
            setRegisterStatus(1);
        } else {
            const SUBMIT_INPUTS = {
                parentkid_parent: props.parent,
                parentkid_student: studentCode
            };
            try {
                await axios.post(FORMURL[2], SUBMIT_INPUTS);
                toast.success("Estudante atribuido com sucesso !");
                setStudentCode(null); 
                setRegisterStatus(2);
            } catch (error) {
                const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
                toast.error(msg);
                setRegisterStatus(1);
            }
            GET_DATA();
        }
    };

    return (
        <div>
            <div onClick={handleShow}>
                {
                    props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'> </button>
                }
            </div>
            <Modal size='lg' className={showBox ? ModalAnimationShow() : ModalAnimationClose()} centered dialogAs={DraggableModal} show={show} onHide={handleClose}>
                <Modal.Header closeButton>
                    <Modal.Title>
                        <div className="ed-flex align-center">
                            <UserOptionDropDown />
                            <h5>Estudantes associados (educandos) </h5>
                        </div>
                    </Modal.Title>
                </Modal.Header>
                <Form onSubmit={FormSubmit} >
                    <Modal.Body className='scrollLimit'>
                        <div className="ed-center">
                            <div className="ed-block">

                                <div className="ed-flex">
                                    <div className="col">
                                        <Form.Group>
                                            <div className="ed-space">
                                                <div>
                                                    <Form.Label>Nome do estudante {studentCode} <span className='text-danger ml-2'>*</span></Form.Label>
                                                </div>
                                                <div className='ed-flex'>
                                                    {studentCode !== null ? <StudentDetailsMenu student_id={studentCode} toggle_btn={<div className='btn-pm-info'><InfoOutlined /></div>} /> : <></>}
                                                </div>
                                            </div>
                                            <div className={`select-search-item`}>
                                                <SelectSearch onChange={(e) => GetStudentCode(e)} value={studentCode} options={StudentsArray()[0]} search={true}
                                                    placeholder="Selecione um aluno" />
                                            </div>
                                        </Form.Group>
                                    </div>
                                </div>
                                {Data.length > 0 ?
                                    <div>
                                        <List className='mt-2'>
                                            {Data.map((item, index) => {
                                                return (
                                                    <li key={index + 1}>
                                                        <div className="ed-space">
                                                            <div className="ed-flex">
                                                                <Avatar src={Hoot() + item.ed_student_picture} alt={item.ed_student_name} />
                                                                <div className="ml-2"><span>{item.ed_student_name}</span></div>
                                                            </div>
                                                            <div className="ed-flex">
                                                                <DeleteModal title="a atribuição de estudante" url={Hoot() + "eduallparentkids/delete/" + item.ed_parentkid_id} toggle_btn={
                                                                    <div className="btn-circle  bg-danger ml-2 text-light">
                                                                        <Delete />
                                                                    </div>} />
                                                            </div>
                                                        </div>
                                                    </li>)
                                            })}
                                        </List>
                                    </div>
                                    :
                                    <div className="ed-center">
                                        <br /><br />
                                        <h5 className="grey-text">Nenhum estudante foi associado aos dados deste encarregado</h5>
                                        <br /><br />
                                    </div>
                                }
                            </div>
                        </div>
                    </Modal.Body>
                    <Modal.Footer>
                        <div className="ed-space">
                            <div className="ed-flex"></div>
                            <div className="ed-flex">
                                <Button className='bg-light text-dark' onClick={handleClose}>Cancelar</Button>
                                <SaveButton icon={<Save />} title={'Salvar'} status={RegisterStatus} />
                            </div>
                        </div>
                    </Modal.Footer>
                </Form>
            </Modal>
        </div >
    )
}



const List = styled.div`
   padding:10px 0px;

     li{
        display:flex;
        align-items:center;
        margin: 10px 0px;
        border:1px solid var(--ed-white-smoke);
        background:var(--ed-background-color);
        padding:10px;
        border-radius:6px;
        list-style:none;
     }
`;

export default ParentsChildsPopup
