import React, { useState } from 'react';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap';
import { InfoOutlined, Save, Update } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import { toast } from 'react-hot-toast';
import axios from 'axios';
import ClearInputs from '../../../General/components/ClearInputs';
import RefreshList from '../../../General/components/RefreshList';
import Hoot from '../../../General/components/Hoot';
import { StudentsArray } from '../../../General/components/InstituteData';
import SelectSearch from 'react-select-search';
import StudentDetailsMenu from '../elements/StudentDetailsMenu';
import { Checkbox, FormControlLabel } from '@mui/material';
import { RichTextEditor } from '../../../General/components/RichTextEditor';

function NewDeclarationRequestModal(props) {
    const [show, setShow] = useState(false);
    const [registerStatus, setRegisterStatus] = useState(null);
    const [founded, setFounded] = useState(null);
    const [form, setForm] = useState({
        declaration_request_student_code: "",
        declaration_request_by: "",
        declaration_request_with_marks: true,
        declaration_request_description: "",
        declaration_request_status: "0"
    });
    const [errors, setErrors] = useState({});
    const [showBox, setShowBox] = useState(false);

    const handleClose = () => {
        setShowBox(false);
        setTimeout(() => setShow(false), 1200);
    };

    const handleShow = () => {
        setShowBox(true);
        setShow(true);
        setTimeout(() => GET_DATA(), 1000);
    };

    const FORM_URLS = [
        Hoot() + "edualldeclarationrequestregister/post",
        props.get ? props.get : '',
        props.url ? props.url : ''
    ];

    const GET_DATA = async () => {
        if (props.update) {
            try {
                const response = await axios.get(FORM_URLS[1]);
                if (response.data.length > 0) {
                    setForm({
                        declaration_request_student_code: response.data[0].ed_declaration_request_student_code,
                        declaration_request_by: response.data[0].ed_declaration_request_by,
                        declaration_request_with_marks: Math.floor(response.data[0].ed_declaration_request_with_marks) === 1,
                        declaration_request_description: response.data[0].ed_declaration_request_description,
                        declaration_request_status: response.data[0].ed_declaration_request_status
                    });
                } else {
                    toast.error("Não foi possível encontrar as informações selecionadas!");
                }
            } catch {
                toast.error("Erro ao carregar os dados da solicitação!");
            }
        }
    };

    const handleInput = (e) => {
        const { id, value } = e.target;
        setField(id, value);
    };

    const setField = (field, value) => {
        setForm({ ...form, [field]: value });
        if (!!errors[field]) setErrors({ ...errors, [field]: null });
    };

    const toggleCheckBox = (e) => {
        setField("declaration_request_with_marks", e.target.checked);
    };

    const validateForm = () => {
        const { declaration_request_by, declaration_request_student_code } = form;
        const newErrors = {};
        setRegisterStatus(0);
        if (declaration_request_by < 0) newErrors.declaration_request_by = 'Campo obrigatório!';
        if (declaration_request_student_code * 1 <= 0) newErrors.declaration_request_student_code = 'Estudante inválido!';
        return newErrors;
    };

    const FormSubmit = async (e) => {
        e.preventDefault();
        const formErrors = validateForm();

        if (Object.keys(formErrors).length > 0) {
            setErrors(formErrors);
            toast.error("Verifique todos os campos obrigatórios!");
            setRegisterStatus(1);
        } else {
            if (!props.update) {
                try {
                    await axios.post(FORM_URLS[0], form);
                    toast.success("Solicitação registrada com sucesso!");
                    setForm({ declaration_request_student_code: "", declaration_request_by: "", declaration_request_with_marks: true, declaration_request_description: "", declaration_request_status: "0" });
                    ClearInputs();
                    RefreshList(`.el-refresh-list`);
                    setRegisterStatus(2);
                    setTimeout(() => handleClose(), 1500);
                } catch (error) {
                    const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
                    toast.error(msg);
                    setRegisterStatus(1);
                }
            } else {
                try {
                    await axios.put(FORM_URLS[2], form);
                    toast.success("Solicitação atualizada com sucesso!");
                    setForm({ declaration_request_student_code: "", declaration_request_by: "", declaration_request_with_marks: true, declaration_request_description: "", declaration_request_status: "0" });
                    ClearInputs();
                    RefreshList(`.el-refresh-list`);
                    setRegisterStatus(2);
                    setTimeout(() => handleClose(), 1500);
                } catch (error) {
                    const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
                    toast.error(msg);
                    setRegisterStatus(1);
                }
            }
        }
    };

    return (
        <div>
            <div onClick={handleShow}>
                {props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon /> Registrar Solicitação de Declaração</button>}
            </div>
            <Modal className={showBox ? ModalAnimationShow() : ModalAnimationClose()} centered size='lg' dialogAs={DraggableModal} show={show} onHide={handleClose}>
                <Modal.Header closeButton>
                    <Modal.Title>
                        <div className="ed-wrap align-center">
                            <UserOptionDropDown />
                            <h5>{props.title ? props.title : 'Registrar '} Solicitação de Declaração</h5>
                        </div>
                    </Modal.Title>
                </Modal.Header>
                <Form onSubmit={FormSubmit}>
                    <Modal.Body className='scrollLimit'>
                        <Form.Group className="mb-3">
                            <div className="ed-space">
                                <Form.Label>Nome do estudante <span className='text-danger ml-2'>*</span></Form.Label>
                                {form.declaration_request_student_code &&
                                    <StudentDetailsMenu student_id={form.declaration_request_student_code} toggle_btn={<div className='btn-pm-info'><InfoOutlined /></div>} />}
                            </div>
                            <div className={`select-search-item ${errors.declaration_request_student_code ? 'error' : ''}`}>
                                <SelectSearch onChange={(e) => setField("declaration_request_student_code", e)} value={form.declaration_request_student_code} options={StudentsArray()[0]} search={true} placeholder="Selecione um aluno" />
                            </div>
                            <small className="text-danger">{errors.declaration_request_student_code}</small>
                        </Form.Group>
                        <Form.Group className="mb-3">
                            <Form.Label>Solicitado por<span className='text-danger ml-2'>*</span></Form.Label>
                            <Form.Select id="declaration_request_by" value={form.declaration_request_by} onChange={handleInput} isInvalid={!!errors.declaration_request_by}>
                                <option value="0">Encarregado</option>
                                <option value="1">Estudante</option>
                                <option value="2">Professor</option>
                            </Form.Select>
                            <Form.Control.Feedback type='invalid'>{errors.declaration_request_by}</Form.Control.Feedback>
                        </Form.Group>
                        <FormControlLabel control={<Checkbox id='declaration_with_marks' checked={form.declaration_request_with_marks} onChange={toggleCheckBox} />} label="Adicionar notas à declaração" />
                        <Form.Group className="mb-3">
                            <Form.Label>Descrição</Form.Label>
                            <div className="class-description-input">
                                <textarea onChange={handleInput} name="declaration_request_description" id="declaration_request_description"
                                    value={form.declaration_request_description} rows={10} className="form-control"></textarea>
                            </div>
                        </Form.Group>
                    </Modal.Body>
                    <Modal.Footer>
                        <Button className='bg-light text-dark' onClick={handleClose}>Cancelar</Button>
                        <SaveButton icon={props.update ? <Update /> : <Save />} title={props.title || 'Salvar'} status={registerStatus} />
                    </Modal.Footer>
                </Form>
            </Modal>
        </div>
    );
}

export default NewDeclarationRequestModal;
