function AddsGenerator(props){ 
  const [CurrentAdd, setCurrentAdd] = useState(null);


  useEffect(()=>{  
    FirtsPop();
    StartPoping();
  },[]);

  const Adds = props.smaller ? SmallerADDS : LargeAdds; 


  const StartPoping = ()=>{
     let x = (Math.floor(Math.random() * Adds.length) + 0);
     setInterval(() => { 
         RegisteraDS(Adds[x]); 
         x = (Math.floor(Math.random() * Adds.length) + 0); 
     }, 20000);
  }
 

  const FirtsPop = ()=>{
    let x = (Math.floor(Math.random() * Adds.length) + 0);
     setTimeout(() => {
        RegisteraDS(Adds[x]); 
        x = (Math.floor(Math.random() * Adds.length) + 0); 
     }, 1000);
 }


  const  RegisteraDS = async(e)=>{  
    setCurrentAdd(e); 
     if(document.hidden === false){
        try {
          axios.post(URL+e.code, e.code ).then((dt)=>{    
            setCurrentAdd(e); 
          }).catch((error)=>{
              console.log(error);
          });  
        } catch (error) { 
          console.log(error);
        }  
     }  
}


 
if(CurrentAdd !== null){
  return (
    <>  
      {props.smaller ? <AdBox  smaller key={0} data={CurrentAdd} />    : 
      <AdBox cramb={props.cramb ? true : false} margin={props.margin ? false : true}  small={props.small  ? true : false}  text={props.text ? 'left' : 'right'} size='lg' key={0} data={CurrentAdd} />  }
    </>
  ) 
}


}

export default AddsGenerator