import React, { useRef, useState } from 'react'
import { Play , Scan, VolumeMute, InformationCircle, VolumeHigh, TabletLandscape, Settings, RefreshOutline,
    PhoneLandscape, Videocam, VolumeMedium, Pause, PlaySkipBack, CopyOutline, VolumeLow, PlaySkipForward } from 'react-ionicons'
    import { PiClosedCaptioning } from "react-icons/pi";
import ImageLazyLoading from '../../ImageLazyLoading';



function EduallVideoPlayer(props){
    const [IsVideoPlaying, setIsVideoPlaying] = useState(false);
    const VideoRef = useRef(null);
    const [TotalVideoDuration , SetTotalVideoDuration] = useState("00");
    const [CurrentVideoTime , SetCurrentVideoTime] = useState("00");
    const [VideoRepeat, setVideoReapeat] =  useState(false);
    const [VideoSpeed, setVideoSpeed] = useState("1x");

    //Get player Icons
    const GetPlayerIcons = (key)=>{ 
          const List = [
            {name:"play", obj:<><Play/></>},
            {name:"pause", obj:<><Pause/> </>},
            {name:"prev", obj:<><PlaySkipBack/></>},
            {name:"next", obj:<><PlaySkipForward/></>},
            {name:"caption", obj:<><PiClosedCaptioning/> </>},
            {name:"settings", obj:<><Settings /></>},
            {name:"vmuted", obj:<><VolumeMute/></>},
            {name:"vlow", obj:<><VolumeLow/></>},
            {name:"vhigh", obj:<><VolumeHigh/> </>},
            {name:"vnormal", obj:<><VolumeMedium/> </>},
            {name:"info", obj:<><InformationCircle/></>},
            {name:"streaming", obj:<><Videocam/></>},
            {name:"landscape", obj:<><PhoneLandscape/></>},
            {name:"normalview", obj:<><TabletLandscape/></>},
            {name:"fullscreen", obj:<><Scan/></>},
            {name:"picture", obj:<><CopyOutline/></>},
            {name:"repeat", obj:<><RefreshOutline/></>},
        ]; 
       let Icon = List.map((el, index)=>{if(el.name === key){return el.obj;}else{ return <></>
      }});

    return Icon;
    }

    const leadingZeroFormatter = new Intl.NumberFormat(undefined, {
        minimumIntegerDigits : 2,//ara conque caso o numero tenha apenas um digito ele adicione zero
     })
    
     function formatDuration(time) {
        const seconds = Math.floor(time % 60);
        const minutes = Math.floor(time / 60) % 60;
        const hours = Math.floor(time / 3600);
        if (hours === 0) {
            return <>{`${minutes} : ${leadingZeroFormatter.format(seconds)}`}</> ;
        }else{
            return<>{`${hours}:${leadingZeroFormatter.format(minutes)}: 
            ${leadingZeroFormatter.format(seconds)}`}</>
        }
     }


    const VideoPlay =  (e)=>{
       // setIsVideoPlaying(e)
    }

    const ToggleVideoPlayPause = ()=>{
           if(IsVideoPlaying === true){
               VideoRef.current.pause();
               setIsVideoPlaying(false);
           }else{
              VideoRef.current.play();
              setIsVideoPlaying(true);
           }
    }


    const TrackVideoTimeUpdate = (e)=>{
        SetCurrentVideoTime(formatDuration(VideoRef.current.currentTime));
    }


    const TrackVideoOnLoad = (e)=>{
        SetTotalVideoDuration(formatDuration(VideoRef.current.duration))
    }


    const TrackVideoVolume =  (e)=>{

    }


    //Change video player speed
    const ChangeVideoSpeed = (e)=>{
        let newPlaybackRate = VideoRef.current.playbackRate + 0.25;
        if(newPlaybackRate > 2){newPlaybackRate = 0.25};
        VideoRef.current.playbackRate = newPlaybackRate; 
        setVideoSpeed(`${newPlaybackRate} x`);
    }


   ///Toggle events after video ends
    const VideoOnEnded  =  ()=>{
        let playlist = false;
        if(!playlist){
            setVideoReapeat(true);
        }else{
            setVideoReapeat(false);
        }
    }

  //Repeat video player function
    const RepeatVideo =  ()=>{
        setVideoReapeat(false);   
        VideoRef.current.play();
        setIsVideoPlaying(true);
    }


   //Video on waiting 
    const VideoOnWaiting  =  ()=>{

    }


 ////Video timeline tracking functions



let wasPaused
let isScrubbing  = false;
let timelineContainer = document.querySelector(".timeline-container");
let videoContainer =  document.querySelector(".video-container");

window.addEventListener("mouseup", e=>{
    if(isScrubbing) toggleScrubbing(e);
 });


window.addEventListener("mousemove", e=>{
    if(isScrubbing) handleTimelineUpdate(e);
});


function toggleScrubbing(e) {
    const rect = timelineContainer.getBoundingClientRect();
    const percent = Math.min(Math.max(0, e.x  - rect.x), rect.width) / rect.width ;
    isScrubbing = (e.buttons & 1);


    console.log("Scrubbing  = "+ isScrubbing);
 
    videoContainer.classList.toggle("scrubbing", isScrubbing);

console.log(videoContainer.classList)

    if (isScrubbing) {
        wasPaused = VideoRef.current.paused
        VideoRef.current.pause()
    }else{
        VideoRef.current.currentTime = percent * VideoRef.current.duration
        if (!wasPaused) VideoRef.current.play()
    }
    handleTimelineUpdate(e);
} 

  function handleTimelineUpdate(e) {
       const rect = timelineContainer.getBoundingClientRect();

       console.log("window = ", e);
       console.log(timelineContainer);

       const percent = Math.min(Math.max(0, e.pageX  - rect.x), rect.width) / rect.width ;
       const previewImgNumber = Math.max(1, Math.floor((percent*  VideoRef.current.duration) /10));
       //const previewImgSrc = `assets/previewImgs/preview${previewImgNumber}.jpg`;
       //previewImg.src = previewImgSrc;


       console.log("percent  = "+percent);

       timelineContainer.style.setProperty("--preview-position", percent);

       if (isScrubbing) {
          e.preventDefault();   
          //thumbnailImg.src = previewImgSrc;
          timelineContainer.style.setProperty("--progress-position", percent);
       }
  }

  return (
      <div className="player-page">
    <div className='eduall-video-player' id="#"> 
    <div className={`video-container  ${IsVideoPlaying === true ? " " : "paused"}`} data-volume-level="high">
        <img className="thumbnail-img"/>
        <video ref={VideoRef}
          onPlay={()=>VideoPlay(true)}
          onPause={()=>VideoPlay(false)}
          onClick={ToggleVideoPlayPause}
          onTimeUpdate={TrackVideoTimeUpdate}
          onLoadedData={TrackVideoOnLoad}
          onEnded={VideoOnEnded}
          poster='https://static.vecteezy.com/system/resources/previews/022/455/303/non_2x/cook-cuts-meat-with-a-knife-in-the-kitchen-prepares-food-vegetables-and-spices-on-the-kitchen-table-in-a-restaurant-to-prepare-a-delicious-lunch-free-photo.jpg'  
          src="https://www.shutterstock.com/shutterstock/videos/1086443234/preview/stock-footage-close-up-of-falling-tasty-beef-steak-in-kitchen-super-slow-motion-camera-movement-filmed-on-high.webm">
          <track kind="captions" srclang=""/> 
        </video>
       <div className={IsVideoPlaying === true ? "play-button hide"  : "play-button"}  onClick={ToggleVideoPlayPause}>
          <div className="play-btn"> {GetPlayerIcons("play")}  </div>
       </div>
      <section className="info-section">
      <div className="playlist-container hide">
          <div className="comming-next">
               <h2>A seguir :</h2> 
               <div className="next-item-thumb">
                   <ImageLazyLoading  source="https://i.ytimg.com/vi/ZengOKCUBHo/maxresdefault.jpg"  height={110} />
               </div>
          </div>
       </div>
       <div className="user-info-con">
           
       </div>
      </section>
        <div className="video-controls-container">
            <div className="timeline-container"  onMouseMove={handleTimelineUpdate}  onMouseDown={toggleScrubbing}>
                <div className="timeline">
                    <img className="preview-img"/>
                    <div className="thumb-indicator"></div>
                </div>
            </div>
            <div className="controls">
               <div className="item">
              
                     {VideoRepeat === true ? 
                      <button className="play-pause-btn" onClick={RepeatVideo}> 
                        <div>{GetPlayerIcons("repeat")}</div>
                     </button>
                     :
                     <>
                      <button className="play-pause-btn"   onClick={ToggleVideoPlayPause}> 
                         <div className="play-icon"> {GetPlayerIcons("play")}</div>
                         <div className="pause-icon"> {GetPlayerIcons("pause")}</div>
                       </button>
                     </> }
                
                <div className="volume-container">
                    <button className="mute-btn">
                        <div className="high-icon"> {GetPlayerIcons("vhigh")} </div>
                        <div className="low-icon"> {GetPlayerIcons("vlow")} </div>
                        <div className="muted-icon"> {GetPlayerIcons("vmuted")} </div>
                   </button>
                   <input type="range" min="0" max="1" step="any" value="1" className="volume-slider" />
                </div>
                <div className="duration-container">
                    <div className="current-time">{TotalVideoDuration}</div> / 
                    <div className="total-time">{CurrentVideoTime}</div>
                </div>
               </div>
               <div className="item">
               <button className="caption-btn">  {GetPlayerIcons("caption")}  </button>
                <button className="speed-btn wide-btn" onClick={ChangeVideoSpeed}>{VideoSpeed}</button>
                <button className="mini-player-btn"> {GetPlayerIcons("picture")} </button>
                <button className="theater-btn">
                     <div  className="tall"> {GetPlayerIcons("landscape")} </div>
                     <div className="wide"> {GetPlayerIcons("nromalview")} </div>
                </button>
                <button className="full-screen-btn"> {GetPlayerIcons("fullscreen")} </button>
               </div>
            </div>
          </div>
        </div> 
       </div>
      </div>
  )
}

export default EduallVideoPlayer