import React, { useState } from 'react'
import NavbarStudent from './Students/Components/NavbarStudent'
import styled from 'styled-components';
import { Avatar, AvatarGroup } from '@mui/material';
import { Form } from 'react-bootstrap';
import { BookmarksOutlined, ChatBubbleOutline, CommentOutlined, Email, FavoriteBorder, ForumOutlined, GroupOutlined, HomeOutlined, ImageOutlined, LinkedIn, ListAltOutlined, MailOutlineOutlined, NotificationsNoneRounded, Phone, Share, ThumbDown, ThumbsUpDownOutlined, ThumbUpSharp, YouTube } from '@material-ui/icons';
import { Link } from 'react-router-dom';
import { HeartBrokenOutlined, QuestionMarkRounded, ThumbDownAltOutlined } from '@mui/icons-material';
import ReduceTextLength from '../General/components/ReduceTextLength';
import HonorBoard from './Students/Components/HonorBoard';
import StudentMenu from './Students/Components/StudentMenu';
import { SettingsOutlined, Facebook, Instagram } from '@material-ui/icons';
import StudentProfileGlobal from './Students/Components/StudentProfileGlobal';
import { Tab } from 'bootstrap';
import SidebarLeft from './Students/Components/SidebarLeft';
import MenuRight from './Components/MenuRight';
import UserNavbar from './Components/UserNavbar';
import Hoot from '../General/components/Hoot';
import ProfileGlobal from './Profile/ProfileGlobal';
import { toast } from 'react-hot-toast';
import axios from 'axios';
import ImageLazyLoading from '../General/components/ImageLazyLoading';
import { FiImage } from "react-icons/fi";
import { LiaCogSolid } from "react-icons/lia";

function PersonalProfile({ userdata }) {
  document.title = userdata.user_Information.ed_user_account_name;
  const [CurrentTab, SetCurrentTab] = useState(0);
  const Data = userdata.user_Information;
  let lettername = '';

  if (Data?.ed_user_account_name) {
    const nameParts = Data.ed_user_account_name.trim().split(/\s+/);
  
    const firstInitial = nameParts[0]?.[0]?.toUpperCase() || '';
    const lastInitial = nameParts[nameParts.length - 1]?.[0]?.toUpperCase() || '';
  
    lettername = firstInitial + lastInitial;
  }
  
  
  
    const [CoverImage, setCoverImage] = useState(null);
  const [ProfileImage, setProfileImage] = useState(null);

  const SwitchTab = (e) => {
    SetCurrentTab(e);
  }


  const FORMURL = [
    Hoot() + "eduallprofilepictureupdate/update",
    Hoot() + "eduallprofilecoverimageupdate/update"
  ];


  const InputImageCoverChange = (e) => {
    if (e !== null & e.target.files.length >= 1) {
      console.clear();
      console.log(e.target.files[0]);
      setCoverImage(e.target.files[0]);
    } else {
      toast.error("Lamentamos mas não foi  possivel executar esta ação");
    }
  }


  const InputImageProfileChange = (e) => {
    if (e !== null & e.target.files.length >= 1) {
      console.clear();
      console.log(e.target.files[0]);
      setProfileImage(e.target.files[0]);
    }
  }


  const UpdateProfileCoverImage = async () => {
    if (CoverImage !== null) {
      const formData = new FormData();
      formData.append("user_account_profile_cover", CoverImage);
      try {
        axios.put(FORMURL[1], formData).then(() => {
          toast.success("Imagem atualizada com sucesso !");
        }).catch((error) => {
          toast.error("Lamentamos mas não foi  possivel executar esta ação");
        });
      } catch (error) {
        console.log(error);
        toast.error("Lamentamos mas não foi  possivel executar esta ação");
      }
    } else {
      toast.error("Selecione uma imagem de fundo !");
    }
  }


  const UpdateProfileImage = async () => {
    if (ProfileImage !== null) {
      const formData = new FormData();
      formData.append("user_account_picture", ProfileImage);

      try {
        axios.put(FORMURL[0], formData).then(() => {
          toast.success("Imagem atualizada com sucesso !");
        }).catch((error) => {
          toast.error("Lamentamos mas não foi  possivel executar esta ação");
        });
      } catch (error) {
        console.log(error);
        toast.error("Lamentamos mas não foi  possivel executar esta ação");
      }
    } else {
      toast.error("Selecione uma imagem de fundo !");
    }
  }



  return (
    <div className='eduall-network'>
      <UserNavbar data={userdata} />
      <div className="d-flex">
        <Container>
          <Profile>
            <div className="cover">
              <div className="cover-wall">

                <div className="wall">
                  <ImageLazyLoading height={400}
                    source={(CoverImage !== null) ? URL.createObjectURL(CoverImage) : (Hoot() + Data.ed_user_account_detProfileCover)}
                    alt="eduall" />
                </div>

              </div>
              <div className="cover-over">
                <div className="ed-wrapper">
                  <div className="cover-over-top">
                    <div>
                    </div>
                    <div className="ed-flex">
                      <div className="profile-user-options">
                        <>
                          <label htmlFor="ed-user-cover-image">
                            <div className="ed-flex"><div className="mr-2"><FiImage /></div> Trocar imagem de fundo</div>
                          </label>
                          <input type="file" onChange={InputImageCoverChange} hidden name="ed-user-cover-image" id="ed-user-cover-image" />
                        </>
                        {CoverImage !== null ? <button className="bg-main btn ml-2" onClick={(e) => UpdateProfileCoverImage(e)}>Salvar</button> : <></>}
                      </div>
                    </div>
                  </div>

                </div>
              </div>
            </div>
            <div className="ed-wrapper">
              <div className="profile-user-dets ed-flex">
                <div className="avatar-pic">
                  <>
                    <label htmlFor="user_account_picture">
                      <div className="ed-user-picture-image-label">
                        <FiImage />
                      </div>
                    </label>
                    {ProfileImage !== null ? <button className="bg-main save-pic-btn btn ml-2" onClick={() => UpdateProfileImage()}>Salvar</button> : <></>}
                    <input type="file" onChange={InputImageProfileChange} hidden name="user_account_picture" id="user_account_picture" />
                  </>
                  <Avatar alt={Data.ed_user_account_name} src={(ProfileImage !== null) ? URL.createObjectURL(ProfileImage) : (Hoot() + Data.ed_user_account_picture)}
                    sx={{ width: 150, height: 150, bgcolor: Data.ed_user_account_detAvatarColor }}>{lettername}
                  </Avatar>
                </div>
                <div className="ed-space">
                  <div className="name ml-2">
                    <strong><h5>{Data.ed_user_account_name}</h5></strong>
                    <div className="mt-2"><small>{Data.ed_user_account_email}</small></div>
                  </div>
                  <div>
                    <Link to="/settings">
                      <div className='settings-icon'>
                        <LiaCogSolid />
                      </div>
                    </Link>
                  </div>
                </div>
              </div>
              <div className="tabs-menu ed-space">
                <ul>
                  <li onClick={() => SwitchTab(0)} className={CurrentTab === 0 ? 'active' : ''}>Visão geral</li>
                  <li onClick={() => SwitchTab(1)} className={CurrentTab === 1 ? 'active' : ''}>Publicações</li>
                  <li onClick={() => SwitchTab(2)} className={CurrentTab === 2 ? 'active' : ''}>Galeria</li>
                  <li onClick={() => SwitchTab(4)} className={CurrentTab === 4 ? 'active' : ''}>Seguidores</li>
                  <li onClick={() => SwitchTab(4)} className={CurrentTab === 4 ? 'active' : ''}>Seguidores</li>
                </ul>
              </div>
            </div>
          </Profile>
          <BlockBox>
            <div className="ed-wrapper">
              <Content>
                <ProfileContainer>
                  <Block className={CurrentTab === 0 ? 'active' : 'd-none'} >
                    <ProfileGlobal data={userdata} info={Data} />
                  </Block>
                  <Block className={CurrentTab === 1 ? 'active' : 'd-none'} >
                    <h1>calendario</h1>
                  </Block>
                  <Block className={CurrentTab === 2 ? 'active' : 'd-none'} >
                    <h1>Actividades</h1>
                  </Block>
                  <Block className={CurrentTab === 3 ? 'active' : 'd-none'} >
                    <h1>Solicitações </h1>
                  </Block>
                  <Block className={CurrentTab === 4 ? 'active' : 'd-none'} >
                    <h1>publicações </h1>
                  </Block>
                  <Block className={CurrentTab === 5 ? 'active' : 'd-none'} >
                    <h1>Extratos </h1>
                  </Block>
                </ProfileContainer>
              </Content>
            </div>
          </BlockBox>
        </Container>
      </div>
    </div>
  )
}


const Container = styled.div` 
    width:100%;  
`;

const BlockBox = styled.div` 
     width:100%;
     padding:0px 20px;
`;

const Content = styled.div`
  display:flex;
  width:100%; 
  padding-top:20px;
  background:var(--ed-background-color);  


  h1.title{
    position:relative;
    margin:0px;
    width:max-content;
    font-size:18px;
    color:var(--ed-dark);
    font-weight:bold;
    display:block; 
  }
`;

const Block = styled.div` 
  display:block; 
  width:100%;
`

const ProfileContainer = styled.div`
    width:100%;  
`;

const Profile = styled.div` 
     width:100%;
     margin-top:70px; 
     padding:20px;
     margin-bottom:20px; 
     box-shadow:var(--ed-shadow-df);
     overflow:hidden;
     background:var(--ed-white);



.profile-user-dets{
    padding:0px 20px;
}

.settings-icon svg{
    font-size:30px;
    color:var(--ed-dark);
    margin:0px !important;
}

.settings-icon{
   width:50px;
   height:50px;
   border:1px solid var(--ed-silver-light);
   display:flex;
   align-items:center;
   justify-content:center;
   border-radius:100%;
   cursor:pointer;
}


    .name{
      margin-left:30px;
      margin-top:20px;  
      z-index:100;
      position:relative;

       h5{
          font-size:18px;
          color:var(--ed-dark);
          font-weight:600;
       }

       small{
          color:var(--ed-grey-text);
          font-size:16px;
       }
  }


    .ed-user-picture-image-label{
        width:40px;
        height:40px;
        display:flex;
        align-items:center;
        justify-content:center; 
        position:absolute;
        right:6px;
        top:30px;
        z-index:100;
        border-radius:100%;
        cursor:pointer;
        background:#000; 
        color:var(--ed-white);

          svg{
              width:18px;
              height:18px;
          }
    }

    .avatar-pic{
        margin-top:-100px; 
        width:155px;
        height:155px;
        position:relative;

        .save-pic-btn{
             position:absolute;
             top:-35px;
             left:0px;
             min-width:130px;
             text-align:center;
        }

          .MuiAvatar-root{
              border:6px solid var(--ed-white);
              box-shadow:var(--ed-shadow-df);
          }
    }






 
     .tabs-menu{
        padding:5px;      
        width:100%;
        min-height:80px; 

         ul{
            margin:0px;
            display:flex;
            align-items:center;
            margin-top:10px;

             li{ 
                transition:all 1s ease-in-out;
                margin-right:20px;
                font-weight:500;
                cursor:pointer;
                color:var(--ed-dark); 
                padding:10px 20px; 
                border-radius:6px;
                cursor:pointer; 
                display:flex;
                align-items:center;
                border:1px solid  #eaeaee;
             }

             li.active{
                color:var(--ed-white); 
                background:var(--ed-purple-light); 
             }
         }
     }

     .cover{
        width:100%;
        height:400px;
        position:relative;  
        overflow:hidden;
        border-radius:20px;


        @media screen and (max-width:1280px){
            height:400px;
        }


        .cover-over{
            background:var(--ed-trp-1);
            position:absolute; 
            top:0px;
            left.0px;
            width:100%;
            height:100%;
            padding:20px;


               .cover-over-top{
                  position:absolute;
                  padding:0px 20px;
                  left:0px;
                  top:20px;
                  width:100%;
                  display:flex;
                  justify-content:space-between;

                
                
                .profile-user-options .ed-flex{
                    padding:10px 15px;
                    cursor:pointer;
                    background:var(--ed-trp-6);
                    color:var(--ed-white);
                    font-size:15px;
                    border-radius:6px;

                    svg{
                        width:18px;
                        height:18px;
                     }
                  }
               }

               .cover-over-bottom{
                  width:100%;
                  position:absolute;
                  bottom:0px;
                  left:0px;
                  padding:0px 20px;

                    .cover-over-details{
                        width:100%;
                        display:flex;
                        justify-content:space-between;
                        align-items:flex-end; 
                        position:relative;

                      

                        .profile-user-options{
                            margin-bottom:20px;
                            display:flex;

                              .btn{
                                 background:var(--ed-white);
                                 color:var(--ed-purple) !important;
                                 font-size:15px; 

                                   
                              }
                        }






                    }
               }
        }
                
         .cover-wall{
            height:100%;  

           .wall {
            height:100%; 
              img{
                 width:100%;
                 height:100%;
                 object-fit:cover; 
                 background:var(--ed-purple);
              }
           }
         }
     }
`;

export default PersonalProfile