import React, { useState, useRef } from 'react';
import { FaCamera, FaSave, FaTimes, FaCrop } from 'react-icons/fa';
import Button from 'react-bootstrap/Button';
import Modal from 'react-bootstrap/Modal';
import styled from 'styled-components';
import { Cropper } from 'react-cropper';
import { IoCameraOutline, IoSaveOutline, IoCropOutline } from "react-icons/io5";

const generateRandomFilename = (length = 10) => {
    const characters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    return Array.from({ length }, () => characters[Math.floor(Math.random() * characters.length)]).join('');
};

function PictureModal(props) {
    const [show, setShow] = useState(false);
    const [cropMode, setCropMode] = useState(false);
    const [imageSrc, setImageSrc] = useState(null);
    const VideoRef = useRef(null);
    const PhotoRef = useRef(null);
    const CropperRef = useRef(null);
    const [hasPhoto, setHasPhoto] = useState(false);

    const handleClose = () => {
        setShow(false);
        setHasPhoto(false);
        setImageSrc(null);
        setCropMode(false);
    };

    const GetVideo = () => {
        navigator.mediaDevices.getUserMedia({ video: { width: 1980, height: 1080 } })
            .then(stream => {
                let video = VideoRef.current;
                if (video) {
                    video.srcObject = stream;
                    video.play();
                }
            })
            .catch(err => console.error("Erro ao acessar a câmera:", err));
    };

    const handleShow = () => {
        setShow(true);
        GetVideo();
    };

    const TakePhoto = () => {
        const width = 414;
        const height = width / (16 / 9) + 100;
        let video = VideoRef.current;
        let photo = PhotoRef.current;

        if (!video || !photo) {
            console.error("Erro: Elementos de vídeo ou canvas não encontrados.");
            return;
        }

        photo.width = width;
        photo.height = height;

        let ctx = photo.getContext("2d");
        if (!ctx) {
            console.error("Erro: Contexto 2D não disponível.");
            return;
        }

        ctx.drawImage(video, 0, 0, width, height);
        const imageDataUrl = photo.toDataURL("image/png");

        setImageSrc(imageDataUrl);
        setHasPhoto(true);
        setCropMode(true);
    };

    const handleCrop = () => {
        if (CropperRef.current) {
            const croppedCanvas = CropperRef.current.cropper.getCroppedCanvas();
            if (croppedCanvas) {
                const croppedImage = croppedCanvas.toDataURL("image/png");
                setImageSrc(croppedImage);
                setCropMode(false);
            }
        }
    };

    const handleSave = () => {
        if (!imageSrc) return;

        fetch(imageSrc)
            .then(res => res.blob())
            .then(blob => {
                const filename = `eduall_picture_${generateRandomFilename(15)}.png`;
                const file = new File([blob], filename, { type: "image/png" });

                props.Picture(file, imageSrc);
                handleClose();
            })
            .catch(err => console.error("Erro ao salvar a imagem:", err));
    };

    return (
        <div>
            <div>
                {props.toggle_btn ? (
                    <div onClick={handleShow}>{props.toggle_btn}</div>
                ) : (
                    <button onClick={handleShow} className="btn bg-main">
                        <FaCamera /> Fotografar
                    </button>
                )}
            </div>
            <Modal size="lg" centered show={show} onHide={handleClose} backdrop="static" keyboard={false}>
                <Modal.Header closeButton>
                    <Modal.Title><h5> Câmera Fotográfica</h5></Modal.Title>
                </Modal.Header>
                <Modal.Body>
                    <CaptureBox>
                        {!hasPhoto && <video ref={VideoRef}></video>}
                        {hasPhoto && !cropMode && <img src={imageSrc} alt="Captured" style={{ width: '100%' }} />}
                        {cropMode && (
                            <Cropper
                                ref={CropperRef}
                                src={imageSrc}
                                style={{ height: 400, width: "100%" }}
                                aspectRatio={1} // Change aspect ratio as needed
                                guides={false}
                            />
                        )}
                        {/* Adicionado Canvas ao DOM */}
                        <canvas ref={PhotoRef} style={{ display: "none" }}></canvas>
                    </CaptureBox>
                </Modal.Body>
                <Modal.Footer>
                    {!hasPhoto ? (
                        <button className="btn bg-main" onClick={TakePhoto}>
                            <IoCameraOutline /> Capturar
                        </button>
                    ) : cropMode ? (
                        <button className="btn bg-main" onClick={handleCrop}>
                            <IoCropOutline /> Ajustar
                        </button>
                    ) : (
                        <>
                            <button className="btn bg-danger" onClick={handleClose}>
                                <FaTimes /> Cancelar
                            </button>
                            <button className="btn bg-main" onClick={handleSave}>
                                <IoSaveOutline /> Salvar
                            </button>
                        </>
                    )}
                </Modal.Footer>
            </Modal>
        </div>
    );
}

 
const CaptureBox = styled.div`
    height:400px;
    width:100%;
    border:2px dotted var(--ed-silver);
    border-radius:6px;
    position:relative;
    background:var(--ed-background-color); 
    overflow:hidden;

    video{
         width:100%;
         height:100%;
         background:var(--ed-dark);
    }

    canvas{
        display:none;
        background:var(--ed-white); 
        width:160px;
        height:120px;
        border:2px dotted var(--ed-silver); 
        border-radius:6px;
    }   

    .pop{
        display:flex;
        align-items:center;
        position:absolute;
        top:20px;
        right:20px;

        .block{
            padding-right:15px;

            .btn{
                width:30px;
                height:30px;
                border-radius:100%;
                display:flex;
                align-items:center;
                justify-content:center;

                  svg{
                      margin:0px !important;
                      width:18px;
                      height:18px;
                  }
            }

             .btn.bg-blue{
                 margin-top:10px;
                 background:var(--ed-blue) !important;
             }
        }

         canvas{
              display:block;
         }
    }
`;


export default PictureModal; 