import React, { useState } from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap'
import { Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import { toast } from 'react-hot-toast';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import { Update } from '@material-ui/icons';
import { GetInstituteCode } from '../../../General/components/InstituteData';
import RefreshList from '../../../General/components/RefreshList';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import { MultiSelect } from 'react-multi-select-component';
import { Options } from 'react-ionicons';
import styled from 'styled-components';
import { RichTextEditor } from '../../../General/components/RichTextEditor';

function CalendarEventModal(props) {
    const [show, setShow] = useState(false);
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [SelectedColor, setSelectedColor] = useState(null);
    const [Founded, SetFounded] = useState(null);
    const [Select, setSelected] = useState([]);
    const [Audience, setAudience] = useState(null);
    const [showBox, SetshowBox] = useState(false);
    const handleClose = () => {
        SetshowBox(false);
        setTimeout(() => {
            setShow(false);
        }, 1200);
    }

    const handleShow = () => {
        SetshowBox(true);
        setShow(true);
        setTimeout(() => {
            GET_DATA();
        }, 1000);
    };


    const [form, setForm] = useState({});
    const [errors, setErrors] = useState({});

    const AudienceOptions = [
        { label: "Encarregados de educação", value: 1 },
        { label: "Estudantes", value: 2 },
        { label: "Funcionários", value: 3 },
    ]


    const FORMURL = [
        Hoot() + "eduallcalendarevenregister/post",
        props.get ? props.get : '',
        props.url ? props.url : '',
    ];


    const INPUTS = {
        event_title: CRValue("#event_title"),
        event_start: CRValue("#event_start"),
        event_end: CRValue("#event_end"),
        event_audience: Audience,
        event_color: SelectedColor,
        event_description:CRValue(".modal form #event_description") 
    };



    const GET_DATA = async () => {
        if (props.update) {
            try {
                const response = await axios.get(FORMURL[1]);
                if (response.data.length > 0) {
                    document.querySelector("#event_title").value = response.data[0].ed_calendar_event_title;
                    INPUTS.event_title = response.data[0].ed_calendar_event_title;

                    document.querySelector("#event_start").value = response.data[0].ed_calendar_event_start;
                    INPUTS.event_start = response.data[0].ed_calendar_event_start;

                    document.querySelector("#event_end").value = response.data[0].ed_calendar_event_end;
                    INPUTS.event_end = response.data[0].ed_calendar_event_end; 
                  

                    setSelectedColor(response.data[0].ed_calendar_event_color);
                    INPUTS.event_color = response.data[0].ed_calendar_event_color;

                    document.querySelector(".modal form textarea").value = response.data[0].ed_calendar_event_description;
                    INPUTS.event_description = response.data[0].ed_calendar_event_description;



                    console.clear();
                    let audience = []; 
                    let NewAudience = []; 
                    var options = ""; 
                    let dt = response.data[0].ed_calendar_event_audience.split(",");
                    setTimeout(() => { 
                        if (response.data[0].ed_calendar_event_audience * 1 >= 0) {
                            audience.push(AudienceOptions[response.data[0].ed_calendar_event_audience * 1]);
                        } else { 
                            for(let i = 0; i < dt.length; i++){ 
                                if ((dt[i] * 1) > 0 && (dt[i]*1)!== NaN) audience.push(dt[i] * 1);
                            }

                            for(let i = 0; i < audience.length; i++){
                                for(let a = 0; a < AudienceOptions.length; a++){
                                   if(audience[i] === AudienceOptions[a].value){
                                        NewAudience.push(AudienceOptions[a]);
                                   }
                                }
                            }
                        }

                        setSelected(NewAudience); 
                        for (let i = 0; i < dt.length; i++) { 
                           if ((dt[i] * 1) > 0 && (dt[i]*1)!== NaN){
                              options += "," + dt[i];
                           }
                        }
                        setAudience(options); 
                    }, 500);

                      

           
                    
                } else {
                    toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
                }
            } catch (error) {
                console.clear()
                console.log(error);
                toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
            }
        }
    }

    const setField = (field, value) => {
        setForm({
            ...form,
            [field]: value
        })

        if (!!errors[field]) {
            setErrors({
                ...errors,
                [field]: null
            });
        }
    }


    function selectedAudience(e) {
        setSelected(e);
        console.clear();
        console.log(e);
        setField("event_audience", "audience");
        var options = "";
        for (let i = 0; i < e.length; i++) { options += "," + e[i].value; }
        setAudience(options);
        console.clear();
        console.log(" audicence", e)
    }



    const validateForm = () => {
        const { event_title, event_audience, event_start, event_end } = form;
        const NewErrors = {};
        setRegisterStatus(0);

        if (INPUTS.event_title === "" || INPUTS.event_title === " ") {
            if (!event_title || event_title === '') NewErrors.event_title = `Titulo invalido`;
        } else { if (!event_title) { setField("event_title", INPUTS.event_title); } }

        if (INPUTS.event_start === "" || INPUTS.event_start === " ") {
            if (!event_start || event_start === '') NewErrors.event_start = `Data invalida`;
        } else { if (!event_start) { setField("event_start", INPUTS.event_start); } }

        if (INPUTS.event_end === "" || INPUTS.event_end === " ") {
            if (!event_end || event_end === '') NewErrors.event_end = `Data invalida`;
        } else { if (!event_end) { setField("event_end", INPUTS.event_end); } }

        if (INPUTS.event_audience === "" || INPUTS.event_audience === " ") {
            if (!event_audience || event_audience === '') NewErrors.event_audience = `Selecione uma audiencia valida`;
        } else { if (!event_audience) { setField("event_audience", INPUTS.event_audience); } }

        return NewErrors;
    }


    const FormSubmit = (e) => {
        console.log(INPUTS);
        e.preventDefault();
        const formErrors = validateForm();
        if (Object.keys(formErrors).length > 0) {
            setErrors(formErrors);
            toast.error("Verifique todos os  campos !");
            setRegisterStatus(1);
        } else {
            const SUBMIT_INPUTS = {
                cev_audience: INPUTS.event_audience,
                cev_title: INPUTS.event_title,
                cev_color: INPUTS.event_color,
                cev_start: INPUTS.event_start,
                cev_end: INPUTS.event_end,
                cev_description: INPUTS.event_description,
            };

            if (!props.update) {
                try {
                    axios.post(FORMURL[0], SUBMIT_INPUTS).then(() => {
                        toast.success("Evento adicionado ao calendário com sucesso !");
                        setForm({});
                        ClearInputs();
                        RefreshList(`.el-refresh-list`)
                        setRegisterStatus(2);
                    }).catch((error) => {
                        console.clear()
                        console.log(error.response);
                        toast.error("Lamentamos mas não foi  possivel executar esta ação !");
                        setRegisterStatus(1);
                    });
                } catch (error) {
                    console.clear()
                    console.log(error.response);
                    toast.error("Lamentamos mas não foi  possivel executar esta ação !");
                    setRegisterStatus(1);
                }
            } else {
                try {
                    axios.put(FORMURL[2], SUBMIT_INPUTS).then(() => {
                            toast.success("Evento atualizado com sucesso !");
                            setForm({});
                            ClearInputs();
                            RefreshList(`.el-refresh-list`)
                            setRegisterStatus(2);
                            setTimeout(() => {
                                handleClose();
                            }, 1000);
                        }).catch((error) => {
                            console.clear()
                            console.log(error.response);
                            toast.error("Lamentamos mas não foi  possivel executar esta ação !");
                            setRegisterStatus(1);
                        });
                } catch (error) {
                    console.clear()
                    console.log(error.response);
                    toast.error("Lamentamos mas não foi  possivel executar esta ação !");
                    setRegisterStatus(1);
                }
            }
        }
    };


    const handleInput = (e) => {
        switch (e.target.id) {
            case "event_title":
                setField("event_title", e.target.value);
                INPUTS.event_title = e.target.value;
                break;
            case "event_start":
                setField("event_start", e.target.value);
                INPUTS.event_start = e.target.value;
                break;
            case "event_end":
                setField("event_end", e.target.value);
                INPUTS.event_end = e.target.value;
                break;
            case "event_description":
                setField("event_description", e.target.value);
                INPUTS.event_description = e.target.value;
                break;
            case "event_audience":
                setField("event_audience", e.target.value);
                INPUTS.event_audience = e.target.value;
                break;
            default:
        }
    }


    return (
        <div>
            <div>
                <div onClick={handleShow}>
                    {
                        props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon /> Adicionar evento</button>
                    }
                </div>
                <Modal size='lg' dialogAs={DraggableModal} centered className={showBox ? ModalAnimationShow() : ModalAnimationClose()} show={show} onHide={handleClose}>
                    <Modal.Header closeButton>
                        <Modal.Title>
                            <div className="ed-wrap align-center">
                                <UserOptionDropDown />
                                <h5>{props.title ? props.title : 'Adicionar '} evento</h5>
                            </div>
                        </Modal.Title>
                    </Modal.Header>
                    <Form onSubmit={FormSubmit}>
                        <Modal.Body className='scrollLimit'>
                            <Form.Group className="mb-3"  >
                                <Form.Label>Audiencia<span className="text-danger ml-2">*</span> </Form.Label>
                                <MultiSelect options={AudienceOptions} value={Select} labelledBy='select'
                                    className={errors.feepayment_months ? 'border-red' : ''} onChange={selectedAudience} />
                                <Form.Control.Feedback type='invalid'>{errors.event_audience}</Form.Control.Feedback>
                            </Form.Group>
                            <Form.Group className="mb-3"  >
                                <Form.Label>Titulo<span className="text-danger ml-2">*</span> </Form.Label>
                                <Form.Control type="text" onChange={handleInput} className={!!errors.event_title && 'is-invalid'} value={form.event_title}
                                    isInvalid={!!errors.event_title} id="event_title" />
                                <Form.Control.Feedback type='invalid'>{errors.event_title}</Form.Control.Feedback>
                            </Form.Group>
                            <div className="ed-flex ed-space">
                                <div className="col">
                                    <Form.Group className="mb-3"  >
                                        <Form.Label>Inicio <span className="text-danger ml-2">*</span></Form.Label>
                                        <Form.Control type="datetime-local" onChange={handleInput} className={!!errors.event_start && 'is-invalid'} value={form.event_start}
                                            isInvalid={!!errors.event_start} id="event_start" />
                                        <Form.Control.Feedback type='invalid'>{errors.event_start}</Form.Control.Feedback>
                                    </Form.Group>
                                </div>
                                <div className="pd-1"></div>
                                <div className="col">
                                    <Form.Group className="mb-3"  >
                                        <Form.Label>Fim <span className="text-danger ml-2">*</span></Form.Label>
                                        <Form.Control type="datetime-local" onChange={handleInput} className={!!errors.event_end && 'is-invalid'} value={form.event_end}
                                            isInvalid={!!errors.event_end} id="event_end" />
                                        <Form.Control.Feedback type='invalid'>{errors.event_end}</Form.Control.Feedback>
                                    </Form.Group>
                                </div>
                            </div>
                            <Colors>
                                {["#FCBF49", "#FFA69E", "#9F86C0", "#80ED99", "#4895EF", "#FE6D73", "#D4A373", "#D6CCC2", "#E0B1CB"].map((color, index) => (
                                    <li onClick={() => setSelectedColor(color)} className={`${SelectedColor === color ? "selected" : ""}`}
                                        key={index} style={{ backgroundColor: `${color}` }}></li>
                                ))}
                            </Colors>
                            <Form.Group className="mb-3 mt-3"  >
                                <Form.Label>Descrição </Form.Label>
                                 <div className="custom-editor">
                                     <textarea name="" id="event_description" rows={10} className="form-control"></textarea>
                                 </div>
                                <Form.Control.Feedback type='invalid'>{errors.description}</Form.Control.Feedback>
                            </Form.Group>
                        </Modal.Body>
                        <Modal.Footer>
                            <div className="ed-space">
                                <div className="ed-flex"></div>
                                <div className="ed-flex">
                                    <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                                    {props.update ? (Founded === false ? <div></div> :
                                        <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
                                        <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />}
                                </div>
                            </div>
                        </Modal.Footer>
                    </Form>
                </Modal>
            </div>
        </div>
    )
}


const Colors = styled.div` 
    margin:10px 0px;
    padding:0px;
    display:flex;
    align-items:center;
    flex-wrap:wrap;


     li{
         width:35px;
         height:35px;
         border-radius:100%;
         margin-right:10px;
         cursor:pointer;
         list-style:none;
         border:3px solid var(--white);
         box-shadow:var(--ed-shadow-1);
     }

     li.selected{
       border-color:var(--ed-dark);
       transform:scale(1.1);
     }
`;

export default CalendarEventModal 
