import React, { useState } from 'react'
import UserParentsAccountsTable from '../components/Table/UserParentsAccountsTable';
import { AddCircleOutline, Delete, Description, Edit ,OpenInBrowser, Refresh, Search } from '@mui/icons-material';
import { Link } from 'react-router-dom'; 
import { Form } from 'react-bootstrap';
import NewParentAccountModal from '../components/modal/NewParentAccountModal';

function UserParentsAccounts() {
  document.title  =  "Contas de encarregado";
  const [value, setValue] = useState(null);

  return (
    <div> 
      <div className="ed-space">
        <div>
        <Form>
              <div className='search-box'>
              <Form.Group>
                    <div className="ed-flex m0 fill">
                     <Search/>
                        <div className="block col ml-2"> 
                            <Form.Control  type="text" onChange={(e)=>setValue(e.target.value)} placeholder="Pesquisar ..."  autoFocus /> 
                        </div> 
                    </div> 
               </Form.Group> 
              </div>
            </Form>
        </div>
          <div> 
             <NewParentAccountModal /> 
          </div> 
      </div>
      <UserParentsAccountsTable  FilterByName={value} />      
    </div>
  )
}

export default UserParentsAccounts