import FloorNumber from './FloorNumber';

export default function CalculateNote (p1, p2, exam, specialexam, typeOfMath){
    // typeOfMath  0 = result between p1 and p2  / md
    // typeOfMath  1 = result between md and exam / res
    // typeOfMath 2 = result between  res and specialexam / fn
    // typeOfMath 3 = show final status 0-1

    const md = FloorNumber((p1+p2) / 2);
    const res =  FloorNumber((md + exam) / 2);
    const fn =  specialexam;

    if(typeOfMath === 0){
        return md;
    }else if(typeOfMath === 1){ 
      return  res; 
    }else if(typeOfMath === 2){
        return fn
    }else  if(typeOfMath === 3){ 
      if(md <= 13){ 
        if(res < 10){
            if(res <= 7  || res <= 9 ){
              if(fn < 10){
                return 1; // false
             }else{
               return 0; /// true      
             }
            }else{
              return 1; /// false
            }
        }else{
           return 0; /// true
        } 
      }else{
        return 0; /// true
      } 
    }
  }