const PT_WEEKDAYS_MIN = ["2ª", "3ª", "4ª", "5ª", "6ª", "Sáb", "Dom"];
const toMonFirst = (dow) => (dow + 6) % 7;
const daysInMonth = (y, m) => new Date(y, m + 1, 0).getDate();
const pad2 = (n) => String(n).padStart(2, "0");
const dateKey = (d) => `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`;

function buildMonthMatrix(year, month) {
  const matrix = [];
  const first = new Date(year, month, 1);
  const firstDow = toMonFirst(first.getDay());
  const lastDay = daysInMonth(year, month);
  const prevMonth = (month + 11) % 12,
    prevYear = month === 0 ? year - 1 : year,
    prevLast = daysInMonth(prevYear, prevMonth);
  let dayCounter = 1;
  for (let w = 0; w < 6; w++) {
    const week = [];
    for (let d = 0; d < 7; d++) {
      const idx = w * 7 + d;
      let inMonth = true,
        y = year,
        m = month,
        day;
      if (idx < firstDow) {
        inMonth = false;
        m = prevMonth;
        y = prevYear;
        day = prevLast - (firstDow - idx - 1);
      } else if (idx >= firstDow + lastDay) {
        inMonth = false;
        m = (month + 1) % 12;
        y = month === 11 ? year + 1 : year;
        day = idx - (firstDow + lastDay) + 1;
      } else {
        day = dayCounter++;
      }
      week.push({ date: new Date(y, m, day), inMonth });
    }
    matrix.push(week);
  }
  return matrix;
}

