const hexToARGB = (h) => "FF" + h.replace("#", "").toUpperCase();
function mapFillARGB(absenceTypes) {
  const o = {};
  absenceTypes.forEach((t) => {
    o[t.key] = { bg: hexToARGB(t.bg) };
  });
  return o;
}
async function loadImageBase64(url) {
  try {
    const res = await fetch(url, { mode: "cors" });
    const blob = await res.blob();
    return new Promise((resolve, reject) => {
      const fr = new FileReader();
      fr.onloadend = () => resolve(String(fr.result).split(",")[1]);
      fr.onerror = reject;
      fr.readAsDataURL(blob);
    });
  } catch (e) {
    console.warn("Logo falhou:", e);
    return null;
  }
}
function writeLegendBlock(ws, startRow, startCol, legendCols, absenceTypes, title = "Categorias") {
  ws.mergeCells(startRow, startCol, startRow, startCol + legendCols - 1);
  const head = ws.getCell(startRow, startCol);
  head.value = title;
  head.font = { name: "Poppins", size: 12, bold: true, color: { argb: "FF2E2F33" } };
  head.alignment = { vertical: "middle", horizontal: "left" };
  ws.getRow(startRow).height = 20;

  let r = startRow + 1;
  absenceTypes.forEach((t) => {
    const colorCell = ws.getCell(r, startCol);
    colorCell.value = "";
    colorCell.fill = { type: "pattern", pattern: "solid", fgColor: { argb: hexToARGB(t.bg) } };
    colorCell.border = {
      top: { style: "thin", color: { argb: "FFFFFFFF" } },
      left: { style: "thin", color: { argb: "FFFFFFFF" } },
      bottom: { style: "thin", color: { argb: "FFFFFFFF" } },
      right: { style: "thin", color: { argb: "FFFFFFFF" } },
    };
    ws.mergeCells(r, startCol + 1, r, startCol + legendCols - 1);
    const labelCell = ws.getCell(r, startCol + 1);
    labelCell.value = t.label;
    labelCell.font = { name: "Poppins", size: 11, color: { argb: "FF2E2F33" } };
    labelCell.alignment = { vertical: "middle", horizontal: "left" };
    ws.getRow(r).height = 18;
    r++;
  });

  ws.getColumn(startCol).width = 3.0;
  for (let c = 1; c < legendCols; c++) ws.getColumn(startCol + c).width = 16;
  return r;
}

