import React , {useState, useEffect} from 'react'
import { Avatar } from '@mui/material'; 
import { Link } from 'react-router-dom'; 
import axios from 'axios';
import { Delete, Description, Edit, PreviewOutlined, Refresh} from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot'; 
import DeleteModal from '../elements/DeleteModal';
import TableGrid from '../../../General/components/TableGrid';
import { Badge } from 'react-bootstrap';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import { GetJobTitle } from '../../../General/components/InstituteData';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import NewTeacherAccountModal from '../modal/NewTeacherAccountModal';

const TABLEURL = Hoot()+"eduallgetalluserinstitutes/get";

 

const columns = [ 
  { field: 'index',
   headerName: 'Nº',  
   width:90,
   resizable: true, 
  },
  {
    field: 'name',
    headerName: 'Nome do funcionário', 
    resizable: true, 
    minWidth:300,
    cellRenderer:(props)=>{
       return      <div className='ed-flex'>
         <Avatar className='df' alt={props.data.name}   src={props.data.picture !==""  ?  Hoot()+props.data.picture : ""} /> 
         <span className='ml-2'>{props.data.name}</span>
       </div> 
    }
  }, 
  {
    field: 'accountemail',
    headerName: 'Conta eduall', 
    resizable: true, 
    minWidth:300, 
  },   
  {
    field: 'action',
    headerName: 'Ação', 
     resizable: true, 
     width:90,
     cellRenderer:(props) => { 
      return <div className="ed-flex"> 
          <DeleteModal title='esta conta' url={Hoot()+`edualldeleteuserinstitutes/delete/${props.data.id}`} 
           message={'Conta deletado com sucesso'+props.data.id} toggle_btn={
            <button  className="btn-circle bg-danger text-light">
               <Delete/>
            </button>
           }/> 
        </div> ;
    }
  } 
];



function TeacherAccountsTables() {
    const [data, setData] = useState([]);
    const [load, setLoaded] = useState(false);
    const [LoadStatus, setLoadStatus] = useState(null);

    async function loadData(){
       try {
         setLoaded(false); 
         setLoadStatus(0); 
         const response = await axios.get(TABLEURL); 
           const rows = []; 
           response.data.map((item, index)=>{  
                 rows.push({
                 index:index+1,
                 id:item.ed_user_institute_id,
                 name:item.ed_employee_name,
                 picture:item.ed_employee_picture,
                 status:item.ed_employee_status,
                 accountemail: item.ed_user_account_name,
                 charge:item.ed_employee_charge,
                gender:item.ed_employee_gender 
             }); 
         }); 
         setData(rows);
        setTimeout(() => {
          setLoaded(true); 
        }, 200);
        setLoadStatus(2); 
       } catch (error) {
        setLoadStatus(1); 
       }
    }
  
    useEffect(()=>{
        loadData(); 
    },[]);
  
  if(load){
      return (
      <div>
        <TableGrid
            TableHead={columns}
            TableBody={data} 
            TableTitle='Contas dos professores'
            TableBtn={
              <div className='ed-flex' >
              <button className='btn-icon btn btn-export-data ml-2' 
                 onClick={()=>ExportDataForTablesExcel("contas dos professores ", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
              </button>
             <RefreshButton action={loadData} status={LoadStatus} />
         </div>}
        />
    </div>
    )
  }else{
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
            TableHead={columns}
            TableBody={data} 
            TableTitle='Contas dos professores'
            TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
    </div>
    )
  }
}

export default TeacherAccountsTables;
