import { Delete, Edit } from '@mui/icons-material';
import React, { useEffect, useState } from 'react';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import { styled } from 'styled-components';
import ReactPaginate from 'react-paginate';
import ImageLazyLoading from '../../../General/components/ImageLazyLoading';
import NewBookEditModal from '../modal/NewBookEditModal';
import DeleteModal from '../elements/DeleteModal';

const URL = Hoot() + `edualllibrarybooks/get`;

function BooksGrid({ searchTerm }) {
    const [data, setData] = useState([]);

    async function loadData() {
        try {
            const response = await axios.get(URL);
            setData(response.data);
        } catch (error) {
            console.error("Erro ao carregar dados:", error);
        }
    }

    useEffect(() => {
        loadData();
    }, []);
 
    const filteredData = data.filter((book) => 
        book.ed_library_book_title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        book.ed_library_author_name.toLowerCase().includes(searchTerm.toLowerCase())
    );

    return (
        <div>
            <PaginatedItems itemsPerPage={15} data={filteredData} />
            <br />
        </div>
    );
}

function Items({ currentItems }) {
    return (
        <div className="ed-wrap library-books-grid mb-4">
            {currentItems &&
                currentItems.map((item) => (
                    <div className="book-card" key={item.ed_library_book_id}>
                        <ImageLazyLoading 
                            source={item.ed_library_book_picture ? Hoot() + item.ed_library_book_picture : ""} 
                            height={260} 
                            alt=""
                        />
                        <h3>{item.ed_library_book_title}</h3>
                        <div className="ed-flex">
                            <h5>Autor: <span>{item.ed_library_author_name}</span></h5>
                        </div>
                        <div className="ed-flex mt-2 classification">
                            <div className="ed-flex">
                                <NewBookEditModal 
                                    title='Atualizar' 
                                    update='true' 
                                    get={Hoot() + `eduallsinglelibrarybook/get/${item.ed_library_book_id}`}
                                    url={Hoot() + `edualllibrarybookupdate/update/${item.ed_library_book_id}`} 
                                    toggle_btn={
                                        <button className="btn-circle bg-success text-light">
                                            <Edit />
                                        </button>
                                    } 
                                />
                                <DeleteModal 
                                    title='Este livro' 
                                    url={Hoot() + `edualllibrarybookdelete/delete/${item.ed_library_book_id}`}
                                    message='Livro deletado com sucesso' 
                                    toggle_btn={
                                        <button className="btn-circle bg-danger ml-2">
                                            <Delete />
                                        </button>
                                    } 
                                />
                            </div>
                        </div>
                    </div>
                ))}
        </div>
    );
}

function PaginatedItems({ itemsPerPage, data }) {
    const [itemOffset, setItemOffset] = useState(0);
    const endOffset = itemOffset + itemsPerPage;
    
    const currentItems = data.slice(itemOffset, endOffset);
    const pageCount = Math.ceil(data.length / itemsPerPage);

    const handlePageClick = (event) => {
        const newOffset = (event.selected * itemsPerPage) % data.length;
        setItemOffset(newOffset);
    };

    return (
        <>
            <Items currentItems={currentItems} />
            <div className="ed-space mr-2">
                <div >
                    <Title>{data.length} items encontrados na lista</Title>
                </div>
                <div>
                    <div className="paginate box">
                        <ReactPaginate
                            breakLabel="..."
                            nextLabel=" > "
                            onPageChange={handlePageClick}
                            pageRangeDisplayed={5}
                            pageCount={pageCount}
                            previousLabel=" < "
                            renderOnZeroPageCount={null}
                        />
                    </div>
                </div>
            </div>
        </>
    );
}

const Title = styled.h3`
    font-size: 18px;
    margin: 0px;
`;

export default BooksGrid; 