import React, { useEffect, useRef, useState, useCallback, useMemo } from "react";
import styled from "styled-components";
import axios from "axios";
import MockAdapter from "axios-mock-adapter";
import { v4 as uuid } from "uuid";
import { Virtuoso } from "react-virtuoso";
import { useDropzone } from "react-dropzone";
import { Offcanvas, Button } from "react-bootstrap";
import {
  TbSearch, TbInbox, TbPhotoPlus, TbMoodSmile, TbSend, TbDots,
  TbPointFilled, TbPhone, TbMapPin, TbCalendar, TbHash
} from "react-icons/tb";

/* -------------------------------------------------------------------------- */
/*                          MOCK + SOCKET SIMULADO                            */
/* -------------------------------------------------------------------------- */
const api = axios.create({ baseURL: "/mock" });
const mock = new MockAdapter(api, { delayResponse: 400 });
const listeners = new Map();
const socket = {
  on(ev, cb) { if (!listeners.has(ev)) listeners.set(ev, new Set()); listeners.get(ev).add(cb); return () => listeners.get(ev)?.delete(cb); },
  emit(ev, payload) { listeners.get(ev)?.forEach(cb => cb(payload)); }
};

const AVS = [
  "https://images.pexels.com/photos/220453/pexels-photo-220453.jpeg",
  "https://images.pexels.com/photos/415829/pexels-photo-415829.jpeg",
  "https://images.pexels.com/photos/712513/pexels-photo-712513.jpeg",
  "https://images.pexels.com/photos/614810/pexels-photo-614810.jpeg",
];
const ME = { id: "me", name: "Isaac Reed", email: "isaac@koala.com", avatar: AVS[3] };
const USERS = [
  { id: "u1", name: "Nathan Hale", email: "nathan@koala.com", phone:"+1 234 567 890", city:"Los Angeles, CA", avatar: AVS[0], company:{payroll:43,salary:"$48,640",active:4}, socials:{ig:"@nathan"} },
  { id: "u2", name: "Scarlett Harris", email: "scarlett@koala.com", phone:"+1 333 999 222", city:"Seattle, WA", avatar: AVS[1], company:{payroll:17,salary:"$62,310",active:2}, socials:{ig:"@scarlett"} },
  { id: "u3", name: "Dominic Scott", email: "dominic@koala.com", phone:"+1 444 111 555", city:"Austin, TX", avatar: AVS[2], company:{payroll:12,salary:"$72,000",active:1}, socials:{ig:"@dominic"} },
];

const THREADS = USERS.map((u,i)=>({
  id:`t${i+1}`, user:u, unread:Math.random()>.5,
  lastSnippet:i%2?"Looks good!":"There you go :)",
  lastTime:Date.now()-Math.random()*86400000*3
}));

const MSGS = {};
THREADS.forEach(t=>{
  MSGS[t.id] = [
    { id:uuid(), from:t.user.id, text:"Hey there! 👋", time:Date.now()-3600000*5 },
    { id:uuid(), from:ME.id, text:"Hi! Got your update.", time:Date.now()-3600000*4.5 },
    { id:uuid(), from:t.user.id, text:"Perfect! Let's sync later.", time:Date.now()-3600000*3 }
  ];
});

mock.onGet("/threads").reply(200, THREADS);
mock.onGet(/\/threads\/[^/]+\/messages/).reply(cfg=>{
  const id = cfg.url.split("/")[2];
  return [200, MSGS[id] || []];
});
mock.onPost("/send").reply(cfg=>{
  const {threadId,text,images}=JSON.parse(cfg.data||"{}");
  const msg={id:uuid(),from:ME.id,text,images, time:Date.now()};
  MSGS[threadId] = [...(MSGS[threadId]||[]), msg];
  setTimeout(()=>{
    const t=THREADS.find(x=>x.id===threadId);
    socket.emit("new_message",{threadId,message:{id:uuid(),from:t.user.id,text:"Got it 👍",time:Date.now()}});
  },1500);
  return [201,msg];
});

/* -------------------------------------------------------------------------- */
/*                                ESTILOS BASE                                */
/* -------------------------------------------------------------------------- */
const Shell = styled.div`
  display:flex; height:100vh; background:#f8f9fb; color:#111827; font-family:Inter,system-ui,sans-serif;
`;
const InboxPanel = styled.div`
  width:400px; background:#fff; border-right:1px solid #e5e7eb; display:flex; flex-direction:column;
`;
const ChatPanel = styled.div`
  flex:1; display:flex; flex-direction:column; background:#fff;
`;
const Header = styled.div`
  display:flex; align-items:center; gap:12px; padding:12px 16px; border-bottom:1px solid #e5e7eb;
`;
const Input = styled.div`
  display:flex; align-items:center; gap:8px; background:#f9fafb; border:1px solid #e5e7eb; border-radius:8px; padding:6px 10px;
  input{border:none;outline:none;background:transparent;width:100%;}
`;
const Row = styled.div`display:flex;align-items:center;gap:8px;`;
const MsgRow = styled.div`
  display:flex;align-items:flex-end;gap:8px;margin:8px 0;justify-content:${p=>p.me?"flex-end":"flex-start"};
`;
const Bubble = styled.div`
  background:${p=>p.me?"#4f46e5":"#f3f4f6"};color:${p=>p.me?"#fff":"#111"};padding:10px 14px;border-radius:12px;max-width:65%;
`;

/* -------------------------------------------------------------------------- */
/*                              COMPONENTES                                   */
/* -------------------------------------------------------------------------- */
function ConversationItem({ t, active, onClick }) {
  return (
    <div onClick={onClick}
      style={{
        display:"grid",gridTemplateColumns:"44px 1fr auto",gap:10,
        padding:"10px 14px",borderBottom:"1px solid #f1f3f5",
        background:active?"#f3f4f8":"transparent",cursor:"pointer"
      }}>
      <img src={t.user.avatar} alt="" style={{width:44,height:44,borderRadius:12,objectFit:"cover"}}/>
      <div style={{overflow:"hidden"}}>
        <Row style={{justifyContent:"space-between"}}>
          <strong>{t.user.name}</strong>
          {t.unread && <TbPointFilled color="#ef4444"/>}
        </Row>
        <div style={{fontSize:13,color:"#6b7280",whiteSpace:"nowrap",overflow:"hidden",textOverflow:"ellipsis"}}>
          {t.lastSnippet}
        </div>
      </div>
      <small style={{color:"#9ca3af"}}>{new Date(t.lastTime).toLocaleDateString()}</small>
    </div>
  );
}

function Inbox({ selectedId, onSelect }) {
  const [threads,setThreads]=useState([]);const [q,setQ]=useState("");
  useEffect(()=>{api.get("/threads").then(r=>setThreads(r.data));},[]);
  const view=useMemo(()=>threads.filter(t=>t.user.name.toLowerCase().includes(q.toLowerCase())),[threads,q]);
  return (
    <InboxPanel>
      <Header>
        <Input><TbSearch/><input placeholder="Search…" value={q} onChange={e=>setQ(e.target.value)}/></Input>
        <Button variant="outline-secondary" size="sm"><TbInbox/></Button>
      </Header>
      <div style={{overflow:"auto"}}>
        {view.map(t=><ConversationItem key={t.id} t={t} active={t.id===selectedId} onClick={()=>onSelect(t)}/>)}
      </div>
    </InboxPanel>
  );
}

function MessageList({ data, meId }) {
  const virtRef=useRef(null);
  useEffect(()=>{virtRef.current?.scrollToIndex({index:data.length-1,align:"end",behavior:"smooth"});},[data.length]);
  return (
    <Virtuoso
      ref={virtRef}
      style={{flex:1}}
      data={data}
      itemContent={(i,m)=>(
        <MsgRow me={m.from===meId}>
          {m.from!==meId && <img src={USERS.find(u=>u.id===m.from)?.avatar} alt="" style={{width:30,height:30,borderRadius:8}}/>}
          <Bubble me={m.from===meId}>
            <div>{m.text}</div>
            {m.images?.length>0 && (
              <div style={{display:"grid",gap:6,marginTop:6,gridTemplateColumns:`repeat(${Math.min(3,m.images.length)},1fr)`}}>
                {m.images.map((s,i)=><img key={i} src={s} alt="" style={{width:"100%",borderRadius:8,objectFit:"cover"}}/>)}
              </div>
            )}
          </Bubble>
        </MsgRow>
      )}
    />
  );
}

function Composer({ onSend }) {
  const [val,setVal]=useState("");const [images,setImages]=useState([]);
  const onDrop=useCallback(acc=>acc.forEach(f=>{const r=new FileReader();r.onload=()=>setImages(p=>[...p,r.result]);r.readAsDataURL(f);}),[]);
  const {getRootProps,getInputProps,open}=useDropzone({onDrop,noClick:true,accept:{"image/*":[]}});

  const send=()=>{if(!val.trim()&&!images.length)return;onSend(val,images);setVal("");setImages([]);};
  return (
    <div {...getRootProps()} style={{borderTop:"1px solid #e5e7eb",padding:12}}>
      <input {...getInputProps()}/>
      {images.length>0&&(
        <Row style={{gap:8,flexWrap:"wrap",marginBottom:8}}>
          {images.map((src,i)=><img key={i} src={src} alt="" style={{width:64,height:64,objectFit:"cover",borderRadius:8}}/>)}
        </Row>
      )}
      <Row>
        <Input style={{flex:1}}>
          <TbMoodSmile/>
          <input value={val} onChange={e=>setVal(e.target.value)} placeholder="Write a message…" 
                 onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();send();}}}/>
        </Input>
        <Button variant="outline-secondary" onClick={open}><TbPhotoPlus/></Button>
        <Button variant="primary" onClick={send}><TbSend/></Button>
      </Row>
    </div>
  );
}

function Chat({ thread, onInfo }) {
  const [msgs,setMsgs]=useState([]);
  useEffect(()=>{if(thread)api.get(`/threads/${thread.id}/messages`).then(r=>setMsgs(r.data));},[thread?.id]);
  useEffect(()=>{
    const off=socket.on("new_message",({threadId,message})=>{
      if(threadId===thread?.id)setMsgs(x=>[...x,message]);
    });
    return off;
  },[thread?.id]);
  const send=async(text,images)=>{
    const {data}=await api.post("/send",{threadId:thread.id,text,images});
    setMsgs(x=>[...x,data]);
  };
  if(!thread) return <ChatPanel style={{alignItems:"center",justifyContent:"center"}}><div>🗨️ Select a conversation</div></ChatPanel>;
  return (
    <ChatPanel>
      <Header style={{justifyContent:"space-between"}}>
        <Row>
          <img src={thread.user.avatar} alt="" style={{width:38,height:38,borderRadius:10,objectFit:"cover"}}/>
          <div>
            <strong>{thread.user.name}</strong>
            <div style={{fontSize:12,color:"#6b7280"}}>{thread.user.email}</div>
          </div>
        </Row>
        <Button variant="outline-secondary" size="sm" onClick={onInfo}><TbDots/></Button>
      </Header>
      <MessageList data={msgs} meId={ME.id}/>
      <Composer onSend={send}/>
    </ChatPanel>
  );
}

function UserOffcanvas({ user, show, onHide }) {
  if(!user)return null;
  return (
    <Offcanvas show={show} onHide={onHide} placement="end" style={{width:340}}>
      <Offcanvas.Header closeButton>
        <Offcanvas.Title>{user.name}</Offcanvas.Title>
      </Offcanvas.Header>
      <Offcanvas.Body>
        <img src={user.avatar} alt="" style={{width:"100%",borderRadius:12,marginBottom:12}}/>
        <div><strong>Email:</strong><br/>{user.email}</div>
        <div className="mt-2"><TbPhone/> {user.phone}</div>
        <div><TbMapPin/> {user.city}</div>
        <div><TbCalendar/> Joined 03/11/2023</div>
        <hr/>
        <div><strong>Payroll checks:</strong> {user.company.payroll}</div>
        <div><strong>Salary:</strong> {user.company.salary}</div>
        <div><strong>Active projects:</strong> {user.company.active}</div>
        <hr/>
        <div><TbHash/> {user.socials.ig}</div>
      </Offcanvas.Body>
    </Offcanvas>
  );
}

/* -------------------------------------------------------------------------- */
/*                                 ROOT APP                                   */
/* -------------------------------------------------------------------------- */
export default function Chat_hr(){
  const [sel,setSel]=useState(null);
  const [showInfo,setShowInfo]=useState(false);
  return (
    <Shell>
      <Inbox selectedId={sel?.id} onSelect={setSel}/>
      <Chat thread={sel} onInfo={()=>setShowInfo(true)}/>
      <UserOffcanvas user={sel?.user} show={showInfo} onHide={()=>setShowInfo(false)}/>
    </Shell>
  );
}
