import React, { useEffect, useState, useCallback } from "react";
import styled from "styled-components";
import { Badge, Form } from "react-bootstrap";
import { Avatar } from "@mui/material";
import axios from "axios";
import { Edit, Delete as DeleteIcon } from "@material-ui/icons";
import { PiMicrosoftExcelLogoDuotone } from "react-icons/pi";
import TableGrid from "../../../../General/components/TableGrid";
import ContinuousAvaliationModal from "./SubTabs/Modal/ContinuousAvaliationModal";
import Hoot from "../../../../General/components/Hoot";
import DeleteModal from "../../../../Dashboard/components/elements/DeleteModal";
import ExportDataForTablesExcel from "../../../../General/components/ExportDataForTablesExcel";
import { GetClasstitle_byclass, GetSubject } from "../../../../General/components/InstituteData";

const TABLEURL = Hoot() + "eduallgetctnavlpointsbysubclass/get/";

const withRetry = async (fn, { tries = 3, baseDelay = 300 } = {}) => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  let attempt = 0;
  let lastErr;
  while (attempt < tries) {
    try {
      return await fn();
    } catch (err) {
      lastErr = err;
      attempt += 1;
      if (attempt >= tries) break;
      await sleep(baseDelay * Math.pow(2, attempt - 1));
    }
  }
  throw lastErr;
};

const columns = [
  { field: "index", headerName: "Nº", width: 90, resizable: true },
  {
    field: "name",
    headerName: "Nome do aluno",
    width: 400,
    resizable: true,
    cellRenderer: (props) => (
      <div className="ed-flex">
        <Avatar
          className="df"
          alt={props.data?.sortName}
          src={props.data.picture ? Hoot() + props.data.picture : ""}
        />
        <span className="ml-2">{props.data.name}</span>
      </div>
    ),
  },
  {
    field: "score",
    headerName: "Pontos",
    width: 120,
    resizable: true,
    cellRenderer: (props) => {
      const s = Number(props.data.score);
      if (s <= 3) return <Badge bg="warning">{s}</Badge>;
      if (s <= 4) return <Badge bg="primary">{s}</Badge>;
      return <Badge bg="success">{s}</Badge>;
    },
  },
  {
    field: "date",
    headerName: "Data de registro",
    width: 170,
    resizable: true,
  },
  {
    field: "action",
    headerName: "Ação",
    width: 150,
    resizable: true,
    cellRenderer: (props) => (
      <div className="ed-flex">
        <ContinuousAvaliationModal
          data={props.data.data}
          title="Atualizar"
          update="true"
          get={Hoot() + `eduallgetsinglectnavlpoints/get/${props.data.id}`}
          url={Hoot() + `eduallgetctnavlpointsbysubclass/update/${props.data.id}`}
          toggle_btn={
            <button className="btn-circle btn-edit-timing bg-success text-light">
              <Edit />
            </button>
          }
        />
        <DeleteModal
          title="esta pontuação"
          url={Hoot() + `eduallgetctnavlpointsbysubclass/delete/${props.data.id}`}
          message="Pontuação deletada com sucesso"
          toggle_btn={
            <button className="btn-circle btn-delete-timing bg-danger ml-2 text-light">
              <DeleteIcon />
            </button>
          }
        />
      </div>
    ),
  },
];

function TeacherContinuousEvaluation({ Data: TeacherData }) {
  const [rows, setRows] = useState([]);
  const [load, setLoad] = useState(true);
  const [error, setError] = useState(null);
  const [selected, setSelected] = useState(""); // valor do tipo "classId|subjectId"

  const DT = TeacherData?.data || [];

  const loadData = useCallback(async (comboValue) => {
    if (!comboValue) {
      setRows([]);
      setLoad(true);
      return;
    }

    const [, subjectId] = comboValue.split("|"); // separa turma|disciplina
    if (!subjectId) return;

    setLoad(false);
    setError(null);

    try {
      const res = await withRetry(
        () => axios.get(TABLEURL + subjectId),
        { tries: 3, baseDelay: 300 }
      );

      const list = Array.isArray(res.data) ? res.data : [];
      const mapped = list.map((item, index) => ({
        index: index + 1,
        date: item.ed_cn_avl_date,
        studentcode: item.ed_cn_avl_studentCode,
        studentid: item.ed_student_id,
        sortName: item.ed_student_name,
        picture: item.ed_student_picture,
        name: `(#${item.ed_student_code}) - ${item.ed_student_name}`,
        score: item.ed_cn_avl_score,
        id: item.ed_cn_avl_id,
        data: TeacherData.data,
      }));

      setRows(mapped);
    } catch (err) {
      console.error(err);
      setError("Falha ao carregar pontuações. Tente novamente.");
      setRows([]);
    } finally {
      setLoad(true);
    }
  }, [TeacherData.data]);

  useEffect(() => {
    if (DT.length > 0 && !selected) {
      const first = `${DT[0].ed_tch_subject_class}|${DT[0].ed_tch_subject_id}`;
      setSelected(first);
      loadData(first);
    }
  }, [DT, selected, loadData]);

  const handleInput = (e) => {
    const value = e.target.value;
    setSelected(value);
    loadData(value);
  };

  return (
    <Container>
      <div className="top-container">
        <Box className="ed-emp-dashboard-contavl">
          <div className="ed-space">
            <div className="title">
              <h1>Adicionar Pontos</h1>
            </div>

            <div className="ed-flex">
              <Form className="mt-2">
                <Form.Group className="ml-2">
                  <Form.Select
                    id="student_attendance_classSub"
                    value={selected}
                    onChange={handleInput}
                  >
                    {DT.length > 0 ? (
                      DT.map((item, index) => (
                        <option
                          key={index}
                          value={`${item.ed_tch_subject_class}|${item.ed_tch_subject_id}`}
                        >
                          Turma - <GetClasstitle_byclass ID={item.ed_tch_subject_class} /> (
                          <GetSubject ID={item.ed_tch_subject_code} />)
                        </option>
                      ))
                    ) : ( 
                      <option value="">Sem turmas atribuídas</option>
                    )}
                  </Form.Select>
                </Form.Group>
              </Form>

              <button
                className="btn-icon btn btn-export-data ml-2"
                onClick={() =>
                  ExportDataForTablesExcel(
                    "Avaliações contínuas (pontuações)- ",
                    ["Ação"],
                    "TeacherContinuousEvaluation-area"
                  )
                }
              >
                <PiMicrosoftExcelLogoDuotone /> Exportar dados
              </button>

              <div className="ml-2">
                <ContinuousAvaliationModal data={TeacherData.data} />
              </div>
            </div>
          </div>
        </Box>
      </div>

      <div className="table-box" id="TeacherContinuousEvaluation-area">
        {error && (
          <div className="alert alert-warning py-2 px-3 mb-2">{error}</div>
        )}

        <TableGrid
          TableHead={columns}
          TableBody={load ? rows : []}
          TableHeight={window.innerWidth <= 900 ? 250 : 420}
          TableTitle="Pontuações"
        />
      </div>
    </Container>
  );
}

// ---------------- Styled ----------------
const Container = styled.section`
  display: block;
  width: 100%;

  .top-container {
    margin-top: 20px;
  }

  .table-box {
    margin-top: 30px;
    min-height: 600px;
  }
`;

const Box = styled.div`
  width: 100%;
  border-radius: 6px;
  min-height: 90px;
  margin-bottom: 21px !important;
  background: var(--ed-white);
  box-shadow: var(--ed-shadow-df);
  padding: 0px 20px;
  position: relative;
  display: flex;
  align-items: center;

  .ed-space {
    align-items: center;
    height: 100%;
  }

  .form-select {
    max-width: 320px;
  }

  .title h1 {
    font-size: 18px;
    font-weight: 600;
    margin: 0px;
  }
`;

export default React.memo(TeacherContinuousEvaluation);
