import React, { useState, useEffect } from 'react'
import axios from 'axios'
import { Delete, Edit, Refresh } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import NewAuthorModal from '../modal/NewAuthorModal';
import { Badge } from 'react-bootstrap';
import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';

const TABLEURL = Hoot() + "edualllibraryauthor/get";


const columns = [
  {
    field: 'index',
    headerName: 'Nº',
    width: 90,
    resizable: true,
  },
  {
    field: 'title',
    headerName: 'Autor',
    resizable: true,
    width: 350,
  },
  {
    field: 'status',
    headerName: 'Estado',
    resizable: true,
    width: 150,
    cellRenderer: (props) => {
      return Math.floor(props.data.status) === 0 ?
        <Badge bg='info'><div className="text-dark">Activo</div></Badge> :
        <Badge bg='danger'><div className="text-dark">Inactivo</div></Badge>
    }
  },
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true,
    cellRenderer: (props) => {
      return <div className="ed-flex">
        <NewAuthorModal title='Atualizar ' update='true' get={Hoot() + `eduallsinglelibraryauthor/get/${props.data.id}`}
          url={Hoot() + `edualllibraryauthorupdate/update/${props.data.id}`} toggle_btn={
            <button className="btn-circle bg-success text-light">
              <Edit />
            </button>
          } />
        <DeleteModal title='este autor' url={Hoot() + `edualllibraryauthordelete/delete/${props.data.id}`}
          message='Autor deletado com sucesso' toggle_btn={
            <button className="btn-circle bg-danger ml-2 text-light">
              <Delete />
            </button>
          } />
      </div>
    }
  }
];

function AuthorTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData() {
    setLoadStatus(0);
    try {
      setLoaded(false);
      const response = await axios.get(TABLEURL);
      const rows = [];
      response.data.map((item, index) => {
        rows.push({
          index: index + 1,
          id: item.ed_library_author_id,
          title: item.ed_library_author_name,
          status: item.ed_library_author_status,
          action: ""
        });
      });
      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoadStatus(1);
      setLoaded(false);
    }
  }

  useEffect(() => {
    loadData();
  }, []);



  if (load) {
    return (
      <div id='ed-custom-table-data'> 
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista dos autores' 
          TableBtn={
            <div className='ed-flex'>
              <button id='ed-custom-table-data-btn'
                onClick={() =>
                  ExportDataToTablesToPdf({
                    fileName: "Lista dos Autores",
                    headerId: null,
                    contentId: "ed-custom-table-data",
                    footerId: null,
                    rotation: "portrait",
                    buttonId: "ed-custom-table-data-btn",
                    customHeader: "Lista dos Autores",
                    excludedColumns: ["Ação"]
                  })
                }
                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
              </button>
              <button className='btn-icon btn btn-export-data ml-2'
                onClick={() => ExportDataForTablesExcel("lista dos autores", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
              </button>
              <RefreshButton action={loadData} status={LoadStatus} />
            </div>
          }
        />
      </div>
    )
  } else {
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={[]}
          TableTitle='Lista dos autores'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    )
  }


}

export default AuthorTable