import React, { useEffect, useState } from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap'
import { Save } from '@mui/icons-material';
import DraggableModal from '../../../../General/components/DraggableModal';
import axios from 'axios';
import Hoot from '../../../../General/components/Hoot';
import ClearInputs from '../../../../General/components/ClearInputs';
import CRValue from '../../../../General/components/CRValue';
import { toast } from 'react-hot-toast';
import { Update } from '@material-ui/icons';
import SaveButton from '../../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../../General/components/ModalAnimations';
import RefreshList from '../../../../General/components/RefreshList';

function NewLibraryBookColectionModal(props) {
  const [show, setShow] = useState(false);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [Founded, SetFounded] = useState(null);


  const [showBox, SetshowBox] = useState(false);
  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200);
  }

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };


  const INPUTS = {
    collection_title: CRValue("#collection_title"),
  };

  const FORMURL = [
    Hoot() + "edualllibrarycollectionregister/post",
    props.get ? props.get : '',
    props.url ? props.url : ''
  ];

  const GET_DATA = async () => {
    if (props.update) {
      try {
        const response = await axios.get(FORMURL[1]);
        if (response.data.length > 0) {
          document.querySelector("#collection_title").value = response.data[0].ed_library_collection_title;
          INPUTS.collection_title = response.data[0].ed_library_collection_title;
        } else {
          toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
        }
      } catch (error) {
        toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
      }
    }
  }

  const setField = (field, value) => {
    setForm({
      ...form,
      [field]: value
    })

    if (!!errors[field]) {
      setErrors({
        ...errors,
        [field]: null
      });
    }
  }


  const validateForm = () => {
    const { collection_title } = form;
    const NewErrors = {};
    setRegisterStatus(0);

    if (INPUTS.collection_title === "" || INPUTS.collection_title === " ") {
      if (!collection_title || collection_title === '') NewErrors.collection_title = 'Coleção  invalida !';
    } else { if (!collection_title) { setField("collection_title", INPUTS.collection_title); } }

    return NewErrors;
  }

  const SUBMIT_INPUTS = { collection_title: INPUTS.collection_title };

  const FormSubmit = (e) => {
    e.preventDefault();
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os  campos !");
      setRegisterStatus(1);
    } else {
      if (!props.update) {
        try {
          axios.post(FORMURL[0], SUBMIT_INPUTS).then(() => {
            toast.success("Coleção  registrada com sucesso !");
            setForm({});
            ClearInputs();
            setRegisterStatus(2);
              RefreshList(`.el-refresh-list`);
          }).catch((error) => {
            console.clear()
            console.log(error.response);
            setRegisterStatus(1);
            toast.error("Lamentamos mas não foi  possivel executar esta ação !")
          });
        } catch (error) {
          console.clear()
          console.log(error.response);
          toast.error("Lamentamos mas não foi  possivel executar esta ação !");
          setRegisterStatus(1);
        }
      } else {
        try {
          axios.put(FORMURL[2], SUBMIT_INPUTS)
            .then(() => {
              toast.success("Coleção  atualizada com sucesso !");
              setForm({});
              ClearInputs();
                RefreshList(`.el-refresh-list`);
              setRegisterStatus(2);
              setTimeout(() => {
                handleClose();
              }, 1500);
            }).catch((error) => {
              console.clear()
              console.log(error.response);
              setRegisterStatus(1);
              toast.error("Lamentamos mas não foi  possivel executar esta ação")
            });
        } catch (error) {
          console.clear()
          console.log(error.response);
          toast.error("Lamentamos mas não foi  possivel executar esta ação !");
          setRegisterStatus(1);
        }
      }
    }
  };


  const handleInput = (e) => {
    switch (e.target.id) {
      case "collection_title":
        INPUTS.collection_title = e.target.value
        setField("collection_title", e.target.value);
        break;
      default:
    }
  }


  return (
    <div>
      <div onClick={handleShow}>
        {
          props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon /> Registrar Coleção</button>
        }
      </div>
      <Modal centered className={showBox ? ModalAnimationShow() : ModalAnimationClose()} dialogAs={DraggableModal} show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title><h5>Registrar Coleção</h5></Modal.Title>
        </Modal.Header>
        <Form onSubmit={FormSubmit}>
          <Modal.Body className='scrollLimit'>
            <Form.Group className="mb-3"  >
              <Form.Label>Coleção<span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Control onChange={handleInput} className={!!errors.collection_title && 'is-invalid'} value={form.collection_title} isInvalid={!!errors.collection_title}
                type="text" id="collection_title" />
              <Form.Control.Feedback type='invalid'>{errors.collection_title}</Form.Control.Feedback>
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <div className="ed-space">
              <div className="ed-flex"></div>
              <div className="ed-flex">
                <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                {props.update ? (Founded === false ? <div></div> :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />}
              </div>
            </div>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  )
}

export default NewLibraryBookColectionModal; 
