import React, { useState, useEffect } from 'react'
import {
  TbSmartHome, TbInbox, TbMessageChatbot, TbUser, TbBuilding, TbLockBolt, TbChartLine,
  TbCalendarShare, TbClockHour5, TbUsers, TbUmbrella, TbSubtask, TbPigMoney, TbBriefcase, TbMoneybag,
  TbTimeDuration15, TbProgressCheck, TbChartPie, TbCapProjecting, TbFolderRoot, TbHourglassEmpty
} from "react-icons/tb";
import { IoDocumentTextOutline, IoDocumentAttachOutline } from "react-icons/io5";
import { LuFolderClock } from "react-icons/lu";
import { Link, useLocation } from 'react-router-dom';

const LogoImg = [
  require('../../Assets/images/logos/black/eduallportalADM-8.png'),
  require('../../Assets/images/logo-small-white.png'),
];

function SidebarRH() {
  const location = useLocation();

  const [ActiveMenu, setActiveMenu] = useState(() => {
    return localStorage.getItem('ActiveMenuRH') || "Início";
  });

  const MenuList = [
    {
      subtitle: null,
      menus: [
        { name: "Início", link: "/hr/home", icon: <TbSmartHome /> },
        { name: "Caixa de mensagens", link: "/hr/inbox", icon: <TbInbox /> },
        { name: "Chat", link: "/hr/chat", icon: <TbMessageChatbot /> },
      ]
    },
    {
      subtitle: "Eu",
      menus: [
        { name: "Perfil de colaborador", link: "/hr/employee-profile", icon: <TbUser /> },
        { name: "Rélogio de ponto", link: "/hr/time-clock", icon: <TbClockHour5 /> },
        { name: "Férias", link: "/hr/vacations", icon: <TbUmbrella /> },
        { name: "Tarefas", link: "/hr/tasks", icon: <TbSubtask /> },
        { name: "Meus documentos", link: "/hr/my-documents", icon: <IoDocumentTextOutline /> },
        { name: "Meus objectivos", link: "/hr/my-goals", icon: <TbProgressCheck /> },
      ]
    },
    {
      subtitle: "A sua empresa",
      menus: [
        { name: "Organização", link: "/hr/organization", icon: <TbBuilding /> },
        { name: "Colaboradores", link: "/hr/employees", icon: <TbUsers /> },
        { name: "Performance", link: "/hr/performance", icon: <TbChartLine /> },
        { name: "Mapa de férias", link: "/hr/vacations_map", icon: <TbHourglassEmpty /> },
        { name: "Acessos", link: "/hr/access", icon: <TbLockBolt /> },
        { name: "Caléndario", link: "/hr/calendar", icon: <TbCalendarShare /> },
        { name: "Recrutamento", link: "/hr/recruitment", icon: <TbBriefcase /> },
        { name: "Despesas", link: "/hr/expenses", icon: <TbPigMoney /> },
        { name: "Folha de pagamento", link: "/hr/payroll", icon: <TbMoneybag /> },
        { name: "Arquivos", link: "/hr/files", icon: <IoDocumentAttachOutline /> },
        { name: "Horários", link: "/hr/schedules", icon: <TbTimeDuration15 /> },
        { name: "Analises", link: "/hr/analytics", icon: <TbChartPie /> },
        { name: "Rélogio de ponto", link: "/hr/time-clock", icon: <LuFolderClock /> },
        { name: "Projetos", link: "/hr/projects", icon: <TbCapProjecting /> },
        { name: "Arquivos", link: "/hr/folders", icon: <TbFolderRoot /> },
      ]
    }
  ];

  // Guarda o ativo no localStorage
  useEffect(() => {
    localStorage.setItem('ActiveMenuRH', ActiveMenu);
  }, [ActiveMenu]);

  // Detecta menu ativo pela rota
  useEffect(() => {
    const allMenus = MenuList.flatMap(group => group.menus);

    const current = allMenus.find(m => {
      const menuPath = m.link.replace(/\/$/, '');
      return (
        location.pathname === menuPath ||
        location.pathname.startsWith(`${menuPath}/`)
      );
    });

    if (current) {
      setActiveMenu(current.name);
      localStorage.setItem('ActiveMenuRH', current.name);
    }
  }, [location.pathname]);

  const ChangeMenu = (name) => {
    setActiveMenu(name);
    localStorage.setItem('ActiveMenuRH', name);
  };

  return (
    <div className='rh-sidebar'>
      <div>
        <Link to='/dashboard'>
          <div className="ed-rh-logo">
            <img loading="lazy" src={LogoImg[0]} alt="eduall" />
          </div>
        </Link>
      </div>

      <ul className='rh-sidebar-menu'>
        {MenuList.map((menu, index) => (
          <div key={index}>
            {menu.subtitle && <h3 className='grey-text'>{menu.subtitle}</h3>}

            <ol>
              {menu.menus.map((item, key) => (
                <li
                  key={key}
                  onClick={() => ChangeMenu(item.name)}
                  className={ActiveMenu === item.name ? "active-menu" : ""}
                >
                  <Link to={item.link} className='ed-flex'>
                    {item.icon} <span>{item.name}</span>
                  </Link>
                </li>
              ))}
            </ol>

            <div className="line"></div>
          </div>
        ))}
      </ul>
    </div>
  )
}

export default SidebarRH;
