import React from 'react'
import { Button } from 'react-bootstrap'; 
import { RefreshOutline } from 'react-ionicons'; 
import { SyncCircleOutline } from 'react-ionicons'

function RefreshButton(props){
    let status = props.status;

    const ClassType = ()=>{  
        if(status === 0){
            return "bg-warning";
        }else if(status === 1){
              return "bg-danger";
        }else if(status === 2){  
          return "bg-main";
        }else if (status === null){
            return "bg-main";
        }
    }
    
    
    const Data = ()=>{  
        if(status === 0){
            return <SyncCircleOutline  color={'#00000'}  rotate   height="65px"  width="65px" />
        }else if(status === 1){
              return <><RefreshOutline/></>
        }else if(status === 2){  
          return <><RefreshOutline/></>
        }else if (status === null){
            return <><RefreshOutline/></>
        }
    }
    
      return (
        <div onClick={props.action ? props.action : console.log("Nothing.....")}>
          <Button disabled={props.disable ? true : (props.status === 0 ? true : false)}  
            className={`btn el-refresh-list ed-flex ed-center ml-2  btn-icon table-btn-small  ${ClassType()} `}> 
             { Data() }
           </Button>
        </div>
      )
}

export default RefreshButton