import { Settings } from '@mui/icons-material';
import { Avatar } from '@mui/material';
import React, {useState, useEffect} from 'react' 
import { Link } from 'react-router-dom'; 
import {ChatbubbleEllipsesOutline} from 'react-ionicons'
import MenuDropDown from './MenuDropDown';
import styled from 'styled-components';

function MessagesDropDownMenu() {
    const [show, setShow] = useState(false); 
    const handleClose = () => setShow(false);
    const handleShow = () => setShow(true);  
    const [ToggleState, setToggleState] = useState(1);
    
    const toggleTab = (index)=>{ 
        setToggleState(index);  
     }
    
      return (
        <>
            <div>
            <MenuDropDown
                 toggle_btn={<button className='nav-toggle'><ChatbubbleEllipsesOutline/><div className="count bg-danger">0</div></button>} 
                  header={  
                  <Header> 
                      <h1 className="title">Mensagens</h1> 
                  </Header>}
                  content={
                      <Container className="message-dropdown-body">
                         <div className="ed-center"> <small className="text-main">A sua caixa de correio está vazia</small> </div>
                         <div className="view ed-center d-none  text-main col mt-4">
                              <Link to="/chat">Iniciar conversa</Link>
                         </div>
                      </Container>
                  } 
              />  
          </div>
        </>
      )
}


const Header = styled.div` 
  padding:10px 20px;
  border-bottom:1px solid var(--ed-white-smoke);

    h1.title{
      font-weight: 600;
      font-size: 18px; 
      margin:0px;
    }
`;


const Container = styled.div`
   padding:20px;
`;

export default MessagesDropDownMenu