import React, {useState} from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import {Modal, Form, Button} from 'react-bootstrap'
import { Save, Update } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';

function NewServicePaymentModal(props) {
    const [show, setShow] = useState(false); 
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [Founded, SetFounded] = useState(null);

         
    const [showBox, SetshowBox]  = useState(false);
    const handleClose = () => {
      SetshowBox(false);
      setTimeout(() => {
        setShow(false);
      }, 1200);
    } 

    const handleShow = () => {
          SetshowBox(true);
          setShow(true);  
          setTimeout(() => {  
         
         }, 1000);   
    };

    
  return (
    <div>
         <button className='btn bg-dark  ml-2' onClick={handleShow}>
           <AddCircleOutlineIcon/> Registrar pagamento de serviço
      </button> 
      <Modal className={showBox ? ModalAnimationShow() : ModalAnimationClose()}   centered size='lg' dialogAs={DraggableModal}  show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>Registrar pagamento de serviço</h5>
           </div>   
          </Modal.Title>
        </Modal.Header>
        <Modal.Body className='scrollLimit'>
          <Form> 
            <Form.Group className="mb-3"  >
              <Form.Label>Nome do aluno <span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Select required select>
                  <option value="#" selected>Carlos Mateus</option> 
              </Form.Select>
            </Form.Group>  
            <Form.Group className="mb-3"  >
              <Form.Label>Serviço <span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Select required select>
                  <option value="#" selected>Aulas de Karate</option> 
              </Form.Select>
            </Form.Group> 
            <Form.Group className="mb-3"  >
              <Form.Label>Metodo de pagamento <span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Select required select>
                  <option value="0" selected>Multibanco</option> 
              </Form.Select>
            </Form.Group> 
          </Form>
        </Modal.Body>
        <Modal.Footer>
        <div className="ed-space">
             <div className="ed-flex"></div>
             <div className="ed-flex">
             <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button> 
            {props.update ? (Founded === false ? <div></div>  : 
            <SaveButton icon={props.title ? <Update/> : <Save/>} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
            <SaveButton icon={props.title ? <Update/> : <Save/>} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />} 
             </div>
          </div>
        </Modal.Footer>
      </Modal>
    </div>
  )
}

export default NewServicePaymentModal