 
import {GoPersonAdd,GoBriefcase}from "react-icons/go";
import React, { useEffect, useState } from 'react'
import { AiOutlineHeart, AiFillHeart } from 'react-icons/ai'
import Hoot from '../../General/components/Hoot';
import axios from 'axios';
import { BsChat  } from "react-icons/bs";
import { toast } from 'react-hot-toast';
import { Link } from "react-router-dom";
import {TbLoader3} from "react-icons/tb";
const AudioSound  = require("../../Assets/audios/audio_3.wav");

function AddContactButton(props){
  const [Contact, SetContact] = useState(0);
  const [ContactStatus, SetContactStatus] = useState(0);


  const DATAURL =  [
      Hoot()+"eduallmakeusercontactrequest/post",
      Hoot()+"eduallcheckifuserisacontact/get/",
  ];

  const CheckIfIsContact = async(code, type)=>{ 
        try {
          const [response] = await Promise.all([
            axios.get(DATAURL[1]+code),  
          ]); 
          if(response.data.length >= 1){
            SetContact(true);
            SetContactStatus(response.data[0].ed_user_contact_status*1 === 1 ? 1 : 0);
           
          }else{
            SetContact(false);
          }
        } catch (error) {
          SetContact(null);
        } 
  }


  
  const MakeContactRequest = async(code, type)=>{ 
      try {
        axios.post(DATAURL[0], {CODE:code}).then(()=>{ 
          var audio = new Audio(AudioSound);
          audio.play();  
          SetContact(1); 
        }).catch((error)=>{
          toast.error("Lamentamos mas não foi  possivel executar esta ação"); 
          SetContact(false);
          console.clear();
          console.log(error);
        });  
      } catch (error) {
        SetContact(false);
      } 
  }


  useEffect(()=>{
    CheckIfIsContact(props.CODE, props.TYPE);
  },[props]);


  return (
    <div>  
        <div className={Contact === 0 ? "d-none" : "" }>
          {Contact === null ? <></> : <>{Contact !== 1 ? <>{Contact === true ? 
            <><button className="btn btn-sm bg-main text-light"><TbLoader3/> Aguardando</button></>  :  
            <button  onClick={()=>MakeContactRequest(props.CODE, props.TYPE)}  className="btn btn-bordered text-main"><GoPersonAdd/> Contactar</button>
          
          }</>  :  <>{ContactStatus === 1  ? <Link to="#"><button className="btn btn-sm bg-main text-light"><AiFillHeart /> Conversar</button> </Link>  : <button className="btn bg-main text-light"><TbLoader3/> Aguardando</button> 
          }</>} </>} 
        </div>  
    </div>
  )
}







 
export default AddContactButton