import React, { useEffect, useState } from 'react'
import { styled } from 'styled-components';
import ProgressBar from 'react-bootstrap/ProgressBar';
import {BsEmojiSmile,BsEmojiExpressionless,BsEmojiLaughing,BsEmojiAngry,BsEmojiFrown} from "react-icons/bs";
import { Avatar } from '@mui/material';
import {BsStarFill,BsStarHalf, BsStar} from "react-icons/bs";
import TimeAgo from "javascript-time-ago";
import pt from "javascript-time-ago/locale/pt.json";
import ReactTimeAgo from 'react-time-ago'  
import Hoot from '../../../General/components/Hoot';


function PP_behavier({data}) {
  const [GetPercentageData, setGetPercentageData] = useState({el1:[], el2:[], el3:[], el4:[], el5:[]});
  
  const  LoadData = ()=>{
    let rows = {el1:[], el2:[], el3:[], el4:[], el5:[]};
        data.map((item, index)=>{
            if(item.ed_student_behavior_type*1 === 0){rows.el1.push(index)}
            if(item.ed_student_behavior_type*1 === 1){rows.el2.push(index)}
            if(item.ed_student_behavior_type*1 === 2){rows.el3.push(index)}
            if(item.ed_student_behavior_type*1 === 3){rows.el4.push(index)}
            if(item.ed_student_behavior_type*1 === 4){rows.el5.push(index)}
        })
       setGetPercentageData(rows);
  }


  const CalculatePercentage = (a, b)=>{
    if(a === 0) return 0;
    if(b === 0) return 0;
    return Math.floor((a*100) / b);
  }

  useEffect(()=>{
      LoadData();
  },[data])

  return (
    <div> 
        <div className="mt-4">
          <Box>
             <h1 className="title">Comentários  dos professores ({data.length}) </h1>
             <section className="comments">
                 {data.map((comment, index)=>{
                    return( 
                      <article key={index} className='comment'>
                          <div className="comment-header">
                              <div className="avatar-box">
                                   <div className="status***"></div>
                                   <Avatar className='df' src={Hoot()+comment.ed_user_account_picture} sx={{width:60,height:60}} alt={comment.ed_user_account_name} />  
                               </div>
                              <div className="ed-block">
                                 <div className="name">{comment.ed_user_account_name}</div>
                                 <small> <ReactTimeAgo date={comment.ed_student_behavior_registerDate} locale="pt-PT"/></small>
                              </div>
                          </div>
                          <div className="comment-body">
                             <div className="stars">
                                 <div className={comment.ed_student_behavior_stars*1 >= 1 ? "selected" : ""} ><BsStarFill /> </div>
                                 <div className={comment.ed_student_behavior_stars*1 >= 2 ? "selected" : ""} ><BsStarFill /> </div>
                                 <div className={comment.ed_student_behavior_stars*1 >= 3 ? "selected" : ""} ><BsStarFill /> </div> 
                                 <div className={comment.ed_student_behavior_stars*1 >= 4 ? "selected" : ""} ><BsStarFill /> </div>
                                 <div className={comment.ed_student_behavior_stars*1 >= 5 ? "selected" : ""} ><BsStarFill /> </div> 
                             </div>
                             <p>{comment.ed_student_behavior_description}</p>
                          </div>
                      </article>
                    )
                 })}
             </section>
          </Box>
        </div>
    </div>
  )
}

const Box = styled.div`
    background:var(--ed-white); 
    border-radius:6px; 
    box-shadow:var(--ed-shadow-df);
    width:100%;
    margin:20px 0px; 
    padding:20px; 

    
   .title{
      font-size: 18px;
      font-weight: 600;
      margin: 0px; 
    }

    .avaliation-progress{ 
      margin-top:20px;

      div{
        min-width:70px;
        font-size:16px;
      }

      div span svg{
         width:22px;
         height:22px;
         margin-right:6px;
      }

      .progress-box{
        width:73%; 
        margin:0px 15px;

        .progress-bar{
          background:var(--ed-purple-light) !important;
        }
   
       .progress {
         width:100%;
         height:8px !important;
        }
      }
    }





    .comments{
        display:block;
        padding:20px 0px;

          .comment{
              margin:10px 0px;

              small,p{
                  font-size:15px;
                  color:var(--ed-grey-text);
              }

              .comment-header{
                  display:flex;

                  .avatar-box{
                     width:60px;
                     height:60px;
                     position:relative;

                      .status{
                         position:absolute;
                         top:-2px;
                         right:2px;
                         width:15px;
                         height:15px;
                         background:var(--ed-green);
                         z-index:100;
                         border-radius:100%;
                         border:3px solid var(--ed-white);
                         box-shadow:var(--ed-shadow-df);
                      } 
                  }

                  .ed-block{
                    padding-left:20px;

                      .name{
                         font-size:16px;
                         font-weight:500;
                      }
                  }

              }


              .comment-body{
                 
                .stars{
                    display:flex;
                    margin:10px 0px;

                     div{
                        margin-right:10px;

                        svg{
                            color:var(--ed-grey-text);
                        }
                     }


                     .selected{
                        svg{
                          color:var(--ed-gold) !important;
                        }
                     }
                }



                border-bottom:1px solid var(--ed-silver);
                padding-bottom:40px;
                margin-bottom:30px;
              } 
          }



    }


`;


export default PP_behavier
