import { Print } from '@mui/icons-material';
import React, { useState } from 'react'
import Form from 'react-bootstrap/Form'; 
import PdSchoolMarksTable from '../Table/PdSchoolMarksTable';
import PdStudentMarksTable from "../Table/PdStudentMarksTable";
import GetTypeOfInstitute from '../../../General/components/GetTypeOfInstitute';
import PdStudentMarksCollegeTable from '../Table/PdStudentMarksCollegeTable';

function Marks({data}) {
  const [ActiveTab, setActiveTab] = useState(0);


  return (
    <div> 
      {GetTypeOfInstitute() === 0 ?
       <>
        <div className="ed-space">
            <div>
              <> 
                <Form.Group className="mb-3"> 
                  <Form.Select onChange={(e)=>setActiveTab(e.target.value*1)}>
                      <option selected value="0">Nota escolar</option>
                      <option value="1">Boletim escolar</option> 
                  </Form.Select>
                </Form.Group> 
              </>
            </div> 
       </div> 
         {ActiveTab === 0 ?
          <div className="mt-2">   
               <PdSchoolMarksTable  StudentCode={data.ed_student_id}  ClassId={data.ed_student_class} /> 
            </div>  
         : <></>}

        {ActiveTab === 1 ?
          <div className="mt-2">   
                <PdStudentMarksTable StudentCode={data.ed_student_id}  ClassId={data.ed_student_class} />  
            </div>  
         : <></>} 
       </>
      : 
      <>
        <div className="ed-space">
            <div>
              <> 
                <Form.Group className="mb-3"> 
                  <Form.Select onChange={(e)=>setActiveTab(e.target.value*1)}>
                      <option selected value="1">Iº Semestre</option>
                      <option value="2">IIº Semestre</option> 
                  </Form.Select>
                </Form.Group> 
              </>
            </div> 
       </div> 
       <PdStudentMarksCollegeTable StudentCode={data.ed_student_id} Semester={ActiveTab} ClassId={data.ed_student_class} />
      </>} 
    </div>
  )
}

export default Marks;