import React from 'react';
import styled from "styled-components";
import { Swiper, SwiperSlide } from 'swiper/react';
import ImageLazyLoading from '../../../../../General/components/ImageLazyLoading';
import ReduceTextLength from '../../../../../General/components/ReduceTextLength';
import { Heart } from 'react-ionicons'
import { Link } from 'react-router-dom';


const Images  = [ 
    "https://mspoweruser.com/wp-content/uploads/2016/09/Webgroesse_HighRes_Microsoft12711.jpg",
    "https://static.dezeen.com/uploads/2018/10/microsoft-ireland-gensler-architecture_dezeen_2364_hero_b.jpg",
    "https://img-prod-cms-rt-microsoft-com.akamaized.net/cms/api/am/imageFileData/RE3H8Fn?ver=8b3a&q=90&m=6&h=431&w=767&b=%23FFFFFFFF&l=f&o=t&aim=true", 
];

function Comp_offices() {
return (
    <Container>
        <h1 className="title">Escritorios </h1>
        <div className="line"></div>
        <div className="col mt-4 mb-4">
       <Swiper  spaceBetween={30}   slidesPerView={2.2}  >
           {Images.map((item, index)=>(
               <SwiperSlide key={index+1}>
                   <div className="card">
                     <div className="image">
                        <Link to="#">
                           <ImageLazyLoading source={item} height={150} />
                        </Link>
                     </div>
                     <div className="txt">
                     <Link to="#">
                        <p><ReduceTextLength  text="Gensler and RKD Architects create digital waterfall for Microsoft Ireland's HQ" length={30} /></p>
                     </Link>
                     <div className='ed-flex lk'>
                          <div className="icon"><Heart /></div> 123 de aprovação
                      </div>
                     </div>
                   </div>
               </SwiperSlide> 
            ))}
        </Swiper>
       </div>
    </Container>
    )
}

const Container = styled.div`
   max-width:750px; 
   margin:20px 0px;


     .card{
        min-width:200px;
        min-height:200px;
        border-radius:6px;
        border:1px solid var(--ed-silver-light);
        display:block;
        background:var(--ed-white);
        box-shadow:vat(--ed-shadow-df);   
        
        .image, .txt{
             padding:10px;
        }

        .image{
           border-radius:10px;
            overflow:hidden;

              img{
                  height:200px;
                  border-radius:10px;
                  object-fit:cover;
              }
        }

        .txt{
            background:var(--ed-silver-light);  

            p{
                 color:var(--ed-dark);
            }

            .lk{
                font-size:14px;
                margin-top:10px;

                .icon{
                    svg{
                        width:18px;
                        height:18px;
                        margin-right:5px;
                        color:var(--ed-main);
                        fill:var(--ed-main);
                   }
                }
            }
        }
     }
`;


export default Comp_offices