import axios from 'axios';
import React, { useEffect, useState } from 'react'
import { Alert, Form } from 'react-bootstrap';
import toast from 'react-hot-toast';
import styled from 'styled-components';
import Hoot from '../../../General/components/Hoot';
import GetTypeOfInstitute from '../../../General/components/GetTypeOfInstitute';
import Loader from '../../../General/components/Loader';

function PDrestrictions() {
    const [Quarter1, setQuarter1] = useState(false);
    const [Quarter2, setQuarter2] = useState(false);
    const [Quarter3, setQuarter3] = useState(false);
    const [ExamNote, setExamNote] = useState(false);
    const [SpecialExamNote, setSpecialExamNote] = useState(false);
    const [Presence, setPresence] =  useState(false);
    const [Loading, setLoading] = useState(false);

    async function GetCurrentRestrictions() {
        try {
            const response = await axios.get(Hoot() + "eduallgetquarterpermittions/get");
            if (response.data.length > 0) {
                console.clear();
                console.log(response.data[0]);
                setQuarter1(response.data[0].ed_quarterly_restriction_first_quarter === 1);
                setQuarter2(response.data[0].ed_quarterly_restriction_second_quarter === 1);
                setQuarter3(response.data[0].ed_quarterly_restriction_third_quarter === 1);
                setSpecialExamNote(response.data[0].ed_quarterly_restriction_specialexam === 1);
                setExamNote(response.data[0].ed_quarterly_restriction_exam === 1);
                setPresence(response.data[0].ed_quarterly_restriction_presence === 1)
            } else {
                toast.error("Lamentamos mas não foi  possivel encontrar os dados de restrições !");
            }
            setLoading(true)
            setTimeout(() => {
                console.log(response.data[0])
            }, 1000);
        } catch (error) {
            console.clear();
            console.log(error);
            setLoading(true)
            const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel encontrar os dados de restrições !";
            toast.error(msg);
        }
    }
 

    useEffect(() => {
        setTimeout(() => {
            GetCurrentRestrictions();
        }, 500);
    }, []);


    async function ApplyChanges(type, status) { 
        if (type === 1) setQuarter1(status);
        if (type === 2) setQuarter2(status);
        if (type === 3) setQuarter3(status);
        if (type === 4) setSpecialExamNote(status);
        if (type === 5) setExamNote(status);
        if (type === 6) setPresence(status);
     
        const formData = {
            firstQuarter: (type === 1 ? status : Quarter1) ? 1 : 0,
            secondQuarter: (type === 2 ? status : Quarter2) ? 1 : 0,
            thirdQuarter: (type === 3 ? status : Quarter3) ? 1 : 0,
            SpecialExam: (type === 4 ? status : SpecialExamNote) ? 1 : 0,
            Exam: (type === 5 ? status : ExamNote) ? 1 : 0,
            presence: (type === 6 ? status : Presence) ? 1 : 0,
        };
    
        try { 
            axios.put(Hoot() + "eduallpedagogyrestriction/update", formData).then(() => { 
                toast.success("Permissões atualizadas com sucesso  !"); 
            }).catch((error) => {
                const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
                toast.error(msg); 
                console.clear();
                console.log(error);
                GetCurrentRestrictions(); 
            });
        } catch (error) {
            const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
            toast.error(msg);
            GetCurrentRestrictions();
            console.clear();
            console.log(error);
        }
    }
    


 
    return (
        <Box> 
            <Alert variant='info'>
                <samll style={{ fontSize: "13px" }} > 
                    Este formulário permite configurar as restrições de lançamento e atualização de notas  e de presenças  na plataforma. <br />
                    Apenas o Diretor Pedagógico da instituição tem permissão para alterar estas configurações.
                </samll>
            </Alert>
            {Loading === true ?  
            <section className="ed-wrap gap">

                {GetTypeOfInstitute() === 0 ?
                    <>
                        <article className="box">
                            <div className="ed-space">
                                <div><strong>Notas do Iº Trimestre</strong></div>
                                <div>
                                    <Form.Check
                                        type="switch"
                                        checked={Quarter1}
                                        id="custom-switch-1"
                                        onChange={(e) => ApplyChanges(1, e.target.checked)}
                                    />
                                </div>
                            </div>
                            <small className="grey-text">Ativa ou desativa a edição de notas e presenças no primeiro trimestre.</small>
                        </article>

                        <article className="box">
                            <div className="ed-space">
                                <div><strong>Notas do IIº Trimestre</strong></div>
                                <div>
                                    <Form.Check
                                        type="switch"
                                        checked={Quarter2}
                                        id="custom-switch-2"
                                        onChange={(e) => ApplyChanges(2, e.target.checked)}
                                    />
                                </div>
                            </div>
                            <small className="grey-text">Controla o acesso à edição de notas e presenças no segundo trimestre.</small>
                        </article>

                        <article className="box">
                            <div className="ed-space">
                                <div><strong>Notas do IIIº Trimestre</strong></div>
                                <div>
                                    <Form.Check
                                        type="switch"
                                        checked={Quarter3}
                                        id="custom-switch-3"
                                        onChange={(e) => ApplyChanges(3, e.target.checked)}
                                    />
                                </div>
                            </div>
                            <small className="grey-text">Controla o acesso à edição de notas e presenças no terceiro trimestre.</small>
                        </article>
                    </> :

                    <>
                        <article className="box">
                            <div className="ed-space">
                                <div><strong>Notas do Iº Semestre</strong></div>
                                <div>
                                    <Form.Check
                                        type="switch"
                                        checked={Quarter1}
                                        id="custom-switch-1"
                                        onChange={(e) => ApplyChanges(1, e.target.checked)}
                                    />
                                </div>
                            </div>
                            <small className="grey-text">Ativa ou desativa a edição de notas e presenças no primeiro trimestre.</small>
                        </article>

                        <article className="box">
                            <div className="ed-space">
                                <div><strong>Notas do IIº Semestre</strong></div>
                                <div>
                                    <Form.Check
                                        type="switch"
                                        checked={Quarter2}
                                        id="custom-switch-2"
                                        onChange={(e) => ApplyChanges(2, e.target.checked)}
                                    />
                                </div>
                            </div>
                            <small className="grey-text">Controla o acesso à edição de notas e presenças no segundo trimestre.</small>
                        </article>
                    </>
                }


                <article className="box">
                    <div className="ed-space">
                        <div><strong>Notas do recurso</strong></div>
                        <div>
                            <Form.Check
                                type="switch"
                                checked={SpecialExamNote}
                                id="custom-switch-4"
                                onChange={(e) => ApplyChanges(4, e.target.checked)}
                            />
                        </div>
                    </div>
                    <small className="grey-text">Permite ou restringe a edição das notas de recurso (exame especial).</small>
                </article>

                <article className="box">
                    <div className="ed-space">
                        <div><strong>Notas do exame</strong></div>
                        <div>
                            <Form.Check
                                type="switch"
                                checked={ExamNote}
                                id="custom-switch-5"
                                onChange={(e) => ApplyChanges(5, e.target.checked)}
                            />
                        </div>
                    </div>
                    <small className="grey-text">Permite ou restringe a edição das notas de exame.</small>
                </article>

                <article className="box">
                    <div className="ed-space">
                        <div><strong>Presença escolar do aluno</strong></div>
                        <div>
                            <Form.Check
                                type="switch"
                                checked={Presence}
                                id="custom-switch-6"
                                onChange={(e) => ApplyChanges(6, e.target.checked)}
                            />
                        </div>
                    </div>
                    <small className="grey-text">Permite ou restringe a marcação de presenças escolares dos alunos.</small>
                </article>
            </section> 
            : 
             <div className="ed-center col  ed-flex"> 
                  <Loader absolute />
                <br />
             </div> 
            }  
        </Box>
    )
}



const Box = styled.div`
    width:100%; 
    border-radius:6px;   
    padding:20px;
    min-height:450px;
    height:auto;
    background:var(--ed-white);  
    box-shadow:var(--ed-shadow-df);
    margin:10px 0;
    position:relative;
    overflow:hidden;

    small{
       font-size:13px !important;
    }

     
    .gap{
        gap:10px;
    }

    article{
       border:1px solid var(--ed-silver-light);
       padding:20px;
       border-radius:10px;
       width:32%;
    }
 
`;

export default PDrestrictions
