import React from 'react'
import styled from "styled-components";

function Comp_LatestJobs() {
return (
    <Container>
        <h1 className="title">Empregos </h1>
        <div className="line"></div>
        <ul className="ed-flex ed-wrap">
           {[1,2,3,4].map((item, index)=>(
              <li key={index+1}>
                <h5>Engenheiro de sofware</h5>
                <div className="candidatures">13 candidaturas</div>
                <div className="location">Angola, luanda Mutamba</div>
              </li>
           ))}
        </ul>
    </Container>
    )
}

const Container = styled.div`
    ul{
         margin:20px 0px;
         padding:0px;

         li{
            list-style:none; 
            margin:0px;
            margin-top:20px;
            margin-right:20px;
            width:350px;
            border:1px solid var(--ed-silver-light);
            padding:10px;
            display:block;
            min-height:130px; 
            border-radius:10px;
            box-shadow:var(--ed-shadow-df);

              h5{
                  font-size:16px;
                  font-weight:600;
                  margin:8px 0px;
              }

              div{
                  font-size:14px;
                  margin:4px 0px;
              }
         }
    }
`;

    
export default Comp_LatestJobs