import axios from 'axios';
import React, { useState } from 'react' 
import { toast } from 'react-hot-toast'; 
import { Button, Form } from 'react-bootstrap';
import { Update } from '@mui/icons-material';

function MN_GeneralView() {
  return (
    <div>
    <Form className='col'  method='post' encType='multipart/form-data'>
       <div className="title"><h2>Detalhes da conta</h2></div>
       <div className="description">
         <p>Para alterar as suas informações de conta e necessário fazer login com o seu email, e dirigir-se para o perfil de usuário clicar
          em definições , e fazer as alterações pretendidas.</p>
          </div>
        <Form.Group className="mt-4"  >
           <div className="col-lg-12">
               <div className="ed-space">
                   <div>
                      <Form.Label> <strong>Nome</strong> </Form.Label>
                   </div>
                   <div className='col-lg-8'>
                      <Form.Control    type="text"  readOnly   />  
                   </div>
               </div> 
           </div> 
       </Form.Group>
       <hr />
       <Form.Group className="mt-4"  >
           <div className="col-lg-12">
               <div className="ed-space">
                   <div>
                      <Form.Label> <strong>Nome de usuário</strong> </Form.Label>
                   </div>
                   <div className='col-lg-8'>
                      <Form.Control    type="text" readOnly  />  
                   </div>
               </div> 
           </div> 
       </Form.Group>
       <hr />
       <Form.Group className="mt-4"  >
           <div className="col-lg-12">
               <div className="ed-space">
                   <div>
                      <Form.Label> <strong>Email</strong> </Form.Label>
                   </div>
                   <div className='col-lg-8'>
                      <Form.Control    type="text"  readOnly   />  
                   </div>
               </div> 
           </div> 
       </Form.Group>
       
   </Form>
</div>)
}

export default MN_GeneralView