import React, { useState } from "react";
import { Modal, Button, Form } from "react-bootstrap";
import { toast } from "react-hot-toast";
import axios from "axios";
import { SlCloudDownload } from "react-icons/sl";
import AddCircleOutlineIcon from "@mui/icons-material/AddCircleOutline";
import DraggableModal from "../../../General/components/DraggableModal";
import Hoot from "../../../General/components/Hoot";
import UserOptionDropDown from "../elements/UserOptionDropDown";
import SaveButton from "../elements/SaveButton";
import { ModalAnimationClose, ModalAnimationShow } from "../../../General/components/ModalAnimations";

function DownloadSaft(props) {
  const [show, setShow] = useState(false);
  const [showBox, setShowBox] = useState(false);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});

  const currentYear = new Date().getFullYear();

  const years = Array.from(
    { length: currentYear - 2023 + 1 },
    (_, i) => 2023 + i
  );

  const months = [
    { value: 1, label: "Janeiro" },
    { value: 2, label: "Fevereiro" },
    { value: 3, label: "Março" },
    { value: 4, label: "Abril" },
    { value: 5, label: "Maio" },
    { value: 6, label: "Junho" },
    { value: 7, label: "Julho" },
    { value: 8, label: "Agosto" },
    { value: 9, label: "Setembro" },
    { value: 10, label: "Outubro" },
    { value: 11, label: "Novembro" },
    { value: 12, label: "Dezembro" },
  ];

  const handleClose = () => {
    setShowBox(false);
    setTimeout(() => setShow(false), 1200);
  };

  const handleShow = () => {
    setShowBox(true);
    setShow(true);
  };

  const setField = (field, value) => {
    setForm({ ...form, [field]: value });
    if (!!errors[field]) setErrors({ ...errors, [field]: null });
  };

  const validateForm = () => {
    const { year, month } = form;
    const NewErrors = {};
    setRegisterStatus(0);

    if (!year || year === "") NewErrors.year = "Ano é obrigatório!";
    if (!month || month === "") NewErrors.month = "Mês é obrigatório!";

    return NewErrors;
  };

  const handleDownload = async (e) => {
    e.preventDefault();
  
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os campos obrigatórios");
      setRegisterStatus(1);
      return;
    }
  
    const toastId = toast.loading("Baixando SAFT...");
  
    try {
      const res = await axios.get(
        Hoot() + `eduallvendus/saft/${form.year}/${form.month}`,
        { responseType: "blob" }
      );
  
      // Criar URL para download
      const url = window.URL.createObjectURL(new Blob([res.data]));
      const link = document.createElement("a");
      link.href = url;
      link.setAttribute("download", `SAFT_${form.year}_${form.month}.xml`);
      document.body.appendChild(link);
      link.click();
      link.remove();
  
      toast.dismiss(toastId);
      toast.success("SAFT baixado com sucesso!");
      setRegisterStatus(2);
      handleClose();
  
    } catch (error) {
      toast.dismiss(toastId);
  
      let msg = "Erro ao baixar SAFT";
  
      if (error.response && error.response.data) {
        try { 
          const text = await error.response.data.text();
          const data = JSON.parse(text);
          msg = data.msg || msg;
        } catch (e) { 
        }
      }
  
      toast.error(msg);
      setRegisterStatus(1);
    }
  };
  
  

  return (
    <div>
      <div onClick={handleShow}>
        {props.toggle_btn ? (
          props.toggle_btn
        ) : (
          <button className="btn text-dark btn-export-data-1  mr-2">
              <SlCloudDownload /> Baixar SAFT
          </button>
        )}
      </div>

      <Modal
        size="md"
        dialogAs={DraggableModal}
        centered
        className={showBox ? ModalAnimationShow() : ModalAnimationClose()}
        show={show}
        onHide={handleClose}
      >
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>Baixar SAFT</h5>
            </div>
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={handleDownload}>
          <Modal.Body className="scrollLimit">
            <Form.Group className="mb-3">
              <Form.Label>Ano <span className="text-danger ml-2">*</span></Form.Label>
              <Form.Select
                value={form.year || ""}
                onChange={(e) => setField("year", e.target.value)}
                isInvalid={!!errors.year}
              >
                <option value="">Selecione o ano</option>
                {years.map((y) => (
                  <option key={y} value={y}>
                    {y}
                  </option>
                ))}
              </Form.Select>
              <Form.Control.Feedback type="invalid">
                {errors.year}
              </Form.Control.Feedback>
            </Form.Group>

            <Form.Group>
              <Form.Label>Mês <span className="text-danger ml-2">*</span></Form.Label>
              <Form.Select
                value={form.month || ""}
                onChange={(e) => setField("month", e.target.value)}
                isInvalid={!!errors.month}
              >
                <option value="">Selecione o mês</option>
                {months.map((m) => (
                  <option key={m.value} value={m.value}>
                    {m.label}
                  </option>
                ))}
              </Form.Select>
              <Form.Control.Feedback type="invalid">
                {errors.month}
              </Form.Control.Feedback>
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <div className="ed-space">
              <Button className="bg-light text-dark" onClick={handleClose}>
                Cancelar
              </Button>
              <SaveButton title="Baixar" status={RegisterStatus} />
            </div>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  );
}

export default DownloadSaft;
