import React, { forwardRef, useImperativeHandle, useState, useId, useRef } from 'react';
import { FaCamera, FaTimes } from 'react-icons/fa';
import styled from 'styled-components';
import { Avatar } from '@mui/material';
import PictureModal from './PictureModal';
import { IoCameraOutline } from "react-icons/io5";

const ImagePreview = forwardRef((props, ref) => {
    const uniqueID = useId();  // Garante um ID único por instância
    const inputID = props.inputID || `imageUpload-${uniqueID}`;  // Garante que o ID seja único

    const [imgPreview, setImgPreview] = useState(null);
    const [Image, setImage] = useState(null);
    const [ImageError, setImageError] = useState(false);

    const handleImageChange = (e) => {
        const selected = e.target.files[0];
        const allowedExtensions = ["image/png", "image/jpeg", "image/jpg"];

        if (selected && allowedExtensions.includes(selected.type)) {
            setImageError(false);
            let reader = new FileReader();
            reader.onloadend = () => { 
                setImgPreview(reader.result);
            };
            reader.readAsDataURL(selected);

            setImage(selected);
            props.Picture(selected);
        } else {
            setImageError(true);
            props.Picture(null);
        }
    };

    // Function to handle the captured image from the camera
    const handleCapturedImage = (file, previewUrl) => {
        setImage(file);
        setImgPreview(previewUrl);
        props.Picture(file);
    };

    useImperativeHandle(ref, () => ({
        RemoveImage() {
            setImgPreview(null);
            setImage(null);
            props.Picture(null);
            setImageError(false);
        }
    }));

    const RemoveImage = () => {
        setImgPreview(null);
        setImage(null);
        props.Picture(null);
        setImageError(false);
    };

    return (
        <Preview> 
            <div className="imgPreview">
                <div className="avatar-box">
                    {/* label agora corretamente vinculado ao input */}
                    <label htmlFor={inputID}>
                        <Avatar 
                            variant={props.rounded ? "rounded" : ""} 
                            className='df' 
                            sx={{ width: 160, height: 160 }} 
                            src={imgPreview || props.Cover} 
                            alt="Uploaded Image" 
                        />
                    </label>
                    {imgPreview && (
                        <div className='removeAvatarImage' onClick={RemoveImage}>
                            <FaTimes />
                        </div>
                    )}
                </div>
                <input 
                    type="file" 
                    onChange={handleImageChange}   
                    id={inputID}  // Aqui o ID é associado diretamente
                    style={{ display: 'none' }}  // O input fica oculto
                />
                <div className="ed-flex ed-center">
                    {!props.NoCam && (
                        <PictureModal 
                            Picture={handleCapturedImage}
                            toggle_btn={
                                <li className='btn center btn-call-cam bg-main'>
                                    <IoCameraOutline />
                                </li>
                            } 
                        />
                    )}
                </div> 
            </div>
            {ImageError && <p className='errorMsg text-danger mt-2'>Ficheiro não suportado</p>}
        </Preview>
    );
});

const Preview = styled.div`
    display: flex;
    align-items: center;
    justify-content: center;
    flex-direction: column;

    .btn-call-cam {
        border-radius: 100%;
        height: 40px;
        width: 40px;
        padding: 0px;
        margin-top: -20px;
        margin-right: 10px;
        font-size: 14px !important;
    }

    .avatar-box {
        position: relative;
        margin-right: 20px;
        display: flex;
        align-items: center;
        justify-content: center;
        flex-direction: column;

        .removeAvatarImage {
            position: absolute;
            top: 30px;
            left: -5px;
            width: 28px;
            height: 28px;
            background: var(--ed-white);
            border-radius: 100%;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            box-shadow: var(--ed-shadow-1);

            svg {
                width: 10px;
                margin: 0;
                height: 10px;
                fill: var(--ed-red);
            }
        }

        .image-preview {
            min-width: 200px;
            min-height: 175px;
            width: 200px;
            height: 175px;
            border-radius: 6px;
            position: relative;
            display: flex;
            justify-content: center;
        }
    }

    li {
        width: 45px;
        height: 40px;
        box-shadow: var(--ed-shadow-df);
        border-radius: 4px;
        background: var(--purple);
        margin-top: -35px;
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        z-index: 100;
        position: relative;

        svg {
            fill: var(--ed-white);
            width: 22px;
            height: 22px;
            margin: 0;
        }
    }
`;

export { ImagePreview };
