import React, { useState } from 'react'
import { Button, Modal } from 'react-bootstrap'
import { AppsOutline } from 'react-ionicons'
import UserOptionDropDown from './UserOptionDropDown'
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations'
import ImageLazyLoading from '../../../General/components/ImageLazyLoading'
import DraggableModal from '../../../General/components/DraggableModal'

function AppsPopup() {
    const [show, setShow] = useState(false);
    const [showBox, SetshowBox] = useState(false);

    const handleClose = () => {
        SetshowBox(false);
        setTimeout(() => {
            setShow(false);
        }, 1200);
    }

    const handleShow = () => {
        SetshowBox(true);
        setShow(true);
    };


    return (
        <div>
            <Button className='bg-white text-dark' onClick={handleShow}>
                <AppsOutline />
            </Button>
            <Modal size='md' centered dialogAs={DraggableModal} className={showBox ? ModalAnimationShow() : ModalAnimationClose()} show={show} onHide={handleClose}>
                <Modal.Header closeButton>
                    <Modal.Title>
                        <div className="ed-wrap align-center">
                            <UserOptionDropDown />
                            <h5>Instalar aplicativos </h5>
                        </div>
                    </Modal.Title>
                </Modal.Header>
                <Modal.Body className='scrollLimit'> 
                  <div className="ed-center">
                     <h5>Informação !</h5>
                  </div>
                  <div className="ed-center">
                  <small>No momento, não existem aplicativos disponíveis para instalação no sistema. Fique atento às atualizações, em breve teremos novidades!
                        <br />
                        Para mais informações, entre em contacto com o suporte.
                    </small>
                  </div>
                </Modal.Body>
            </Modal>
        </div>
    )
}

export default AppsPopup
