const TABLEURL = [
  Hoot()+"edualllessonsectionbygroupcode/",
  Hoot()+"eduallgetlessoncontentbysection/get/"
];


async function loadData(){  
  console.log(filters);
if(filters.type*1 === 0){
   //load teacher lesson content
   setLoaded(false);
   try {
     const response = await axios.get(TABLEURL[0]+filters.code); 
     const rows = [];
     const Lessons  = [];
     
     response.data.map((item, index)=>{   
        rows.push({ 
          section_index:index,
          section_id:item.ed_lesson_section_id,
          section_title:item.ed_lesson_section_title,
          section_code:item.ed_lesson_section_groupCode,
          section_data:[] 
       });
     });
 

   if(rows.length >= 1){
    rows.map((item, index)=>{
      const SectionLessons = async()=>{
        try {
          const response1 = await axios.get(TABLEURL[1]+item.section_id);  

          if(index === rows.length-1) {
            setTimeout(() => {
              setLoaded(true);
            }, 200);
          }


          response1.data.map((contentItem, ind)=>{
             Lessons.push(ind); 
             item.section_data.push(contentItem);
          });

        } catch (error) {}  
      }
     SectionLessons();
    }); 

    console.log(rows)
    setData(rows); 
    setTotalLessons(Lessons);
   }else{
    setLoaded(true);
    setData([]);
   }
   }catch(error){
    console.clear();
    console.log(error); 
      setLoaded(true);
   }
}else{
   //load course content

}
};


