import React, { useEffect } from 'react'
import UserNavbar from './Components/UserNavbar'
import styled from 'styled-components';
import MenuLeft from './Components/MenuLeft';
import MenuRight from './Components/MenuRight';
import { useState } from 'react';
import ImageLazyLoading from '../General/components/ImageLazyLoading';
import { LuLayoutDashboard } from "react-icons/lu";
import { IoSettingsOutline } from "react-icons/io5";
import { LuUserRound } from "react-icons/lu";
import { LuGraduationCap } from "react-icons/lu";
import { PiBaby } from "react-icons/pi";
import ReduceTextLength from '../General/components/ReduceTextLength';
import { Link } from 'react-router-dom';
import AccountModal from '../Dashboard/components/elements/AccountModal/Index';
import { Avatar } from '@mui/material';
import Hoot from '../General/components/Hoot';
import { Offcanvas } from 'react-bootstrap';
import { Close } from 'react-ionicons';
import { RiMenu4Line } from 'react-icons/ri';

const Logo = require('../Assets/images/logos/black/eduall-workspaces.png');
const Logowhite = require('../Assets/images/logos/white/eduall_workspace_white.png');

function WorkSpaces({ userdata }) { 
  document.title = "eduall - Áreas de trabalho";
  const [isLoading, SetLoading] = useState(false);
  let lettername = '';

  if (userdata?.user_Information?.ed_user_account_name) {
    const nameParts = userdata.user_Information.ed_user_account_name.trim().split(/\s+/);
  
    const firstInitial = nameParts[0]?.[0]?.toUpperCase() || '';
    const lastInitial = nameParts[nameParts.length - 1]?.[0]?.toUpperCase() || '';
  
    lettername = firstInitial + lastInitial;
  }
  


  const [showMenu, setShowMenu] = useState(false);
  const handleClose = () => setShowMenu(false);
  const handleShow = () => setShowMenu(true);


  const accountsData = userdata;

  const [show, setShow] = useState(false);
  const [GifItem, setGifItem] = useState(null);
  const [text, setText] = useState("");
  const [data, setData] = useState([]);

  const GetFeedPosts = async () => {
    SetLoading(false);
  }

  const getGifImage = (e) => { 
    setShow(false);
  }


  useEffect(() => {
    GetFeedPosts(); 
  }, []);


  function MenuWrap({ formobile }) {
    return (
      <div className={formobile ? "nav-theme sidebar-data mobile" : "nav-theme sidebar-data normal"} >
        <aside>
          <div className="top-nav">
            <div className="ed-space">
              <div className="logo-nav">
                <div className="user-nav-logo">
                    <div className="logo1"><ImageLazyLoading source={Logo} /></div>
                    <div className="logo2"><ImageLazyLoading source={Logowhite} /></div>
                </div>
              </div>
              <div className={!formobile ? "d-none" : ""}>
                 <div className="cursor-pointer close-menu-workspace" onClick={handleClose}><Close /></div>
              </div>
            </div>
          </div>
          <ul>
            <li>
              <Link to="/WorkSpaces">
                <div className="toggle-menu bg-main text-light">
                  <LuLayoutDashboard /><span>Áreas de trabalho</span>
                </div>
              </Link>
            </li>

            {/* Contas de professor */}
            <li className={accountsData.user_institutes.length > 0 ? "" : "d-none"}>
              <div className="toggle-menu">
                <LuUserRound /><span>Contas do professor</span>
              </div>
              <ol className="menu-items active">
                {accountsData.user_institutes.map((item, index) => (
                  <li key={index}>
                    <Link to={`/teacher_dashboard/${item.ed_institute_code}`} className="grey-text">
                      <div className="ed-flex">
                        <Avatar variant="rounded" className="df" 
                         src={Hoot() + item.ed_institute_logo} sx={{ width: 25, height: 25 }} />
                        <div className="name ml-2">
                          <ReduceTextLength text={item.ed_institute_name} length={20} />
                        </div>
                      </div>
                    </Link>
                  </li>
                ))}
              </ol>
            </li>

            {/* Contas do aluno */}
            <li className={accountsData.user_student_accounts.length > 0 ? "" : "d-none"}>
              <div className="toggle-menu">
                <LuGraduationCap /><span>Contas do aluno</span>
              </div>
              <ol className="menu-items active">
                {accountsData.user_student_accounts.map((item, index) => (
                  <li key={index}>
                    <Link to={`student_portal/${item.ed_student_id}`} className="grey-text">
                      <div className="ed-flex">
                        <Avatar className="df"  src={Hoot() + item.ed_student_picture} sx={{ width: 25, height: 25 }} alt={item.ed_student_name} />
                        <div className="name ml-2">
                          <ReduceTextLength text={item.ed_student_name} length={20} />
                        </div>
                      </div>
                    </Link>
                  </li>
                ))}
              </ol>
            </li>

            {/* Contas de encarregado */}
            <li className={accountsData.user_childs.length > 0 ? "" : "d-none"}>
              <div className="toggle-menu">
                <PiBaby /><span>Contas de encarregado</span>
              </div>
              <ol className="menu-items active">
                {accountsData.user_childs.map((item, index) => (
                  <li key={index}>
                    <Link to={`parent_portal/${item.ed_student_id}`} className="grey-text">
                      <div className="ed-flex">
                        <Avatar className="df"  src={Hoot() + item.ed_student_picture} sx={{ width: 25, height: 25 }} alt={item.ed_student_name} />
                        <div className="name ml-2">
                          <ReduceTextLength text={item.ed_student_name} length={20} />
                        </div>
                      </div>
                    </Link>
                  </li>
                ))}
              </ol>
            </li>
          </ul>

        </aside>
        <aside>
          <ul>
            <AccountModal data={userdata.user_Information} toggle_btn={
              <li className="toggle-settings theme-light-txt">
                <IoSettingsOutline /> Definições de conta
              </li>
            } />
          </ul>
        </aside>
      </div>
    )
  }


  return (
    <Wrapper>
      <div className="eduall_network">
        <div className="d-flex"> 
          <MenuWrap />
          <Content>
            <div className="nav-mob-1">
               <UserNavbar nologo data={userdata} />
            </div>
            <div className='nav-mob-2'>
                 <UserNavbar logoIndex={0} noquote data={userdata} menu={0} />
            </div>
            <Container className='col  body-theme bg-background'>
              <aside> 
                <div className="ed-space ed-flex">
                  <div>
                     <h1 className="title theme-light-txt">Aréas de trabalho 
                         <a href="#" target="_blank" rel="noopener noreferrer" className='text-main ml-1'>#eduall</a>
                      </h1>
                  </div>
                  <div className="menu-toggle-workspace">
                    <button className='toggle-menu ml-2' show={showMenu} onClick={handleShow}><RiMenu4Line /></button>
                    <Offcanvas show={showMenu} onHide={handleClose}>
                      <Offcanvas.Body className='pd0 pd-0'>
                        <Wrapper>
                          <MenuWrap formobile />
                        </Wrapper>
                      </Offcanvas.Body>
                    </Offcanvas>
                  </div>
                </div>
                <MenuLeft data={userdata} />
                <div className="ed-flex ed-center mt-4">
                   <div style={{maxWidth:"800px"}}>
                   <small className="grey-text">
                    Se você já teve acesso a espaços de trabalho e eles deixaram de aparecer, pode ser que a instituição tenha removido seu vínculo ou que a licença Eduall tenha expirado. Nesses casos, o ambiente de trabalho é ocultado até que a licença seja renovada.
                  </small> 
                   </div>
                </div>
              </aside>
            </Container>
          </Content>
        </div>
      </div>
    </Wrapper>
  )
}


const Container = styled.div`
  width:100%; 
  height:calc(100vh - 80px);
  max-height:calc(100vh - 80px);
  overflow-y:auto;  
  background:var(--ed-background-color);  
  padding:30px 20px;
 
   h2.subtitle{
     font-size:18px;
     font-weight:bold;
     margin:10px 0px;
  }
 

  .menu-toggle-workspace{
    display:none;
    
    .toggle-menu{
      width:40px;
      height:40px;
      display: flex;
      align-items: center;
      justify-content: center;
      border-radius:100%;
      cursor: pointer;
      margin-left:10px; 
      border:1px solid var(--ed-silver-light);
      background:var(--ed-white);
     }
  }


`;


const Wrapper = styled.div`    
  width:100%;
  height:auto;   
  min-height:500px; 
  position:relative;  
  min-width:200px; 
  margin:0 auto;

  .nav-mob-2{
      display:none;
  }



  .sidebar-data.mobile{
      width:100%;
      height:auto !important;
      box-shadow:unset !important; 
      min-width:auto !important; 
      max-width:400px !important; 

       ul{
          padding:10px 20px; 
      }
  }

  .sidebar-data{
     width:350px;
     min-width:350px;
     height:100vh;
     background:var(--ed-white);
     box-shadow:var(--ed-shadow-1); 
     display:flex;
     flex-direction:column;
     justify-content:space-between;

      .toggle-menu.bg-main{
          padding:10px;
          border-radius:6px;
          margin-bottom:10px;
      }


    ul{
        padding:20px;
        margin:0px;
        
       li{
           padding:5px 0px;
           margin:5px 0px;
           cursor:pointer; 
           list-style:none;

            svg{
                font-size:20px;
                width:20px;
                height:20px;
                margin-right:10px;
            } 
        } 
     } 
  }

  .top-nav{
    height:80px;
    width:100%;
    display:flex;
    align-items:center;
    border-bottom:1px solid var(--ed-silver-light);
    padding:0px 20px;

    .logo-nav img{
       max-width:250px;
     } 



  }

   
`;


const Content = styled.div`
  display:block;
  width:100%; 
  height:100vh;

  
`;


export default WorkSpaces