import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { WarningOutline } from 'react-ionicons';
import Hoot from './Hoot';  

function AlertsBox({ Access }) {
  const [alert, setAlert] = useState(null); 

  async function loadAlert() {
    if (Access * 1 === 1) { 
      try {
        const response = await axios.get(Hoot() + 'alerts/latest');
        if (response.data.success && response.data.alert) {
          setAlert(response.data.alert);
        } else {
          setAlert(null);  
        }
      } catch (error) {
        console.error("Erro ao carregar alertas:", error);
      }
    }
  }

  useEffect(() => {
    loadAlert();
  }, []);

  if (!alert) return null;   
  return (
    <section>
      <div className="alert-area ed-flex ed-center">
        <div className="box ed-flex ed-center">
          <div className="ed-flex">
            <WarningOutline color={"#ffff"} width={"25px"} height={"25px"} />
            <div className="ml-2">
              <h1>{alert.title}</h1>
              <p>{alert.message}</p>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}

export default AlertsBox;
