import React from 'react'
import ImageLazyLoading from '../../../General/components/ImageLazyLoading'
import styled from 'styled-components'


function Profile_gn_hobies({data}){
  return (
    <Container>
     <h1 className="title">Hobies</h1>
       <ul>
       {[1,2,3,4,5].map((item, index)=>{
            return(
            <li key={index}>
               <ImageLazyLoading source="" height={200} />
               <span>Musica</span>
            </li>) 
        })}
       </ul>
    </Container>
   )
 }
 
 
 const Container = styled.div`
    margin:20px 0px;
 
      ul{
         display:flex;
         align-items:center;
         padding:0px;
         margin:0px;
         margin-top:10px;
 
         li{
            width:190px;
            height:200px;
            border-radius:10px;
            overflow:hidden;                 
            margin-right:15px; 
            display:block;
            text-align:center;

               span{
                   font-size:16px;
                   margin-top:10px;
               }
         }
 
  } 
`;

export default Profile_gn_hobies
