import React, {useState} from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import {Modal, Form, Button} from 'react-bootstrap'
import { Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';

function NewDepartment(props) {
    const [show, setShow] = useState(false);
    const [RegisterStatus, setRegisterStatus] = useState(null);
     
    const [showBox, SetshowBox]  = useState(false);
    const handleClose = () => {
      SetshowBox(false);
      setTimeout(() => {
        setShow(false);
      }, 1200);
    } 

    const handleShow = () => {
          SetshowBox(true);
          setShow(true);  
          setTimeout(() => {  
          
         }, 1000);   
    };


  return (
   <div>
    <button className='btn btn-main bg-main' onClick={handleShow}>
        <AddCircleOutlineIcon/> Registrar departamento
   </button> 
    <Modal  centered  className={showBox ? ModalAnimationShow() : ModalAnimationClose()}  dialogAs={DraggableModal}  show={show} onHide={handleClose}>
    <Modal.Header closeButton>
      <Modal.Title>
      <div className="ed-wrap align-center">
            <UserOptionDropDown />
            <h5>Registrar departamento</h5>
        </div> 
      </Modal.Title>
    </Modal.Header>
    <Modal.Body className='scrollLimit'>
      <Form>
        <Form.Group className="mb-3"  >
          <Form.Label>Titulo<span className="text-danger ml-2">*</span> </Form.Label>
          <Form.Control required type="text" autoFocus/>
        </Form.Group>
        <Form.Group className="mb-3"  >
          <Form.Label>Código<span className="text-danger ml-2">*</span> </Form.Label>
          <Form.Control type="text" required/>
        </Form.Group> 
      </Form>
    </Modal.Body>
    <Modal.Footer>
     
    </Modal.Footer>
  </Modal>
   </div>
  )
}

export default NewDepartment