import React, { useEffect, useState } from 'react'
import CalendarBox from '../components/elements/CalendarBox';
import CalendarEventModal from '../components/modal/CalendarEventModal';
import { Link } from 'react-router-dom'; 
import SummarizeOutlinedIcon from '@mui/icons-material/SummarizeOutlined';
import axios from 'axios';
import { toast } from 'react-hot-toast';
import Hoot from '../../General/components/Hoot';


function CalendarsEvent() {
  document.title = "Calendário de eventos";
  const TABLEURL = Hoot()+"eduallgetcalendarevents/get";

  const [data, setData] = useState([]);  

  async function loadData(){
   try { 
       const response = await axios.get(TABLEURL); 
       const rows = [];
       response.data.map((item, index)=>{ 
         rows.push({
           id:item.ed_calendar_event_id,
           title:item.ed_calendar_event_title,
           start:item.ed_calendar_event_start,
           end:item.ed_calendar_event_end,
           color:item.ed_calendar_event_color, 
        })
       }); 
       setData(rows); 
   } catch (error) {
    toast.error("Lamentamos mas não foi  possivel carregar os dados !");
   }
  };
  
  useEffect(()=>{ 
      loadData();  
  },[]);



  return (
    <div>
        <div className="ed-flex ed-space m-">
            <div className="ed-flex">

            </div>
            <div className="ed-flex">
                <div className="d-none"><div className="el-refresh-list" onClick={()=>loadData()}></div></div>
                <div className="mr-2">
                   <Link to="/calendareventslist">
                      <button className='btn bg-green-light'><SummarizeOutlinedIcon/> Listagem de eventos </button>
                   </Link>
                </div>
               <CalendarEventModal />
            </div>
        </div>
        <CalendarBox Data={data} Drag={false}   />
    </div>
  )
}

export default CalendarsEvent
