import React from 'react'
import { Form } from 'react-bootstrap';
import ProgressBar from 'react-bootstrap/ProgressBar'; 
import SystemBillingsTable  from  "./SystemBillingsTable";

function BillingsSettings() {
  document.title = "Planos e pagamentos"

    const Data = [
        {
            currentplan: false,
            name: "Plano bronze",
            prices: [
                "180.999 AOA",
                "155.999 AOA",
                "138.999 AOA",
            ],
            desciption: [
                "(Ensino primario, Ensino escundario)",
                "Addmnistração",
            ],
        },
        {
            currentplan: false,
            name: "Plano bronze",
            prices: [
                "180.999 AOA",
                "155.999 AOA",
                "138.999 AOA",
            ],
            desciption: [
                "(Ensino primario, Ensino escundario)",
                "Addmnistração",
            ],
        },
        {
            currentplan: false,
            name: "Plano bronze",
            prices: [ 
                "180.999 AOA",
                "155.999 AOA",
                "138.999 AOA",
            ],
            desciption: [
                "(Ensino primario, Ensino escundario)",
                "Addmnistração",
            ],
        },
    ];

    return (
        <div className='billings-settings'>
            <div className="prices-card itembox">
                <h1 className="title">Planos e Pagamentos</h1>
                <p className='grey-text' >Lorem ipsum dolor sit amet consectetur adipisicing elit. Minus vitae quo consectetur cupiditate voluptates beatae esse aperiam blanditiis dignissimos impedit.</p>
                <br />
                <section className="ed-flex ed-wrap ed-space cards"> 
                    {Data.map((item, index) => (
                        <article className={item.currentplan === true ? "mt-2 active" : "mt-2"} key={index}>
                            <div className="ed-space ed-flex col">
                                <div><h1>{item.name}</h1></div>
                                <div><Form.Check type={"radio"} id={`default-radio`} /></div>
                            </div>
                            <div className="d-block mt-2 mb-2 col">
                                <div className="mb-2"><h2 className='ed-flex'>{item.prices[0]} <span className='ml-2 grey-text'> / mês</span> </h2></div>
                                <div><p className='grey-text'>pagamentos (Trimestral, Semeestral, Anual)</p></div>
                            </div><br />
                            {item.desciption.map((desc, ind) => (
                                <div><small className='grey-text' >{desc}</small></div>
                            ))}
                            <div className="ed-flex ed-space">
                                <button className="bg-black text-light btn col mt-2 mb-2">Comprar Agora</button>
                                <div className="pd-1"></div>
                                <button className="btn-outline text-white btn col">Saiba Mais</button>
                            </div>
                        </article>
                    ))} 
                </section>
            </div>
            <div className="itembox col mt-4">
                <h1 className="title">Controle do periodo da licença</h1>
                <p className='grey-text ed-flex'>345 dias pagos - <small className='ml-1 text-warning'> 134 restantes </small></p>
                <div className="col mt-4">
                    <ProgressBar variant='info' style={{ height: "10px" }} now={60} />
                </div>
            </div>
            <div className="mt-4">
            <SystemBillingsTable />
            </div>
        </div>
    )
}

export default BillingsSettings