import React, {useState, useEffect} from 'react'
import axios from 'axios'
import { Delete, Description, Edit , PreviewOutlined, Refresh } from '@mui/icons-material';
import Table from './Table';
import Hoot from '../../../General/components/Hoot';
import { GetAcademicYear, GetAcademicLevel, GetClassroom, GetCourse, GetSubjectAsOption } from '../../../General/components/InstituteData';
import NewClassModal from '../modal/NewClassModal';
import DeleteModal from '../elements/DeleteModal'; 
import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import ReplaceWord from '../../../General/components/ReplaceWord';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';


const TABLEURL = Hoot()+"eduallclassapi/get/";
const Periods = ["Manhã", "Tarde", "Noturno"];
 


const columns = [ 
  { field: 'index', headerName: 'Nº', width: 90,resizable: true }, 
   { field: 'id', headerName: 'code', width: 90,resizable: true }, 
  {
    field: 'title',
    headerName: 'Turma',
    width:310,
    resizable: true,
  },  
  {
    field: 'course',
    headerName: 'Curso',
    resizable: true, 
    width:230, 
  },
  {
    field: 'period',
    headerName: 'Periodo',
    width:130,
    editable: true 
  },
  {
    field: 'academiclevel',
    headerName: ReplaceWord("Classe"),
     resizable: true,
     width:150, 
  },
  {
    field: 'classroom',
    headerName: 'Nº da Sala',
     resizable: true, 
     width:120, 
  }, 
  {
    field: 'academicyear',
    headerName: 'Ano letivo',
    resizable: true,
    width:130, 
  },
  {
    field: 'action',
    headerName: 'Ação', 
    resizable: true,
    cellRenderer:(props) => { 
      return <div className="ed-flex">
          <NewClassModal  title='Atualizar ' update='true' get={Hoot()+`eduallsingleclassapi/get/${props.data.id}`}  
          url={Hoot()+`eduallclassupdate/update/${props.data.id}`}  toggle_btn={
          <button  className="btn-circle bg-success text-light">
              <Edit/>
          </button> 
          } />
          <DeleteModal title='esta turma' url={Hoot()+`eduallclassdelete/delete/${props.data.id}`} 
           message='Turma deletada com sucesso !' toggle_btn={
            <button  className="btn-circle bg-danger ml-2 text-light">
               <Delete/>
            </button>
           }/> 
        </div> ;
    }
  } 
];

 

function ClassList(props) {
  const [data, setData] = useState([]);  
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData(){
    try {
      setLoadStatus(0); 
      setLoaded(false);
        const response = await axios.get(TABLEURL); 
        const rows = []; 
        response.data.map((item, index)=>{  
          rows.push({
            index:index+1,
            id:item.ed_class_id,
            title:item.ed_class_title,  
            code:item.ed_class_code,  
            course:item.ed_course_title,
            period:Periods[Math.floor(item.ed_class_period)],
            academiclevel:item.ed_academic_level_title,
            classroom:item.ed_classroom_title,
            academicyear:item.ed_academic_year_title,  
          })    
        }); 
        setData(rows); 
        setTimeout(() => {
          setLoaded(true);
        }, 200);
        setLoadStatus(2); 
    } catch (error) {
      setLoadStatus(1); 
    }
  };
  
  useEffect(()=>{ 
    loadData(); 
  },[]); 
 
 if(load){
  return (
    <div id="ed-custom-table-data">
      <TableGrid 
          TableHead={columns}
          TableBody={data} 
          TableTitle='Lista de turmas'
          TableBtn={
            <div className='ed-flex' > 
            <button id='ed-custom-table-data-btn'
              onClick={() =>
                ExportDataToTablesToPdf({
                  fileName: "Lista de turmas",
                  headerId: null,
                  contentId: "ed-custom-table-data",
                  footerId: null,
                  rotation: "portrait",
                  buttonId: "ed-custom-table-data-btn",
                  customHeader: "Lista de turmas",
                  excludedColumns: ["Ação"]
                })
              }
              className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
            </button> 
            <button className='btn-icon btn btn-export-data ml-2' 
               onClick={()=>ExportDataForTablesExcel("turmas ", ["Ação"], "ed-custom-table-data")}><PiMicrosoftExcelLogoDuotone />
            </button>
           <RefreshButton action={loadData} status={LoadStatus} />
       </div>}
      />
  </div>
  ) 
 }else{
  return (
    <div>
      <div className="d-none">*</div>
      <TableGrid 
          TableHead={columns}
          TableBody={[]} 
          TableTitle='Lista de turmas'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
      />
  </div>
  ) 
 }
}

export default ClassList
 

 