import React, {useState, useEffect} from 'react'
import axios from 'axios'
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import { Delete, Description, Edit , PreviewOutlined, Refresh } from '@mui/icons-material';
import Table from './Table';
import Hoot from '../../../General/components/Hoot';
import NewClassRoomModal from '../modal/NewClassRoomModal';
import DeleteModal from '../elements/DeleteModal';
import TableGrid from '../../../General/components/TableGrid';
import RefreshButton from '../../../General/components/RefreshButton';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';

const TABLEURL = Hoot()+"eduallclassroomapi/get/";
 

const columns = [ 
  { 
   field: 'index',
   headerName: 'Nº',  
   resizable: true,
   width:90,
  }, 
   { 
    field: 'title',
    headerName: 'Nº da Sala',  
    resizable: true,
   },   
  {
    field: 'action',
    headerName: 'Ação',  
     resizable: true,
      cellRenderer:(props) => { 
      return   <div className="ed-flex">
      <NewClassRoomModal  title='Atualizar ' update='true' get={Hoot()+`eduallsingleclassroomapi/get/${props.data.id}`}  
       url={Hoot()+`eduallclassroomupdate/update/${props.data.id}`}  toggle_btn={  
     <button classroom_code={props.data.id} className="btn-circle bg-success text-light">
         <Edit/>
     </button>  
     }/> 
      <DeleteModal title='esta Sala' url={Hoot()+`eduallclassroomdelete/delete/${props.data.id}`} message='Sala deletada com sucesso' toggle_btn={
         <button classroom_code={props.data.id} className="btn-circle bg-danger ml-2 text-light">
             <Delete/>
        </button>
      }/>
     </div>;
    }
  } 
];

function ClassroomList() {    
  const [data, setData] = useState([]);
  const [data1, setData1] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData(){
    setLoaded(false);
       try {
        setLoadStatus(0); 
        const response = await axios.get(TABLEURL); 
         const rows = []; 
         const rows1 = []; 
         response.data.map((item, index)=>{  
              rows.push({
              index:index+1,
              id:item.ed_classroom_id,  
              code:item.ed_classroom_code,
              title:item.ed_classroom_title,   
              action:'',  
          }) 
          rows1.push({
            index:index+1, 
            title:item.ed_classroom_title,  
        }) 
      });  
      setData(rows);
      setData1(rows1);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2); 
       } catch (error) {
        setLoaded(true);
        setLoadStatus(1); 
       }
  }

  useEffect(()=>{
      loadData();  
  },[]);

if(load){
    return (
    <div id="ed-custom-table-data" >
      <TableGrid
          TableHead={columns}
          TableBody={data}  
          TableTitle='Lista das salas'
          TableBtn={
            <div className='ed-flex' >

            <button id='ed-custom-table-data-btn'
              onClick={() =>
                ExportDataToTablesToPdf({
                  fileName: "Lista das salas",
                  headerId: null,
                  contentId: "ed-custom-table-data",
                  footerId: null,
                  rotation: "portrait",
                  buttonId: "ed-custom-table-data-btn",
                  customHeader: "Lista das salas",
                  excludedColumns: ["Ação"]
                })
              }
              className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
            </button>

            <button className='btn-icon btn btn-export-data ml-2' 
               onClick={()=>ExportDataForTablesExcel("salas ", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
            </button>
           <RefreshButton action={loadData} status={LoadStatus} />
       </div>}
      />
  </div>
  )
}else{
  return (
    <div>
      <div className="d-none">*</div>
      <TableGrid
          TableHead={columns}
          TableBody={[]} 
          TableTitle='Lista das salas'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
      />
  </div>
  )
}
}

export default ClassroomList