import React, { useState, useEffect } from 'react'
import { Avatar } from '@mui/material';
import { Link } from 'react-router-dom';
import axios from 'axios';
import { Check, Close, Delete, Edit, InfoOutlined } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import TableGrid from '../../../General/components/TableGrid';
import { Badge } from 'react-bootstrap';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import { GetJobTitle } from '../../../General/components/InstituteData';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import AttendanceModal from '../../../EduUsers/Employees/Components/Tabs/SubTabs/Modal/AttendanceModal';
import moment from 'moment';
import ReplaceWord from '../../../General/components/ReplaceWord';
import NewEmployeeAttendanceModal from '../modal/Pedagogy/NewEmployeeAttendanceModal';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';

const TABLEURL = Hoot() + "eduallgetallemployeesattendence/get/";


const StatusType = [
    <div className="ml-2"><Badge bg={'success'}><Check /> Presente</Badge></div>,
    <div className="ml-2"><Badge bg={'danger'}> <Close /> Ausente</Badge></div>,
    <div className="ml-2"><Badge bg={'warning'}><InfoOutlined /> Atrasado</Badge></div>
];

const columns = [
    {
        field: 'index',
        headerName: 'Nº',
        width: 90,
        resizable: true,
    },
    {
        field: 'name',
        headerName: 'Nome do funcionário',
        resizable: true,
        width: 300,
        cellRenderer: (props) => {
            return <div className='ed-flex'>
                <Avatar className='df' alt={props.data.name} src={props.data.picture !== "" ? Hoot() + props.data.picture : ""} />
                <span className='ml-2'>{props.data.name}</span>
            </div>
        }
    },
    {
        field: 'time',
        headerName: 'Horário',
        width: 190,
        resizable: true,
        editable: true,
    },
    {
        field: 'date',
        headerName: 'Data',
        width: 190,
        resizable: true,
        editable: true,
    },
    {
        field: 'status',
        width: 180,
        headerName: 'Status',
        resizable: true,
        cellRenderer: (props) => {
            return <div className='ed-flex'> {StatusType[props.data.status]} </div>
        }
    },
    {
        field: 'action',
        headerName: 'Ação',
        resizable: true,
        cellRenderer: (props) => {
            return <div className="ed-flex">
                <NewEmployeeAttendanceModal title='Atualizar ' update='true' get={Hoot() + `eduallgetsingleemployeeattendence/get/${props.data.id}`}
                    url={Hoot() + `eduallemployeeattendenceupdate/update/${props.data.id}`}
                    toggle_btn={
                        <button subject-code={props.data.id} className="btn-circle bg-success text-light">
                            <Edit />
                        </button>
                    } />
                <DeleteModal title='esta informação' url={Hoot() + `eduallemployeeattendencedelete/delete/${props.data.id}`}
                    message='Marcação de presença deletada com sucesso' toggle_btn={
                        <button className="btn-circle btn-delete-timing bg-danger ml-2 text-light">
                            <Delete />
                        </button>
                    } />
            </div>;
        }

    },
];


function EmployeeAttandanceTable() {
    const [data, setData] = useState([]);
    const [load, setLoaded] = useState(false);
    const [LoadStatus, setLoadStatus] = useState(null);

    async function loadData() {
        try {
            setLoaded(false);
            setLoadStatus(0);
            const response = await axios.get(TABLEURL);
            const rows = [];
            response.data.map((item, index) => {
                rows.push({
                    index: index + 1,
                    id: item.ed_employee_attd_id,
                    timing: item.ed_employee_attd_timing,
                    date: moment(item.ed_employee_attd_date).format("YYYY-MM-DD"),
                    status: item.ed_employee_attd_status,
                    name: item.ed_employee_name,
                    picture: item.ed_employee_picture,
                    time: item.ed_timing_hour_start + ":" + item.ed_timing_minute_start + "-" + item.ed_timing_hour_end + ":" + item.ed_timing_minute_end
                });
            });
            setData(rows);
            setTimeout(() => {
                setLoaded(true);
            }, 200);
            setLoadStatus(2);
        } catch (error) {
            setLoadStatus(1);
        }
    }

    useEffect(() => {
        loadData();
    }, []);

    if (load) {
        return (
            <div id="ed-custom-table-data">
                <TableGrid
                    TableHead={columns}
                    TableBody={data}
                    TableTitle='Controle de presenças dos funcionários'
                    TableBtn={
                        <div className='ed-flex' > 
                            <button id='ed-custom-table-data-btn'
                                onClick={() =>
                                    ExportDataToTablesToPdf({
                                        fileName: "Controle de presenças dos funcionários",
                                        headerId: null,
                                        contentId: "ed-custom-table-data",
                                        footerId: null,
                                        rotation: "portrait",
                                        buttonId: "ed-custom-table-data-btn",
                                        customHeader: "Controle de presenças dos funcionários",
                                        excludedColumns: ["Ação"]
                                    })
                                }
                                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
                            </button>
                            <button className='btn-icon btn btn-export-data ml-2'
                                onClick={() => ExportDataForTablesExcel("Controle de presenças dos funcionários ", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
                            </button>
                            <RefreshButton action={loadData} status={LoadStatus} />
                        </div>}
                />
            </div>
        )
    } else {
        return (
            <div>
                <div className="d-none">*</div>
                <TableGrid
                    TableHead={columns}
                    TableBody={data}
                    TableTitle='Controle de presenças dos funcionários'
                    TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
                />
            </div>
        )
    }
}

export default EmployeeAttandanceTable;