import React, { useEffect, useState } from 'react'
import styled from 'styled-components'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button, Badge } from 'react-bootstrap'
import { InfoOutlined, Save } from '@mui/icons-material';
import DraggableModal from '../../../../General/components/DraggableModal';
import axios from 'axios';
import Hoot from '../../../../General/components/Hoot';
import ClearInputs from '../../../../General/components/ClearInputs';
import CRValue from '../../../../General/components/CRValue';
import { toast } from 'react-hot-toast';
import { Update } from '@material-ui/icons';
import { SubjectDataOptions, StudentsArrayByClass, ClassDataOptions, GetClasstitle_byclass, GetSubject, getStudentData } from '../../../../General/components/InstituteData';
import SelectSearch from 'react-select-search';
import StudentDetailsMenu from '../../elements/StudentDetailsMenu';
import ReduceTextLength from '../../../../General/components/ReduceTextLength';
import FloorNumber from '../../../../General/components/FloorNumber';
import RefreshList from '../../../../General/components/RefreshList';
import SmallLoader from '../../../../General/components/SmallLoader';
import Loader from '../../../../General/components/Loader';
import UserOptionDropDown from '../../elements/UserOptionDropDown';
import SaveButton from '../../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../../General/components/ModalAnimations';
import ReplaceWord from '../../../../General/components/ReplaceWord';
import CalculateNote from '../../../../General/components/CalculateNote';
import MessageTypeSelectorSend from '../../../../General/components/MessageTypeSelectorSend';

const DATA_URL = [
  Hoot() + 'eduallsingleclassapi/get/',
  Hoot() + 'eduallsingleacademiclevelsapi/get/',
];


function QuarterlyNotesModal(props) {
  const [show, setShow] = useState(false);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});
  const [studentCode, setStudentCode] = useState(null);
  const [CurrentClass, SetCurrentClass] = useState(null);
  const [CurrentSubject, SetCurrentSubject] = useState(null);
  const [CurrentQuarter, SetCurrentQuarter] = useState(null);
  const [Total, SetTotal] = useState(0);
  const [StudentsData, setStudentsData] = useState([]);
  const [MaxValue, setMaxValue] = useState(0);
  const [data, setData] = useState([]);
  const [Founded, setFounded] = useState(false);
  const [LoadingStudents, setLoadingStudents] = useState(false);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [EnableExamInput, setEnableExamInput] = useState(false);
  const [EnableSpecialExamInput, setEnableSpecialExamInput] = useState(false);
  const [InstituteData, SetInstituteData] = useState({});
  const [SendMessage, setSendMessage] = useState({ send: false, message: null, title: "" });

  useEffect(() => {
    const fetchInstitute = async () => {
      try {
        if (props.Institute?.ed_institute_name) {
          SetInstituteData(props.Institute);
          return;
        }
        const response = await axios.get(Hoot() + "eduallgetcurentuserinstitute/get/");
        if (response.data.length > 0) {
          SetInstituteData(response.data[0]);
        } else {
          toast.error("Instituição não encontrada !");
        }
      } catch (error) {
        console.error("Erro ao carregar dados da instituição:", error); 
      }
    };

    fetchInstitute();
  }, []);


  const [showBox, SetshowBox] = useState(false);
  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200);
  }

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };



  const INPUTS = {
    quarterly_note_subject: props.update ? CurrentSubject : (CRValue("#quarterly_note_class").split("|").length >= 2 ? CRValue("#quarterly_note_class").split("|")[1] : CRValue("#quarterly_note_subject")),
    quarterly_note_class: props.update ? CurrentClass : (CRValue("#quarterly_note_class").split("|").length >= 2 ? CRValue("#quarterly_note_class").split("|")[0] : CRValue("#quarterly_note_class")),
    quarterly_note_student_code: studentCode,
    quarterly_note_mac: CRValue("#quarterly_note_mac") * 1,
    quarterly_note_npp: CRValue("#quarterly_note_npp") * 1,
    quarterly_note_npt: CRValue("#quarterly_note_npt") * 1,
    quarterly_note_quarter: props.update ? CurrentQuarter : (CRValue("#quarterly_note_quarter1") * 1),

    quarterly_note_exam: CRValue("#quarterly_note_exam"),
    quarterly_note_p2: CRValue("#quarterly_note_p2"),
    quarterly_note_p1: CRValue("#quarterly_note_p1"),
    quarterly_note_semester: CRValue("#quarterly_note_semester") * 1,
    quarterly_note_special_test: CRValue("#quarterly_note_special_test"),
  };


  const url1 = InstituteData.ed_institute_type * 1 === 1 ? Hoot() + "eduallregistersemesternotes/post" : Hoot() + "eduallquarterlynotesregister/post";

  const FORMURL = [
    url1,
    Hoot() + "eduallsinglequarterlynotebyqrtsubstdqrttypeclass/get/",
    props.get ? props.get : '',
    props.url ? props.url : '',
    Hoot() + "eduallgetstudentsbyclass/",
    Hoot() + "eduallsinglesemesternotebysmtsubstdqrttypeclass/get/"
  ];


  const GetColor = (e, max) => {
    return (e < (max / 2)) ?
      <span className='text-danger'>{e}</span>
      : <span className='text-success'>{e}</span>
  }


  const GET_DATA = async () => {
    if (props.update) {
      try {

        setFounded(true);
        const response = await axios.get(FORMURL[2]);
        setMaxValue(props.maxvalue);
        if (response.data.length >= 1) {

          if (InstituteData.ed_institute_type * 1 === 0) {

            SetCurrentClass(response.data[0].ed_quarter_note_class);
            INPUTS.quarterly_note_class = response.data[0].ed_quarter_note_class
            setField("quarterly_note_class", response.data[0].ed_quarter_note_class);

            setStudentCode(response.data[0].ed_quarter_note_studentcode);

            setField("quarterly_note_subject", response.data[0].ed_quarter_note_subject);
            INPUTS.quarterly_note_subject = response.data[0].ed_quarter_note_subject;
            SetCurrentSubject(response.data[0].ed_quarter_note_subject);

            setField("quarterly_note_quarter", response.data[0].ed_quarter_note_quarter);
            INPUTS.quarterly_note_quarter = response.data[0].ed_quarter_note_quarter;
            SetCurrentQuarter(response.data[0].ed_quarter_note_quarter);

            setField("quarterly_note_mac", response.data[0].ed_quarter_note_mac);
            INPUTS.quarterly_note_mac = response.data[0].ed_quarter_note_mac;

            setField("quarterly_note_npp", response.data[0].ed_quarter_note_npp);
            INPUTS.quarterly_note_npp = response.data[0].ed_quarter_note_npp;

            setField("quarterly_note_npt", response.data[0].ed_quarter_note_npt);
            INPUTS.quarterly_note_npt = response.data[0].ed_quarter_note_npt;


            document.querySelector("#quarterly_note_mac").value = response.data[0].ed_quarter_note_mac;
            document.querySelector("#quarterly_note_npp").value = response.data[0].ed_quarter_note_npp;
            document.querySelector("#quarterly_note_npt").value = response.data[0].ed_quarter_note_npt;

 
            setForm({ 
              ...form, 
              quarterly_note_npp: response.data[0].ed_quarter_note_npp,
              quarterly_note_class: response.data[0].quarterly_note_class,
              quarterly_note_subject: response.data[0].ed_quarter_note_subject,
              quarterly_note_quarter: response.data[0].ed_quarter_note_quarter,
              quarterly_note_mac:  response.data[0].ed_quarter_note_mac,
              quarterly_note_npt: response.data[0].ed_quarter_note_npt, 
              quarterly_note_student_code:response.data[0].ed_quarter_note_studentcode,
            })

            SetTotal(FloorNumber(((
              response.data[0].ed_quarter_note_mac * 1 +
              response.data[0].ed_quarter_note_npp * 1 +
              response.data[0].ed_quarter_note_npt * 1) / 3))
            );
          } else {
            SetCurrentClass(response.data[0].ed_semester_note_class);
            INPUTS.quarterly_note_class = response.data[0].ed_semester_note_class
            setField("quarterly_note_class", response.data[0].ed_semester_note_class);

            setStudentCode(response.data[0].ed_semester_note_studentcode);

            setField("quarterly_note_subject", response.data[0].ed_semester_note_subject);
            INPUTS.quarterly_note_subject = response.data[0].ed_semester_note_subject;
            SetCurrentSubject(response.data[0].ed_semester_note_subject);

            setField("quarterly_note_semester", response.data[0].ed_semester_note_semester);
            INPUTS.quarterly_note_semester = response.data[0].ed_semester_note_semester;

            setField("quarterly_note_exam", response.data[0].ed_semester_note_exam);
            INPUTS.quarterly_note_exam = response.data[0].ed_semester_note_exam;

            setField("quarterly_note_special_test", response.data[0].ed_semester_note_specialexam);
            INPUTS.quarterly_note_special_test = response.data[0].ed_semester_note_specialexam;

            setField("quarterly_note_p1", response.data[0].ed_semester_note_p1);
            INPUTS.quarterly_note_p1 = response.data[0].ed_semester_note_p1;

            setField("quarterly_note_p2", response.data[0].ed_semester_note_p2);
            INPUTS.quarterly_note_p2 = response.data[0].ed_semester_note_p2;

            SetTotal(((INPUTS.quarterly_note_p1 * 1) + (INPUTS.quarterly_note_p2 * 1)) / 2);
          }
        }
      } catch (error) {

      }
    }
  }


  useEffect(() => {
    setTimeout(() => {
      let vl = CRValue("#quarterly_note_class").split("|").length >= 2 ? CRValue("#quarterly_note_class").split("|")[0] : CRValue("#quarterly_note_class");
      if (vl * 1 > 0) {
        GetStudentsByClass(vl);
      }
    }, 500);
  }, []);


  const setField = (field, value) => {
    setForm({
      ...form,
      [field]: value
    })

    if (!!errors[field]) {
      setErrors({
        ...errors,
        [field]: null
      });
    }
  }


  function getData() {
    console.clear();
    console.log("dados do form -----------");
    console.log(form);
    console.log("dado dos inputs ---------");
    console.log(INPUTS);
    console.log("dado do url = ", FORMURL[2])
  }




  let FormValidateErrors = [];
  const validateForm = async () => {
    let NewErrors = {};
    setRegisterStatus(0);

    try {
      const {
        quarterly_note_class, quarterly_note_student_code, quarterly_note_subject,
        quarterly_note_semester, quarterly_note_p1, quarterly_note_quarter, quarterly_note_mac, quarterly_note_npp
      } = form;

      // --- validações básicas ---
      if (!CurrentClass || CurrentClass === '') {
        NewErrors.quarterly_note_class = ReplaceWord("Classe") + ' inválida';
      }

      if (!quarterly_note_student_code || quarterly_note_student_code === '' || quarterly_note_student_code * 1 <= 0) {
        NewErrors.quarterly_note_student_code = 'Estudante inválido';
      }

      if (!quarterly_note_subject || quarterly_note_subject === '') {
        NewErrors.quarterly_note_subject = ReplaceWord("Disciplina") + ' inválida';
      }

      // --- validações avançadas ---
      if (props.data) {
        if ((InstituteData.ed_institute_type * 1) === 0) {
          if (!quarterly_note_quarter || quarterly_note_quarter === '') {
            NewErrors.quarterly_note_quarter = 'Trimestre inválido';
          }
          if (!quarterly_note_mac || quarterly_note_mac === '') {
            NewErrors.quarterly_note_mac = 'MAC inválido';
          }
          if (!quarterly_note_npp || quarterly_note_npp === '') {
            NewErrors.quarterly_note_npp = 'NPP inválido';
          }

          if (!props.update) {
            const response = await axios.get(
              FORMURL[1] +
              `${INPUTS.quarterly_note_subject},${INPUTS.quarterly_note_student_code},${INPUTS.quarterly_note_quarter},${INPUTS.quarterly_note_class}`
            );
            if (response.data.length >= 1) {
              NewErrors.quarterly_note_student_code = 'A nota deste estudante já foi lançada';
            }
          }
        } else {
          if (!quarterly_note_semester || quarterly_note_semester === '') {
            NewErrors.quarterly_note_semester = 'Semestre inválido';
          }
          if (!quarterly_note_p1 || quarterly_note_p1 === '') {
            NewErrors.quarterly_note_p1 = 'P1 inválida';
          }

          if (!props.update) {
            const response = await axios.get(
              FORMURL[5] +
              `${INPUTS.quarterly_note_subject},${INPUTS.quarterly_note_student_code},${INPUTS.quarterly_note_semester},${INPUTS.quarterly_note_class}`
            );
            if (response.data.length >= 1) {
              NewErrors.quarterly_note_student_code = 'A nota deste estudante já foi lançada';
            }
          }
        }
      }
    } catch (error) {
      console.log(error);
      NewErrors.quarterly_note_student_code = 'Lamentamos, algo não deu certo';
    }

    return NewErrors;
  };





  const FormSubmit = async (e) => {
    e.preventDefault();
    console.log(INPUTS);
    validateForm();
    const formErrors = await validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os campos");
      console.log(formErrors);
      setRegisterStatus(1);
    } else {
      let SUBMIT_INPUTS = {};

      if ((InstituteData.ed_institute_type * 1) === 0) {
        SUBMIT_INPUTS = {
          quarterly_note_subject: INPUTS.quarterly_note_subject,
          quarterly_note_class: CurrentClass,
          quarterly_note_student_code: INPUTS.quarterly_note_student_code,
          quarterly_note_mac: INPUTS.quarterly_note_mac,
          quarterly_note_npp: INPUTS.quarterly_note_npp,
          quarterly_note_npt: INPUTS.quarterly_note_npt,
          quarterly_note_quarter: INPUTS.quarterly_note_quarter,
        };
      } else {
        SUBMIT_INPUTS = {
          semester_note_subject: INPUTS.quarterly_note_subject,
          semester_note_class: CurrentClass,
          semester_note_student_code: INPUTS.quarterly_note_student_code,
          semester_note_exam: INPUTS.quarterly_note_exam,
          semester_note_p2: INPUTS.quarterly_note_p2,
          semester_note_p1: INPUTS.quarterly_note_p1,
          semester_note_semester: INPUTS.quarterly_note_semester,
          semester_note_special_test: (FloorNumber((FloorNumber(Total * 1) + (form.quarterly_note_exam * 1)) / 2) < 10 && Total * 1 <= 13) ? INPUTS.quarterly_note_special_test : 0,
        };
      }



      if (!props.update) {
        try {
          setSendMessage({ send: false, message: null, title: "" });
          axios.post(FORMURL[0], SUBMIT_INPUTS).then(() => {
            async function load() {
              const { name, scholl, mac, npp, npt, mt, exame, recurso } = await getStudentData(
                studentCode,
                INPUTS.quarterly_note_subject,
                CurrentClass,
                INPUTS.quarterly_note_quarter
              );

              const msg = `${scholl}\nAssunto: Notas do(a) aluno(a): ${name}\nInformamos que as últimas notas do ${INPUTS.quarterly_note_quarter}º trimestre são as seguintes:\n\n- MAC: ${mac}\n- NPP: ${npp}\n- NPT: ${npt}\n- MT (Média Total): ${mt}\n- Exame: ${exame}\n- Recurso: ${recurso}\nCaso necessite de mais informações, por favor contacte a instituição.\n\nObrigado pela atenção.`;

              setSendMessage({
                send: true,
                title: `Notas do(a) aluno(a): ${name}`,
                message: msg
              });

              toast.success("Nota adicionada com sucesso !");
              setForm({});
              setErrors({})
              RefreshList(`.el-refresh-list`);
              SetTotal(0);
              setRegisterStatus(2);
              setTimeout(() => {
                setSendMessage({ send: false, title: null, message: null });
              }, 2000);
            }
            load();

          }).catch((error) => {
            console.clear();
            console.log(error);
            console.log(SUBMIT_INPUTS);

            if (error.response) {
              const { data } = error.response;
              const message = data?.msg || "Lamentamos mas não foi possivel executar esta ação !";
              toast.error(message);
            } else if (error.request) {
              toast.error("Sem resposta do servidor. Verifique sua conexão.");
            } else {
              toast.error("Erro ao processar a requisição.");
            }
            setRegisterStatus(1);
          });
        } catch (error) {
          console.clear();
          console.log(error);
          console.log(SUBMIT_INPUTS);

          if (error.response) {
            const { data } = error.response;
            const message = data?.msg || "Lamentamos mas não foi possivel executar esta ação !";
            toast.error(message);
          } else if (error.request) {
            toast.error("Sem resposta do servidor. Verifique sua conexão.");
          } else {
            toast.error("Erro ao processar a requisição.");
          }
          setRegisterStatus(1);
        }
      } else {
        try {

          console.clear();
          console.log(SUBMIT_INPUTS);

          axios.put(FORMURL[3], SUBMIT_INPUTS).then((dt) => {
            toast.success("Nota atualizada com sucesso !");
            setForm({});
            setErrors({})
            RefreshList(`.el-refresh-list`);
            setRegisterStatus(2);
            setTimeout(() => {
              handleClose();
            }, 1000);
          }).catch((error) => {
            console.clear()
            console.log(error);
            if (error.response) {
              const { data } = error.response;
              const message = data?.msg || "Lamentamos mas não foi possivel executar esta ação !";
              toast.error(message);
            } else if (error.request) {
              toast.error("Sem resposta do servidor. Verifique sua conexão.");
            } else {
              toast.error("Erro ao processar a requisição.");
            }
            setRegisterStatus(1);
          });

        } catch (error) {
          console.clear()
          console.log(error);
          if (error.response) {
            const { data } = error.response;
            const message = data?.msg || "Lamentamos mas não foi possivel executar esta ação !";
            toast.error(message);
          } else if (error.request) {
            toast.error("Sem resposta do servidor. Verifique sua conexão.");
          } else {
            toast.error("Erro ao processar a requisição.");
          }
          setRegisterStatus(1);
        }
      }
    }

  };




  const GetStudentCode = (e) => {
    setStudentCode(e);
    setField("quarterly_note_student_code", e);
  }


  const GetStudentsByClass = async (e) => {
    setStudentsData([]);
    setMaxValue(0);
    setLoadingStudents(true);
    try {
      const [response, response1] = await Promise.all([
        axios.get(FORMURL[4] + e),
        axios.get(DATA_URL[0] + `${e}`),
      ]);


      const info = await axios.get(DATA_URL[1] + `${response1.data[0].ed_class_academic_level}`);

      const students = [];
      if (response.data !== null) {
        if (info.data.length >= 1) {
          setMaxValue(info.data[0].ed_academic_level_avaliationtype_endat * 1);
        } else {
          setMaxValue(0);
        }
        response.data.map((item, index) => {
          students.push({ name: item.ed_student_name, value: item.ed_student_id });
        })
      }
      setTimeout(() => {
        setStudentsData(students);
        setLoadingStudents(false);
      }, 100);
    } catch (error) {

    }
  }




  const handleInput = (e) => {



    switch (e.target.id) {
      case "quarterly_note_class":
        if (e.target.value.split("|").length >= 2) {
          const value = e.target.value || "";
          const parts = value.split("|");

          const classValue = parts[0] ? parts[0].trim() : "";
          const subjectValue = parts[1] ? parts[1].trim() : "";

          SetCurrentClass(classValue);
          GetStudentsByClass(classValue);

          INPUTS.quarterly_note_class = classValue;
          setField("quarterly_note_class", classValue);

          INPUTS.quarterly_note_subject = subjectValue;
          setField("quarterly_note_subject", subjectValue);
        } else {
          SetCurrentClass(e.target.value);
          GetStudentsByClass(e.target.value);
          INPUTS.quarterly_note_class = e.target.value
          setField("quarterly_note_class", e.target.value);
        }
        break;
      case "quarterly_note_subject":
        setField("quarterly_note_subject", e.target.value);
        INPUTS.quarterly_note_subject = e.target.value
        break;
      case "quarterly_note_quarter1":
        setField("quarterly_note_quarter", e.target.value);
        INPUTS.quarterly_note_quarter = e.target.value
        break;
      case "quarterly_note_mac":
        setField("quarterly_note_mac", e.target.value);
        INPUTS.quarterly_note_mac = e.target.value
        break;
      case "quarterly_note_npp":
        setField("quarterly_note_npp", e.target.value);
        INPUTS.quarterly_note_npp = e.target.value
        break;
      case "quarterly_note_npt":
        setField("quarterly_note_npt", e.target.value);
        INPUTS.quarterly_note_npt = e.target.value;
        break;


      case "quarterly_note_semester":
        setField("quarterly_note_semester", e.target.value);
        INPUTS.quarterly_note_semester = e.target.value;
        break;
      case "quarterly_note_p1":
        setField("quarterly_note_p1", e.target.value);
        INPUTS.quarterly_note_p1 = e.target.value;
        break;
      case "quarterly_note_p2":
        setField("quarterly_note_p2", e.target.value);
        INPUTS.quarterly_note_p2 = e.target.value;
        break;
      case "quarterly_note_exam":
        setField("quarterly_note_exam", e.target.value);
        INPUTS.quarterly_note_exam = e.target.value;
        break;
      case "quarterly_note_special_test":
        setField("quarterly_note_special_test", e.target.value);
        INPUTS.quarterly_note_special_test = e.target.value;
        break;
      default:
        console.log("none of them");
    }

    if ((InstituteData.ed_institute_type * 1) === 0) {
      SetTotal(((INPUTS.quarterly_note_npp * 1) + (INPUTS.quarterly_note_mac * 1) + (INPUTS.quarterly_note_npt * 1)) / 3);
    } else {
      //CalculateNote
      SetTotal(((INPUTS.quarterly_note_p1 * 1) + (INPUTS.quarterly_note_p2 * 1)) / 2);

      if (CalculateNote(0, 0, 0, 0, 0)) {
        setEnableSpecialExamInput(true);
      } else {
        setEnableSpecialExamInput(false);
      };
      if (CalculateNote(0, 0, 0, 0, 0)) {
        setEnableExamInput(true);
      } else {
        setEnableExamInput(false);
      };
    }
  }


  const run = () => {
    console.clear();
    console.log(props.data)
  }



  return (

    <div>
      <div onClick={handleShow}>
        {props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon />Lançar nota</button>}
      </div>
      <Modal size='lg' className={showBox ? ModalAnimationShow() : ModalAnimationClose()} centered dialogAs={DraggableModal} show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>{props.title ? props.title : 'Efetuar '} Lançamento de notas</h5>
            </div>
            <button onClick={() => getData()} >pegar dados</button>
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={FormSubmit}>
          <Modal.Body className='scrollLimit'>

            {(InstituteData.ed_institute_type * 1) === 1 ?
              <>
                {!props.update ?
                  <>
                    {props.data ?
                      <>
                        <Form.Group className="mb-3"  >
                          <Form.Label>Turma - {ReplaceWord("Disciplina", true)}<span className="text-danger ml-2">*</span></Form.Label>
                          <div className="ed-flex">
                            <Form.Select
                              onChange={handleInput}
                              className={!!errors.quarterly_note_class ? 'is-invalid' : ''}
                              value={form.quarterly_note_class}
                              isInvalid={!!errors.quarterly_note_class}
                              id="quarterly_note_class"
                            >
                              <option value="" disabled selected>
                                selecionar...
                              </option>
                              {props.data.map((item, index) => (
                                <option
                                  key={index}
                                  value={`${item.ed_tch_subject_class}|${item.ed_tch_subject_code}`}
                                >
                                  Turma - <GetClasstitle_byclass ID={item.ed_tch_subject_class} /> ( <GetSubject ID={item.ed_tch_subject_code} /> )
                                </option>
                              ))}
                            </Form.Select>

                            {LoadingStudents ? <div className='ed-flex'><div className="pd-2"></div>
                              <SmallLoader />
                            </div> : <></>}
                          </div>
                          <Form.Control.Feedback type='invalid'>{errors.quarterly_note_class}</Form.Control.Feedback>
                        </Form.Group>
                      </> :
                      <>
                      </>
                    }
                    {props.update ? <></> :
                      <>

                        {StudentsData.length >= 0 ?
                          <>
                            <Form.Group className="mb-3">
                              <div className='ed-space'>
                                <div><Form.Label>Nome do estudante<span className='text-danger ml-2'>*</span></Form.Label></div>
                                {studentCode !== null ? <StudentDetailsMenu nopayment student_id={studentCode} toggle_btn={<div className='btn-pm-info'><InfoOutlined /></div>} /> : <></>}
                              </div>
                              <div className={`select-search-item  ${errors.quarterly_note_student_code ? 'error' : ''}`}>
                                <SelectSearch onChange={(e) => GetStudentCode(e)} value={studentCode} options={StudentsData} search={true}
                                  placeholder="Selecione um aluno" />
                              </div>
                              <small className="text-danger">{errors.quarterly_note_student_code}</small>
                            </Form.Group>
                          </> :
                          <>

                          </>
                        }
                      </>
                    }
                    <Form.Group className="mb-3"  >
                      <Form.Label>Semestre<span className="text-danger ml-2">*</span></Form.Label>
                      <Form.Select onChange={handleInput} className={!!errors.quarterly_note_semester && 'is-invalid'} value={form.quarterly_note_semester}
                        isInvalid={!!errors.quarterly_note_semester} id="quarterly_note_semester">
                        <option value="1" selected>Iº Semestre</option>
                        <option value="2">IIº Semestre</option>
                      </Form.Select>
                      <Form.Control.Feedback type='invalid'>{errors.quarterly_note_semester}</Form.Control.Feedback>
                    </Form.Group>

                    {MaxValue !== 0 && !LoadingStudents ?
                      <div>
                        <div className="ed-flex">
                          <div className='col'>
                            <Form.Group className="mb-3">
                              <Form.Label>P1</Form.Label>
                              <Form.Control type="number" min="0" max={MaxValue} onChange={handleInput} className={!!errors.quarterly_note_p1 && 'is-invalid'} value={form.quarterly_note_p1}
                                placeholder={`Nota de 0 - ${MaxValue}`} isInvalid={!!errors.quarterly_note_p1} id="quarterly_note_p1" />
                              <Form.Control.Feedback type='invalid'>{errors.quarterly_note_p1}</Form.Control.Feedback>
                            </Form.Group>
                          </div>
                          <div className='col ml-2'>
                            <Form.Group className="mb-3"  >
                              <Form.Label>P2</Form.Label>
                              <Form.Control type="number" min="0" max={MaxValue} onChange={handleInput} className={!!errors.quarterly_note_p2 && 'is-invalid'} value={form.quarterly_note_p2}
                                placeholder={`Nota de 0 - ${MaxValue}`} isInvalid={!!errors.quarterly_note_p2} id="quarterly_note_p2" />
                              <Form.Control.Feedback type='invalid'>{errors.quarterly_note_p2}</Form.Control.Feedback>
                            </Form.Group>
                          </div>
                        </div>
                        <div>
                          <div className="d-flex">
                            {FloorNumber(Total) <= 13 ?
                              <div className='col'>
                                <Form.Group className="mb-3"  >
                                  <Form.Label>Exame</Form.Label>
                                  <Form.Control type="number" min="0" max={MaxValue} onChange={handleInput} className={!!errors.quarterly_note_exam && 'is-invalid'} value={form.quarterly_note_exam}
                                    placeholder={`Nota de 0 - ${MaxValue}`} isInvalid={!!errors.quarterly_note_exam} id="quarterly_note_exam" />
                                  <Form.Control.Feedback type='invalid'>{errors.quarterly_note_exam}</Form.Control.Feedback>
                                </Form.Group>
                              </div>
                              : <></>}
                            {FloorNumber(Total) <= 13 ?
                              <>
                                {(FloorNumber((FloorNumber(Total) + (form.quarterly_note_exam)) / 2) < 10) ?
                                  <div className='col ml-2'>
                                    <Form.Group className="mb-3">
                                      <Form.Label>Recurso</Form.Label>
                                      <Form.Control type="number" min="0" max={MaxValue} onChange={handleInput} className={!!errors.quarterly_note_special_test && 'is-invalid'} value={form.quarterly_note_special_test}
                                        placeholder={`Nota de 0 - ${MaxValue}`} isInvalid={!!errors.quarterly_note_special_test} id="quarterly_note_special_test" />
                                      <Form.Control.Feedback type='invalid'>{errors.quarterly_note_special_test}</Form.Control.Feedback>
                                    </Form.Group>
                                  </div>
                                  : <></>}  </>
                              : <></>}
                          </div>
                        </div>
                      </div>
                      : <></>}
                  </> :
                  <>
                    {Founded === true ?
                      <>
                        <div>
                          <div className="ed-flex">
                            <div className='col'>
                              <Form.Group className="mb-3">
                                <Form.Label>P1</Form.Label>
                                <Form.Control type="number" min="0" max={MaxValue} onChange={handleInput} className={!!errors.quarterly_note_p1 && 'is-invalid'} value={form.quarterly_note_p1}
                                  placeholder={`Nota de 0 - ${MaxValue}`} isInvalid={!!errors.quarterly_note_p1} id="quarterly_note_p1" />
                                <Form.Control.Feedback type='invalid'>{errors.quarterly_note_p1}</Form.Control.Feedback>
                              </Form.Group>
                            </div>
                            <div className='col ml-2'>
                              <Form.Group className="mb-3"  >
                                <Form.Label>P2</Form.Label>
                                <Form.Control type="number" min="0" max={MaxValue} onChange={handleInput} className={!!errors.quarterly_note_p2 && 'is-invalid'} value={form.quarterly_note_p2}
                                  placeholder={`Nota de 0 - ${MaxValue}`} isInvalid={!!errors.quarterly_note_p2} id="quarterly_note_p2" />
                                <Form.Control.Feedback type='invalid'>{errors.quarterly_note_p2}</Form.Control.Feedback>
                              </Form.Group>
                            </div>
                          </div>
                          <div>
                            <div className="d-flex">
                              {FloorNumber(Total) <= 13 ?
                                <div className='col'>
                                  <Form.Group className="mb-3"  >
                                    <Form.Label>Exame</Form.Label>
                                    <Form.Control type="number" min="0" max={MaxValue} onChange={handleInput} className={!!errors.quarterly_note_exam && 'is-invalid'} value={form.quarterly_note_exam}
                                      placeholder={`Nota de 0 - ${MaxValue}`} isInvalid={!!errors.quarterly_note_exam} id="quarterly_note_exam" />
                                    <Form.Control.Feedback type='invalid'>{errors.quarterly_note_exam}</Form.Control.Feedback>
                                  </Form.Group>
                                </div>
                                : <></>}
                              {FloorNumber(Total) <= 13 ?
                                <>
                                  {(FloorNumber((FloorNumber(Total) + (form.quarterly_note_exam)) / 2) < 10) ?
                                    <div className='col ml-2'>
                                      <Form.Group className="mb-3">
                                        <Form.Label>Recurso</Form.Label>
                                        <Form.Control type="number" min="0" max={MaxValue} onChange={handleInput} className={!!errors.quarterly_note_special_test && 'is-invalid'} value={form.quarterly_note_special_test}
                                          placeholder={`Nota de 0 - ${MaxValue}`} isInvalid={!!errors.quarterly_note_special_test} id="quarterly_note_special_test" />
                                        <Form.Control.Feedback type='invalid'>{errors.quarterly_note_special_test}</Form.Control.Feedback>
                                      </Form.Group>
                                    </div>
                                    : <></>}  </>
                                : <></>}
                            </div>
                          </div>
                        </div>
                      </>
                      : <>
                        <LoaderContainer>
                          <Loader absolute small />
                        </LoaderContainer>
                      </>
                    }
                  </>
                }
              </>
              :
              <>
                {!props.update ?
                  <>
                    {props.data ?
                      <>
                        <Form.Group className="mb-3"  >
                          <Form.Label>Turma - {ReplaceWord("Disciplina", true)}<span className="text-danger ml-2">*</span></Form.Label>
                          <div className="ed-flex">
                            <Form.Select
                              onChange={handleInput}
                              className={!!errors.quarterly_note_class ? 'is-invalid' : ''}
                              value={form.quarterly_note_class}
                              isInvalid={!!errors.quarterly_note_class}
                              id="quarterly_note_class"
                            >
                              <option value="" disabled selected>
                                selecionar...
                              </option>
                              {props.data.map((item, index) => (
                                <option
                                  key={index}
                                  value={`${item.ed_tch_subject_class}|${item.ed_tch_subject_code}`}
                                >
                                  Turma - <GetClasstitle_byclass ID={item.ed_tch_subject_class} /> ( <GetSubject ID={item.ed_tch_subject_code} /> )
                                </option>
                              ))}
                            </Form.Select>
                            {LoadingStudents ? <div className='ed-flex'><div className="pd-2"></div>
                              <SmallLoader />
                            </div> : <></>}
                          </div>
                          <Form.Control.Feedback type='invalid'>{errors.quarterly_note_class}</Form.Control.Feedback>
                        </Form.Group>
                      </> :
                      <>
                      </>
                    }

                    {props.update ? <></> :
                      <>
                        {props.data ?
                          <>
                            {StudentsData.length >= 1 ?
                              <>
                                <Form.Group className="mb-3">
                                  <div>
                                    <div className='ed-space'>
                                      <div><Form.Label>Nome do estudante<span className='text-danger ml-2'>*</span></Form.Label></div>
                                      {studentCode !== null ? <StudentDetailsMenu nopayment student_id={studentCode} toggle_btn={<div className='btn-pm-info'><InfoOutlined /></div>} /> : <></>}
                                    </div>
                                  </div>
                                  <div className={`select-search-item  ${errors.quarterly_note_student_code ? 'error' : ''}`}>
                                    <SelectSearch onChange={(e) => GetStudentCode(e)} value={studentCode} options={StudentsData} search={true}
                                      placeholder="Selecione um aluno" />
                                  </div>
                                  <small className="text-danger">{errors.quarterly_note_student_code}</small>
                                </Form.Group>
                              </> :
                              <>

                              </>
                            }
                          </>
                          :
                          <></>}
                      </>
                    }

                    <Form.Group className="mb-3"  >
                      <Form.Label>Trimestre<span className="text-danger ml-2">*</span></Form.Label>
                      <Form.Select onChange={handleInput} className={!!errors.quarterly_note_quarter && 'is-invalid'} value={form.quarterly_note_quarter}
                        isInvalid={!!errors.quarterly_note_quarter} id="quarterly_note_quarter1">
                        <option selected disabled>Selecionar trimestre ...</option>
                        <option value="1">Iº Trimestre</option>
                        <option value="2">IIº Trimestre</option>
                        <option value="3">IIIº Trimestre</option>
                      </Form.Select>
                      <Form.Control.Feedback type='invalid'>{errors.quarterly_note_quarter}</Form.Control.Feedback>
                    </Form.Group>

                    {MaxValue !== 0 && !LoadingStudents ?
                      <div className="ed-flex">
                        <div className='col-lg-3'>
                          <Form.Group className="mb-3">
                            <Form.Label>MAC</Form.Label>
                            <Form.Control type="number" min="0" max={MaxValue} onChange={handleInput} className={!!errors.quarterly_note_mac && 'is-invalid'} value={form.quarterly_note_mac}
                              placeholder={`Nota de 0 - ${MaxValue}`} isInvalid={!!errors.quarterly_note_mac} id="quarterly_note_mac" />
                            <Form.Control.Feedback type='invalid'>{errors.quarterly_note_mac}</Form.Control.Feedback>
                          </Form.Group>
                        </div>
                        <div className='col-lg-3 ml-2 mr-2'>
                          <Form.Group className="mb-3"  >
                            <Form.Label>NPP</Form.Label>
                            <Form.Control type="number" min="0" max={MaxValue} onChange={handleInput} className={!!errors.quarterly_note_npp && 'is-invalid'} value={form.quarterly_note_npp}
                              placeholder={`Nota de 0 - ${MaxValue}`} isInvalid={!!errors.quarterly_note_npp} id="quarterly_note_npp" />
                            <Form.Control.Feedback type='invalid'>{errors.quarterly_note_npp}</Form.Control.Feedback>
                          </Form.Group>
                        </div>
                        <div className='col-lg-3'>
                          <Form.Group className="mb-3"  >
                            <Form.Label>NPT</Form.Label>
                            <Form.Control type="number" min="0" max={MaxValue} onChange={handleInput} className={!!errors.quarterly_note_npt && 'is-invalid'} value={form.quarterly_note_npt}
                              placeholder={`Nota de 0 - ${MaxValue}`} isInvalid={!!errors.quarterly_note_npt} id="quarterly_note_npt" />
                            <Form.Control.Feedback type='invalid'>{errors.quarterly_note_npt}</Form.Control.Feedback>
                          </Form.Group>
                        </div>
                      </div>
                      : <></>}
                  </> :
                  <>
                    {Founded === true ?
                      <>
                        <div className="ed-flex">
                          <div className='col-lg-3'>
                            <Form.Group className="mb-3">
                              <Form.Label>MAC</Form.Label>
                              <Form.Control type="number" min="0" max={MaxValue} onChange={handleInput} className={!!errors.quarterly_note_mac && 'is-invalid'}
                                value={form.quarterly_note_mac}
                                placeholder={`Nota de 0 - ${MaxValue}`} isInvalid={!!errors.quarterly_note_mac} id="quarterly_note_mac" />
                              <Form.Control.Feedback type='invalid'>{errors.quarterly_note_mac}</Form.Control.Feedback>
                            </Form.Group>
                          </div>
                          <div className='col-lg-3 ml-2 mr-2'>
                            <Form.Group className="mb-3"  >
                              <Form.Label>NPP</Form.Label>
                              <Form.Control type="number" min="0" max={MaxValue} onChange={handleInput} className={!!errors.quarterly_note_npp && 'is-invalid'}
                                value={form.quarterly_note_npp}
                                placeholder={`Nota de 0 - ${MaxValue}`} isInvalid={!!errors.quarterly_note_npp} id="quarterly_note_npp" />
                              <Form.Control.Feedback type='invalid'>{errors.quarterly_note_npp}</Form.Control.Feedback>
                            </Form.Group>
                          </div>
                          <div className='col-lg-3'>
                            <Form.Group className="mb-3"  >
                              <Form.Label>NPT</Form.Label>
                              <Form.Control type="number" min="0" max={MaxValue} onChange={handleInput} className={!!errors.quarterly_note_npt && 'is-invalid'}
                                value={form.quarterly_note_npt}
                                placeholder={`Nota de 0 - ${MaxValue}`} isInvalid={!!errors.quarterly_note_npt} id="quarterly_note_npt" />
                              <Form.Control.Feedback type='invalid'>{errors.quarterly_note_npt}</Form.Control.Feedback>
                            </Form.Group>
                          </div>
                        </div>
                      </>
                      : <>
                        <LoaderContainer>
                          <Loader absolute small />
                        </LoaderContainer>
                      </>
                    }
                  </>

                }
              </>}
          </Modal.Body>
          <Modal.Footer>
            <div className="ed-space modal-footer-area">
              <div className="ed-block">
                <div className="ed-flex">
                  {(InstituteData.ed_institute_type * 1) === 0 ?
                    <h5 className='ed-flex'>Media final :
                      <span className='text-danger ml-2'>
                        <ReduceTextLength text={Total.toString() + ""} length={5} />
                      </span>
                      <div className="ml-2">~</div>
                      <span className="text-green ml-2">
                        {FloorNumber(Total)}
                      </span>
                    </h5> :
                    <div className="ed-block">
                      <div>
                        <h5 className='ed-flex'>Media final :
                          <span className='text-danger ml-2'>
                            <ReduceTextLength text={Total.toString() + ""} length={5} />
                          </span>
                          <div className="ml-2">~</div>
                          <span className="text-green ml-2">
                            {FloorNumber(Total)}
                          </span>
                        </h5>
                      </div>
                      <div className="ed-wrap">
                        {FloorNumber(Total * 1) <= 13 ?
                          <div className="mr-2 ed-flex mt-1"><small>Resultado do Exame : </small>
                            <small className="ml-2">{GetColor(FloorNumber((FloorNumber(Total * 1) + (form.quarterly_note_exam * 1)) / 2), 20)}</small>
                          </div>
                          : <small className="text-success mr-2 mt-1">Dispensado para o exame </small>}
                        {FloorNumber((FloorNumber(Total * 1) + (form.quarterly_note_exam * 1)) / 2) < 10 && Total * 1 <= 13 ?
                          <div className="mr-2 ed-flex mt-1"><small>Nota do recurso : </small><small>0</small></div>
                          : <small className="text-success mt-1">Dispensado para o recurso </small>}
                      </div>
                    </div>
                  }
                </div>
                <div className="ed-flex">
                  <MessageTypeSelectorSend
                    message={SendMessage.message}
                    student={studentCode}
                    title={SendMessage.title}
                    send={SendMessage.send} />
                </div>
              </div>
              <div className="ed-flex">
                <div className="ed-flex">
                  <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                  {props.update ? (Founded === false ? <div></div> :
                    <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
                    <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />}
                </div>
              </div>
            </div>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  )
}


const LoaderContainer = styled.div`
  width:100%;
  min-height:300px;
  padding:30px;
  display:flex;
  align-items:center;
  justify-content:center; 
`;



export default QuarterlyNotesModal