import React, { useEffect, useState } from 'react'
import TableGrid from '../../../General/components/TableGrid';
import axios from 'axios';
import { GetServiceTitle, GetserviceCoin } from '../../../General/components/InstituteData';
import { PreviewOutlined, PrintOutlined } from '@mui/icons-material';
import { Link } from 'react-router-dom';
import NumberToPrice from '../../../General/components/NumberToPrice';
import Hoot from '../../../General/components/Hoot';
import PP_feepaymentsstatus from './PP_feepaymentsstatus';
import TitleBlock from '../../Components/TitleBlock';
import styled from 'styled-components';
import moment from 'moment';


const Months = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho",
"Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];

 
 

const columns = [
  { field: 'index', headerName: 'N', width: 60 },
  { field: 'invoiceN', headerName: 'Nº da Fatura', width: 180 },
  { field: 'service', headerName: 'Título do serviço', width: 260 },
  {
    field: 'monthsLabel',
    headerName: 'Meses pagos',
    width: 220,
  },
  {
    field: 'price',
    headerName: 'Preçário',
    width: 140,
    cellRenderer: (props) => (
      <div className='ed-flex'>
        {NumberToPrice(props.data.price)} {props.data.coin}
      </div>
    ),
  },
  {
    field: 'total',
    headerName: 'Total',
    width: 160,
    cellRenderer: (props) => (
      <div className='ed-flex'>
        {NumberToPrice(props.data.balance)} {props.data.coin}
      </div>
    ),
  },
  {
    field: 'situation',
    headerName: 'Situação',
    width: 150,
    cellRenderer: (props) =>
      props.data.invoiceCount > 1 ? (
        <div className="badge col-lg-12 bg-warning">
          {props.data.invoiceCount} meses
        </div>
      ) : (
        <div className="badge col-lg-12 bg-success">PG. Simples</div>
      ),
  },
  {
    field: 'date',
    headerName: 'Data de pagamento',
    width: 240,
  },
];


function PP_payments(props) {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [InstituteData, setInstituteData] = useState([]);
  const [StudentAcademicYear, setStudentAcademicYear] = useState(null);
  const [CurrentStudent, setCurrentStudent] = useState({});
  const [studentTransportData, setStudentTransportData] = useState([]);

  
 let month = new Date().getMonth()
 let currentMonth = month+1 <= 12 ? month+1 : month;  
 let Months = [];
 const CY =  new Date().getFullYear(); 
 const MonthsList = ["Janeiro", "Fevereiro", "Março",
 "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro",
 "Outubro", "Novembro", "Dezembro"]  


 const FORMURL1 = [
  Hoot()+"eduallsinglestudenttransportpayment/get/",
  Hoot()+"edualltransportsinglepassengerget/get/",
  Hoot()+"eduallgetpassengerbystudentcode/",
  Hoot()+"eduallsingleacademicyearapi/get/", 
]; 

 
  // calcula total de cada item individual
  function computeTotal(item) {
    const price = item.ed_fee_payment_price * 1;
    const discount = item.ed_fee_payment_discount * 1 || 0;
    const iva = item.ed_fee_payment_iva * 1 || 0;
    const fineType = item.ed_fee_payment_fineType * 1 || 0;
    const fineValue = item.ed_fee_payment_fineValue * 1 || 0;

    const afterDiscount = price - (price * discount) / 100;
    const base = iva > 0 ? afterDiscount / (1 + iva / 100) : afterDiscount;
    const fineAmount = fineType === 1 ? fineValue : (base * fineValue) / 100;
    return afterDiscount + fineAmount;
  }


  async function loadData() {
    setCurrentStudent(props.datacode.student);
    setStudentAcademicYear(props.datacode.academicyear);
    setLoaded(false);

    const grouped = {};

    props.data.Data.forEach((item) => {
      const total = computeTotal(item);
      const key = item.ed_fee_payment_invoiceCode;

      if (!grouped[key]) {
        grouped[key] = {
          id: item.ed_fee_payment_id,
          invoiceN: item.ed_fee_payment_invoiceCode,
          service: item.ed_service_title,
          coin: item.ed_coin_code,
          code: item.ed_fee_payment_invoiceFile,
          student: item.ed_fee_payment_student,
          name: item.ed_student_name,
          balance: total,
          price: item.ed_fee_payment_price,
          months: [item.ed_fee_payment_month],
          invoiceCount: 1,
          date: moment(item.ed_fee_payment_registerDate).format('DD [de] MMMM [de] YYYY [às] HH:mm'),
        };
      } else {
        grouped[key].balance += total;
        grouped[key].months.push(item.ed_fee_payment_month);
        grouped[key].invoiceCount += 1;
      }
    });

    // converte para array formatado
    const rows = Object.values(grouped).map((g, index) => ({
      ...g,
      index: index + 1,
      monthsLabel: g.months
        .map((m) => {
          if (!m) return '';
          const [mm, yy] = m.split('.');
          const monthName = Months[parseInt(mm, 10)] || mm;
          return `${monthName} de ${yy}`;
        })
        .join(', '),
    }));

    setData(rows);

    // Mantém tua chamada axios + função adicional
    try {
      const [response] = await Promise.all([
        axios.get(FORMURL1[2] + props.datacode.student),
      ]);
      if (response.data.length >= 1) {
        LoadStudentTransportPayments(
          response.data[0],
          props.datacode.studentData,
          props.datacode.academicyear
        );
      }
    } catch (error) {
      console.log(error);
    }

    setTimeout(() => {
      setLoaded(true);
    }, 200);
  }


  
  async function LoadStudentTransportPayments(student, studentCode, Academic_year){ 
    let CurrentStudentData = {}; 
    setTimeout(() => { 
        if (studentCode !== null) { 
           async function CheckStudentPayment(){ 
                try {
                                    
                const [AcademicYearData,  response] = await  Promise.all([
                    axios.get( FORMURL1[3]+Academic_year), 
                    axios.get(FORMURL1[0]+`${student.ed_transport_passenger_id}`+","+`${Academic_year}`)
                ]);
                if (AcademicYearData.data.length >= 1){
                    let CurrentAcademicYearData = AcademicYearData.data[0]; 
                    let PassengerStartMonth  = null;

                    /// start getting the academic year data 
                    let M1, M2 = null;
                    let Y1, Y2 = null; 
                    let currentYear = new Date().getFullYear();
                    M1 = CurrentAcademicYearData.ed_academic_year_startDate.split('-')[1]*1;
                    M2 = CurrentAcademicYearData.ed_academic_year_endDate.split('-')[1]*1;
                    Y1 = CurrentAcademicYearData.ed_academic_year_startDate.split('-')[0]*1;
                    Y2 = CurrentAcademicYearData.ed_academic_year_endDate.split('-')[0]*1;
                    

                    let CRY = Y2 - Y1 === 1 ? 1 : 0;
                    let DF = 12;   
                
                    if(M2 === 0 || M2 === null || M1 === 0 || M1 === null) return false;    
                      if (Y2 - Y1 <= 1) {
                         

                        if (CRY === 1){ 
                            if((M2*1) <= (M1*1)){ 
                            let CurrentMonths = [];
                            let EX = 0; 
                            let R = (DF - (M1*1) === 0 ? 1 : DF- (M1*1)) + (M2*1);
                            EX = R > DF ? R - DF : null;  
                            
                            
                            for(let i = (M1-1)+1; i <= 12; i++){   
                                    CurrentMonths.push({month:(MonthsList[i-1]  + " de "+ Y1)  ,status:'other', code:((i-1+"."+ Y1)*1)})
                                }
                        
                                if(EX !== 0 && EX !== null){
                                    for (let i = 0; i <= (EX -1); i++) { 
                                        CurrentMonths.push({month:(MonthsList[i-1] + " de "+ Y2)  ,status:'other', code:((i-1 +"."+ Y2)*1)})
                                    }
                                }   
                        
                                for(let i = 0; i <= (M2-1); i++) {  
                                    CurrentMonths.push({month:(MonthsList[i]  + " de "+ Y2)  ,status:'other', code:((i+"."+Y2)*1)  })
                                }   
                            
                        
                            Months = CurrentMonths; 
                        
                            }else{ 
                             let CurrentMonths = [];
                            let EX = M1 === M2 ? M2 : (M1 - M2 < 0 ? M2 : M1 - M2);
                            let DM = DF - M1;  
                        
                            
                            for(let i = (M1*1); i <= DF; i++) { 
                                CurrentMonths.push({month:(MonthsList[i-1]  + " de "+ Y1)  ,status:'other', code: ((i-1+"."+ Y1)*1)  })
                            }
                            
                        
                            if(EX >= 1){ 
                            for(let i = 1; i <= EX; i++) { 
                                CurrentMonths.push({month:(MonthsList[i-1]  + " de "+ Y2)  ,status:'other', code: ((i-1+ "."+ Y2)*1)  })
                            }
                            } 
                              Months = CurrentMonths;  
                            } 
                    
                        }else{
                        let CurrentMonths = []; 
                        CurrentMonths.push({month:(MonthsList[(M1*1)-1]  + " de "+ Y1)  ,status:'other', code: ((((M1*1)-1)+"."+Y1)*1)     })
                        
                        if(M2 !== null){
                            for(let i = (M1*1)+1; i <= M2; i++) { 
                            CurrentMonths.push({month:(MonthsList[i-1]  + " de "+ Y1) ,status:'other', code: (((i-1)+"."+Y1)*1)})
                          }
                        }   

                      //  console.log("Senario n 3");

                          Months = CurrentMonths;  
                        }  
 
                    
                        /// end 

                        /*** ADDING PAYMENT STATUS */
                        if(Months.length >= 1){   

                            let  Months1 = Months;
                              
                             const StudentData = async()=>{ 
                                   if (student !== null ){  
                                      CurrentStudentData.name = student.ed_student_name;
                                      CurrentStudentData.class = student.ed_student_class;
                                      CurrentStudentData.picture = Hoot()+student.ed_student_picture; 
                                      CurrentStudentData.id = student.ed_student_id;  
                                      CurrentStudentData.class_title = student.ed_class_title;
                                      PassengerStartMonth  = student.ed_transport_passenger_startMonth*1;
                                   }
                               }  
                               StudentData();  
                              
        
                                
                               setTimeout(() => {   
                                       const ServiceData = async()=>{  
                                           let paidMonths = []

                                           if (response.data.length >= 1) {   
                                               for(let i = 0; i < response.data.length; i++) {
                                               const e = response.data[i];
                                               if(e.ed_transport_payment_month !== ""){   
                                                   for (let a = 0; a <  Months1.length; a++) {
                                                    if((Months1[a].code*1) === (e.ed_transport_payment_month*1)){
                                                        let thisMonthYear =  Months1[a].month.split(" ")[2]*1;
                                                        Months1[a].status = "paid"   
                                                        paidMonths.push(Months1[a].code*1);  
                                                        //console.log("Case 0 = "+thisMonthYear + " | "+currentYear);

                                                    }else{  

                                                       if((Months1[a].code*1) < (((currentMonth-1)+"."+CY)*1) && Months1[a].status !== 'paid'){  
                                                            let thisMonthYear =  Months1[a].month.split(" ")[2]*1;
                                                            if(thisMonthYear <= currentYear) { 
                                                                Months1[a].status = "notpaid"; 
                                                            };   
                                                            //console.log("Case 1= "+thisMonthYear + " | "+currentYear);
                                                       } else{

                                                         if (Y2 - Y1 === 0 ) { 
                                                            let thisMonthYear =  Months1[a].month.split(" ")[2]*1;
                                                            if(thisMonthYear <= currentYear) { 
                                                                if(Months1[a].status !== 'paid') Months1[a].status = "notpaid"; 
                                                            };  
                                                          //  console.log("Case 2= "+thisMonthYear + " | "+currentYear);
                                                         } 

                                                       } 
                                                    } 
                                                   }  
                                               } 
                                           }  
 
        
                                       
                                           for(let i = 0; i < paidMonths.length; i++){
                                               for(let p = 0; p < Months1.length; p++){  
                                                if (Months1[i].code !== paidMonths[p]){ 
                                                    if(Months1[i].code < (((currentMonth-1)+"."+CY)*1) && Months1[i].status !== 'paid'){  
                                                         let thisMonthYear =  Months1[i].month.split(" ")[2]*1;
                                                         if(thisMonthYear <= currentYear)  Months1[i].status = "notpaid";  
                                                        // console.log("Case 3 = "+thisMonthYear + " | "+currentYear);
                                                    }
                                                  }  
                                               }
                                              }   
                                           }
 
        
                                          if(paidMonths.length === 0){ 
                                            let x = null;
                                           for (let i = 0; i < Months1.length; i++) {
                                                  if(Months1[i].code === (((currentMonth-1)+"."+CY)*1)){  
                                                      x = i;
                                                      if(i >=  x){
                                                           Months1[i].status = "other"; 
                                                      }
                                                   } else{
                                                    if(x !== null){
                                                       if(i > x) {
                                                          Months1[i].status = "other"; 
                                                       }
                                                    }else{ 
                                                        let thisMonthYear =  Months1[i].month.split(" ")[2]*1;
                                                        if(thisMonthYear <= currentYear)  Months1[i].status = "notpaid";  
                                                       // console.log("Case 4 = "+thisMonthYear + " | "+currentYear);
                                                    }
                                                   } 
                                               }
                                          }
 
                                         CurrentStudentData.months = Months1; 

                                                                                              
                                          /// PassengerStartMonth 
                                          for (let i = 0; i < Months1.length; i++) {
                                              let MTH = Months1[i];
                                              let CR_MTH_YEAR  = MTH.code.toString().split(".")[1]*1; 
                                              let CR_MTH_MONTH  = MTH.code.toString().split(".")[0]*1; 
                                              if(CR_MTH_YEAR <= Y1){
                                                  if(CR_MTH_MONTH < PassengerStartMonth){
                                                      MTH.status = "null";
                                                  }
                                              } 
                                          }


                                         if(Months1.length >= 1){CurrentStudentData.founded = true}else{CurrentStudentData.founded  = false;} 
                                         setStudentTransportData(CurrentStudentData);      
                                    }  
                                   ServiceData();
                              }, 100); 



                              console.clear();
                              console.log(CurrentStudentData);
                              setStudentTransportData(CurrentStudentData.months);              
                        }
                        // END 
                    }   
                }  
                } catch (error) {
                  CurrentStudentData.founded  = false;
                } 
            }
            CheckStudentPayment();
        } 
    }, 10); 

} 



  useEffect(()=>{
      loadData(); 
  },[]);
 

if(load){
    return (
    <div>
      <div className="mt-2 mb-2">
         <TitleBlock title="Gestão de pagamentos"/>
      </div>
      <TableGrid
          TableHead={columns}
          TableBody={data}  
          TableTitle='Propinas pagas' 
          TableHeight={data.length <= 5 ? 200 : 600}
          NoButtons
      /> 
      <div className="mt-2 pp-payments-status">
          <PP_feepaymentsstatus  student={CurrentStudent} year={StudentAcademicYear} />
      </div>
      <br />
      <div className="mb-4"> 
          {studentTransportData !==  undefined ? 
           <Box>  
              <div className="box-content">
                <div className="ed-space">
                    <h1 className="title">Situação das mensalidades do transporte escolar</h1>
                </div>
                <div className="mt-4 fees">
                    <div className="fees">
                    <div className="ed-wrap">
                        <li className="ed-flex ex"><div className="dot success"></div> Pago</li> 
                        <li className="ed-flex ex"><div className="dot warning"></div>Não pago</li>
                        <li className="ed-flex ex"><div className="dot danger"></div>Anulado</li>
                        <li className="ed-flex ex"><div className="dot other"></div> Outras</li>
                    </div> 
                        <div className="wrap wrap-scroll mt-4"> 
                          {studentTransportData.months !== undefined ?  
                                <>
                                {studentTransportData.months.map((item, index)=>{
                                        return(<div className={item.status === '' ? 'month' : `month ${item.status}`}  key={index}>{item.month}</div>)
                                    })}
                                </> 
                            : ""} 
                        </div>
                    </div>
                </div>
            </div> 
          </Box> 
        : <></>} 
      </div> 
  </div>
  )
}else{
  return (
    <div>
      <div className="mt-2 mb-2">
         <TitleBlock title="Gestão de pagamentos"/>
      </div>
      <div className="d-none">*</div>
      <TableGrid
          TableHead={columns}
          TableBody={[]}  
          TableTitle='Propinas pagas' 
          NoButtons
          TableHeight={200}
      />
      <br />
  </div>
  )
}
}




const Box = styled.div`
    background:var(--ed-white); 
    border-radius:6px; 
    box-shadow:var(--ed-shadow-df); 
    min-width:100px;
    min-height:150px;
    overflow:hidden;


     
    .ex{
        font-size:16px;
        margin-top:8px;
        margin-right:25px;

        .dot{
            width:20px;
            height:20px;
            border-radius:100%;
            margin-right:10px;
            border:3px solid var(--ed-white);
            box-shadow:var(--ed-shadow-df);
        }

        .dot.warning{
            background:#FFBD00;
        }

        .dot.success{
            background:#52B69A;
        }

        .dot.other{
            background:#CED4DA;
        }

        
        .dot.danger{
            background:var(--ed-red-light);
        }
    } 



    .toggle-menu{
         display:none;
    }

    .box-content{
          padding:20px;
    }

    .title, .name{
        font-size: 18px;
        font-weight: 600;
        margin: 0px;
    }

    .br-left{
        border-left:6px solid var(--ed-purple-light);
    }
`;


export default PP_payments