import React, { useState, useEffect } from 'react'
import Table from './Table';
import { Delete, Edit, VisibilityOutlined } from '@mui/icons-material';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import TableGrid from '../../../General/components/TableGrid';
import RefreshButton from '../../../General/components/RefreshButton'; 
import { Avatar } from '@mui/material';
import NewDriverModal from '../modal/NewDriverModal';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
const TABLEURL = Hoot() + 'edualltransportdriversget/get';


const columns = [
  {
    field: 'index',
    headerName: 'Nº',
    resizable: true,
    width: 90,
  },
  {
    field: 'name',
    headerName: 'Nome',
    resizable: true,
    width: 350,
    cellRenderer: (props) => {
      return <div className='ed-flex'>
        <Avatar className='df' alt={props.data.name} src={props.data.picture !== "" ? props.data.picture : ""} />
        <span className='ml-2'>{props.data.name}</span>
      </div>
    }
  },
  {
    field: 'bi',
    headerName: 'Nº do bilhete de identificação',
    resizable: true,
    width: 250,
  },
  {
    field: 'email',
    headerName: 'Email',
    resizable: true,
    width: 200,
  },
  {
    field: 'address',
    headerName: 'Endereço',
    resizable: true,
    width: 200,
  },
  {
    field: 'phone',
    headerName: 'Telefone',
    resizable: true,
  },
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true, cellRenderer: (props) => {
      return <div className="ed-flex">
        <NewDriverModal title='Atualizar ' update='true' get={Hoot() + `edualltransportsingledriverget/get/${props.data.id}`}
          url={Hoot() + `edualltransportdriverupdate/update/${props.data.id}`} toggle_btn={
            <button className="btn-circle  bg-success text-light">
              <Edit />
            </button>} />
        <DeleteModal title='este motorista' url={Hoot() + `edualltransportsdriverdelete/delete/${props.data.id}`}
         message='Motorista deletado com sucesso' toggle_btn={
          <button className="btn-circle bg-danger ml-2 text-light">
            <Delete />
          </button>} />
      </div>;
    }
  }
];


function DriversTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData() {
    try {
      setLoadStatus(0);
      setLoaded(false);
      const response = await axios.get(TABLEURL);
      const rows = [];
      response.data.map((item, index) => {
        rows.push({
          index: index + 1,
          id: item.ed_transport_driver_id,
          name: item.ed_transport_driver_name,
          picture: Hoot() + item.ed_transport_driver_picture,
          bi: item.ed_transport_driver_identification_number,
          email: item.ed_transport_driver_email,
          address: item.ed_transport_driver_address,
          phone: item.ed_transport_driver_phone,
          action: '',
        })
      });
      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoadStatus(1);
    }
  }

  useEffect(() => {
    loadData();
  }, []);


  if (load) {
    return (
      <div id="ed-custom-table-data" >
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista dos motoristas'
          TableBtn={
            <div className='ed-flex'>
                <button id='ed-custom-table-data-btn'
                    onClick={() =>
                        ExportDataToTablesToPdf({
                            fileName: "Lista dos motoristas",
                            headerId: null,
                            contentId:"ed-custom-table-data",
                            footerId: null,
                            rotation: "portrait",
                            buttonId: "ed-custom-table-data-btn",
                            customHeader: "Lista dos motoristas",
                            excludedColumns: ["Ação"]
                        })
                    }
                    className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
                </button>
                <button className='btn-icon btn btn-export-data ml-2'
                    onClick={() => ExportDataForTablesExcel("lista dos motoristas", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
                </button>
                <RefreshButton action={loadData} status={LoadStatus} />
            </div>
        }
        />
      </div>
    )
  } else {
    return (
      <div>
        <><div className="d-none">*</div>
          <TableGrid
            TableHead={columns}
            TableBody={[]}
            TableTitle='Lista de motoristas'
            TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
          />
        </>
      </div>
    )
  }
}

export default DriversTable