import axios from 'axios';
import React, { useEffect, useState } from 'react'
import Hoot from '../General/components/Hoot';

function SeApp() {
  const [MYNAME,SETmYnAME] =  useState(null);
  const [text, setText] =  useState(null);

    const Load = async()=>{
        try {
            const response  =  await axios.get(Hoot()+"getss");
            SETmYnAME(response.data)

        } catch (error) {
             SETmYnAME("error")
        }
    }

    useEffect(() => {
        Load();
    }, []);


    const Add = async()=>{
     try {
        axios.post(Hoot()+"setss",  {text:text}).then(()=>{  
            Load();
            alert("Nice boy")
          }).catch((error)=>{
            alert("error 1");  
          }); 
     } catch (error) {
        alert("error 2");  
     }
    }



  return (
    <div>
    
        <div className="ed-center text-center mb-4">
              <h1>My code = {MYNAME}  </h1>
        </div>

       <div className="ed-flex">
          <input type="text" onChange={(e)=>setText(e.target.value)} placeholder='name here ....' className="form-control" />
          <button className="btn text-light bg-main" onClick={Add}>Login</button>
       </div>
    
    </div>
  )
}

export default SeApp