import React from 'react';
import styled from "styled-components"
import { Swiper, SwiperSlide } from 'swiper/react';
import LatestPostBox from '../../../../Components/PostComponents/LatestPostBox';

function Comp_LatestPost() {
  return (
    <Container>
         <h1 className="title">Acontecimentos recentes</h1>
         <div className="line"></div>
       <div className="col mt-4 mb-4">
       <Swiper  spaceBetween={30}   slidesPerView={3.2}  >
           {[1,2,3,4,5,6].map((item, index)=>(
               <SwiperSlide key={index+1}>
                   <LatestPostBox data={item} />
               </SwiperSlide> 
            ))}
        </Swiper>
       </div>
    </Container>
  )
}

const Container = styled.div`
   max-width:750px; 
   margin:20px 0px;
`;


export default Comp_LatestPost