import React from 'react'
import { Link } from 'react-router-dom';
import styled from 'styled-components';
import ImageLazyLoading from '../../../General/components/ImageLazyLoading';
import {BsDownload,BsFileText} from "react-icons/bs";

function Profile_gn_experience({}) {

const Data = [
     {name:"TikTok", image:"https://p16-tiktokcdn-com.akamaized.net/obj/tiktok-obj/e57eeb7f01a395871c992fe592822b64"},
     {name:"Teala INC", image:"https://images.fineartamerica.com/images/artworkimages/mediumlarge/3/4-tesla-logo-davison-melissa.jpg"},
     {name:"Spotify", image:"https://play-lh.googleusercontent.com/cShys-AmJ93dB0SV8kE6Fl5eSaf4-qMMZdwEDKI5VEmKAXfzOqbiaeAsqqrEBCTdIEs=w240-h480-rw"},
     {name:"Google", image:"https://t.ctcdn.com.br/P7-_JvQTS4U7-if6zHyXjyMiNQ8=/400x400/smart/i606944.png"}, 
]


  return (
     <Container>
          <h1 className="title">Experiencia profissional (4)</h1>
          <section>
               {Data.map((item, index)=>{
                  return(
                    <article>
                    <div className="content-header">
                        <div className="company-logo">
                             <Link to="#">
                                <div className="icon"><ImageLazyLoading height={80} source={item.image} /></div>
                            </Link>
                        </div>
                     <div className="ed-block">
                     <Link to="#"><h5>{item.name}</h5></Link>
                       <span className="charge">Engenheiro de software</span>
                       <div className="date">Desde 14 de Maio de 2019 até 23 de Junho de 2023</div>
                     </div>
                    </div>
                    <div className="content-body">
                        {index === 0 ? 
                          <a href="#">
                           <div className="letter-box ed-space">
                              <div className="ed-flex">
                                <div className="icon"><BsFileText/></div>
                                <div className="text"><span>Carta de recomendação</span></div>
                              </div>
                              <div className="download-icon"><BsDownload /> </div>
                           </div>
                          </a>
                         : <></>}
                         <div className="description mt-1">
                             Lorem ipsum dolor sit amet consectetur adipisicing elit. Eos doloremque accusantium dolorem, reprehenderit ipsum ex nam rerum id magni sapiente magnam dolorum sed quo quibusdam quas. Aliquid placeat et perferendis! Provident, repellat numquam. Voluptate nesciunt similique fuga nostrum quae nam!
                         </div>
                    </div>
                 </article>)
               })}
          </section>
     </Container>
  )
}


const Container = styled.div`
    margin:20px 0px;

     section{
          margin:10px 0px;

           article{
               display:block;
               margin:30px 0px;

               .content-header{
                  display:flex;
                  margin-bottom:10px;

                  .company-logo{
                      height:80px;
                      width:80px;
                      border:3px solid var(--ed-silver-light); 
                      margin-right:20px;
                      border-radius:6px;

                      img{
                        border-radius:6px;
                        height:100%;
                        width:100%;
                      }
                  }


                 .ed-block{
                     h5{
                        font-size:18px;
                        color:var(--ed-dark);
                      }

                      .charge, .date{
                         font-size:15px;
                      }

                      .date{
                        color:var(--ed-grey-text);
                      }
                 } 

               }


               .content-body{
                  .description{
                     background:var(--ed-silver-light);
                     padding:10px;
                     border-radius:6px;
                     margin:10px 0px;
                     font-size:15px;
                     color:var(--ed-grey-text);
                     width:auto;
                     max-width:700px;
                  }

                  .letter-box{
                      padding:10px;
                      margin:10px 0px;
                      background:var(--ed-purple-light);
                      color:var(--ed-white);
                      max-width:400px;
                      border-radius:6px;

                        svg{
                            font-size:20px;
                            width:25px;
                            height:25px;
                        }

                        .text{
                            margin-left:10px;
                        }
                  }
                  
               }




           }
     }

`;

export default Profile_gn_experience
