import React, { useState } from 'react';
import Dialog from '@mui/material/Dialog';
import AppBar from '@mui/material/AppBar';
import Toolbar from '@mui/material/Toolbar';
import Slide from '@mui/material/Slide';
import styled from 'styled-components';
import { Close } from '@material-ui/icons';
import { Avatar, Checkbox, FormControlLabel } from '@mui/material';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import { toast } from 'react-hot-toast';
import CRValueStatus from '../../../General/components/CRValueStatus';
import { Button, Form } from 'react-bootstrap';
import { Save, Update } from '@mui/icons-material';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import Loader from '../../../General/components/Loader';

const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="up" ref={ref} {...props} />;
});

function EditUserModal(props) {
  const [open, setOpen] = useState(false);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [Founded, SetFounded] = useState(null);

  const handleClickOpen = async () => {
    setOpen(true);
    GET_DATA();
  };

  const handleClose = () => {
    setOpen(false);
  };

  const FORMURL = [
    props.get ? props.get : '',
    props.url ? props.url : '',
    Hoot() + "eduallcheckexistentuseraccountemail/",
  ];


  const RealNames = [
    { name: "Módulo pedagogy", realname: "Módulo de Pedagogia" },
    { name: "Módulo myinstitute", realname: "Módulo da Minha Instituição" },
    { name: "Módulo portal", realname: "Portal do Professor" },
    { name: "Módulo secretary", realname: "Módulo da Secretaria" },
    { name: "Módulo configuration", realname: "Módulo de Configuração" },
    { name: "Módulo finances", realname: "Módulo de Finanças" },
    { name: "Módulo administration", realname: "Módulo de Administração" },
    { name: "Módulo library", realname: "Módulo da Biblioteca" },
    { name: "Módulo transportation", realname: "Módulo de Transporte" },
  ];


  const getRealName = (inputName) => {
    const normalize = (str) =>
      str
        .normalize("NFD") // Remove acentos
        .replace(/[\u0300-\u036f]/g, "")
        .replace(/\s+/g, "")
        .toLowerCase();

    const normalizedInput = normalize(inputName);
    const match = RealNames.find(item => normalize(item.name) === normalizedInput);

    return match ? match.realname : inputName;
  };



  const INPUTS = {
    user_account_name: "",
    user_account_charge: "",
    access_pedagogy: 0,
    access_myinstitute: 0,
    access_portal: 0,
    access_secretary: 0,
    access_configuration: 0,
    access_finances: 0,
    access_administration: 0,
    access_library: 0,
    access_transportation: 0,
  };

  const handleInput = (e) => {
    const { id, value, checked } = e.target;
    setForm((prev) => ({
      ...prev,
      [id]: id.startsWith("access_") ? (checked ? 1 : 0) : value,
    }));
  };

  const FormSubmit = async (e) => {
    e.preventDefault();
    setRegisterStatus(0);

    const formData = new FormData();
    const INP = {};
    Object.keys(form).forEach((key) => {
      formData.append(key, form[key]);
      INP[key] = form[key];
    });

    try {
      await axios.put(FORMURL[1], INP);
      toast.success("Conta de usuário atualizada com sucesso!");
      setRegisterStatus(2);
    } catch (error) {
      console.clear();
      console.log(error.response);
      console.log("INPUTS", INP);
      toast.error("Lamentamos mas não foi possível executar esta ação");
      setRegisterStatus(1);
    }

  };

  const GET_DATA = async () => {
    if (props.update) {
      try {
        SetFounded(false);
        const response = await axios.get(FORMURL[0]);
        if (response.data.length > 0) {
          SetFounded(true);
          const userData = response.data[0];
          setForm({
            user_account_name: userData.ed_employee_name,
            user_account_charge: userData.ed_employee_charge,
            access_pedagogy: userData.ed_user_access_pedagogicalarea,
            access_myinstitute: userData.ed_user_access_myinstitute,
            access_portal: userData.ed_user_access_portal,
            access_secretary: userData.ed_user_access_secretary,
            access_configuration: userData.ed_user_access_configuration,
            access_finances: userData.ed_user_access_finances,
            access_administration: userData.ed_user_access_administration,
            access_library: userData.ed_user_access_library,
            access_transportation: userData.ed_user_access_transportation,
          });
        } else {
          SetFounded(true);
          toast.error("Lamentamos mas não foi possível encontrar a informação selecionada!");
        }
      } catch (error) {
        SetFounded(true);
        toast.error("Lamentamos mas não foi possível encontrar a informação selecionada!");
      }
    }
  };

  return (
    <div>
      <div onClick={handleClickOpen}>
        {props.toggle_btn ? props.toggle_btn : <></>}
      </div>
      <Dialog className='special-dialog' fullScreen open={open} onClose={handleClose} TransitionComponent={Transition}>
        <AppBar sx={{ position: 'relative' }}>
          <Toolbar>
            <div className="ed-space">
              <div className="ed-wrap align-center">
                <UserOptionDropDown />
                <div className="title"><h1>Editar informações de usuário</h1></div>
              </div>
              <div onClick={handleClose} className="close-btn">
                <Close />
              </div>
            </div>
          </Toolbar>
        </AppBar>
        <Content>
          {Founded === false ?
            <div className="ed-flex ed-center">
              <br /><br />
              <div>
                <Loader />
              </div>
              <br /><br />
            </div> :
            <div>
              {Founded === null ? <></> :
                <Form onSubmit={FormSubmit} method='post' encType='multipart/form-data'>
                  <Form.Group className="mb-3">
                    <div>
                      <Form.Label>Nome do funcionário</Form.Label>
                      <Form.Control readOnly className={!!errors.user_account_name && 'is-invalid'} value={form.user_account_name || ''} isInvalid={!!errors.user_account_name} type="text" name='user_account_name' id="user_account_name" />
                      <Form.Control.Feedback type='invalid'>{errors.user_account_name}</Form.Control.Feedback>
                    </div>
                  </Form.Group>
                  <Container>
                    {Object.keys(INPUTS).map((key, index) => {
                      if (key.startsWith("access_")) {
                        return (
                          <article key={index}>
                            <div className="small-box">
                              <FormControlLabel
                                control={<Checkbox id={key} checked={form[key] === 1} onChange={handleInput} />}
                                label={getRealName(key.replace("access_", "Módulo "))}
                              />
                            </div>
                          </article>
                        );
                      }
                      return null;
                    })}
                  </Container>
                  <div className="dialog-footer">
                    <div className="ed-space">
                      <div className="ed-flex"></div>
                      <div className="ed-flex">
                        <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                        <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />
                      </div>
                    </div>
                  </div>
                </Form>
              }
            </div>
          }
        </Content>
      </Dialog>
    </div>
  );
}

export default EditUserModal;



const Content = styled.div`
  max-height:92vh;
  height:92vh;
  padding:20px;
  overflow-y:auto;

  &::-webkit-scrollbar{
    width:6px;
    background-color:transparent;
 }

 &::-webkit-scrollbar-thumb{
    background:rgb(219, 219, 219); 
 }
 
`;


const Container = styled.div`   
padding-right:10px;
 

article{
 width:100%;

 label{
     width:100%;
 }

 .small-box{  
     margin:10px 0px;
     min-height:50px;
     padding:5px 10px;
     border-radius:6px;
     width:100%;  
     display:flex;
     align-items:center;
     cursor:pointer;
     border:1px solid var(--ed-silver-light); 
 }


ol{
   display:block;

     span{
         font-size:15px;
     }
 }

}



`;