import React, { useState, useEffect } from 'react'
import axios from 'axios'
import { Delete, Description, Edit, PreviewOutlined, Refresh } from '@mui/icons-material';
import Table from './Table';
import Hoot from '../../../General/components/Hoot';
import { DemoComponent, GetserviceCoin, GetServiceTitle, GetStudentName, GetStudentPicture } from '../../../General/components/InstituteData';
import DeleteModal from '../elements/DeleteModal';
import NewfeeManualPaymentModal from '../modal/NewfeeManualPaymentModal';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import TableGrid from '../../../General/components/TableGrid';
import { PrintOutlined } from '@material-ui/icons';
import { Link } from 'react-router-dom';
import NumberToPrice from '../../../General/components/NumberToPrice';
import { Avatar } from '@mui/material';
import NewTransportPaymentsModal from '../modal/NewTransportPaymentsModal';
import PopTransportPaymentDetailsModal from '../modal/PopTransportPaymentDetailsModal';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import moment from 'moment';
import { PiFilePdf, PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import DownloadInvoicePDFButton from '../../../General/components/DownloadInvoicePDFButton';


const TABLEURL = [Hoot() + "edualltransportpaymentsapi/get/", Hoot() + "eduallgetsingleinstitute/get/1"];
const Months = ["Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho", "Julho",
  "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"];



const columns = [
  {
    field: 'invoiceN',
    resizable: true,
    headerName: 'Nº da Fatura',
    width: 200,
  },
  {
    field: 'student',
    resizable: true,
    headerName: 'Passageiro',
    width: 250,
    cellRenderer: (props) => {
      return <SwitchFromPages link={`studentinfo/${props.data.studentid}`}
        menu='3' menu_item='17' toggle_btn={
          <div className='ed-flex'>
            <Avatar className='df' alt={props.data.name} src={props.data.picture !== "" ? Hoot() + props.data.picture : ""} />
            <span className='ml-2'>(#{props.data.studentcode}) - {props.data.name}</span>
          </div>
        } />
    }
  },
  {
    field: 'service',
    resizable: true,
    headerName: 'Titulo do serviço',
    width: 250,
  },
  {
    field: 'month',
    resizable: true,
    headerName: 'Mês pago',
    width: 180,
    cellRenderer: (props) => {
      return <div className="tb-item">{Months[Math.floor(props.data.month.split('.')[0])] + " de " + props.data.month.split('.')[1]}</div>
    }
  },
  {
    field: 'price',
    resizable: true,
    headerName: 'Preçario',
    width: 160,
    cellRenderer: (props) => {
      return <div className='ed-flex'> {NumberToPrice(props.data.price)}  {props.data.coin} </div>
    }
  },
  {
    field: 'date',
    resizable: true,
    headerName: 'Data de pagamento',
    width: 250,
  },
  {
    field: 'total',
    headerName: 'Total',
    width: 150,
    cellRenderer: (props) => {
      return <div className='ed-flex'>
        {NumberToPrice(props.data.balance)}  {" " + " "}
        {props.data.coin}
      </div>
    }
  },
  {
    field: 'action',
    resizable: true,
    headerName: 'Ação',
    width: 290,
    cellRenderer: (props) => {
      return (
        <div className="ed-flex">
          <div className="d-none">
            <NewTransportPaymentsModal title='Atualizar ' update='true' get={Hoot() + `edualltransportpaymentsingle/get/${props.data.id}`}
              url={Hoot() + `edualltransportpaymentupdate/update/${props.data.id}`} toggle_btn={
                <button className="btn-circle bg-success text-light">
                  <Edit />
                </button>
              } />
          </div>
          <div className="tb-item">
            <DownloadInvoicePDFButton documentId={props.data.code} />
          </div>
          <PopTransportPaymentDetailsModal print={`/student_transport_payment_print_invoice/${props.data.id}`}
            get={Hoot() + `edualltransportpaymentsingle/get/${props.data.id}`} toggle_btn={
              <PreviewButton />
            } />
          <DeleteModal title='um pagamento de transporte escolar' url={Hoot() + `edualltransportpaymentsdelete/delete/${props.data.id}`}
            message='Pagamento deletado com sucesso' toggle_btn={
              <DeleteButton />
            } />
        </div>
      );
    }
  }
];

function TransportPaymentsTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData() {
    setLoaded(false);
    try {
      setLoadStatus(0);
      const response = await axios.get(TABLEURL[0]);
      const rows = [];
      response.data.map((item, index) => {
        let total = item.ed_transport_payment_price * 1 - ((item.ed_transport_payment_price * item.ed_transport_payment_discount) / 100);
        let base = item.ed_transport_payment_iva * 1 > 0 ? total / (1 + (item.ed_transport_payment_iva / 100)) : total;
        let totalIva = total - base;
        let fineValue = item.ed_transport_payment_fineType * 1 === 1
          ? item.ed_transport_payment_fineValue * 1
          : ((base * item.ed_transport_payment_fineValue * 1) / 100);
        let totalResult = total + fineValue;

        rows.push({
          index: index + 1,
          id: item.ed_transport_payment_id,
          service: item.ed_service_title,
          code: item.ed_transport_payment_invoiceFile,
          coin: item.ed_coin_code,
          student: item.ed_transport_payment_student,
          studentcode: item.ed_student_code,
          studentid: item.ed_student_id,
          name: item.ed_student_name,
          picture: item.ed_student_picture,
          month: item.ed_transport_payment_month,
          balance: totalResult,
          price: item.ed_transport_payment_price,
          iva: item.ed_transport_payment_iva,
          discount: item.ed_transport_payment_discount,
          fineType: item.ed_transport_payment_fineType,
          fineValue: item.ed_transport_payment_fineValue,
          invoiceN: item.ed_transport_payment_invoiceCode,
          date: moment(item.ed_transport_payment_registerDate).format('DD [de] MMMM [de] YYYY [às] HH:mm'),
          total: '',
          action: '',
        });
      });

      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoaded(true);
      setLoadStatus(1);
    }
  }

  useEffect(() => {
    loadData();
  }, []);


  if (load) {
    return (
      <div id="ed-custom-table-data" >
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Mensalidades do transporte pagas'
          TableBtn={
            <div className='ed-flex' >
              <button id='ed-custom-table-data-btn'
                onClick={() =>
                  ExportDataToTablesToPdf({
                    fileName: "Lista dos pagamentos das mensalidades do transporte",
                    headerId: null,
                    contentId: "ed-custom-table-data",
                    footerId: null,
                    rotation: "landscape",
                    buttonId: "ed-custom-table-data-btn",
                    customHeader: "Lista dos pagamentos das mensalidades do transporte",
                    excludedColumns: ["Ação"]
                  })
                }
                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
              </button>
              <button className='btn-icon btn btn-export-data ml-2'
                onClick={() => ExportDataForTablesExcel("Mensalidades do transporte pagas", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
              </button>
              <RefreshButton action={loadData} status={LoadStatus} />
            </div>}
        />
        <br />
      </div>
    )
  } else {
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={[]}
          TableTitle='Mensalidades do transporte pagas'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
        <br />
      </div>
    )
  }
}

export default TransportPaymentsTable