 

import React, {useState, useEffect} from 'react'
import Table from './Table';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import { Delete, Description, Edit ,OpenInBrowser, Refresh } from '@mui/icons-material';
import NewAcademicLevelModal from '../modal/NewAcademicLevelModal';
import DeleteModal from '../elements/DeleteModal';  
import TableGrid from '../../../General/components/TableGrid';
import { Badge } from 'react-bootstrap';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import ReplaceWord from '../../../General/components/ReplaceWord';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';

const TABLEURL = Hoot()+"eduallacademiclevelsapi/get/"
 


const columns = [ 
  {
  field: 'index', 
  headerName: 'Nº' ,
   resizable: true,
   width:90
  },
  {
    field: 'title',
    headerName:ReplaceWord("Classe"),
    resizable: true,
  },
  {
    field: 'forExam',
    headerName: ReplaceWord("Classe")+' de exame',
    resizable: true,
    cellRenderer:(props)=>{
      return  Math.floor(props.data.forExam) === 1 ? 
      <Badge bg='info'><div className="text-dark">Sim</div></Badge> :
      <Badge bg='danger'><div className="text-dark">Não</div></Badge>
    }
  },
  {
    field: 'forFt',
    headerName: ReplaceWord("Classe")+' de recurso',
    resizable: true,
    cellRenderer:(props)=>{
      return  Math.floor(props.data.forFt) === 1 ? 
      <Badge bg='info'><div className="text-dark">Sim</div></Badge> :
      <Badge bg='danger'><div className="text-dark">Não</div></Badge>
    }          
  },
  {
    field: 'action',
    headerName: 'Ação', 
     resizable: true,
     cellRenderer:(props) => { 
      return   <div className="ed-flex">
        <NewAcademicLevelModal  title='Atualizar ' update='true' get={Hoot()+`eduallsingleacademiclevelsapi/get/${props.data.id}`}  
        url={Hoot()+`eduallacademiclevelupdate/update/${props.data.id}`}  toggle_btn={
        <button  className="btn-circle btn-edit-academic-level bg-success text-light">
            <Edit/>
        </button> 
        }/>
        <DeleteModal title={'esta ' + ReplaceWord("Classe", true)} url={Hoot()+`eduallacademicleveldelete/delete/${props.data.id}`} message={ReplaceWord("Classe") + ' deletada com sucesso'} toggle_btn={ 
      <button  className="btn-circle bg-danger ml-2 text-light">
          <Delete/>
      </button>} /> 
      </div> ;
    }
  } 
];

function AcademicLevelTable() {
    const [data, setData] = useState([]);  
    const [load, setLoaded] = useState(false);
    const [RegisterStatus, setRegisterStatus] = useState(null);
    
    async function loadData(){
      try {
        setLoaded(false);
        setRegisterStatus(0); 
        const response = await axios.get(TABLEURL);
        const rows = [];
        const rows1 = [];
        response.data.map((item, index)=>{ 
          rows.push({
            id:item.ed_academic_level_id,
            index:index+1,
            title:item.ed_academic_level_title,
            forExam:item.ed_academic_level_forExam,
            forFt:item.ed_academic_level_forFt,
            action:"",  
         }) 
        });  
        setData(rows); 
        setTimeout(() => {
           setLoaded(true);
        }, 200);
        setRegisterStatus(2); 
      } catch (error) {
        setRegisterStatus(1); 
      }
    };
    
    useEffect(()=>{ 
        loadData();  
    },[]);
   
 

    if(load){
        return (
        <div id="ed-custom-table-data" >
          <TableGrid
              TableHead={columns}
              TableBody={data}  
              TableTitle={ReplaceWord("Classes académicas")}
              TableBtn={
                <div className='ed-flex' >
                                    
                <button id='ed-custom-table-data-btn'
                  onClick={() =>
                    ExportDataToTablesToPdf({
                      fileName: "Lista das "+ ReplaceWord("Classes académicas"),
                      headerId: null,
                      contentId: "ed-custom-table-data",
                      footerId: null,
                      rotation: "portrait",
                      buttonId: "ed-custom-table-data-btn",
                      customHeader: "Lista das "+ ReplaceWord("Classes académicas"),
                      excludedColumns: ["Ação"]
                    })
                  }
                  className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
                </button>

                <button className='btn-icon btn btn-export-data ml-2' 
                    onClick={()=>ExportDataForTablesExcel( ReplaceWord("Classe académica"), ["Ação"])}><PiMicrosoftExcelLogoDuotone />
                </button>
                <RefreshButton action={loadData} status={RegisterStatus} />
            </div>}
          />
      </div>)
    }else{
      return (
        <>
         <div className="d-none">*</div>
          <div>
            <TableGrid
                TableHead={columns}
                TableBody={[]} 
                TableTitle={ReplaceWord("Classes académicas")}
                TableBtn={<RefreshButton action={loadData} status={RegisterStatus} />}
            />
        </div>
        </>
      )
    }
    
}

export default AcademicLevelTable;