import React, { useEffect, useState } from 'react'
import styled from "styled-components";
import {Table, Form} from 'react-bootstrap';
import { Avatar } from '@mui/material'; 
import RandomAvatarColor from '../../General/components/RandomAvatarColor';
import Hoot from '../../General/components/Hoot';
import { SearchOutline, AtOutline, CallOutline, LocationOutline, MailOpenOutline } from 'react-ionicons'
import { VideocamOutline,  ChatbubbleEllipsesOutline, EllipsisVerticalOutline} from 'react-ionicons'
import axios from "axios";
import {toast} from 'react-hot-toast';
import { Link } from 'react-router-dom/cjs/react-router-dom';
import { SummarizeOutlined } from '@mui/icons-material';

function InstituteContacts() {
  document.title  = "Contactos da instituição";
  const [Data, setData] =  useState([]);
  const[FilterData, setFilterData] =  useState([]);
  const [SelectedContact, setSelectedContact] =   useState({});
   let x = 0;

  const loadData = async()=>{
    try {
      const response = await axios.get(Hoot()+"eduallgetinstitutecontacts/get");
      setData(response.data);
      setFilterData(response.data)
    }catch(error){
       console.clear()
       console.log(error);
      toast.error("Lamentamos mas não foi  possivel carregar os contactos da instituição !"); 
    }
  } 


  const filterContacts = (value) => {
    const filteredDataArray = Data.filter(contact => 
      contact.ed_contact_name.toLowerCase().includes(value.toLowerCase()) ||
      contact.ed_contact_phone.includes(value) ||
      contact.ed_contact_email.toLowerCase().includes(value.toLowerCase())
    );
    setFilterData(filteredDataArray);
  };
  

  useEffect(() => {
    loadData();
  }, []); 


const Types  = ["Estudante", "funcionário", "Encarregado", "Visitante", "Fornecedor", "Outro"];
const contactTypes = ["", "Estudante", "Encarregado", "Funcionário", "Outro"];

  return (
    <div> 
    <Box>

   {SelectedContact.ed_contact_name ?
    <>
      <div className="details-area">
          <section>
              <div className="ed-flex">
                <Avatar  src={Hoot()+SelectedContact.ed_contact_photo}  sx={{background:`${SelectedContact.ed_contact_avatar}`,width:120,height:120}} />
                <div className="ed-block ml-2">
                      <div><h3>{SelectedContact.ed_contact_name}</h3></div>
                      <p>Engeheniro de software</p>
                      <div className="bdg">
                        <div className="bg-main dot"></div>
                        <span>{contactTypes[SelectedContact.ed_contact_type*1]}</span>
                      </div>
                </div>
              </div> 
              <Buttons className="mt-2 mb-2 ed-flex">
                <button><CallOutline/></button>
                <button><ChatbubbleEllipsesOutline/></button>
                <button><VideocamOutline/></button>
                <button><MailOpenOutline/></button>
                <button><EllipsisVerticalOutline/></button>  
            </Buttons>  
            <div className="section-data">
              <h4>Informações de contacto</h4>
                <ul>
                    <li>
                      <div className="icon"><AtOutline/></div>
                      <span>{SelectedContact.ed_contact_email}</span>
                    </li>
                    <li>
                      <div className="icon"><CallOutline/></div>
                      <span>{SelectedContact.ed_contact_phone}</span>
                    </li>
                    <li>
                      <div className="icon"><LocationOutline/></div>
                      <span>{SelectedContact.ed_contact_address}</span>
                    </li>
                </ul>
               <hr />
             </div>
             <div className="col">
                <button className="btn col-lg-12 mt-2 mb-2 bg-main text-center">Enviar convite de adesão</button>  
                <div className="account-box">
                     
                </div>
             </div>
          </section>
      </div>
      <div className="pd-1"></div>
    </>
   : <></>}
      
       <div className="col"> 
       <div className="ed-space col mb-2">
          <h1 className="title">Contactos ({Data.length})</h1>
          <div>
              <Link  to="/contactslist" >
                  <button className='btn ml-2 btn-main bg-main'><SummarizeOutlined/> Tabela de contactos</button>
              </Link>
          </div>
       </div>
       <div className="search-bar mt-2">
          <Form>
             <Form.Control placeholder="Pesquisar..."  onChange={(e)=>filterContacts(e.target.value)} onPaste={(e)=>filterContacts(e.target.value)}  />
             <div className="icon"><SearchOutline/></div>
          </Form>
       </div>
       <div className="table-box">
       <Table hover borderless >
          <thead>
            <tr>
              <th>Nome</th>
              <th>Telefone</th> 
              <th>Email</th>
            </tr>
          </thead>
          <tbody>
           {FilterData.map((item, index)=>(
              <tr className='cursor-pointer' key={index+1}>
                <td>  
                  <div className="ed-flex">
                    <Avatar src={Hoot()+item.ed_contact_photo}  sx={{background:`${item.ed_contact_avatar}`, width:45,height:45}} />
                    <div className="ed-block ml-2">
                         <div><span>{item.ed_contact_name}</span></div>
                         <p>{Types[item.ed_contact_type*1]}</p>
                    </div>
                  </div>
                </td>
                <td>{item.ed_contact_phone}</td> 
                <td>{item.ed_contact_email}</td>
              </tr> 
           ))}
          </tbody>
        </Table>
       </div>  
       </div>
     </Box>
    </div>
  )
}

const Box = styled.div`
    width:100%;
    border-radius:6px;  
    margin-bottom:20px !important;
    background:var(--ed-white);  
    box-shadow:var(--ed-shadow-df); 
    padding:20px;
    display:flex;

    h1.title{
       font-size:18px;
       margin:0px 0px;
       font-weight:600;
    }

    .table-box{
       max-height:750px;
       overflow-y:auto;  
       
       &::-webkit-scrollbar{
        width:6px;
        background-color:transparent;
      }
 
        &::-webkit-scrollbar-thumb{
            background:#eaeaee;   
        } 
    }


    .details-area{
        min-width:360px;
        max-width:360px;
        border-right:1px solid  var(--ed-silver-light);
        padding-right:20px;

           div h3{
              font-size:18px;
              font-weight:600;
           }

           .bdg{
              font-size:14px !important;
              padding:6px 14px;
              border-radius:30px;
              background:var(--ed-background-color);
              width:max-content;
              margin-top:5px;
              display:flex;
              align-items:center;


                 .dot{
                     width:10px;
                     height:10px;
                     border-radius:100%;
                     margin-right:10px;
                 }
           }


           p{
              font-size:15px;
              color:var(--ed-grey-text);
           }

          .section-data{
              h4{
                  font-size:18px;
                  font-weight:600;
                  margin-top:20px;
              }
          }

          
          hr{
            border-color:var(--ed-silver);
            margin:10px 0px; 
          }

           ul{
             padding:0px;
             margin:15px 0px;
               
                li{
                  display:flex;
                  align-items:center;
                  margin:10px 0px;

                  svg{
                      width:18px;
                      height:18px;
                      margin-right:10px;
                      color:var(--ed-grey-text);
                      fill:var(--ed-grey-text);
                  }

                   span{
                     color:var(--ed-grey-text);
                     font-size:15px;
                   }
                }
           }
    }

    table{
      .ed-block{
        p{
          font-size:13px !important;
          color:var(--ed-grey-text);
        }
      }
    }


    .search-bar{
        form{
          display:flex;
          align-items:center;
          border:1px solid var(--ed-silver-light);
          padding:5px 10px;
          border-radius:6px;
          width:100%;

            input{
                border:none !important;
            }

            .icon{
                margin-left:10px;
                  svg{
                      width:20px;
                      height:20px;
                  }
            }
        }
    }
`;


const Buttons = styled.div`
    button{
      margin:0px 5px;
      width:40px;
      min-width:40px;
      height:40px;
      background:var(--ed-background-color);
      border-radius:100%;
      border:1px solid var(--ed-silver-light);
      margin-top:10px;
    }
`;


export default InstituteContacts