import React from 'react'
import styled from 'styled-components';
import AddsGenerator from '../../Components/AddsGenerator';
import { Form } from 'react-bootstrap';
import SidebarLeft from '../../Employees/Components/SidebarLeft';
import UserNavbar from '../../Components/UserNavbar';
import {TbListSearch} from "react-icons/tb";
import { Link } from 'react-router-dom';
import { Avatar, AvatarGroup } from '@mui/material';
import {GoProjectRoadmap} from "react-icons/go";
import ImageLazyLoading from '../../../General/components/ImageLazyLoading';
import {BsFillPlayFill} from "react-icons/bs";
import AddContactButton from '../../Components/AddContactButton';

function NotifactionsMain({userdata}){  
    document.title  = "Notificações";

    return (
      <div className="eduall-network">
      <UserNavbar data={userdata} />
       <Container className='ed_search_page'> 
          <div className="ed-wrapper">
          <div className="content">
             <SidebarLeft data={userdata} />
                  <section>
                      <ul className="notifications-container">

                          <li className="post-notf not-readed"> 
                            <Link to="#">
                                 <Avatar sx={{width:40,height:40}} className='df' src="#" />
                            </Link>
                            <div className="ed-block ml-2">
                                <div className="date">******</div>
                                <div className="description">
                                    <b>João maria</b> adicionou uma <b className="text-orange"> tarefa </b>
                                    ao projeto <b className="text-green">Arquitectura de computadores</b>
                                </div>
                                <div className="ed-flex post-box col mt-2 bx">
                                    <div className="image"><Avatar variant="rounded" sx={{width:50,height:50}}  /></div>
                                    <div className="ed-block ml-2">
                                       <p>criação de diagramas para planos multidimensionais em domini proprio ...</p>
                                      <div className="date mt-2 ed-flex"><b>Publicado </b> *****</div>
                                    </div>
                                </div>
                            </div> 
                          </li>


                          <li className="prt-notf"> 
                            <Link to="#">
                                 <Avatar sx={{width:40,height:40}} className='df' src="#" />
                            </Link>
                            <div className="ed-block ml-2">
                                <div className="date">******</div>
                                <div className="description">
                                    <b>João maria</b> adicionou uma <b className="text-orange">tarefa</b>
                                    ao projeto <b className="text-green">Arquitectura de computadores</b>
                                </div> 
                            </div> 
                          </li>


                          <li className="rqs-notf"> 
                            <Link to="#">
                                 <Avatar sx={{width:40,height:40}} className='df' src="#" />
                            </Link>
                            <div className="ed-block ml-2">
                                <div className="date">******</div>
                                <div className="description">
                                    <b>João maria</b> adicionou uma <b className="text-orange">tarefa</b>
                                    ao projeto <b className="text-green">Arquitectura de computadores</b>
                                </div> 
                                <div className="ed-flex buttons mt-2">
                                     <button className="btn bg-main mr-2 mt-2">Aceitar</button>
                                     <button className="btn bg-danger mr-2 mt-2">Rejeitar</button>
                                </div>
                            </div> 
                          </li>


                          <li className="reaction-notf"> 
                            <Link to="#">
                                 <Avatar sx={{width:40,height:40}} className='df' src="#" />
                            </Link>
                            <div className="ed-block ml-2">
                                <div className="date">******</div>
                                <div className="description">
                                    <b>João maria</b> <span className="text-red">❤</span> curtiu a pagina do <b className="text-main">colegio Micissipi</b> </div> 
                            </div> 
                          </li>


                          <li className="files-notf"> 
                            <Link to="#">
                                <Avatar sx={{width:40,height:40}} className='df' src="#" />
                            </Link>
                            <div className="ed-block ml-2">
                                <div className="date">******</div>
                                <div className="description">
                                <b>João maria</b> <span className="text-red">❤</span> curtiu a pagina do <b className="text-main">colegio Micissipi</b> </div> 
                                <div className="image-assets ed-flex mt-2 bx">
                                  {[1,2,3,4,5].map((item, index)=>(
                                     <div className="image"><ImageLazyLoading source="" height={107} /></div>
                                  ))}
                                </div>
                            </div> 
                          </li>

                          
                          <li className="member-notf"> 
                            <Link to="#">
                                 <Avatar sx={{width:40,height:40}} className='df' src="#" />
                            </Link>
                            <div className="ed-block ml-2">
                                <div className="date">******</div>
                                <div className="description">
                                <b>João maria</b> <span className="text-red">❤</span> curtiu a pagina do <b className="text-main">colegio Micissipi</b> </div> 
                                 <div className="member-box bx mt-2 col ed-space">
                                     <div className="ed-flex">
                                      <Avatar sx={{width:30,height:30}} className='df' src="#" />
                                       <div className="name ml-2">Carmos Mendonça</div>
                                     </div>
                                     <div className="ed-flex">
                                         <AddContactButton CODE={0} />
                                     </div>
                                 </div>
                            </div> 
                          </li>


                          <li className="video-notf"> 
                            <Link to="#">
                                 <Avatar sx={{width:40,height:40}} className='df' src="#" />
                            </Link>
                            <div className="ed-block ml-2">
                                <div className="date">******</div>
                                <div className="description">
                                <b>João maria</b> curtiu a pagina do <b>colegio Micissipi</b> </div> 
                                 <div className="video-box mt-2 bx">
                                    <small>como mudar a dinamica escolar ...</small>
                                   <div className="video-poster"> 
                                        <div className="video-box-over">
                                                <div className="ed-center text-main d-flex play-btn-box">
                                                    <div className="icon"><BsFillPlayFill/> </div>
                                                </div> 
                                        </div>
                                        <ImageLazyLoading source="#" height={200} /> 
                                   </div>
                                     
                                 </div>
                            </div> 
                          </li>




                      </ul>
                  </section>
                  <div className="filter-box">
                       <div className="box">
                            <div className="ed-flex title"><TbListSearch/>  Filtrar resultados</div>
                            <Form>
                              <div className="mt-4">
                                  <Form.Select>
                                      <option disabled selected>Localização</option>
                                  </Form.Select>
                              </div>
                              <div className="mt-4">
                                  <Form.Select>
                                      <option disabled selected >Categoria</option>
                                  </Form.Select>
                              </div>
                              <div className="mt-4">
                                  <Form.Select>
                                      <option disabled selected >Ver tudo</option>
                                  </Form.Select>
                              </div>
                              <div className="mt-4 col">
                                  <button className="btn bg-main col-lg-12">Aplicar filtros</button>
                              </div>
                            </Form>
                       </div>
                       <AddsGenerator small />
                  </div>
             </div>
          </div>
       </Container>
     </div>
    )
  }

  
const Container = styled.div`
padding:100px 20px; 
width:100%;
min-height:100vh; 
background:var(--ed-background-color);   

.content{  
   display:flex; 
   width:100%;

   section{
    width:100%;
    padding-left:90px;

      .total-search{
        font-style: italic;
        color:var(--ed-grey-text);
      } 
   }
}

.notifications-container{
    width:100%; 
    border-radius:6px;   
    min-height:200px;
    background:var(--ed-white);  
    box-shadow:var(--ed-shadow-df);
    margin-bottom:20px; 
    padding:20px 0px;
 

    li.not-readed{
        background:#E2EAFC;
    }

    li{
        display:flex;
        padding:10px  20px;
        padding-bottom:20px;
        margin:10px 0px;
        border-bottom:1px solid  #eaeaee;

        b{
            margin:0px 3px;
        }

        .text-red{
            margin:0px 3px;
        }


        .bx .btn{
            border:1px solid var(--ed-purple-light) !important;
        }

        .ed-block{
            width:100%;

           .bx{
              background:var(--ed-background-color);   
              padding:10px;
              border-radius:6px;
           }

           .image-assets{
            width:max-content;

               .image{
                  width:150px;
                  height:110px; 
                  margin:2px 5px;
                  border-radius:6px;

                     img{
                        width:100%;
                        height:100%;
                        border-radius:6px;
                     }

               }
           }

           .video-box{
             max-width:350px;
             margin-top:10px;
             cursor:pointer;

            .video-poster{
                width:100%;
                height:200px;
                overflow:hidden; 
                position:relative;   
                border-radius:6px;          
  
               .video-box-over{
                   position:absolute;
                   top:0px;    
                   left:0px;
                   width:100%;
                   height:100%;
                   background:var(--ed-trp-1);
                   z-index:100;
                   border-radius:6px;
                   display:flex;
                   align-items:center;
                   justify-content:center;

                      .play-btn-box{
                         width:70px;
                         height:70px;
                         border-radius:100%;
                         background:rgba(255,255,255,0.5);
                         font-size:30px; 
                         display:flex;
                         align-items:center;
                         justify-content:center; 
                      }
                }
            }


           }

           .date{
              font-size:15px;
              color:var(--ed-grey-text);
           }

           .description{
              display:flex;
              flex-wrap:wrap;
           }
        }
    }

}


.filter-box{
    padding-left:40px;
    min-width:350px;
    width:400px; 

    .box{
        width:100%; 
        border-radius:6px;   
        min-height:200px;
        background:var(--ed-white);  
        box-shadow:var(--ed-shadow-df);
        margin-bottom:20px; 
        padding:20px;

          .title{
            position: relative;
            margin: 0px;
            width: max-content;
            font-size: 18px;
            color: var(--black);
            font-weight: bold; 

            svg{
                margin-right:10px;
                width:25px;
                height:25px;
            }
          }
    }

}





`;


export default NotifactionsMain