import React, {useState, useEffect} from 'react'
import Table from './Table';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import { Delete, Description, Edit ,OpenInBrowser, Refresh } from '@mui/icons-material';
import DeleteModal from '../elements/DeleteModal';
import NewCicleModal from '../modal/NewCicleModal';
import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import Avatar from "@mui/material/Avatar";
import AvatarGroup from "@mui/material/AvatarGroup";
import Tooltip from "@mui/material/Tooltip";
import moment from "moment";
import PopEmailMessageDetails from '../modal/PopEmailMessageDetails';

const TABLEURL = Hoot()+"eduallgetallsentemails/get/"
 
const columns = [  
  { field: 'index', headerName: 'Nº', width:70},
  {
    field: 'subject',
    headerName: 'Assunto',
    resizable: true,
  },
  {
    field: 'message',
    headerName: 'Mensagem',
    resizable: true,
    cellRenderer:(props) => { 
      return <PopEmailMessageDetails data={props.data}   toggle_btn={
        <div className="col-lg-12"> 
        <button className="btn bg-green col col-lg-12">Visualizar</button>
     </div>
     } />  ;
    }, 
  },
  {
    field: 'date',
    headerName: 'Data de envio',
    resizable: true,
  },
  {
    field: 'contacts',
    headerName: 'Contactos',
    resizable: true,
    width:300,
    cellRenderer:(props) => { 
      return  <div className="ed-flex"> 
        <div  style={{ border: "1px solid #ddd", padding: "10px", marginBottom: "10px", borderRadius: "8px" }}> 
            <AvatarGroup max={4} style={{ marginTop: "10px" }}>
                {props.data.contacts.map((contact, idx) => (
                    <Tooltip key={idx} title={contact.contact_name || "Unknown"}>
                        <Avatar className='df' src={Hoot()+contact.contact_picture || "/default-avatar.png"}>
                            {!contact.contact_picture ? contact.contact_name?.charAt(0) : ""}
                        </Avatar>
                    </Tooltip>
                ))}
            </AvatarGroup>
        </div> 
      </div>;
    }, 
  }, 
];


 
function SentEmailstable() {
    const [data, setData] = useState([]);  
    const [load, setLoaded] = useState(false);
    const [LoadStatus, setLoadStatus] = useState(null);
  
    async function loadData(){
     try {
       setLoadStatus(0); 
       setLoaded(false)
         const response = await axios.get(TABLEURL); 
         const rows = [];  
         response.data.map((item, index)=>{ 
           rows.push({
             subject:item.sent_subject,
             index:index+1,
             message:item.sent_message,
             date:moment(item.sent_date).locale("pt").format("dddd, D [de] MMMM [de] YYYY"),
             contacts:item.sent_to,
             action:'',  
          }) 
         }); 
         setData(rows); 
         setTimeout(() => {
           setLoaded(true);
         }, 200);
         setLoadStatus(2); 
     } catch (error) {
      console.clear()
      console.log(error);
      setLoadStatus(1); 
     }
    };
    
    useEffect(()=>{ 
        loadData();  
    },[]);
   
   
  
    if(load){
        return (
        <div>
          <TableGrid
              TableHead={columns}
              TableBody={data}  
              TableTitle='Emails enviados'
              TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
          />
      </div>
      )
    }else{
      return (
        <div>
          <div className="d-none">*</div>
          <TableGrid
                TableHead={columns}
                TableBody={[]} 
                TableTitle='Emails enviados'
                TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
            />
      </div>
      )
    }
}

export default SentEmailstable
