import React, { useState, useEffect } from 'react';
import { Email, Phone, LinkedIn, Facebook } from '@mui/icons-material';
import { Link } from 'react-router-dom';
import { Avatar } from '@mui/material';
import axios from 'axios';
import { Delete, Description, Edit } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import { PreviewOutlined } from '@mui/icons-material';
import styled from 'styled-components';
import ImageLazyLoading from '../../../General/components/ImageLazyLoading';
import NewVehicleModal from '../modal/NewVehicleModal';
import DeleteModal from '../elements/DeleteModal';

const TABLEURL = Hoot() + "edualltransportvehicleget/get/";

function VehiclesGrid({ searchTerm }) {
  const [data, setData] = useState([]);
  const [LoadStatus, setLoadStatus] = useState(null);
  const [load, setLoaded] = useState(false);

  async function loadData() {
    try {
      setLoadStatus(0);
      setLoaded(false);
      const response = await axios.get(TABLEURL);
      const rows = response.data.map((item, index) => ({
        index: index + 1,
        id: item.ed_transport_vehicle_id,
        model: item.ed_transport_vehicle_model,
        image: Hoot() + item.ed_transport_vehicle_picture,
        driver: item.ed_transport_driver_name,
        plate: item.ed_transport_vehicle_plate,
        capacity: item.ed_transport_vehicle_capacity,
        type: item.ed_transport_vehicle_typology === "rent" ? "Aluguel" : "Compra",
        vehiclevalue: item.ed_transport_vehicle_value,
        date: item.ed_transport_vehicle_acquisition_date,
      }));
      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoaded(true);
      setLoadStatus(1);
    }
  }

  useEffect(() => {
    loadData();
  }, []);

  const filteredData = data.filter(item =>
    item.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.plate.toLowerCase().includes(searchTerm.toLowerCase()) ||
    item.driver.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <Container>
      {filteredData.map((item, index) => (
        <Card key={index}>
          <div className="box">
            <div className="image">
              <ImageLazyLoading height={300} source={item.image} />
            </div>
          </div>
          <div className="details mt-2">
            <ul>
              <li>Modelo : <span>{item.model}</span></li>
              <li>Placa : <span>{item.plate}</span></li>
              <li>Motorista : <span>{item.driver}</span></li>
              <li>Capacidade : <span>{item.capacity}</span></li>
            </ul>
            <div className="ed-flex mt-2">
              <NewVehicleModal title='Atualizar' update='true' get={Hoot()+`edualltransportsinglevehicleget/get/${item.id}`}
                  url={Hoot() + `edualltransportvehicleupdate/update/${item.id}`} toggle_btn={
                      <button className="btn-circle bg-success text-light">
                          <Edit />
                      </button>
                  } />
              <DeleteModal title='este veiculo' url={Hoot()+`edualltransportvehicledelete/delete/${item.id}`}
                  message='Veiculo deletado com sucesso' toggle_btn={
                      <button className="btn-circle bg-danger ml-2 text-light">
                          <Delete />
                      </button>
                  } />
            </div>
          </div>
        </Card>
      ))}
    </Container>
  );
}

const Card = styled.article`
  padding:20px;
  margin:15px 0;
  border-radius:6px;
  background:var(--ed-white);
  height:430px;
  width:32.5%;
  box-shadow:var(--ed-shadow-df);

  ul{
     list-style:none;
     padding:0px;

     li{
        font-size:14.5px;
        margin-bottom:10px;

          span{
             font-size:12px;
             margin-top:7px;
             color:var(--ed-blue-dark);
          }
     }
  }

  .box{
    height:200px;
    min-width:100%;
    width:100%;
    border-radius:6px;
    position:relative;
    overflow:hidden;
    border:1px solid var(--ed-silver-light);

    .image{
        height:100%;
    }

    img{
        width:100%;
        height:100%;
        object-fit:contain;
    }

      .over{
         position:absolute;
         left:0px;
         width:100%;
         height:100%;
         background:var(--ed-trp-2);
         top:0px;
         padding:10px;

           h2{
               color:var(--ed-white);
               font-size:16px;
           }

          button{
             width:40px;
             height:40px;
              border-radius:100%;
                svg{
                   fill:var(--ed-white);
               }
            }
      }
  }

  @media screen and (max-width:1280px){
      width:33.3%;
      padding:10px;
      margin:15px 0px;
  }
`

const Container = styled.article`
     display:flex;
     flex-wrap:wrap;
     gap:15px;
`;

export default VehiclesGrid;
