import React, { useState } from 'react';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap';
import { Save, Update } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import { toast } from 'react-hot-toast';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import { GetInstituteCode } from '../../../General/components/InstituteData';
import RefreshList from '../../../General/components/RefreshList';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';

function NewProductCategoryModal(props) {
    const [show, setShow] = useState(false);
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [Founded, SetFounded] = useState(null);
    const [showBox, SetshowBox] = useState(false);
    const [form, setForm] = useState({});
    const [errors, setErrors] = useState({});

    const handleClose = () => {
        SetshowBox(false);
        setTimeout(() => {
            setShow(false);
        }, 1200);
    };

    const handleShow = () => {
        SetshowBox(true);
        setShow(true);
        setTimeout(() => {
            GET_DATA();
        }, 1000);
    };

    const FORMURL = [
        Hoot() + "eduallregisterproduct_category/post",
        props.get ? props.get : '',
        props.url ? props.url : ''
    ];

    const INPUTS = {
        product_category: CRValue("#product_category")
    };

    const GET_DATA = async () => {
        if (props.update) {
            try {
                const response = await axios.get(FORMURL[1]);
                if (response.data.length > 0) {
                    document.querySelector("#product_category").value = response.data[0].ed_product_category_name;
                    INPUTS.product_category = response.data[0].ed_product_category_name;
                } else {
                    toast.error("Não foi possível encontrar a informação selecionada!");
                }
            } catch (error) {
                toast.error("Não foi possível encontrar a informação selecionada!");
            }
        }
    };

    const setField = (field, value) => {
        setForm({ ...form, [field]: value });
        if (!!errors[field]) {
            setErrors({ ...errors, [field]: null });
        }
    };

    const validateForm = () => {
        const { product_category } = form;
        const NewErrors = {};
        setRegisterStatus(0);
        if (!product_category || product_category === '') NewErrors.product_category = 'Nome da categoria inválido!';
        return NewErrors;
    };

    const FormSubmit = (e) => {
        e.preventDefault();
        const formErrors = validateForm();
        if (Object.keys(formErrors).length > 0) {
            setErrors(formErrors);
            toast.error("Verifique todos os campos !");
            setRegisterStatus(1);
        } else {
            const SUBMIT_INPUTS = { product_category: INPUTS.product_category };
            if (!props.update) {
                try {
                    axios.post(FORMURL[0], SUBMIT_INPUTS).then(() => {
                        toast.success("Categoria registrada com sucesso!");
                        setForm({});
                        ClearInputs();
                        RefreshList(`.el-refresh-list`);
                        setRegisterStatus(2);
                    }).catch((error) => {
                        const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
                        toast.error(msg);
                        setRegisterStatus(1);
                    });
                } catch (error) {
                    const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
                    toast.error(msg);
                    setRegisterStatus(1);
                }
            } else {
                try {
                    axios.put(FORMURL[2], SUBMIT_INPUTS).then(() => {
                        toast.success("Categoria atualizada com sucesso !");
                        setForm({});
                        ClearInputs();
                        RefreshList(`.el-refresh-list`);
                        setRegisterStatus(2);
                        setTimeout(() => {handleClose();}, 1000);
                    }).catch((error) => {
                        const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
                        toast.error(msg);
                        setRegisterStatus(1);
                    });
                } catch (error) {
                    const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
                    toast.error(msg);
                    setRegisterStatus(1);
                }
            }
        }
    };

    const handleInput = (e) => {
        if (e.target.id === "product_category") {
            setField("product_category", e.target.value);
            INPUTS.product_category = e.target.value;
        }
    };

    return (
        <div>
            <div onClick={handleShow}>
                {props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon /> Registrar Categoria de produto</button>}
            </div>
            <Modal size='md' dialogAs={DraggableModal} centered className={showBox ? ModalAnimationShow() : ModalAnimationClose()} show={show} onHide={handleClose}>
                <Modal.Header closeButton>
                    <Modal.Title>
                        <div className="ed-wrap align-center">
                            <UserOptionDropDown />
                            <h5>{props.title ? props.title : 'Registrar '} Categoria de produto</h5>
                        </div>
                    </Modal.Title>
                </Modal.Header>
                <Form onSubmit={FormSubmit}>
                    <Modal.Body className='scrollLimit'>
                        <Form.Group className="mb-3">
                            <Form.Label>Nome<span className="text-danger ml-2">*</span></Form.Label>
                            <Form.Control type="text" required onChange={handleInput} className={!!errors.product_category && 'is-invalid'} value={form.product_category} isInvalid={!!errors.product_category} id="product_category" />
                            <Form.Control.Feedback type='invalid'>{errors.product_category}</Form.Control.Feedback>
                        </Form.Group>
                    </Modal.Body>
                    <Modal.Footer>
                        <Button className='bg-light text-dark' onClick={handleClose}>Cancelar</Button>
                        <SaveButton icon={props.update ? <Update /> : <Save />} title={props.update ? 'Atualizar' : 'Salvar'} status={RegisterStatus} />
                    </Modal.Footer>
                </Form>
            </Modal>
        </div>
    );
}

export default NewProductCategoryModal;