import React, {useState, useEffect} from 'react'
import axios from 'axios'
import { Delete, Description, Edit , PreviewOutlined, Refresh } from '@mui/icons-material'; 
import Hoot from '../../../General/components/Hoot'; 
import DeleteModal from '../elements/DeleteModal'; 
import TableGrid from '../../../General/components/TableGrid'; 
import RefreshButton from '../../../General/components/RefreshButton';
import ReplaceWord from '../../../General/components/ReplaceWord';
import NewAccountsPayableAndReceivableModal from '../modal/NewAccountsPayableAndReceivableModal';
import NumberToPrice from '../../../General/components/NumberToPrice';


const TABLEURL = Hoot()+"eduallgetaccounts_payable_and_receivable/get/";
const paymentMethods = [
  { value: "0", label: "Dinheiro a mão" },
  { value: "1", label: "Transferência" },
  { value: "2", label: "Depósito" },
  { value: "3", label: "TPA" }
];

const columns = [ 
  { field: 'index', headerName: 'Nº', width: 70,resizable: true },
  {
    field: 'description',
    headerName: 'Descrição',
    width:300,
    resizable: true,
  },  
  {
    field: 'suplierorclient',
    headerName: 'Cliente ou fornecedor',
    resizable: true, 
    width:230, 
  },
  {
    field: 'payable',
    headerName: 'Valor a pagar',
    width:200,
    editable: true 
  },
  {
    field: 'receivable',
    headerName:"Valor a receber",
     resizable: true,
     width:200, 
  }, 
  {
    field: 'action',
    headerName: 'Ação', 
    resizable: true,
    cellRenderer:(props) => {  
      return <div className="ed-flex">
          <NewAccountsPayableAndReceivableModal  title='Atualizar ' update='true' 
          get={Hoot()+`eduallgetsingleaccount_payable_and_receivable/get/${props.data.id}`}  
          url={Hoot()+`eduallaccount_payable_and_receivableupdate/update/${props.data.id}`}  toggle_btn={
          <button  className="btn-circle bg-success text-light">
              <Edit/>
          </button> 
          } />
          <DeleteModal title='esta conta' url={Hoot()+`eduallaccount_payable_and_receivabledelete/delete/${props.data.id}`} 
           message='Conta deletada com sucesso !' toggle_btn={
            <button  className="btn-circle bg-danger ml-2 text-light">
               <Delete/>
            </button> 
           }/> 
        </div> ;
    }
  } 
]; 

function PayableAndReceivableTable() {
  const [data, setData] = useState([]);  
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData(){
    try {
      setLoadStatus(0); 
      setLoaded(false);
        const response = await axios.get(TABLEURL); 
        const rows = []; 
        response.data.map((item, index)=>{  
          rows.push({
            index:index+1,
            id:item.ed_account_payable_receivable_id,
            description:item.ed_accounts_payable_and_receivable_description,  
            suplierorclient:item.ed_accounts_payable_and_receivable_client_or_supplier,  
            payable:NumberToPrice(item.ed_accounts_payable_and_receivable_amount_payable) + " "+ item.ed_coin_code, 
            receivable:NumberToPrice(item.ed_accounts_payable_and_receivable_amount_receivable) + " "+item.ed_coin_code, 
            paymentmethod:paymentMethods[item.ed_accounts_payable_and_receivable_payment_method],  
          })   
        }); 
        setData(rows); 
        setTimeout(() => {
          setLoaded(true);
        }, 200);
        setLoadStatus(2); 
    } catch (error) {
      setLoadStatus(1); 
    }
  };
  
  useEffect(()=>{ 
    loadData(); 
  },[]); 
 
 if(load){
  return (
    <div>
      <TableGrid 
          TableHead={columns}
          TableBody={data} 
          TableTitle='Contas a pagar e receber' 
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
      />
  </div>
  ) 
 }else{
  return (
    <div>
      <div className="d-none">*</div>
      <TableGrid 
          TableHead={columns}
          TableBody={[]} 
          TableTitle='Contas a pagar e receber'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
      />
  </div>
  ) 
 }
}
export default PayableAndReceivableTable;
