import React, { useEffect, useState } from 'react'
import { styled } from 'styled-components';
import ParentPortalSidebar from './Components/ParentPortalSidebar';
import UserNavbar from '../Components/UserNavbar';
import { Avatar } from '@mui/material';
import { Link, useParams } from 'react-router-dom';
import ReduceTextLength from '../../General/components/ReduceTextLength';
import PP_resume from './Pages/PP_resume';
import PP_attedance from './Pages/PP_attedance';
import PP_behavier from './Pages/PP_behavier';
import PP_calendar from './Pages/PP_calendar';
import PP_marks from './Pages/PP_marks';
import axios from 'axios';
import Hoot from '../../General/components/Hoot';
import moment from 'moment';
import NoData from '../../General/components/NoData';
import PP_classmates from './Pages/PP_classmates';
import Loader from '../../General/components/Loader';
import PP_payments from './Pages/PP_payments';
import PP_exams from './Pages/PP_exams';
import { BsArrowLeft } from 'react-icons/bs';

function ParentPortal({ userdata }) {
  document.title = "Portal do encarregado";
  const { CHILDID } = useParams();
  const [ActiveTab, setActiveTab] = useState(0);
  const [CurrentStudent, setCurrentStudent] = useState({});
  const [ActiveStudent, SetActiveStudent] = useState(null);
  const [Founded, setFounded] = useState(null);
  const [Loaded, setLoaded] = useState(false);
  const [StundentAttendance, setStundentAttendance] = useState([]);
  const [StundentExamsCalendar, setStundentExamsCalendar] = useState([]);
  const [StudentInstitute, setStudentInstitute] = useState({});
  const [Payments, SetPayments] = useState([]);
  const [ClassTimings, SetClassTimings] = useState([]);
  const [StudentBehaviorData, SetStudentBehaviorData] = useState([]);
  const [StudentExamsData, SetStudentExamsData] = useState([]);
  const [StudentAcademicYear, setStudentAcademicYear] = useState(null);

  const DATAURL = [
    Hoot() + "eduallgetallstudentattendance/get/",
    Hoot() + "eduallgetsingleinstitutebycode/get/",
    Hoot() + "eduallstudentexamcalendargetbyclass/get/",
    Hoot() + "eduallgetallstudentattendance/get/",
    Hoot() + "eduallupdatecurrentinstitutecode/post/",
    Hoot() + 'eduallsinglestudentfeepayment/get/',

    Hoot() + 'eduallsingleclassapi/get/',
    Hoot() + 'eduallgetclasstimings/get/',
    Hoot() + "eduallgetstudentbehaviorbystudentcode/get/",
    Hoot() + "eduallstudentexamcalendargetbyclass/get/"
  ];

  const LoadData = async (e) => {
    try {
      await axios.post(DATAURL[4] + e.ed_student_institute_code).then((a) => {
        const GetData = async () => {

          try {
            setStundentAttendance([]);
            const [response, response1, response2, response3, response5, response6, response7] = await Promise.all([
              axios.get(DATAURL[6] + e.ed_student_class),
              axios.get(DATAURL[0] + e.ed_student_id + "," + e.ed_student_class),
              axios.get(DATAURL[1] + e.ed_student_institute_code),
              axios.get(DATAURL[2] + e.ed_student_class),
              axios.get(DATAURL[7] + e.ed_student_class),
              axios.get(DATAURL[8] + e.ed_student_id),
              axios.get(DATAURL[9] + e.ed_student_class),
            ]);



            if (response.data.length >= 1) {
              const response4 = await axios.get(DATAURL[5] + e.ed_student_id + "," + response.data[0].ed_class_year);
              if (response4.data.length >= 1) {
                SetPayments(response4.data);
              }


              setStundentAttendance(response1.data);
              setStudentInstitute(response2.data.length >= 1 ? response2.data[0] : {});
              SetClassTimings(response5.data);
              setStudentAcademicYear(response.data[0].ed_class_year);
              SetStudentBehaviorData(response6.data);
              SetStudentExamsData(response7.data);

              console.clear();
              console.log(DATAURL[1] + e.ed_student_institute_code);
              console.log(response7.data);

              const rows = [];
              response3.data.map((item, index) => {
                rows.push({
                  title: item.ed_subject_title,
                  start: moment(item.ed_student_exam_date).format("YYYY-MM-DD HH:mm:ss"),
                  end: moment(item.ed_student_exam_date).format("YYYY-MM-DD HH:mm:ss"),
                })
              });
              setStundentExamsCalendar(rows);
              setCurrentStudent(e);
              setFounded(true);
              setLoaded(true);
            } else {

              console.clear();
              console.log("NOT FOUNDED 2", response3.data)
              setFounded(false);
              setLoaded(true);
            }
          } catch (error) {
            console.log(error);
            setFounded(false);
            setLoaded(true);
          }
        }
        GetData();
      }).catch((error) => {
        console.log(error);
        setFounded(false);
        setLoaded(true);
      });
    } catch (error) {
      console.log(error);
      setFounded(false);
      setLoaded(true);
    }
  }



  const GetData = (ID) => {
    setLoaded(false);
    SetActiveStudent(null);
    setCurrentStudent({});
    setStundentAttendance([]);
    SetPayments([]);
    SetClassTimings([]);
    SetStudentBehaviorData([]);
    const students = { codes: [], data: [] };
    if (userdata.user_childs && userdata.user_childs.length >= 1) {
      userdata.user_childs.map((item, index) => {
        students.codes.push(item.ed_student_id * 1);
        students.data.push(item)
      });
      if (students.codes.includes(ID * 1)) {
        for (let i = 0; i < students.data.length; i++) {
          if (students.data[i].ed_student_id * 1 === ID * 1) {
            LoadData(students.data[i]);
          } else {
            setFounded(false);
            console.clear();
            console.log("NOT FOUNDED 1")
          }
        }
      } else {
        LoadData(userdata.user_childs[0]);
      }
    } else {
      setFounded(false);
      console.clear();
      console.log("NOT FOUNDED 0")
    }
    SetActiveStudent(ID);
  }

  useEffect(() => {
    GetData(CHILDID);
  }, []);


  const Run = (e) => {
    setActiveTab(e);
  }


  if (Loaded) {
    if (Founded) {
      return (
        <div className='parent-portal-area'>
          <UserNavbar logoIndex={1} noquote data={userdata} menu={0} />
          <Container>
            <div className="wrapper">
              <br /><br />
              <div className="back-item ed-flex">
                <Link to="/WorkSpaces" className="ed-flex">
                  <div className="circle-icon text-main ed-flex ed-center"><BsArrowLeft /> </div>
                  <span className="text-dark">voltar para o inicio</span>
                </Link>
              </div>
              <div className="d-flex pareent-portal-flex">
                <ParentPortalSidebar ChangeStudent={GetData} ChangeTabPage={Run} ActiveStudent={ActiveStudent} ActiveTab={ActiveTab} data={userdata} />
                <Content className='parent-content' >
                  <div className="ed-wrapper">
                    <div>
                      {ActiveTab <= 4 ?
                        <div>
                          <Box>
                            <div className="box-content">
                              <div className="ed-flex ed-student-details parent-ed-student-details ">
                                <Avatar  className='df' src={Hoot() + CurrentStudent.ed_student_picture} sx={{ width: 130, height: 130 }} />
                                <div className="ed-block">
                                  <h1 className="name">{CurrentStudent.ed_student_name}</h1>
                                  <div className="code"><span>Nº de matricula : {CurrentStudent.ed_student_code}</span></div>
                                  <Link to={`#`} className="text-main">
                                    <div className="ed-institute ed-flex">
                                      <Avatar className='df'  variant="rounded" src={Hoot() + StudentInstitute.ed_institute_logo} sx={{ width: 30, height: 30 }} />
                                      <div className="ml-2 grey-text"><ReduceTextLength text={`${StudentInstitute.ed_institute_name}`} length="55" /></div>
                                    </div>
                                  </Link>
                                </div>
                              </div>
                            </div>
                          </Box>  
                          <ul className="box-content-tabs student-box-content-tabs">
                            <li className={`${ActiveTab === 0 ? "bg-main text-light" : ""}`} onClick={() => setActiveTab(0)}>Resumo</li>
                            <li className={`${ActiveTab === 1 ? "bg-main text-light" : ""}`} onClick={() => setActiveTab(1)}>Notas</li>
                            <li className={`${ActiveTab === 2 ? "bg-main text-light" : ""}`} onClick={() => setActiveTab(2)}>Presença escolar</li>
                            <li className={`${ActiveTab === 3 ? "bg-main text-light" : ""}`} onClick={() => setActiveTab(3)}>Comportamento</li>
                            <li className={`${ActiveTab === 4 ? "bg-main text-light" : ""}`} onClick={() => setActiveTab(4)}>Calendário de aulas</li>
                          </ul>
                        </div>
                        : <></>
                      }
                      {(ActiveStudent !== null && CurrentStudent !== null) ?
                        <div className="content-tabs mt-4">
                          <section className={`${ActiveTab === 0 ? "sec_tab active" : "sc_tab"}`}>
                            <PP_resume data={{ student: CurrentStudent, institute: StudentInstitute }} />
                          </section>
                          <section className={`${ActiveTab === 1 ? "sec_tab active" : "sc_tab"}`}>
                            <PP_marks data={{ student: CurrentStudent, institute: StudentInstitute }} />
                          </section>
                          <section className={`${ActiveTab === 2 ? "sec_tab active" : "sc_tab"}`}>
                            <PP_attedance data={{ Data: StundentAttendance }} />
                          </section>
                          <section className={`${ActiveTab === 3 ? "sec_tab active" : "sc_tab"}`}>
                            <PP_behavier data={StudentBehaviorData} />
                          </section>
                          <section className={`${ActiveTab === 4 ? "sec_tab active" : "sc_tab"}`}>
                            <PP_calendar data={ClassTimings} />
                          </section>
                          <section className={`${ActiveTab === 15 ? "sec_tab active" : "sc_tab"}`}>
                            <PP_classmates class={CurrentStudent.ed_student_class} />
                          </section>
                          <section className={`${ActiveTab === 6 ? "sec_tab active" : "sc_tab"}`}>
                            <PP_payments datacode={{ student: CurrentStudent.ed_student_id, academicyear: StudentAcademicYear, studentData: CurrentStudent }} data={{ Data: Payments }} />
                          </section>
                          <section className={`${ActiveTab === 9 ? "sec_tab active" : "sc_tab"}`}>
                            <PP_exams datacode={{ student: CurrentStudent.ed_student_id, academicyear: StudentAcademicYear }} data={StudentExamsData} />
                          </section>
                        </div>
                        : <></>}
                    </div>
                  </div>
                </Content>
              </div>
            </div>
          </Container>
        </div>
      );
    } else {
      return (
        <div>
          <UserNavbar logoIndex={1} noquote data={userdata} menu={0} />
          <Content>
            <NoData />
          </Content>
        </div>
      );
    }
  } else {
    return (
      <div>
        <UserNavbar logoIndex={1} noquote data={userdata} menu={0} />
        <Content>
          <Loader />
        </Content>
      </div>
    );
  }


}

const Container = styled.div`
  background:var(--ed-background-color);
  min-height:100vh; 
  width:100%;

  
   .box-content-tabs{
        padding:20px 0px;   
        padding-bottom:0px;  
        width:100%;  
        margin:0px;
        display:flex;
        align-items:center; 

         li{ 
            transition:all 1s ease-in-out;
            margin-right:20px;
            background:var(--ed-white);
            font-weight:500;
            cursor:pointer;
            color:var(--ed-dark);  
            padding:10px 20px; 
            border-radius:6px;
            cursor:pointer; 
            display:flex;
            align-items:center;
            box-shadow:var(--ed-shadow-df);
        }

     }

   .back-item {
        cursor:pointer; 
        font-weight:600;
        color:var(--dark);
        width:max-content;
        margin-bottom:20px;
        
        .circle-icon {
            border-radius:100%;
            background:var(--ed-white); 
            width:50px;
            height:50px;
            font-size:20px;
            margin-right:10px;
            box-shadow:var(--ed-shadow-df); 
         }
      }
`;

const Content = styled.div`
   display:block;
   padding:20px; 
   width:100%;
   padding-top:10px; 
   position:relative;

   
  &&::-webkit-scrollbar{
    width:6px !important;
    background-color:transparent !important;
  }
    
    &&::-webkit-scrollbar-thumb{
        background:rgb(219, 219, 219) !important; 
    }


   .ed-student-details{
           
     .code{
        margin:7px 0px; 
     } 
 

     .ed-block{
        margin-left:20px;
      }
    }
 


   .title, .name{
    font-size: 18px;
    font-weight: 600;
    margin: 0px;
   }

   .sc_tab{
       display:none;
    }

    .sc_tab.active{
        display:block !important;
    }

`;

const Box = styled.div`
    background:var(--ed-white); 
    border-radius:6px; 
    box-shadow:var(--ed-shadow-df);
    min-width:100px;

    .box-content{
          padding:20px;
    }
`;


export default ParentPortal
