import React from 'react'
import styled from 'styled-components';
import ImageLazyLoading from '../../../General/components/ImageLazyLoading';
import { Link } from 'react-router-dom';
import ReduceTextLength from '../../../General/components/ReduceTextLength';

function Profile_gn_latestprojects({data}) {
  return (
    <Container>
        <h1 className="title">Portofolio (5)</h1>
        <ul>
          {[1,2,3].map((item, index)=>{
             return(
                 <li key={index}>
                    <div className="image"><ImageLazyLoading source=""  height={200} /></div>
                    <div className="date">publicado 3 dias atras</div>
                    <Link to="#"><h6><ReduceTextLength text="Ui/Ux webapplication design com css html" length={30} /> </h6></Link>
                   <Link to="#"><button className="btn text-main">Saiba mais</button></Link>
                 </li>
             )
          })}
        </ul>
    </Container>
  )
}

const Container = styled.div`
   margin:10px 0px;

   ul{
      padding:0px;
      margin:0px;
      display:flex;

        li{
            margin-right:15px;
            width:325px;
            height:340px;
            border:1px solid var(--ed-silver-light);
            margin-top:10px;
            padding:10px;
            border-radius:6px;

            .date{
                font-size:15px;
                color:var(--ed-grey-text);
            }

            h6{
               font-size:16px;
               margin:5px 0px;
               color:var(--ed-dark);
               font-weight:600;
            }

            .image{
                border-radius:10px;
                overflow:hidden;
            }

              button{
                 background:transparent;
                 border-radius:30px;
                 margin-top:10px;
                 padding:7px 15px;
                 border:1px solid var(--ed-purple-light) !important;
              }


        }
   }
`;


export default Profile_gn_latestprojects
