import React, { useEffect, useState } from 'react'
import ImageLazyLoading from '../../components/ImageLazyLoading'
import moment from 'moment';
import TimeAgo from "javascript-time-ago";
import pt from "javascript-time-ago/locale/pt.json";
import ReactTimeAgo from 'react-time-ago'  
import { Avatar } from '@mui/material';
import Hoot from '../../components/Hoot';
import axios from 'axios';
import LinkPreviewComponent from '../../components/LinkPreviewComponent';

function ChatMessageBubbles(props){
  const [SetCurrentUser, CurrentUser] = useState({}); 
  const [searchField, setSearchField] = useState({});
  const [Data, setData] = useState([]); 
  const [load, setLoaded] = useState(false);   
  const URL = Hoot()+"eduallgetchatmessagesbycontact/get/";
  const socket = props.socket;
  let Code = props.chatuser.contact_id;


  const AudioAssets  =  [
       require("../../../Assets/audios/message_1.mp3"),
       require("../../../Assets/audios/message_2.mp3"),
  ];

  async function loadData(){
    setData([]);
    if(Code && Code !== null){
        try {
          setLoaded(false);
          const response = await axios.get(URL+Code); 
          const rows = [];
          console.log(response.data); 
          if(response.data.currentusercode*1 > 0){
               let user  = response.data.currentusercode*1;
               response.data.messages.map((msg, index)=>{
                  if(msg.ed_chat_message_from*1 === user){
                       rows.push(FetchMessage(msg));
                     }else{
                      rows.push(FetchMessage(msg));
                    }
               })
          }  
          setData(rows);
          setTimeout(() => {
             setLoaded(true);
             setTimeout(() => {
                scroolDown();
             }, 200);
          }, 200);
        } catch (error) {
          setLoaded(true);
        }
    } 
  };



 
useEffect(()=>{
  setSearchField(props.chatuser); 
  loadData();   
},[props]);


 
const FetchMessage  =  (msg)=>{
  return {
    message_user:msg.ed_chat_message_from*1 === Code ? 0  : 1,
    message_content:((msg.ed_chat_message_content !== null) && (msg.ed_chat_message_content.split("").length >= 1)) ? msg.ed_chat_message_content : null,
    message_gif:((msg.ed_chat_message_gif !== null) && (msg.ed_chat_message_gif.split("").length > 5)) ? msg.ed_chat_message_gif : null,
    message_time:moment(msg.ed_chat_message_registertime).format("YYYY-MM-DD HH:mm:ss"),
    message_username:msg.ed_user_account_name.split(" ")[0],
    message_userpicture:Hoot()+msg.ed_user_account_picture,
    message_files:[]
  }
}


const scroolDown = () =>{
    const elms = document.querySelectorAll(".messages-area"); 
     for (let i = 0; i < elms.length; i++) {
         const el =  elms[i];
         el.scrollTop =  el.scrollHeight; 
     }
  }
  
  var audio1 = new Audio(AudioAssets[0]);
  var audio2 = new Audio(AudioAssets[1]);

  const PlayAudio  =  (index)=>{
     if(index === 0){audio1.play();}else{audio2.play();}
  }


const GetRealTimeMessage =  (msg)=>{ 
  if(msg.ed_chat_message_to*1 === Code){
    let NewMessage  = {};  
   if(msg.ed_chat_message_from*1 !== Code) {
    //for the one that sent the message
      scroolDown();
      PlayAudio(0);
   }else{
    //for the one that receive the message
    PlayAudio(1);
   }
  if(msg !== null & msg !== undefined)   NewMessage = FetchMessage(msg); 
  setData([...Data, NewMessage]);
  }
} 


useEffect(() => { 
  socket.on('eduall_reponse_chat_messageIo', (data) => GetRealTimeMessage(data.message, data.user)); 
}, [socket, Data]);



  return (
    <div>
           <ul className="messages-area">
 

            {(load === true && Data.length <= 0) ? 
            <div className="ed-center ed-flex mt-4">
                <div className="empty-message mt-4">Não seja timido, inicie uma conversa</div>
             </div>
            : <></> } 
                {Data.map((msg, index)=>{
                  return(
                      <li key={index} className={msg.message_user === 1  ? "me" : "other"} >
                          <div className="msg-box">
                              <div className="msg-content">
                               <div className="d-flex">
                               <div className="avatar">
                                    {msg.message_user === 1  ? <></> : 
                                    <Avatar alt={msg.message_username} src={msg.message_userpicture} sx={{width:35,height:35}} />}    
                                </div>
                                  <div className="ed-block col">
                                    {msg.message_user === 1  ? <></> : <div className="name">{msg.message_username}</div>} 
                                    {msg.message_user === 1  ? <>
                                       <div className="ed-space col">
                                           <div></div>
                                           <div><div className="time"><ReactTimeAgo date={msg.message_time} locale="pt-PT"/></div></div>
                                       </div>
                                    </> : 
                                    <>
                                      <div className="time"><ReactTimeAgo date={msg.message_time} locale="pt-PT"/></div> 
                                    </> }   
                                  </div>
                                </div>
                                 {msg.message_content !== null ? <div> 
                                      <div className="content">
                                          <p> {msg.message_content} </p>
                                      </div>
                                   </div> : 
                                  <></>} 
                                  {msg.message_gif !== null ? <div className="gif-image mt-2"> 
                                       <ImageLazyLoading  height={200} source={msg.message_gif} alt="image_gif" />  
                                   </div> : <></>}
                                  <div className="msg-status"></div>
                              </div>
                          </div>
                      </li>
                    )
                })}

                
              <li className="me">
                <div className="msg-box">
                  <div className="msg-content">
                      <LinkPreviewComponent text={"Olá, dá uma olhada nesses links: https://openai.com mas não é so isso que temos https://eduall.ao"}   />
                  </div>
                </div>
              </li>

            </ul> 
    </div>
  )
}

export default ChatMessageBubbles