import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Delete, Edit } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal'; 
import TableGrid from '../../../General/components/TableGrid';
import RefreshButton from '../../../General/components/RefreshButton';
import NewLibraryBookColectionModal from '../modal/Library/NewLibraryBookColectionModal';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';

const TABLEURL = Hoot() + "edualllibrarycollectiongetall/get";

const columns = [
  { field: 'index', headerName: 'Nº', width: 90, resizable: true },
  { field: 'title', headerName: 'Coleção', resizable: true, width: 350 },
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true,
    cellRenderer: (props) => {
      return (
        <div className="ed-flex">
          <NewLibraryBookColectionModal
            title='Atualizar'
            update='true'
            get={Hoot() + `edualllibrarygetsinglecollection/get/${props.data.id}`}
            url={Hoot() + `edualllibraryupdatecollection/update/${props.data.id}`}
            toggle_btn={
              <button className="btn-circle bg-success text-light">
                <Edit />
              </button>
            }
          />
          <DeleteModal
            title='esta Coleção'
            url={Hoot() + `edualllibrarydeletecollection/delete/${props.data.id}`}
            message='Coleção deletada com sucesso'
            toggle_btn={
              <button className="btn-circle bg-danger ml-2 text-light">
                <Delete />
              </button>
            }
          />
        </div>
      );
    }
  }
];

function BookCollectionsTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData() {
    setLoadStatus(0);
    try {
      setLoaded(false);
      const response = await axios.get(TABLEURL);
      const rows = response.data.map((item, index) => ({
        index: index + 1,
        id: item.ed_library_collection_id,
        title: item.ed_library_collection_title,
        action: ""
      }));
      setData(rows);
      setTimeout(() => setLoaded(true), 200);
      setLoadStatus(2);
    } catch (error) {
      setLoadStatus(1);
      setLoaded(true);
    }
  }

  useEffect(() => {
    loadData();
  }, []);


  
if(load){
    return (
    <div id="ed-custom-table-data" >
      <TableGrid
          TableHead={columns}
          TableBody={data} 
          TableTitle='Lista das Coleções de Livros'
          TableBtn={
            <div className='ed-flex'>
              <button id='ed-custom-table-data-btn'
                onClick={() =>
                  ExportDataToTablesToPdf({
                    fileName: "Lista das Coleções de Livros",
                    headerId: null,
                    contentId: "ed-custom-table-data",
                    footerId: null,
                    rotation: "portrait",
                    buttonId: "ed-custom-table-data-btn",
                    customHeader: "Lista das Coleções de Livros",
                    excludedColumns: ["Ação"]
                  })
                }
                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
              </button>
              <button className='btn-icon btn btn-export-data ml-2'
                onClick={() => ExportDataForTablesExcel("Lista das Coleções de Livros", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
              </button>
              <RefreshButton action={loadData} status={LoadStatus} />
            </div>
          }
      />
  </div>
  )
}else{
  return (
    <div>
      <div className="d-none">*</div>
      <TableGrid
          TableHead={columns}
          TableBody={[]} 
          TableTitle='Lista das Coleções de Livros'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
      />
  </div>
  )
}  
}

export default BookCollectionsTable; 
