import React, { useState, useEffect } from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button, ListGroup } from 'react-bootstrap'
import { Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import { toast } from 'react-hot-toast';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import CourseDataOptions, { GetInstituteCode } from '../../../General/components/InstituteData';
import { SettingsApplicationsRounded, Update } from '@material-ui/icons';
import RefreshList from '../../../General/components/RefreshList';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import SendSmsAndEmailFunc from '../../../General/components/SendSmsAndEmailFunc';
import { FormControl, FormControlLabel, FormLabel, Radio, RadioGroup } from '@mui/material';

function SendEmailAndSmsModal(props) {
    const TYPE = props.type ? props.type*1 : 1;
    const [show, setShow] = useState(false);
    const [form, setForm] = useState({});
    const [errors, setErrors] = useState({});
    const Data = [];
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [Founded, SetFounded] = useState(null);
    const [sendType, SetsendType] = useState(TYPE);
    const [files, setFiles] = useState([]);

    const handleFileChange = (event) => {
        setFiles([...event.target.files]);
    };

    const [showBox, SetshowBox] = useState(false);
    const handleClose = () => {
        SetshowBox(false);
        setTimeout(() => {
            setShow(false);
        }, 1000);
    }

    const handleShow = () => {
        SetshowBox(true);
        setShow(true); 
    }; 
  

    const INPUTS = {
        message_title:CRValue("#message_title"),
        message_description:CRValue("#message_description"), 
    };

    const setField = (field, value) => {
        setForm({
            ...form,
            [field]: value
        })

        if (!!errors[field]) {
            setErrors({
                ...errors,
                [field]: null
            });
        }
    }


    const validateForm = () => {
        const { message_title, message_description } = form;
        const NewErrors = {}; 

       if (sendType > 1) {
         if (INPUTS.message_title === "" || INPUTS.message_title === " ") {
             if (!message_title || message_title === '') NewErrors.message_title = 'Assunto  invalido !';
         } else { if (!message_title) { setField("message_title", INPUTS.message_title); } }
       }

       if (INPUTS.message_description === "" || INPUTS.message_description === " " || INPUTS.message_description.split("").length < 5) {
        if (!message_description || message_description === '') NewErrors.message_description = 'Mensagem invalido !';
      } else { if (!message_description) { setField("message_description", INPUTS.message_description); } }

      if(props.contacts.length < 1){
           NewErrors.message_description = 'Adicione contactos para poder enviar a mensagem !';
       }

        return NewErrors;
    }


    const FormSubmit = (e) => {
        e.preventDefault();
        const formErrors = validateForm();
        if (Object.keys(formErrors).length > 0) {
            setErrors(formErrors);
            console.log(formErrors);
            toast.error("Verifique todos os  campos !"); 
        } else {
            SendSmsAndEmailFunc(props.contacts, INPUTS.message_description, INPUTS.message_title, files, sendType);
        }
    };


    const handleInput = (e) => {
        switch (e.target.id) {
            case "message_title":
                setField("message_title", e.target.value);
                INPUTS.message_title = e.target.value;
                break;
            case "message_description":
                setField("message_description", e.target.value);
                INPUTS.message_description = e.target.value;
                break; 
            default:
        }
    }



    return (
        <div>
            <div onClick={handleShow}>
                {
                    props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon /> Enviar mensagem </button>
                }
            </div>
            <Modal size='lg' centered className={showBox ? ModalAnimationShow() : ModalAnimationClose()} dialogAs={DraggableModal} show={show} onHide={handleClose}>
                <Modal.Header closeButton>
                    <Modal.Title>
                        <div className="ed-wrap align-center">
                            <UserOptionDropDown />
                            <h5> Enviar mensagem </h5>
                        </div>
                    </Modal.Title>
                </Modal.Header>
                <Form onSubmit={FormSubmit}>
                    <Modal.Body className='scrollLimit'> 
                        {sendType > 1 && (
                            <div>
                                <Form.Group className="mb-3">
                                    <Form.Label>Assunto<span className="text-danger ml-2">*</span> </Form.Label>
                                    <Form.Control type="text" onChange={handleInput} className={!!errors.message_title && 'is-invalid'} value={form.message_title}
                                        isInvalid={!!errors.message_title} id="message_title" />
                                    <Form.Control.Feedback type='invalid'>{errors.message_title}</Form.Control.Feedback>
                                </Form.Group>
                            </div>
                        )}
                        <Form.Group className="mb-3">
                            <Form.Label>Mensagem<span className="text-danger ml-2">*</span></Form.Label>
                            <Form.Control  as="textarea" rows={6}
                                onChange={handleInput}   className={!!errors.message_description && 'is-invalid'}
                                value={form.message_description} isInvalid={!!errors.message_description}    id="message_description"
                            />
                            <Form.Control.Feedback type="invalid">{errors.message_description}</Form.Control.Feedback>
                        </Form.Group> 
                        <div className="ed-block mb-2">
                            <FormLabel className='text-main' id="academic_level_forExam">Escolha uma das opções de envio : </FormLabel>
                            <RadioGroup aria-labelledby="academic_level_forExam" defaultValue={sendType}
                                name="radio-buttons-group" id="message_type" onChange={(e) => SetsendType(e.target.value * 1)}  >
                                <div className="mt-2 ed-flex">
                                    <FormControlLabel value="1" control={<Radio />} label="SmS" />
                                    <FormControlLabel value="2" control={<Radio />} label="Email" />
                                    <FormControlLabel value="3" control={<Radio />} label="SmS / Email" />
                                </div>
                            </RadioGroup> 
                        </div>
                        {sendType > 1 && (
                            <div>
                                <div className="mt-2">
                                    <Form.Group controlId="formFileMultiple" className="mb-3">
                                        <Form.Label>Escolha os seus arquivos</Form.Label>
                                        <Form.Control type="file" multiple onChange={handleFileChange} />
                                    </Form.Group>
                                </div>
                                {files.length > 0 && (
                                    <ListGroup className="mb-3">
                                        {files.map((file, index) => (
                                            <ListGroup.Item key={index}>{file.name}</ListGroup.Item>
                                        ))}
                                    </ListGroup>
                                )}
                            </div>
                        )}
                    </Modal.Body>
                    <Modal.Footer>
                        <div className="ed-space">
                            <div className="ed-flex"></div>
                            <div className="ed-flex">
                                <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                                {props.update ? (Founded === false ? <div></div> :
                                    <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Enviar'} status={RegisterStatus} />) :
                                    <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Enviar'} status={RegisterStatus} />}
                            </div>
                        </div>
                    </Modal.Footer>
                </Form>
            </Modal>
        </div>
    )
}

export default SendEmailAndSmsModal
