import React, { useState, useEffect } from 'react'
import { Avatar } from '@mui/material';
import Table from './Table';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import { GetAcademicYear_byclass, GetClasstitle_byclass, GetServiceWithPrice, GetServiceTitle, GetStudentName, GetStudentPicture } from '../../../General/components/InstituteData';
import { CheckCircleOutline } from '@material-ui/icons';
import NewEnrollmentConfirmationModal from '../modal/NewEnrollmentConfirmationModal';
import { Link } from 'react-router-dom';
import { Delete, Edit, PrintOutlined, Refresh } from '@mui/icons-material';
import DeleteModal from '../elements/DeleteModal';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import { flexbox } from '@mui/system';
import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import NumberToPrice from '../../../General/components/NumberToPrice';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';

const TABLEURL = Hoot() + "eduallenrollmentconfirmations/get";


const columns = [
  {
    field: 'code',
    headerName: 'Nº de matrícula',
    width: 180,
    resizable: true,
  },
  {
    field: 'name',
    headerName: 'Nome',
    width: 380,
    resizable: true,
    cellRenderer: (props) => {
      return <SwitchFromPages link={`studentinfo/${props.data.studentid}`}
        menu='3' menu_item='17' toggle_btn={
          <div className='ed-flex'>
            <Avatar className='df' alt={props.data.name} src={props.data.picture !== "" ? Hoot() + props.data.picture : ""} />
            <span className='ml-2'>{props.data.name}</span>
          </div>
        } />
    }
  },
  {
    field: 'class',
    headerName: 'Turma',
    resizable: true,
    width: 100,
  },
  {
    field: 'academicyear',
    headerName: 'Ano académico',
    resizable: true,
  },
  {
    field: 'service',
    headerName: 'Serviço (Valor para confirmação)',
    resizable: true,
    width: 360,
  },
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true,
    width: 230,
    cellRenderer: (props) => {
      return <div className="ed-flex">
        <NewEnrollmentConfirmationModal title='Atualizar ' studentCode={props.data.studentid}  confirmation update get={Hoot()+`eduallgetsingleenrollmentconfirmation/get/${props.data.id}`}  
          url={Hoot()+`eduallstudentenrollmentconfirmationupdate/update/${props.data.id}`} toggle_btn={
          <button className="btn-circle  bg-success text-light">
            <Edit />
          </button>} />
        <DeleteModal fullmessage title='Deseja cancelar esta confirmação de matrícula' url={Hoot() + `eduallenronllmentconfirmationdelete/delete/${props.data.id}`}
          message='Matrícula deletada com sucesso' toggle_btn={
            <button className="btn-circle bg-danger ml-2 text-light">
              <Delete />
            </button>} />
        <Link to={`/print_student_enrollment_confirmation/${props.data.id}`}>
          <button className="btn bg-warning btn-circle ml-2"><PrintOutlined /></button>
        </Link>
      </div>;
    }
  }
];




function StudentEnrollmentAndConfirmationTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData() {
    try {
      setLoadStatus(0);
      setLoaded(false);
      const response = await axios.get(TABLEURL);
      const rows = [];
      response.data.map((item, index) => {
        rows.push({
          id: item.ed_enrollment_confirmation_id, 
          studentid: item.ed_student_id,
          code: item.ed_student_code,
          picture: item.ed_student_picture,
          academicyear: item.ed_academic_year_title,
          name: item.ed_student_name,
          class: item.ed_class_title,
          service: item.ed_service_title + "( " + NumberToPrice(item.ed_service_price) + " " + item.ed_coin_code + ")",
          action: '',
        })
      });
      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoadStatus(1);
    }
  };

  useEffect(() => {
    loadData();
  }, []);


  if (load) {
    return (
      <div id="ed-custom-table-data">
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Confirmações de Matrícula'
          TableBtn={
            <div className='ed-flex' >
              <button id='ed-custom-table-data-btn'
                onClick={() =>
                  ExportDataToTablesToPdf({
                    fileName: "Lista das Confirmações de Matrícula",
                    headerId: null,
                    contentId: "ed-custom-table-data",
                    footerId: null,
                    rotation: "landscape",
                    buttonId: "ed-custom-table-data-btn",
                    customHeader: "Lista das Confirmações de Matrícula",
                    excludedColumns: ["Ação"]
                  })
                }
                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
              </button>
            <button className='btn-icon btn btn-export-data ml-2' 
               onClick={()=>ExportDataForTablesExcel("Lista das Confirmações de Matrícula", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
            </button>
           <RefreshButton action={loadData} status={LoadStatus} />
       </div>}
      /> 
      </div>
    )
  } else {
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={[]}
          TableTitle='Confirmações de Matrícula'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    )
  }

}

export default StudentEnrollmentAndConfirmationTable



