import React, { useEffect, useState } from 'react'
import Hoot from '../../General/components/Hoot'
import ReportFeedbackModal from '../../Dashboard/components/modal/ReportFeedbackModal'
import NotificationModal from '../../General/components/NotificationModal'
import UserModalMenu from '../../Dashboard/components/elements/UserModalMenu'
import axios from 'axios'
import TutorialLessonsModal from '../../General/components/TutorialLessonsModal'
import styled from 'styled-components'
const NoticationSound = require("../../Assets/audios/notify.wav");

function NavbarRH(props) {  
      const [Data, setData] = useState({});
      const [LicenceType, setLicenceType] = useState(null);
  
   
      const FORMURL = [
          Hoot() + "eduallupdateinstitute/update/",
          Hoot() + "eduallgetcurentuserinstitute/get/", 
      ];
  
      const GET_DATA = async () => {
          try {
              const response = await axios.get(FORMURL[1]);
              if (response.data.length > 0) {
                  setData(response.data[0]);
                  setLicenceType(response.data[0].ed_institute_licence_type * 1);
              }
          } catch (error) {
              console.log("error ************************************************");
              console.log(error);
              console.log("******************************************************");
          }
      } 
  
  
      useEffect(() => {
          GET_DATA();
      }, []);



  return (
    <NavbarContainer className='navbar-rh'>
      <div className="ed-space">
        <div className="ed-flex">

        </div>
        <div className="ed-nav-item ed-flex">
          <div className="mr-1">
            <ReportFeedbackModal />
          </div>
          <TutorialLessonsModal apiUrl={Hoot() + ""} />
          <div className="ed-icons">
            <div className="mr-2">
              <NotificationModal
                baseURL={Hoot()}
                currentUser={{
                  id: props?.userdata?.user_Information?.ed_user_account_id,
                  instituteCode: Data?.ed_institute_code,
                  name: props?.userdata?.user_Information?.ed_user_account_name,
                  avatar: Hoot() + props?.userdata?.user_Information?.ed_user_account_picture,
                }}
                notificationSoundUrl={NoticationSound}
              />
            </div>
          </div>
          <div className="ed-avatar">
            <div className="ed-flex ml-1">
              <UserModalMenu data={props.userdata} />
            </div>
          </div>
        </div>
      </div>
    </NavbarContainer>
  )
}

export default NavbarRH



