import React, { useState, useEffect, useRef } from 'react'
import Table from './Table';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import { Delete, Description, Edit, OpenInBrowser, Refresh } from '@mui/icons-material';
import DeleteModal from '../elements/DeleteModal';
import NewCicleModal from '../modal/NewCicleModal';
import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiMicrosoftExcelLogoDuotone } from "react-icons/pi";
import { TbPdf } from 'react-icons/tb';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import { PiFilePdfDuotone } from "react-icons/pi";

const TABLEURL = Hoot() + "eduallciclesapi/get/"

const columns = [
  { field: 'index', headerName: 'Nº', width: 90 },
  {
    field: 'title',
    headerName: 'Ciclo académico',
    resizable: true,
  },
  {
    field: 'code',
    headerName: 'Abreviação',
    resizable: true,
  },
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true,
    cellRenderer: (props) => {
      return <div className="ed-flex">
        <NewCicleModal title='Atualizar ' update='true' get={Hoot() + `eduallsinglecicle/get/${props.data.id}`}
          url={Hoot() + `eduallcicleupdate/update/${props.data.id}`}
          toggle_btn={
            <button className="btn-circle bg-success text-light">
              <Edit />
            </button>
          }
        />
        <DeleteModal title='este ciclo' url={Hoot() + `eduallcicledelete/delete/${props.data.id}`} message='Ciclo académico deletado com sucesso' toggle_btn={
          <button className="btn-circle bg-danger ml-2 text-light">
            <Delete />
          </button>} />
      </div>;
    }
  }
];




function CiclesTable() {
  const [data, setData] = useState([]);
  const [data1, setData1] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);


  async function loadData() {
    try {
      setLoadStatus(0);
      setLoaded(false)
      const response = await axios.get(TABLEURL);
      const rows = [];
      const rows1 = [];
      response.data.map((item, index) => {
        rows.push({
          id: item.ed_cicle_id,
          index: index + 1,
          title: item.ed_cicle_title,
          code: item.ed_cicle_code,
          action: '',
        })
        rows1.push({
          index: index + 1,
          title: item.ed_cicle_title,
          code: item.ed_cicle_code,
        })
      });
      setData(rows);
      setData1(rows1);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoadStatus(1);
    }
  };

  useEffect(() => {
    loadData();
  }, []);



  if (load) {
    return (
      <div id='ed-custom-table-data'>
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Ciclos acadêmicos'
          TableBtn={
            <div className='ed-flex' >
              <button id='ed-custom-table-data-btn'
                onClick={() =>
                  ExportDataToTablesToPdf({
                    fileName: "ciclos",
                    headerId: null,
                    contentId: "ed-custom-table-data",
                    footerId: null,
                    rotation: "portrait",
                    buttonId: "ed-custom-table-data-btn",
                    customHeader: "Ciclos acadêmicos",
                    excludedColumns:["Ação"]
                  })
                }
                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
              </button>
              <button className='btn-icon btn btn-export-data ml-2'
                onClick={() => ExportDataForTablesExcel("Ciclos académicos", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
              </button>
              <RefreshButton action={loadData} status={LoadStatus} />
            </div>
          }
        />
      </div>
    )
  } else {
    return (
      <div id='ed-cicles-table-data' >
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={[]}
          TableTitle='Ciclos acadêmicos'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    )
  }


}

export default CiclesTable