import { requirePropFactory } from '@material-ui/core';
import React from 'react'
import { Link } from 'react-router-dom';
import styled from 'styled-components'
import AddsGenerator from './AddsGenerator';
import TitleBlock from './TitleBlock';
import FriendBox from '../Students/Components/FriendBox';
import StudentDebtsTable from '../Students/Components/StudentDebtsTable';
import TaskBox from '../Students/Components/TaskBox';
import { Avatar } from '@mui/material';
import Hoot from '../../General/components/Hoot';
import ReduceTextLength from '../../General/components/ReduceTextLength';
import { Swiper, SwiperSlide } from 'swiper/react'; 

const Tasks = [
   {title:'Tarefa de matematica',date:'12-02-2022',color:'#eafff6',link:"#"},
   {title:'Projeto de geometria',date:'01-10-2022',color:'#ffeeee', link:"#"},
   {title:'Quimica quantica',date:'04-09-2022',color:'#fff1e6',link:"#"}
];
 
const Friends = [
    {name:'José Martins', link:'', img:require('../../Assets/images/avatars/avatar-3.jpg')},
    {name:'Pedro Kyle', link:'', img:require('../../Assets/images/avatars/avatar-4.jpg')},
    {name:'Sara Lopes', link:'', img:require('../../Assets/images/avatars/avatar-5.jpg')},
    {name:'Carla Solange', link:'', img:require('../../Assets/images/avatars/avatar-6.jpg')},
];


function MenuRight(props) {
  return (
  <Container className='sd-right'>
    <div className={!props.relative ? 'container-el abs' : 'container-el'}>
      <Content> 
        <div className="mt-4">
            <ul>
              <TitleBlock title="Patrocinados"/>
              <AddsGenerator single margin small text='left' />
            </ul>
        </div>
        <div className={props.data.user_student_accounts.length >= 1 ? "mt-4" : "d-none"} >
           <ul className='students' >
           <div className="mb-3">
              <TitleBlock nomargin  title='Contas de estudante' maintext={props.data.user_student_accounts.length} />
           </div>
           <Swiper  Autoplay={true}  spaceBetween={10}  slidesPerView={props.data.user_student_accounts.length > 1  ? 1.1 : 1 } onSlideChange={() => console.log('slide change')}  onSwiper={(swiper) => console.log(swiper)} >
                 {props.data.user_student_accounts.map((item, index)=>{
                    return( <SwiperSlide key={index} > 
                       <li>
                        <Link to={`student_portal/${item.ed_student_id}`} >
                          <div className="avatar-box">
                            <Avatar  src={Hoot()+item.ed_student_picture} sx={{width:45,height:45}} alt={item.ed_student_name}  />
                            <div className="status"></div>
                          </div>
                          </Link> 
                          <div className="block">
                            <Link to={`student_portal/${item.ed_student_id}`} >
                                  <div className="name ml-2"><ReduceTextLength text={item.ed_student_name} length="20" /></div>
                              </Link> 
                              <Link to={`institute_blog/${item.ed_institute_code}`}>
                                <div className="ed-flex ml-2 mt-1">
                                  <Avatar variant="rounded"  src={Hoot()+item.ed_institute_logo} sx={{width:20,height:20}}  />
                                  <small className="grey-text ml-2">
                                    <ReduceTextLength text={item.ed_institute_name} length="20"  />
                                  </small>
                                </div>
                              </Link>
                          </div>
                        </li>  
                    </SwiperSlide>)  
                 })} 
              </Swiper>  
           </ul>
        </div>
          <div className="mt-4"> 
              <ul>
              <TitleBlock title='Trabalhos pendentes'/>
                  {
                      Tasks.map((item, index)=>{
                          return(
                              <TaskBox key={index} props={item} />
                          )
                      })
                  }
            </ul>
          </div>
          <ul>
            <TitleBlock title='Mensagens'/>
              {
                  Friends.map((item, index)=>{
                      return(
                          <FriendBox key={index} props={item} />
                      )
                  })
              }
          </ul>
          <ul>
              <TitleBlock title='Pagamentos pendentes'/>
                <StudentDebtsTable/>
                <br />
          </ul>
      </Content>
    </div>
  </Container>
  )
}


const Content = styled.div`
   width:100%;
   border-bottom;
   max-height:78vh; 
   overflow-y:auto; 

   @media screen and (max-width:1350px){
      padding-right:5px;

      ul{
          padding:10px 0px;
      }
  }

   ul{
     padding:10px 20px;
     border-bottom:1px solid  #eaeaee;
   }


    &&::-webkit-scrollbar{
     width:6px;
     background-color:transparent;
   }

   &&:hover{ 
    &&::-webkit-scrollbar-thumb{
       background:rgb(219, 219, 219); 
    }
  }
`;

const Container = styled.div`  
padding-top:100px;   

.container-el{ 
   width:100%;
   min-width:340px;
   max-width:340px;
   height:80vh;
   background:var(--ed-white); 
   border-radius:10px;
   box-shadow:var(--ed-shadow-df); 
   position:relative;
}


ul.students{
 margin:20px 0px;
 padding:10px 20px;
   

   li{
     margin:12px 0px;
     font-size:15px;
     color:var(--ed-blue-dark);
     border:1px solid #eaeaee;
     display:flex;
     padding:10px;
     border-radius:6px;

        .name{
           color:var(--ed-dark);
        }
   }
}



 
`;

export default MenuRight