import * as React from 'react';
import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Typography from '@mui/material/Typography';
import Modal from '@mui/material/Modal';
import styled from "styled-components";
import { Avatar, AvatarGroup } from '@mui/material';
import Hoot from '../../../../General/components/Hoot';

const style = {
  position: 'absolute',
  top: '50%',
  left: '50%',
  transform: 'translate(-50%, -50%)',
  width:"100%", 
  bgcolor: 'background.paper',
  border: '2px solid #000',
  boxShadow: 24,
  p:0,
};

function Comp_videoIntro(props){
  const [open, setOpen] = React.useState(false);
  const handleOpen = () => setOpen(true);
  const handleClose = () => setOpen(false);

  return (
    <div>
      <div onClick={handleOpen}> {props.toggle_btn} </div>
      <Modal  open={open}  onClose={handleClose}  aria-labelledby="modal-modal-title" aria-describedby="modal-modal-description">
        <Box sx={style}>
           <Container>
               <div className="container-header">
                   <div className="ed-wrapper">
                       <div className="ed-space">
                       <div className="ed-flex mt-2">
                          <Avatar  variant="square" sx={{width:80,height:80}} src={Hoot()+props.data.ed_page_logo}  />
                          <div className="ed-block ml-2">
                               <h1>{props.data.ed_page_name}</h1>
                               <span>{props.data.ed_page_slogan}</span>
                          </div>
                       </div>
                          <div>
                              <button onClick={handleClose}>x</button>
                          </div>
                       </div>
                   </div>
               </div>
               <div className="container-body ed-flex ed-center">
                   <iframe  height="660" src={props.data.ed_page_video} title="YouTube video player" frameborder="0"
                   allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>
                  <br /> 
               </div>
           </Container>
        </Box>
      </Modal>
    </div>
  )
}


const Container = styled.div`
    min-height:200px;

    .container-header{
        min-height:60px;
        border-bottom:1px solid var(--ed-silver-light);
        margin-bottom:20px;
        padding:10px 20px;


         h1{
             font-size:18px;
             font-weight:600;
             margin:0px;
             margin-bottom:5px;
         }

         span{
             font-size:15px;
             color:var(--ed-grey-text);
         }
    }

    .container-body{
        background:black;
        width:100%;
        min-height:400px;
        margin-bottom:50px;

          iframe{
            width:100%;
              max-width:950px;
          }
    }
`;


export default Comp_videoIntro