import React, { useEffect, useState } from 'react'
import { Avatar } from '@mui/material'; 
import CommentReactions from './CommentReactions';
import CommentsToggle from '../CommentsToggle';
import Hoot from '../Hoot';
import axios from 'axios';
import ImageLazyLoading from '../ImageLazyLoading';
import TimeAgo from "javascript-time-ago";
import pt from "javascript-time-ago/locale/pt.json";
import ReactTimeAgo from 'react-time-ago'  

function CommentSubReply({id, socket, total}){
  const [load, setLoaded] = useState(false); 
  const [CommentsData , SetCommentsData] = useState([]); 
  const URL =  Hoot()+"eduallgetCommentssubrepliesbyid/"+id;

  async function loadData(){
    if(id !== null){
      try {
        setLoaded(false);  
        const response = await axios.get(URL);  
        SetCommentsData(response.data);
        //total(response.data.length);   
        setLoaded(true);  
      } catch (error) {
        setLoaded(false);  
      }
    } 
}

  const GetRealTimeData =  (data)=>{  
      console.log(data, id);
      if(data !== null && data !== undefined){
        if((data.ed_comment_subreplie_replieID*1 === id*1)){ 
          if(data !== null & data !== undefined){
            SetCommentsData([...CommentsData, data]);
            setTimeout(() => { 
              //total(CommentsData.length);  
            }, 1000);
          };
        } 
      }
    } 
      
    
    useEffect(() => { 
      socket.on('eduall_response_content_commentssubreplies', (data) => GetRealTimeData(data.data, data.user)); 
    }, [socket, CommentsData]);
    
                
    useEffect(()=>{ 
      loadData() 
    },[]);
    
    useEffect(()=>{ 
      setTimeout(() => {
          CommentsToggle();
      }, 1500);
    },[id]);
  
  return (
    <div>
       {CommentsData.map((item, index)=>{
         return(
            <div className='comment-sub-reply'>
            <div className="d-flex">
           <div className="ed-flex  ed-ln">
                 <Avatar className='df' src={Hoot()+item.ed_user_account_picture} sx={{width:40,height:40}} />
                 <div className="line"></div>
             </div>
             <div className="ed-block"> 
             <div className="comment-box">
                 <div className="flex">
             
                 <div className="ed-block">
                 <div className="ed-space">
                     <div className="name">{item.ed_user_account_name}</div>
                     <div className="time">
                      {(item.ed_comment_subreplie_registerDate !== null && item.ed_comment_subreplie_registerDate !== undefined ) ? 
                      <ReactTimeAgo date={item.ed_comment_subreplie_registerDate} locale="pt-PT"/> : ""} 
                    </div>
                 </div>
                 <div className="content">
                         <div className="text-box">{item.ed_comment_subreplie_text}</div>
                        <div className='ed-flex'>
                           {item.ed_comment_subreplie_image !== "" ?   <div className="image mr-2"><ImageLazyLoading source={Hoot()+item.ed_comment_subreplie_image} /></div> : <></>}
                           {item.ed_comment_subreplie_gif !== "" ?   <div className="image mr-2"><ImageLazyLoading source={item.ed_comment_subreplie_gif} /></div> : <></>}
                        </div>
                       </div>
                 <div className="ed-flex">
                     <CommentReactions type={3} url="eduall_send_content_commentsubrepliesIo" socket={socket}  id={item.ed_comment_subreplie_id}  no />  
                 </div>
                 </div>
                 <div className="toggle-reaction">
                     
                     </div>
                 </div> 
                 </div>  
            </div> 
           </div> 
         </div>)
       })}
    </div>
  )
}

export default CommentSubReply