import { AddCircleOutline, PrintOutlined, Search } from '@mui/icons-material';
import React, { useEffect, useRef, useState } from 'react'
import { Form, Table } from 'react-bootstrap';
import { Link } from 'react-router-dom';
import { ClassDataOptions, GetAcademiclevel_byclass, GetAcademicYear_byclass, GetClassroom_byclass, GetClasstitle_byclass, GetCourse_byclass, GetPeriod_byclass, GetSubject, SubjectDataOptions } from '../../../General/components/InstituteData';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import PdMiniguidelinestable from '../../components/Table/PdMiniguidelinestable';
import DashboardContainerWrapper from '../../components/elements/DashboardContainerWrapper';
import CRValue from '../../../General/components/CRValue';
import CustomTableContainer from '../../components/elements/CustomTableContainer';
import Print_pdminiguideline from '../../components/Reports/Print_pdminiguideline';
import ReplaceWord from '../../../General/components/ReplaceWord';
import ExportCustomTablesDataToExcel from "../../../General/components/ExportCustomTablesDataToExcel";
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import ExportPdTablesToExcel from '../../../General/components/ExportPdTablesToExcel';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';

function Pdminiguidelines() {
   document.title = "Mini pautas";
   const [CurrentClass, SetCurrentClass] = useState(null);
   const [CurrentSubject, SetCurrentSubject] = useState(0);

   const ChildRef = useRef();

   const Run = (e, t) => {
      if (t === "c") {
         if (e * 1 > 0) {
            console.log("here we go - " + e);
            SetCurrentClass(e);
            setTimeout(() => {
               ChildRef.current.RunGetNotes();
            }, 500);
         }
      } else {
         SetCurrentSubject(e);
         setTimeout(() => {
            if (CurrentSubject !== null) {
               ChildRef.current.RunGetNotes();
            } else {
               SetCurrentSubject(e);
               ChildRef.current.RunGetNotes();
            }
         }, 500);
      }
   }

   const ChangeClass = (e) => {
      Run(e.target.value, "c");
   }

   const ChangeSubject = (e) => {
      ;
      Run(e.target.value, "s");
   }


   useEffect(() => {
      console.clear();
      console.log(CRValue("#get-selector-class2"));
   }, []);

   return (
      <DashboardContainerWrapper content={
         <div>
            <div className="ed-space">
               <div>
                  <Form>
                     <div className='search-box'>
                        <Form.Group>
                           <div className="ed-flex">
                              <Search />
                              <div className="block ml-2 col-lg-6">
                                 <Form.Select id="get-selector-subject2" select onChange={(e) => ChangeSubject(e)}>
                                    <SubjectDataOptions />
                                 </Form.Select>
                              </div>
                              <div className="block ml-2">
                                 <Form.Select id="get-selector-class2" onChange={(e) => ChangeClass(e)}>
                                    <ClassDataOptions />
                                 </Form.Select>
                              </div>
                           </div>
                        </Form.Group>
                     </div>
                  </Form>
               </div>
               <div className="ed-flex" >
                  <button onClick={() => ExportPdTablesToExcel(["detailspdtable", "PdMiniguidelinestable"], `Mini pautas ( ${ReplaceWord("Disciplina")} / Turma )`)}
                     className='btn btn-export-data bg-white'><PiMicrosoftExcelLogoDuotone /> Exportar em excel
                  </button> 
                  <div className="d-none">
                  <button id='ed-custom-table-data-btn'
                     onClick={() =>
                        ExportDataToTablesToPdf({
                           fileName: "Mini pautas",
                           headerId: null,
                           contentId: "ed-custom-table-data",
                           footerId: null,
                           rotation: "portrait",
                           buttonId: "ed-custom-table-data-btn",
                           customHeader: "Mini pautas",
                           excludedColumns: ["Ação"]
                        })
                     }
                     className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone /> <span className="ml-1">Exportar em pdf</span>
                  </button>
                  </div>
               </div>
            </div>
            <CustomTableContainer title="Mini pautas" content={<div id="ed-custom-table-data">
               <div className="ed-table-container"  >
                  <div>
                     <Table responsive bordered id='detailspdtable' >
                        <tbody>
                           <tr>
                              <td>
                                 <div className="ed-space">
                                    <div><strong>Sala</strong></div>
                                    <div>{(CurrentClass !== null && CurrentClass * 1 !== NaN) ? <GetClassroom_byclass ID={CurrentClass} /> : <></>} </div>
                                 </div>
                              </td>
                              <td>
                                 <div className="ed-space">
                                    <div><strong>Turma</strong></div>
                                    <div> {(CurrentClass !== null && CurrentClass * 1 !== NaN) ? <GetClasstitle_byclass ID={CurrentClass} /> : <></>} </div>
                                 </div>
                              </td>
                              <td>
                                 <div className="ed-space">
                                    <div><strong>{ReplaceWord("Classe")}</strong></div>
                                    <div> {(CurrentClass !== null && CurrentClass * 1 !== NaN) ? <GetAcademiclevel_byclass ID={CurrentClass} /> : <></>} </div>
                                 </div>
                              </td>
                           </tr>
                           <tr>
                              <td>
                                 <div className="ed-space">
                                    <div><strong>Período</strong></div>
                                    <div> {(CurrentClass !== null && CurrentClass * 1 !== NaN) ? <GetPeriod_byclass ID={CurrentClass} /> : <></>} </div>
                                 </div>
                              </td>
                              <td>
                                 <div className="ed-space">
                                    <div><strong>Ano letivo</strong></div>
                                    <div> {(CurrentClass !== null && CurrentClass * 1 !== NaN) ? <GetAcademicYear_byclass ID={CurrentClass} /> : <></>} </div>
                                 </div>
                              </td>
                              <td>
                                 <div className="ed-space">
                                    <div><strong>Curso</strong></div>
                                    <div>{(CurrentClass !== null && CurrentClass * 1 !== NaN) ? <GetCourse_byclass ID={CurrentClass} /> : <></>} </div>
                                 </div>
                              </td>
                           </tr>
                           <tr>
                              <td colSpan={3} rowSpan={1}>
                                 <div className="ed-space">
                                    <div><strong>{ReplaceWord("Disciplina")}</strong></div>
                                    <div><GetSubject ID={CurrentSubject} /> </div>
                                 </div>
                              </td>
                           </tr>
                        </tbody>
                     </Table>
                  </div>
               </div>
               <div className="eduall-table" >
                  <div className="ed-table-container">
                     {(CurrentClass * 1 !== NaN) ? <PdMiniguidelinestable ref={ChildRef}
                        Filters={{ subject: CurrentSubject, class: CurrentClass * 1 !== NaN }} ClassId={CurrentClass} /> : <></>}
                  </div>
               </div>
            </div>} />
         </div>
      } />
   )
}




export default Pdminiguidelines


