import React, { useState } from 'react';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap';
import { Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import { toast } from 'react-hot-toast';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import RefreshList from '../../../General/components/RefreshList';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import { EmployeesDataOptions } from '../../../General/components/InstituteData'; 
import GetPersonData from '../../../General/components/GetPersonData';
import CreateTemporaryEduallAccountAlert from './CreateTemporaryEduallAccountAlert'; 

function NewTeacherAccountModal(props) {
  const [show, setShow] = useState(false);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});
  const [UserData, setUserData] = useState({ name: "", gender: "" });

  const [showBox, SetshowBox] = useState(false);
  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200);
  }

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };




  const setField = (field, value) => {
    setForm({ ...form, [field]: value });
    if (!!errors[field]) setErrors({ ...errors, [field]: null });
  };

  const INPUTS = {
    email: CRValue("#email"),
    employeeId: CRValue("#employeeId")
  };


  const GET_DATA = async () => {
    if (props.update) {
      try {
        const response = await axios.get(FORMURL[1]);
        if (response.data.length > 0) {
          document.querySelector("#email").value = response.data[0].ed_user_account_email;
          document.querySelector("#employeeId").value = response.data[0].ed_user_institute_employeeCode;

          setField("email", response.data[0].ed_user_account_email);
          setField("employeeId", response.data[0].ed_user_institute_employeeCode);

          INPUTS.email = response.data[0].ed_user_account_email;
          INPUTS.employeeId = document.querySelector("#employeeId").value = response.data[0].ed_user_institute_employeeCode;

        } else {
          toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
        }
      } catch (error) {
        toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
      }
    }
  }


  const FORMURL = [
    Hoot() + "eduallregisteruserinstitutes/post",
    props.get ? props.get : '',
    props.url ? props.url : ''
  ];


  const validateForm = () => {
    const { email, employeeId } = form;
    const newErrors = {};
    setRegisterStatus(0);
    if (!email || email === '') newErrors.email = 'Email inválido!';
    if (!employeeId || employeeId === '') newErrors.employeeId = 'Funcionário inválido!';
    return newErrors;
  };

  const FormSubmit = async (e) => {
    e.preventDefault();
    const formErrors = validateForm();

    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os campos");
      setRegisterStatus(1);
    } else {
      const SUBMIT_INPUTS = {
        email: INPUTS.email,
        employeeId: INPUTS.employeeId
      };

      try {
        if (!props.update) {
          await axios.post(FORMURL[0], SUBMIT_INPUTS);
          toast.success("Conta registrada com sucesso!");
        } else {
          await axios.put(FORMURL[2], form);
          toast.success("Conta atualizada com sucesso!");
        }
        setForm({});
        ClearInputs();
        RefreshList(`.el-refresh-list`);
        setRegisterStatus(2);
        setTimeout(() => handleClose(), 1500);
      } catch (error) {
        const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
        toast.error(msg);
        setRegisterStatus(1);
      }


    }
  };


 

  const handleInput = async (e) => {
    const { id, value } = e.target;
    setField(id === "email" ? "email" : "employeeId", value);
    INPUTS[id] = value;

    if (id === "employeeId" && value) { 
      const data = await GetPersonData(value, "employee");
      setUserData(data);
    }
  };

  return (
    <div>
      <div onClick={handleShow}>
        {props.toggle_btn ? props.toggle_btn : (
          <button className='btn btn-main bg-main'><AddCircleOutlineIcon /> Registrar conta do professor</button>
        )}
      </div>

      <Modal
        size='lg'
        dialogAs={DraggableModal}
        centered
        className={showBox ? ModalAnimationShow() : ModalAnimationClose()}
        show={show}
        onHide={handleClose}
      >
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>{props.title ? props.title : 'Registrar'} Conta de Professor</h5>
            </div>
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={FormSubmit}> 
          <Modal.Body className='scrollLimit'>  
            <Form.Group className="mb-3">
              <Form.Label>Funcionário<span className="text-danger ml-2">*</span></Form.Label>
              <Form.Select type="text" required id="employeeId" value={form.employeeId} onChange={handleInput} className={!!errors.employeeId && 'is-invalid'} isInvalid={!!errors.employeeId} >
                <EmployeesDataOptions />
              </Form.Select>
              <Form.Control.Feedback type='invalid'>{errors.employeeId}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3">
              <Form.Label>Email de Utilizador<span className="text-danger ml-2">*</span></Form.Label>
              <Form.Control required type="email" id="email" value={form.email} onChange={handleInput} className={!!errors.email && 'is-invalid'} isInvalid={!!errors.email} />
              <Form.Control.Feedback type='invalid'>{errors.email}</Form.Control.Feedback>
            </Form.Group> 
          <CreateTemporaryEduallAccountAlert
            email={form.email}
            userName={UserData.name}
            country="ao"  
            gender={UserData.gender}
          />
          </Modal.Body>
          <Modal.Footer>
            <div className="ed-space">
              <div className="ed-flex"></div>
              <div className="ed-flex">
                <Button className='bg-light text-dark' onClick={handleClose}>Cancelar</Button>
                <SaveButton icon={<Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />
              </div>
            </div>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  );
}

export default NewTeacherAccountModal;
 