
import React , {useState, useEffect} from 'react' 
import axios from 'axios'
import Hoot from '../../../General/components/Hoot';
import { Delete,  Edit, Refresh  } from '@mui/icons-material';
import DeleteModal from '../elements/DeleteModal';
import NewYearModal from '../modal/NewYearModal';
import TableGrid from '../../../General/components/TableGrid';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';

const TABLEURL = Hoot()+"eduallacademicyearapi/get/"


const columns = [ 
    { 
     field: 'index',
     headerName: 'Nº', 
     width: 90 , 
     resizable: true, 
    },
    { 
        field: 'title',
        headerName: 'Ano académico',  
        resizable: true, 
    }, 
     { 
      field: 'start',
      headerName: 'Data de inicialização',  
      resizable: true, 
     },  
     { 
        field: 'end',
        headerName: 'Data de finalização',  
        resizable: true, 
    },
    {
      field: 'action',
      headerName: 'Ação',  
       resizable: true, 
       cellRenderer:(props) => { 
        return  <div className="ed-flex">
        <NewYearModal title='Atualizar ' update='true' get={Hoot()+`eduallsingleacademicyearapi/get/${props.data.id}`}  
        url={Hoot()+`eduallacademicyearupdate/update/${props.data.id}`}  toggle_btn={
         <button academic_year_code={props.data.id} className="btn-circle bg-success text-light">
            <Edit/>
        </button> 
        }/>
        <DeleteModal title='Ano académico' url={Hoot()+`eduallacademicyeardelete/delete/${props.data.id}`} message='Ano académico deletado com sucesso' toggle_btn={
            <button  className="btn-circle bg-danger btn-delete-academic-year ml-2 text-light">
                <Delete/>
            </button>
        }/>
        </div>;
      }
    } 
  ];

function YearsList() {   
    const [data, setData] = useState([]);
    const [data1, setData1] = useState([]);
    const [load, setLoaded] = useState(false);
    const [LoadStatus, setLoadStatus] = useState(null);

    async function loadData(){
        try {
          setLoaded(false); 
          setLoadStatus(0)
          const response = await axios.get(TABLEURL); 
            const rows = []; 
            const rows1 = []; 
            response.data.map((item, index)=>{  
               rows.push({
                  index:index+1,
                  id:item.ed_academic_year_id,  
                  title:item.ed_academic_year_title,  
                  start:item.ed_academic_year_startDate, 
                  end:item.ed_academic_year_endDate, 
                  action:'',  
              }) 
              rows1.push({
                index:index+1, 
                title:item.ed_academic_year_title,  
                start:item.ed_academic_year_startDate, 
                end:item.ed_academic_year_endDate,  
            }) 
          }); 
          setData1(rows1);
          setData(rows);
          setTimeout(() => {
             setLoaded(true); 
          }, 200);
          setLoadStatus(2)
        } catch (error) {
          setLoadStatus(1)
        }
    }
  
    useEffect(()=>{
        loadData(); 
    },[]);
  
  if(load){
      return (
      <div id='ed-custom-table-data'>
        <TableGrid
            TableHead={columns}
            TableBody={data} 
            TableTitle='Anos Académicos' 
            TableBtn={
              <div className='ed-flex' >
            <button id='ed-custom-table-data-btn'
                onClick={() =>
                  ExportDataToTablesToPdf({
                    fileName: "Lista dos Anos Académicos",
                    headerId: null,
                    contentId: "ed-custom-table-data",
                    footerId: null,
                    rotation: "portrait",
                    buttonId: "ed-custom-table-data-btn",
                    customHeader: "Lista dos Anos Académicos",
                    excludedColumns: ["Ação"]
                  })
                }
                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
              </button>
              <button className='btn-icon btn btn-export-data ml-2' 
                 onClick={()=>ExportDataForTablesExcel("Anos Académicos ", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
              </button>
             <RefreshButton action={loadData} status={LoadStatus} />
         </div>}
        />
    </div>
    )
  }else{
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
            TableHead={columns}
            TableBody={[]} 
            TableTitle='Anos Académicos'
            TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
    </div>
    )
  }
}

export default YearsList

 