
import React, {useState} from 'react' 
import styled from 'styled-components'
import SliderBox from "react-slick";
import { Form } from 'react-bootstrap'; 
import { EmojiEmotionsOutlined, Search } from '@mui/icons-material';
import { Link } from 'react-router-dom';
import { EmojiEmotions, EmojiPeopleOutlined } from '@material-ui/icons';
import { Star } from '@material-ui/icons'
import { StarHalf } from '@mui/icons-material'
import { Avatar, Checkbox, FormControlLabel, FormGroup } from '@mui/material'
import UserBooksGrid from './Components/UserBooksGrid';
import UserNavbar from '../Components/UserNavbar';
import ImageLazyLoading from '../../General/components/ImageLazyLoading';  
import Slider from '@mui/material/Slider';
import {BiSearch} from "react-icons/bi";
import {BsGrid} from "react-icons/bs" 
import UserBooksGridCol from './Components/UserBooksGridCol';

function valuetext(value) {
  return `${value}°C`;
}

const Images = [ 
    'https://s26162.pcdn.co/wp-content/uploads/2017/12/covercover.jpg',    
];

function VirtualLibrary({userdata}) {
    document.title = "Livraria"; 
    const settings = {
        dots: true,
        infinite: true,
        speed: 500,
        slidesToShow: 1,
        slidesToScroll: 1
      };

  
      const [value, setValue] = useState([20, 37]);
      const [ActiveView, setActiveView] = useState(1);

      const handleChange = (event, newValue) => {
        setValue(newValue);
      };

  return (
    <div>
        <UserNavbar data={userdata} />
        <Container>
        <Advertisement>
            <div className="box">
                <SliderBox {...settings}> 
                    <div className="book-slider">
                        <ImageLazyLoading  height={320} source={Images[0]} alt="" />  
                        <div className="sponsored">Patrocinado</div>
                    </div>  
                </SliderBox>     
               <div className="over-ads">
                  <div className="ed-wrapper">
                    <div className="search-box">
                        <div className="box-search">
                            <Form>
                                <div className="box-item"> 
                                   <Form.Control placeholder='Pesquise por palavras chaves...' />
                                </div>
                                <div className="box-item">
                                    <Form.Select>
                                         <option disabled selected>Selecione uma categoria</option>
                                         <option value=""></option>
                                         <option value=""></option>
                                         <option value=""></option>
                                         <option value=""></option>
                                         <option value=""></option>
                                    </Form.Select>
                                </div>
                                <div className="box-item">
                                    <Form.Select>
                                         <option disabled selected>Selecione tipologia</option>
                                         <option value=""></option>
                                         <option value=""></option>
                                         <option value=""></option>
                                         <option value=""></option>
                                         <option value=""></option>
                                    </Form.Select>
                                </div>
                                <button className="btn bg-black text-light"><BiSearch/> </button>
                            </Form>
                        </div>
                     </div>
                  </div>
               </div>
            </div>    
        </Advertisement>
         <div className="ed-wrapper">
         <div className="content">
           <div className="filter-container">
               <div className="filter-box">
                   <div className="block-filter mt-4">
                      <h2 className="title">Assunto</h2>
                      <ul> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                      </ul>
                   </div>
                   <div className="block-filter mt-4">
                      <h2 className="title">Assunto</h2>
                      <ul> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                      </ul>
                   </div>
                   <div className="block-filter mt-4">
                      <h2 className="title">Assunto</h2>
                      <ul>  
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                        <div className="mt-2">
                        <Slider
                            getAriaLabel={() => 'Temperature range'}
                            value={value}
                            onChange={handleChange}
                            valueLabelDisplay="auto"
                            getAriaValueText={valuetext}
                            color="primary"
                         />
                        </div>
                      </ul>
                   </div> 
                   <div className="block-filter mt-4">
                      <h2 className="title">Assunto</h2>
                      <ul> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                      </ul>
                   </div>
                   <div className="block-filter mt-4">
                      <h2 className="title">Assunto</h2>
                      <ul> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                         <li className='mt-2'><FormControlLabel  control={<Checkbox defaultChecked />} label={`Hítorias de amor (23)`} /></li> 
                      </ul>
                   </div>
               </div>
            </div>
            <div className="books-container">
                 <div className="details-bar">
                    <div className="ed-space">
                       <div className="ed-flex">
                          <Form className='ed-flex'>
                               <Form.Select>
                                   <option selected disabled>Ordenar por popularidade</option>
                                   <option value=""></option>
                                   <option value=""></option>
                                   <option value=""></option>
                                   <option value=""></option>
                               </Form.Select>
                               <Form.Select>
                                   <option selected disabled>Data de publicação</option>
                                   <option value=""></option>
                                   <option value=""></option>
                                   <option value=""></option>
                              </Form.Select>
                          </Form>
                       </div>
                       <div className="ed-flex">
                           <div onClick={()=>setActiveView(1)} className={ActiveView === 1 ? "toggle-menu active" : "toggle-menu"}><BsGrid/></div>
                           <div onClick={()=>setActiveView(2)} className={ActiveView === 2 ? "toggle-menu active" : "toggle-menu"}>row</div>
                       </div>
                    </div>
                 </div>
               <div className="ed-block">
                   <div className={ActiveView === 1 ? "" : "d-none"}><UserBooksGrid filters={[]} /></div>
                   <div className={ActiveView === 2 ? "" : "d-none"}><UserBooksGridCol filters={[]} /></div>
               </div>
            </div>
           </div>
         </div>
        </Container> 
        <BooksList>

        </BooksList>
    </div>
  )
}

const Container = styled.div`
    display:block;
    width:100%; 
    margin-top:70px;
    background:var(--ed-background-color);

     
    .content{
        display:flex;
        width:100%;
        padding:20px;

        .filter-container{
            min-height:70vh;
            height:min-content;
            min-width:300px; 
            padding-right:20px;

            .filter-box{
                 border:1px solid var(--ed-silver-light);
                 border-radius:6px; 
                 background:var(--ed-white);
                  
                 .block-filter{
                    padding:10px 20px;
                    border-bottom:1px solid var(--ed-silver-light);

                    h2.title{
                        margin:10px 0px;  
                        margin-top:0px;
                        font-size: 18px;
                        color: var(--black);
                        font-weight: bold; 
                     }
    
                    ul{
                      padding:0px;
                      margin:0px;
                      list-style:none;
    
                       li{
                          font-size:15px;
                          list-style:none;
                       }
                    }

                 }
            }

        }
    
    
        .books-container{
             width:100%;
             display:block;


             .details-bar{
                margin-bottom:20px;
                width:100%;
                padding:10px 20px;
                min-height:50px;
                border:1px solid var(--ed-silver-light);
                display:flex;
                align-items:center;
                justify-content:space-between;
                border-radius:6px; 
                background:var(--ed-white);

                 select{
                      border:none !important;
                      margin-right:15px;
                      font-size:15px;
                      min-width:250px;
                 }

                 .toggle-menu{
                    margin-left:15px;
                    cursor:pointer;
                    width:40px;
                    height:40px;
                    border-radius:6px;
                    display:flex;
                    justify-content:center;
                    align-items:center;

                      svg{
                          width:24px;
                          height:24px;
                      }
                 }

                 .toggle-menu.active{
                      color:var(--ed-purple-light);
                      border:1px solid var(--ed-purple-light);

                 }
             }
        }
    
    
    
    .library-books-grid-col{
        display:block;
        width:100%;
        margin:20px 0px;

        .book-card-col{
            display:flex;
            margin:20px 0px; 
            background-color: var(--ed-white); 
            border-radius:6px;
            box-shadow:var(--ed-shadow-df);
            overflow: hidden; 
            list-style:none !important;
            position:relative;
            padding:20px;

            .image{
                width:170px; 
                img{
                    height:220px;
                    border-radius:6px;
                    width:170px;
                }
            }

            .dets{    
                padding-left:20px;

                .classification{
                    font-size:16px; 
                    color:var(--ed-dark);

                    svg{
                         fill:var(--ed-gold);
                    }
                }

                .aut{
                    font-size:15px  !important;
                    color:var(--ed-grey-text) !important;
                    margin-top:10px;
                }

                p{
                    margin:10px 0px;
                    font-size:15px;
                    color:var(--ed-grey-text);
                }

               h3, .price{
                   font-size:16px;
                   margin-top:10px; 
                   line-height:25px;
                   color:var(--ed-dark);
                }
                
                h5{
                   font-size:15px; 
                }
                 
                
               svg{
                    width:20px;
                    height:20px;
                    margin-right:7px;
                    fill:var(--ed-dark);
                }
            }
        


        }
    }

    
    
     .library-books-grid{
            width:100%;
            margin:20px 0px;
    
            .book-card{
                width:227px; 
                min-height:440px; 
                border-radius:6px; 
                margin:10px; 
                background-color: var(--ed-white);
                background-clip: border-box;  
                box-shadow:var(--ed-shadow-df);
                overflow: hidden; 
                list-style: none !important;
                position:relative;

                .price{
                    padding:8px 15px;
                    border-radius:30px;
                    color:var(--ed-white);
                    background:var(--ed-orange);
                    width:auto;
                    position:absolute;
                    top:20px;
                    right:20px;
                }
    
                img{
                    border-radius:4px;
                    height:280px;
                    width:100%; 
                    object-fit: fill;
                }
            
            .dets{    
                padding:10px;

                .classification{
                    font-size:16px; 
                    color:var(--ed-dark);

                    svg{
                         fill:var(--ed-gold);
                    }
                }

                .aut{
                    font-size:15px  !important;
                    color:var(--ed-grey-text) !important;
                }

               h3{
                   font-size:16px;
                   margin-top:10px; 
                   line-height:25px;
                   color:var(--ed-dark);
                }
                
                h5{
                   font-size:15px; 
                }
                 
                
               svg{
                    width:20px;
                    height:20px;
                    margin-right:7px;
                    fill:var(--ed-dark);
                }
            }
        
            }
            
             
    
    
        }    
    } 

`;

const Advertisement = styled.div`
       width:100%;
       height:320px; 
       border:1px solid var(--ed-silver-light); 
       margin-bottom:60px;
       position:relative;

       img{
          height:320px;
       }

       .over-ads{
          position:absolute;
          top:0px;
          left:0px;
          width:100%;
          height:100%; 
          display:flex;
          justify-content:flex-end;
          align-items:flex-end;

            .search-box{
                width:100%;  
                margin:0 auto;
                padding:20px; 
                display:flex;
                justify-content:center;
                align-items:center;

                  .box-search{
                     height:80px;
                     width:100%;  
                     border-radius:6px;
                     background:var(--ed-white);
                     margin-bottom:-60px;
                     box-shadow:var(--ed-shadow-1);
                     z-index:100;
                     position:relative;  

                     form{
                        width:100%;
                        display:flex;
                        align-items:center;
                        justify-content:space-between;
                     }

                      .box-item{
                          width:32%;
                          height:100%;
                          padding:10px;

                            input, select{
                                height:60px;
                                padding:10px;
                                border:none !important; 
                                border-radius:0px;
                                border-right:1px solid var(--ed-silver-light) !important; 
                            }
                      }

                      .btn{
                         min-width:70px;
                         height:80px;
                         display:flex;
                         justify-content:center;
                         align-items:center;

                          svg{
                             margin:0px;
                          }
                      }
                  }
            }
        }

         .sponsored{
            position:absolute;
            top:20px;
            right:20px;
            padding:4px 20px;
            max-width:200px;
            font-size:16px;
            color:var(--ed-white);
            background:var(--ed-trp-4);
            border-radius:4px;
            box-shadow:var(--ed-shadow-df);
         }
`;



const BooksList = styled.div`
   
`;



export default VirtualLibrary