import React, { useEffect, useState } from 'react'
import styled from 'styled-components';
import { Save, Star } from 'react-ionicons'
import { ProgressBar, Form } from 'react-bootstrap';
import { Avatar } from '@mui/material';
import { toast } from 'react-hot-toast';
import Hoot from '../../../../General/components/Hoot';
import TimeAgo from "javascript-time-ago";
import pt from "javascript-time-ago/locale/pt.json";
import ReactTimeAgo from 'react-time-ago'  
import axios from 'axios';
import SaveButton from '../../../../Dashboard/components/elements/SaveButton';

function LessonFeedbackTab({data, filters, userdata ,  id, socket, total}){
  const [LessonReviews , SetLessonReviews] = useState([]);
  const [ReviewText, setReviewText] = useState("");
  const [ReviewStars, setReviewStars] = useState(1); 
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);
  const  [ReviewsStats, setReviewsStats] = useState({});
  const [LargestReview, setLargestReview]  = useState(0); 
  const [RegisterStatus, setRegisterStatus] = useState(null);


  async function loadData(){
      if(id !== null){
        try {
          setLoaded(false); 
          setLoadStatus(0) 
          const response = await axios.get(Hoot()+"eduallgetlessonreviewsbylessonid/"+id); 
          SetLessonReviews(response.data);
          GetReviewsStatistics(response.data);
          total(response.data.length);  
          setLoadStatus(2)
        } catch (error) {
          setLoadStatus(1)
        }
      } 
  }



  const GetReviewsStatistics = (data)=>{
    if(data !== null && data !== undefined && data.length >= 1){
      let Values = {p1:0,p2:0, p3:0,  p4:0, p5:0,  p1v:[], p2v:[], p3v:[], p4v:[], p5v:[] };
    let Array = [];


     data.map((item)=>{
      Array.push(item.ed_lesson_review_stars);
      if(item.ed_lesson_review_stars*1 === 1){Values.p1v.push(1)}
      if(item.ed_lesson_review_stars*1 === 2){Values.p2v.push(1)}
      if(item.ed_lesson_review_stars*1 === 3){Values.p3v.push(1)}
      if(item.ed_lesson_review_stars*1 === 4){Values.p4v.push(1)}
      if(item.ed_lesson_review_stars*1 === 5){Values.p5v.push(1)}
    }) 

     const count = {}; 
     for (let index = 0; index < Array.length; index++){count[Array[index]] = (count[Array[index]] || 0) + 1;} 
       Object.entries(count).map(([key, value])=>{ 
           if(key*1 === 1){Values.p1 = value; console.log("p1 = ", value)}
           if(key*1 === 2){Values.p2 = value; console.log("p2 = ", value)}
           if(key*1 === 3){Values.p3 = value; console.log("p3 = ", value)}
           if(key*1 === 4){Values.p4 = value; console.log("p4 = ", value)}
           if(key*1 === 5){Values.p5 = value; console.log("p5 = ", value)} 
       })
        

     let NewValues = {
      p1:CalculatePercentage(data.length, Values.p1), p1v:Values.p1v.length,
      p2:CalculatePercentage(data.length, Values.p2), p2v:Values.p2v.length,
      p3:CalculatePercentage(data.length, Values.p3), p3v:Values.p3v.length,
      p4:CalculatePercentage(data.length, Values.p4), p4v:Values.p4v.length,
      p5:CalculatePercentage(data.length, Values.p5), p5v:Values.p5v.length,
    };
     
    console.log("*******************************");
      console.log(Values);
    console.log("*******************************");




    GetLargestValueOnReviews( 
      [NewValues.p1v, NewValues.p2v, NewValues.p3v, NewValues.p4v, NewValues.p5v], 
      {1:NewValues.p1v, 2:NewValues.p2v, 3:NewValues.p3v, 4:NewValues.p4v, 5:NewValues.p5v});
    setReviewsStats(NewValues);
    }
  }


  const CalculatePercentage = (a, b)=>{
   return  Math.floor((b*100) / a);
  }
 

  const FormSubmit = (e)=>{     
    e.preventDefault();
    setRegisterStatus(0);
    if(ReviewText.split("").length >= 15){
      const FormData = { 
        fd_lesson_socketID: socket.id,
        fd_lesson_id:id,
        fd_lesson_text:ReviewText,
        fd_lesson_stars:ReviewStars
     };  
      
      try { 
        socket.emit('eduall_send_lesson_reviewIo', FormData);  
        setReviewText("");
        setReviewStars(1); 
      } catch (error) {
        console.clear();
        console.log(error);
        toast.error("Ocorreu um erro ao enviar a sua avaliação !")
        setRegisterStatus(1)
      }  
    }else{
      setRegisterStatus(1);
    }
};


const GetRealTimeData =  (data)=>{ 
  console.clear();
  console.log(data, id);
  if(data !== null && data !== undefined){
    if(data.ed_lesson_review_lessonId*1 === id){ 
      setRegisterStatus(2)
      if(data !== null & data !== undefined){
        SetLessonReviews([...LessonReviews, data]);
        setTimeout(() => {
          GetReviewsStatistics(LessonReviews);
          total(LessonReviews.length);  
        }, 1000);
      };
    }else{
      setRegisterStatus(1);
    }
  }else{
    setRegisterStatus(1);
  }
} 


const GetLargestValueOnReviews = (values, object)=>{
  let max = Math.max(...values);
  function getObjectKey(obj, value){return Object.keys(obj).find(key => obj[key] === value);}
  let val =  getObjectKey(object, max); 
  setLargestReview(val);
}

 

useEffect(() => { 
  socket.on('eduall_response_lesson_reviews', (data) => GetRealTimeData(data.data, data.user)); 
}, [socket, LessonReviews]);


useEffect(()=>{
  loadData(); 
},[id]);

 
   

  return (
    <Container>
        <div className="review-progress">
             <div className="block">
              <h1>{LargestReview*1}.0</h1>
              <div className="ed-flex stars">
                  <div className={LargestReview >= 1 ? "gold" : ""} onClick={()=>setReviewStars(1)}><Star/></div>
                  <div className={LargestReview >= 2 ? "gold" : ""} onClick={()=>setReviewStars(2)}><Star/></div>
                  <div className={LargestReview >= 3 ? "gold" : ""} onClick={()=>setReviewStars(3)}><Star/></div>
                  <div className={LargestReview >= 4 ? "gold" : ""} onClick={()=>setReviewStars(4)}><Star/></div>
                  <div className={LargestReview >= 5 ? "gold" : ""} onClick={()=>setReviewStars(5)}><Star/></div>
               </div>
               <span>Baseado em {LessonReviews.length} avaliações</span>
             </div> 
             <div className="progress-barBox col">
                 <div className="ed-flex"><div className="label">Excelente ({ReviewsStats.p5v}) </div><div className="progress-box"><ProgressBar  variant='success' style={{height:7}} now={ReviewsStats.p5} /></div></div>
                 <div className="ed-flex"><div className="label">Muito bom ({ReviewsStats.p4v})</div><div className="progress-box"><ProgressBar  variant='info' style={{height:7}} now={ReviewsStats.p4} /></div></div>
                 <div className="ed-flex"><div className="label">Bom ({ReviewsStats.p3v})</div><div className="progress-box"><ProgressBar  variant='primary' style={{height:7}} now={ReviewsStats.p3} /></div></div>
                 <div className="ed-flex"><div className="label">Abaixo da media ({ReviewsStats.p2v})</div><div className="progress-box"><ProgressBar  variant='warning' style={{height:7}} now={ReviewsStats.p2} /></div></div>
                 <div className="ed-flex"><div className="label">Pessimo ({ReviewsStats.p1v})</div><div className="progress-box"><ProgressBar  variant='danger' style={{height:7}} now={ReviewsStats.p1} /></div></div>                
             </div>
        </div> 
        <div className="feedback-form mt-4">
            <Form onSubmit={FormSubmit}>
                <div className="d-flex mb-2">
                    <Avatar sx={{width:40,height:40}} src={Hoot()+userdata.user_Information.ed_user_account_picture} />
                    <div className="ml-2 col">
                       <Form.Control as="textarea" value={ReviewText} onChange={(e)=>setReviewText(e.target.value)}
                        minLength={15} maxLength={500} placeholder='Fale algo interessante sobre esta aula...' />
                     <div className="ed-space"> 
                     <div> 
                      <div className="ed-flex mt-2">
                        <div className="stars ed-flex ml-2">
                          <div className={ReviewStars >= 1 ? "gold" : ""} onClick={()=>setReviewStars(1)}><Star/></div>
                          <div className={ReviewStars >= 2 ? "gold" : ""} onClick={()=>setReviewStars(2)}><Star/></div>
                          <div className={ReviewStars >= 3 ? "gold" : ""} onClick={()=>setReviewStars(3)}><Star/></div>
                          <div className={ReviewStars >= 4 ? "gold" : ""} onClick={()=>setReviewStars(4)}><Star/></div>
                          <div className={ReviewStars >= 5 ? "gold" : ""} onClick={()=>setReviewStars(5)}><Star/></div>
                          </div>  
                        <SaveButton icon={<></>} title={'Enviar'} status={RegisterStatus} />
                      </div>
                     </div> 
                     <div className="count-length"><small>{Math.floor(500-(ReviewText.split("").length))} caracteres</small></div>
                    </div> 
                  </div>
                </div> 
            </Form> 
        </div>
        <ul className="reviews-container">
          {LessonReviews.map((item, index)=>(
              <li key={index+1}>
                   <div className="ed-space d-flex">
                   <div className="ed-flex">
                       <Avatar sx={{width:50,height:50}} src={Hoot()+item.ed_user_account_picture} />
                       <div className="ml-2">
                           <span className="name">{item.ed_user_account_name}</span>
                           <div className="stars">
                              <div className={item.ed_lesson_review_stars*1  >= 1 ? "gold" : ""}><Star/></div>
                              <div className={item.ed_lesson_review_stars*1  >= 2 ? "gold" : ""}><Star/></div>
                              <div className={item.ed_lesson_review_stars*1  >= 3 ? "gold" : ""}><Star/></div>
                              <div className={item.ed_lesson_review_stars*1  >= 4 ? "gold" : ""}><Star/></div>
                              <div className={item.ed_lesson_review_stars*1  >= 5 ? "gold" : ""}><Star/></div>
                              <strong>{item.ed_lesson_review_stars*1}.0</strong>
                          </div>
                       </div>
                   </div>
                   <div>
                      <span>
                         {(item.ed_lesson_review_date !== null && item.ed_lesson_review_date !== undefined ) ? 
                         <ReactTimeAgo date={item.ed_lesson_review_date} locale="pt-PT"/> : ""}
                      </span> 
                    </div>
                   </div>
                   <div className="text"> {item.ed_lesson_review_text} </div>
              </li> 
          ))}
      </ul>
    </Container> 
  )
}

const Container =  styled.div`
  .progress{width:100%;}

  .review-progress{
    background:var(--ed-background-color);
    padding:0px 20px;
    border-radius:10px; 
    display:flex;
    align-items:center;
    width:100%;

      .block{
          text-align:center; 
          display:flex;
          align-items:center;
          flex-direction:column; 
          border-right:1px solid var(--ed-silver);
          min-width:270px;

          h1{
            margin:10px 0px;
            font-size:35px; 
          }

            .stars{ 
                 svg{
                    margin:5px;
                    color:var(--ed-grey-text);
                    fill:var(--ed-grey-text);
                    width:22px;
                    height:22px;
                 }

                 .gold{
                     svg{
                         color:var(--ed-gold) !important;
                         fill:var(--ed-gold) !important;
                     }
                 }
            }
      }

      .progress-barBox{
          padding-left:20px;
          margin:20px 0px;
          width:100% 
          background:gold;

          .ed-flex{
              width:100%;
              text-align:left;
              margin-bottom:2px; 

              .label{
                  min-width:200px; 
                  font-size:15px !important;
              }

              .progress-box{
                   width:100%; 
              }

          } 
      }
   }

   .feedback-form{
    
       textarea{
         min-height:100px;
       }

       small{
         color:var(--ed-grey-text);
       }

       div.gold{
          svg{
            color:var(--ed-gold) !important;
            fill:var(--ed-gold) !important;
          }
       }

       .stars{
           div{
              margin:0px 2px;
              background:transparent;
              cursor:pointer;

              svg{
                  width:20px;
                  height:20px;
                  color:var(--ed-grey-text);
                  fill:var(--ed-grey-text);
              }
           }
       }
 
   }

      ul{
        padding:20px 0px;

          li{
            list-style:none !important;
            margin:10px 0px;
            border-top:1px solid var(--ed-silver-light);
            padding-top:20px;
            margin-bottom:10px;

            .ed-space{
                max-width:950px;

                  span, strong{
                      font-size:15px !important;
                      margin:0px;
                      margin-left:8px; 
                  }
            }

              .ed-flex{
                  margin-bottom:10px;

                  .stars{ 
                    display:flex;

                    svg{
                       margin-right:5px;
                       color:var(--ed-grey-text);
                       fill:var(--ed-grey-text);
                       width:15px;
                       height:15px;
                    }
   
                    .gold{
                        svg{
                            color:var(--ed-gold) !important;
                            fill:var(--ed-gold) !important;
                        }
                    }
                 }

              }

              .text{
                  max-width:850px;
                  font-size:15px;
              }
          }
      }


 

`;

export default LessonFeedbackTab