import React, {useState, useEffect} from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import {Modal, Form, Button} from 'react-bootstrap'
import { Save } from '@mui/icons-material'; 
import {toast} from 'react-hot-toast'; 
import axios from 'axios';
import { Update } from '@material-ui/icons';
import CRValue from '../General/components/CRValue';
import Hoot from '../General/components/Hoot';
import DraggableModal from '../General/components/DraggableModal';
import { useHistory ,Link} from 'react-router-dom';
import SaveButton from '../Dashboard/components/elements/SaveButton';
import { FcGoogle} from "react-icons/fc";
import { FaFacebook } from "react-icons/fa";
import jwt_decode from 'jwt-decode';
import { styled } from 'styled-components';
import { ModalAnimationClose, ModalAnimationShow } from '../General/components/ModalAnimations';
import { Avatar } from '@mui/material';

function LoginModal(props) {
    const [show, setShow] = useState(false);
    const [messageWarning, setMessagewarning] = useState(null); 
    const [showScreen, setShowScreen] = useState(null);
    const [ed_email, setEd_email] = useState(null);
    const [ed_password, setEd_password] = useState(null); 
    const [loading, setLoading] = useState(true);
    const navigate = useHistory();
    const [switchuser, SetSwitchUser] = useState(false);
    const [RegisterStatus, setRegisterStatus] = useState(null); 
    const [LatestLoggedinUsers, SetLatestLoggedinUsers] = useState([""]);
   const [userPicture, setUserPicture] = useState(""); 
   
    const [showBox, SetshowBox]  = useState(false);
    const handleClose = () => {
      SetshowBox(false);
      setTimeout(() => {
        setShow(false);
      }, 1200);
    } 

    const handleShow = () => {
          SetshowBox(true);
          setShow(true);  
          setTimeout(() => {  
           
         }, 1000);   
    };
    const [form, setForm] = useState({});
    const [errors, setErrors] = useState({});
   
    
    const FORMURL = [
      Hoot()+"eduallcicleregister/post/",
      props.get ? props.get : '',
      props.url ? props.url : ''
    ];
  
  
    const INPUTS = {
         title:CRValue("#title"),
         code:CRValue("#code"), 
    }; 
  
  
   
    const setField = (field, value)  =>{
      setForm({
          ...form,
          [field]:value
      })
  
      if(!!errors[field]){
           setErrors({
              ...errors,
              [field]:null
           });  
      }
  }
   

  const GetUserImage = async(email)=>{
     try {
      const response = await axios.get(Hoot()+'eduallgetuserimagebyuser/get/'+`${email}`); 
      if(response.data.length >= 1) setUserPicture(Hoot()+response.data[0].ed_user_account_picture);
     } catch (error) {
      
     }
  }


  const CheckLogin = async ()=>{ 
      setInterval(() => {
         //if(show === false) setShow(true);
      }, 1000*10);
  }


  useEffect(() => {
    CheckLogin();
  }, []);


  function hideMessage() {
    setMessagewarning(null); 
    setShow(false);
  }

  const Auth = async (e)=>{
     e.preventDefault(); 
     setRegisterStatus(0);  
     try {
         if(ed_email ===  null ||ed_password ===  null){
             setMessagewarning("Preencha corretamente os campos"); 
             setRegisterStatus(1);  
         }else{ 
            await axios.post(Hoot()+'login',{
               ed_user_account_email:ed_email,
               ed_user_account_password:ed_password
             }); 
             hideMessage();
             setRegisterStatus(2);  
             setTimeout(()=>{navigate.push('/dashboard');},100);
         }
     } catch (error) {
       if(error.response){
         if (error.response.data) {
           setRegisterStatus(1);  
           setMessagewarning(error.response.data.msg);
           console.log(error); 
         }else{
           setRegisterStatus(1);  
           setMessagewarning('Não foi possível concluir a operação. Tente novamente em instantes !');
           console.log(error); 
         }
       }else{
         setRegisterStatus(1);  
           setMessagewarning("Erro ao estabelecer ligação com o servidor");
       }
     } 
  }

 
    const handleInput = (e)=>{ 
       switch (e.target.id) { 
          case "title":
            setField("title", e.target.value) 
            INPUTS.title = e.target.value
           break;
           case "code":
            setField("code", e.target.value) 
            INPUTS.code = e.target.value
           break;  
       }
    }
  


    return (
    <div>
     <div>
       <div onClick={handleShow}> </div>
     <Modal size='md'  dialogAs={DraggableModal}  centered    show={show} onHide={handleClose}>
       <Form >
       <Modal.Body className='scrollLimit'>
            <Container>
                   <>
                  <div className="ed-center ed-flex mb-3">
                      <Avatar className="df" sx={{width:150,height:150}} src={"http://localhost:5000/images/users/eduall_file_user_account_picture_1699905976996_0.11198244378183331_.jpg"}  />
                  </div> 
                     <Form.Group className="mb-3"> 
                     <Form.Control onChange={handleInput}  id="ed_user_account_password"  value={ed_password}  type="password" required placeholder="Digite a sua senha" />
                  </Form.Group> 
                  </>  
                   <SaveButton class='col btn mt-2 bg-main text-light' title={'Entrar'} status={RegisterStatus} />  
            </Container>
       </Modal.Body> 
       </Form>
     </Modal>
   </div>
      </div>
    )
}


 
const Container = styled.div`  
   .or{   
      display:flex;
      align-items:center;
      justify-content:space-between; 
      color:grey; 

        .ln{
            width:45%;
            height:1px;
            background:var(--ed-silver);
        }
   }

   .btn.col{
      width:100% !important; 
   }

    .btn-social{
        min-width:229px !important;
        max-width:229px !important;
        box-shadow:unset !important;
        font-size:14.5px !important;
        border:1px solid var(--ed-silver) !important;

          svg{
            margin-right:10px;
          }
    }

    .btn-facebook{
         svg{
             fill:var(--ed-blue-light);
         }
    }

 
 
 
 
       .form-message h5{
            font-size:17px;
            text-transform: lowercase !important;
            margin:0px !important;
        } 
   
     

       input{
            padding:7px 10px;
            font-size:16px;
       } 

 
`

export default LoginModal
