import React, {useState, useEffect} from 'react'
import Table from './Table';
import { Delete,  Edit, Refresh, VisibilityOutlined } from '@mui/icons-material';
import  axios  from 'axios';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import NewServiceModal from '../modal/NewServiceModal';
import { GetProviderName } from '../../../General/components/InstituteData';
import TableGrid from '../../../General/components/TableGrid';
import NumberToPrice from '../../../General/components/NumberToPrice';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';

const TABLEURL = Hoot()+'eduallservicesapi/get/';

 
const ServiceMethods = ["Diario", "Semanal", "Mensal", "Anual", "Outro"];

const columns = [ 
  { field: 'index', headerName: 'Nº', width: 90,resizable: true },
  {
    field: 'title',
    headerName: 'Serviço', 
    resizable: true,
  },
  {
    field: 'method',
    headerName: 'Metodo de cobrança', 
    resizable: true,
  },
  {
    field: 'price',
    headerName: 'Valor do serviço', 
    resizable: true,
  },
  {
    field: 'provider',
    headerName: 'Fornecedor', 
    resizable: true, 
  },
  {
    field: 'action',
    headerName: 'Ação', 
    width: 240, 
    sortable:false,
    resizable: true,
    cellRenderer:(props) => { 
      return  <div className="ed-flex"> 
      <NewServiceModal   title='Atualizar ' update='true' get={Hoot()+`eduallsingleserviceapi/get/${props.data.id}`}  
       url={Hoot()+`eduallserviceupdate/update/${props.data.id}`}  toggle_btn={
         <button className="btn-circle btn-edit-service bg-success ml-2 text-light">
           <Edit/> 
        </button>
      } />
     <DeleteModal  title='este serviço' url={Hoot()+`eduallservicedelete/delete/${props.data.id}`} 
      message='Serviço deletado com sucesso !' toggle_btn={
         <button service-code={props.data.id}   className="btn-circle bg-danger btn-delete-service ml-2 text-light">
            <Delete/>
         </button>
        } />
     </div>;
    }
  } 
];


function ServicesTable() {      
  const [data, setData] = useState([]);  
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData(){
    try {
      setLoadStatus(0);
      setLoaded(false);
      const response = await axios.get(TABLEURL); 
      const rows = []; 
      response.data.map((item, index)=>{ 
        rows.push({
          id:item.ed_service_id,
          index:index+1,
          title:item.ed_service_title ,
          method: ServiceMethods[item.ed_service_type*1],  
          price: NumberToPrice(item.ed_service_price)+ " "+ item.ed_coin_code ,
          provider:item.ed_provider_title, 
       }) 
      }); 
      setData(rows); 
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoadStatus(1);
    }
  };
  
  useEffect(()=>{ 
      loadData();  
  },[]);
 
 

  if(load){
      return (
      <div id="ed-custom-table-data">
        <TableGrid
            TableHead={columns}
            TableBody={data} 
            TableTitle='Lista dos Serviços'
            TableBtn={
              <div className='ed-flex' >
                <button id='ed-custom-table-data-btn'
                  onClick={() =>
                    ExportDataToTablesToPdf({
                      fileName: "Lista dos serviços",
                      headerId: null,
                      contentId: "ed-custom-table-data",
                      footerId: null,
                      rotation: "portrait",
                      buttonId: "ed-custom-table-data-btn",
                      customHeader: "Lista dos serviços",
                      excludedColumns: ["Ação"]
                    })
                  }
                  className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
                </button>
              <button className='btn-icon btn btn-export-data ml-2' 
                 onClick={()=>ExportDataForTablesExcel("serviços ", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
              </button>
             <RefreshButton action={loadData} status={LoadStatus} />
         </div>}
        />
    </div>
    )
  }else{
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
            TableHead={columns}
            TableBody={[]} 
            TableTitle='Lista dos Serviços'
            TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
    </div>
    )
  }
  
}

export default ServicesTable