import { useEffect } from "react";

// Aplica temas padrão, remove 'theme-mode-light' e salva no localStorage
const useSetDefaultThemes = () => {
  useEffect(() => {
    const requiredClasses = ["theme-mode-light-bar", "theme-color-purple"];
    const removeClass = "theme-mode-light";

    // Salva no localStorage
    localStorage.setItem("themeMode", "theme-mode-light-bar");
    localStorage.setItem("colorMode", "theme-color-purple");

    const body = document.body;
    if (body) {
      if (body.classList.contains(removeClass)) {
        body.classList.remove(removeClass);
      }

      requiredClasses.forEach(cls => {
        if (!body.classList.contains(cls)) {
          body.classList.add(cls);
        }
      });
    }

    const dashboardContainer = document.querySelector(".dashboard-container");
    if (dashboardContainer) {
      if (dashboardContainer.classList.contains(removeClass)) {
        dashboardContainer.classList.remove(removeClass);
      }

      requiredClasses.forEach(cls => {
        if (!dashboardContainer.classList.contains(cls)) {
          dashboardContainer.classList.add(cls);
        }
      });
    }
  }, []);
};

export default useSetDefaultThemes;
