import React, { useEffect, useState } from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap'
import { Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import axios from 'axios';
import Hoot from '../../../General/components/Hoot';
import ClearInputs from '../../../General/components/ClearInputs';
import CRValue from '../../../General/components/CRValue';
import { toast } from 'react-hot-toast';
import { Update } from '@material-ui/icons';
import { GetInstituteCode } from '../../../General/components/InstituteData';
import RefreshList from '../../../General/components/RefreshList';
import { FormControl, FormControlLabel, FormLabel, Radio, RadioGroup } from '@mui/material';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import ReplaceWord from '../../../General/components/ReplaceWord';


function NewAcademicLevelModal(props) {
  const [show, setShow] = useState(false);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});
  const [ForExam, setForExam] = useState(0);
  const [ForFt, setForFt] = useState(0);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [Founded, SetFounded] = useState(null);


  const [showBox, SetshowBox] = useState(false);
  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200);
  }

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };


  const INPUTS = {
    academic_level_title: CRValue("#academic_level_title"),
    academic_level_forExam: ForExam,
    academic_level_forFt: ForFt,
    academic_level_avaliationtype_endat: CRValue("#academic_level_avaliationtype_endat")
  };

  const FORMURL = [
    Hoot() + "eduallregisteracademiclevel/post",
    props.get ? props.get : '',
    props.url ? props.url : ''
  ];

  const GET_DATA = async () => {
    if (props.update) {
      try {
        const response = await axios.get(FORMURL[1]);
        if (response.data.length > 0) {
          if (response.data[0] !== null) {
            document.querySelector("#academic_level_title").value = response.data[0].ed_academic_level_title;
            INPUTS.academic_level_title = response.data[0].ed_academic_level_title;

            document.querySelector("#academic_level_avaliationtype_endat").value = response.data[0].ed_academic_level_avaliationtype_endat;
            INPUTS.academic_level_avaliationtype_endat = response.data[0].ed_academic_level_avaliationtype_endat;
          }
        } else {
          toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
        }
      } catch (error) {
        toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
      }
    }
  }

  const setField = (field, value) => {
    setForm({
      ...form,
      [field]: value
    })

    if (!!errors[field]) {
      setErrors({
        ...errors,
        [field]: null
      });
    }
  }


  const validateForm = () => {
    const { academic_level_title, academic_level_avaliationtype_endat } = form;
    const NewErrors = {};
    setRegisterStatus(0);

    if (INPUTS.academic_level_title === "" || INPUTS.academic_level_title === " ") {
      if (!academic_level_title || academic_level_title === '') NewErrors.academic_level_title = ReplaceWord("Classe") + ' invalida !';
    } else { if (!academic_level_title) { setField("academic_level_title", INPUTS.academic_level_title); } }

    if (INPUTS.academic_level_avaliationtype_endat === "" || INPUTS.academic_level_avaliationtype_endat === " ") {
      if (!academic_level_title || academic_level_title === '') NewErrors.academic_level_avaliationtype_endat = 'Informação Invalida !';
    } else { if (!academic_level_title) { setField("academic_level_title", INPUTS.academic_level_avaliationtype_endat); } }
    return NewErrors;
  }


  const FormSubmit = (e) => {
    e.preventDefault();
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os  campos");
      setRegisterStatus(1);
    } else {
      if (!props.update) {
        try {
          axios.post(FORMURL[0], INPUTS).then(() => {
            toast.success(ReplaceWord("Classe") + " registrada com sucesso !");
            setForm({});
            ClearInputs();
            RefreshList(`.el-refresh-list`);
            setRegisterStatus(2);
          }).catch((error) => {
        const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
        toast.error(msg);
            setRegisterStatus(1);
          });
        } catch (error) {
        const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
        toast.error(msg);
          setRegisterStatus(1);
        }
      } else {
        try {
          axios.put(FORMURL[2], INPUTS)
            .then(() => {
              toast.success(ReplaceWord("Classe") + " atualizada com sucesso !");
              setForm({});
              ClearInputs();
              RefreshList(`.el-refresh-list`)
              setRegisterStatus(2);
            }).catch((error) => {
        const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
        toast.error(msg);
              setRegisterStatus(1);
            });
        } catch (error) {
        const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
        toast.error(msg);
          setRegisterStatus(1);
        }
      }
    }
  };


  const handleInput = (e) => {
    switch (e.target.id) {
      case "academic_level_title":
        INPUTS.academic_level_title = e.target.value
        setField("academic_level_title", e.target.value);
        break;
      case "academic_level_avaliationtype_endat":
        INPUTS.academic_level_avaliationtype_endat = e.target.value
        setField("academic_level_avaliationtype_endat", e.target.value);
        break;
      default:
    }
  }


  const handleInput1 = (e) => {
    setForFt(e.target.value);
    setField("academic_level_forFt", e.target.value);
  }

  const handleInput2 = (e) => {
    setForExam(e.target.value);
    setField("academic_level_forExam", e.target.value);
  }

  return (
    <div>
      <div onClick={handleShow}>
        {
          props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main'><AddCircleOutlineIcon /> Registrar {ReplaceWord("Classe")}</button>
        }
      </div>
      <Modal size='lg' className={showBox ? ModalAnimationShow() : ModalAnimationClose()} centered dialogAs={DraggableModal} show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>{props.title ? props.title : 'Registrar '} {ReplaceWord("Classe")}</h5>
            </div>
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={FormSubmit}>
          <Modal.Body className='scrollLimit'>
            <Form.Group className="mb-3" >
              <Form.Label>Nome da {ReplaceWord("Classe", true)}<span className='text-danger ml-2'>*</span></Form.Label>
              <Form.Control required placeholder={'Ex: 1ª ' + ReplaceWord("Classe", true)} onChange={handleInput} className={!!errors.academic_level_title && 'is-invalid'} value={form.academic_level_title} isInvalid={!!errors.academic_level_title}
                type="text" id="academic_level_title" />
              <Form.Control.Feedback type='invalid'>{errors.academic_level_title}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className='mb-3'>
              <FormControl id="academic_level_forExam">
                <div className="ed-flex">
                  <FormLabel className='text-main' id="academic_level_forExam">Definir como {ReplaceWord("Classe", true)} de exame :</FormLabel>
                  <RadioGroup aria-labelledby="academic_level_forExam" defaultValue={ForExam}
                    name="radio-buttons-group" id="academic_level_forExam" onChange={handleInput2}  >
                    <div className="ml-2 ed-flex">
                      <FormControlLabel value="1" control={<Radio />} label="Sim" />
                      <FormControlLabel value="0" control={<Radio />} label="Não" />
                    </div>
                  </RadioGroup>
                  <Form.Control.Feedback type='invalid'>{errors.academic_level_forExam}</Form.Control.Feedback>
                </div>
              </FormControl>
              <FormControl id="academic_level_forFt">
                <div className="ed-flex">
                  <FormLabel className='text-main' id="academic_level_forFt">Definir como {ReplaceWord("Classe", true)} de recurso :</FormLabel>
                  <RadioGroup aria-labelledby="academic_level_forFt" defaultValue={ForFt}
                    name="radio-buttons-group" id="academic_level_forFt" onChange={handleInput1}  >
                    <div className="ml-2 ed-flex">
                      <FormControlLabel value="1" control={<Radio />} label="Sim" />
                      <FormControlLabel value="0" control={<Radio />} label="Não" />
                    </div>
                  </RadioGroup>
                  <Form.Control.Feedback type='invalid'>{errors.academic_level_forFt}</Form.Control.Feedback>
                </div>
              </FormControl>
            </Form.Group>
            <Form.Group>
              <div className="ed-flex mt-2">
                <div className="text-main mr-2">Começar á avaliar dos</div>
                <div style={{ width: "60px" }}>
                  <Form.Control placeholder='0' readOnly type="number" />
                </div>
                <div className="text-main ml-2 mr-2">aos</div>
                <div style={{ width: "60px" }}>
                  <Form.Control
                    placeholder="10"
                    type="number"
                    min={10}
                    max={20}
                    onChange={handleInput}
                    className={!!errors.academic_level_avaliationtype_endat && 'is-invalid'}
                    value={form.academic_level_avaliationtype_endat}
                    isInvalid={!!errors.academic_level_avaliationtype_endat}
                    id="academic_level_avaliationtype_endat"
                  />

                </div>
                <div className="text-main ml-2">valores</div>
              </div>
              <Form.Control.Feedback type='invalid'>{errors.academic_level_avaliationtype_endat}</Form.Control.Feedback>
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <div className="ed-space">
              <div className="ed-flex"></div>
              <div className="ed-flex">
                <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                {props.update ? (Founded === false ? <div></div> :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />}
              </div>
            </div>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  )
}

export default NewAcademicLevelModal