import axios from 'axios';
import React, { useEffect, useState } from 'react';
import Form from 'react-bootstrap/Form';
import ReactFlagsSelect from "react-flags-select";
import PhoneInput from 'react-phone-input-2'
import Hoot from '../../General/components/Hoot';
import { Avatar, AvatarGroup } from '@mui/material';
import SaveButton from '../../Dashboard/components/elements/SaveButton';
import { Save, Update } from '@mui/icons-material';
import CRValue from '../../General/components/CRValue';
import {toast} from 'react-hot-toast';
import ClearInputs from '../../General/components/ClearInputs';
import { passwordStrength } from 'check-password-strength'


function UserSecuritySettings() { 
    const [form, setForm] = useState({});
    const [errors, setErrors] = useState({}); 
    const [RegisterStatus, setRegisterStatus] = useState(null);
    const [PasswordStrength, SetPasswordStrength] = useState(0);
 
         
    const INPUTS = {
        user_password:CRValue("#user_password"),  
        class_course:CRValue("#class_course"), 
        class_period:CRValue("#class_period"), 
        class_year:CRValue("#class_year"), 
        user_retype_new_password:CRValue("#user_retype_new_password"), 
        user_new_password:CRValue("#user_new_password"), 
   }; 

   const FORMURL = [
     Hoot()+"eduallchangecurrentuserpassword",
   ];

    
    const setField = (field, value)  =>{
        setForm({
            ...form,
            [field]:value
        })
    
        if(!!errors[field]){
             setErrors({
                ...errors,
                [field]:null
             });  
        }
    }
     
  
      const validateForm = ()=>{
        const {user_password, user_new_password, user_retype_new_password} = form; 
        const NewErrors = {};
        setRegisterStatus(0);  
  
        
      if(INPUTS.user_password ===  "" || INPUTS.user_password ===  " "){
        if(!user_password || user_password === '') NewErrors.user_password = 'Palavra-passe atual é invalida !';  
        }else{if(!user_password){setField("user_password", INPUTS.user_password);}} 
  
        if(INPUTS.user_new_password ===  "" || INPUTS.user_new_password ===  " "){
        if(!user_new_password || user_new_password === '') NewErrors.user_new_password = 'Nova Palavra-passe não foi validada !';  
        }else{if(!user_new_password){setField("user_new_password", INPUTS.user_new_password);}} 
  
        if(INPUTS.user_retype_new_password ===  "" || INPUTS.user_retype_new_password ===  " "){
        if(!user_retype_new_password || user_retype_new_password === '') NewErrors.user_retype_new_password = 'As palavras-passes não combinam !';  
        }else{if(!user_retype_new_password){setField("user_retype_new_password", INPUTS.user_retype_new_password);}} 

        if(passwordStrength(INPUTS.user_new_password).value === "weak"){ 
            NewErrors.user_new_password = "Palavra-passe demasiado fraca !";
        }
        if(user_retype_new_password !== user_new_password) NewErrors.user_retype_new_password = 'As palavras-passes não combinam !';  
        
        return NewErrors;
    }




    
 
      const FormSubmit = (e)=>{  
        e.preventDefault();   
        const formErrors = validateForm();
        if(Object.keys(formErrors).length > 0){
             setErrors(formErrors);
             toast.error("Verifique todos os  campos !");
             setRegisterStatus(1);     
          }else{
             try {
                const SUBMIT_INPUTS = {ed_user_newpassword:INPUTS.user_new_password, ed_user_oldpassword:INPUTS.user_password};
                 axios.put(FORMURL[0] , SUBMIT_INPUTS).then(()=>{  
                   toast.success("Palavra-passe atualizada com sucesso !");
                   setForm({});
                   ClearInputs();
                   setRegisterStatus(2);  
                   setErrors({});
                 }).catch((error)=>{
                    console.log(error)
                    if(error.response){
                        if (error.response.data) {  
                            setErrors({user_password:error.response.data.msg});
                        }else{
                            toast.error("Lamentamos mas não foi  possivel executar esta ação !");
                        }
                      }else{
                        toast.error("Lamentamos mas não foi  possivel executar esta ação !");
                      } 
                   setRegisterStatus(1);  
                 }); 
             } catch (error) {
                toast.error("Lamentamos mas não foi  possivel executar esta ação !");
                setRegisterStatus(1);  
             } 
          }
        }  
          
  
        
      
    const handleInput = (e)=>{ 
        switch (e.target.id) {
         case "user_password":
            INPUTS.user_password = e.target.value
            setField("user_password", e.target.value);
           break;
           case "user_new_password":
             INPUTS.user_new_password = e.target.value
             setField("user_new_password", e.target.value);
               if(e.target.value.split("").length >= 1){
                if(passwordStrength(e.target.value).value.toLowerCase() === "weak"){ SetPasswordStrength(1);
                }else if (passwordStrength(e.target.value).value.toLowerCase() === "medium"){SetPasswordStrength(2);
                }else if(passwordStrength(e.target.value).value.toLowerCase() === "strong"){ SetPasswordStrength(3);
                }else{SetPasswordStrength(1);}
            }else{SetPasswordStrength(0);}
            break;  
           case "user_retype_new_password":
             INPUTS.user_retype_new_password = e.target.value
             setField("user_retype_new_password", e.target.value);
           break;
           default:
        }
     }
  
  
   
     return (
       <div className='container-box'>
          <Form onSubmit={FormSubmit}>  
         <div className="mb-3">
         <Form.Group className="mb-3 col" controlId="formBasicPassword">
           <Form.Label>Palavra-passe atual</Form.Label>
           <Form.Control onChange={handleInput} type="password"  className={!!errors.user_password && 'is-invalid'} 
           value={form.user_password} isInvalid={!!errors.user_password}  id="user_password" />
            <Form.Control.Feedback type='invalid'>{errors.user_password}</Form.Control.Feedback>
         </Form.Group> <div className="pd-1"></div> 
         </div>
         <div className="mb-3">
         <Form.Group className="mb-3 col" controlId="formBasicPassword"> 
           
           <div className="ed-space">
           <Form.Label>Nova palavra-passe</Form.Label>
           <div className="ed-flex">
                <div className={PasswordStrength >= 1 ?  "dot bg-green" : "dot"}></div>
                <div className={PasswordStrength >= 2 ?  "dot bg-green" : "dot"}></div>
                <div className={PasswordStrength >= 3 ?  "dot bg-green" : "dot"}></div>
            </div>
           </div>
           <Form.Control onChange={handleInput} type="password"  className={!!errors.user_new_password && 'is-invalid'} 
           value={form.user_new_password} isInvalid={!!errors.user_new_password} placeholder="Ex: A@2asdF2020!!*"  id="user_new_password" />
            <Form.Control.Feedback type='invalid'>{errors.user_new_password}</Form.Control.Feedback>
         </Form.Group> <div className="pd-1"></div>
         <Form.Group className="mb-3 col" controlId="formBasicCheckbox">
            <Form.Label>Repetir nova palavra-passe</Form.Label>
            <Form.Control  onChange={handleInput} type="password"  className={!!errors.user_retype_new_password && 'is-invalid'} 
             value={form.user_retype_new_password} isInvalid={!!errors.user_retype_new_password} placeholder="Ex: A@2asdF2020!!*"  id="user_retype_new_password" />
            <Form.Control.Feedback type='invalid'>{errors.user_retype_new_password}</Form.Control.Feedback>
          </Form.Group> 
         </div>  
         <div className="mt-2">
            <SaveButton icon={<Update/>} title={'Salvar alterações'} status={RegisterStatus} />
          </div>
       </Form>
       </div>
     )
   }


export default UserSecuritySettings