import React, { useState, useEffect } from 'react'
import axios from 'axios'
import { Delete, Description, Edit, PreviewOutlined } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import TableGrid from '../../../General/components/TableGrid'; 
import { Link } from 'react-router-dom';
import NewTransportRouteModal from '../modal/NewTransportRouteModal';
import RefreshButton from '../../../General/components/RefreshButton';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
 
const TABLEURL = Hoot() + "edualltransportroutesget/get/";
const columns = [
  {
    field: 'index',
    headerName: 'Nº',
    resizable: true,
    width: 80
  },
  {
    field: 'route',
    headerName: 'Nome da rota',
    sortable: false,
    resizable: true,
    width: 270,
  },
  {
    field: 'vehicle',
    headerName: 'Veiculo',
    sortable: false,
    resizable: true,
    width: 180,
  },
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true,
    cellRenderer: (props) => {
      return <div className="ed-flex">
        <NewTransportRouteModal title='Atualizar ' update='true' get={Hoot() + `edualltransportsinglerouteget/get/${props.data.id}`}
          url={Hoot() + `edualltransportrouteupdate/update/${props.data.id}`}
          toggle_btn={
            <button className="btn-circle btn-edit-timing bg-success text-light">
              <Edit />
            </button>
          }
        />
        <DeleteModal title='esta rota' url={Hoot() + `edualltransportroutedelete/delete/${props.data.id}`}
          message='Rota deletada com sucesso' toggle_btn={
            <button className="btn-circle bg-danger ml-2 text-light">
              <Delete />
            </button>
          } />
      </div>;
    }
  }
];

function TransportRoutesTable() {
  const [data, setData] = useState([]);
  const [LoadStatus, setLoadStatus] = useState(null);
  const [load, setLoaded] = useState(false);


  async function loadData() {
    try {
      setLoadStatus(0);
      setLoaded(false);
      const response = await axios.get(TABLEURL);
      const rows = [];
      response.data.map((item, index) => {
        rows.push({
          index: index + 1,
          id: item.ed_transport_route_id,
          route: item.ed_transport_route_name,
          vehicle: item.ed_transport_vehicle_model,
        })
      });
      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoaded(true);
      setLoadStatus(1);
    }
  }


  useEffect(() => {
    loadData();
  }, []);



  if (load) {
    return (
      <div id="ed-custom-table-data">
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista das rotas'
          TableBtn={
            <div className='ed-flex'>
              <button id='ed-custom-table-data-btn'
                onClick={() =>
                  ExportDataToTablesToPdf({
                    fileName: "Lista das rotas",
                    headerId: null,
                    contentId: "ed-custom-table-data",
                    footerId: null,
                    rotation: "portrait",
                    buttonId: "ed-custom-table-data-btn",
                    customHeader: "Lista das rotas",
                    excludedColumns: ["Ação"]
                  })
                }
                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
              </button>
              <button className='btn-icon btn btn-export-data ml-2'
                onClick={() => ExportDataForTablesExcel("lista das rotas", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
              </button>
              <RefreshButton action={loadData} status={LoadStatus} />
            </div>
          }
        />
      </div>
    )
  } else {
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista de rotas'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    )
  }
}

export default TransportRoutesTable