import React from 'react'
import ImageLazyLoading from './ImageLazyLoading'
import Hoot from './Hoot';
import ReplaceWord from './ReplaceWord';

function StudentCard({index, data}) {
  const Periods  = ["Manhã", "Tarde", "Noturno"];
  return (
    <article className="ed-id-card">
    <div className={`edic ed-id-card-${index}`}>
      {(data.name === null  || data.name === undefined) ?
        <>
        <div className="header">
             <div className="logo">
               <ImageLazyLoading  source="https://static.wixstatic.com/media/ddb0c7_fba77c787d6648938e276569d7c599f9~mv2.png/v1/fit/w_2500,h_1330,al_c/ddb0c7_fba77c787d6648938e276569d7c599f9~mv2.png" height={20} />
             </div>
              <div className="text">
                 <div><strong>xxxxxxxxxxxxxxx xxxxxxxxx xxxxxxxx</strong></div>
                 <div><span>xxxxxxxxx xxxxxxxx xxxxxxxxxxxxx xxxxxxxx</span></div>
            </div>
        </div>
        <div className="d-flex">
            <div className="avatar-img">
               <ImageLazyLoading height={200}  source="https://rimh2.domainstatic.com.au/podf_4pBcH9GEsYPJbh2_w5dXv8=/232x232/top/filters:no_upscale():format(png):quality(85)/https://images.domain.com.au/img/3358/contact_1548946.png?date=637769762660663951" />
            </div>
           <div className="ed-block ml-2">
                <h3>Nome: xxxxx xxxxx xxxxx</h3>
                <div>
                 <div className="ed-flex mt-2">
                   <h4>Número: xxxxx</h4>
                   <h4 className="ml-2" >Sala: xxxxx </h4>
                 </div>
                  <div className="ed-flex mt-2">
                    <h4>Classe : xxx</h4>
                    <h4 className='ml-2'>Turma: xxxxxx</h4>
                  </div>
                  <div className="ed-flex mt-2">
                  <h4>Periodo : xxxxx</h4> 
                </div>
                </div>
           </div>
        </div>      
        </>
        :
       <>
        <div className="header">
           <div className="logo">
             <ImageLazyLoading source={Hoot()+data.instituteData.ed_institute_logo} height={20} />
           </div>
            <div className="text">
               <div><strong>{data.instituteData.ed_institute_name}</strong></div>
               <div><span>{data.instituteData.ed_institute_slogan}</span></div>
             </div>
      </div>
      <div className="d-flex">
         <div className="avatar-img">  
            <ImageLazyLoading source={data.picture} height={200}  />
         </div>
         <div className="ed-block ml-2">
              <h3>Nome: {data.name} </h3>
              <div>
               <div className="ed-flex mt-2">
                 <h4>Número: {data.id}</h4>
                 <h4 className="ml-2" >Sala: {data.instituteData.ed_classroom_title}</h4>
               </div>
                <div className="ed-flex mt-2">
                  <h4>{ReplaceWord("Classe")} : {data.instituteData.ed_academic_level_title}</h4>
                  <h4 className='ml-2'>Turma: {data.instituteData.ed_class_title}</h4>
                </div>
                <div className="ed-flex mt-2">
                  <h4>Periodo : {Periods[data.instituteData.ed_class_period*1]}</h4> 
                </div>
              </div>
         </div>
      </div>
       </>}  
    </div>
    </article>
  )
}

export default StudentCard