import React, { useState, useEffect } from 'react'
import axios from 'axios'
import { Delete, Description, Edit, PreviewOutlined, Refresh } from '@mui/icons-material';
import Table from './Table';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import { GetServicePrice, GetServiceTitle, GetStudentName, GetTransportStopName } from '../../../General/components/InstituteData';
import NewTransportPassengerModal from '../modal/NewTransportPassengerModal';
import TableGrid from '../../../General/components/TableGrid';
import { Link } from 'react-router-dom';
import SwitchFromPages from '../../../General/components/SwitchFromPages';
import { Avatar } from '@mui/material';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import FakeTableRender from '../../../General/components/FakeTableRender';


const TABLEURL = Hoot() + "edualltransportpassengerget/get/";


const columns = [
  {
    field: 'index',
    headerName: 'Nº',
    resizable: true,
    width: 80
  },
  {
    field: 'student',
    headerName: 'Nome do estudante',
    sortable: false,
    resizable: true,
    width: 270,
    cellRenderer: (props) => {
      return <SwitchFromPages link={`studentinfo/${props.data.studentid}`}
        menu='3' menu_item='17' toggle_btn={
          <div className='ed-flex'>
            <Avatar className='df' alt={props.data.name} src={props.data.picture !== "" ? Hoot() + props.data.picture : ""} />
            <span className='ml-2'>{props.data.student}</span>
          </div>
        } />
    }
  },
  {
    field: 'startmonth',
    headerName: 'Mês de adesão',
    sortable: false,
    resizable: true,
    width: 160,
  },
  {
    field: 'academicyear',
    headerName: 'Ano letivo',
    sortable: false,
    resizable: true,
    width: 130,
  },
  {
    field: 'stop',
    headerName: 'Paragem',
    sortable: false,
    resizable: true,
    width: 180,
  },
  {
    field: 'action',
    headerName: 'Ação',
    resizable: true,
    cellRenderer: (props) => {
      return <div className="ed-flex">
        <NewTransportPassengerModal title='Atualizar ' update='true' get={Hoot()+`edualltransportsinglepassengerget/get/${props.data.id}`}
          url={Hoot()+`edualltransportpassengerupdate/update/${props.data.id}`}
          toggle_btn={
            <button className="btn-circle  bg-success text-light">
              <Edit />
            </button>
          }
        />
        <DeleteModal title='este passageiro' url={Hoot() + `edualltransportpassengerdelete/delete/${props.data.id}`}
          message='Passageiro deletado com sucesso' toggle_btn={
            <button className="btn-circle bg-danger ml-2 text-light">
              <Delete />
            </button>
          } />
      </div>;
    }
  }
];



function TransportPassengersTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  const MonthsList = ["Janeiro", "Fevereiro", "Março",
    "Abril", "Maio", "Junho", "Julho", "Agosto", "Setembro",
    "Outubro", "Novembro", "Dezembro"];


  async function loadData() {
    try {
      setLoaded(false);
      setLoadStatus(0);
      const response = await axios.get(TABLEURL);
      const rows = [];
      response.data.map((item, index) => {
        rows.push({
          index: index + 1,
          id:item.ed_transport_passenger_id,
          studentid: item.ed_student_id,
          student: item.ed_student_name,
          picture: item.ed_student_picture,
          service: item.ed_service_title,
          startmonth: MonthsList[item.ed_transport_passenger_startMonth],
          stop: item.ed_transport_stop_name,
          academicyear: item.ed_academic_year_title,
          action: '',
        })
      });
      setData(rows);
      setTimeout(() => {
        setLoaded(true);
      }, 200);
      setLoadStatus(2);
    } catch (error) {
      setLoaded(true);
      setLoadStatus(1);
    }
  }

  useEffect(() => {
    loadData();
  }, []);



  if (load) { 
    return (
      <div id="ed-custom-table-data"> 
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista de passageiros'
          TableBtn={
            <div className='ed-flex'>
              <button id='ed-custom-table-data-btn'
                onClick={() =>
                  ExportDataToTablesToPdf({
                    fileName: "Lista de passageiros",
                    headerId: null,
                    contentId: "ed-custom-table-data",
                    footerId: null,
                    rotation: "portrait",
                    buttonId: "ed-custom-table-data-btn",
                    customHeader: "Lista de passageiros",
                    excludedColumns: ["Ação"]
                  })
                }
                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
              </button>
              <button className='btn-icon btn btn-export-data ml-2'
                onClick={() => ExportDataForTablesExcel("lista dos autores", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
              </button>
              <RefreshButton action={loadData} status={LoadStatus} />
            </div>
          }
        />
      </div>
    )
  } else {
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Lista de passageiros'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    )
  }
}

export default TransportPassengersTable