import { AccountCircleOutlined, CalendarTodayOutlined, CastForEducationOutlined, FaceOutlined, ForumOutlined, MonetizationOnOutlined } from '@material-ui/icons';
import { AutoStoriesOutlined, CalendarMonthOutlined, FactCheckOutlined, LogoutTwoTone, SummarizeOutlined, TopicOutlined } from '@mui/icons-material';
import React from 'react'
import { useState } from 'react';
import { Link } from 'react-router-dom';
import styled from 'styled-components'
import Tooltip from '../../../General/components/Tooltip';

function SidebarLeft() {
 const [activeMenu, SetActiveMenu] = useState(0); 

 const changeCurrentMenu =(e)=>{
      SetActiveMenu(e);
 }

  return (
     <Content>
        <ul>
          <Tooltip  place='right' text='#' toggle_btn={
             <Link to='/profile'>
               <li  onClick={()=>changeCurrentMenu(1)}   className={activeMenu === 1 ? 'active bg-main' : ''}><AccountCircleOutlined /></li>
            </Link>
            }/>
              <Tooltip  place='right' text='#' toggle_btn={
                <Link to='#'>
                    <li  onClick={()=>changeCurrentMenu(2)}   className={activeMenu === 2 ? 'active bg-main' : ''}><CalendarTodayOutlined /></li>
                </Link>
            }/>
              <Tooltip  place='right' text='#' toggle_btn={
               <Link to='#'>
                  <li  onClick={()=>changeCurrentMenu(3)}   className={activeMenu === 3 ? 'active bg-main' : ''}><FaceOutlined /></li>
               </Link>
            }/>
              <Tooltip  place='right' text='#' toggle_btn={ 
             <Link to='#'>
                <li  onClick={()=>changeCurrentMenu(4)}   className={activeMenu === 4 ? 'active bg-main' : ''}><MonetizationOnOutlined /></li>
             </Link>
            }/>
              <Tooltip  place='right' text='#' toggle_btn={
               <Link to='#'>
                  <li  onClick={()=>changeCurrentMenu(5)}   className={activeMenu === 5 ? 'active bg-main' : ''}><ForumOutlined /></li>
               </Link>
            }/>
              <Tooltip  place='right' text='#' toggle_btn={ 
             <Link to='#'>
               <li  onClick={()=>changeCurrentMenu(6)}   className={activeMenu === 6 ? 'active bg-main' : ''}><FactCheckOutlined /></li>
            </Link>
            }/>
              <Tooltip  place='right' text='#' toggle_btn={ 
               <Link to='#'>
                  <li  onClick={()=>changeCurrentMenu(7)}   className={activeMenu === 7 ? 'active bg-main' : ''}><SummarizeOutlined /></li>
              </Link>
            }/>
              <Tooltip  place='right' text='#' toggle_btn={
             <Link to='#'>
               <li  onClick={()=>changeCurrentMenu(8)}   className={activeMenu === 8 ? 'active bg-main' : ''}><AutoStoriesOutlined /></li>
            </Link>
            }/>
              <Tooltip  place='right' text='#' toggle_btn={
             <Link to='#'>
               <li  onClick={()=>changeCurrentMenu(9)}   className={activeMenu === 9 ? 'active bg-main' : ''}><CastForEducationOutlined /></li>
            </Link>
            }/>
              <Tooltip  place='right' text='#' toggle_btn={ 
             <Link to='#'>
               <li  onClick={()=>changeCurrentMenu(10)}   className={activeMenu === 10 ? 'active bg-main' : ''}><TopicOutlined /></li>
            </Link> 
            }/>   
        </ul> 
        <div className="toggle-menu text-light">M</div>
        <ul>
         <Tooltip  place='right' text='#' toggle_btn={
             <Link to='#' className='icon-red'>
                 <li><LogoutTwoTone /></li>
             </Link>
            }/>
        </ul> 
     </Content>
  )
}


const Content = styled.div`
  min-width:80px;
  max-width:80px;
  background:var(--ed-white);
  height:100vh;
  display:flex;
  align-items:center;
  flex-direction:column;
  justify-content:space-between;
  padding:20px 10px;
  padding-top:100px;
  border-right:1px solid #eaeaee;
  position:fixed;
  left:0px;
  top:0px;
  z-index:100;

 

  ul{
    padding:0px;
    margin:0px;
    display:flex;
    align-items:center; 
    justify-content:center;
    flex-direction:column;

    .icon-red{
        li svg{
            fill:var(--ed-red);
        }
    }

    li.active{
        svg{
            fill:var(--ed-white);
        }   
    }

    li{
        border-radius:100%;
        width:40px;
        min-width:40px;
        height:40px; 
        margin:5px 0px;
        display:flex;
        transition:all 1s ease-in-out;
        cursor:pointer;
        align-items:center; 
       justify-content:center;

       svg{
           width:22px;
           height:22px;
           margin:0px !important;
           fill:var(--ed-blue-dark);
       }
    }
  }
`;

export default SidebarLeft