import { Search, SummarizeOutlined } from '@mui/icons-material';
import React, { useRef, useState } from 'react'
import { Form } from 'react-bootstrap';
import { AcademiclevelDataOptions, ClassDataOptions } from '../../../General/components/InstituteData';
import ListDebts from '../../components/Table/ListDebts';
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import BallotOutlinedIcon from '@mui/icons-material/BallotOutlined';
import ListTransportsDebts from '../../components/Table/ListTransportsDebts';
import SwitchFromPages from '../../../General/components/SwitchFromPages';




function ListTransportDebts() {
  document.title = "Lista dos alunos devedores (Transporte escolar)";
  const [SelectedClass, setSelectedClass] = useState(null);
  const [CurrentMenu, setCurrentMenu] = useState(0);
  const ChildRef = useRef();

  const FilterByClass = (e) => {
    setSelectedClass(e.target.value);
    setTimeout(() => {
      ChildRef.current.loadData(e.target.value);
    }, 200);
  }

  const ChangeMenu = (e) => {
    setCurrentMenu(e);
  }

  return (
    <div>
      <div className="ed-space">
        <div className='ed-flex'>
          <Form>
            <div className='search-box'>
              <Form.Group>
                <div className="ed-flex m0 fill">
                  <Search />
                  <div className="block col ml-2">
                    <Form.Select className='col' onChange={FilterByClass} select>
                      <ClassDataOptions />
                    </Form.Select>
                  </div>
                </div>
              </Form.Group>
            </div>
          </Form>
        </div>
        <div className="ed-flex">
          <SwitchFromPages link={`transportpayments`}
            menu='5' menu_item='17' toggle_btn={
              <div className='btn bg-main ml-2 mr-2'>
                <SummarizeOutlined /> Lista de pagamentos
              </div>
            } />
        </div>
      </div> 
      <div className="eduall-table">
        <ListTransportsDebts ref={ChildRef} CurrentMenu={CurrentMenu} Class={SelectedClass} />
      </div>
    </div>
  )
}

export default ListTransportDebts
