export default function NumberToLetters(input) {
  const units = ["zero","um","dois","três","quatro","cinco","seis","sete","oito","nove"];
  const teens = ["dez","onze","doze","treze","quatorze","quinze","dezesseis","dezessete","dezoito","dezenove"];
  const tens = ["","dez","vinte","trinta","quarenta","cinquenta","sessenta","setenta","oitenta","noventa"];
  const hundreds = ["","cento","duzentos","trezentos","quatrocentos","quinhentos","seiscentos","setecentos","oitocentos","novecentos"];

  const scales = [
    { singular: "",       plural: ""       }, // unidades
    { singular: "mil",    plural: "mil"    }, // mil não pluraliza
    { singular: "milhão", plural: "milhões"},
    { singular: "bilhão", plural: "bilhões"},
    { singular: "trilhão",plural: "trilhões"},
  ];

  const num = Number(input);
  if (!Number.isFinite(num)) return "Valor inválido";
  if (num < 0 || num > 999999999999.99) return "Número fora do intervalo suportado";

  // === Trunca para 2 casas decimais ===
  const inteiro = Math.floor(num);
  const centesimos = Math.floor((num - inteiro) * 100);

  if (inteiro === 0 && centesimos === 0) return "zero";

  function belowHundred(n) {
    if (n < 10) return units[n];
    if (n < 20) return teens[n - 10];
    const t = Math.floor(n / 10), u = n % 10;
    return u ? `${tens[t]} e ${units[u]}` : tens[t];
  }

  function belowThousand(n) {
    if (n === 0) return "";
    if (n === 100) return "cem";
    const c = Math.floor(n / 100);
    const r = n % 100;
    const parts = [];
    if (c) parts.push(hundreds[c]);
    if (r) {
      if (c) parts.push("e");
      parts.push(belowHundred(r));
    }
    return parts.join(" ");
  }

  function toChunks(n) {
    const chunks = [];
    let value = n;
    while (value > 0) {
      chunks.unshift(value % 1000);
      value = Math.floor(value / 1000);
    }
    return chunks;
  }

  const chunks = inteiro === 0 ? [0] : toChunks(inteiro);

  const pieces = [];
  for (let i = 0; i < chunks.length; i++) {
    const groupVal = chunks[i];
    if (!groupVal) continue;

    const scaleIdx = chunks.length - 1 - i;
    if (scaleIdx === 0) {
      pieces.push({ text: belowThousand(groupVal), value: groupVal, scale: scaleIdx });
    } else if (scaleIdx === 1) {
      const text = groupVal === 1 ? "mil" : `${belowThousand(groupVal)} mil`;
      pieces.push({ text, value: groupVal, scale: scaleIdx });
    } else {
      const label = groupVal === 1 ? scales[scaleIdx].singular : scales[scaleIdx].plural;
      const prefix = groupVal === 1 ? "um" : belowThousand(groupVal);
      pieces.push({ text: `${prefix} ${label}`, value: groupVal, scale: scaleIdx });
    }
  }

  let extenso = "";
  for (let i = 0; i < pieces.length; i++) {
    extenso += pieces[i].text;
    if (i < pieces.length - 1) {
      const next = pieces[i + 1];
      const isLastJoin = i === pieces.length - 2;
      const needE =
        next.scale === 1 && next.value === 1 ||
        (isLastJoin && next.scale === 0 && next.value < 100);
      extenso += needE ? " e " : " ";
    }
  }

  if (centesimos > 0) {
    extenso += " vírgula " + belowHundred(centesimos);
  }

  return extenso.trim();
}
