import React, { useEffect, useState } from 'react'
import styled from 'styled-components'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button, Badge } from 'react-bootstrap'
import { InfoOutlined, Save } from '@mui/icons-material';
import DraggableModal from '../../../../../../General/components/DraggableModal';
import axios from 'axios';
import Hoot from '../../../../../../General/components/Hoot';
import ClearInputs from '../../../../../../General/components/ClearInputs';
import CRValue from '../../../../../../General/components/CRValue';
import { RichTextEditor } from '../../../../../../General/components/RichTextEditor';
import { toast } from 'react-hot-toast';
import { Update } from '@material-ui/icons';
import SelectSearch from 'react-select-search';
import { ClassDataOptions, GetClasstitle_byclass, GetSubject, GetTime, StudentsArray } from '../../../../../../General/components/InstituteData';
import StudentDetailsMenu from '../../../../../../Dashboard/components/elements/StudentDetailsMenu';
import UserOptionDropDown from '../../../../../../Dashboard/components/elements/UserOptionDropDown';
import SaveButton from '../../../../../../Dashboard/components/elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../../../../General/components/ModalAnimations';
import ReplaceWord from '../../../../../../General/components/ReplaceWord';
import RefreshList from '../../../../../../General/components/RefreshList';
import moment from 'moment';


function ContinuousAvaliationModal(props) {
  const [show, setShow] = useState(false);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});
  const [studentCode, setStudentCode] = useState(null);
  const [StudentsData, setStudentsData] = useState([]);
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [Founded, SetFounded] = useState(null);


  const [showBox, SetshowBox] = useState(false);
  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200);
  }

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };


  const INPUTS = {
    cn_avaliation_classSubject: CRValue("#cn_avaliation_classSubject").split("|")[2],
    cn_avaliation_score: CRValue("#cn_avaliation_score"),
    cn_avaliation_Date: CRValue("#cn_avaliation_date"),
    cn_avaliation_studentCode: studentCode,
    cn_avaliation_description: document.querySelectorAll(".modal form textarea").length >= 1 ?
    document.querySelector(".modal form textarea").value : ""
  };

  const FORMURL = [
    Hoot() + "eduallregisterctnavlpoint/post",
    Hoot() + "eduallattendancecheckpaidmonth/",
    props.get ? props.get : '',
    props.url ? props.url : '',
    Hoot() + "eduallgetstudentsbyclass/"
  ];
 

  const GET_DATA = async () => {
    if (props.update) {
      try { 
        const response = await axios.get(FORMURL[2]);
         setTimeout(() => {
          if (response.data.length > 0) {


            console.clear();
            console.log(response.data[0]);

            const data = response.data[0];
 
            if (document.querySelector("#cn_avaliation_classSubject"))
              document.querySelector("#cn_avaliation_classSubject").value = data.ed_cn_avl_subClass;
            
            if (document.querySelector("#cn_avaliation_score"))
              document.querySelector("#cn_avaliation_score").value = data.ed_cn_avl_score;
             
            
            if (document.querySelector("#cn_avaliation_studentCode"))
              document.querySelector("#cn_avaliation_studentCode").value = data.ed_cn_avl_studentCode;
            
            if (document.querySelector("#cn_avaliation_description"))
              document.querySelector("#cn_avaliation_description").value = data.ed_cn_avl_description;
             
            INPUTS.cn_avaliation_classSubject = data.ed_cn_avl_subClass;
            INPUTS.cn_avaliation_score = data.ed_cn_avl_score; 
            INPUTS.cn_avaliation_studentCode = data.ed_cn_avl_studentCode;
            INPUTS.cn_avaliation_description = data.ed_cn_avl_description;

            setStudentCode(data.ed_cn_avl_studentCode);
             
            setField("cn_avaliation_classSubject", data.ed_cn_avl_subClass);
            setField("cn_avaliation_score", data.ed_cn_avl_score); 
            setField("cn_avaliation_studentCode", data.ed_cn_avl_studentCode);
            setField("cn_avaliation_description", data.ed_cn_avl_description); 


            const formattedDate = moment(data.ed_cn_avl_date).format('YYYY-MM-DD'); 
          
            if(document.querySelector("#cn_avaliation_date")){
            document.querySelector("#cn_avaliation_date").value = formattedDate;} 
            INPUTS.cn_avaliation_Date = formattedDate;  


            if (data?.ed_cn_avl_date) {
              const formattedDate1 = moment(data.ed_cn_avl_date).format('YYYY-MM-DD');
              setForm(prev => ({
                ...prev,
                cn_avaliation_Date: formattedDate1
              }));
            }

        } else {
          toast.error("Lamentamos mas não foi possivel encontrar a informação selecionada 1 !");
        }
         }, 500);
      } catch (error) {
        console.clear();
        console.log(FORMURL[1])
        toast.error("Lamentamos mas não foi possivel encontrar a informação selecionada 2 !");
      }
    }
  }


  const GetStudentsByClass = async (e) => {
    setStudentsData([]);
    try {
      const response = await axios.get(FORMURL[4] + e);
      const students = [];
      if (response.data.length > 0) {
        response.data.map((item, index) => {
          students.push({ name: item.ed_student_name, value: item.ed_student_id });
        });
      }
      setStudentsData(students);
    } catch (error) {
      toast.error("Lamentamos mas não foi possivel encontrar a informação selecionada !");
    }
  }


  const setField = (field, value) => {
    setForm({
      ...form,
      [field]: value
    })

    if (!!errors[field]) {
      setErrors({
        ...errors,
        [field]: null
      });
    }
  }


  const validateForm = () => {
    setRegisterStatus(0);
    const { cn_avaliation_classSubject, cn_avaliation_score, cn_avaliation_Date } = form;
    const NewErrors = {};

    if (INPUTS.cn_avaliation_classSubject === "" || INPUTS.cn_avaliation_classSubject === " ") {
      if (!cn_avaliation_classSubject || cn_avaliation_classSubject === '') NewErrors.cn_avaliation_classSubject = 'Selecione a turma';
    } else { if (!cn_avaliation_classSubject) { setField("cn_avaliation_classSubject", INPUTS.cn_avaliation_classSubject); } }

    if (INPUTS.cn_avaliation_score === "" || INPUTS.cn_avaliation_score === " ") {
      if (!cn_avaliation_score || cn_avaliation_score === '') NewErrors.cn_avaliation_score = 'adicione pontos';
    } else { if (!cn_avaliation_score) { setField("cn_avaliation_score", INPUTS.cn_avaliation_score); } }

    if (studentCode === null) NewErrors.cn_avaliation_code = 'Selecione um estudante';

    if (INPUTS.cn_avaliation_Date === "" || INPUTS.cn_avaliation_Date === " ") {
      if (!cn_avaliation_Date || cn_avaliation_Date === '') NewErrors.cn_avaliation_Date = 'Selecione uma data valida';
    } else { if (!cn_avaliation_Date) { setField("cn_avaliation_Date", INPUTS.cn_avaliation_Date); } }

    return NewErrors;
  }


  const FormSubmit = (e) => {
    e.preventDefault();
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os  campos");
      console.clear();
      console.log(formErrors);
      setRegisterStatus(1);
    } else {

      const SUBMIT_INPUTS = {
        cn_avaliation_score: INPUTS.cn_avaliation_score,
        cn_avaliation_subClass: INPUTS.cn_avaliation_classSubject,
        cn_avaliation_studentCode: INPUTS.cn_avaliation_studentCode,
        cn_avaliation_description: INPUTS.cn_avaliation_description,
        cn_avaliation_date: INPUTS.cn_avaliation_Date,
      };


      console.clear()
      console.log(SUBMIT_INPUTS);

      if (!props.update) {
        try {
          axios.post(FORMURL[0], SUBMIT_INPUTS).then((e) => {
            toast.success("Pontuação atribuida com sucesso !");
            setForm({}); 
            setRegisterStatus(2);
              RefreshList(`.el-refresh-list`)
          }).catch((error) => {
            console.clear();
            setRegisterStatus(1);
            console.log(error.response);
            toast.error("Lamentamos mas não foi  possivel executar esta ação !");
          });
        } catch (error) {
          console.clear();
          setRegisterStatus(1);
          console.log(error.response);
          toast.error("Lamentamos mas não foi  possivel executar esta ação !");
        }
      } else {
        try {
          axios.put(FORMURL[3], SUBMIT_INPUTS).then(() => {
            toast.success("Pontuação atualizada com sucesso !");
            setForm({}); 
            setRegisterStatus(2);
              RefreshList(`.el-refresh-list`)
          }).catch((error) => {
            console.clear();
            console.log(error.response);
            setRegisterStatus(1);
            toast.error("Lamentamos mas não foi  possivel executar esta ação !");
          });
        } catch (error) {
          console.clear();
          setRegisterStatus(1);
          console.log(error.response);
          toast.error("Lamentamos mas não foi  possivel executar esta ação !");
        }
      }


    }
  };


  const GetStudentCode = (e) => {
    setStudentCode(e);
  }

  const handleInput = (e) => {
    switch (e.target.id) {
      case "cn_avaliation_classSubject":
        GetStudentsByClass(e.target.value.split("|")[0] * 1);
        INPUTS.cn_avaliation_classSubject = e.target.value.split("|")[2];
        setField("cn_avaliation_classSubject", e.target.value.split("|")[2]);
        break;
      case "cn_avaliation_score":
        setField("cn_avaliation_score", e.target.value);
        INPUTS.cn_avaliation_score = e.target.value;
        break;
      case "cn_avaliation_Date":
        setField("cn_avaliation_Date", e.target.value);
        INPUTS.cn_avaliation_Date = e.target.value;
       break;
       case "cn_avaliation_description":
        setField("cn_avaliation_description", e.target.value);
        INPUTS.cn_avaliation_description = e.target.value;
       break;
   default:
    }
  }

  return (
    <div>
      <div onClick={handleShow}>
        {props.toggle_btn ? props.toggle_btn : <button className="btn bg-main"><AddCircleOutlineIcon /> Atributos e pontos</button>}
      </div>
      <Modal size='md' className={showBox ? ModalAnimationShow() : ModalAnimationClose()} centered dialogAs={DraggableModal} show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>{props.title ? props.title : 'Atributos '} de pontos</h5>
            </div>
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={FormSubmit}>
          <Modal.Body className='scrollLimit'>
            <div  className={props.update ? "d-none" : ""}>
              <Form.Group className="mb-3">
                <Form.Label>Turma - {ReplaceWord("Disciplina", true)} <span className='text-danger ml-2'>*</span></Form.Label>
                <Form.Select  onChange={handleInput} className={!!errors.cn_avaliation_classSubject && 'is-invalid'} value={form.cn_avaliation_classSubject}
                  isInvalid={!!errors.cn_avaliation_classSubject} id="cn_avaliation_classSubject">
                  {props.data.map((item, index) => {
                    return (<option value={item.ed_tch_subject_class + "|" + item.ed_tch_subject_code + "|" + item.ed_tch_subject_id}>
                      <GetClasstitle_byclass ID={item.ed_tch_subject_class} />
                      ( <GetSubject ID={item.ed_tch_subject_code} /> )
                    </option>)
                  })}
                </Form.Select>
                <Form.Control.Feedback type='invalid'>{errors.cn_avaliation_classSubject}</Form.Control.Feedback>
              </Form.Group>
            </div>
            {
              props.update ? <></> :
                <>
                  {StudentsData.length >= 1 ?
                    <>
                      <Form.Group className="mb-3">
                        <div className="ed-space">
                          <div>
                            <Form.Label>Nome do estudante <span className='text-danger ml-2'>*</span></Form.Label>
                          </div>
                          <div className='ed-flex'>
                            {studentCode !== null ? <StudentDetailsMenu student_id={studentCode} toggle_btn={<div className='btn-pm-info'><InfoOutlined /></div>} /> : <></>}
                          </div>
                        </div>
                        <div className={`select-search-item  ${errors.cn_avaliation_code ? 'error' : ''}`}>
                          <SelectSearch onChange={(e) => GetStudentCode(e)} value={studentCode} options={StudentsData} search={true}
                            placeholder="Selecione um aluno" />
                        </div>
                        <small className="text-danger">{errors.cn_avaliation_code}</small>
                      </Form.Group>
                    </> :
                    <></>
                  }
                </>
            }
            <div>
              <Form.Group className="mb-3">
                <Form.Label>Pontos <span className='text-danger ml-2'>*</span></Form.Label>
                <Form.Control text="number" onChange={handleInput} className={!!errors.cn_avaliation_score && 'is-invalid'} value={form.cn_avaliation_score}
                  isInvalid={!!errors.cn_avaliation_score} id="cn_avaliation_score" />
                <Form.Control.Feedback type='invalid'>{errors.cn_avaliation_score}</Form.Control.Feedback>
              </Form.Group>
            </div>
            <div className={props.update ? "d-none" : ""}>
              <Form.Group className="mb-3">
                <Form.Label>Data <span className='text-danger ml-2'>*</span></Form.Label>
                <Form.Control type="date" onChange={handleInput} className={!!errors.cn_avaliation_Date && 'is-invalid'} value={form.cn_avaliation_Date}
                  isInvalid={!!errors.cn_avaliation_Date} id="cn_avaliation_Date" />
                <Form.Control.Feedback type='invalid'>{errors.cn_avaliation_Date}</Form.Control.Feedback>
              </Form.Group>
            </div>
            <div>
              <Form.Group className="mb-3">
                <Form.Label>Descrição</Form.Label>
                 <Form.Control as={"textarea"} id='cn_avaliation_description' 
                 rows={8} onChange={handleInput}  onPaste={handleInput}  />
              </Form.Group>
            </div>
          </Modal.Body>
          <Modal.Footer>
            <div className="ed-space"> 
              <div className="ed-flex"></div>
              <div className="ed-flex">
                <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                {props.update ? (Founded === false ? <div></div> :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />}
              </div>
            </div>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  )
}

export default ContinuousAvaliationModal
