import React, { useState } from 'react';
import { Modal } from 'react-bootstrap';
import DraggableModal from '../../../General/components/DraggableModal';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import CreateTemporaryEduallAccountAlert from './CreateTemporaryEduallAccountAlert';
import UserOptionDropDown from '../elements/UserOptionDropDown';

function NewTemporaryUserAccountModal(props) {
    const [show, setShow] = useState(false);
    const [showBox, setShowBox] = useState(false);

    const handleClose = () => {
        setShowBox(false);
        setTimeout(() => {
            setShow(false);
        }, 1200);
    };

    const handleShow = () => {
        setShowBox(true);
        setShow(true);
    };

    return (
        <div>
            <div onClick={handleShow}>
                {props.toggle_btn ? props.toggle_btn : (
                    <button className="btn btn-main bg-main">Criar Conta</button>
                )}
            </div>

            <Modal size="lg" dialogAs={DraggableModal} centered className={showBox ? ModalAnimationShow() : ModalAnimationClose()}
                show={show} onHide={handleClose}  >
                <Modal.Header closeButton>
                    <Modal.Title>
                        <div className="ed-wrap align-center">
                            <UserOptionDropDown />
                            <h5>Criar conta de utilizador </h5>
                        </div>
                    </Modal.Title>
                </Modal.Header>
                <Modal.Body className="scrollLimit">
                    <CreateTemporaryEduallAccountAlert
                        email={props.email}
                        userName={props.userName}
                        country={props.country || "ao"}
                        gender={props.gender}
                        expand={true}
                    />
                </Modal.Body>
            </Modal>
        </div>
    );
}

export default NewTemporaryUserAccountModal;
