import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Delete, Edit } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import TableGrid from '../../../General/components/TableGrid';
import RefreshButton from '../../../General/components/RefreshButton';
import NewProductCategoryModal from '../modal/NewProductCategoryModal';
import NumberToPrice from '../../../General/components/NumberToPrice';
import Chart from 'react-apexcharts';
import styled from 'styled-components';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdf, PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import DownloadInvoicePDFButton from '../../../General/components/DownloadInvoicePDFButton';
import moment from 'moment';

const TABLEURL = Hoot() + "eduallgetallproductsales/get/";


const columns = [
    {
        field: 'invoicecode',
        headerName: 'Nº da fatura',
        resizable: true,
        width: 180,
    },
    {
        field: 'nif',
        headerName: 'NIF do Cliente',
        resizable: true,
        width: 150,
    },
    {
        field: 'productsAdded',
        headerName: 'Produtos Adicionados',
        resizable: true,
        width: 300,
        cellRenderer: (params) => {
            const products = params.data.productsAdded || [];
            return (
                <select
                    className='form-select mt-1' style={{ fontSize: "13px" }}
                    onChange={(e) => {
                        const selectedProduct = products.find((product) => product.ed_product_name === e.target.value);
                        params.api.getRowNode(params.node.id).setDataValue('selectedProduct', selectedProduct);
                    }}
                >
                    {products.map((product, index) => (
                        <option key={index} value={product.ed_product_name}>
                            {product.ed_product_name} - {NumberToPrice(product.ed_sale_product_price)} {product.coin}  * ({product.ed_sale_product_quantity})
                        </option>
                    ))}
                </select>
            );
        }
    },
    {
        field: 'totalPaid',
        headerName: 'Total Pago com Desconto',
        resizable: true,
        width: 200,
    },
    {
        field: 'discount',
        headerName: 'Desconto (%)',
        resizable: true,
        width: 150,
    },
    {
        field: 'discountValue',
        headerName: 'Valor do Desconto',
        resizable: true,
        width: 200,
    },
    {
        field: 'date',
        headerName: 'Data de pagamento',
        resizable: true,
        width: 200,
    },
    {
        field: 'action',
        headerName: 'Ação',
        resizable: true,
        cellRenderer: (props) => {
            return (
                <div className="ed-flex"> 
                    <DownloadInvoicePDFButton documentId={props.data.salecode} /> 
                    <DeleteModal
                        title='Esta venda'
                        url={Hoot() + `edualldeletesale/delete/${props.data.id}`}
                        message='Venda deletada com sucesso !'
                        toggle_btn={
                            <button className="btn-circle bg-danger ml-2 text-light">
                                <Delete />
                            </button>
                        }
                    />
                </div>
            );
        }
    }
];

function ProductSalesTables() {
    const [data, setData] = useState([]);
    const [load, setLoaded] = useState(false);
    const [LoadStatus, setLoadStatus] = useState(null);
    const [chartData, setChartData] = useState({ series: [], categories: [] });

    async function loadData() {
        setLoadStatus(0);
        try {
            setLoaded(false);
            const response = await axios.get(TABLEURL);
            const rows = [];
            response.data.map((item, index) => {
                let totalPaid = 0;
                let totalProducts = 0;
                let totalDiscountValue = 0;
                let discountPercentage = item.ed_product_sale_discount;
                let coinSymbol = item.coin_symbol || '';

                let productsAdded = item.products.map(product => ({
                    ed_product_name: product.ed_product_name,
                    ed_sale_product_quantity: product.ed_sale_product_quantity,
                    ed_sale_product_price: product.ed_sale_product_price,
                    coin: coinSymbol
                }));

                item.products.forEach((product) => {
                    totalProducts += product.ed_sale_product_quantity;
                    let productTotal = product.ed_sale_product_price * product.ed_sale_product_quantity;
                    totalPaid += productTotal - (productTotal * discountPercentage / 100);
                    totalDiscountValue += productTotal * discountPercentage / 100;
                });

                rows.push({
                    id:item.ed_product_sale_id,
                    index: index + 1,
                    invoicecode: item.ed_product_sale_invoiceCode,
                    salecode:item.ed_product_sale_invoiceFile,
                    productName: '',
                    selectedProduct: null,
                    nif: item.ed_product_sale_nif || 'N/A',
                    productsAdded: productsAdded,
                    totalPaid: `${NumberToPrice(totalPaid)} ${coinSymbol}`,
                    discount: `${discountPercentage}%`,
                    discountValue: `${NumberToPrice(totalDiscountValue)} ${coinSymbol}`,
                    title: item.ed_product_category_name,
                    date: moment(item.ed_product_sale_date).format('DD [de] MMMM [de] YYYY [às] HH:mm'),
                    action: "",
                });
            });
            setData(rows);

            const productSales = {};
            let COIN = "";
            const SalesData = response.data;

            SalesData.forEach(item => {
                let discountPercentage = item.ed_product_sale_discount;
                COIN = item.coin_symbol || 'AOA';

                item.products.forEach(product => {
                    let productTotal = product.ed_sale_product_price * product.ed_sale_product_quantity;
                    let discountValue = (productTotal * discountPercentage) / 100;
                    let totalPaid = productTotal - discountValue;

                    if (!productSales[product.ed_product_name]) {
                        productSales[product.ed_product_name] = {
                            totalQuantity: 0,
                            totalRevenue: 0,
                            totalDiscountValue: 0
                        };
                    }

                    productSales[product.ed_product_name].totalQuantity += product.ed_sale_product_quantity;
                    productSales[product.ed_product_name].totalRevenue += totalPaid;
                    productSales[product.ed_product_name].totalDiscountValue += discountValue;
                });
            });


            const categories = Object.keys(productSales);
            const totalQuantities = categories.map(name => productSales[name].totalQuantity);
            const totalRevenues = categories.map(name => productSales[name].totalRevenue);
            const totalDiscountValues = categories.map(name => productSales[name].totalDiscountValue);

            setChartData({
                series: [
                    { name: "Quantidade Vendida", data: totalQuantities },
                    { name: `Faturamento Total ( ${COIN} )`, data: totalRevenues },
                    { name: `Valor de Desconto ( ${COIN} )`, data: totalDiscountValues }
                ],
                categories
            });

            setTimeout(() => {
                setLoaded(true);
            }, 200);
            setLoadStatus(2);

            console.clear();
            console.log(rows);
        } catch (error) {
            setLoadStatus(1);
            setLoaded(false);
            console.clear();
            console.log(error.response.data);
        }
    }

    useEffect(() => {
        loadData();
    }, []);

    const options = {
        chart: {
            type: 'bar',
            height: 400
        },
        colors: ['var(--ed-red)', 'var(--ed-green)'],
        plotOptions: {
            bar: {
                horizontal: false,
                columnWidth: '40%',
                dataLabels: { position: 'top' }
            }
        },
        dataLabels: {
            enabled: true,
            formatter: (val) => val.toLocaleString()
        },
        stroke: { show: true, width: 2, colors: ['transparent'] },
        xaxis: { categories: chartData.categories },
        yaxis: { labels: { formatter: (val) => val.toLocaleString() } },
        legend: { position: 'top' },
        tooltip: {
            y: { formatter: (val) => NumberToPrice(val) }
        }
    };

    if (load) {
        return (
            <div id="ed-custom-table-data" >
                <TableGrid
                    TableHead={columns}
                    TableBody={data}
                    TableHeight={400}
                    TableTitle="Vendas efetuadas"
                    TableBtn={
                        <div className='ed-flex' >
                            <button id='ed-custom-table-data-btn'
                                onClick={() =>
                                    ExportDataToTablesToPdf({
                                        fileName: "Lista das vendas efetuadas",
                                        headerId: null,
                                        contentId: "ed-custom-table-data",
                                        footerId: null,
                                        rotation: "landscape",
                                        buttonId: "ed-custom-table-data-btn",
                                        customHeader: "Lista das vendas efetuadas",
                                        excludedColumns: ["Ação"]
                                    })
                                }
                                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
                            </button>
                            <button className='btn-icon btn btn-export-data ml-2'
                                onClick={() => ExportDataForTablesExcel("Lista das vendas efetuadas ", ["Ação"], "ed-custom-table-data")}><PiMicrosoftExcelLogoDuotone />
                            </button>
                            <RefreshButton action={loadData} status={LoadStatus} />
                        </div>}
                />
                <div className="mt-4">
                    <Container>
                        <Chart options={options} series={chartData.series} type="bar" height={400} />
                    </Container>
                </div>
            </div>
        );
    } else {
        return (
            <div>
                <div className="d-none">*</div>
                <TableGrid
                    TableHead={columns}
                    TableBody={[]}
                    TableTitle="Vendas efetuadas"
                    TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
                />
            </div>
        );
    }
}


const Container = styled.div`
    width:100%; 
    border-radius:6px;   
    padding:20px 0px;
    min-height:520px;
    height:auto;
    background:var(--ed-white);  
    box-shadow:var(--ed-shadow-df);
    padding:20px;
`;



export default ProductSalesTables;









