import React, { useEffect, useState } from 'react'
import TableGrid from '../../../General/components/TableGrid';
import axios from 'axios';
import { GetServiceTitle, GetserviceCoin } from '../../../General/components/InstituteData';
import { PreviewOutlined, PrintOutlined } from '@mui/icons-material';
import { Link } from 'react-router-dom';
import NumberToPrice from '../../../General/components/NumberToPrice';
import Hoot from '../../../General/components/Hoot';
import PP_feepaymentsstatus from './PP_feepaymentsstatus';
import TitleBlock from '../../Components/TitleBlock';
import moment from "moment";
import ReplaceWord from '../../../General/components/ReplaceWord';
 

 
const columns = [ 
  { field: 'index',
    resizable: true ,
    width:60,
    headerName: 'Nº', 
  },
  {
    field: 'subject',
    resizable: true ,
    headerName:ReplaceWord("Disciplina"),  
    width:280 
  },  
  {
    field: 'class',
    resizable: true ,
    headerName: 'Turma',  
    width:280 
  },  
  {
    field: 'classroom',
    resizable: true ,
    headerName: 'Sala',  
    width:280 
  },  
  {
    field: 'date',
    resizable: true ,
    headerName: 'Data da prova',  
    width:280 
  },  
  {
    field: 'registerdate',
    resizable: true ,
    headerName: 'Data de publicação',  
    width:280 
  },  
];


function PP_exams({data, notitle}) {
  const [Data, setData] = useState([]); 
  const [Loading , setLoading] =  useState(false);

  async function loadData(){ 
    setLoading(false);
    console.log(data)
    const rows = [];
    data.map((item, index)=>{
      rows.push({
        index:index+1,
        subject:item.ed_subject_title,
        class:item.ed_class_title,
        classroom:item.ed_class_room,
        date:moment(item.ed_student_exam_date).format("Y-MM-DD - HH:mm"),
        registerdate:item.ed_student_exam_registerDate,
     });
    })
    setData(rows); 
    setLoading(true);
  }

  useEffect(()=>{
      loadData(); 
  },[]);
 
 
   if(Loading === true){
    return (
      <div>
        <div className={notitle ? "d-none": "mt-2 mb-2"}>
           <TitleBlock title="Calendario de provas"/>
        </div>
        <TableGrid
            TableHead={columns}
            TableBody={Data}  
            TableTitle='Calendario de provas' 
            TableHeight={data.length <= 5 ? 200 : 600}
            NoButtons
        />   
        <br />
    </div>
    ) 
   }else{
    return (
      <div>
        <div className={notitle ? "d-none": "mt-2 mb-2"}>
           <TitleBlock title="Calendario de provas"/>
        </div>
        <TableGrid
            TableHead={columns}
            TableBody={[]}  
            TableTitle='Calendario de provas' 
            TableHeight={data.length <= 5 ? 200 : 600}
            NoButtons
        />   
        <br />
    </div>
    ) 
   }
}

export default PP_exams
