import React, { useState } from 'react'
import AddCircleOutlineIcon from '@mui/icons-material/AddCircleOutline';
import { Modal, Form, Button } from 'react-bootstrap'
import { Save } from '@mui/icons-material';
import DraggableModal from '../../../General/components/DraggableModal';
import { RichTextEditor } from '../../../General/components/RichTextEditor';
import { toast } from 'react-hot-toast';
import CRValue from '../../../General/components/CRValue';
import ClearInputs from '../../../General/components/ClearInputs';
import Hoot from '../../../General/components/Hoot';
import axios from 'axios';
import { Update } from '@material-ui/icons';
import { GetInstituteCode } from '../../../General/components/InstituteData';
import AuditoryRegister from '../../../General/components/AuditoryRegister';
import RefreshList from '../../../General/components/RefreshList';
import UserOptionDropDown from '../elements/UserOptionDropDown';
import SaveButton from '../elements/SaveButton';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';



function NewClassRoomModal(props) {
  const [show, setShow] = useState(false);
  const [form, setForm] = useState({});
  const [errors, setErrors] = useState({});
  const [RegisterStatus, setRegisterStatus] = useState(null);
  const [Founded, SetFounded] = useState(null);


  const [showBox, SetshowBox] = useState(false);
  const handleClose = () => {
    SetshowBox(false);
    setTimeout(() => {
      setShow(false);
    }, 1200);
  }

  const handleShow = () => {
    SetshowBox(true);
    setShow(true);
    setTimeout(() => {
      GET_DATA();
    }, 1000);
  };


  const INPUTS = {
    title: CRValue("#classroom_title"),
    description: CRValue(".modal form textarea")
  };

  const FORMURL = [
    Hoot() + "eduallclassroomregisterapi/post/",
    props.get ? props.get : '',
    props.url ? props.url : ''
  ];


  async function GET_DATA() {
    if (props.update) {
      try {
        const response = await axios.get(FORMURL[1]);
        if (response.data.length > 0) {
          document.querySelector("#classroom_title").value = response.data[0].ed_classroom_title;
          document.querySelector(".modal form textarea").value = response.data[0].ed_classroom_description;

          INPUTS.title = response.data[0].ed_classroom_title;
          INPUTS.description = response.data[0].ed_classroom_description;
        } else {
          toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
        }
      } catch (error) {
        toast.error("Lamentamos mas não foi  possivel encontrar a informação selecionada !");
      }
    }
  }

  const setField = (field, value) => {
    setForm({
      ...form,
      [field]: value
    })

    if (!!errors[field]) {
      setErrors({
        ...errors,
        [field]: null
      });
    }
  }


  const validateForm = () => {
    const { classroom_title } = form;
    const NewErrors = {};
    setRegisterStatus(0);

    if (INPUTS.title === "" || INPUTS.title === " ") {
      if (!classroom_title || classroom_title === '') NewErrors.classroom_title = 'Sala de aula invalida';
    } else { if (!classroom_title) { setField("classroom_title", INPUTS.title); } }

    return NewErrors;
  }



  const FormSubmit = (e) => {
    console.log(INPUTS);
    e.preventDefault();
    const formErrors = validateForm();
    if (Object.keys(formErrors).length > 0) {
      setErrors(formErrors);
      toast.error("Verifique todos os  campos");
      setRegisterStatus(1);
    } else {
      const SUBMIT_INPUTS = { title: INPUTS.title, description: INPUTS.description, institute_code: INPUTS.institute_code };

      if (!props.update) {
        try {
          axios.post(FORMURL[0], SUBMIT_INPUTS).then(() => {
            toast.success("Sala adicionada com sucesso !");
            setForm({});
            ClearInputs();
            RefreshList(`.el-refresh-list`)
            setRegisterStatus(2);
          }).catch((error) => {
            setRegisterStatus(1);
            const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
            toast.error(msg);
          });
        } catch (error) {
          setRegisterStatus(1); 
          const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
          toast.error(msg);
        }
      } else {
        try {
          axios.put(FORMURL[2], SUBMIT_INPUTS).then(() => {
            toast.success("Sala atualizada com sucesso !");
            setForm({});
            ClearInputs();
            RefreshList(`.el-refresh-list`)
            setRegisterStatus(2);
            setTimeout(() => {
              handleClose();
            }, 1500);
          }).catch((error) => {
            setRegisterStatus(1); 
            const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
            toast.error(msg);
          });
        } catch (error) {
          setRegisterStatus(1); 
          const msg = error?.response?.data?.msg || "Lamentamos mas não foi  possivel executar esta ação !";
          toast.error(msg);
        }
      }
    }
  };


  const handleInput = (e) => {
    switch (e.target.id) {
      case "classroom_title":
        setField("classroom_title", e.target.value)
        INPUTS.title = e.target.value
        break;
      case "classroom_description":
        setField("classroom_description", e.target.value)
        INPUTS.description = e.target.value
        break;
      default:
    }
  }


  return (
    <div>
      <div onClick={handleShow}>
        {
          props.toggle_btn ? props.toggle_btn : <button className='btn btn-main bg-main' onClick={handleShow}><AddCircleOutlineIcon /> Registrar sala</button>
        }
      </div>
      <Modal size='lg' className={showBox ? ModalAnimationShow() : ModalAnimationClose()}
        centered dialogAs={DraggableModal} show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title>
            <div className="ed-wrap align-center">
              <UserOptionDropDown />
              <h5>{props.title ? props.title : 'Registrar '} sala</h5>
            </div>
          </Modal.Title>
        </Modal.Header>
        <Form onSubmit={FormSubmit}>
          <Modal.Body className='scrollLimit'>
            <Form.Group className="mb-3"  >
              <Form.Label>Nº da sala<span className="text-danger ml-2">*</span> </Form.Label>
              <Form.Control onChange={handleInput} className={!!errors.classroom_title && 'is-invalid'} value={form.classroom_title} isInvalid={!!errors.classroom_title}
                type="number" id="classroom_title" autoFocus />
              <Form.Control.Feedback type='invalid'>{errors.classroom_title}</Form.Control.Feedback>
            </Form.Group>
            <Form.Group className="mb-3"  >
              <Form.Label>Descrição</Form.Label>
              <div className="custom-editor">
                <textarea className="form-control" onChange={handleInput} id='classroom_description' rows={10} > </textarea>
              </div>
            </Form.Group>
          </Modal.Body>
          <Modal.Footer>
            <div className="ed-space">
              <div className="ed-flex"></div>
              <div className="ed-flex">
                <Button className='bg-light text-dark' onClick={handleClose}> Cancelar </Button>
                {props.update ? (Founded === false ? <div></div> :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />) :
                  <SaveButton icon={props.title ? <Update /> : <Save />} title={props.title ? props.title : 'Salvar'} status={RegisterStatus} />}
              </div>
            </div>
          </Modal.Footer>
        </Form>
      </Modal>
    </div>
  )
}

export default NewClassRoomModal