import React from 'react'
import { styled } from 'styled-components'
import EduallPlayer from '../../../General/components/VideoPlayer/PlayerComponents/EduallPlayer';
const VideoSource  = {
  source: require("../../../Assets/videos/lessons/v0.mp4"),
  poster: require("../../../Assets/videos/lessons/v0.jpg"),
  currentTimeStatus:null,
  fullTimeVideo:null
}


function PlayerContainer({data}) {
  return (
    <>
   {(data.video !== null && data.video !== undefined) ?   
    <PlayerArea className='bg-black'>
      <div className="video-area">  
            <EduallPlayer poster={data.poster}  src={data.video} title={data.title} />  
      </div>
    </PlayerArea>
    : <></>} 
   </>
  )
}

const PlayerArea = styled.div` 
   width:100%;
   min-height:80vh;
   max-height:80vh; 
   background:#0000;

   .video-area{ 
      width:100%;
      height:80vh;
      max-height:80vh;    

        video{
            border-radius:0px !important;
        } 
   }
`;

export default PlayerContainer
