import React from 'react'
import PaidServicesTable from '../../components/Table/PaidServicesTable'
import { AddCircleOutline } from 'react-ionicons';
import SwitchFromPages from '../../../General/components/SwitchFromPages';

function ServicepaymentsList() {
  document.title = "Pagamento de serviços";

  return (
    <div>
      <div className="ed-space">
        <div></div>
        <div>
          <SwitchFromPages link='servicepayments' menu="5" menu_item="50"
          toggle_btn={<button className="btn bg-main"><AddCircleOutline/> Pagar serviços</button>} />
        </div>
      </div>
      <PaidServicesTable />
    </div>
  )
}

export default ServicepaymentsList