import React, { useEffect, useState } from 'react'
import Table from './Table';
import axios from 'axios';
import { Delete, Edit, PreviewOutlined } from '@mui/icons-material';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import Hoot from '../../../General/components/Hoot';
import DeleteModal from '../elements/DeleteModal';
import NewVehicleModal from '../modal/NewVehicleModal'; 
import TableGrid from '../../../General/components/TableGrid'; 
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import RefreshButton from '../../../General/components/RefreshButton';


const TABLEURL = Hoot() + "edualltransportvehicleget/get/";

const columns = [
    {
        field: 'index',
        headerName: 'Nº',
        resizable: true,
        width: 80
    },
    {
        field: 'model',
        headerName: 'Modelo',
        sortable: false,
        resizable: true,
        width: 270,
    },
    {
        field: 'plate',
        headerName: 'Matrícula (Placa)',
        sortable: false,
        resizable: true,
        width: 180,
    },
    {
        field: 'driver',
        headerName: 'Motorista',
        sortable: false,
        resizable: true,
        width: 180,
    },
    {
        field: 'type',
        headerName: 'Tipologia',
        sortable: false,
        resizable: true,
        width: 180,
    },
    {
        field: 'vehiclevalue',
        headerName: 'Valor da viatura',
        sortable: false,
        resizable: true,
        width: 180,
    },
    {
        field: 'date',
        headerName: 'Data de aquisição',
        sortable: false,
        resizable: true,
        width: 180,
    },
    {
        field: 'capacity',
        headerName: 'Capacidade',
        sortable: false,
        resizable: true,
        width: 180,
    },
    {
        field: 'action',
        headerName: 'Ação',
        resizable: true,
        cellRenderer: (props) => {
            return <div className="ed-flex">
                <NewVehicleModal title='Atualizar ' update='true' get={Hoot() + `edualltransportsinglevehicleget/get/${props.data.id}`}
                    url={Hoot() + `edualltransportvehicleupdate/update/${props.data.id}`} toggle_btn={
                        <button className="btn-circle bg-success text-light">
                            <Edit />
                        </button>
                    } />
                <DeleteModal title='este veiculo' url={Hoot() + `edualltransportvehicledelete/delete/${props.data.id}`}
                    message='Veiculo deletado com sucesso' toggle_btn={
                        <button className="btn-circle bg-danger ml-2 text-light">
                            <Delete />
                        </button>
                    } />
            </div>;
        }
    }
];



function VehiclesTable() {
    const [data, setData] = useState([]);
    const [LoadStatus, setLoadStatus] = useState(null);
    const [load, setLoaded] = useState(false);


    async function loadData() {
        try {
            setLoadStatus(0);
            setLoaded(false);
            const response = await axios.get(TABLEURL);
            const rows = [];
            response.data.map((item, index) => {
                rows.push({
                    index: index + 1,
                    id: item.ed_transport_vehicle_id,
                    model: item.ed_transport_vehicle_model,
                    image: Hoot() + item.ed_transport_vehicle_picture,
                    driver: item.ed_transport_driver_name,
                    plate: item.ed_transport_vehicle_plate,
                    capacity: item.ed_transport_vehicle_capacity,
                    type: item.ed_transport_vehicle_typology === "rent" ? "Aluguel" : "Compra",
                    vehiclevalue: item.ed_transport_vehicle_value,
                    date: item.ed_transport_vehicle_acquisition_date,
                })
            });
            setData(rows);
            setTimeout(() => {
                setLoaded(true);
            }, 200); 
            setLoadStatus(2);
        } catch (error) {
            setLoaded(true);
            setLoadStatus(1);
        }
    }


    useEffect(() => {
        loadData();
    }, []);



    if (load) {
        return (
            <div id="ed-custom-table-data">
                <TableGrid
                    TableHead={columns}
                    TableBody={data}
                    TableTitle='Lista de veículos'
                    TableBtn={
                        <div className='ed-flex'>
                            <button id='ed-custom-table-data-btn'
                                onClick={() =>
                                    ExportDataToTablesToPdf({
                                        fileName: "Lista de veículos",
                                        headerId: null,
                                        contentId:"ed-custom-table-data",
                                        footerId: null,
                                        rotation: "landscape",
                                        buttonId: "ed-custom-table-data-btn",
                                        customHeader: "Lista de veículos",
                                        excludedColumns: ["Ação"]
                                    })
                                }
                                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
                            </button>
                            <button className='btn-icon btn btn-export-data ml-2'
                                onClick={() => ExportDataForTablesExcel("lista de veículos", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
                            </button>
                            <RefreshButton action={loadData} status={LoadStatus} />
                        </div>
                    }
                />
            </div>
        )
    } else {
        return (
            <div>
                <div className="d-none">*</div>
                <TableGrid
                    TableHead={columns}
                    TableBody={data}
                    TableTitle='Lista de veículos'
                    TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
                />
            </div>)
    }
}

export default VehiclesTable