import React, { useState, useEffect } from 'react'
import axios from 'axios'
import { Delete, Edit, Refresh } from '@mui/icons-material';
import Hoot from '../../../General/components/Hoot';
import { GetServiceTitle, GetServicePriceNumb, GetServiceCointText } from '../../../General/components/InstituteData';
import DeleteModal from '../elements/DeleteModal';
import TableGrid from '../../../General/components/TableGrid';
import { Badge } from 'react-bootstrap';
import NewFinePriceModal from '../modal/NewFinePriceModal';
import { DeleteButton, EditButton, PrintButton, PreviewButton } from '../../../General/components/Buttons/TableButtons';
import RefreshButton from '../../../General/components/RefreshButton';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import NumberToPrice from '../../../General/components/NumberToPrice';

const TABLEURL = Hoot() + "eduallgetservicefines/get/";


const columns = [
  { field: 'index', headerName: 'Nº', width: 60 },
  {
    field: 'service',
    headerName: 'Nome do serviço',
    width: 300,
  },
  {
    field: 'vltype',
    headerName: 'Tipo de multa',
    width: 130,
    resizable: true, cellRenderer: (props) => {
      return props.data.vltype * 1 === 0 ? <Badge className='bg-info'>Percentagem</Badge> : <Badge className='bg-warning'>Valor Fixo</Badge>
    }
  },
  {
    field: 'value',
    headerName: 'Valor da multa',
    width: 160,
    sortable: false,
    resizable: true, cellRenderer: (props) => {
      return props.data.vltype * 1 === 0 ?
        <Badge className='bg-primary'>{props.data.value} % {' ( '} {NumberToPrice(Math.floor((props.data.value * 1 * props.data.service_price) / 100))}
          {' ' + (props.data.service_coin)} {' ) '} </Badge> :
        <Badge className='bg-warning'>{NumberToPrice(props.data.value)} {(props.data.service_coin)}</Badge>
    }
  },
  {
    field: 'scholarshipHolders',
    headerName: 'AP. aos Bolseiros',
    width: 150,
    resizable: true, cellRenderer: (props) => {
      return props.data.scholarshipHolders * 1 === 1 ? <Badge className='bg-danger'>Aplicar</Badge> : <Badge className='bg-secondary'>Não Aplicar</Badge>
    }
  },
  {
    field: 'incrementValue',
    headerName: 'Incrementar  valor',
    width: 210,
    sortable: false,
    resizable: true, cellRenderer: (props) => {
      return <> {props.data.incrementValue === 0 ?
        <span className='text-red'>Não Incrementar</span> :
        <span>Incrementar a cada {props.data.daysafterprevmonth} dias </span>}</>
    }
  },
  {
    field: 'daysafterprevmonth',
    headerName: 'AP. depois de',
    width: 120,
    sortable: false,
    resizable: true, cellRenderer: (props) => {
      return <> {props.data.daysafterprevmonth} dias</>
    }
  },
  {
    field: 'parentsChildrens',
    headerName: 'Anular para encarregados com +',
    width: 260,
    sortable: false,
    resizable: true, cellRenderer: (props) => {
      return <>{props.data.parentsChildrens >= 1 ?
        <Badge className='bg-dark text-light'> {props.data.parentsChildrens} educandos</Badge> :
        <Badge className='bg-dark text-red'>Aplicar multa</Badge>
      }</>
    }
  },
  {
    field: 'action',
    headerName: 'Ação',
    width: 150,
    sortable: false,
    resizable: true, cellRenderer: (props) => {
      return <div className="ed-flex">
        <NewFinePriceModal title='Atualizar ' update={true} get={Hoot() + `eduallgetsinglefine/get/${props.data.id}`}
          url={Hoot() + `eduallfineupdate/update/${props.data.id}`} toggle_btn={
            <button className="btn-circle bg-success text-light">
              <Edit />
            </button>
          } />
        <DeleteModal title='esta multa' url={Hoot() + `eduallfinedelete/delete/${props.data.id}`}
          message='Multa deletada com sucesso' toggle_btn={
            <button className="btn-circle bg-danger ml-2 text-light">
              <Delete />
            </button>
          } />
      </div>;
    }
  }
];

function FinesTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [LoadStatus, setLoadStatus] = useState(null);

  async function loadData() {
    try {
      setLoadStatus(0);
      setLoaded(false);
      const response = await axios.get(TABLEURL);
      const rows = [];

      response?.data?.map((item, index) => {
        rows.push({
          index: index + 1,
          id: item.ed_fine_id,
          service: item.ed_service_title,
          service_price:item.ed_service_price,
          service_coin:item.ed_coin_code,
          vltype: item.ed_fine_value_type,
          value: item.ed_fine_value,
          scholarshipHolders: item.ed_fine_for_scholarshipholders,
          incrementValue: item.ed_fine_increment_value,
          parentsChildrens: item.ed_fine_parentsChildrens,
          daysafterprevmonth: item.ed_fine_daysafterprevmonth,
          action: '',
        })
      });
      console.clear();
      console.table(rows);

     
       setData(rows); 
        
      
      setLoaded(true);
      setLoadStatus(2);
    } catch (error) {
      console.clear()
      console.log(error);
      setLoadStatus(1);
    }
  };

  useEffect(() => {
    loadData();
  }, []);


  if (load) {
    return (
      <div id='ed-custom-table-data'>
        <TableGrid
          TableHead={columns}
          TableBody={data}
          TableTitle='Multas aplicadas'
          TableBtn={
            <div className='ed-flex' >
              <button id='ed-custom-table-data-btn'
                onClick={() =>
                  ExportDataToTablesToPdf({
                    fileName: "Multas aplicadas",
                    headerId: null,
                    contentId: "ed-custom-table-data",
                    footerId: null,
                    rotation: "portrait",
                    buttonId: "ed-custom-table-data-btn",
                    customHeader: "Multas aplicadas",
                    excludedColumns: ["Ação"]
                  })
                }
                className='btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white'><PiFilePdfDuotone />
              </button>
              <button className='btn-icon btn btn-export-data ml-2'
                onClick={() => ExportDataForTablesExcel("Multas aplicadas", ["Ação"])}><PiMicrosoftExcelLogoDuotone />
              </button>
              <RefreshButton action={loadData} status={LoadStatus} />
            </div>
          }
        />
      </div>
    )
  } else {
    return (
      <div>
        <div className="d-none">*</div>
        <TableGrid
          TableHead={columns}
          TableBody={[]}
          TableTitle='Multas aplicadas'
          TableBtn={<RefreshButton action={loadData} status={LoadStatus} />}
        />
      </div>
    )
  }
}

export default FinesTable




