import { Search } from '@mui/icons-material'
import React, { useState } from 'react'
import { Link } from 'react-router-dom'; 
import { Form } from 'react-bootstrap'
import DateTimePicker from 'react-datetime-picker'
import PdAttendanceGrid from '../../components/Grid/PdAttendanceGrid';
import NewEmployeeAttendanceModal from '../../components/modal/Pedagogy/NewEmployeeAttendanceModal';
import { List } from 'react-ionicons';

function PdAttendance() {
    document.title = "Livro de ponto"; 
    const [value1, setValue1] = useState(null);
    const [value2, setValue2] = useState(null);
  
    const handleChange = (e, type) => {
        console.log(e);
        
        if(type === 0){
             setValue1(e);
        }else{
          setValue2(e);
        }
    };
  
    
  return (
    <div>
        <div className="ed-space">
          <div className='ed-flex'> 
          </div>
            <div className='ed-flex'>
              <Link className='btn text-white btn-icon bg-green-light text-light ml-2' to='/employeeattandance'>
                  <List color="#ffff" /> 
              </Link> 
              <div className="ml-2">
                  <NewEmployeeAttendanceModal />
              </div>
            </div> 
        </div>
        <PdAttendanceGrid date1={value1} date2={value2}  />
    </div>
  )
}

export default PdAttendance
