import React, { useEffect, useState } from 'react'
import ChatSidebar from './ChatComponents/ChatSidebar'
import ChatUsers from './ChatComponents/ChatUsers'
import ChatMessages from './ChatComponents/ChatMessages'
import ChatVideoCall from "./ChatComponents/ChatVideoCall"
import socketIO from 'socket.io-client';
import Hoot from './components/Hoot'
const socket = socketIO(Hoot(), {withCredentials: true});

function Chat() { 
  const [searchField, setSearchField] = useState({});
  document.title =  "Chat";

  const GetCurrentChatUser = (e)=>{  
    setSearchField(e)
  }

  useEffect(() => {  
     socket.on('connect', () => { 
         console.log('Connected to server with id number',  socket.id);
    });
  }, []);


  return (
    <div className='ed-chat-container'>
        <ChatSidebar socket={socket} />
        <ChatUsers  socket={socket}  CurrentUser={GetCurrentChatUser} />
        <ChatMessages  socket={socket}  CurrentChatUser={searchField} />
        <ChatVideoCall />
    </div>
  )
}

export default Chat
