import React, { useState, useEffect } from 'react';
import { Avatar, AvatarGroup } from '@mui/material';
import axios from 'axios';
import { Badge, Modal, Button, Spinner } from 'react-bootstrap';
import Hoot from '../../../General/components/Hoot'; 
import RefreshButton from '../../../General/components/RefreshButton';
import { toast } from 'react-hot-toast';
import { IoKeyOutline } from "react-icons/io5";
import { PiFilePdfDuotone, PiMicrosoftExcelLogoDuotone } from 'react-icons/pi';
import ExportDataForTablesExcel from '../../../General/components/ExportDataForTablesExcel';
import { ExportDataToTablesToPdf } from '../../../General/components/ExportDataToTablesToPdf';
import NewStudentUserAccountModal from '../modal/NewStudentUserAccountModal';
import TableGrid from '../../../General/components/TableGrid';
import DraggableModal from '../../../General/components/DraggableModal';
import { Close, Done } from '@material-ui/icons';
import { ModalAnimationClose, ModalAnimationShow } from '../../../General/components/ModalAnimations';
import RefreshList from '../../../General/components/RefreshList';

const TABLEURL = Hoot() + "eduallgetuserstudentsaccounts/get";

// ================= Modal de Reset de Senha =================
function ResetPasswordModal({ toggle_btn, userId, email, refreshList }) {
  const [show, setShow] = useState(false);
  const [showBox, setShowBox] = useState(false);
  const [resetDone, setResetDone] = useState(false);
  const [loading, setLoading] = useState(false);

  const handleClose = () => {
    setShowBox(false);
    setTimeout(() => setShow(false), 1200);
  };

  const handleShow = () => {
    setShowBox(true);
    setShow(true);
    setResetDone(false);
    setLoading(false);
  };

  const resetPassword = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      await axios.post(Hoot() + "eduallresetstudentaccountpassword/post", {
        userId,
        email
      });

      setResetDone(true);
      toast.success(`Senha do usuário ${email} resetada com sucesso!`);
      if (refreshList) refreshList();
      handleClose();
    } catch (error) {
      const msg = error?.response?.data?.msg || "Erro ao resetar a senha!";
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <div onClick={handleShow}>{toggle_btn}</div>
      <Modal
        className={showBox ? ModalAnimationShow() : ModalAnimationClose()}
        centered
        dialogAs={DraggableModal}
        show={show}
        onHide={handleClose}
      >
        <div className="prt">
          <div className={resetDone ? "deleteIcon deleted " : "deleteIcon"} style={{ marginTop: '-10px' }}>
            <div className="icon bg-green text-light text-white">
              {resetDone ? <Done /> : <IoKeyOutline style={{ fontSize: 36 }} />}
            </div>
          </div>
        </div>

        <div className="close-modal" onClick={handleClose}>
          <div className="top-icon"><Close /></div>
        </div>

        <div className="ed-flex">
          <div className="block text-center modal-delete-details  mt-4">
            {!resetDone ? (
              <>
                <h2>Deseja realmente resetar a senha de <strong><div className="underline">{email} ?</div></strong></h2>
                <p>A senha será redefinida para o padrão: <strong className='text-main'>765*eduall#</strong></p>
              </>
            ) : (
              <h2 className='text-green'>Senha resetada com sucesso!</h2>
            )}
          </div>
        </div>

        <Modal.Body className='scrollLimit'>
          <div className="modal-delete-body">
            {!resetDone ? (
              <div className="ed-center">
                <div className="ed-flex">
                  <Button className='bg-light text-dark' onClick={handleClose} disabled={loading}>
                    Cancelar
                  </Button>
                  <Button
                    className="btn bg-green text-green btn-outlined  ml-2 d-flex align-items-center justify-content-center"
                    onClick={resetPassword}
                    disabled={loading}
                  >
                    {loading ? (
                      <>
                        <Spinner animation="border" size="sm" className="mr-2" /> 
                        Processando...
                      </>
                    ) : (
                      'Continuar'
                    )}
                  </Button>
                </div>
              </div>
            ) : (
              <div className="ed-center">
                <Button className='bg-light text-dark' onClick={handleClose}>Ok</Button>
              </div>
            )}
          </div>
        </Modal.Body>
      </Modal>
    </div>
  );
}

// ================= Table Columns =================
const columns = (refreshList) => [
  { field: 'index', headerName: 'Nº', width: 90, resizable: true },

  {
    field: 'student_name',
    headerName: 'Nome do estudante',
    minWidth: 350,
    resizable: true,
    cellRenderer: (props) => (
      <div className="ed-flex">
        <Avatar
          className='df'
          alt={props.data.student_alt}
          src={props.data.student_picture}
          sx={{ width: 45, height: 45 }}
        />
        <span className="ml-2">{props.data.student_name}</span>
      </div>
    ),
  },

  {
    field: 'student_email',
    headerName: 'Email',
    minWidth: 250,
    resizable: true,
  },
  {
    field: 'student_class',
    headerName: 'Turma',
    width: 150,
    resizable: true,
  }, 

  {
    field: 'status',
    headerName: 'Status',
    width:100,
    resizable: true,
    cellRenderer: (props) =>
      props.data.accounts.length > 0 ? (
        <Badge bg="info">Activo</Badge>
      ) : (
        <Badge bg="danger">Sem Conta</Badge>
      ),
  },

  {
    field: 'actions',
    headerName: 'Ações',
    width: 210,
    resizable: true,
    cellRenderer: (props) => (
      <div className="ed-flex">
        {props.data.accounts.length > 0 && (
          <ResetPasswordModal
            userId={props.data.accounts[0].code} // <-- ed_user_account_id real
            email={props.data.accounts[0].email} // <-- email da conta real
            refreshList={refreshList}
            toggle_btn={
              <button className="btn table-btn-large cursor-pointer btn-small bg-warning ml-2">
                <span className="ml-1">Repor senha padrão</span>
              </button>
            }
          />
        )} 
      </div>
    ),
  },
];

// ================= Table Component =================
function UsersStudentsAccountsTable() {
  const [data, setData] = useState([]);
  const [load, setLoaded] = useState(false);
  const [loadStatus, setLoadStatus] = useState(null);

  const loadData = async () => {
    try {
      setLoaded(false);
      setLoadStatus(0);
      const response = await axios.get(TABLEURL);

      const rows = [];
      const list = response.data.map((Item, i) => ({
        id: i,
        code: Item.ed_student_id,
        data: Item,
      }));

      const hashtable = {};
      list.forEach((item) => {
        const key = ['code', 'data'].map((k) => item[k]).join('|');
        hashtable[key] = hashtable[key] || [];
        hashtable[key].push(item);
      });

      const duplicates = Object.values(hashtable);

      duplicates.forEach((element) => {
        if (element.length >= 1) {
          const accounts = element.map((el) => ({
            code: el.data.ed_user_account_id,
            name: el.data.ed_user_account_name,
            email: el.data.ed_user_account_email,
            picture: Hoot() + el.data.ed_user_account_picture,
          }));

          rows.push({
            student_id: element[0].data.ed_student_id,
            student_name: `(#${element[0].data.ed_student_code}) - `+ element[0].data.ed_student_name,
            student_alt:element[0].data.ed_student_name,
            student_email: element[0].data.ed_user_account_email,
            student_class: element[0].data.ed_class_title,
            student_picture: Hoot() + element[0].data.ed_student_picture,
            accounts,
          });
        }
      });

      const sorted = rows
        .sort((a, b) => a.student_name.localeCompare(b.student_name))
        .map((item, index) => ({ ...item, index: index + 1 }));

      setData(sorted);
      setLoadStatus(2);
      setLoaded(true);
    } catch (error) {
      console.log(error);
      toast.error("Erro ao carregar as contas de estudante!");
      setLoadStatus(1);
      setLoaded(true);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  return (
    <div id="ed-students-table">
      <TableGrid
        TableHead={columns(loadData)}
        TableBody={data}
        TableTitle="Lista de Contas de Estudantes"
        TableBtn={
          <div className="ed-flex">
            <button
              id="export-student-pdf"
              onClick={() =>
                ExportDataToTablesToPdf({
                  fileName: "Contas de Estudantes",
                  headerId: null,
                  contentId: "ed-students-table",
                  rotation: "portrait",
                  customHeader: "Lista de Contas de Estudantes",
                  excludedColumns: ["Ações"],
                })
              }
              className="btn-icon ed-flex ed-center btn btn-export-data ml-2 bg-white"
            >
              <PiFilePdfDuotone />
            </button>

            <button
              className="btn-icon btn btn-export-data ml-2"
              onClick={() =>
                ExportDataForTablesExcel("Lista de Contas de Estudantes", ["Ações"])
              }
            >
              <PiMicrosoftExcelLogoDuotone />
            </button>

            <RefreshButton action={loadData} status={loadStatus} />
          </div>
        }
      />
    </div>
  );
}

export default UsersStudentsAccountsTable;
