import React, { useEffect, useState } from "react";
import axios from "axios";
import Hoot from "../../../General/components/Hoot";
import { Badge } from "react-bootstrap";
import TableGrid from "../../../General/components/TableGrid";
import { Avatar } from "@mui/material";
import SwitchFromPages from "../../../General/components/SwitchFromPages";
import { PiMicrosoftExcelLogoDuotone } from "react-icons/pi";
import ExportDataForTablesExcel from "../../../General/components/ExportDataForTablesExcel";

export default function ClassPaymentsTable() {
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(true);
  const [status, setStatus] = useState(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      setStatus(0);
      const response = await axios.get(Hoot() + "eduallGetAllClassesPaymentsStatus/get/");
      setData(response.data);
      setStatus(2);
    } catch (err) {
      console.error("Erro ao carregar dados:", err);
      setStatus(1);
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="ed-flex ed-center">
        <h4 className="title">Carregando informações...</h4>
      </div>
    );
  }

  // Função para calcular totais gerais
  const calculatePaymentSummary = () => {
    let paid = 0, notPaid = 0, others = 0;
    const today = new Date();

    data.forEach(cls => {
      cls.students.forEach(student => {
        student.months?.forEach(month => {
          const [monthName, , yearLabel] = month.month.split(" ");
          const monthIndex = new Date(`${monthName} 1, ${yearLabel}`).getMonth();
          const monthDate = new Date(yearLabel, monthIndex);

          if (monthDate > today) {
            others++;
          } else if (month.status === "paid") {
            paid++;
          } else if (month.status === "notpaid") {
            notPaid++;
          } else {
            others++;
          }
        });
      });
    });

    return { paid, notPaid, others };
  };

  const { paid, notPaid, others } = calculatePaymentSummary();

  return (
    <div>
      {/* Totais gerais */}
      <div className="status-total ed-flex mb-3">
        <h5 className="mr-3">
          <div className="dot bg-green mr-1"></div>Propinas pagas - {paid}
        </h5>
        <h5 className="mr-3">
          <div className="dot bg-warning mr-1"></div>Propinas não pagas - {notPaid}
        </h5>
        <h5 className="mr-3">
          <div className="dot bg-grey mr-1"></div>Outros pagamentos - {others}
        </h5>
      </div>

      {/* Tabelas por turma */}
      {data.map((cls, index) => {
        const startYear = cls.academic_year?.ed_academic_year_startDate
          ? cls.academic_year.ed_academic_year_startDate.split("-")[0]
          : "N/A";
        const endYear = cls.academic_year?.ed_academic_year_endDate
          ? cls.academic_year.ed_academic_year_endDate.split("-")[0]
          : "N/A";

        // Colunas da tabela
        const columns = [
          {
            field: "student",
            headerName: "Nome do estudante",
            resizable: true,
            width: 320,
            cellRenderer: (props) => (
              <SwitchFromPages
                link={`studentinfo/${props.data.id}`}
                menu="3"
                menu_item="17"
                toggle_btn={
                  <div className="ed-flex">
                    <Avatar
                      className="df"
                      alt={(props.data.student?.split("-").pop()?.trim()?.charAt(0) || "").toUpperCase()}
                      src={props.data.picture ? Hoot() + props.data.picture : ""}
                    />
                    <span className="ml-2">{props.data.student}</span>
                  </div>
                }
              />
            ),
          },
        ];

        // Colunas dos meses
        if (cls.students.length > 0 && cls.students[0].months) {
          cls.students[0].months.forEach((month, mIndex) => {
            columns.push({
              field: `month_${mIndex}`,
              headerName: month.month,
              resizable: true,
              width: 200,
              cellRenderer: (props) => {
                const value = props.value?.toLowerCase();
                if (value === "paid") return <Badge bg="success" className="col-lg-12">Propina paga</Badge>;
                if (value === "notpaid") return <Badge bg="warning" className="col-lg-12">Propina não paga</Badge>;
                return <Badge bg="secondary" className="col-lg-12">Outro</Badge>;
              },
            });
          });
        }

        // Linhas da tabela
        const rows = cls.students.map((student) => {
          const row = {
            id: student.id,
            student: `(#${student.code}) - ${student.name}`,
            picture: student.picture
          };
          student.months?.forEach((item, i) => {
            row[`month_${i}`] = item.status;
          });
          return row;
        });

        return (
          <div key={index} id={`ClassPaymentsTable-${index + 1}`} className="mb-5">
            <TableGrid
              NoCustomItems
              TableHead={columns}
              TableBody={rows}
              TableHeight={rows.length < 5 ? 200 : 370}
              TableTitle={`Turma: ${cls.class_title} — Ano académico: ${startYear} / ${endYear}`}
              TableBtn={
                <div className="ed-flex">
                  <button
                    className="btn-icon btn btn-export-data"
                    onClick={() => ExportDataForTablesExcel(
                      `Pendências de Propinas da Turma: ${cls.class_title} — Ano académico: ${startYear} / ${endYear}`,
                      ["Ação"],
                      `ClassPaymentsTable-${index + 1}`
                    )}
                  >
                    <PiMicrosoftExcelLogoDuotone />
                  </button>
                </div>
              }
            />
          </div>
        );
      })}
    </div>
  );
}
