import styled from 'styled-components';
import PeopleOutlineIcon from '@mui/icons-material/PeopleOutline';
import PlayLessonOutlinedIcon from '@mui/icons-material/PlayLessonOutlined';
import AssignmentOutlinedIcon from '@mui/icons-material/AssignmentOutlined';
import BadgeOutlinedIcon from '@mui/icons-material/BadgeOutlined';
import Chart from 'react-apexcharts';
import TodayTask from '../components/Table/TodayTask';
import { ClassCountData, StudentsCountData, CourseCountData, EmployeesCountData, RequestsCountData } from '../../General/components/InstituteData';
import AnimationPage from '../../General/AnimationPage';
import StudentsNByAcademicLevelChart from '../components/elements/Charts/StudentsNByAcademicLevelChart';
import StudentNByClassChart from '../components/elements/Charts/StudentNByClassChart';
import Calendar from 'react-calendar';
import { useState } from 'react';
import DashboardEventsTable from '../components/Table/DashboardEventsTable';
import { useEffect } from 'react';
import axios from 'axios';
import Hoot from '../../General/components/Hoot';
import ReplaceWord from '../../General/components/ReplaceWord';
import PaymentsOfTheDayTable from '../components/Table/PaymentsOfTheDayTable';
import { RxExternalLink } from "react-icons/rx";
import SwitchFromPages from '../../General/components/SwitchFromPages';
import ImportarEstudantesButton from '../components/modal/ImportarEstudantesButton';


const Dashboard = () => {
    const [value, onChange] = useState(new Date());
    const [totalSchoolStudents, SettotalSchoolStudents] = useState(0);
    const [ClassesData, SetClassesData] = useState([]);
    const [SchoolGenderOptions, SetSchoolGenderOptions] = useState({});

     
 


    const FORMURL = [
        Hoot() + "eduallupdateinstitute/update/",
        Hoot() + "eduallgetcurentuserinstitute/get/"
    ];

const GET_DATA = async () => {
  try {
    const response = await axios.get(FORMURL[1]);
    if (response.data?.[0]) {
      document.title = 'Dashboard - ' + response.data[0].ed_institute_name;
    }

    const [class_response, students_response] = await Promise.all([
      axios.get(Hoot() + "eduallclassapi/get"),
      axios.get(Hoot() + "eduallstudentsapi/get")
    ]);

    const classes = class_response.data;
    const students = students_response.data;

    // 🔹 Criar Map de estudantes por classe para acesso O(1)
    const studentsByClass = new Map();
    students.forEach(student => {
      const classId = student.ed_student_class || 0;
      if (!studentsByClass.has(classId)) studentsByClass.set(classId, []);
      studentsByClass.get(classId).push(student);
    });

    // 🔹 Processar classes
    const outputData = [];
    let totalSchoolMales = 0;
    let totalSchoolFemales = 0;

    classes.forEach(schoolClass => {
      const classId = schoolClass.ed_class_id;
      const classTitle = schoolClass.ed_class_title;

      const classStudents = studentsByClass.get(classId) || [];

      let maleCount = 0;
      let femaleCount = 0;

      classStudents.forEach(student => {
        if (student.ed_student_gender === 'male') maleCount++;
        else if (student.ed_student_gender === 'female') femaleCount++;
      });

      const totalStudents = classStudents.length;
      const percentageMales = totalStudents ? ((maleCount / totalStudents) * 100).toFixed(2) + '%' : '0%';
      const percentageFemales = totalStudents ? ((femaleCount / totalStudents) * 100).toFixed(2) + '%' : '0%';

      totalSchoolMales += maleCount;
      totalSchoolFemales += femaleCount;

      outputData.push({
        class_title: classTitle,
        class_percentagebygender: {
          Totalmales: maleCount,
          Totalfemales: femaleCount,
          Percentagemales: percentageMales,
          Percentagefemale: percentageFemales
        },
        class_students: classStudents
      });
    });

    SetClassesData(outputData);
    SettotalSchoolStudents(students.length);

    // 🔹 Gerar gráfico de gênero
    const totalStudents = totalSchoolMales + totalSchoolFemales;
    const percentageMales = totalStudents ? (totalSchoolMales / totalStudents) * 100 : 0;
    const percentageFemales = totalStudents ? (totalSchoolFemales / totalStudents) * 100 : 0;

    const chartLabels = [
      `Mulheres - ${totalSchoolFemales} (${percentageFemales.toFixed(1)}%)`,
      `Homens - ${totalSchoolMales} (${percentageMales.toFixed(1)}%)`
    ];

    const chartOptions = {
      series: [percentageFemales, percentageMales],
      options: {
        chart: { type: 'donut' },
        colors: ['var(--ed-green)', 'var(--ed-purple)'],
        labels: chartLabels,
        responsive: [{
          breakpoint: 480,
          options: {
            chart: { width: 400 },
            legend: {
              show: true,
              position: 'bottom',
              horizontalAlign: 'center',
              fontSize: '15px',
              fontWeight: 400,
              itemMargin: { horizontal: 15, vertical: 0 }
            }
          }
        }]
      }
    };

    SetSchoolGenderOptions(chartOptions);

  } catch (error) {
    console.error(error);
    document.title = 'Dashboard - ******';
  }
};


    useEffect(() => {
        GET_DATA();
    }, []);


    return (
        <AnimationPage>
            <div>
                <div className="mt-2">  
                    <Flex className='flex-to-col'>
                        <BoxFlex className='flex-to-col'>
                            <Box className='mrb-2 boxItem bg-main text-light'>
                               <div className="ed-space">
                               <div className="ed-flex">
                                    <h3 className='text-white' ><StudentsCountData /> </h3>
                                </div> 
                                <SwitchFromPages link={`Students/`}  menu='3'  menu_item='13'  
                                toggle_btn={ <div className="link text-light"> <RxExternalLink/> </div>} />
                               </div>
                                <Block >
                                    <span className='text-white' >Estudantes registrados</span>
                                </Block>
                            </Box>
                            <Box className='mrb-2 boxItem'> 
                                <div className="ed-space">
                                <div className="ed-flex">
                                    <h3><ClassCountData /></h3>
                                </div>
                                <SwitchFromPages link={`New_class/`}  menu='2'  menu_item='4'  
                                toggle_btn={ <div className="link text-main"> <RxExternalLink/> </div>} />
                                </div>
                                <Block>
                                    <span>Total turmas </span>
                                </Block>
                             </Box>
                            <Box className='boxItem'>
                                <div className="ed-space">
                                <div className='ed-flex'>
                                    <h3><RequestsCountData /> </h3>
                                </div>
                                <SwitchFromPages link={`answerrequests/`}  menu='3'  menu_item='18'  
                                toggle_btn={ <div className="link text-main"> <RxExternalLink/> </div>} />
                                </div> 
                                <Block>
                                    <span>Número Total de solicitações</span>
                                </Block>
                            </Box>
                            <Box className='boxItem'>
                            <div className="ed-space">
                            <div className="ed-flex">
                                    <h3><EmployeesCountData /></h3>
                                </div>
                                <SwitchFromPages link={`employees/`}  menu='2'  menu_item='5'  
                                toggle_btn={ <div className="link text-main"> <RxExternalLink/> </div>} />
                                </div> 
                                <Block>
                                    <span>Total funcionários</span>
                                </Block>
                            </Box>
                        </BoxFlex>
                    </Flex>
                </div>
                <BoxItem className='boxItem'>
                    <Flex>
                        <div className='chart-container'>
                            <div className="title mb-4"><h1>Estudantes por género</h1></div> 
                            {SchoolGenderOptions.options !== undefined && SchoolGenderOptions.options !== null ?
                            <Chart options={SchoolGenderOptions.options} series={SchoolGenderOptions.series} type="donut" />  : <></>}  
                        </div>
                        <div className="ml-2 col">
                            <div className="ed-space col-lg-12">
                               <div className="title"><h1>Controle de estudantes por turma</h1></div>
                               <div className="d-flex">
                                   <div className="ed-flex mr-2"><div className="dot bg-warning"></div> Homens</div>
                                   <div className="ed-flex ml-2"><div className="dot bg-green"></div> Mulheres</div>
                               </div> 
                           </div> 
                           <ul className='scroll-bx' >
                                {ClassesData.map(classData => {
                                    const { class_title, class_percentagebygender, class_students } = classData;
                                    const totalStudents = class_students.length;
                                    const totalMales = class_percentagebygender.Totalmales;
                                    const totalFemales = class_percentagebygender.Totalfemales; 
                             
                                    const percentageMales = class_percentagebygender.Percentagemales;
                                    const percentageFemales = class_percentagebygender.Percentagefemale; 

                                    const percentageOfClassInSchool = totalSchoolStudents > 0 
                                    ? ((totalStudents / totalSchoolStudents) * 100).toFixed(2) + '%'  : '0%';

                                    return (
                                        <li className="ed-flex mb-2 ed-space" key={class_title}> 
                                            <strong>{class_title}</strong>
                                            <div className="barstatus ml-2 mr-2 col ed-flex bg-silver"> 
                                                <div 
                                                    className="col-lg-5 bg-warning" 
                                                    style={{ width: percentageMales }}
                                                ></div>
                                                <div 
                                                    className="col-lg-3 bg-green" 
                                                    style={{ width: percentageFemales }}
                                                ></div>
                                            </div>
                                            <strong>{`${percentageOfClassInSchool}   (${totalStudents})`}</strong>
                                        </li>
                                    );
                                })}
                            </ul> 
                        </div>
                    </Flex>
                </BoxItem>
                
                 <div className="col mb-4">
                    <PaymentsOfTheDayTable /> 
                 </div>
           
                <Flex>
                    <BoxItem className='boxItem'>
                        <div className="title"><h1>Número de estudantes por {ReplaceWord("Classe")}</h1></div>
                        <StudentsNByAcademicLevelChart />
                    </BoxItem>
                </Flex>
            </div>
            <br />
        </AnimationPage>
    );
}


const Flex = styled.div`
   display:flex;
   width:100%; 

     .barstatus{
        height:15px;
        border-radius:30px;
        background:var(--ed-background);
       overflow:hidden;

         div{
             height:100%;
         }
     }

     ul{
        padding:0px;
        margin:0px;
        margin-top:20px;

         li{
           strong{
              font-size:14px !important;
           }
         }
     }

   
    .chart-container{
        width:200px;      
        min-width:400px; 
        padding-right:50px;
        border-right:1px solid var(--ed-silver-light);
    }
   
   .space{
     display:flex;
     justify-content:space-between;

     .custom-table {
          margin:0px;
     }
   }

     .calendar-box{
        width:38%;
        .react-calendar {
            min-height:360px;
        }
     }

     .table-box{ 
         min-width:60%;
         width:60%;
     }
`;


const BoxFlex = styled.div`
    display:flex; 
    width:100%;
    flex-wrap:wrap; 
    justify-content:space-between;


     .link{
        font-size:20px;
        margin-top:-20px;
     }

`;

const Box = styled.div`
   width:23%;
   min-width:24%;
   border-radius:6px; 
   height:100px;
   margin-bottom:21px !important;
   background:var(--ed-white);  
   box-shadow:var(--ed-shadow-df);
   display:flex;
   flex-direction:column;
   justify-content:center;
   padding:20px;
   position: relative;

   .ed-flex{
      align-items:center;
   }

  .icon{
   width:60px;
   height:60px;
   display:flex;
   align-items:center;
   justify-content:center;
   border-radius:100%;
   background:var(--ed-purple-light);

    svg{
        width:30px;
        height:30px;
        fill:var(--ed-white);
    }
  }

   h3{ 
       font-size:35px;
       font-weight:bolder;
       margin:0px; 
       color:var(--ed-blue-dark);
   }

   span{
       font-size:14px; 
   }
`;


const Block = styled.div`
   display:block;
   margin-top:10px;
`;

const ChartBox = styled.div`
    width:100%;
    padding-left:20px; 


    .title h1{
      font-size: 18px;
      font-weight: 600;
      margin: 0px;
      margin-bottom:20px;
   }
`;


const BoxItem = styled.div`
    width:100%; 
    border-radius:6px;
    margin-bottom:20px;    
    margin-top:10px;
    padding:20px;
    min-height:200px;
    background:var(--ed-white);  
    box-shadow:var(--ed-shadow-df);

    .dot{
         width:15px;
         height:15px;
         border-radius:100%;
         margin-right:10px;
         border:4px solid var(--ed-shadow-df);
         box-shadow:var(--ed-shadow-df);
    }

    .title h1{
        font-size: 18px;
        font-weight: 600;
        margin: 0px;
    }
`;

export default Dashboard;