import React, { useEffect , useState} from 'react'
import ElearningNavbar from './Components/ElearningNavbar'
import { styled } from 'styled-components'
import ContentPlaylist from './Components/ContentPlaylist';
import PlayerContainer from './Components/PlayerContainer';
import { Done, Share } from '@material-ui/icons';
import { useParams } from 'react-router-dom';
import { useLocation } from 'react-router-dom';
import { useMemo } from 'react'; 
import LessonDescriptionTab from './Components/LessonTabs/LessonDescriptionTab';
import LessonFeedbackTab from './Components/LessonTabs/LessonFeedbackTab';
import LessonFilesTab from './Components/LessonTabs/LessonFilesTab';
import LessonNotesTab from './Components/LessonTabs/LessonNotesTab';
import LessonCommentsTab from './Components/LessonTabs/LessonCommentsTab';
import Hoot from '../../General/components/Hoot';

function useQuery() {
  const { search } = useLocation();
 

  return React.useMemo(() => new URLSearchParams(search), [search]);
}


function WatchCourse({socket, userdata}) {
  document.title = "Assistir - "
  const [FixedMenu, setFixedMenu] =  useState(false);
  const [ActiveTab, setActiveTab] =  useState(1);
  const [CurrentVideo, setCurrentVideo] = useState({});
  const [CurrentItem, setCurrentItem] = useState(null);
  const [Filters, setFilters] =  useState({});
  const [VideoData, setVideoData] = useState({});
  const [ContentDescription, setContentDescription] = useState("");
  const [ContentId, setContentId]  = useState(null);
  const [TotalReviews, setTotalReviews]  = useState(0);

  let query = useQuery(); 
 

     const GetCurrentItem = (e)=>{
      setContentDescription("");
      setContentId(null);
      setVideoData({});
       
      if(e.ed_lesson_video_id !== null){
        setVideoData({
          poster:Hoot()+e.ed_ls_vd_poster_source, 
          video:Hoot()+e.ed_lesson_video_source,
          title:e.ed_lesson_content_title
        });}else{setVideoData({})}
        setContentDescription(e.ed_lesson_content_description);
        setContentId(e.ed_lesson_content_id);
     }


     const GetTotalReviews =  (e)=>{
         setTotalReviews(e*1);
     }


    useEffect(() => { 
      setFilters({code:query.get("code"), type:query.get("type"), current:query.get("current")}); 
    }, []);


  return (
    <div>
        <ElearningNavbar filters={{code:query.get("code"), type:query.get("type"), current:query.get("current")}} />
        <Container>
            <ContentPlaylist socket={socket}  CurrentItem={GetCurrentItem} filters={{code:query.get("code"), type:query.get("type"), current:query.get("current")}} />
               <div className="course-content-area"> 
                    <PlayerContainer socket={socket}  data={VideoData} />
                    <div className="course-content-area-tabs">
                      <div className={`content-tabs ${FixedMenu === true ? " fixed " : ""}  `}>
                        <div className="ed-space">
                          <div className="tabs">
                             <ul className="ed-flex">
                              <li className={ActiveTab === 1 ? 'active' : ""}  onClick={()=>setActiveTab(1)} >Descrição</li>
                              <li className={ActiveTab === 2 ? 'active' : ""}  onClick={()=>setActiveTab(2)} >Avaliações ({TotalReviews})</li>
                              <li className={ActiveTab === 3 ? 'active' : ""}  onClick={()=>setActiveTab(3)} >Ficheiros (0)</li>
                              <li className={ActiveTab === 4 ? 'active' : ""}  onClick={()=>setActiveTab(4)} >Notas (0)</li>
                              <li className={ActiveTab === 5 ? 'active' : ""}  onClick={()=>setActiveTab(5)} >Comentarios (0)</li>
                             </ul>
                          </div>
                          <div className="ed-flex menu-bar"> 
                                <button className='btn'><div className="icon"><Share/></div> partilhar</button>
                                <button className='btn ended'><div className="icon"><Done /></div> Marcar como finalizado</button>
                          </div>
                        </div>
                      </div>
                      <aside>
                         <section className={ActiveTab === 1 ? 'active' : ""}>
                             <LessonDescriptionTab userdata={userdata} data={ContentDescription} filters={{code:query.get("code"), type:query.get("type"), current:query.get("current")}} />
                         </section>
                         <section className={ActiveTab === 2 ? 'active' : ""}>
                            <LessonFeedbackTab total={GetTotalReviews} userdata={userdata}  socket={socket} id={ContentId} filters={{code:query.get("code"), type:query.get("type"), current:query.get("current")}} />
                         </section>
                         <section className={ActiveTab === 3 ? 'active' : ""}>
                           <LessonFilesTab userdata={userdata} data={[]} filters={{code:query.get("code"), type:query.get("type"), current:query.get("current")}}/>
                         </section>
                         <section className={ActiveTab === 4 ? 'active' : ""}>
                            <LessonNotesTab userdata={userdata}  socket={socket} id={ContentId}  filters={{code:query.get("code"), type:query.get("type"), current:query.get("current")}}/>
                         </section>
                         <section className={ActiveTab === 5 ? 'active' : ""}>
                            <LessonCommentsTab userdata={userdata} socket={socket} id={ContentId} filters={{code:query.get("code"), type:query.get("type"), current:query.get("current")}}/>
                         </section>
                      </aside> 
                    </div>
               </div>
        </Container>
    </div>
  )
}

const Container = styled.div`
    width:100%;
    display:flex;
    height:100vh; 
    background:var(--ed-white); 

    .course-content-area{
         width:100%; 
         max-height:100vh;
         overflow-y:auto;
         position:relative;
         margin-top:70px;
    }


    .content-tabs.fixed{
        position:fixed !important;
        top:200px;
        left:411px;
        width:calc(100% - 430px);
        z-index:100;
        background:red !important;
    }

    .content-tabs{
        padding:0px;
        background:var(--ed-background-color); 

        .menu-bar{
            button{
                margin:0px 10px;
                background:transparent;
                border:1px solid var(--dark) !important; 
                height:40px; 
                font-size:15px !important;
                display:flex;
                align-items:center;
                justify-content:center; 
                padding:0px 10px;
                color:var(--dark) !important;

                  .icon{
                     margin-right:8px;
                     border-radius:100%;
                     padding:2px;

                       svg{
                          margin:0px !important;
                       }
                  }
            }

             button.ended{
                 color:var(--ed-blue-dark) !important; 
                 background:var(--ed-green); 

                 .icon{
                    background:var(--ed-green-light); 
                    color:var(--ed-white) !important; 
                 }

             }
        } 

          ul{
            padding:0px;
              margin:0px;


                li{
                    margin:0px; 
                    padding:20px; 
                    list-style:none;
                    cursor:pointer;
                    border-right:1px solid var(--ed-silver);
                    
                }

                li.active{
                    background:var(--ed-white); 
                    color:var(--ed-purple);
                }


                li:hover{
                    background:var(--ed-background-color);
                    color:var(--ed-dark);
                }
          }
    }




    aside{
        section{
          padding:40px 20px;
          display:none;
          width:100%;
          min-height:500px;
        }

        section.active{
          display:block !important;


            .title{
                font-weight:bold;
                font-size:18px;
            }
        }
    }


`;

export default WatchCourse
